-- ============================================================
-- UTILITY FUNCTION
-- ============================================================
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public

-- ============================================================
-- AUTO-CREATE PROFILE ON SIGNUP
-- ============================================================
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  _first text;
  _last text;
  _role public.user_role;
BEGIN
  _first := COALESCE(NEW.raw_user_meta_data->>'first_name', '');
  _last := COALESCE(NEW.raw_user_meta_data->>'last_name', '');
  _role := COALESCE((NEW.raw_user_meta_data->>'role')::public.user_role, 'STAFF');

  INSERT INTO public.profiles (id, first_name, last_name, full_name, role)
  VALUES (NEW.id, _first, _last, TRIM(_first || ' ' || _last), _role);

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, _role);

  RETURN NEW;
END;
$$

-- Auto-create reminders on appointment insert
CREATE OR REPLACE FUNCTION public.create_appointment_reminders()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.appointment_reminders (appointment_id, remind_at, channel)
  VALUES (NEW.id, NEW.scheduled_at - INTERVAL '48 hours', 'SMS');
  INSERT INTO public.appointment_reminders (appointment_id, remind_at, channel)
  VALUES (NEW.id, NEW.scheduled_at - INTERVAL '24 hours', 'SMS');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public

-- ============================================================
-- RESPONSE METRIC TRACKING TRIGGER
-- ============================================================
CREATE OR REPLACE FUNCTION public.track_response_metric()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE _client_msg RECORD;
BEGIN
  IF NEW.sender_type = 'STAFF' AND NEW.is_internal = false THEN
    SELECT id, created_at, type INTO _client_msg
    FROM public.messages
    WHERE conversation_id = NEW.conversation_id AND sender_type = 'CLIENT' AND created_at < NEW.created_at
    ORDER BY created_at DESC LIMIT 1;

    IF _client_msg.id IS NOT NULL THEN
      INSERT INTO public.response_metrics (conversation_id, message_id, staff_id, client_message_at, staff_reply_at, channel)
      VALUES (NEW.conversation_id, NEW.id, NEW.sender_id, _client_msg.created_at, NEW.created_at, NEW.type);
    END IF;
  END IF;
  RETURN NEW;
END;
$$

-- ============================================================
-- RETENTION POLICY FUNCTION
-- ============================================================
CREATE OR REPLACE FUNCTION public.apply_retention_policies()
RETURNS void AS $$
DECLARE v_archive_days INT; v_purge_days INT; v_enabled TEXT;
BEGIN
  SELECT value INTO v_enabled FROM public.app_settings WHERE key = 'retention_enabled';
  IF v_enabled != 'true' THEN RETURN; END IF;
  SELECT value::INT INTO v_archive_days FROM public.app_settings WHERE key = 'retention_archive_days';
  SELECT value::INT INTO v_purge_days FROM public.app_settings WHERE key = 'retention_purge_days';
  UPDATE public.conversations SET status = 'ARCHIVED', archived_at = now()
  WHERE status = 'ACTIVE' AND last_message_at < now() - (v_archive_days || ' days')::INTERVAL;
  DELETE FROM public.conversations WHERE status = 'ARCHIVED' AND archived_at < now() - (v_purge_days || ' days')::INTERVAL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public

-- ============================================================
-- WELLNESS REMINDER AUTO-CREATE TRIGGER
-- ============================================================
CREATE OR REPLACE FUNCTION public.create_vaccine_wellness_reminder()
RETURNS TRIGGER AS $$
DECLARE v_client_id UUID; v_days_before INT;
BEGIN
  IF NEW.next_due_at IS NULL THEN RETURN NEW; END IF;
  SELECT client_id INTO v_client_id FROM public.pets WHERE id = NEW.pet_id;
  SELECT value::INT INTO v_days_before FROM public.app_settings WHERE key = 'wellness_reminder_days_before';
  IF v_days_before IS NULL THEN v_days_before := 30; END IF;
  INSERT INTO public.wellness_reminders (pet_id, client_id, vaccination_id, reminder_type, label, next_due_at)
  VALUES (NEW.pet_id, v_client_id, NEW.id, 'VACCINE_DUE', NEW.vaccine_name || ' due', NEW.next_due_at - (v_days_before || ' days')::INTERVAL);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public

-- Transactional cascade delete function
CREATE OR REPLACE FUNCTION public.delete_conversation_cascade(conv_id uuid)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  DELETE FROM public.message_attachments WHERE message_id IN (SELECT id FROM public.messages WHERE conversation_id = conv_id);
  DELETE FROM public.client_files WHERE conversation_id = conv_id;
  DELETE FROM public.messages WHERE conversation_id = conv_id;
  DELETE FROM public.conversations WHERE id = conv_id;
END;
$$

-- Step 2: Unique constraint on sms_consent (idempotent - may already exist from prior migration attempt)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'sms_consent_client_phone_unique') THEN
    ALTER TABLE public.sms_consent ADD CONSTRAINT sms_consent_client_phone_unique UNIQUE (client_id, phone_number);
  END IF;
END $$

-- Fix track_response_metric to compute response_time_seconds
CREATE OR REPLACE FUNCTION public.track_response_metric()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $function$
DECLARE _client_msg RECORD;
BEGIN
  IF NEW.sender_type = 'STAFF' AND NEW.is_internal = false THEN
    SELECT id, created_at, type INTO _client_msg
    FROM public.messages
    WHERE conversation_id = NEW.conversation_id AND sender_type = 'CLIENT' AND created_at < NEW.created_at
    ORDER BY created_at DESC LIMIT 1;

    IF _client_msg.id IS NOT NULL THEN
      INSERT INTO public.response_metrics (conversation_id, message_id, staff_id, client_message_at, staff_reply_at, response_time_seconds, channel)
      VALUES (
        NEW.conversation_id, NEW.id, NEW.sender_id, _client_msg.created_at, NEW.created_at,
        EXTRACT(EPOCH FROM (NEW.created_at - _client_msg.created_at))::INT,
        NEW.type
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

-- 2. Trigger: prevent non-admins from changing is_active or role on profiles
CREATE OR REPLACE FUNCTION public.protect_profile_privileges()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW; -- definer/system contexts
  END IF;
  IF public.has_role(auth.uid(), 'ADMIN') THEN
    RETURN NEW;
  END IF;
  IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    RAISE EXCEPTION 'Only admins can change profile active status';
  END IF;
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    RAISE EXCEPTION 'Only admins can change profile role';
  END IF;
  RETURN NEW;
END;
$$

-- No INSERT/UPDATE policy: only service_role (edge functions) can write.

-- ============================================================
-- 2. Helper: drop & recreate standard staff-gated policies
-- ============================================================
DO $$
DECLARE
  t TEXT;
  op_tables TEXT[] := ARRAY[
    'campaigns','campaign_recipients','tickets','appointments','appointment_reminders',
    'consent_form_templates','call_logs','callback_queue','voicemail_messages',
    'client_files','wellness_reminders','waitlist_entries','pet_vaccinations','refill_requests',
    'surveys','survey_responses','urgent_alerts','on_call_schedules','payment_links',
    'message_templates','sms_consent','lab_results',
    'follow_up_templates','follow_up_instances','follow_up_messages','message_attachments'
  ];
  pol RECORD;
BEGIN
  FOREACH t IN ARRAY op_tables LOOP
    -- Drop every existing policy on this table
    FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename=t LOOP
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, t);
    END LOOP;
    -- Recreate standard active-staff policies
    EXECUTE format('CREATE POLICY "Active staff read %I" ON public.%I FOR SELECT TO authenticated USING (public.is_active_staff(auth.uid()))', t, t);
    EXECUTE format('CREATE POLICY "Active staff insert %I" ON public.%I FOR INSERT TO authenticated WITH CHECK (public.is_active_staff(auth.uid()))', t, t);
    EXECUTE format('CREATE POLICY "Active staff update %I" ON public.%I FOR UPDATE TO authenticated USING (public.is_active_staff(auth.uid())) WITH CHECK (public.is_active_staff(auth.uid()))', t, t);
    EXECUTE format('CREATE POLICY "Admins delete %I" ON public.%I FOR DELETE TO authenticated USING (public.has_role(auth.uid(), ''ADMIN''))', t, t);
  END LOOP;
END $$

-- ============================================================
-- 3. consent_submissions — keep anon token read, harden the rest
-- ============================================================
DO $$
DECLARE pol RECORD;
BEGIN
  FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='consent_submissions' LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.consent_submissions', pol.policyname);
  END LOOP;
END $$

-- ============================================================
-- 4. app_settings — read by any active staff, write admin only
-- ============================================================
DO $$
DECLARE pol RECORD;
BEGIN
  FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='app_settings' LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.app_settings', pol.policyname);
  END LOOP;
END $$

-- ============================================================
-- 5. audit_logs — admin read only; only system (triggers) insert
-- ============================================================
DO $$
DECLARE pol RECORD;
BEGIN
  FOR pol IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename='audit_logs' LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.audit_logs', pol.policyname);
  END LOOP;
END $$

CREATE OR REPLACE FUNCTION public.admin_update_staff_role(_target_user uuid, _new_role public.user_role)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.has_role(auth.uid(), 'ADMIN') THEN
    RAISE EXCEPTION 'Only admins can change staff roles';
  END IF;
  IF _target_user IS NULL OR _new_role IS NULL THEN
    RAISE EXCEPTION 'Missing target user or role';
  END IF;

  -- Atomic: both updates run inside the same function call / transaction
  UPDATE public.profiles SET role = _new_role, updated_at = now() WHERE id = _target_user;
  DELETE FROM public.user_roles WHERE user_id = _target_user;
  INSERT INTO public.user_roles (user_id, role) VALUES (_target_user, _new_role);
END;
$$

CREATE OR REPLACE FUNCTION public.admin_set_staff_active(_target_user uuid, _is_active boolean)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  IF NOT public.has_role(auth.uid(), 'ADMIN') THEN
    RAISE EXCEPTION 'Only admins can change staff active status';
  END IF;
  UPDATE public.profiles SET is_active = _is_active, updated_at = now() WHERE id = _target_user;
END;
$$

-- 3. handle_new_user — never trust raw_user_meta_data.role
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _first text;
  _last text;
BEGIN
  _first := COALESCE(NEW.raw_user_meta_data->>'first_name', '');
  _last := COALESCE(NEW.raw_user_meta_data->>'last_name', '');

  INSERT INTO public.profiles (id, first_name, last_name, full_name, role)
  VALUES (NEW.id, _first, _last, TRIM(_first || ' ' || _last), 'STAFF');

  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'STAFF');

  RETURN NEW;
END;
$function$

-- 4. delete_conversation_cascade — admin only
CREATE OR REPLACE FUNCTION public.delete_conversation_cascade(conv_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'ADMIN') THEN
    RAISE EXCEPTION 'Only admins may delete conversations';
