declare result public.clients; actor uuid;
begin
 actor := public.clinical_require_staff();
 if p_actor_id is distinct from actor then raise exception 'Actor does not match signed-in staff' using errcode='42501'; end if;
 if p_first_name is null or length(trim(p_first_name)) not between 1 and 150 or p_last_name is null or length(trim(p_last_name)) not between 1 and 150 or length(p_primary_phone)>50 or length(p_primary_email)>254 or length(p_mailing_address)>1000 or length(p_housecall_address)>1000 then raise exception 'Client fields are missing or too long' using errcode='23514'; end if;
 if nullif(trim(p_primary_email),'') is not null and p_primary_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'Client email is invalid' using errcode='23514'; end if;
 if p_client_id is null then
  insert into public.clients(first_name,last_name,full_name,primary_phone,primary_email,preferred_channel,mailing_address,housecall_address) values(trim(p_first_name),trim(p_last_name),trim(p_first_name)||' '||trim(p_last_name),nullif(trim(p_primary_phone),''),nullif(trim(p_primary_email),''),p_preferred_channel,nullif(trim(p_mailing_address),''),nullif(trim(p_housecall_address),'')) returning * into result;
 else
  update public.clients set first_name=trim(p_first_name),last_name=trim(p_last_name),full_name=trim(p_first_name)||' '||trim(p_last_name),primary_phone=nullif(trim(p_primary_phone),''),primary_email=nullif(trim(p_primary_email),''),preferred_channel=p_preferred_channel,mailing_address=nullif(trim(p_mailing_address),''),housecall_address=nullif(trim(p_housecall_address),'') where id=p_client_id and version=p_expected_version returning * into result;
  if not found then raise exception 'Record changed or no longer exists; reload before saving' using errcode='40001'; end if;
 end if;
 return result;
end $$

create function public.search_clients(p_search text,p_limit integer default 250) returns setof public.clients language plpgsql security definer set search_path=public as $$
declare needle text := lower(trim(coalesce(p_search,'')));
begin
 perform public.clinical_require_staff();
 if length(needle)>250 then raise exception 'Search is too long' using errcode='23514'; end if;
 return query select c.* from public.clients c where needle='' or strpos(lower(c.full_name),needle)>0 or strpos(lower(coalesce(c.primary_email,'')),needle)>0 or strpos(coalesce(c.primary_phone,''),needle)>0 or (needle ~ '^[+0-9().[:space:]-]+$' and regexp_replace(needle,'[^0-9]','','g') <> '' and strpos(regexp_replace(coalesce(c.primary_phone,''),'[^0-9]','','g'),regexp_replace(needle,'[^0-9]','','g'))>0) or exists(select 1 from public.pets p where p.client_id=c.id and strpos(lower(p.name),needle)>0) order by c.full_name,c.id limit greatest(1,least(coalesce(p_limit,250),250));
end $$

create function public.guard_patient_document() returns trigger language plpgsql security definer set search_path=public as $$
declare actor uuid := public.clinical_require_staff();
begin
 if TG_OP='DELETE' then raise exception 'Document history cannot be deleted' using errcode='23514'; end if;
 if TG_OP='INSERT' then
  NEW.created_by:=actor; NEW.created_at:=now(); NEW.status:='uploading'; NEW.version:=1;
  NEW.finalized_at:=null; NEW.voided_by:=null; NEW.voided_at:=null; NEW.void_reason:=null;
  NEW.file_path:=actor::text||'/'||NEW.pet_id::text||'/'||NEW.id::text||'/original';
  if NEW.encounter_id is not null and not exists(select 1 from public.clinical_encounters where id=NEW.encounter_id and pet_id=NEW.pet_id) then raise exception 'Encounter does not belong to patient' using errcode='23514'; end if;
 else
  if (to_jsonb(NEW)-array['status','version','finalized_at','voided_by','voided_at','void_reason']) is distinct from (to_jsonb(OLD)-array['status','version','finalized_at','voided_by','voided_at','void_reason']) then raise exception 'Document metadata is immutable; upload a replacement' using errcode='23514'; end if;
  if not ((OLD.status='uploading' and NEW.status in ('ready','abandoned') and OLD.created_by=actor) or (OLD.status='ready' and NEW.status='void')) then raise exception 'Invalid document transition' using errcode='23514'; end if;
  NEW.version:=OLD.version+1;
  if NEW.status='ready' then NEW.finalized_at:=now(); end if;
  if NEW.status='void' then NEW.voided_by:=actor; NEW.voided_at:=now(); NEW.finalized_at:=OLD.finalized_at; end if;
 end if;
 return NEW;
end $$

create function public.prepare_patient_document(p_id uuid,p_pet_id uuid,p_encounter_id uuid,p_file_name text,p_mime_type text,p_file_size bigint,p_category text,p_source text,p_document_date date,p_visibility text)
returns public.patient_documents language plpgsql security definer set search_path=public as $$
declare actor uuid := public.clinical_require_staff(); result public.patient_documents;
begin
 insert into public.patient_documents(id,pet_id,encounter_id,file_name,file_path,mime_type,file_size,category,source,document_date,visibility,created_by)
 values(p_id,p_pet_id,p_encounter_id,p_file_name,'',p_mime_type,p_file_size,p_category,coalesce(p_source,''),p_document_date,p_visibility,actor) on conflict(id) do nothing;
 select * into result from public.patient_documents where id=p_id for update;
 if result.created_by is distinct from actor then raise exception 'Document belongs to another uploader' using errcode='42501'; end if;
 if row(result.pet_id,result.encounter_id,result.file_name,result.mime_type,result.file_size,result.category,result.source,result.document_date,result.visibility) is distinct from row(p_pet_id,p_encounter_id,p_file_name,p_mime_type,p_file_size,p_category,coalesce(p_source,''),p_document_date,p_visibility) then raise exception 'Upload identifier already used with different metadata' using errcode='23514'; end if;
 if result.status not in ('uploading','ready') then raise exception 'Upload is no longer available' using errcode='23514'; end if;
 return result;
end $$

create function public.finalize_patient_document(p_id uuid) returns public.patient_documents language plpgsql security definer set search_path=public as $$
declare actor uuid := public.clinical_require_staff(); result public.patient_documents; object_metadata jsonb;
begin
 select * into result from public.patient_documents where id=p_id for update;
 if not found or result.created_by<>actor then raise exception 'Document belongs to another uploader or does not exist' using errcode='42501'; end if;
 if result.status='ready' then return result; end if;
 if result.status<>'uploading' then raise exception 'Upload is no longer available' using errcode='23514'; end if;
 select metadata into object_metadata from storage.objects where bucket_id='patient-documents' and name=result.file_path for share;
 if not found then raise exception 'Upload the file before finalizing' using errcode='23514'; end if;
 if object_metadata->>'size' is distinct from result.file_size::text or object_metadata->>'mimetype' is distinct from result.mime_type then raise exception 'Uploaded file size or MIME type does not match reservation' using errcode='23514'; end if;
 update public.patient_documents set status='ready' where id=p_id returning * into result;
 return result;
end $$

create function public.abandon_patient_document(p_id uuid) returns public.patient_documents language plpgsql security definer set search_path=public as $$
declare actor uuid := public.clinical_require_staff(); result public.patient_documents;
begin
 select * into result from public.patient_documents where id=p_id for update;
 if not found or result.created_by<>actor then raise exception 'Document belongs to another uploader or does not exist' using errcode='42501'; end if;
 if result.status='abandoned' then return result; end if;
 if result.status<>'uploading' then raise exception 'Only pending uploads can be abandoned' using errcode='23514'; end if;
 if exists(select 1 from storage.objects where bucket_id='patient-documents' and name=result.file_path) then raise exception 'Remove the pending file before abandoning' using errcode='23514'; end if;
 update public.patient_documents set status='abandoned' where id=p_id returning * into result;
 return result;
end $$

create function public.void_patient_document(p_id uuid,p_expected_version integer,p_reason text) returns public.patient_documents language plpgsql security definer set search_path=public as $$
declare result public.patient_documents;
begin
 perform public.clinical_require_staff();
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'A void reason is required (maximum 2000 characters)' using errcode='23514'; end if;
 update public.patient_documents set status='void',void_reason=trim(p_reason) where id=p_id and version=p_expected_version and status='ready' returning * into result;
 if not found then raise exception 'Record changed or no longer exists; reload before voiding' using errcode='40001'; end if;
 return result;
end $$

-- Row locks serialize storage writes with finalization/abandonment. No overwrite policy exists.
create function public.patient_document_storage_write(p_path text) returns boolean language plpgsql security definer set search_path=public as $$
declare doc public.patient_documents;
begin
 if auth.uid() is null or not public.is_active_staff(auth.uid()) then return false; end if;
 select * into doc from public.patient_documents where file_path=p_path for update;
 return found and doc.created_by=auth.uid() and doc.status='uploading';
end $$

create function public.save_appointment(p_actor_id uuid,p_id uuid,p_expected_version integer,p_client_id uuid,p_pet_id uuid,p_scheduled_at timestamptz,p_duration_minutes integer,p_appointment_type text,p_status public.appointment_status,p_assigned_dvm_id uuid,p_visit_type text,p_address_snapshot text,p_travel_before_minutes integer,p_travel_after_minutes integer,p_resource_name text,p_notes text,p_reminder_offsets integer[])
returns public.appointments language plpgsql security definer set search_path=public as $$
declare actor uuid; result public.appointments; previous public.appointments; offset_hours integer; busy_start timestamptz; busy_end timestamptz;
begin
 actor := public.clinical_require_staff();
 if p_actor_id is distinct from actor then raise exception 'Actor mismatch' using errcode='42501'; end if;
 -- A transaction-scoped schedule lock also covers clinician reassignment and shared rooms.
 perform pg_advisory_xact_lock(73260123);
 if p_id is not null then
  select * into previous from public.appointments where id=p_id for update;
  if not found or previous.version is distinct from p_expected_version then raise exception 'Appointment changed; reload before saving' using errcode='40001'; end if;
 end if;
 if p_client_id is null or p_pet_id is null or not exists(select 1 from public.pets where id=p_pet_id and client_id=p_client_id and ((archived_at is null and deceased_at is null) or (p_status='CANCELLED' and previous.pet_id=p_pet_id and previous.client_id=p_client_id))) then raise exception 'Select an active patient belonging to this household' using errcode='23514'; end if;
 if p_assigned_dvm_id is null or (not public.is_active_staff(p_assigned_dvm_id) and not coalesce(p_status='CANCELLED' and previous.assigned_dvm_id=p_assigned_dvm_id,false)) then raise exception 'Select an active staff clinician' using errcode='23514'; end if;
 if p_scheduled_at is null or not isfinite(p_scheduled_at) or p_duration_minutes is null or p_duration_minutes not between 5 and 480 or p_visit_type is null or p_visit_type not in ('clinic','housecall') or p_status is null or p_travel_before_minutes is null or p_travel_before_minutes not between 0 and 240 or p_travel_after_minutes is null or p_travel_after_minutes not between 0 and 240 then raise exception 'Invalid appointment time or duration' using errcode='23514'; end if;
 if p_appointment_type is null or length(trim(p_appointment_type)) not between 1 and 150 or p_address_snapshot is null or length(trim(p_address_snapshot)) not between 1 and 1000 or length(p_notes)>10000 or length(p_resource_name)>150 then raise exception 'Appointment fields are missing or too long' using errcode='23514'; end if;
 if p_reminder_offsets is null or cardinality(p_reminder_offsets)>5 or exists(select 1 from unnest(p_reminder_offsets) h where h is null or h not between 1 and 720) or cardinality(p_reminder_offsets)<>(select count(distinct h) from unnest(p_reminder_offsets) h) then raise exception 'Use up to five distinct reminder offsets between 1 and 720 hours' using errcode='23514'; end if;
 busy_start := p_scheduled_at - make_interval(mins=>p_travel_before_minutes);
 busy_end := p_scheduled_at + make_interval(mins=>p_duration_minutes+p_travel_after_minutes);
 if p_status in ('SCHEDULED','CONFIRMED') and exists (
  select 1 from public.appointments a where a.id is distinct from p_id and a.status in ('SCHEDULED','CONFIRMED')
  and (a.assigned_dvm_id=p_assigned_dvm_id or (nullif(trim(p_resource_name),'') is not null and lower(a.resource_name)=lower(trim(p_resource_name))))
  and a.scheduled_at-make_interval(mins=>a.travel_before_minutes)<busy_end
  and a.scheduled_at+make_interval(mins=>a.duration_minutes+a.travel_after_minutes)>busy_start
 ) then raise exception 'Clinician or room is already booked, including travel buffers' using errcode='23P01'; end if;
 if p_id is null then
  insert into public.appointments(client_id,pet_id,scheduled_at,duration_minutes,appointment_type,status,assigned_dvm_id,visit_type,address_snapshot,travel_before_minutes,travel_after_minutes,resource_name,notes,reminder_offsets,updated_by)
  values(p_client_id,p_pet_id,p_scheduled_at,p_duration_minutes,trim(p_appointment_type),p_status,p_assigned_dvm_id,p_visit_type,case when p_visit_type='clinic' then '2619 Spruce Street, Boulder, CO' else trim(p_address_snapshot) end,p_travel_before_minutes,p_travel_after_minutes,nullif(trim(p_resource_name),''),p_notes,p_reminder_offsets,actor) returning * into result;
 else
  update public.appointments set client_id=p_client_id,pet_id=p_pet_id,scheduled_at=p_scheduled_at,duration_minutes=p_duration_minutes,appointment_type=trim(p_appointment_type),status=p_status,assigned_dvm_id=p_assigned_dvm_id,visit_type=p_visit_type,address_snapshot=case when p_visit_type='clinic' then '2619 Spruce Street, Boulder, CO' else trim(p_address_snapshot) end,travel_before_minutes=p_travel_before_minutes,travel_after_minutes=p_travel_after_minutes,resource_name=nullif(trim(p_resource_name),''),notes=p_notes,reminder_offsets=p_reminder_offsets,updated_by=actor,version=version+1 where id=p_id returning * into result;
 end if;
 update public.appointment_reminders set status='SKIPPED',error_message='Appointment revised' where appointment_id=result.id and status='PENDING';
 if result.status in ('SCHEDULED','CONFIRMED') then
  foreach offset_hours in array result.reminder_offsets loop
   insert into public.appointment_reminders(appointment_id,appointment_version,remind_at,channel,status)
   values(result.id,result.version,result.scheduled_at-make_interval(hours=>offset_hours),'SMS',case when result.scheduled_at-make_interval(hours=>offset_hours)>now() then 'PENDING'::public.reminder_status else 'SKIPPED'::public.reminder_status end);
  end loop;
 end if;
 return result;
end $$

-- Role rows remain private; expose only eligible clinician names to active staff.
