create function public.invalidate_inactive_patient_reminders() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if NEW.archived_at is not null or NEW.deceased_at is not null then
  update public.appointment_reminders r set status='SKIPPED',error_message='Patient inactive'
  from public.appointments a where a.id=r.appointment_id and a.pet_id=NEW.id and r.status='PENDING';
 end if;
 return NEW;
end $$

create function public.inventory_guard() returns trigger language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();
begin
 if TG_OP='DELETE' then raise exception 'Inventory and billing history cannot be deleted' using errcode='23514'; end if;
 if TG_OP='UPDATE' then
  if TG_TABLE_NAME not in ('catalog_products','billing_invoices') then raise exception 'Ledger records are append-only' using errcode='23514'; end if;
  NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.version:=OLD.version+1;
  if TG_TABLE_NAME='catalog_products' then
   if (NEW.kind,NEW.unit) is distinct from (OLD.kind,OLD.unit) then raise exception 'Product kind and stock unit are immutable' using errcode='23514'; end if;
  end if;
  if TG_TABLE_NAME='billing_invoices' then
   if NEW.client_id<>OLD.client_id or not ((OLD.status='draft' and NEW.status in ('draft','issued')) or (OLD.status='issued' and NEW.status='void')) then raise exception 'Invalid invoice transition' using errcode='23514'; end if;
   if OLD.status='issued' then NEW.total_cents:=OLD.total_cents; NEW.issued_at:=OLD.issued_at; end if;
  end if;
 else NEW.created_by:=actor; NEW.created_at:=now();
 end if;
 return NEW;
end $$

do $$ declare t text; begin
 foreach t in array array['catalog_products','inventory_lots','inventory_movements','billing_invoices','billing_invoice_items','billing_credits','patient_treatments','patient_treatment_corrections'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,service_role',t);
  execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
  execute format('create trigger inventory_guard before insert or update or delete on public.%I for each row execute function public.inventory_guard()',t);
  execute format('create trigger inventory_audit after insert or update on public.%I for each row execute function public.audit_trigger_fn()',t);
 end loop;
end $$

create function public.save_catalog_product(p_id uuid,p_expected_version integer,p_name text,p_kind text,p_manufacturer text,p_unit text,p_unit_price_cents bigint,p_active boolean) returns public.catalog_products language plpgsql security definer set search_path=public as $$
declare result public.catalog_products; actor uuid:=public.clinical_require_staff();
begin
 if p_id is null then insert into public.catalog_products(name,kind,manufacturer,unit,unit_price_cents,active,created_by) values(trim(p_name),p_kind,coalesce(p_manufacturer,''),p_unit,p_unit_price_cents,p_active,actor) returning * into result;
 else update public.catalog_products set name=trim(p_name),kind=p_kind,manufacturer=coalesce(p_manufacturer,''),unit=p_unit,unit_price_cents=p_unit_price_cents,active=p_active where id=p_id and version=p_expected_version returning * into result;
 if not found then raise exception 'Product changed; reload before saving' using errcode='40001'; end if; end if;
 return result;
end $$

create function public.receive_inventory(p_id uuid,p_lot_id uuid,p_product_id uuid,p_lot_number text,p_expires_on date,p_location text,p_quantity numeric,p_reason text) returns public.inventory_movements language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.inventory_movements; lot public.inventory_lots;
begin
 if p_quantity is null or p_quantity::text in ('NaN','Infinity','-Infinity') or p_quantity<=0 or p_quantity<>round(p_quantity,3) then raise exception 'Receipt quantity must be positive with at most 3 decimals' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.inventory_movements where id=p_id;
 if found then
  select * into lot from public.inventory_lots where id=result.lot_id;
  if result.created_by<>actor or row(result.kind,result.lot_id,result.quantity,result.reason,lot.product_id,lot.lot_number,lot.expires_on,lot.location) is distinct from row('receive'::text,p_lot_id,p_quantity,p_reason,p_product_id,p_lot_number,p_expires_on,p_location) then raise exception 'Receipt identifier already used' using errcode='23514'; end if;
  return result;
 end if;
 perform 1 from public.catalog_products where id=p_product_id and kind<>'service' and active for share;
 if not found then raise exception 'Receipt requires active stock product' using errcode='23514'; end if;
 insert into public.inventory_lots(id,product_id,lot_number,expires_on,location,created_by) values(p_lot_id,p_product_id,p_lot_number,p_expires_on,p_location,actor) on conflict(id) do nothing;
 select * into lot from public.inventory_lots where id=p_lot_id for update;
 if row(lot.product_id,lot.lot_number,lot.expires_on,lot.location) is distinct from row(p_product_id,p_lot_number,p_expires_on,p_location) then raise exception 'Lot identifier already used with different metadata' using errcode='23514'; end if;
 insert into public.inventory_movements(id,lot_id,quantity,kind,reason,created_by) values(p_id,p_lot_id,p_quantity,'receive',p_reason,actor) returning * into result;
 return result;
end $$

create function public.adjust_inventory(p_id uuid,p_lot_id uuid,p_quantity numeric,p_reason text) returns public.inventory_movements language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.inventory_movements;
begin
 if p_quantity is null or p_quantity::text in ('NaN','Infinity','-Infinity') or p_quantity=0 or p_quantity<>round(p_quantity,3) then raise exception 'Adjustment must be nonzero with at most 3 decimals' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.inventory_movements where id=p_id;
 if found then
  if result.created_by<>actor or row(result.lot_id,result.quantity,result.reason,result.kind) is distinct from row(p_lot_id,p_quantity,p_reason,'adjust'::text) then raise exception 'Adjustment identifier already used' using errcode='23514'; end if; return result;
 end if;
 perform 1 from public.inventory_lots where id=p_lot_id for update;
 if not found then raise exception 'Lot not found' using errcode='23514'; end if;
 if (select coalesce(sum(quantity),0) from public.inventory_movements where lot_id=p_lot_id)+p_quantity<0 then raise exception 'Insufficient stock' using errcode='23514'; end if;
 insert into public.inventory_movements(id,lot_id,quantity,kind,reason,created_by) values(p_id,p_lot_id,p_quantity,'adjust',p_reason,actor) returning * into result; return result;
end $$

create function public.create_billing_invoice(p_id uuid,p_client_id uuid) returns public.billing_invoices language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.billing_invoices;
begin
 insert into public.billing_invoices(id,client_id,created_by) values(p_id,p_client_id,actor) on conflict(id) do nothing;
 select * into result from public.billing_invoices where id=p_id;
 if result.client_id<>p_client_id or result.created_by<>actor then raise exception 'Invoice identifier already used' using errcode='23514'; end if; return result;
end $$

-- Request JSON is an immutable retry fingerprint; unknown keys are rejected.
create function public.record_patient_treatment(p_id uuid,p_request jsonb) returns public.patient_treatments language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_treatments; lot public.inventory_lots; product public.catalog_products; inv public.billing_invoices; historical boolean; pet uuid; qty numeric; admin_at timestamptz;
begin
 if p_request is null or jsonb_typeof(p_request)<>'object' or exists(select 1 from jsonb_object_keys(p_request) k where k not in ('pet_id','lot_id','invoice_id','quantity','dose','route','site','veterinarian','veterinarian_license','administered_at','next_due_on','historical','product_name','manufacturer','lot_number','expires_on','source','kind')) then raise exception 'Invalid treatment request fields' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.patient_treatments where id=p_id;
 if found then if result.created_by<>actor or result.request<>p_request then raise exception 'Treatment identifier already used' using errcode='23514'; end if; return result; end if;
 historical:=coalesce((p_request->>'historical')::boolean,false); pet:=(p_request->>'pet_id')::uuid; qty:=(p_request->>'quantity')::numeric; admin_at:=(p_request->>'administered_at')::timestamptz;
 if qty is null or qty::text in ('NaN','Infinity','-Infinity') or qty<=0 or qty<>round(qty,3) or admin_at is null or not isfinite(admin_at) or admin_at>now()+interval '5 minutes' then raise exception 'Invalid quantity or administration time' using errcode='23514'; end if;
 if historical then
  if p_request->>'lot_id' is not null or p_request->>'invoice_id' is not null or length(trim(coalesce(p_request->>'source','')))=0 then raise exception 'Historical records require source and cannot bill or debit stock' using errcode='23514'; end if;
  insert into public.patient_treatments(id,pet_id,kind,historical,product_name,manufacturer,lot_number,expires_on,quantity,dose,route,site,veterinarian,veterinarian_license,administered_at,next_due_on,source,request,created_by)
  values(p_id,pet,coalesce(p_request->>'kind','vaccine'),true,p_request->>'product_name',coalesce(p_request->>'manufacturer',''),coalesce(p_request->>'lot_number',''),(p_request->>'expires_on')::date,qty,p_request->>'dose',p_request->>'route',coalesce(p_request->>'site',''),p_request->>'veterinarian',coalesce(p_request->>'veterinarian_license',''),admin_at,(p_request->>'next_due_on')::date,p_request->>'source',p_request,actor) returning * into result;
 else
  select * into inv from public.billing_invoices where id=(p_request->>'invoice_id')::uuid for update;
  if not found or inv.status<>'draft' then raise exception 'A draft invoice is required' using errcode='23514'; end if;
  perform 1 from public.pets where id=pet and client_id=inv.client_id and archived_at is null and deceased_at is null for share;
  if not found then raise exception 'Invoice patient mismatch or inactive patient' using errcode='23514'; end if;
  select * into lot from public.inventory_lots where id=(p_request->>'lot_id')::uuid for update;
  if not found then raise exception 'Lot not found' using errcode='23514'; end if;
  select * into product from public.catalog_products where id=lot.product_id for share;
  if not product.active then raise exception 'Product is inactive' using errcode='23514'; end if;
  if lot.expires_on<(now() at time zone 'America/Denver')::date or lot.expires_on<(admin_at at time zone 'America/Denver')::date then raise exception 'Expired stock cannot be administered or dispensed' using errcode='23514'; end if;
  if (select coalesce(sum(quantity),0) from public.inventory_movements where lot_id=lot.id)<qty then raise exception 'Insufficient stock' using errcode='23514'; end if;
  insert into public.patient_treatments(id,pet_id,product_id,lot_id,invoice_id,kind,historical,product_name,manufacturer,lot_number,expires_on,quantity,dose,route,site,veterinarian,veterinarian_license,administered_at,next_due_on,source,request,created_by)
  values(p_id,pet,product.id,lot.id,inv.id,product.kind,false,product.name,product.manufacturer,lot.lot_number,lot.expires_on,qty,p_request->>'dose',p_request->>'route',coalesce(p_request->>'site',''),p_request->>'veterinarian',coalesce(p_request->>'veterinarian_license',''),admin_at,(p_request->>'next_due_on')::date,coalesce(p_request->>'source','Practice administration'),p_request,actor) returning * into result;
  insert into public.inventory_movements(id,lot_id,quantity,kind,reason,created_by) values(p_id,lot.id,-qty,'dispense','Patient treatment '||p_id::text,actor);
  insert into public.billing_invoice_items(id,invoice_id,pet_id,product_id,description,quantity,unit_price_cents,created_by) values(p_id,inv.id,pet,product.id,product.name,qty,product.unit_price_cents,actor);
  update public.billing_invoices set version=version+1 where id=inv.id;
 end if;
 return result;
end $$

create function public.add_invoice_service(p_id uuid,p_invoice_id uuid,p_pet_id uuid,p_product_id uuid,p_quantity numeric) returns public.billing_invoice_items language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.billing_invoice_items; product public.catalog_products; inv public.billing_invoices;
begin
 if p_quantity is null or p_quantity::text in ('NaN','Infinity','-Infinity') or p_quantity<=0 or p_quantity<>round(p_quantity,3) then raise exception 'Invalid service quantity' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.billing_invoice_items where id=p_id;
 if found then if result.created_by<>actor or row(result.invoice_id,result.pet_id,result.product_id,result.quantity) is distinct from row(p_invoice_id,p_pet_id,p_product_id,p_quantity) then raise exception 'Line identifier already used' using errcode='23514'; end if; return result; end if;
 select * into inv from public.billing_invoices where id=p_invoice_id for update;
 if not found or inv.status<>'draft' then raise exception 'A draft invoice is required' using errcode='23514'; end if;
 if p_pet_id is not null and not exists(select 1 from public.pets where id=p_pet_id and client_id=inv.client_id) then raise exception 'Invoice patient mismatch' using errcode='23514'; end if;
 select * into product from public.catalog_products where id=p_product_id and kind='service' and active for share;
 if not found then raise exception 'Active service product required' using errcode='23514'; end if;
 insert into public.billing_invoice_items(id,invoice_id,pet_id,product_id,description,quantity,unit_price_cents,created_by) values(p_id,p_invoice_id,p_pet_id,product.id,product.name,p_quantity,product.unit_price_cents,actor) returning * into result;
 update public.billing_invoices set version=version+1 where id=p_invoice_id;
 return result;
end $$

create function public.issue_billing_invoice(p_id uuid,p_expected_version integer) returns public.billing_invoices language plpgsql security definer set search_path=public as $$
declare result public.billing_invoices;
begin
 perform public.clinical_require_staff();
 select * into result from public.billing_invoices where id=p_id for update;
 if not found or result.version<>p_expected_version or result.status<>'draft' then raise exception 'Invoice changed; reload before issuing' using errcode='40001'; end if;
 if not exists(select 1 from public.billing_invoice_items where invoice_id=p_id) then raise exception 'Invoice requires at least one item' using errcode='23514'; end if;
 update public.billing_invoices set status='issued',issued_at=now(),total_cents=(select sum(amount_cents) from public.billing_invoice_items where invoice_id=p_id) where id=p_id returning * into result;
 return result;
end $$

create function public.void_billing_invoice(p_id uuid,p_expected_version integer,p_reason text) returns public.billing_invoices language plpgsql security definer set search_path=public as $$
declare result public.billing_invoices;
begin
 perform public.clinical_require_staff();
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Void reason is required' using errcode='23514'; end if;
 select * into result from public.billing_invoices where id=p_id for update;
 if not found or result.version<>p_expected_version or result.status<>'issued' then raise exception 'Invoice changed; reload before voiding' using errcode='40001'; end if;
 if exists(select 1 from public.billing_credits where invoice_id=p_id) then raise exception 'Credited invoices cannot be voided; credit the remaining balance' using errcode='23514'; end if;
 update public.billing_invoices set status='void',voided_at=now(),void_reason=trim(p_reason) where id=p_id returning * into result; return result;
end $$

create function public.credit_billing_invoice(p_id uuid,p_invoice_id uuid,p_amount_cents bigint,p_reason text) returns public.billing_credits language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.billing_credits; inv public.billing_invoices;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.billing_credits where id=p_id;
 if found then if result.created_by<>actor or row(result.invoice_id,result.amount_cents,result.reason) is distinct from row(p_invoice_id,p_amount_cents,p_reason) then raise exception 'Credit identifier already used' using errcode='23514'; end if; return result; end if;
 select * into inv from public.billing_invoices where id=p_invoice_id for update;
 if not found or inv.status<>'issued' then raise exception 'Credit requires issued invoice' using errcode='23514'; end if;
 if (select coalesce(sum(amount_cents),0) from public.billing_credits where invoice_id=p_invoice_id)+p_amount_cents>inv.total_cents then raise exception 'Credit exceeds invoice balance' using errcode='23514'; end if;
 insert into public.billing_credits(id,invoice_id,amount_cents,reason,created_by) values(p_id,p_invoice_id,p_amount_cents,p_reason,actor) returning * into result; return result;
end $$

create function public.correct_patient_treatment(p_id uuid,p_treatment_id uuid,p_reason text,p_replacement_id uuid) returns public.patient_treatment_corrections language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_treatment_corrections; original public.patient_treatments;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.patient_treatment_corrections where id=p_id;
 if found then if result.created_by<>actor or row(result.treatment_id,result.reason,result.replacement_id) is distinct from row(p_treatment_id,p_reason,p_replacement_id) then raise exception 'Correction identifier already used' using errcode='23514'; end if; return result; end if;
 select * into original from public.patient_treatments where id=p_treatment_id for update;
 if not found then raise exception 'Treatment not found' using errcode='23514'; end if;
 if p_replacement_id is not null and (p_replacement_id=p_treatment_id or not exists(select 1 from public.patient_treatments where id=p_replacement_id and pet_id=original.pet_id)) then raise exception 'Replacement must be a different record for the same patient' using errcode='23514'; end if;
 insert into public.patient_treatment_corrections(id,treatment_id,reason,replacement_id,created_by) values(p_id,p_treatment_id,p_reason,p_replacement_id,actor) returning * into result; return result;
end $$

do $$ declare f record; begin
 for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname in ('save_catalog_product','receive_inventory','adjust_inventory','create_billing_invoice','record_patient_treatment','add_invoice_service','issue_billing_invoice','void_billing_invoice','credit_billing_invoice','correct_patient_treatment') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  execute format('grant execute on function %s to authenticated',f.signature);
 end loop;
end $$

create function public.ezyvet_is_active_admin(p_actor uuid) returns boolean language sql stable security definer set search_path=public as $$
 select public.is_active_staff(p_actor) and exists(select 1 from public.user_roles where user_id=p_actor and role='ADMIN');
$$

do $$ declare t text; begin
 foreach t in array array['ezyvet_import_runs','ezyvet_import_snapshots','ezyvet_import_pages','ezyvet_import_page_items','ezyvet_import_reviews'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);
 execute format('grant select on table public.%I to authenticated,service_role',t);
 execute format('create policy "Active administrators read imports" on public.%I for select to authenticated using (public.ezyvet_is_active_admin(auth.uid()))',t);
 end loop;
end $$

create function public.claim_ezyvet_import(p_id uuid,p_actor uuid,p_site_uid text,p_resource text,p_source_origin text)
returns public.ezyvet_import_runs language plpgsql security definer set search_path=public as $$
declare r public.ezyvet_import_runs;
begin
 if public.ezyvet_is_active_admin(p_actor) is not true then raise exception 'Active administrator required' using errcode='42501'; end if;
 if p_id is null or nullif(trim(p_site_uid),'') is null then raise exception 'Invalid import request' using errcode='23514'; end if;
 -- Serialize claims per source/resource, including different runs, to avoid concurrent provider traffic.
 perform pg_advisory_xact_lock(hashtextextended(p_source_origin||':'||p_site_uid||':'||p_resource,0));
 insert into public.ezyvet_import_runs(id,source_origin,source_site_uid,resource,requested_by) values(p_id,p_source_origin,p_site_uid,p_resource,p_actor) on conflict(id) do nothing;
 select * into strict r from public.ezyvet_import_runs where id=p_id for update;
 if r.requested_by<>p_actor or r.source_origin<>p_source_origin or r.source_site_uid<>p_site_uid or r.resource<>p_resource then raise exception 'Import identity mismatch' using errcode='42501'; end if;
 if r.status<>'running' then return r; end if;
 if exists(select 1 from public.ezyvet_import_runs where source_origin=p_source_origin and source_site_uid=p_site_uid and resource=p_resource and (lease_until>now() or retry_after>now())) then raise exception 'Import busy or cooling down' using errcode='55P03'; end if;
 update public.ezyvet_import_runs set lease_id=gen_random_uuid(),lease_until=now()+interval '90 seconds',last_error_code=null,updated_at=now() where id=p_id returning * into r;
 return r;
end $$

create function public.stage_ezyvet_import_page(p_id uuid,p_actor uuid,p_lease_id uuid,p_page integer,p_complete boolean,p_items jsonb)
returns public.ezyvet_import_runs language plpgsql security definer set search_path=public,extensions as $$
declare r public.ezyvet_import_runs; item jsonb; snapshot_id uuid; item_hash text;
begin
 if public.ezyvet_is_active_admin(p_actor) is not true then raise exception 'Active administrator required' using errcode='42501'; end if;
 select * into strict r from public.ezyvet_import_runs where id=p_id for update;
 if r.requested_by<>p_actor then raise exception 'Import owner mismatch' using errcode='42501'; end if;
 -- Retried committed page is a no-op, including a response lost after successful staging.
 if exists(select 1 from public.ezyvet_import_pages where run_id=p_id and page=p_page) then return r; end if;
 if r.status<>'running' or r.lease_id is distinct from p_lease_id or r.lease_until<=now() or p_page<>r.next_page then raise exception 'Import lease or cursor changed' using errcode='40001'; end if;
 if p_complete is null or p_items is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)>50 or octet_length(p_items::text)>2097152 then raise exception 'Invalid import page' using errcode='23514'; end if;
 if not p_complete and jsonb_array_length(p_items)=0 then raise exception 'Empty intermediate page' using errcode='23514'; end if;
 if (select count(*) from jsonb_array_elements(p_items))<>(select count(distinct value->>'external_id') from jsonb_array_elements(p_items)) then raise exception 'Duplicate external IDs' using errcode='23514'; end if;
 insert into public.ezyvet_import_pages(run_id,page,item_count) values(p_id,p_page,jsonb_array_length(p_items));
 for item in select value from jsonb_array_elements(p_items) loop
  if jsonb_typeof(item->'payload') is distinct from 'object' or item->>'external_id' is null or item->>'external_id' !~ '^[A-Za-z0-9_-]{1,128}$' then raise exception 'Invalid imported entity' using errcode='23514'; end if;
  item_hash=encode(digest((item->'payload')::text,'sha256'),'hex');
  insert into public.ezyvet_import_snapshots(source_origin,source_site_uid,resource,external_id,payload,payload_hash,first_seen_by)
  values(r.source_origin,r.source_site_uid,r.resource,item->>'external_id',item->'payload',item_hash,p_actor) on conflict(source_origin,source_site_uid,resource,external_id,payload_hash) do nothing;
  select id into strict snapshot_id from public.ezyvet_import_snapshots where source_origin=r.source_origin and source_site_uid=r.source_site_uid and resource=r.resource and external_id=item->>'external_id' and payload_hash=item_hash;
  insert into public.ezyvet_import_page_items(run_id,page,snapshot_id) values(p_id,p_page,snapshot_id);
 end loop;
 update public.ezyvet_import_runs set next_page=p_page+1,status=case when p_complete then 'review_ready' when p_page=1000 then 'page_limit_reached' else 'running' end,lease_id=null,lease_until=null,retry_after=now()+interval '2 seconds',last_error_code=null,updated_at=now() where id=p_id returning * into r;
 return r;
end $$

create function public.fail_ezyvet_import_page(p_id uuid,p_actor uuid,p_lease_id uuid,p_code text,p_retry_seconds integer)
returns void language plpgsql security definer set search_path=public as $$
begin
 if public.ezyvet_is_active_admin(p_actor) is not true then raise exception 'Active administrator required' using errcode='42501'; end if;
 if p_code is null or p_retry_seconds is null or p_code !~ '^[A-Z_]{1,64}$' or p_retry_seconds not between 1 and 3600 then raise exception 'Invalid import failure' using errcode='23514'; end if;
 update public.ezyvet_import_runs set lease_id=null,lease_until=null,last_error_code=p_code,retry_after=now()+make_interval(secs=>p_retry_seconds),updated_at=now() where id=p_id and requested_by=p_actor and lease_id=p_lease_id;
end $$

create function public.review_ezyvet_snapshot(p_snapshot_id uuid,p_decision text,p_client_id uuid,p_pet_id uuid,p_reason text)
returns public.ezyvet_import_reviews language plpgsql security definer set search_path=public as $$
declare s public.ezyvet_import_snapshots; r public.ezyvet_import_reviews;
begin
 if public.ezyvet_is_active_admin(auth.uid()) is not true then raise exception 'Active administrator required' using errcode='42501'; end if;
 select * into strict s from public.ezyvet_import_snapshots where id=p_snapshot_id;
 if (p_client_id is not null and s.resource<>'contact') or (p_pet_id is not null and s.resource<>'animal') then raise exception 'Match target does not fit imported resource' using errcode='23514'; end if;
 insert into public.ezyvet_import_reviews(snapshot_id,decision,client_id,pet_id,reason,reviewed_by) values(p_snapshot_id,p_decision,p_client_id,p_pet_id,trim(p_reason),auth.uid()) returning * into r;
 return r;
end $$

do $$ declare t text; begin
 foreach t in array array['communication_outbox','communication_attempts','communication_delivery_events','communication_suppressions','communication_retry_audit'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,service_role',t);
 end loop;
end $$

create function public.communication_recipient(p_channel text,p_recipient text) returns text language plpgsql immutable set search_path=public as $$
declare result text;
begin
 if p_channel='EMAIL' then
  result:=lower(trim(p_recipient));
  if length(result)>254 or result !~ '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' or result like '.%' or result like '%..%' or result like '%.@%' then result:=null; end if;
 elsif p_channel='SMS' then
  if trim(p_recipient) !~ '^\+[0-9 ().-]+$' then return null; end if;
  result:=regexp_replace(trim(p_recipient),'[ ().-]','','g');
  if result !~ '^\+[1-9][0-9]{7,14}$' then result:=null; end if;
 end if;
 return result;
end $$

create function public.enqueue_communication(p_actor_id uuid,p_request_id uuid,p_conversation_id uuid,p_channel text,p_recipient text,p_subject text,p_body text,p_attachment_ids uuid[] default '{}') returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid; recipient text; client public.clients; existing public.communication_outbox; msg_id uuid; result public.communication_outbox;
begin
 actor:=public.clinical_require_staff();
 if p_actor_id is distinct from actor then raise exception 'Actor mismatch' using errcode='42501'; end if;
 recipient:=public.communication_recipient(p_channel,p_recipient);
 if p_request_id is null or recipient is null or p_body is null or length(trim(p_body))<1 or (p_channel='EMAIL' and (p_subject is null or length(trim(p_subject)) not between 1 and 500 or length(p_body)>100000)) or (p_channel='SMS' and (coalesce(p_subject,'')<>'' or length(p_body)>1600)) or p_attachment_ids is null or cardinality(p_attachment_ids)<>0 then raise exception 'Invalid outbound request; attachments require the record-release workflow' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,914));
 select * into existing from public.communication_outbox where request_id=p_request_id;
 if found then
  if existing.created_by is distinct from actor or existing.conversation_id is distinct from p_conversation_id or existing.channel is distinct from p_channel or existing.recipient is distinct from recipient or existing.subject is distinct from coalesce(p_subject,'') or existing.body is distinct from p_body then raise exception 'Request identifier already used for different content' using errcode='23505'; end if;
  return existing;
 end if;
 select c.* into client from public.clients c join public.conversations v on v.client_id=c.id where v.id=p_conversation_id;
 if not found or recipient is distinct from public.communication_recipient(p_channel,case when p_channel='EMAIL' then client.primary_email else client.primary_phone end) then raise exception 'Recipient does not match the conversation household' using errcode='42501'; end if;
 if public.communication_is_suppressed(p_channel,recipient,client.id) then raise exception 'Recipient suppressed or SMS consent missing' using errcode='42501'; end if;
 insert into public.messages(conversation_id,content,type,sender_type,sender_id,is_internal) values(p_conversation_id,p_body,p_channel::public.message_type,'STAFF',actor,false) returning id into msg_id;
 insert into public.communication_outbox(request_id,conversation_id,client_id,message_id,created_by,channel,recipient,subject,body,provider)
 values(p_request_id,p_conversation_id,client.id,msg_id,actor,p_channel,recipient,coalesce(p_subject,''),p_body,case when p_channel='EMAIL' then 'resend' else 'twilio' end) returning * into result;
 update public.conversations set last_message_at=now(),is_read=true where id=p_conversation_id;
 return result;
end $$

create function public.claim_communication() returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare result public.communication_outbox;
begin
 perform public.communication_require_service();
 -- A dead worker with an in-flight request is ambiguous, including after provider acceptance.
 update public.communication_attempts a set outcome='uncertain',finished_at=now(),error_code='worker_lease_expired'
 from public.communication_outbox o where o.state='claimed' and o.lease_expires_at<now() and o.attempt_started_at is not null and a.lease_token=o.lease_token and a.finished_at is null;
 update public.communication_outbox set state=case when attempt_started_at is null then 'pending' else 'uncertain' end,last_error='worker_lease_expired',lease_token=null,lease_expires_at=null,updated_at=now() where state='claimed' and lease_expires_at<now();
 select * into result from public.communication_outbox where state='pending' order by created_at for update skip locked limit 1;
 if not found then return null; end if;
 update public.communication_outbox set state='claimed',lease_token=gen_random_uuid(),lease_expires_at=now()+interval '2 minutes',attempt_started_at=null,updated_at=now() where id=result.id returning * into result;
 return result;
end $$

create function public.start_communication_attempt(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare result public.communication_outbox;
begin
 perform public.communication_require_service();
 select * into result from public.communication_outbox where id=p_id for update;
 if not found or result.state<>'claimed' or result.lease_token is distinct from p_lease_token or result.lease_expires_at<=now() or result.attempt_started_at is not null then raise exception 'Outbox lease is unavailable' using errcode='40001'; end if;
 -- Re-check immediately before the external request, including actor revocation and contact changes.
 if not public.is_active_staff(result.created_by) or public.communication_is_suppressed(result.channel,result.recipient,result.client_id)
 or not exists(select 1 from public.clients c where c.id=result.client_id and public.communication_recipient(result.channel,case when result.channel='EMAIL' then c.primary_email else c.primary_phone end)=result.recipient) then
  update public.communication_outbox set state='failed',last_error='recipient_or_actor_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into result;
  return result;
 end if;
 if p_provider_config is null or jsonb_typeof(p_provider_config)<>'object' or (result.provider='resend' and (not(p_provider_config ?& array['from','reply_to']) or p_provider_config-array['from','reply_to']<>'{}'::jsonb)) or (result.provider='twilio' and (not(p_provider_config ?& array['from','account_sid']) or p_provider_config-array['from','account_sid']<>'{}'::jsonb)) then raise exception 'Invalid provider metadata' using errcode='23514'; end if;
 if result.provider_config is not null and result.provider_config<>p_provider_config then raise exception 'Provider sender metadata changed; reconcile before sending' using errcode='23514'; end if;
 if result.first_attempt_at is not null and result.provider='resend' and result.first_attempt_at<=now()-interval '23 hours' then
  update public.communication_outbox set state='uncertain',last_error='idempotency_window_expired',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into result; return result;
 end if;
 update public.communication_outbox set provider_config=coalesce(provider_config,p_provider_config),first_attempt_at=coalesce(first_attempt_at,now()),attempt_started_at=now(),attempt_count=attempt_count+1,updated_at=now() where id=p_id returning * into result;
 insert into public.communication_attempts(outbox_id,lease_token,attempt_number) values(result.id,p_lease_token,result.attempt_count);
 return result;
end $$

create function public.finish_communication_attempt(p_id uuid,p_lease_token uuid,p_outcome text,p_provider_message_id text,p_error_code text) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare result public.communication_outbox;
begin
 perform public.communication_require_service();
 if p_outcome is null or p_outcome not in ('accepted','failed','uncertain') or (p_outcome='accepted' and (p_provider_message_id is null or length(p_provider_message_id) not between 1 and 200)) or length(p_error_code)>200 then raise exception 'Invalid provider outcome' using errcode='23514'; end if;
 select * into result from public.communication_outbox where id=p_id for update;
 if not found or result.state<>'claimed' or result.lease_token is distinct from p_lease_token or result.attempt_started_at is null then raise exception 'Outbox attempt is unavailable; reconcile provider outcome' using errcode='40001'; end if;
 update public.communication_attempts set outcome=p_outcome,finished_at=now(),provider_message_id=p_provider_message_id,error_code=p_error_code where lease_token=p_lease_token;
 update public.communication_outbox set state=p_outcome,provider_message_id=p_provider_message_id,last_error=p_error_code,accepted_at=case when p_outcome='accepted' then now() else accepted_at end,lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into result;
 return result;
end $$

-- A configuration/allowlist rejection before start is safe to release without an attempt.
create function public.release_communication_claim(p_id uuid,p_lease_token uuid,p_error_code text) returns void language plpgsql security definer set search_path=public as $$
begin
 perform public.communication_require_service();
 update public.communication_outbox set state='failed',last_error=left(p_error_code,200),lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id and state='claimed' and lease_token=p_lease_token and attempt_started_at is null;
 if not found then raise exception 'Outbox claim unavailable' using errcode='40001'; end if;
end $$

create function public.retry_communication(p_actor_id uuid,p_id uuid) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid; result public.communication_outbox;
begin
 actor:=public.clinical_require_staff(); if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501'; end if;
 select * into result from public.communication_outbox where id=p_id for update;
 if not found or result.state not in ('failed','uncertain') then raise exception 'Only failed or eligible uncertain messages can be retried' using errcode='23514'; end if;
 if result.provider_message_id is not null then raise exception 'Previously accepted messages require delivery reconciliation, not resend' using errcode='23514'; end if;
 if result.state='uncertain' and (result.provider<>'resend' or result.first_attempt_at is null or result.first_attempt_at<=now()-interval '23 hours') then raise exception 'Provider reconciliation required; blind retry is unsafe' using errcode='23514'; end if;
 if public.communication_is_suppressed(result.channel,result.recipient,result.client_id) then raise exception 'Recipient suppressed or SMS consent missing' using errcode='42501'; end if;
 insert into public.communication_retry_audit(outbox_id,requested_by,previous_state) values(result.id,actor,result.state);
 update public.communication_outbox set state='pending',attempt_started_at=null,updated_at=now() where id=p_id returning * into result;
 return result;
end $$

-- Called only after a verified provider webhook; receipt IDs deduplicate retries.
create function public.record_communication_delivery(p_provider text,p_event_id text,p_provider_message_id text,p_outcome text) returns void language plpgsql security definer set search_path=public as $$
declare target uuid; previous public.communication_delivery_events;
begin
 perform public.communication_require_service();
 if p_outcome is null or p_outcome not in ('delivered','failed') or p_event_id is null or length(p_event_id) not between 1 and 200 then raise exception 'Invalid delivery event' using errcode='23514'; end if;
 select id into target from public.communication_outbox where provider=p_provider and provider_message_id=p_provider_message_id for update;
 if not found then raise exception 'Unknown provider message' using errcode='23503'; end if;
 select * into previous from public.communication_delivery_events where provider=p_provider and event_id=p_event_id;
 if found then
  if previous.outbox_id<>target or previous.outcome<>p_outcome then raise exception 'Delivery event identifier reused' using errcode='23505'; end if;
  return;
 end if;
 insert into public.communication_delivery_events(provider,event_id,outbox_id,outcome) values(p_provider,p_event_id,target,p_outcome);
 update public.communication_outbox set state=case when state='delivered' then 'delivered' else p_outcome end,delivered_at=case when p_outcome='delivered' then coalesce(delivered_at,now()) else delivered_at end,updated_at=now() where id=target;
end $$

create function public.suppress_communication(p_actor_id uuid,p_channel text,p_recipient text,p_reason text) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid; normalized_recipient text;
begin
 actor:=public.clinical_require_staff(); if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501'; end if;
 normalized_recipient:=public.communication_recipient(p_channel,p_recipient);
 if normalized_recipient is null then raise exception 'Invalid recipient' using errcode='23514'; end if;
 insert into public.communication_suppressions(channel,recipient,reason,created_by) values(p_channel,normalized_recipient,p_reason,actor) on conflict(channel,recipient) do nothing;
 update public.communication_outbox set state='failed',last_error='recipient_suppressed',updated_at=now() where channel=p_channel and recipient=normalized_recipient and state='pending';
end $$

do $$ declare f record; begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on p.pronamespace=n.oid where n.nspname='public' and p.proname in ('communication_recipient','communication_require_service','communication_is_suppressed','enqueue_communication','claim_communication','start_communication_attempt','finish_communication_attempt','release_communication_claim','retry_communication','record_communication_delivery','suppress_communication') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('enqueue_communication','retry_communication','suppress_communication') then execute format('grant execute on function %s to authenticated',f.signature);
  elsif f.proname in ('claim_communication','start_communication_attempt','finish_communication_attempt','release_communication_claim','record_communication_delivery') then execute format('grant execute on function %s to service_role',f.signature);
  end if;
 end loop;
end $$

create function public.reconcile_communication(p_id uuid,p_outcome text,p_provider_message_id text,p_evidence_reference text) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare result public.communication_outbox;
begin
 perform public.communication_require_service();
 if p_outcome is null or p_outcome not in ('accepted','failed') or p_evidence_reference is null or length(trim(p_evidence_reference)) not between 5 and 500 or (p_outcome='accepted' and (p_provider_message_id is null or length(p_provider_message_id) not between 1 and 200)) or (p_outcome='failed' and p_provider_message_id is not null) then raise exception 'Provider reconciliation requires a valid outcome and evidence reference' using errcode='23514'; end if;
 select * into result from public.communication_outbox where id=p_id for update;
 if not found or result.state<>'uncertain' then raise exception 'Only uncertain requests can be reconciled' using errcode='23514'; end if;
 insert into public.communication_reconciliations(outbox_id,previous_state,outcome,provider_message_id,evidence_reference) values(p_id,result.state,p_outcome,p_provider_message_id,p_evidence_reference);
 update public.communication_outbox set state=p_outcome,provider_message_id=p_provider_message_id,first_attempt_at=case when p_outcome='failed' then null else first_attempt_at end,accepted_at=case when p_outcome='accepted' then coalesce(accepted_at,now()) else accepted_at end,last_error=case when p_outcome='failed' then 'reconciled_not_accepted' else null end,updated_at=now() where id=p_id returning * into result;
 return result;
end $$

-- The conversation display must remain consistent with immutable outbound intent.
create function public.guard_outbox_message() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if exists(select 1 from public.communication_outbox where message_id=OLD.id) then
  if TG_OP='DELETE' then raise exception 'Queued communication history cannot be deleted' using errcode='23514'; end if;
  if (to_jsonb(NEW)-array['triage_priority','triage_confidence','triage_reason']) is distinct from (to_jsonb(OLD)-array['triage_priority','triage_confidence','triage_reason']) then raise exception 'Queued communication content is immutable' using errcode='23514'; end if;
 end if;
 return case when TG_OP='DELETE' then OLD else NEW end;
end $$

create function public.search_inventory_products(p_search text default '',p_limit integer default 101) returns setof public.catalog_products language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 if length(p_search)>200 then raise exception 'Search is too long' using errcode='23514'; end if;
 return query select * from public.catalog_products where strpos(lower(name||' '||manufacturer),lower(coalesce(p_search,'')))>0 order by name,id limit greatest(1,least(coalesce(p_limit,101),101));
end $$

create function public.inventory_lot_balances(p_search text default '',p_product_id uuid default null,p_limit integer default 101)
returns table(id uuid,product_id uuid,product_name text,kind text,unit text,active boolean,lot_number text,expires_on date,location text,balance numeric) language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 if length(p_search)>200 then raise exception 'Search is too long' using errcode='23514'; end if;
 return query select l.id,l.product_id,p.name,p.kind,p.unit,p.active,l.lot_number,l.expires_on,l.location,coalesce((select sum(m.quantity) from public.inventory_movements m where m.lot_id=l.id),0)
 from public.inventory_lots l join public.catalog_products p on p.id=l.product_id
 where (p_product_id is null or l.product_id=p_product_id) and strpos(lower(p.name||' '||l.lot_number||' '||l.location),lower(coalesce(p_search,'')))>0
 order by l.expires_on,l.id limit greatest(1,least(coalesce(p_limit,101),101));
end $$

create function public.create_inventory_product(p_id uuid,p_name text,p_kind text,p_manufacturer text,p_unit text,p_unit_price_cents bigint) returns public.catalog_products language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.catalog_products;
begin
 insert into public.catalog_products(id,name,kind,manufacturer,unit,unit_price_cents,created_by) values(p_id,trim(p_name),p_kind,coalesce(p_manufacturer,''),p_unit,p_unit_price_cents,actor) on conflict(id) do nothing;
 select * into result from public.catalog_products where id=p_id;
 if result.created_by<>actor or row(result.name,result.kind,result.manufacturer,result.unit,result.unit_price_cents) is distinct from row(trim(p_name),p_kind,coalesce(p_manufacturer,''),p_unit,p_unit_price_cents) then raise exception 'Product identifier already used with different metadata' using errcode='23514'; end if;
 return result;
end $$

create function public.ezyvet_observe_identity() returns trigger language plpgsql security definer set search_path=public as $$
declare s public.ezyvet_import_snapshots;
begin
 select * into strict s from public.ezyvet_import_snapshots where id=new.snapshot_id;
 insert into public.ezyvet_identity_heads(source_origin,source_site_uid,resource,external_id,snapshot_id) values(s.source_origin,s.source_site_uid,s.resource,s.external_id,s.id)
 on conflict(source_origin,source_site_uid,resource,external_id) do update set snapshot_id=excluded.snapshot_id,version=ezyvet_identity_heads.version+1,observed_at=clock_timestamp() where ezyvet_identity_heads.snapshot_id<>excluded.snapshot_id;
 return new;
end $$

do $$ declare t text; begin foreach t in array array['ezyvet_identity_heads','ezyvet_record_links'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);
 execute format('grant select on table public.%I to authenticated,service_role',t);
 execute format('create policy "Active administrators read import decisions" on public.%I for select to authenticated using (public.ezyvet_is_active_admin(auth.uid()))',t);
end loop;end $$

create function public.promote_ezyvet_identity(p_request_id uuid,p_snapshot_id uuid,p_expected_hash text,p_head_version integer,p_action text,p_client_id uuid,p_pet_id uuid,p_expected_local_version integer,p_values jsonb,p_reason text)
returns public.ezyvet_record_links language plpgsql security definer set search_path=public,extensions as $$
declare actor uuid:=auth.uid(); s public.ezyvet_import_snapshots; h public.ezyvet_identity_heads; result public.ezyvet_record_links; c public.clients; p public.pets; owner_id uuid; fingerprint text; allowed text[];
begin
 if public.ezyvet_is_active_admin(actor) is not true then raise exception 'Active administrator required' using errcode='42501'; end if;
 if p_request_id is null or p_values is null or jsonb_typeof(p_values)<>'object' or p_action is null or p_action not in ('create','link') or nullif(trim(p_reason),'') is null or length(p_reason)>2000 then raise exception 'Invalid reviewed import' using errcode='23514'; end if;
 fingerprint=encode(digest(jsonb_build_array(p_snapshot_id,p_expected_hash,p_head_version,p_action,p_client_id,p_pet_id,p_expected_local_version,p_values,p_reason)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,1));
 select * into result from public.ezyvet_record_links where request_id=p_request_id;
 if found then
  if result.approved_by<>actor or result.request_hash<>fingerprint then raise exception 'Approval request identity mismatch' using errcode='42501'; end if;
  return result;
 end if;
 select * into strict s from public.ezyvet_import_snapshots where id=p_snapshot_id;
 if s.resource not in ('contact','animal') then raise exception 'Only reviewed contacts and animals can be promoted' using errcode='23514'; end if;
 select * into h from public.ezyvet_identity_heads where source_origin=s.source_origin and source_site_uid=s.source_site_uid and resource=s.resource and external_id=s.external_id for update;
 if not found or h.snapshot_id<>s.id or h.version is distinct from p_head_version or s.payload_hash is distinct from p_expected_hash then raise exception 'Source changed; reload and review again' using errcode='40001'; end if;
 if exists(select 1 from public.ezyvet_record_links where source_origin=s.source_origin and source_site_uid=s.source_site_uid and resource=s.resource and external_id=s.external_id) then raise exception 'Source identity already linked; local record will not be overwritten' using errcode='23505'; end if;
 if p_action='link' and p_values<>'{}'::jsonb then raise exception 'Linking cannot change local values' using errcode='23514'; end if;
 if s.resource='contact' then
  if p_pet_id is not null then raise exception 'Contact cannot target a patient' using errcode='23514'; end if;
  if p_action='create' then
   if p_client_id is not null or p_expected_local_version is not null then raise exception 'New household cannot target existing records' using errcode='23514'; end if;
   allowed=array['first_name','last_name','primary_phone','primary_email','mailing_address','housecall_address'];
   if exists(select 1 from jsonb_object_keys(p_values) k where not k=any(allowed)) then raise exception 'Unsupported household fields' using errcode='23514'; end if;
   c=public.save_client(actor,null,null,p_values->>'first_name',p_values->>'last_name',p_values->>'primary_phone',p_values->>'primary_email','EMAIL',p_values->>'mailing_address',p_values->>'housecall_address');
  else
   select * into c from public.clients where id=p_client_id for share;
   if not found or c.version is distinct from p_expected_local_version then raise exception 'Local record changed; reload before linking' using errcode='40001'; end if;
  end if;
 else
  select client_id into owner_id from public.ezyvet_record_links where source_origin=s.source_origin and source_site_uid=s.source_site_uid and resource='contact' and external_id=s.payload->>'contact_id';
  if owner_id is null then raise exception 'Review and link the source household first' using errcode='23514'; end if;
  if p_client_id is distinct from owner_id then raise exception 'Animal household does not match source household link' using errcode='23514'; end if;
  if p_action='create' then
   if p_pet_id is not null or p_expected_local_version is not null then raise exception 'New patient cannot target existing records' using errcode='23514'; end if;
   allowed=array['name','species','breed','dob','birth_date_precision','color','sex','neuter_status','microchip_id','deceased_at'];
   if exists(select 1 from jsonb_object_keys(p_values) k where not k=any(allowed)) then raise exception 'Unsupported patient fields' using errcode='23514'; end if;
   p=public.save_patient(null,owner_id,null,p_values->>'name',p_values->>'species',nullif(p_values->>'breed',''),nullif(p_values->>'dob','')::date,coalesce(p_values->>'birth_date_precision','unknown'),nullif(p_values->>'color',''),coalesce(p_values->>'sex','unknown'),coalesce(p_values->>'neuter_status','unknown'),nullif(p_values->>'microchip_id',''),null,nullif(p_values->>'deceased_at','')::date);
  else
   select * into p from public.pets where id=p_pet_id for share;
   if not found or p.version is distinct from p_expected_local_version then raise exception 'Local record changed; reload before linking' using errcode='40001'; end if;
   if p.client_id<>owner_id then raise exception 'Existing patient ownership cannot change through import' using errcode='23514'; end if;
  end if;
 end if;
 insert into public.ezyvet_record_links(request_id,request_hash,source_origin,source_site_uid,resource,external_id,snapshot_id,head_version,client_id,pet_id,local_version,action,reason,approved_by)
 values(p_request_id,fingerprint,s.source_origin,s.source_site_uid,s.resource,s.external_id,s.id,h.version,case when s.resource='contact' then c.id else owner_id end,case when s.resource='animal' then p.id else null end,case when s.resource='contact' then c.version else p.version end,p_action,trim(p_reason),actor) returning * into result;
 return result;
end $$

do $$ declare t text;begin
 foreach t in array array['communication_provider_events','communication_inbound','communication_inbound_assignments','communication_phone_preferences','conversation_read_cursors'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,service_role',t);
  if t='conversation_read_cursors' then execute format('create policy "Own read cursor" on public.%I for select to authenticated using(user_id=auth.uid() and public.is_active_staff(auth.uid()))',t);
  else execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);end if;
 end loop;
end $$

create function public.receive_communication_event(p_provider text,p_event_id text,p_resource_id text,p_event_type text,p_payload_hash text,p_metadata jsonb) returns public.communication_provider_events language plpgsql security definer set search_path=public as $$
declare result public.communication_provider_events;
begin
 perform public.communication_require_service();
 if p_provider is null or p_provider not in ('resend','twilio') or p_event_id is null or length(p_event_id) not between 1 and 200 or p_resource_id is null or length(p_resource_id) not between 1 and 200 or p_event_type is null or p_event_type not in ('inbound','sent','delivered','bounced','complained','failed','undelivered','queued','sending') or p_metadata is null or jsonb_typeof(p_metadata)<>'object' then raise exception 'Invalid provider event' using errcode='23514'; end if;
 -- Receipt callbacks can arrive before the send worker persists its provider ID. Fail for retry, never acknowledge and drop.
 if p_event_type<>'inbound' and not exists(select 1 from public.communication_outbox where provider=p_provider and provider_message_id=p_resource_id) then raise exception 'Provider receipt is not yet correlated' using errcode='23503'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_provider||':'||p_event_id,927));
 select * into result from public.communication_provider_events where provider=p_provider and event_id=p_event_id;
 if found then
  if result.payload_hash is distinct from p_payload_hash or result.resource_id is distinct from p_resource_id or result.event_type is distinct from p_event_type then raise exception 'Provider event identifier reused' using errcode='23505';end if;
  return result;
 end if;
 insert into public.communication_provider_events(provider,event_id,resource_id,event_type,payload_hash,metadata) values(p_provider,p_event_id,p_resource_id,p_event_type,p_payload_hash,p_metadata) returning * into result;
 return result;
end $$

create function public.claim_communication_event() returns public.communication_provider_events language plpgsql security definer set search_path=public as $$
declare result public.communication_provider_events;
begin
 perform public.communication_require_service();
 update public.communication_provider_events set state='pending',lease_token=null,lease_expires_at=null where state='claimed' and lease_expires_at<now();
 select * into result from public.communication_provider_events where state='pending' and available_at<=now() order by received_at for update skip locked limit 1;
 if not found then return null;end if;
 update public.communication_provider_events set state='claimed',lease_token=gen_random_uuid(),lease_expires_at=now()+interval '2 minutes',attempts=attempts+1 where id=result.id returning * into result;
 return result;
end $$

create function public.release_communication_event(p_id uuid,p_lease_token uuid,p_error text,p_review boolean default false) returns void language plpgsql security definer set search_path=public as $$
begin
 perform public.communication_require_service();
 update public.communication_provider_events set state=case when p_review or attempts>=10 then 'review' else 'pending' end,available_at=now()+make_interval(secs=>least(3600,power(2,least(attempts,10))::integer*30)),last_error=left(p_error,200),lease_token=null,lease_expires_at=null where id=p_id and state='claimed' and lease_token=p_lease_token;
 if not found then raise exception 'Provider event lease unavailable' using errcode='40001';end if;
end $$

create function public.complete_inbound_communication(p_event_id uuid,p_lease_token uuid,p_sender text,p_recipient text,p_subject text,p_body text,p_html text,p_rfc_message_id text,p_reply_ids text[],p_attachments jsonb,p_occurred_at timestamptz,p_opt_action text default null) returns public.communication_inbound language plpgsql security definer set search_path=public as $$
declare event public.communication_provider_events; result public.communication_inbound; channel text; sender text;recipient text;client uuid;conversation uuid;matches integer;message uuid;preference public.communication_phone_preferences;consent_watermark timestamptz;
begin
 perform public.communication_require_service();
 select * into event from public.communication_provider_events where id=p_event_id for update;
 if not found or event.state<>'claimed' or event.lease_token is distinct from p_lease_token or event.event_type<>'inbound' then raise exception 'Provider event lease unavailable' using errcode='40001';end if;
 channel:=case when event.provider='resend' then 'EMAIL' else 'SMS' end;
 sender:=public.communication_recipient(channel,p_sender);recipient:=public.communication_recipient(channel,p_recipient);
 if sender is null or recipient is null or p_body is null or length(p_body)>100000 or length(p_html)>500000 or length(p_subject)>500 or p_occurred_at is null or not isfinite(p_occurred_at) or p_occurred_at>now()+interval '5 minutes' or p_reply_ids is null or cardinality(p_reply_ids)>50 or p_attachments is null or jsonb_typeof(p_attachments)<>'array' or jsonb_array_length(p_attachments)>100 then raise exception 'Invalid inbound content' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(channel||':'||sender,936));
 select * into result from public.communication_inbound where provider=event.provider and resource_id=event.resource_id;
 if found then update public.communication_provider_events set state='processed',lease_token=null,lease_expires_at=null where id=event.id;return result;end if;
 -- Exact normalized household match only. Shared addresses stay in review; no pet is inferred.
 select count(*),(array_agg(c.id))[1] into matches,client from public.clients c where public.communication_recipient(channel,case when channel='EMAIL' then c.primary_email else c.primary_phone end)=sender;
 if matches<>1 then client:=null;end if;
 if client is not null then
  select count(distinct i.conversation_id),(array_agg(i.conversation_id))[1] into matches,conversation from public.communication_inbound i where i.rfc_message_id=any(p_reply_ids) and i.client_id=client and i.conversation_id is not null;
  if matches>1 then conversation:=null;
  elsif matches=0 then
   select count(*),(array_agg(c.id))[1] into matches,conversation from public.conversations c where c.client_id=client and c.status='ACTIVE';
   if matches>1 then conversation:=null;
   elsif matches=0 then insert into public.conversations(client_id) values(client) returning id into conversation;
   end if;
  end if;
 end if;
 if conversation is not null then
  insert into public.messages(conversation_id,type,sender_type,content,is_internal) values(conversation,channel::public.message_type,'CLIENT',p_body,false) returning id into message;
  update public.conversations set last_message_at=now(),is_read=false where id=conversation;
 end if;
 insert into public.communication_inbound(provider,resource_id,event_id,channel,sender,recipient,subject,body,html_body,rfc_message_id,reply_ids,attachment_metadata,occurred_at,client_id,conversation_id,message_id,review_reason)
 values(event.provider,event.resource_id,event.id,channel,sender,recipient,coalesce(p_subject,''),p_body,p_html,p_rfc_message_id,p_reply_ids,p_attachments,p_occurred_at,client,conversation,message,case when client is null then 'Unknown or shared sender' when conversation is null then 'Multiple possible conversation threads' end) returning * into result;
 -- Provider-fetched occurrence time makes older STOP/START deliveries unable to reverse newer consent.
 if channel='SMS' and p_opt_action in ('STOP','START') then
  select * into preference from public.communication_phone_preferences where phone=sender for update;
  -- Legacy/manual consent timestamps are also authoritative: an older START must
  -- not erase a later staff-recorded opt-out which predates this provider table.
  select max(greatest(opted_in_at,opted_out_at)) into consent_watermark from public.sms_consent where public.communication_recipient('SMS',phone_number)=sender;
  if (preference.phone is null or p_occurred_at>preference.occurred_at or (p_occurred_at=preference.occurred_at and p_opt_action='STOP'))
   and (consent_watermark is null or p_occurred_at>consent_watermark or (p_occurred_at=consent_watermark and p_opt_action='STOP')) then
   insert into public.communication_phone_preferences(phone,opted_in,occurred_at,resource_id,event_id) values(sender,p_opt_action='START',p_occurred_at,event.resource_id,event.id)
   on conflict(phone) do update set opted_in=excluded.opted_in,occurred_at=excluded.occurred_at,resource_id=excluded.resource_id,event_id=excluded.event_id,updated_at=now();
   if p_opt_action='STOP' then
    insert into public.communication_suppressions(channel,recipient,reason) values('SMS',sender,'provider_sms_stop') on conflict on constraint communication_suppressions_pkey do nothing;
    update public.sms_consent set opted_in=false,opted_out_at=p_occurred_at where public.communication_recipient('SMS',phone_number)=sender;
    update public.communication_outbox o set state='failed',last_error='recipient_suppressed' where o.channel='SMS' and o.recipient=sender and o.state='pending';
   else
    delete from public.communication_suppressions s where s.channel='SMS' and s.recipient=sender and s.reason in ('provider_sms_stop','staff_sms_opt_out');
    -- START applies only to an unambiguous household, without overriding other suppression reasons.
    if client is not null then
     update public.sms_consent set opted_in=true,opted_in_at=p_occurred_at,opted_out_at=null where client_id=client and public.communication_recipient('SMS',phone_number)=sender;
     if not found then insert into public.sms_consent(client_id,phone_number,opted_in,opted_in_at,consent_details) values(client,sender,true,p_occurred_at,'Provider-verified START');end if;
    end if;
   end if;
  end if;
 end if;
 update public.communication_provider_events set state='processed',lease_token=null,lease_expires_at=null,last_error=null where id=event.id;
 return result;
end $$

create function public.complete_communication_status(p_event_id uuid,p_lease_token uuid) returns void language plpgsql security definer set search_path=public as $$
declare event public.communication_provider_events; outbound public.communication_outbox;
begin
 perform public.communication_require_service();select * into event from public.communication_provider_events where id=p_event_id for update;
 if not found or event.state<>'claimed' or event.lease_token is distinct from p_lease_token or event.event_type='inbound' then raise exception 'Provider event lease unavailable' using errcode='40001';end if;
 select * into outbound from public.communication_outbox where provider=event.provider and provider_message_id=event.resource_id for update;
 if not found then raise exception 'Provider receipt not correlated' using errcode='23503';end if;
 if event.event_type='delivered' then perform public.record_communication_delivery(event.provider,event.event_id,event.resource_id,'delivered');
 elsif event.event_type in ('failed','undelivered','bounced','complained') then
  perform public.record_communication_delivery(event.provider,event.event_id,event.resource_id,'failed');
  if event.event_type in ('bounced','complained') then
   insert into public.communication_suppressions(channel,recipient,reason) values(outbound.channel,outbound.recipient,'provider_'||event.event_type) on conflict on constraint communication_suppressions_pkey do nothing;
   update public.communication_outbox set delivery_failure_kind=case when delivery_failure_kind='complained' then 'complained' else event.event_type end where id=outbound.id;
   update public.communication_outbox set state='failed',last_error='recipient_suppressed' where channel=outbound.channel and recipient=outbound.recipient and state='pending';
  end if;
 end if;
 update public.communication_provider_events set state='processed',lease_token=null,lease_expires_at=null where id=event.id;
end $$

create function public.assign_inbound_communication(p_actor_id uuid,p_id uuid,p_expected_version integer,p_client_id uuid,p_conversation_id uuid,p_reason text) returns public.communication_inbound language plpgsql security definer set search_path=public as $$
declare actor uuid;result public.communication_inbound;message uuid;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into result from public.communication_inbound where id=p_id for update;
 if not found or result.version is distinct from p_expected_version or result.message_id is not null then raise exception 'Inbound review changed; reload' using errcode='40001';end if;
 if p_reason is null or length(trim(p_reason)) not between 5 and 1000 or not exists(select 1 from public.conversations where id=p_conversation_id and client_id=p_client_id) then raise exception 'Choose a conversation belonging to the selected household and provide a reason' using errcode='23514';end if;
 insert into public.messages(conversation_id,type,sender_type,content,is_internal) values(p_conversation_id,result.channel::public.message_type,'CLIENT',result.body,false) returning id into message;
 update public.communication_inbound set client_id=p_client_id,conversation_id=p_conversation_id,message_id=message,review_reason=null,version=version+1 where id=p_id returning * into result;
 insert into public.communication_inbound_assignments(inbound_id,client_id,conversation_id,assigned_by,reason) values(p_id,p_client_id,p_conversation_id,actor,p_reason);
 update public.conversations set last_message_at=now(),is_read=false where id=p_conversation_id;
 return result;
end $$

create function public.mark_conversation_read(p_actor_id uuid,p_conversation_id uuid,p_message_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid;message public.messages;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into message from public.messages where id=p_message_id and conversation_id=p_conversation_id;
 if not found then raise exception 'Message does not belong to conversation' using errcode='23514';end if;
 insert into public.conversation_read_cursors(user_id,conversation_id,read_at,message_id) values(actor,p_conversation_id,message.created_at,message.id)
 on conflict(user_id,conversation_id) do update set read_at=excluded.read_at,message_id=excluded.message_id where (conversation_read_cursors.read_at,conversation_read_cursors.message_id)<(excluded.read_at,excluded.message_id);
end $$

do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('receive_communication_event','claim_communication_event','release_communication_event','complete_inbound_communication','complete_communication_status','assign_inbound_communication','mark_conversation_read','list_communication_inbox') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('assign_inbound_communication','mark_conversation_read','list_communication_inbox') then execute format('grant execute on function %s to authenticated',f.signature);
  else execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

create function public.guard_inbound_message() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if exists(select 1 from public.communication_inbound where message_id=OLD.id) then
  if TG_OP='DELETE' then raise exception 'Received communication history cannot be deleted' using errcode='23514';end if;
  if (to_jsonb(NEW)-array['triage_priority','triage_confidence','triage_reason']) is distinct from (to_jsonb(OLD)-array['triage_priority','triage_confidence','triage_reason']) then raise exception 'Received communication content is immutable' using errcode='23514';end if;
 end if;
 return case when TG_OP='DELETE' then OLD else NEW end;
end $$

create function public.record_sms_consent(p_actor_id uuid,p_client_id uuid,p_phone text,p_opted_in boolean,p_method public.consent_method,p_details text,p_expected_updated_at timestamptz default null) returns public.sms_consent language plpgsql security definer set search_path=public as $$
declare actor uuid;normalized_phone text;latest timestamptz;result public.sms_consent;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 normalized_phone:=public.communication_recipient('SMS',p_phone);
 if normalized_phone is null or p_opted_in is null or p_method is null or p_method not in ('VERBAL','WRITTEN','WEB_FORM') or p_details is null or length(trim(p_details)) not between 5 and 1000 or not exists(select 1 from public.clients where id=p_client_id and public.communication_recipient('SMS',primary_phone)=normalized_phone) then raise exception 'Matching household number and documented consent method required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('SMS:'||normalized_phone,936));
 if p_opted_in and (select count(*) from public.clients where public.communication_recipient('SMS',primary_phone)=normalized_phone)<>1 then raise exception 'Shared phone numbers require separate consent review' using errcode='23514';end if;
 select max(updated_at) into latest from public.sms_consent where client_id=p_client_id and public.communication_recipient('SMS',phone_number)=normalized_phone;
 if latest is distinct from p_expected_updated_at then raise exception 'Consent changed; reload before saving' using errcode='40001';end if;
 insert into public.sms_consent(client_id,phone_number,opted_in,opted_in_at,opted_out_at,consent_method,consent_details)
 values(p_client_id,normalized_phone,p_opted_in,case when p_opted_in then now() else null end,case when not p_opted_in then now() else null end,p_method,trim(p_details))
 on conflict(client_id,phone_number) do update set opted_in=excluded.opted_in,opted_in_at=excluded.opted_in_at,opted_out_at=excluded.opted_out_at,consent_method=excluded.consent_method,consent_details=excluded.consent_details;
 update public.sms_consent set opted_in=p_opted_in,opted_in_at=case when p_opted_in then now() else null end,opted_out_at=case when not p_opted_in then now() else null end,consent_method=p_method,consent_details=trim(p_details)
 where client_id=p_client_id and public.communication_recipient('SMS',phone_number)=normalized_phone;
 if p_opted_in then
  delete from public.communication_suppressions where channel='SMS' and communication_suppressions.recipient=normalized_phone and reason='staff_sms_opt_out';
 else
  insert into public.communication_suppressions(channel,recipient,reason,created_by) values('SMS',normalized_phone,'staff_sms_opt_out',actor) on conflict(channel,recipient) do nothing;
  update public.communication_outbox set state='failed',last_error='recipient_suppressed' where channel='SMS' and communication_outbox.recipient=normalized_phone and state='pending';
 end if;
 select * into result from public.sms_consent where client_id=p_client_id and phone_number=normalized_phone;
 return result;
end $$

create function public.care_chart_guard() returns trigger language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();
begin
 if TG_OP='DELETE' then raise exception 'Care chart history cannot be deleted' using errcode='23514'; end if;
 if TG_OP='UPDATE' then
  if TG_TABLE_NAME not in ('patient_qol_records','patient_lesions') then raise exception 'Observations and corrections are append-only' using errcode='23514'; end if;
  NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.pet_id:=OLD.pet_id; NEW.version:=OLD.version+1;
 else NEW.created_by:=actor; NEW.created_at:=now(); end if;
 if TG_TABLE_NAME in ('patient_qol_records','patient_lesions') then NEW.updated_by:=actor; NEW.updated_at:=now(); end if;
 if TG_TABLE_NAME='patient_qol_records' then
  if TG_OP='UPDATE' then if OLD.status='signed' then raise exception 'Signed quality-of-life records are immutable; add an addendum' using errcode='23514'; end if; end if;
  if NEW.status='signed' then
   if length(trim(NEW.appetite||NEW.drinking||NEW.mobility||NEW.comfort||NEW.social_engagement||NEW.good_days||NEW.notes))=0 then raise exception 'Document observations before signing' using errcode='23514'; end if;
   NEW.signed_by:=actor; NEW.signed_at:=now();
  else NEW.signed_by:=null; NEW.signed_at:=null; end if;
 end if;
 return NEW;
end $$

do $$ declare t text; begin
 foreach t in array array['patient_qol_records','patient_qol_addenda','patient_lesions','patient_lesion_observations','patient_lesion_corrections'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,service_role',t);
  execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
  execute format('create trigger care_chart_guard before insert or update or delete on public.%I for each row execute function public.care_chart_guard()',t);
  execute format('create trigger care_chart_audit after insert or update on public.%I for each row execute function public.audit_trigger_fn()',t);
 end loop;
end $$

create function public.save_patient_qol(p_id uuid,p_pet_id uuid,p_expected_version integer,p_observed_at timestamptz,p_observer text,p_appetite text,p_drinking text,p_mobility text,p_comfort text,p_social_engagement text,p_good_days text,p_notes text) returns public.patient_qol_records language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_qol_records;
begin
 if p_observed_at is null or not isfinite(p_observed_at) or p_observed_at>now()+interval '5 minutes' then raise exception 'Invalid observation time' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.patient_qol_records where id=p_id for update;
 if found then
  if result.pet_id<>p_pet_id then raise exception 'Patient does not match chart' using errcode='23514'; end if;
  if (case when p_expected_version is null then result.created_by else result.updated_by end)=actor and result.version=coalesce(p_expected_version+1,1) and row(result.observed_at,result.observer,result.appetite,result.drinking,result.mobility,result.comfort,result.social_engagement,result.good_days,result.notes) is not distinct from row(p_observed_at,p_observer,p_appetite,p_drinking,p_mobility,p_comfort,p_social_engagement,p_good_days,p_notes) then return result; end if;
  if result.version is distinct from p_expected_version then raise exception 'Chart changed; reload before saving' using errcode='40001'; end if;
  update public.patient_qol_records set observed_at=p_observed_at,observer=p_observer,appetite=p_appetite,drinking=p_drinking,mobility=p_mobility,comfort=p_comfort,social_engagement=p_social_engagement,good_days=p_good_days,notes=p_notes where id=p_id returning * into result;
 else
  if p_expected_version is not null then raise exception 'Chart no longer exists' using errcode='40001'; end if;
  insert into public.patient_qol_records(id,pet_id,observed_at,observer,appetite,drinking,mobility,comfort,social_engagement,good_days,notes,created_by,updated_by) values(p_id,p_pet_id,p_observed_at,p_observer,p_appetite,p_drinking,p_mobility,p_comfort,p_social_engagement,p_good_days,p_notes,actor,actor) returning * into result;
 end if;
 return result;
end $$

create function public.sign_patient_qol(p_id uuid,p_expected_version integer) returns public.patient_qol_records language plpgsql security definer set search_path=public as $$
declare result public.patient_qol_records; actor uuid:=public.clinical_require_staff();
begin
 select * into result from public.patient_qol_records where id=p_id for update;
 if found and result.status='signed' and result.signed_by=actor and result.version=p_expected_version+1 then return result; end if;
 update public.patient_qol_records set status='signed' where id=p_id and version=p_expected_version returning * into result;
 if not found then raise exception 'Chart changed; reload before signing' using errcode='40001'; end if; return result;
end $$

create function public.add_patient_qol_addendum(p_id uuid,p_qol_id uuid,p_content text) returns public.patient_qol_addenda language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_qol_addenda;
begin
 perform 1 from public.patient_qol_records where id=p_qol_id and status='signed' for share;
 if not found then raise exception 'Addenda require a signed chart' using errcode='23514'; end if;
 insert into public.patient_qol_addenda(id,qol_id,content,created_by) values(p_id,p_qol_id,p_content,actor) on conflict(id) do nothing;
 select * into result from public.patient_qol_addenda where id=p_id;
 if result.created_by<>actor or (result.qol_id,result.content) is distinct from (p_qol_id,p_content) then raise exception 'Addendum identifier already used' using errcode='23514'; end if; return result;
end $$

create function public.record_lesion_observation(p_id uuid,p_lesion_id uuid,p_pet_id uuid,p_expected_version integer,p_observed_at timestamptz,p_label text,p_body_view text,p_x numeric,p_y numeric,p_length_mm numeric,p_width_mm numeric,p_depth_mm numeric,p_notes text,p_photo_document_id uuid) returns public.patient_lesion_observations language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_lesion_observations; lesion public.patient_lesions; fingerprint jsonb;
begin
 fingerprint:=jsonb_build_object('lesion_id',p_lesion_id,'pet_id',p_pet_id,'expected_version',p_expected_version,'observed_at',p_observed_at,'label',p_label,'body_view',p_body_view,'x',p_x,'y',p_y,'length_mm',p_length_mm,'width_mm',p_width_mm,'depth_mm',p_depth_mm,'notes',p_notes,'photo_document_id',p_photo_document_id);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.patient_lesion_observations where id=p_id;
 if found then if result.created_by<>actor or result.request<>fingerprint then raise exception 'Observation identifier already used' using errcode='23514'; end if; return result; end if;
 if p_observed_at is null or not isfinite(p_observed_at) or p_observed_at>now()+interval '5 minutes' then raise exception 'Invalid observation time' using errcode='23514'; end if;
 if p_photo_document_id is not null and not exists(select 1 from public.patient_documents where id=p_photo_document_id and pet_id=p_pet_id and status='ready' and mime_type in ('image/png','image/jpeg')) then raise exception 'Photo must be a ready image belonging to this patient' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_lesion_id::text,1));
 select * into lesion from public.patient_lesions where id=p_lesion_id for update;
 if found then
  if lesion.pet_id<>p_pet_id then raise exception 'Lesion does not belong to patient' using errcode='23514'; end if;
  if lesion.version is distinct from p_expected_version then raise exception 'Body map changed; reload before saving' using errcode='40001'; end if;
  update public.patient_lesions set label=p_label,body_view=p_body_view,x=p_x,y=p_y where id=p_lesion_id;
 else
  if p_expected_version is not null then raise exception 'Lesion no longer exists' using errcode='40001'; end if;
  insert into public.patient_lesions(id,pet_id,label,body_view,x,y,created_by,updated_by) values(p_lesion_id,p_pet_id,p_label,p_body_view,p_x,p_y,actor,actor);
 end if;
 insert into public.patient_lesion_observations(id,lesion_id,observed_at,label,body_view,x,y,length_mm,width_mm,depth_mm,notes,photo_document_id,request,created_by) values(p_id,p_lesion_id,p_observed_at,p_label,p_body_view,p_x,p_y,p_length_mm,p_width_mm,p_depth_mm,p_notes,p_photo_document_id,fingerprint,actor) returning * into result;
 return result;
end $$

create function public.correct_lesion_observation(p_id uuid,p_observation_id uuid,p_reason text) returns public.patient_lesion_corrections language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_lesion_corrections;
begin
 insert into public.patient_lesion_corrections(id,observation_id,reason,created_by) values(p_id,p_observation_id,p_reason,actor) on conflict(id) do nothing;
 select * into result from public.patient_lesion_corrections where id=p_id;
 if result.created_by<>actor or (result.observation_id,result.reason) is distinct from (p_observation_id,p_reason) then raise exception 'Correction identifier already used' using errcode='23514'; end if; return result;
end $$

