create function public.guard_conversation_history() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if TG_OP='DELETE' then raise exception 'Conversation history must be archived, not deleted' using errcode='23514';end if;
 if TG_OP='UPDATE' and NEW.client_id is distinct from OLD.client_id then raise exception 'Conversation household is immutable' using errcode='23514';end if;
 if TG_OP='INSERT' or NEW.status is distinct from OLD.status then
  perform pg_advisory_xact_lock(hashtextextended('conversation:'||NEW.client_id::text,950));
  if NEW.status='ACTIVE' and exists(select 1 from public.conversations where client_id=NEW.client_id and status='ACTIVE' and id<>NEW.id) then
   raise exception 'Household already has an active conversation' using errcode='23514';
  end if;
 end if;
 return NEW;
end $$

create function public.ensure_active_conversation(p_client_id uuid) returns public.conversations language plpgsql security definer set search_path=public as $$
declare actor uuid; result public.conversations; matches integer;
begin
 actor:=public.clinical_require_staff();
 perform pg_advisory_xact_lock(hashtextextended('conversation:'||p_client_id::text,950));
 if not exists(select 1 from public.clients where id=p_client_id) then raise exception 'Household not found' using errcode='23503';end if;
 select count(*) into matches from public.conversations where client_id=p_client_id and status='ACTIVE';
 if matches>1 then raise exception 'Select an existing conversation; household has multiple active threads' using errcode='23514';end if;
 select * into result from public.conversations where client_id=p_client_id and status='ACTIVE';
 if matches=0 then
  insert into public.conversations(client_id) values(p_client_id) returning * into result;
  insert into public.conversation_activity_audit(conversation_id,actor_id,action,after_value) values(result.id,actor,'created',to_jsonb(result));
 end if;
 return result;
end $$

create function public.update_conversation_metadata(p_actor_id uuid,p_conversation_id uuid,p_expected_revision integer,p_status public.conversation_status,p_assigned_to_id uuid,p_priority public.conversation_priority,p_tags text[]) returns public.conversations language plpgsql security definer set search_path=public as $$
declare actor uuid; original public.conversations; result public.conversations;
begin
 actor:=public.clinical_require_staff();
 if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into original from public.conversations where id=p_conversation_id;
 perform pg_advisory_xact_lock(hashtextextended('conversation:'||original.client_id::text,950));
 select * into original from public.conversations where id=p_conversation_id for update;
 if not found then raise exception 'Conversation not found' using errcode='23503';end if;
 if original.revision is distinct from p_expected_revision then raise exception 'Conversation changed; reload' using errcode='40001';end if;
 if p_status is null or p_priority is null or p_tags is null or cardinality(p_tags)>20 or exists(select 1 from unnest(p_tags)t where t is null or length(trim(t)) not between 1 and 40) then raise exception 'Invalid conversation metadata' using errcode='23514';end if;
 if p_assigned_to_id is not null and not public.is_active_staff(p_assigned_to_id) then raise exception 'Assignee must be active staff' using errcode='23514';end if;
 update public.conversations set status=p_status,assigned_to_id=p_assigned_to_id,priority=p_priority,
 tags=array(select distinct trim(t) from unnest(p_tags)t order by 1),revision=revision+1,
 archived_at=case when p_status='ARCHIVED' then coalesce(archived_at,now()) else null end
 where id=p_conversation_id returning * into result;
 insert into public.conversation_activity_audit(conversation_id,actor_id,action,before_value,after_value) values(result.id,actor,'metadata',to_jsonb(original),to_jsonb(result));
 return result;
end $$

create or replace function public.mark_conversation_read(p_actor_id uuid,p_conversation_id uuid,p_message_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid; message public.messages;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_conversation_id::text,951));
 select * into message from public.messages where id=p_message_id and conversation_id=p_conversation_id;
 if not found then raise exception 'Message does not belong to conversation' using errcode='23514';end if;
 insert into public.conversation_read_cursors(user_id,conversation_id,read_at,message_id) values(actor,p_conversation_id,message.created_at,message.id)
 on conflict(user_id,conversation_id) do update set read_at=excluded.read_at,message_id=excluded.message_id where (conversation_read_cursors.read_at,conversation_read_cursors.message_id)<(excluded.read_at,excluded.message_id);
 insert into public.conversation_unread_flags(user_id,conversation_id,forced) values(actor,p_conversation_id,false)
 on conflict(user_id,conversation_id) do update set forced=false,revision=conversation_unread_flags.revision+1;
end $$

create function public.mark_conversation_unread(p_actor_id uuid,p_conversation_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid;begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_conversation_id::text,951));
 insert into public.conversation_unread_flags(user_id,conversation_id,forced) values(actor,p_conversation_id,true)
 on conflict(user_id,conversation_id) do update set forced=true,revision=conversation_unread_flags.revision+1;
end $$

create function public.apply_inbox_read_snapshot(p_actor_id uuid,p_snapshot_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid;snapshot public.inbox_read_snapshots;b jsonb;current_revision bigint;begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into snapshot from public.inbox_read_snapshots where id=p_snapshot_id and user_id=actor for update;
 if not found or snapshot.created_at<now()-interval '15 minutes' then raise exception 'Read snapshot missing or expired' using errcode='23514';end if;
 if snapshot.applied_at is not null then return;end if;
 for b in select value from jsonb_array_elements(snapshot.boundaries) order by value->>'conversation' loop
  perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||(b->>'conversation'),951));
  select revision into current_revision from public.conversation_unread_flags where user_id=actor and conversation_id=(b->>'conversation')::uuid;
  if coalesce(current_revision,0)=(b->>'revision')::bigint then
   if b->>'message' is not null then
    perform public.mark_conversation_read(actor,(b->>'conversation')::uuid,(b->>'message')::uuid);
   else
    update public.conversation_unread_flags set forced=false,revision=revision+1 where user_id=actor and conversation_id=(b->>'conversation')::uuid;
   end if;
  end if;
 end loop;
 update public.inbox_read_snapshots set applied_at=now() where id=snapshot.id;
end $$

create function public.inbox_unread_totals() returns table(unread_conversations bigint,unread_messages bigint) language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 return query select count(*) filter(where is_unread),coalesce(sum(unread_count),0)::bigint from public.inbox_workspace_rows where status='ACTIVE';
end $$

do $$ declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and p.proname in ('guard_conversation_history','ensure_active_conversation','update_conversation_metadata','mark_conversation_read','mark_conversation_unread','capture_inbox_read_snapshot','apply_inbox_read_snapshot','list_inbox_workspace','inbox_unread_totals') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname<>'guard_conversation_history' then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$

-- Display the current number's consent and effective suppression together.
create function public.current_sms_consent(p_client_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare phone text; selected public.sms_consent; result jsonb;
begin
 perform public.clinical_require_staff();
 select public.communication_recipient('SMS',primary_phone) into phone from public.clients where id=p_client_id;
 if not found then raise exception 'Household not found' using errcode='P0002'; end if;
 select * into selected from public.sms_consent where client_id=p_client_id and public.communication_recipient('SMS',phone_number)=phone order by updated_at desc,id desc limit 1;
 result:=case when selected.id is null then jsonb_build_object('id',null,'client_id',p_client_id,'phone_number',phone,'opted_in',false,'updated_at',null) else to_jsonb(selected) end;
 return result || jsonb_build_object('can_message',phone is not null and not public.communication_is_suppressed('SMS',phone,p_client_id));
end $$

create function public.save_lab_due_template(p_id uuid,p_expected_version integer,p_name text,p_interval_days integer,p_active boolean,p_review_note text)
returns public.lab_due_templates language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.lab_due_templates;
begin
 actor=public.clinical_require_staff();
 if not exists(select 1 from public.user_roles where user_id=actor and role='ADMIN') then raise exception 'Active administrator required to review standard settings' using errcode='42501';end if;
 if p_id is null then raise exception 'Stable request ID required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,10));
 select * into r from public.lab_due_templates where id=p_id for update;
 if found then
  if r.updated_by=actor and r.name=trim(p_name) and r.interval_days=p_interval_days and r.active=p_active and r.review_note=trim(p_review_note) and r.version=coalesce(p_expected_version,0)+1 then return r;end if;
  if r.version is distinct from p_expected_version then raise exception 'Template version conflict; reload' using errcode='40001';end if;
  update public.lab_due_templates set name=trim(p_name),interval_days=p_interval_days,active=p_active,review_note=trim(p_review_note),version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;
 else
  if p_expected_version is not null then raise exception 'Template version conflict' using errcode='40001';end if;
  insert into public.lab_due_templates(id,name,interval_days,active,review_note,updated_by) values(p_id,trim(p_name),p_interval_days,p_active,trim(p_review_note),actor) returning * into r;
 end if;
 insert into public.lab_work_revisions(entity,entity_id,version,snapshot,reason,actor_id) values('template',r.id,r.version,to_jsonb(r),r.review_note,actor);
 return r;
end $$

create function public.save_patient_lab_order(p_id uuid,p_pet_id uuid,p_expected_version integer,p_values jsonb,p_correction_reason text)
returns public.patient_lab_orders language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.patient_lab_orders;n public.patient_lab_orders;t public.lab_due_templates;existed boolean;
begin
 actor=public.clinical_require_staff();
 if p_id is null or p_values is null or jsonb_typeof(p_values)<>'object' or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('test_name','status','due_date','collected_date','result_date','accession','notes','result_document_id','template_id','template_version','interval_days','interval_anchor','override_reason')) then raise exception 'Invalid lab order fields' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,11));
 select * into r from public.patient_lab_orders where id=p_id for update;existed=found;
 if existed and r.pet_id<>p_pet_id then raise exception 'Order belongs to another patient' using errcode='42501';end if;
 n=jsonb_populate_record(null::public.patient_lab_orders,p_values);
 n.test_name=trim(n.test_name);n.notes=coalesce(n.notes,'');n.accession=coalesce(n.accession,'');n.override_reason=coalesce(n.override_reason,'');
 -- Exact retry after an uncertain response returns its prior version without creating history twice.
 if existed and r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and exists(select 1 from public.lab_work_revisions where entity='order' and entity_id=r.id and version=r.version and reason=coalesce(trim(p_correction_reason),'')) and
  (to_jsonb(r)-array['id','pet_id','version','created_by','updated_by','created_at','updated_at'])=(to_jsonb(n)-array['id','pet_id','version','created_by','updated_by','created_at','updated_at']) then return r;end if;
 if existed and r.version is distinct from p_expected_version or not existed and p_expected_version is not null then raise exception 'Lab order version conflict; reload before saving' using errcode='40001';end if;
 if not exists(select 1 from public.pets where id=p_pet_id) then raise exception 'Patient not found' using errcode='23514';end if;
 if not existed and not exists(select 1 from public.pets where id=p_pet_id and archived_at is null and deceased_at is null) then raise exception 'New orders require an active patient' using errcode='23514';end if;
 if existed and (r.status in ('resulted','cancelled') or r.result_date is not null or r.result_document_id is not null) and nullif(trim(p_correction_reason),'') is null then raise exception 'Historical result changes require a correction reason' using errcode='23514';end if;
 if length(coalesce(p_correction_reason,''))>2000 then raise exception 'Correction reason too long' using errcode='23514';end if;
 if n.status in ('collected','resulted') and n.collected_date is null or n.status='resulted' and n.result_date is null then raise exception 'Record collection and result dates for this status' using errcode='23514';end if;
 if n.collected_date>(now() at time zone 'America/Denver')::date or n.result_date>(now() at time zone 'America/Denver')::date then raise exception 'Collection and result dates cannot be in the future' using errcode='23514';end if;
 if n.result_document_id is not null then
  perform 1 from public.patient_documents where id=n.result_document_id and pet_id=p_pet_id and status='ready' for share;
  if not found then raise exception 'Choose a ready document belonging to this patient' using errcode='42501';end if;
 end if;
 if n.template_id is not null then
  select * into t from public.lab_due_templates where id=n.template_id for share;
  -- Existing provenance remains valid when a reusable template is later revised/retired.
  if not (existed and row(r.template_id,r.template_version,r.interval_days,r.interval_anchor,r.due_date,r.override_reason) is not distinct from row(n.template_id,n.template_version,n.interval_days,n.interval_anchor,n.due_date,n.override_reason)) then
   if t.id is null or not t.active or t.version is distinct from n.template_version then raise exception 'Template changed or retired; review current settings' using errcode='40001';end if;
   if n.interval_days is distinct from t.interval_days and nullif(trim(n.override_reason),'') is null then raise exception 'Patient interval override requires a reason' using errcode='23514';end if;
  end if;
 elsif n.template_version is not null then raise exception 'Template version requires a template' using errcode='23514';end if;
 if n.interval_days is not null then
  if n.interval_anchor is null or not isfinite(n.interval_anchor) or n.due_date is distinct from n.interval_anchor+n.interval_days then raise exception 'Review interval anchor and due date' using errcode='23514';end if;
 elsif n.interval_anchor is not null or n.template_id is not null then raise exception 'Interval required' using errcode='23514';end if;
 if existed then
  update public.patient_lab_orders set test_name=n.test_name,status=n.status,due_date=n.due_date,collected_date=n.collected_date,result_date=n.result_date,accession=n.accession,notes=n.notes,result_document_id=n.result_document_id,template_id=n.template_id,template_version=n.template_version,interval_days=n.interval_days,interval_anchor=n.interval_anchor,override_reason=n.override_reason,version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;
 else
  insert into public.patient_lab_orders(id,pet_id,test_name,status,due_date,collected_date,result_date,accession,notes,result_document_id,template_id,template_version,interval_days,interval_anchor,override_reason,created_by,updated_by) values(p_id,p_pet_id,n.test_name,n.status,n.due_date,n.collected_date,n.result_date,n.accession,n.notes,n.result_document_id,n.template_id,n.template_version,n.interval_days,n.interval_anchor,n.override_reason,actor,actor) returning * into r;
 end if;
 insert into public.lab_work_revisions(entity,entity_id,version,snapshot,reason,actor_id) values('order',r.id,r.version,to_jsonb(r),coalesce(trim(p_correction_reason),''),actor);return r;
end $$

do $$ declare t text;begin foreach t in array array['lab_due_templates','patient_lab_orders','lab_work_revisions'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);
 execute format('grant select on table public.%I to authenticated',t);
 execute format('create policy "Active staff read lab tracking" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
end loop;end $$

create table public.anesthesia_record_revisions (
 id bigint generated always as identity primary key, record_id uuid not null references public.patient_anesthesia_records(id),version integer not null,snapshot jsonb not null,actor_id uuid not null references public.profiles(id),recorded_at timestamptz not null default now(),unique(record_id,version)
)

create table public.anesthesia_record_addenda (
 id uuid primary key, record_id uuid not null references public.patient_anesthesia_records(id),content text not null check(length(trim(content)) between 1 and 10000),actor_id uuid not null references public.profiles(id),recorded_at timestamptz not null default now()
)

create function public.anesthesia_validate(p_record public.patient_anesthesia_records) returns void language plpgsql set search_path=public as $$
declare item jsonb;observed timestamptz;
begin
 if p_record.started_at is null or not isfinite(p_record.started_at) or p_record.started_at>now()+interval '5 minutes' or p_record.ended_at>now()+interval '5 minutes' then raise exception 'Record finite procedure times no later than now' using errcode='23514';end if;
 if p_record.observations is null or jsonb_typeof(p_record.observations)<>'array' or jsonb_array_length(p_record.observations)>1000 or octet_length(p_record.observations::text)>500000 or p_record.events is null or jsonb_typeof(p_record.events)<>'array' or jsonb_array_length(p_record.events)>1000 or octet_length(p_record.events::text)>500000 then raise exception 'Invalid observation or event collection' using errcode='23514';end if;
 for item in select value from jsonb_array_elements(p_record.observations) loop
  if jsonb_typeof(item)<>'object' or exists(select 1 from jsonb_object_keys(item) k where k not in ('at','label','value','unit','notes')) or jsonb_typeof(item->'at') is distinct from 'string' or jsonb_typeof(item->'label') is distinct from 'string' or length(trim(item->>'label')) not between 1 and 120 or jsonb_typeof(item->'value') is distinct from 'number' or abs((item->>'value')::numeric)>1e100 or jsonb_typeof(item->'unit') is distinct from 'string' or length(trim(item->>'unit')) not between 1 and 60 or jsonb_typeof(item->'notes') is distinct from 'string' or length(item->>'notes')>2000 then raise exception 'Observations require a timestamp, label, finite value and explicit unit' using errcode='23514';end if;
  observed=(item->>'at')::timestamptz;
  if not isfinite(observed) or observed<p_record.started_at or observed>coalesce(p_record.ended_at,now()+interval '5 minutes') then raise exception 'Observation time must fall within the recorded procedure' using errcode='23514';end if;
 end loop;
 for item in select value from jsonb_array_elements(p_record.events) loop
  if jsonb_typeof(item)<>'object' or exists(select 1 from jsonb_object_keys(item) k where k not in ('at','kind','description')) or jsonb_typeof(item->'at') is distinct from 'string' or item->>'kind' is null or item->>'kind' not in ('medication','procedure','other') or jsonb_typeof(item->'description') is distinct from 'string' or length(trim(item->>'description')) not between 1 and 4000 then raise exception 'Events require a timestamp, type and documentary description' using errcode='23514';end if;
  observed=(item->>'at')::timestamptz;
  if not isfinite(observed) or observed<p_record.started_at or observed>coalesce(p_record.ended_at,now()+interval '5 minutes') then raise exception 'Event time must fall within the recorded procedure' using errcode='23514';end if;
 end loop;
end $$

create function public.save_patient_anesthesia_record(p_id uuid,p_pet_id uuid,p_expected_version integer,p_values jsonb) returns public.patient_anesthesia_records language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.patient_anesthesia_records;n public.patient_anesthesia_records;existed boolean;
begin
 actor=public.clinical_require_staff();
 if p_id is null or p_values is null or jsonb_typeof(p_values)<>'object' or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('procedure_name','started_at','ended_at','team','assessment','plan','recovery_notes','observations','events','source','source_description','original_document_id')) then raise exception 'Invalid anesthesia record fields' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,12));
 select * into r from public.patient_anesthesia_records where id=p_id for update;existed=found;
 if existed and r.pet_id<>p_pet_id then raise exception 'Anesthesia record belongs to another patient' using errcode='42501';end if;
 if existed and r.status<>'draft' then raise exception 'Signed anesthesia records are immutable; append a correction' using errcode='23514';end if;
 n=jsonb_populate_record(null::public.patient_anesthesia_records,p_values);
 n.procedure_name=trim(n.procedure_name);n.team=trim(n.team);n.assessment=coalesce(n.assessment,'');n.plan=coalesce(n.plan,'');n.recovery_notes=coalesce(n.recovery_notes,'');n.source_description=coalesce(n.source_description,'');n.observations=coalesce(n.observations,'[]');n.events=coalesce(n.events,'[]');
 if existed and r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and (to_jsonb(r)-array['id','pet_id','status','version','created_by','updated_by','created_at','updated_at','signed_by','signed_at'])=(to_jsonb(n)-array['id','pet_id','status','version','created_by','updated_by','created_at','updated_at','signed_by','signed_at']) then return r;end if;
 if existed and r.version is distinct from p_expected_version or not existed and p_expected_version is not null then raise exception 'Anesthesia record version conflict; reload' using errcode='40001';end if;
 if not exists(select 1 from public.pets where id=p_pet_id and (existed or (archived_at is null and deceased_at is null))) then raise exception 'New records require an active patient' using errcode='23514';end if;
 perform public.anesthesia_validate(n);
 if n.original_document_id is not null then perform 1 from public.patient_documents where id=n.original_document_id and pet_id=p_pet_id and status='ready' for share;if not found then raise exception 'Original file must be a ready document for this patient' using errcode='42501';end if;end if;
 if existed then
 update public.patient_anesthesia_records set procedure_name=n.procedure_name,started_at=n.started_at,ended_at=n.ended_at,team=n.team,assessment=n.assessment,plan=n.plan,recovery_notes=n.recovery_notes,observations=n.observations,events=n.events,source=n.source,source_description=n.source_description,original_document_id=n.original_document_id,version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;
 else
 insert into public.patient_anesthesia_records(id,pet_id,procedure_name,started_at,ended_at,team,assessment,plan,recovery_notes,observations,events,source,source_description,original_document_id,created_by,updated_by) values(p_id,p_pet_id,n.procedure_name,n.started_at,n.ended_at,n.team,n.assessment,n.plan,n.recovery_notes,n.observations,n.events,n.source,n.source_description,n.original_document_id,actor,actor) returning * into r;
 end if;return r;
end $$

create function public.sign_patient_anesthesia_record(p_id uuid,p_pet_id uuid,p_expected_version integer) returns public.patient_anesthesia_records language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.patient_anesthesia_records;
begin actor=public.clinical_require_staff();select * into strict r from public.patient_anesthesia_records where id=p_id for update;
 if r.pet_id<>p_pet_id then raise exception 'Anesthesia record belongs to another patient' using errcode='42501';end if;
 if r.status='signed' and r.signed_by=actor and r.version=p_expected_version+1 then return r;end if;
 if r.version is distinct from p_expected_version then raise exception 'Anesthesia record version conflict; reload' using errcode='40001';end if;
 if r.status<>'draft' then raise exception 'Record already signed' using errcode='23514';end if;
 if r.ended_at is null or nullif(trim(r.assessment),'') is null or nullif(trim(r.plan),'') is null then raise exception 'Record end time, assessment and plan before signing' using errcode='23514';end if;
 update public.patient_anesthesia_records set status='signed',signed_by=actor,signed_at=now(),version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;return r;
end $$

create function public.add_anesthesia_record_addendum(p_id uuid,p_record_id uuid,p_pet_id uuid,p_content text) returns public.anesthesia_record_addenda language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.anesthesia_record_addenda;c public.patient_anesthesia_records;
begin actor=public.clinical_require_staff();select * into strict c from public.patient_anesthesia_records where id=p_record_id for share;
 if c.pet_id<>p_pet_id then raise exception 'Anesthesia record belongs to another patient' using errcode='42501';end if;
 if c.status<>'signed' then raise exception 'Addenda require a signed record' using errcode='23514';end if;
 if p_id is null then raise exception 'Stable addendum ID required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,13));select * into r from public.anesthesia_record_addenda where id=p_id;
 if found then if r.record_id<>p_record_id or r.actor_id<>actor or r.content is distinct from trim(p_content) then raise exception 'Addendum retry changed' using errcode='42501';end if;return r;end if;
 insert into public.anesthesia_record_addenda(id,record_id,content,actor_id) values(p_id,p_record_id,trim(p_content),actor) returning * into r;return r;
end $$

do $$ declare t text;begin foreach t in array array['patient_anesthesia_records','anesthesia_record_revisions','anesthesia_record_addenda'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);execute format('grant select on table public.%I to authenticated',t);execute format('create policy "Active staff read anesthesia records" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
end loop;end $$

create function public.guard_prepared_request() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='DELETE' or NEW.request_id is distinct from OLD.request_id or NEW.actor_id is distinct from OLD.actor_id or NEW.scope is distinct from OLD.scope or NEW.payload is distinct from OLD.payload or NEW.created_at is distinct from OLD.created_at or OLD.state<>'prepared' then raise exception 'Prepared request history is immutable' using errcode='23514';end if;
 return NEW;
end $$

create function public.recover_message_request(p_actor_id uuid,p_scope text,p_request_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;prepared public.communication_prepared_requests;queued public.communication_outbox;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 if p_scope is null or p_scope !~ '^[A-Za-z0-9:_-]{1,200}$' then raise exception 'Invalid composer scope' using errcode='23514';end if;
 select * into prepared from public.communication_prepared_requests where actor_id=actor and scope=p_scope and ((p_request_id is not null and request_id=p_request_id) or (p_request_id is null and state='prepared'));
 if not found then return null;end if;
 select * into queued from public.communication_outbox where request_id=prepared.request_id and created_by=actor;
 return jsonb_build_object('request_id',prepared.request_id,'payload',prepared.payload,'status',prepared.state,
 'receipt',case when queued.id is null then null else jsonb_build_object('success',true,'queued',true,'outbox_id',queued.id,'message_id',queued.message_id,'state',queued.state) end);
end $$

create function public.prepare_message_request(p_actor_id uuid,p_request_id uuid,p_scope text,p_conversation_id uuid,p_channel text,p_recipient text,p_subject text,p_body text,p_attachment_ids uuid[] default '{}') returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;prepared public.communication_prepared_requests;payload jsonb;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 if p_request_id is null or p_scope is null or p_scope !~ '^[A-Za-z0-9:_-]{1,200}$' or public.communication_recipient(p_channel,p_recipient) is null or p_body is null or length(trim(p_body))<1 or (p_channel='EMAIL' and (p_subject is null or length(trim(p_subject)) not between 1 and 500 or length(p_body)>100000)) or (p_channel='SMS' and (coalesce(p_subject,'')<>'' or length(p_body)>1600)) or p_attachment_ids is null or cardinality(p_attachment_ids)<>0 then raise exception 'Invalid prepared message' using errcode='23514';end if;
 if not exists(select 1 from public.conversations where id=p_conversation_id) then raise exception 'Conversation not found' using errcode='23503';end if;
 payload:=jsonb_build_object('conversation_id',p_conversation_id,'channel',p_channel,'to',p_recipient,'subject',coalesce(p_subject,''),'body',p_body,'attachment_ids',to_jsonb(p_attachment_ids));
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,914));
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_scope,1200));
 select * into prepared from public.communication_prepared_requests where request_id=p_request_id;
 if found then
  if prepared.actor_id is distinct from actor or prepared.scope is distinct from p_scope or prepared.payload is distinct from payload or prepared.state='abandoned' then raise exception 'Request already used or abandoned' using errcode='23505';end if;
 else
  if exists(select 1 from public.communication_prepared_requests where actor_id=actor and scope=p_scope and state='prepared') then raise exception 'Composer has an unresolved prepared request' using errcode='23505';end if;
  insert into public.communication_prepared_requests(request_id,actor_id,scope,payload,state) values(p_request_id,actor,p_scope,payload,'prepared');
 end if;
 return public.recover_message_request(actor,p_scope,p_request_id);
end $$

create function public.enqueue_communication(p_actor_id uuid,p_request_id uuid,p_conversation_id uuid,p_channel text,p_recipient text,p_subject text,p_body text,p_attachment_ids uuid[] default '{}') returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid;prepared public.communication_prepared_requests;payload jsonb;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,914));
 select * into prepared from public.communication_prepared_requests where request_id=p_request_id;
 if not found or prepared.actor_id is distinct from actor or prepared.state='abandoned' then raise exception 'Prepare this request before enqueueing' using errcode='42501';end if;
 payload:=jsonb_build_object('conversation_id',p_conversation_id,'channel',p_channel,'to',p_recipient,'subject',coalesce(p_subject,''),'body',p_body,'attachment_ids',to_jsonb(p_attachment_ids));
 if prepared.payload is distinct from payload then raise exception 'Prepared content cannot change' using errcode='23505';end if;
 return public.enqueue_prepared_communication_internal(actor,p_request_id,p_conversation_id,p_channel,p_recipient,p_subject,p_body,p_attachment_ids);
end $$

create function public.resolve_message_request(p_actor_id uuid,p_request_id uuid,p_scope text,p_abandon boolean default false) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;prepared public.communication_prepared_requests;queued boolean;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 if p_request_id is null or p_scope is null or p_scope !~ '^[A-Za-z0-9:_-]{1,200}$' or p_abandon is null then raise exception 'Invalid recovery request' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,914));
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_scope,1200));
 select * into prepared from public.communication_prepared_requests where request_id=p_request_id;
 if found and (prepared.actor_id is distinct from actor or prepared.scope is distinct from p_scope) then raise exception 'Request ownership mismatch' using errcode='42501';end if;
 select exists(select 1 from public.communication_outbox where request_id=p_request_id and created_by=actor) into queued;
 if prepared.request_id is null then
  if not p_abandon then raise exception 'No queued request to acknowledge' using errcode='23514';end if;
  insert into public.communication_prepared_requests(request_id,actor_id,scope,state,resolved_at) values(p_request_id,actor,p_scope,'abandoned',now());
 elsif prepared.state='prepared' then
  if not queued and not p_abandon then raise exception 'No queued request to acknowledge' using errcode='23514';end if;
  update public.communication_prepared_requests set state=case when queued then 'acknowledged' else 'abandoned' end,resolved_at=now() where request_id=p_request_id;
 end if;
 return public.recover_message_request(actor,p_scope,p_request_id);
end $$

do $$ declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('guard_prepared_request','recover_message_request','prepare_message_request','enqueue_communication','resolve_message_request') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname<>'guard_prepared_request' then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$

do $$ declare t text; begin
 foreach t in array array['record_release_policy','record_releases','record_release_sources','record_release_events'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,service_role',t);
  execute format('create policy "Active staff read releases" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
  if t<>'record_release_policy' then
   execute format('create trigger release_immutable before update or delete on public.%I for each row execute function public.record_release_immutable()',t);
   execute format('create trigger release_audit after insert on public.%I for each row execute function public.audit_trigger_fn()',t);
  end if;
 end loop;
end $$

create function public.preview_record_release(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare pet public.pets; owner public.clients; selected uuid; k text; ids jsonb; e public.clinical_encounters; c public.vaccine_certificates; l public.patient_lab_orders; d public.patient_documents; soaps jsonb:='[]'; certs jsonb:='[]'; labs jsonb:='[]'; docs jsonb:='[]'; snapshot jsonb; recipient text; count_selected integer:=0;
begin
 perform public.clinical_require_staff();
 if p_selection is null or jsonb_typeof(p_selection)<>'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f not in ('encounter_ids','certificate_ids','lab_order_ids','document_ids')) then raise exception 'Choose explicit release sources' using errcode='23514'; end if;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids'] loop
  ids:=coalesce(p_selection->k,'[]');
  if jsonb_typeof(ids)<>'array' or jsonb_array_length(ids)>100 then raise exception 'Each source selection must be an array of at most 100 IDs' using errcode='23514'; end if;
  if exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string') or (select count(*) from jsonb_array_elements_text(ids))<>(select count(distinct v::uuid) from jsonb_array_elements_text(ids) v) then raise exception 'Source IDs must be unique strings' using errcode='23514'; end if;
  count_selected:=count_selected+jsonb_array_length(ids);
 end loop;
 if count_selected=0 then raise exception 'Choose at least one source; nothing is included by default' using errcode='23514'; end if;
 select * into pet from public.pets where id=p_pet_id and client_id=p_client_id for share;
 if not found then raise exception 'Patient does not belong to this household' using errcode='42501'; end if;
 select * into owner from public.clients where id=p_client_id for share;
 recipient:=public.communication_recipient(p_channel,p_recipient);
 if p_channel is null or p_channel not in ('EMAIL','SMS') or recipient is null or recipient is distinct from public.communication_recipient(p_channel,case when p_channel='EMAIL' then owner.primary_email else owner.primary_phone end) then raise exception 'Recipient must match the selected patient household contact' using errcode='42501'; end if;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'encounter_ids','[]')) v order by v loop
  select * into e from public.clinical_encounters where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed encounters from this patient can be released' using errcode='23514'; end if;
  soaps:=soaps||jsonb_build_array(jsonb_build_object('id',e.id,'version',e.version,'visit_at',e.visit_at,'visit_type',e.visit_type,'subjective',e.subjective,'objective',e.objective,'assessment',e.assessment,'plan',e.plan,'signed_by',e.signed_by,'signed_at',e.signed_at,'addenda',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'content',a.content,'created_by',a.created_by,'created_at',a.created_at) order by a.created_at,a.id) from public.clinical_addenda a where a.encounter_id=e.id),'[]'::jsonb)));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'certificate_ids','[]')) v order by v loop
  select * into c from public.vaccine_certificates where id=selected and pet_id=p_pet_id for update;
  if not found or exists(select 1 from public.vaccine_certificate_events where certificate_id=selected) then raise exception 'Certificate is unavailable, belongs to another patient or is invalidated' using errcode='23514'; end if;
  certs:=certs||jsonb_build_array(to_jsonb(c)-array['request']);
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'lab_order_ids','[]')) v order by v loop
  select * into l from public.patient_lab_orders where id=selected and pet_id=p_pet_id and status='resulted' for update;
  if not found then raise exception 'Only resulted laboratory records from this patient can be released' using errcode='23514'; end if;
  if l.result_document_id is null or not exists(select 1 from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v where v::uuid=l.result_document_id) then raise exception 'Select the lab original report explicitly as a shareable attachment' using errcode='23514'; end if;
  labs:=labs||jsonb_build_array(jsonb_build_object('id',l.id,'version',l.version,'test_name',l.test_name,'accession',l.accession,'collected_date',l.collected_date,'result_date',l.result_date,'result_document_id',l.result_document_id));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v order by v loop
  select * into d from public.patient_documents where id=selected and pet_id=p_pet_id and status='ready' and visibility='client_shareable' for update;
  if not found then raise exception 'Only ready client-shareable documents from this patient can be released' using errcode='23514'; end if;
  if not exists(select 1 from storage.objects where bucket_id='patient-documents' and name=d.file_path and metadata->>'size'=d.file_size::text and metadata->>'mimetype'=d.mime_type) then raise exception 'Original document object is unavailable or metadata differs' using errcode='23514'; end if;
  docs:=docs||jsonb_build_array(jsonb_build_object('id',d.id,'version',d.version,'file_name',d.file_name,'file_path',d.file_path,'bucket','patient-documents','mime_type',d.mime_type,'file_size',d.file_size,'document_date',d.document_date,'category',d.category));
 end loop;
 snapshot:=jsonb_build_object('schema_version',1,'patient',jsonb_build_object('id',pet.id,'version',pet.version,'name',pet.name,'species',pet.species,'breed',pet.breed,'dob',pet.dob,'birth_date_precision',pet.birth_date_precision,'microchip_id',pet.microchip_id),'recipient',jsonb_build_object('client_id',owner.id,'client_version',owner.version,'name',owner.full_name,'channel',p_channel,'address',recipient),'encounters',soaps,'certificates',certs,'lab_results',labs,'attachments',docs);
 return jsonb_build_object('snapshot',snapshot,'source_hash',encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';
end $$

create function public.confirm_record_release(p_id uuid,p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb,p_reviewed_snapshot jsonb,p_reviewed_hash text,p_attest_review boolean) returns public.record_releases language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.record_releases; preview jsonb; req jsonb; k text; source_type text;
begin
 if p_id is null or p_attest_review is distinct from true then raise exception 'Stable ID and explicit content/recipient review are required' using errcode='23514'; end if;
 req:=jsonb_build_object('pet_id',p_pet_id,'client_id',p_client_id,'channel',p_channel,'recipient',p_recipient,'selection',p_selection,'reviewed_snapshot',p_reviewed_snapshot,'reviewed_hash',p_reviewed_hash,'attest_review',p_attest_review);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,13));
 select * into result from public.record_releases where id=p_id;
 if found then if result.created_by<>actor or result.request is distinct from req then raise exception 'Release identifier already used' using errcode='23514'; end if; return result; end if;
 perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() for share;
 if not found then raise exception 'Clinical acceptance of the release form and workflow is required before confirmation' using errcode='42501'; end if;
 preview:=public.preview_record_release(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);
 if preview->'snapshot' is distinct from p_reviewed_snapshot or preview->>'source_hash' is distinct from p_reviewed_hash then raise exception 'Release sources or recipient changed; preview and review again' using errcode='40001'; end if;
 insert into public.record_releases(id,pet_id,client_id,channel,recipient,selection,snapshot,source_hash,request,created_by) values(p_id,p_pet_id,p_client_id,p_channel,preview#>>'{snapshot,recipient,address}',p_selection,p_reviewed_snapshot,p_reviewed_hash,req,actor) returning * into result;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids'] loop
  source_type:=case k when 'encounter_ids' then 'encounter' when 'certificate_ids' then 'certificate' when 'lab_order_ids' then 'lab' else 'document' end;
  insert into public.record_release_sources(release_id,source_kind,source_id) select p_id,source_type,v::uuid from jsonb_array_elements_text(coalesce(p_selection->k,'[]')) v;
 end loop;
 return result;
end $$

-- Locks coordinate source writers with preview/confirm to prevent missed invalidations.
create function public.release_lock_source_parent() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if TG_TABLE_NAME='clinical_addenda' then perform 1 from public.clinical_encounters where id=NEW.encounter_id for update;
 else perform 1 from public.vaccine_certificates where id=NEW.certificate_id for update; end if;
 return NEW;
end $$

create function public.invalidate_record_release_source() returns trigger language plpgsql security definer set search_path=public as $$
declare source_type text; source uuid;
begin
 case TG_TABLE_NAME
 when 'clinical_addenda' then source_type:='encounter';source:=NEW.encounter_id;
 when 'vaccine_certificate_events' then source_type:='certificate';source:=NEW.certificate_id;
 when 'patient_lab_orders' then source_type:='lab';source:=NEW.id;
 when 'patient_documents' then source_type:='document';source:=NEW.id;
 when 'pets' then source_type:='patient';source:=NEW.id;
 when 'clients' then source_type:='household';source:=NEW.id;
 end case;
 insert into public.record_release_events(id,release_id,kind,reason,created_by)
 select gen_random_uuid(),r.id,'source_changed','Reviewed '||source_type||' changed; prepare a fresh package',auth.uid() from public.record_releases r where (source_type='patient' and r.pet_id=source) or (source_type='household' and r.client_id=source) or exists(select 1 from public.record_release_sources s where s.release_id=r.id and s.source_kind=source_type and s.source_id=source);
 return NEW;
end $$

create function public.withdraw_record_release(p_id uuid,p_release_id uuid,p_reason text) returns public.record_release_events language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.record_release_events;
begin
 if p_id is null or length(trim(coalesce(p_reason,''))) not between 1 and 2000 then raise exception 'Withdrawal reason required' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,13));
 select * into result from public.record_release_events where id=p_id;
 if found then if row(result.release_id,result.kind,result.reason,result.created_by) is distinct from row(p_release_id,'withdrawn'::text,trim(p_reason),actor) then raise exception 'Withdrawal ID already used' using errcode='23514'; end if;return result;end if;
 perform 1 from public.record_releases where id=p_release_id for update;
 if not found then raise exception 'Release not found' using errcode='23514'; end if;
 insert into public.record_release_events(id,release_id,kind,reason,created_by) values(p_id,p_release_id,'withdrawn',trim(p_reason),actor) returning * into result;
 return result;
end $$

create function public.read_record_release(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.record_releases; events jsonb; eligible boolean:=true; why text; current_preview jsonb;
begin
 perform public.clinical_require_staff();
 select * into r from public.record_releases where id=p_id for share;
 if not found then raise exception 'Release not found' using errcode='23514'; end if;
 select coalesce(jsonb_agg(to_jsonb(e) order by created_at,id),'[]') into events from public.record_release_events e where release_id=p_id;
 if jsonb_array_length(events)>0 then eligible:=false;why:='Withdrawn or a reviewed source changed';
 else
  begin
   current_preview:=public.preview_record_release(r.pet_id,r.client_id,r.channel,r.recipient,r.selection);
   if current_preview->>'source_hash'<>r.source_hash then eligible:=false;why:='Current source snapshot differs';end if;
  exception when sqlstate '23514' or sqlstate '42501' then eligible:=false;why:='Source or recipient is no longer eligible';end;
 end if;
 return jsonb_build_object('release',to_jsonb(r)-'request','events',events,'eligible',eligible,'ineligibility_reason',why);
end $$

-- Future transport must authorize a package, never accept arbitrary document IDs.
-- This is not granted to workers: a separately reviewed outbox adapter must revalidate
-- consent/suppression, recipient, content, attachment sizes and delivery state at send time.
create function public.authorize_record_release(p_id uuid,p_client_id uuid,p_channel text,p_recipient text) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() for share;
 if not found then raise exception 'Clinical release acceptance is not active' using errcode='42501';end if;
 result:=public.read_record_release(p_id);
 if (result->>'eligible')::boolean is distinct from true or result#>>'{release,client_id}' is distinct from p_client_id::text or result#>>'{release,channel}' is distinct from p_channel or result#>>'{release,recipient}' is distinct from public.communication_recipient(p_channel,p_recipient) then raise exception 'Release is not eligible for this household recipient' using errcode='42501';end if;
 return result;
end $$

create function public.record_release_policy_audit() returns trigger language plpgsql security definer set search_path=public as $$
begin
 insert into public.audit_logs(user_id,action,table_name,record_id,old_data,new_data) values(auth.uid(),TG_OP,TG_TABLE_NAME,md5('public.record_release_policy:singleton')::uuid,case when TG_OP in ('UPDATE','DELETE') then to_jsonb(OLD) end,case when TG_OP in ('INSERT','UPDATE') then to_jsonb(NEW) end);
 return coalesce(NEW,OLD);
end $$

