 id bigint generated always as identity primary key,entity text not null check(entity in ('vaccine_template','vaccine_plan','message_template')),entity_id uuid not null,version integer not null,snapshot jsonb not null,actor_id uuid not null references public.profiles(id),recorded_at timestamptz not null default now(),unique(entity,entity_id,version)
)

create function public.save_vaccine_due_template(p_id uuid,p_expected_version integer,p_group_key text,p_name text,p_product_ids uuid[],p_interval_days integer,p_active boolean,p_review_note text) returns public.vaccine_due_templates language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.vaccine_due_templates;
begin actor=public.care_require_admin();if p_id is null then raise exception 'Stable ID required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,14));select * into r from public.vaccine_due_templates where id=p_id for update;
 if found then
  if r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and row(r.group_key,r.name,r.product_ids,r.interval_days,r.active,r.review_note) is not distinct from row(lower(trim(p_group_key)),trim(p_name),p_product_ids,p_interval_days,p_active,trim(p_review_note)) then return r;end if;
  if r.version is distinct from p_expected_version then raise exception 'Vaccine template version conflict' using errcode='40001';end if;
  if r.group_key<>lower(trim(p_group_key)) then raise exception 'Canonical group key is immutable' using errcode='23514';end if;
 elsif p_expected_version is not null then raise exception 'Vaccine template version conflict' using errcode='40001';end if;
 if p_product_ids is null or exists(select 1 from unnest(p_product_ids) id where not exists(select 1 from public.catalog_products p where p.id=id and p.kind='vaccine')) or cardinality(p_product_ids)<>(select count(distinct id) from unnest(p_product_ids) id) then raise exception 'Choose distinct explicit vaccine products' using errcode='23514';end if;
 if r.id is null then insert into public.vaccine_due_templates(id,group_key,name,product_ids,interval_days,active,review_note,updated_by) values(p_id,lower(trim(p_group_key)),trim(p_name),p_product_ids,p_interval_days,p_active,trim(p_review_note),actor) returning * into r;
 else update public.vaccine_due_templates set name=trim(p_name),product_ids=p_product_ids,interval_days=p_interval_days,active=p_active,review_note=trim(p_review_note),version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;end if;return r;
end $$

create function public.save_patient_vaccine_due_plan(p_id uuid,p_pet_id uuid,p_expected_version integer,p_template_id uuid,p_template_version integer,p_product_id uuid,p_treatment_id uuid,p_last_administered_on date,p_anchor_source text,p_interval_days integer,p_current_due_on date,p_status text,p_reminders_enabled boolean,p_override_reason text,p_review_note text) returns public.patient_vaccine_due_plans language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.patient_vaccine_due_plans;t public.vaccine_due_templates;admin_date date;proposed date;reviewed_snapshot jsonb;
begin actor=public.clinical_require_staff();if p_id is null then raise exception 'Stable ID required' using errcode='23514';end if;
 -- Patient lock serializes canonical-plan creation, archival, and service enqueue.
 perform 1 from public.pets where id=p_pet_id and archived_at is null and deceased_at is null for update;if not found then raise exception 'Due plans require an active patient' using errcode='23514';end if;
 select * into r from public.patient_vaccine_due_plans where id=p_id for update;
 if r.id is not null and r.pet_id<>p_pet_id then raise exception 'Due plan belongs to another patient' using errcode='42501';end if;
 if r.id is not null and r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and row(r.template_id,r.template_version,r.product_id,r.treatment_id,r.last_administered_on,r.anchor_source,r.interval_days,r.current_due_on,r.status,r.reminders_enabled,r.override_reason,r.review_note) is not distinct from row(p_template_id,p_template_version,p_product_id,p_treatment_id,p_last_administered_on,trim(p_anchor_source),p_interval_days,p_current_due_on,p_status,p_reminders_enabled,coalesce(trim(p_override_reason),''),trim(p_review_note)) then return r;end if;
 if r.id is not null and r.version is distinct from p_expected_version or r.id is null and p_expected_version is not null then raise exception 'Due plan version conflict' using errcode='40001';end if;
 if r.status='retired' then raise exception 'Retired plan is immutable; create a new reviewed plan' using errcode='23514';end if;
 select * into t from public.vaccine_due_templates where id=p_template_id for share;
 -- Existing reviewed snapshots survive later template changes. Reapplying settings needs the latest active version.
 if r.id is not null and row(r.template_id,r.template_version) is not distinct from row(p_template_id,p_template_version) then reviewed_snapshot=r.template_snapshot;
 else if t.id is null or not t.active or t.version is distinct from p_template_version then raise exception 'Template changed or retired; review current settings' using errcode='40001';end if;reviewed_snapshot=to_jsonb(t);end if;
 if r.id is not null and r.group_key<>t.group_key then raise exception 'Plan cannot change canonical vaccine group' using errcode='23514';end if;
 if not exists(select 1 from jsonb_array_elements_text(reviewed_snapshot->'product_ids') item where item::uuid=p_product_id) then raise exception 'Product is not explicitly mapped to this reviewed group' using errcode='23514';end if;
 if p_treatment_id is not null then
  select (administered_at at time zone 'America/Denver')::date into admin_date from public.patient_treatments where id=p_treatment_id and pet_id=p_pet_id and kind='vaccine' and product_id=p_product_id for share;
  if not found or exists(select 1 from public.patient_treatment_corrections where treatment_id=p_treatment_id) then raise exception 'Select an uncorrected vaccine administration for this patient and product' using errcode='42501';end if;
  if admin_date is distinct from p_last_administered_on then raise exception 'Last-administered date must match the selected administration in Denver' using errcode='23514';end if;
 end if;
 if p_last_administered_on is null or not isfinite(p_last_administered_on) or p_last_administered_on>(now() at time zone 'America/Denver')::date or p_current_due_on is null or not isfinite(p_current_due_on) then raise exception 'Record finite dates and a nonfuture administration date' using errcode='23514';end if;
 proposed=p_last_administered_on+(reviewed_snapshot->>'interval_days')::integer;
 if (p_interval_days is distinct from (reviewed_snapshot->>'interval_days')::integer or p_current_due_on is distinct from p_last_administered_on+p_interval_days) and nullif(trim(p_override_reason),'') is null then raise exception 'Patient due/interval override requires a reason' using errcode='23514';end if;
 if r.id is null then insert into public.patient_vaccine_due_plans(id,pet_id,template_id,template_version,template_snapshot,group_key,product_id,treatment_id,last_administered_on,anchor_source,interval_days,proposed_due_on,current_due_on,status,reminders_enabled,override_reason,review_note,created_by,updated_by) values(p_id,p_pet_id,p_template_id,p_template_version,reviewed_snapshot,t.group_key,p_product_id,p_treatment_id,p_last_administered_on,trim(p_anchor_source),p_interval_days,proposed,p_current_due_on,p_status,p_reminders_enabled,coalesce(trim(p_override_reason),''),trim(p_review_note),actor,actor) returning * into r;
 else update public.patient_vaccine_due_plans set template_id=p_template_id,template_version=p_template_version,template_snapshot=reviewed_snapshot,product_id=p_product_id,treatment_id=p_treatment_id,last_administered_on=p_last_administered_on,anchor_source=trim(p_anchor_source),interval_days=p_interval_days,proposed_due_on=proposed,current_due_on=p_current_due_on,status=p_status,reminders_enabled=p_reminders_enabled,override_reason=coalesce(trim(p_override_reason),''),review_note=trim(p_review_note),version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;end if;return r;
end $$

create function public.save_care_message_template(p_id uuid,p_expected_version integer,p_name text,p_channel text,p_days_before integer,p_body text,p_active boolean,p_review_note text) returns public.care_message_templates language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.care_message_templates;remainder text;
begin actor=public.care_require_admin();if p_id is null then raise exception 'Stable ID required' using errcode='23514';end if;
 remainder=replace(replace(replace(p_body,'{{patient_name}}',''),'{{care_name}}',''),'{{due_date}}','');if remainder~'[{}]' then raise exception 'Only patient_name, care_name and due_date placeholders are supported' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,15));select * into r from public.care_message_templates where id=p_id for update;
 if found then
  if r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and row(r.name,r.channel,r.days_before,r.body,r.active,r.review_note) is not distinct from row(trim(p_name),p_channel,p_days_before,p_body,p_active,trim(p_review_note)) then return r;end if;
  if r.version is distinct from p_expected_version then raise exception 'Message template version conflict' using errcode='40001';end if;
 elsif p_expected_version is not null then raise exception 'Message template version conflict' using errcode='40001';end if;
 if r.id is null then insert into public.care_message_templates(id,name,channel,days_before,body,active,review_note,updated_by) values(p_id,trim(p_name),p_channel,p_days_before,p_body,p_active,trim(p_review_note),actor) returning * into r;
 else update public.care_message_templates set name=trim(p_name),channel=p_channel,days_before=p_days_before,body=p_body,active=p_active,review_note=trim(p_review_note),version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;end if;return r;
end $$

create function public.care_invalidate_jobs() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if tg_table_name='patient_vaccine_due_plans' then update public.care_reminder_jobs set status='invalidated',invalidated_at=now(),invalidation_reason='Vaccine plan revised or retired' where source_kind='vaccine' and source_id=new.id and status='pending';
 elsif tg_table_name='patient_lab_orders' then update public.care_reminder_jobs set status='invalidated',invalidated_at=now(),invalidation_reason='Lab order revised or cancelled' where source_kind='lab' and source_id=new.id and status='pending';
 elsif tg_table_name='care_message_templates' then update public.care_reminder_jobs set status='invalidated',invalidated_at=now(),invalidation_reason='Approved message template revised or retired' where message_template_id=new.id and status='pending';
 elsif tg_table_name='pets' and row(new.archived_at,new.deceased_at,new.client_id,new.name) is distinct from row(old.archived_at,old.deceased_at,old.client_id,old.name) then update public.care_reminder_jobs set status='invalidated',invalidated_at=now(),invalidation_reason='Patient status, household or name changed' where pet_id=new.id and status='pending';
 end if;return new;
end $$

create function public.enqueue_care_reminder(p_id uuid,p_source_kind text,p_source_id uuid,p_expected_source_version integer,p_message_template_id uuid,p_expected_template_version integer) returns public.care_reminder_jobs language plpgsql security definer set search_path=public as $$
declare r public.care_reminder_jobs;t public.care_message_templates;p public.pets;v public.patient_vaccine_due_plans;l public.patient_lab_orders;patient_id uuid;due date;care_name text;snapshot jsonb;body text;part record;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service enqueue only' using errcode='42501';end if;
 if p_id is null then raise exception 'Stable job ID required' using errcode='23514';end if;
 if p_source_kind='vaccine' then select pet_id into patient_id from public.patient_vaccine_due_plans where id=p_source_id;
 elsif p_source_kind='lab' then select pet_id into patient_id from public.patient_lab_orders where id=p_source_id;
 else raise exception 'Unsupported reminder source' using errcode='23514';end if;
 select * into p from public.pets where id=patient_id and archived_at is null and deceased_at is null for share;if not found then raise exception 'Reminder requires an active patient' using errcode='23514';end if;
 if p_source_kind='vaccine' then
  select * into v from public.patient_vaccine_due_plans where id=p_source_id for share;
  if v.version is distinct from p_expected_source_version or v.status<>'current' or not v.reminders_enabled or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.treatment_id) then raise exception 'Vaccine due source is not current or enabled' using errcode='40001';end if;
  due=v.current_due_on;care_name=v.template_snapshot->>'name';snapshot=to_jsonb(v);
 else
  select * into l from public.patient_lab_orders where id=p_source_id for share;
  if l.version is distinct from p_expected_source_version or l.status not in ('planned','ordered') or l.due_date is null then raise exception 'Lab due source is not current' using errcode='40001';end if;
  due=l.due_date;care_name=l.test_name;snapshot=to_jsonb(l);
 end if;
 select * into t from public.care_message_templates where id=p_message_template_id for share;
 if t.id is null or not t.active or t.version is distinct from p_expected_template_version then raise exception 'Message template changed or retired' using errcode='40001';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,16));
 select * into r from public.care_reminder_jobs where id=p_id;
 if found then if row(r.source_kind,r.source_id,r.source_version,r.message_template_id,r.message_template_version) is distinct from row(p_source_kind,p_source_id,p_expected_source_version,p_message_template_id,p_expected_template_version) then raise exception 'Job ID reused with changed request' using errcode='42501';end if;return r;end if;
 -- A separate stable request ID for the same source/template version still returns the one canonical job.
 perform pg_advisory_xact_lock(hashtextextended(p_source_kind||p_source_id::text||p_expected_source_version::text||p_message_template_id::text||p_expected_template_version::text,17));
 select * into r from public.care_reminder_jobs where source_kind=p_source_kind and source_id=p_source_id and source_version=p_expected_source_version and message_template_id=p_message_template_id and message_template_version=p_expected_template_version;if found then return r;end if;
 body='';for part in select m[1] as token from regexp_matches(t.body,'(\{\{patient_name\}\}|\{\{care_name\}\}|\{\{due_date\}\}|[^{}]+)','g') m loop body=body||case part.token when '{{patient_name}}' then p.name when '{{care_name}}' then care_name when '{{due_date}}' then due::text else part.token end;end loop;
 insert into public.care_reminder_jobs(id,source_kind,source_id,source_version,pet_id,client_id,message_template_id,message_template_version,channel,scheduled_on,due_on,rendered_body,source_snapshot,template_snapshot) values(p_id,p_source_kind,p_source_id,p_expected_source_version,p.id,p.client_id,t.id,t.version,t.channel,due-t.days_before,due,body,snapshot,to_jsonb(t)) returning * into r;return r;
end $$

do $$ declare t text;begin foreach t in array array['vaccine_due_templates','patient_vaccine_due_plans','care_message_templates','care_plan_revisions','care_reminder_jobs'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);execute format('grant select on table public.%I to authenticated',t);execute format('create policy "Active staff read due plans and unsent reminders" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
end loop;end $$

-- Keyset candidate discovery for a future server scheduler; no messages are dispatched.
create function public.list_care_reminder_candidates(p_through date,p_after_kind text default '',p_after_id uuid default '00000000-0000-0000-0000-000000000000',p_limit integer default 100)
returns table(source_kind text,source_id uuid,source_version integer,pet_id uuid,due_on date) language plpgsql security definer set search_path=public as $$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service discovery only' using errcode='42501';end if;
 if p_through is null or not isfinite(p_through) or p_limit is null or p_limit not between 1 and 500 or p_after_kind is null or p_after_id is null then raise exception 'Finite discovery horizon and bounded page required' using errcode='23514';end if;
 return query select x.kind,x.id,x.version,x.patient,x.due from (
 select 'vaccine'::text kind,v.id,v.version,v.pet_id patient,v.current_due_on due from public.patient_vaccine_due_plans v where v.status='current' and v.reminders_enabled
 union all select 'lab'::text,l.id,l.version,l.pet_id,l.due_date from public.patient_lab_orders l where l.status in ('planned','ordered') and l.due_date is not null
 ) x join public.pets p on p.id=x.patient where p.archived_at is null and p.deceased_at is null and x.due<=p_through and row(x.kind,x.id)>row(p_after_kind,p_after_id) order by x.kind,x.id limit p_limit;
end $$

-- A single-statement read captures a consistent invoice/credit view for printing.
-- This is a current rendering, not a payment receipt or historical identity snapshot.
create function public.read_invoice_document(p_invoice_id uuid, p_client_id uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;
begin
 perform public.clinical_require_staff();
 select jsonb_build_object(
  'id',i.id,'status',i.status,'currency',i.currency,'version',i.version,
  'created_at',i.created_at,'issued_at',i.issued_at,'voided_at',i.voided_at,
  'rendered_at',statement_timestamp(),
  'client',jsonb_build_object('id',c.id,'name',c.full_name,'mailing_address',c.mailing_address),
  'items',coalesce((select jsonb_agg(jsonb_build_object(
    'id',l.id,'description',l.description,'quantity',l.quantity::text,
    'unit_price_cents',l.unit_price_cents::text,'amount_cents',l.amount_cents::text
  ) order by l.created_at,l.id) from public.billing_invoice_items l where l.invoice_id=i.id),'[]'::jsonb),
  'credits',coalesce((select jsonb_agg(jsonb_build_object(
    'id',cr.id,'amount_cents',cr.amount_cents::text,'created_at',cr.created_at
  ) order by cr.created_at,cr.id) from public.billing_credits cr where cr.invoice_id=i.id),'[]'::jsonb),
  'total_cents',coalesce(i.total_cents,(select coalesce(sum(l.amount_cents),0) from public.billing_invoice_items l where l.invoice_id=i.id))::text
 ) into result from public.billing_invoices i join public.clients c on c.id=i.client_id
 where i.id=p_invoice_id and i.client_id=p_client_id;
 if result is null then raise exception 'Invoice not available for this household' using errcode='42501'; end if;
 return result;
end $$

create or replace function public.preview_record_release_v1(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare pet public.pets; owner public.clients; selected uuid; k text; ids jsonb; e public.clinical_encounters; c public.vaccine_certificates; l public.patient_lab_orders; d public.patient_documents; soaps jsonb:='[]'; certs jsonb:='[]'; labs jsonb:='[]'; docs jsonb:='[]'; snapshot jsonb; recipient text; count_selected integer:=0;
begin
 perform public.clinical_require_staff();
 if p_selection is null or jsonb_typeof(p_selection)<>'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f not in ('encounter_ids','certificate_ids','lab_order_ids','document_ids')) then raise exception 'Choose explicit release sources' using errcode='23514'; end if;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids'] loop
  ids:=coalesce(p_selection->k,'[]');
  if jsonb_typeof(ids)<>'array' or jsonb_array_length(ids)>100 then raise exception 'Each source selection must be an array of at most 100 IDs' using errcode='23514'; end if;
  if exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string') or (select count(*) from jsonb_array_elements_text(ids))<>(select count(distinct v::uuid) from jsonb_array_elements_text(ids) v) then raise exception 'Source IDs must be unique strings' using errcode='23514'; end if;
  count_selected:=count_selected+jsonb_array_length(ids);
 end loop;

 select * into pet from public.pets where id=p_pet_id and client_id=p_client_id for share;
 if not found then raise exception 'Patient does not belong to this household' using errcode='42501'; end if;
 select * into owner from public.clients where id=p_client_id for share;
 recipient:=public.communication_recipient(p_channel,p_recipient);
 if p_channel is null or p_channel not in ('EMAIL','SMS') or recipient is null or recipient is distinct from public.communication_recipient(p_channel,case when p_channel='EMAIL' then owner.primary_email else owner.primary_phone end) then raise exception 'Recipient must match the selected patient household contact' using errcode='42501'; end if;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'encounter_ids','[]')) v order by v loop
  select * into e from public.clinical_encounters where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed encounters from this patient can be released' using errcode='23514'; end if;
  soaps:=soaps||jsonb_build_array(jsonb_build_object('id',e.id,'version',e.version,'visit_at',e.visit_at,'visit_type',e.visit_type,'subjective',e.subjective,'objective',e.objective,'assessment',e.assessment,'plan',e.plan,'signed_by',e.signed_by,'signed_at',e.signed_at,'addenda',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'content',a.content,'created_by',a.created_by,'created_at',a.created_at) order by a.created_at,a.id) from public.clinical_addenda a where a.encounter_id=e.id),'[]'::jsonb)));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'certificate_ids','[]')) v order by v loop
  select * into c from public.vaccine_certificates where id=selected and pet_id=p_pet_id for update;
  if not found or exists(select 1 from public.vaccine_certificate_events where certificate_id=selected) then raise exception 'Certificate is unavailable, belongs to another patient or is invalidated' using errcode='23514'; end if;
  certs:=certs||jsonb_build_array(to_jsonb(c)-array['request']);
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'lab_order_ids','[]')) v order by v loop
  select * into l from public.patient_lab_orders where id=selected and pet_id=p_pet_id and status='resulted' for update;
  if not found then raise exception 'Only resulted laboratory records from this patient can be released' using errcode='23514'; end if;
  if l.result_document_id is null or not exists(select 1 from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v where v::uuid=l.result_document_id) then raise exception 'Select the lab original report explicitly as a shareable attachment' using errcode='23514'; end if;
  labs:=labs||jsonb_build_array(jsonb_build_object('id',l.id,'version',l.version,'test_name',l.test_name,'accession',l.accession,'collected_date',l.collected_date,'result_date',l.result_date,'result_document_id',l.result_document_id));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v order by v loop
  select * into d from public.patient_documents where id=selected and pet_id=p_pet_id and status='ready' and visibility='client_shareable' for update;
  if not found then raise exception 'Only ready client-shareable documents from this patient can be released' using errcode='23514'; end if;
  if not exists(select 1 from storage.objects where bucket_id='patient-documents' and name=d.file_path and metadata->>'size'=d.file_size::text and metadata->>'mimetype'=d.mime_type) then raise exception 'Original document object is unavailable or metadata differs' using errcode='23514'; end if;
  docs:=docs||jsonb_build_array(jsonb_build_object('id',d.id,'version',d.version,'file_name',d.file_name,'file_path',d.file_path,'bucket','patient-documents','mime_type',d.mime_type,'file_size',d.file_size,'document_date',d.document_date,'category',d.category));
 end loop;
 snapshot:=jsonb_build_object('schema_version',1,'patient',jsonb_build_object('id',pet.id,'version',pet.version,'name',pet.name,'species',pet.species,'breed',pet.breed,'dob',pet.dob,'birth_date_precision',pet.birth_date_precision,'microchip_id',pet.microchip_id),'recipient',jsonb_build_object('client_id',owner.id,'client_version',owner.version,'name',owner.full_name,'channel',p_channel,'address',recipient),'encounters',soaps,'certificates',certs,'lab_results',labs,'attachments',docs);
 return jsonb_build_object('snapshot',snapshot,'source_hash',encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';
end $$

create function public.preview_record_release(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare k text; ids jsonb; selected uuid; total integer:=0; base_selection jsonb; result jsonb; s jsonb; d public.dental_charts; q public.patient_qol_records; a public.patient_anesthesia_records; l public.patient_lesions; dental jsonb:='[]'; qol jsonb:='[]'; anesthesia jsonb:='[]'; lesions jsonb:='[]';
begin
 perform public.clinical_require_staff();
 if p_selection is null or jsonb_typeof(p_selection)<>'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f not in ('encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids')) then raise exception 'Choose explicit release sources' using errcode='23514';end if;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids'] loop
  ids:=coalesce(p_selection->k,'[]');
  if jsonb_typeof(ids)<>'array' then raise exception 'Source selections must be arrays' using errcode='23514';end if;
  if jsonb_array_length(ids)>100 then raise exception 'Choose at most 100 records per source family' using errcode='23514';end if;
  if exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string') or (select count(*) from jsonb_array_elements_text(ids))<>(select count(distinct v::uuid) from jsonb_array_elements_text(ids) v) then raise exception 'Source IDs must be unique strings' using errcode='23514';end if;
  total:=total+jsonb_array_length(ids);
 end loop;
 if total=0 then raise exception 'Choose at least one source; nothing is included by default' using errcode='23514';end if;
 -- Acquire chart-parent locks before original-document locks, matching chart writers.
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'dental_ids','[]')) v order by v loop
  select * into d from public.dental_charts where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed dental charts from this patient can be released' using errcode='23514';end if;
  dental:=dental||jsonb_build_array(jsonb_build_object('id',d.id,'version',d.version,'species_family',d.species_family,'dentition',d.dentition,'visit_at',d.visit_at,'notes',d.notes,'teeth',d.teeth,'signed_by',d.signed_by,'signed_at',d.signed_at,'addenda',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at,x.id) from public.dental_chart_addenda x where chart_id=d.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'qol_ids','[]')) v order by v loop
  select * into q from public.patient_qol_records where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed QOL records from this patient can be released' using errcode='23514';end if;
  qol:=qol||jsonb_build_array(jsonb_build_object('id',q.id,'version',q.version,'template_version',q.template_version,'observed_at',q.observed_at,'observer',q.observer,'appetite',q.appetite,'drinking',q.drinking,'mobility',q.mobility,'comfort',q.comfort,'social_engagement',q.social_engagement,'good_days',q.good_days,'notes',q.notes,'signed_by',q.signed_by,'signed_at',q.signed_at,'addenda',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at,x.id) from public.patient_qol_addenda x where qol_id=q.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'anesthesia_ids','[]')) v order by v loop
  select * into a from public.patient_anesthesia_records where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed anesthesia records from this patient can be released' using errcode='23514';end if;
  anesthesia:=anesthesia||jsonb_build_array(jsonb_build_object('id',a.id,'version',a.version,'procedure_name',a.procedure_name,'started_at',a.started_at,'ended_at',a.ended_at,'team',a.team,'assessment',a.assessment,'plan',a.plan,'recovery_notes',a.recovery_notes,'observations',a.observations,'events',a.events,'source',a.source,'included_original_document_id',case when exists(select 1 from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v where v::uuid=a.original_document_id) then a.original_document_id else null end,'signed_by',a.signed_by,'signed_at',a.signed_at,'addenda',coalesce((select jsonb_agg(to_jsonb(x) order by x.recorded_at,x.id) from public.anesthesia_record_addenda x where record_id=a.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'lesion_ids','[]')) v order by v loop
  select * into l from public.patient_lesions where id=selected and pet_id=p_pet_id for update;
  if not found then raise exception 'Body-map history must belong to this patient' using errcode='23514';end if;
  lesions:=lesions||jsonb_build_array(jsonb_build_object('id',l.id,'version',l.version,'label',l.label,'observations',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'observed_at',o.observed_at,'label',o.label,'body_view',o.body_view,'x',o.x,'y',o.y,'length_mm',o.length_mm,'width_mm',o.width_mm,'depth_mm',o.depth_mm,'notes',o.notes,'created_by',o.created_by,'created_at',o.created_at,'photo_document_id',case when exists(select 1 from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v where v::uuid=o.photo_document_id) then o.photo_document_id else null end,'corrections',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at,c.id) from public.patient_lesion_corrections c where c.observation_id=o.id),'[]')) order by o.observed_at,o.created_at,o.id) from public.patient_lesion_observations o where lesion_id=l.id),'[]')));
 end loop;
 base_selection:=p_selection-array['dental_ids','qol_ids','anesthesia_ids','lesion_ids'];
 result:=public.preview_record_release_v1(p_pet_id,p_client_id,p_channel,p_recipient,base_selection);
 s:=(result->'snapshot')||jsonb_build_object('schema_version',2,'dental_charts',dental,'qol_records',qol,'anesthesia_records',anesthesia,'lesions',lesions);
 return jsonb_build_object('snapshot',s,'source_hash',encode(sha256(convert_to(s::text,'UTF8')),'hex'));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';
end $$

create function public.release_lock_chart_parent() returns trigger language plpgsql security definer set search_path=public as $$
begin
 case TG_TABLE_NAME
 when 'dental_chart_addenda' then perform 1 from public.dental_charts where id=NEW.chart_id for update;
 when 'patient_qol_addenda' then perform 1 from public.patient_qol_records where id=NEW.qol_id for update;
 when 'anesthesia_record_addenda' then perform 1 from public.patient_anesthesia_records where id=NEW.record_id for update;
 when 'patient_lesion_observations' then perform 1 from public.patient_lesions where id=NEW.lesion_id for update;
 when 'patient_lesion_corrections' then perform 1 from public.patient_lesions where id=(select lesion_id from public.patient_lesion_observations where id=NEW.observation_id) for update;
 end case;
 return NEW;
end $$

create function public.invalidate_record_release_chart() returns trigger language plpgsql security definer set search_path=public as $$
declare source_type text; source uuid;
begin
 case TG_TABLE_NAME
 when 'dental_chart_addenda' then source_type:='dental';source:=NEW.chart_id;
 when 'patient_qol_addenda' then source_type:='qol';source:=NEW.qol_id;
 when 'anesthesia_record_addenda' then source_type:='anesthesia';source:=NEW.record_id;
 when 'patient_lesion_observations' then source_type:='lesion';source:=NEW.lesion_id;
 when 'patient_lesion_corrections' then source_type:='lesion';select lesion_id into source from public.patient_lesion_observations where id=NEW.observation_id;
 end case;
 insert into public.record_release_events(id,release_id,kind,reason,created_by) select gen_random_uuid(),release_id,'source_changed','Reviewed '||source_type||' history changed; prepare a fresh package',auth.uid() from public.record_release_sources where source_kind=source_type and source_id=source;
 return NEW;
end $$

do $$ declare t text;begin
 foreach t in array array['dental_chart_addenda','patient_qol_addenda','anesthesia_record_addenda','patient_lesion_observations','patient_lesion_corrections'] loop
  execute format('create trigger aaa_release_chart_lock before insert on public.%I for each row execute function public.release_lock_chart_parent()',t);
  execute format('create trigger release_chart_changed after insert on public.%I for each row execute function public.invalidate_record_release_chart()',t);
 end loop;
end $$

create or replace function public.confirm_record_release(p_id uuid,p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb,p_reviewed_snapshot jsonb,p_reviewed_hash text,p_attest_review boolean) returns public.record_releases language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.record_releases; preview jsonb; req jsonb; k text; source_type text;
begin
 if p_id is null or p_attest_review is distinct from true then raise exception 'Stable ID and explicit content/recipient review are required' using errcode='23514'; end if;
 req:=jsonb_build_object('pet_id',p_pet_id,'client_id',p_client_id,'channel',p_channel,'recipient',p_recipient,'selection',p_selection,'reviewed_snapshot',p_reviewed_snapshot,'reviewed_hash',p_reviewed_hash,'attest_review',p_attest_review);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,13));
 select * into result from public.record_releases where id=p_id;
 if found then if result.created_by<>actor or result.request is distinct from req then raise exception 'Release identifier already used' using errcode='23514'; end if; return result; end if;
 perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=2 for share;
 if not found then raise exception 'Clinical acceptance of the release form and workflow is required before confirmation' using errcode='42501'; end if;
 preview:=public.preview_record_release(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);
 if preview->'snapshot' is distinct from p_reviewed_snapshot or preview->>'source_hash' is distinct from p_reviewed_hash then raise exception 'Release sources or recipient changed; preview and review again' using errcode='40001'; end if;
 insert into public.record_releases(id,pet_id,client_id,channel,recipient,selection,snapshot,source_hash,request,created_by) values(p_id,p_pet_id,p_client_id,p_channel,preview#>>'{snapshot,recipient,address}',p_selection,p_reviewed_snapshot,p_reviewed_hash,req,actor) returning * into result;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids'] loop
  source_type:=case k when 'encounter_ids' then 'encounter' when 'certificate_ids' then 'certificate' when 'lab_order_ids' then 'lab' when 'dental_ids' then 'dental' when 'qol_ids' then 'qol' when 'anesthesia_ids' then 'anesthesia' when 'lesion_ids' then 'lesion' else 'document' end;
  insert into public.record_release_sources(release_id,source_kind,source_id) select p_id,source_type,v::uuid from jsonb_array_elements_text(coalesce(p_selection->k,'[]')) v;
 end loop;
 return result;
end $$

create or replace function public.read_record_release(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.record_releases; events jsonb; eligible boolean:=true; why text; current_preview jsonb;
begin
 perform public.clinical_require_staff();
 select * into r from public.record_releases where id=p_id for share;
 if not found then raise exception 'Release not found' using errcode='23514'; end if;
 select coalesce(jsonb_agg(to_jsonb(e) order by created_at,id),'[]') into events from public.record_release_events e where release_id=p_id;
 if jsonb_array_length(events)>0 then eligible:=false;why:='Withdrawn or a reviewed source changed';
 else
  begin
   if r.snapshot->>'schema_version'='1' then current_preview:=public.preview_record_release_v1(r.pet_id,r.client_id,r.channel,r.recipient,r.selection); else current_preview:=public.preview_record_release(r.pet_id,r.client_id,r.channel,r.recipient,r.selection);end if;
   if current_preview->>'source_hash'<>r.source_hash then eligible:=false;why:='Current source snapshot differs';end if;
  exception when sqlstate '23514' or sqlstate '42501' then eligible:=false;why:='Source or recipient is no longer eligible';end;
 end if;
 return jsonb_build_object('release',to_jsonb(r)-'request','events',events,'eligible',eligible,'ineligibility_reason',why);
end $$

create or replace function public.authorize_record_release(p_id uuid,p_client_id uuid,p_channel text,p_recipient text) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=coalesce((select (snapshot->>'schema_version')::integer from public.record_releases where id=p_id),2) for share;
 if not found then raise exception 'Clinical release acceptance is not active' using errcode='42501';end if;
 result:=public.read_record_release(p_id);
 if (result->>'eligible')::boolean is distinct from true or result#>>'{release,client_id}' is distinct from p_client_id::text or result#>>'{release,channel}' is distinct from p_channel or result#>>'{release,recipient}' is distinct from public.communication_recipient(p_channel,p_recipient) then raise exception 'Release is not eligible for this household recipient' using errcode='42501';end if;
 return result;
end $$

create function public.list_record_release_sources(p_pet_id uuid,p_offset integer default 0) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.pets;c public.clients;r jsonb;k text;rows jsonb;query text;skip integer:=greatest(coalesce(p_offset,0),0);
begin
 perform public.clinical_require_staff();
 select * into p from public.pets where id=p_pet_id;
 if not found then raise exception 'Patient not found' using errcode='23514';end if;
 select * into c from public.clients where id=p.client_id;
 r:=jsonb_build_object('pet_id',p.id,'client_id',c.id,'client_name',c.full_name,'email',public.communication_recipient('EMAIL',c.primary_email),'phone',public.communication_recipient('SMS',c.primary_phone),'policy_accepted',exists(select 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=2));
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids'] loop
  query:=case k
   when 'encounter_ids' then 'select id,version,visit_at as recorded_at,''Signed SOAP · ''||visit_type as label from public.clinical_encounters where pet_id=$1 and status=''signed'''
   when 'certificate_ids' then 'select id,1 as version,issued_at as recorded_at,kind||'' certificate'' as label from public.vaccine_certificates c where pet_id=$1 and not exists(select 1 from public.vaccine_certificate_events e where e.certificate_id=c.id)'
   when 'lab_order_ids' then 'select id,version,updated_at as recorded_at,test_name as label,result_document_id as required_document_id from public.patient_lab_orders where pet_id=$1 and status=''resulted'''
   when 'document_ids' then 'select id,version,created_at as recorded_at,file_name as label,mime_type,file_size from public.patient_documents where pet_id=$1 and status=''ready'' and visibility=''client_shareable'''
   when 'dental_ids' then 'select id,version,visit_at as recorded_at,''Signed dental · ''||dentition as label from public.dental_charts where pet_id=$1 and status=''signed'''
   when 'qol_ids' then 'select id,version,observed_at as recorded_at,''Signed QOL · ''||observer as label from public.patient_qol_records where pet_id=$1 and status=''signed'''
   when 'anesthesia_ids' then 'select id,version,started_at as recorded_at,procedure_name as label from public.patient_anesthesia_records where pet_id=$1 and status=''signed'''
   else 'select id,version,updated_at as recorded_at,label from public.patient_lesions where pet_id=$1' end;
  execute 'select coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) from ('||query||' order by recorded_at desc,id limit 100 offset $2) x' into rows using p_pet_id,skip;
  r:=r||jsonb_build_object(k,rows);
 end loop;
 return r;
end $$

-- Public submissions remain private, immutable originals. Staff triage is separate.
create function public.guard_contact_submission() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP<>'INSERT' then raise exception 'Original website submissions are immutable' using errcode='23514';end if;
 if length(trim(NEW.name)) not between 1 and 100 or length(NEW.email) not between 3 and 255 or NEW.email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
 or coalesce(length(NEW.phone),0)>20 or length(trim(NEW.subject)) not between 1 and 200 or length(trim(NEW.message)) not between 1 and 2000 then raise exception 'Invalid website contact fields' using errcode='23514';end if;
 return NEW;
end $$

do $$ declare t text;begin
 foreach t in array array['website_inquiry_triage','website_inquiry_history'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated',t);
  execute format('create policy "Active staff inquiry read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
 end loop;
end $$

create function public.read_website_inquiry(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();
 select jsonb_build_object('submission',to_jsonb(s),'triage',to_jsonb(t),'household_name',c.full_name)
 into result from public.contact_submissions s join public.website_inquiry_triage t on t.inquiry_id=s.id left join public.clients c on c.id=t.client_id where s.id=p_id;
 if result is null then raise exception 'Inquiry not found' using errcode='42501';end if;
 return result;
end $$

create function public.update_website_inquiry(p_actor_id uuid,p_id uuid,p_expected_version integer,p_status text,p_assigned_to_id uuid,p_reason text) returns public.website_inquiry_triage language plpgsql security definer set search_path=public as $$
declare actor uuid;original public.website_inquiry_triage;result public.website_inquiry_triage;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into original from public.website_inquiry_triage where inquiry_id=p_id for update;
 if not found or original.version is distinct from p_expected_version then raise exception 'Inquiry changed; reload before saving' using errcode='40001';end if;
 if p_status is null or p_status not in ('new','in_progress','resolved','spam') or p_reason is null or length(trim(p_reason)) not between 5 and 1000 or (p_assigned_to_id is not null and not public.is_active_staff(p_assigned_to_id)) then raise exception 'Valid status, active assignee and review reason required' using errcode='23514';end if;
 update public.website_inquiry_triage set status=p_status,assigned_to_id=p_assigned_to_id,version=version+1,updated_at=now() where inquiry_id=p_id returning * into result;
 insert into public.website_inquiry_history(inquiry_id,actor_id,action,reason,before_value,after_value) values(p_id,actor,'triage',trim(p_reason),to_jsonb(original),to_jsonb(result));
 return result;
end $$

create function public.review_website_inquiry_household(p_actor_id uuid,p_id uuid,p_expected_version integer,p_client_id uuid,p_channel text,p_recipient text,p_confirmed boolean,p_evidence text) returns public.website_inquiry_triage language plpgsql security definer set search_path=public as $$
declare actor uuid;original public.website_inquiry_triage;result public.website_inquiry_triage;recipient text;household public.clients;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into original from public.website_inquiry_triage where inquiry_id=p_id for update;
 if not found or original.version is distinct from p_expected_version then raise exception 'Inquiry changed; reload before linking' using errcode='40001';end if;
 recipient:=public.communication_recipient(p_channel,p_recipient);
 select * into household from public.clients where id=p_client_id;
 if not found or p_confirmed is distinct from true or p_evidence is null or length(trim(p_evidence)) not between 5 and 1000 or recipient is null or recipient is distinct from public.communication_recipient(p_channel,case when p_channel='EMAIL' then household.primary_email else household.primary_phone end) then raise exception 'Independently confirm the household and its current reply destination' using errcode='23514';end if;
 update public.website_inquiry_triage set status='in_progress',client_id=p_client_id,reply_channel=p_channel,reply_recipient=recipient,reviewed_by=actor,reviewed_at=now(),version=version+1,updated_at=now() where inquiry_id=p_id returning * into result;
 insert into public.website_inquiry_history(inquiry_id,actor_id,action,reason,before_value,after_value) values(p_id,actor,'household_review',trim(p_evidence),to_jsonb(original),to_jsonb(result)||jsonb_build_object('household_name',household.full_name));
 return result;
end $$

create function public.authorize_website_inquiry_reply(p_actor_id uuid,p_id uuid,p_expected_version integer) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;review public.website_inquiry_triage;household public.clients;conversation public.conversations;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into review from public.website_inquiry_triage where inquiry_id=p_id for update;
 if not found or review.version is distinct from p_expected_version then raise exception 'Inquiry changed; reload before replying' using errcode='40001';end if;
 select * into household from public.clients where id=review.client_id;
 if review.status<>'in_progress' or review.reviewed_by is null or household.id is null or review.reply_recipient is distinct from public.communication_recipient(review.reply_channel,case when review.reply_channel='EMAIL' then household.primary_email else household.primary_phone end) or public.communication_is_suppressed(review.reply_channel,review.reply_recipient,household.id) then raise exception 'Review the current household destination and channel permission before replying' using errcode='42501';end if;
 conversation:=public.ensure_active_conversation(household.id);
 insert into public.website_inquiry_history(inquiry_id,actor_id,action,reason,after_value) values(p_id,actor,'reply_handoff','Authorized composer handoff; this does not send a message',jsonb_build_object('conversation_id',conversation.id,'client_id',household.id,'channel',review.reply_channel,'recipient',review.reply_recipient,'review_version',review.version));
 return jsonb_build_object('conversation_id',conversation.id,'client_id',household.id,'channel',review.reply_channel,'recipient',review.reply_recipient);
end $$

do $$ declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('guard_contact_submission','initialize_website_inquiry','guard_inquiry_history','list_website_inquiries','website_inquiry_open_count','read_website_inquiry','update_website_inquiry','review_website_inquiry_household','authorize_website_inquiry_reply') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname not in ('guard_contact_submission','initialize_website_inquiry','guard_inquiry_history') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$

create table public.reminder_automation_policy_history (
 id bigint generated always as identity primary key,policy_id uuid not null references public.reminder_automation_policies(id),version integer not null,snapshot jsonb not null,unique(policy_id,version)
)

create function public.save_reminder_automation_policy(p_id uuid,p_expected_version integer,p_source_kind text,p_channel text,p_message_template_id uuid,p_message_template_version integer,p_subject text,p_enabled boolean,p_review_note text) returns public.reminder_automation_policies language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.reminder_automation_policies;t public.care_message_templates;
begin actor=public.care_require_admin();if p_id is null then raise exception 'Stable policy ID required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,18));select * into r from public.reminder_automation_policies where id=p_id for update;
 if found then
  if r.approved_by=actor and r.version=coalesce(p_expected_version,0)+1 and row(r.source_kind,r.channel,r.message_template_id,r.message_template_version,r.subject,r.enabled,r.review_note) is not distinct from row(p_source_kind,p_channel,p_message_template_id,p_message_template_version,coalesce(p_subject,''),p_enabled,trim(p_review_note)) then return r;end if;
  if r.version is distinct from p_expected_version then raise exception 'Automation policy version conflict' using errcode='40001';end if;
  if row(r.source_kind,r.channel) is distinct from row(p_source_kind,p_channel) then raise exception 'Policy source and channel are immutable' using errcode='23514';end if;
 elsif p_expected_version is not null then raise exception 'Automation policy version conflict' using errcode='40001';end if;
 select * into t from public.care_message_templates where id=p_message_template_id for share;
 if t.id is null or not t.active or t.version is distinct from p_message_template_version or upper(t.channel) is distinct from p_channel then raise exception 'Select current reviewed wording for the policy channel' using errcode='23514';end if;
 if r.id is null then insert into public.reminder_automation_policies(id,source_kind,channel,message_template_id,message_template_version,subject,enabled,review_note,approved_by) values(p_id,p_source_kind,p_channel,t.id,t.version,coalesce(p_subject,''),p_enabled,trim(p_review_note),actor) returning * into r;
 else update public.reminder_automation_policies set message_template_id=t.id,message_template_version=t.version,subject=coalesce(p_subject,''),enabled=p_enabled,review_note=trim(p_review_note),version=version+1,approved_by=actor,approved_at=now() where id=p_id returning * into r;end if;
 insert into public.reminder_automation_policy_history(policy_id,version,snapshot) values(r.id,r.version,to_jsonb(r));return r;
end $$

-- Internal validation/rendering is shared by enqueue and EVERY provider-attempt preflight.
create function public.reminder_delivery_context(p_job_kind text,p_job_id uuid,p_policy_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare policy public.reminder_automation_policies;t public.care_message_templates;j public.care_reminder_jobs;ar public.appointment_reminders;a public.appointments;v public.patient_vaccine_due_plans;l public.patient_lab_orders;p public.pets;c public.clients;actor uuid;source jsonb;body text;care_name text;due date;part record;recipient text;
begin
 select * into policy from public.reminder_automation_policies where id=p_policy_id for share;
 if policy.id is null or not policy.enabled or not public.is_active_staff(policy.approved_by) then return null;end if;
 select * into t from public.care_message_templates where id=policy.message_template_id for share;
 if t.id is null or not t.active or t.version<>policy.message_template_version or upper(t.channel)<>policy.channel or not public.is_active_staff(t.updated_by) then return null;end if;
 if p_job_kind='care' then
  select * into j from public.care_reminder_jobs where id=p_job_id for update;
  if j.id is null or j.status<>'pending' or j.source_kind<>policy.source_kind or upper(j.channel)<>policy.channel or j.message_template_id<>t.id or j.message_template_version<>t.version or j.scheduled_on>(now() at time zone 'America/Denver')::date then return null;end if;
  if j.source_kind='vaccine' then select * into v from public.patient_vaccine_due_plans where id=j.source_id for share;
   if v.id is null or v.version<>j.source_version or v.status<>'current' or not v.reminders_enabled or v.pet_id<>j.pet_id or v.current_due_on<>j.due_on or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.treatment_id) then return null;end if;
   source=to_jsonb(v);actor=v.updated_by;
  else select * into l from public.patient_lab_orders where id=j.source_id for share;
   if l.id is null or l.version<>j.source_version or l.status not in ('planned','ordered') or l.pet_id<>j.pet_id or l.due_date is distinct from j.due_on then return null;end if;
   source=to_jsonb(l);actor=l.updated_by;
  end if;
  if source is distinct from j.source_snapshot or actor is distinct from (j.source_snapshot->>'updated_by')::uuid then return null;end if;
  select * into p from public.pets where id=j.pet_id for share;
  if p.client_id is distinct from j.client_id then return null;end if;body=j.rendered_body;due=j.due_on;
 elsif p_job_kind='appointment' then
  select * into ar from public.appointment_reminders where id=p_job_id for update;
  if ar.id is null or ar.status<>'PENDING' or ar.remind_at>now() or ar.channel<>policy.channel or policy.source_kind<>'appointment' then return null;end if;
  select * into a from public.appointments where id=ar.appointment_id for share;
  if a.id is null or a.version<>ar.appointment_version or a.status not in ('SCHEDULED','CONFIRMED') or a.scheduled_at<=now() or a.pet_id is null then return null;end if;
  actor=a.updated_by;source=to_jsonb(a);select * into p from public.pets where id=a.pet_id for share;
  if p.client_id is distinct from a.client_id then return null;end if;
  due=(a.scheduled_at at time zone 'America/Denver')::date;
  care_name=a.appointment_type||' · '||to_char(a.scheduled_at at time zone 'America/Denver','YYYY-MM-DD HH24:MI')||' America/Denver · '||a.address_snapshot;
  body='';for part in select m[1] token from regexp_matches(t.body,'(\{\{patient_name\}\}|\{\{care_name\}\}|\{\{due_date\}\}|[^{}]+)','g') m loop body=body||case part.token when '{{patient_name}}' then p.name when '{{care_name}}' then care_name when '{{due_date}}' then due::text else part.token end;end loop;
 else return null;end if;
 if p.id is null or p.archived_at is not null or p.deceased_at is not null or actor is null or not public.is_active_staff(actor) then return null;end if;
 select * into c from public.clients where id=p.client_id for share;
 recipient=public.communication_recipient(policy.channel,case when policy.channel='EMAIL' then c.primary_email else c.primary_phone end);
 if recipient is null or public.communication_is_suppressed(policy.channel,recipient,c.id) or length(body)<1 or (policy.channel='SMS' and length(body)>1600) then return null;end if;
 return jsonb_build_object('job_kind',p_job_kind,'job_id',p_job_id,'policy',to_jsonb(policy),'template',to_jsonb(t),'source',source,'actor_id',actor,'pet_id',p.id,'patient_name',p.name,'client_id',c.id,'recipient',recipient,'channel',policy.channel,'subject',policy.subject,'body',body,'due_on',due);
end $$

create function public.block_reminder_job(p_job_kind text,p_job_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$
begin
 if p_job_kind='care' then update public.care_reminder_jobs set status='invalidated',invalidated_at=now(),invalidation_reason=p_reason where id=p_job_id and status='pending';
 else update public.appointment_reminders set status='SKIPPED',error_message=p_reason where id=p_job_id and status='PENDING';end if;
end $$

create function public.queue_reminder_outbox(p_job_kind text,p_job_id uuid,p_policy_id uuid) returns public.reminder_outbox_links language plpgsql security definer set search_path=public as $$
declare context jsonb;r public.reminder_outbox_links;policy public.reminder_automation_policies;conversation uuid;msg uuid;outbox uuid;actor uuid;
begin perform public.communication_require_service();
 if p_job_kind not in ('care','appointment') or p_job_kind is null or p_job_id is null then raise exception 'Valid durable job identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_job_kind||p_job_id::text,19));select * into r from public.reminder_outbox_links where job_kind=p_job_kind and job_id=p_job_id;
 if found then if r.policy_id<>p_policy_id then raise exception 'Job already reviewed under another policy' using errcode='23505';end if;return r;end if;
 select * into policy from public.reminder_automation_policies where id=p_policy_id for share;
 if policy.id is null or not policy.enabled then raise exception 'Reminder policy disabled' using errcode='42501';end if;
 context=public.reminder_delivery_context(p_job_kind,p_job_id,p_policy_id);
 if context is null then
  perform public.block_reminder_job(p_job_kind,p_job_id,'Reminder source, consent or approval no longer eligible');
  insert into public.reminder_outbox_links(job_kind,job_id,policy_id,policy_version,state,reason) values(p_job_kind,p_job_id,policy.id,policy.version,'blocked','source_or_recipient_ineligible') returning * into r;return r;
 end if;
 actor=(context->>'actor_id')::uuid;
 -- Serialize household conversation creation; system origin remains linked to the approving staff actor.
 perform pg_advisory_xact_lock(hashtextextended(context->>'client_id',20));
 select id into conversation from public.conversations where client_id=(context->>'client_id')::uuid and status='ACTIVE' and archived_at is null order by created_at,id limit 1 for update;
 if conversation is null then insert into public.conversations(client_id,status) values((context->>'client_id')::uuid,'ACTIVE') returning id into conversation;end if;
 if exists(select 1 from public.communication_outbox where request_id=p_job_id) then raise exception 'Job UUID already belongs to another outbound intent' using errcode='23505';end if;
 insert into public.messages(conversation_id,content,type,sender_type,sender_id,is_internal) values(conversation,context->>'body',(context->>'channel')::public.message_type,'SYSTEM',actor,false) returning id into msg;
 insert into public.communication_outbox(request_id,conversation_id,client_id,message_id,created_by,channel,recipient,subject,body,provider) values(p_job_id,conversation,(context->>'client_id')::uuid,msg,actor,context->>'channel',context->>'recipient',context->>'subject',context->>'body',case when context->>'channel'='EMAIL' then 'resend' else 'twilio' end) returning id into outbox;
 insert into public.reminder_outbox_links(job_kind,job_id,policy_id,policy_version,outbox_id,approving_actor_id,frozen_context,state) values(p_job_kind,p_job_id,policy.id,policy.version,outbox,actor,context,'queued') returning * into r;
 update public.conversations set last_message_at=now(),is_read=true where id=conversation;return r;
end $$

create function public.start_communication_attempt(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare r public.communication_outbox;link public.reminder_outbox_links;context jsonb;
begin perform public.communication_require_service();select * into r from public.communication_outbox where id=p_id for update;
 if r.id is null or r.state<>'claimed' or r.lease_token is distinct from p_lease_token or r.lease_expires_at<=now() or r.attempt_started_at is not null then raise exception 'Outbox lease is unavailable' using errcode='40001';end if;
 select * into link from public.reminder_outbox_links where outbox_id=p_id for update;
 if found then
  if link.invalidated_at is null then context=public.reminder_delivery_context(link.job_kind,link.job_id,link.policy_id);end if;
  if context is null or context is distinct from link.frozen_context then
   update public.reminder_outbox_links set invalidated_at=coalesce(invalidated_at,now()),reason='final_preflight_source_or_recipient_ineligible' where outbox_id=p_id;
   perform public.block_reminder_job(link.job_kind,link.job_id,'Reminder invalidated before provider attempt');
   update public.communication_outbox set state='failed',last_error='reminder_source_or_recipient_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into r;return r;
  end if;
 end if;
 r=public.start_communication_attempt_without_reminder_guard(p_id,p_lease_token,p_provider_config);
 if link.outbox_id is not null and r.state='failed' and r.last_error='recipient_or_actor_ineligible' then
  update public.reminder_outbox_links set invalidated_at=coalesce(invalidated_at,now()),reason='final_preflight_recipient_or_actor_ineligible' where outbox_id=p_id;
  perform public.block_reminder_job(link.job_kind,link.job_id,'Reminder invalidated by final recipient or actor check');
 end if;
 return r;
end $$

do $$ declare t text;begin foreach t in array array['reminder_automation_policies','reminder_automation_policy_history','reminder_outbox_links'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on table public.%I from public,anon,authenticated,service_role',t);execute format('grant select on table public.%I to authenticated,service_role',t);execute format('create policy "Active staff read reminder automation audit" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
end loop;end $$

create function public.preview_vaccine_certificate(p_pet_id uuid,p_kind text,p_rabies_treatment_id uuid,p_details jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare snapshot jsonb;plans jsonb;
begin
 if p_kind='vaccine_history' and p_details is distinct from '{"due_plan_review_version":2}'::jsonb then
  raise exception 'Refresh the certificate workspace to review patient due plans before signing' using errcode='23514';
 end if;
 snapshot=public.preview_vaccine_certificate_v1_internal(p_pet_id,p_kind,p_rabies_treatment_id,case when p_kind='vaccine_history' then '{}'::jsonb else p_details end);
 if p_kind='rabies' then return snapshot;end if;
 -- One aggregate captures all nonretired plans, including explicit gaps awaiting review.
 -- Names and dates come from the reviewed plan, never guessed from vaccine brand names.
 select coalesce(jsonb_agg(jsonb_build_object(
  'plan_id',v.id,'plan_version',v.version,'group_key',v.group_key,
  'group_name',v.template_snapshot->>'name','template_id',v.template_id,'template_version',v.template_version,
  'product_id',v.product_id,'treatment_id',v.treatment_id,'last_administered_on',v.last_administered_on,
  'status',v.status,'reviewed_due_on',case when v.status='current' then v.current_due_on else null end
 ) order by v.group_key,v.id),'[]'::jsonb) into plans
 from public.patient_vaccine_due_plans v where v.pet_id=p_pet_id and v.status<>'retired';
 return snapshot||jsonb_build_object('schema_version',2,'due_plans',plans);
end $$

create or replace function public.issue_vaccine_certificate(p_id uuid,p_pet_id uuid,p_kind text,p_rabies_treatment_id uuid,p_details jsonb,p_reviewed_snapshot jsonb,p_signature_name text,p_attest_review boolean,p_replaces_id uuid default null,p_reason text default null) returns public.vaccine_certificates language plpgsql security definer set search_path=public as $$
declare issuer public.certificate_issuers:=public.certificate_require_issuer(); result public.vaccine_certificates; expected jsonb; request_data jsonb; prior public.vaccine_certificates;
begin
 if p_id is null or p_attest_review is distinct from true or p_signature_name is distinct from issuer.full_name then raise exception 'Explicit review and matching typed veterinarian signature are required' using errcode='23514'; end if;
 request_data:=jsonb_build_object('pet_id',p_pet_id,'kind',p_kind,'rabies_treatment_id',p_rabies_treatment_id,'details',p_details,'reviewed_snapshot',p_reviewed_snapshot,'signature_name',p_signature_name,'attest_review',p_attest_review,'replaces_id',p_replaces_id,'reason',p_reason);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,8));
 select * into result from public.vaccine_certificates where id=p_id;
 if found then
  if result.issued_by<>auth.uid() or result.request is distinct from request_data then raise exception 'Certificate identifier already used' using errcode='23514'; end if;
  return result;
 end if;
 expected:=public.preview_vaccine_certificate(p_pet_id,p_kind,p_rabies_treatment_id,p_details);
 if expected is distinct from p_reviewed_snapshot then raise exception 'Certificate details changed; reload and review before issuing' using errcode='40001'; end if;
 if p_replaces_id is not null then
  select * into prior from public.vaccine_certificates where id=p_replaces_id for update;
  if not found or prior.pet_id<>p_pet_id or prior.kind<>p_kind or length(trim(coalesce(p_reason,''))) not between 1 and 2000 then raise exception 'Reissue requires matching patient, certificate type and reason' using errcode='23514'; end if;
  if exists(select 1 from public.vaccine_certificate_events where certificate_id=p_replaces_id and kind='superseded') then raise exception 'Certificate already reissued; reload its successor' using errcode='40001'; end if;
 elsif p_reason is not null then raise exception 'Reason requires a certificate being replaced' using errcode='23514'; end if;
 insert into public.vaccine_certificates(id,pet_id,kind,snapshot,request,replaces_id,issued_by,signature_name,attestation) values(p_id,p_pet_id,p_kind,expected,request_data,p_replaces_id,auth.uid(),p_signature_name,case when p_kind='rabies' then 'I reviewed this complete certificate and its due date, confirm this was a rabies vaccine administered by me or under my supervision by the named administrator trained in vaccine storage, handling, administration and adverse-event management, and explicitly sign this certificate.' else 'I reviewed the patient identity, included vaccination history and the patient due-plan snapshot, including any plans awaiting review, and explicitly sign this certificate. The reviewed plan dates apply to this snapshot at issuance; no vaccine equivalence or due date was inferred. This is not a rabies certificate.' end) returning * into result;
 insert into public.vaccine_certificate_treatments(certificate_id,treatment_id) select p_id,(v->>'treatment_id')::uuid from jsonb_array_elements(expected->'vaccinations') v;
 if p_replaces_id is not null then insert into public.vaccine_certificate_events(id,certificate_id,kind,reason,replacement_id,created_by) values(p_id,p_replaces_id,'superseded',trim(p_reason),p_id,auth.uid()); end if;
 return result;
end $$

create or replace function public.preview_record_release_v2(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare k text; ids jsonb; selected uuid; total integer:=0; base_selection jsonb; result jsonb; s jsonb; d public.dental_charts; q public.patient_qol_records; a public.patient_anesthesia_records; l public.patient_lesions; dental jsonb:='[]'; qol jsonb:='[]'; anesthesia jsonb:='[]'; lesions jsonb:='[]';
begin
 perform public.clinical_require_staff();
 if p_selection is null or jsonb_typeof(p_selection)<>'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f not in ('encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids')) then raise exception 'Choose explicit release sources' using errcode='23514';end if;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids'] loop
  ids:=coalesce(p_selection->k,'[]');
  if jsonb_typeof(ids)<>'array' then raise exception 'Source selections must be arrays' using errcode='23514';end if;
  if jsonb_array_length(ids)>100 then raise exception 'Choose at most 100 records per source family' using errcode='23514';end if;
  if exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string') or (select count(*) from jsonb_array_elements_text(ids))<>(select count(distinct v::uuid) from jsonb_array_elements_text(ids) v) then raise exception 'Source IDs must be unique strings' using errcode='23514';end if;
  total:=total+jsonb_array_length(ids);
 end loop;

 -- Acquire chart-parent locks before original-document locks, matching chart writers.
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'dental_ids','[]')) v order by v loop
  select * into d from public.dental_charts where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed dental charts from this patient can be released' using errcode='23514';end if;
  dental:=dental||jsonb_build_array(jsonb_build_object('id',d.id,'version',d.version,'species_family',d.species_family,'dentition',d.dentition,'visit_at',d.visit_at,'notes',d.notes,'teeth',d.teeth,'signed_by',d.signed_by,'signed_at',d.signed_at,'addenda',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at,x.id) from public.dental_chart_addenda x where chart_id=d.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'qol_ids','[]')) v order by v loop
  select * into q from public.patient_qol_records where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed QOL records from this patient can be released' using errcode='23514';end if;
  qol:=qol||jsonb_build_array(jsonb_build_object('id',q.id,'version',q.version,'template_version',q.template_version,'observed_at',q.observed_at,'observer',q.observer,'appetite',q.appetite,'drinking',q.drinking,'mobility',q.mobility,'comfort',q.comfort,'social_engagement',q.social_engagement,'good_days',q.good_days,'notes',q.notes,'signed_by',q.signed_by,'signed_at',q.signed_at,'addenda',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at,x.id) from public.patient_qol_addenda x where qol_id=q.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'anesthesia_ids','[]')) v order by v loop
  select * into a from public.patient_anesthesia_records where id=selected and pet_id=p_pet_id and status='signed' for update;
  if not found then raise exception 'Only signed anesthesia records from this patient can be released' using errcode='23514';end if;
  anesthesia:=anesthesia||jsonb_build_array(jsonb_build_object('id',a.id,'version',a.version,'procedure_name',a.procedure_name,'started_at',a.started_at,'ended_at',a.ended_at,'team',a.team,'assessment',a.assessment,'plan',a.plan,'recovery_notes',a.recovery_notes,'observations',a.observations,'events',a.events,'source',a.source,'included_original_document_id',case when exists(select 1 from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v where v::uuid=a.original_document_id) then a.original_document_id else null end,'signed_by',a.signed_by,'signed_at',a.signed_at,'addenda',coalesce((select jsonb_agg(to_jsonb(x) order by x.recorded_at,x.id) from public.anesthesia_record_addenda x where record_id=a.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'lesion_ids','[]')) v order by v loop
  select * into l from public.patient_lesions where id=selected and pet_id=p_pet_id for update;
  if not found then raise exception 'Body-map history must belong to this patient' using errcode='23514';end if;
  lesions:=lesions||jsonb_build_array(jsonb_build_object('id',l.id,'version',l.version,'label',l.label,'observations',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'observed_at',o.observed_at,'label',o.label,'body_view',o.body_view,'x',o.x,'y',o.y,'length_mm',o.length_mm,'width_mm',o.width_mm,'depth_mm',o.depth_mm,'notes',o.notes,'created_by',o.created_by,'created_at',o.created_at,'photo_document_id',case when exists(select 1 from jsonb_array_elements_text(coalesce(p_selection->'document_ids','[]')) v where v::uuid=o.photo_document_id) then o.photo_document_id else null end,'corrections',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at,c.id) from public.patient_lesion_corrections c where c.observation_id=o.id),'[]')) order by o.observed_at,o.created_at,o.id) from public.patient_lesion_observations o where lesion_id=l.id),'[]')));
 end loop;
 base_selection:=p_selection-array['dental_ids','qol_ids','anesthesia_ids','lesion_ids'];
 result:=public.preview_record_release_v1(p_pet_id,p_client_id,p_channel,p_recipient,base_selection);
 s:=(result->'snapshot')||jsonb_build_object('schema_version',2,'dental_charts',dental,'qol_records',qol,'anesthesia_records',anesthesia,'lesions',lesions);
 return jsonb_build_object('snapshot',s,'source_hash',encode(sha256(convert_to(s::text,'UTF8')),'hex'));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';
end $$

create function public.preview_record_release(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare k text;ids jsonb;selected uuid;total integer:=0;added integer:=0;r jsonb;s jsonb;p public.patient_problems;w public.patient_weights;t public.patient_treatments;pet public.pets;problems jsonb:='[]';weights jsonb:='[]';treatments jsonb:='[]';summary jsonb:='[]';
begin
 perform public.clinical_require_staff();
 if p_selection is null or jsonb_typeof(p_selection)<>'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f not in ('encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids','problem_ids','weight_ids','treatment_ids','patient_summary_ids')) then raise exception 'Choose explicit release sources' using errcode='23514';end if;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids','problem_ids','weight_ids','treatment_ids','patient_summary_ids'] loop
  ids:=coalesce(p_selection->k,'[]');
  if jsonb_typeof(ids)<>'array' then raise exception 'Source selections must be arrays' using errcode='23514';end if;
  if jsonb_array_length(ids)>100 then raise exception 'Choose at most 100 records per source family' using errcode='23514';end if;
  if exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string') or (select count(*) from jsonb_array_elements_text(ids))<>(select count(distinct v::uuid) from jsonb_array_elements_text(ids) v) then raise exception 'Source IDs must be unique strings' using errcode='23514';end if;
  total:=total+jsonb_array_length(ids);
  if k in ('problem_ids','weight_ids','treatment_ids','patient_summary_ids') then added:=added+jsonb_array_length(ids);end if;
 end loop;
 if total=0 then raise exception 'Choose at least one source; nothing is included by default' using errcode='23514';end if;
 if added=0 then return public.preview_record_release_v2(p_pet_id,p_client_id,p_channel,p_recipient,p_selection-array['problem_ids','weight_ids','treatment_ids','patient_summary_ids']);end if;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'problem_ids','[]')) v order by v loop
  select * into p from public.patient_problems where id=selected and pet_id=p_pet_id for update;
  if not found then raise exception 'Diagnosis history must belong to this patient' using errcode='23514';end if;
  problems:=problems||jsonb_build_array(jsonb_build_object('id',p.id,'created_by',p.created_by,'created_at',p.created_at,'current',public.release_problem_fields(to_jsonb(p)),'history',coalesce((select jsonb_agg(jsonb_build_object('recorded_at',a.created_at,'recorded_by',a.user_id,'action',a.action,'before',case when a.old_data is not null then public.release_problem_fields(a.old_data) end,'after',case when a.new_data is not null then public.release_problem_fields(a.new_data) end) order by a.created_at,a.id) from public.audit_logs a where a.table_name='patient_problems' and a.record_id=p.id and (a.new_data->>'pet_id'=p_pet_id::text or a.old_data->>'pet_id'=p_pet_id::text)),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'weight_ids','[]')) v order by v loop
  select * into w from public.patient_weights where id=selected and pet_id=p_pet_id for share;
  if not found then raise exception 'Weight measurement must belong to this patient' using errcode='23514';end if;
  weights:=weights||jsonb_build_array(to_jsonb(w)-'pet_id');
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'treatment_ids','[]')) v order by v loop
  select * into t from public.patient_treatments where id=selected and pet_id=p_pet_id for update;
  if not found then raise exception 'Treatment history must belong to this patient' using errcode='23514';end if;
  treatments:=treatments||jsonb_build_array((to_jsonb(t)-array['request','pet_id','product_id','lot_id','invoice_id'])||jsonb_build_object('corrections',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at,c.id) from public.patient_treatment_corrections c where treatment_id=t.id),'[]')));
 end loop;
 for selected in select v::uuid from jsonb_array_elements_text(coalesce(p_selection->'patient_summary_ids','[]')) v loop
  select * into pet from public.pets where id=selected and id=p_pet_id for share;
  if not found then raise exception 'Patient summary must belong to this patient' using errcode='23514';end if;
  summary:=jsonb_build_array(jsonb_build_object('id',pet.id,'version',pet.version,'allergies',pet.allergies,'legacy_weight_lbs',pet.weight_lbs,'provenance','Existing patient profile; allergy verification and legacy weight measurement date are not recorded'));
 end loop;
 r:=public.preview_record_release_v2(p_pet_id,p_client_id,p_channel,p_recipient,p_selection-array['problem_ids','weight_ids','treatment_ids','patient_summary_ids']);
 s:=(r->'snapshot')||jsonb_build_object('schema_version',3,'problems',problems,'weights',weights,'treatments',treatments,'patient_summaries',summary);
 return jsonb_build_object('snapshot',s,'source_hash',encode(sha256(convert_to(s::text,'UTF8')),'hex'));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';
end $$

create or replace function public.confirm_record_release(p_id uuid,p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb,p_reviewed_snapshot jsonb,p_reviewed_hash text,p_attest_review boolean) returns public.record_releases language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.record_releases; preview jsonb; req jsonb; k text; source_type text;
begin
 if p_id is null or p_attest_review is distinct from true then raise exception 'Stable ID and explicit content/recipient review are required' using errcode='23514'; end if;
 req:=jsonb_build_object('pet_id',p_pet_id,'client_id',p_client_id,'channel',p_channel,'recipient',p_recipient,'selection',p_selection,'reviewed_snapshot',p_reviewed_snapshot,'reviewed_hash',p_reviewed_hash,'attest_review',p_attest_review);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,13));
 select * into result from public.record_releases where id=p_id;
 if found then if result.created_by<>actor or result.request is distinct from req then raise exception 'Release identifier already used' using errcode='23514'; end if; return result; end if;
 perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=coalesce((p_reviewed_snapshot->>'schema_version')::integer,3) for share;
 if not found then raise exception 'Clinical acceptance of the release form and workflow is required before confirmation' using errcode='42501'; end if;
 preview:=public.preview_record_release(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);
 if preview->'snapshot' is distinct from p_reviewed_snapshot or preview->>'source_hash' is distinct from p_reviewed_hash then raise exception 'Release sources or recipient changed; preview and review again' using errcode='40001'; end if;
 insert into public.record_releases(id,pet_id,client_id,channel,recipient,selection,snapshot,source_hash,request,created_by) values(p_id,p_pet_id,p_client_id,p_channel,preview#>>'{snapshot,recipient,address}',p_selection,p_reviewed_snapshot,p_reviewed_hash,req,actor) returning * into result;
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids','problem_ids','weight_ids','treatment_ids','patient_summary_ids'] loop
  source_type:=case k when 'encounter_ids' then 'encounter' when 'certificate_ids' then 'certificate' when 'lab_order_ids' then 'lab' when 'dental_ids' then 'dental' when 'qol_ids' then 'qol' when 'anesthesia_ids' then 'anesthesia' when 'lesion_ids' then 'lesion' when 'problem_ids' then 'problem' when 'weight_ids' then 'weight' when 'treatment_ids' then 'treatment' when 'patient_summary_ids' then 'patient_summary' else 'document' end;
  insert into public.record_release_sources(release_id,source_kind,source_id) select p_id,source_type,v::uuid from jsonb_array_elements_text(coalesce(p_selection->k,'[]')) v;
 end loop;
 return result;
end $$

create or replace function public.read_record_release(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.record_releases; events jsonb; eligible boolean:=true; why text; current_preview jsonb;
begin
 perform public.clinical_require_staff();
 select * into r from public.record_releases where id=p_id for share;
 if not found then raise exception 'Release not found' using errcode='23514'; end if;
 select coalesce(jsonb_agg(to_jsonb(e) order by created_at,id),'[]') into events from public.record_release_events e where release_id=p_id;
 if jsonb_array_length(events)>0 then eligible:=false;why:='Withdrawn or a reviewed source changed';
 else
  begin
   if r.snapshot->>'schema_version'='1' then current_preview:=public.preview_record_release_v1(r.pet_id,r.client_id,r.channel,r.recipient,r.selection); elsif r.snapshot->>'schema_version'='2' then current_preview:=public.preview_record_release_v2(r.pet_id,r.client_id,r.channel,r.recipient,r.selection); else current_preview:=public.preview_record_release(r.pet_id,r.client_id,r.channel,r.recipient,r.selection);end if;
   if current_preview->>'source_hash'<>r.source_hash then eligible:=false;why:='Current source snapshot differs';end if;
  exception when sqlstate '23514' or sqlstate '42501' then eligible:=false;why:='Source or recipient is no longer eligible';end;
 end if;
 return jsonb_build_object('release',to_jsonb(r)-'request','events',events,'eligible',eligible,'ineligibility_reason',why);
end $$

create function public.invalidate_record_release_history() returns trigger language plpgsql security definer set search_path=public as $$
declare kind text;source uuid;
begin
 if TG_TABLE_NAME='patient_problems' then kind:='problem';source:=NEW.id;
 elsif TG_TABLE_NAME='patient_treatment_corrections' then kind:='treatment';source:=NEW.treatment_id;
 end if;
 insert into public.record_release_events(id,release_id,kind,reason,created_by) select gen_random_uuid(),release_id,'source_changed','Reviewed '||kind||' history changed; prepare a fresh package',auth.uid() from public.record_release_sources where source_kind=kind and source_id=source;
 return NEW;
end $$

create or replace function public.list_record_release_sources(p_pet_id uuid,p_offset integer default 0) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.pets;c public.clients;r jsonb;k text;rows jsonb;query text;skip integer:=greatest(coalesce(p_offset,0),0);
begin
 perform public.clinical_require_staff();
 select * into p from public.pets where id=p_pet_id;
 if not found then raise exception 'Patient not found' using errcode='23514';end if;
 select * into c from public.clients where id=p.client_id;
 r:=jsonb_build_object('pet_id',p.id,'client_id',c.id,'client_name',c.full_name,'email',public.communication_recipient('EMAIL',c.primary_email),'phone',public.communication_recipient('SMS',c.primary_phone),'policy_accepted',exists(select 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=3));
 foreach k in array array['encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids','problem_ids','weight_ids','treatment_ids','patient_summary_ids'] loop
  query:=case k
   when 'encounter_ids' then 'select id,version,visit_at as recorded_at,''Signed SOAP · ''||visit_type as label from public.clinical_encounters where pet_id=$1 and status=''signed'''
   when 'certificate_ids' then 'select id,1 as version,issued_at as recorded_at,kind||'' certificate'' as label from public.vaccine_certificates c where pet_id=$1 and not exists(select 1 from public.vaccine_certificate_events e where e.certificate_id=c.id)'
   when 'lab_order_ids' then 'select id,version,updated_at as recorded_at,test_name as label,result_document_id as required_document_id from public.patient_lab_orders where pet_id=$1 and status=''resulted'''
   when 'document_ids' then 'select id,version,created_at as recorded_at,file_name as label,mime_type,file_size from public.patient_documents where pet_id=$1 and status=''ready'' and visibility=''client_shareable'''
   when 'dental_ids' then 'select id,version,visit_at as recorded_at,''Signed dental · ''||dentition as label from public.dental_charts where pet_id=$1 and status=''signed'''
   when 'qol_ids' then 'select id,version,observed_at as recorded_at,''Signed QOL · ''||observer as label from public.patient_qol_records where pet_id=$1 and status=''signed'''
   when 'anesthesia_ids' then 'select id,version,started_at as recorded_at,procedure_name as label from public.patient_anesthesia_records where pet_id=$1 and status=''signed'''
   when 'lesion_ids' then 'select id,version,updated_at as recorded_at,label from public.patient_lesions where pet_id=$1'
   when 'problem_ids' then 'select id,version,updated_at as recorded_at,case when importance=''high'' then ''IMPORTANT · '' else '''' end||title||'' · ''||status as label,importance from public.patient_problems where pet_id=$1'
   when 'weight_ids' then 'select id,1 as version,measured_at as recorded_at,weight::text||'' ''||unit as label from public.patient_weights where pet_id=$1'
   when 'treatment_ids' then 'select id,1 as version,administered_at as recorded_at,kind||'' · ''||product_name||case when exists(select 1 from public.patient_treatment_corrections c where c.treatment_id=t.id) then '' · CORRECTED HISTORY'' else '''' end as label from public.patient_treatments t where pet_id=$1'
   else 'select id,version,created_at as recorded_at,''Allergy summary and undated legacy profile weight'' as label from public.pets where id=$1' end;
  execute 'select coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) from ('||query||' order by recorded_at desc,id limit 100 offset $2) x' into rows using p_pet_id,skip;
  r:=r||jsonb_build_object(k,rows);
 end loop;
 return r;
end $$

create table public.contact_intake_budgets (
 bucket text not null,window_start timestamptz not null,attempts integer not null check(attempts>0),primary key(bucket,window_start)
)

create function public.consume_contact_intake_budget() returns boolean language plpgsql security definer set search_path=public as $$
declare minute_count integer;hour_count integer;
begin
 -- Global limits intentionally make no claim of verified per-person identity.
 insert into contact_intake_budgets values('global-minute',date_trunc('minute',now()),1) on conflict(bucket,window_start) do update set attempts=least(contact_intake_budgets.attempts+1,1000000) returning attempts into minute_count;
 insert into contact_intake_budgets values('global-hour',date_trunc('hour',now()),1) on conflict(bucket,window_start) do update set attempts=least(contact_intake_budgets.attempts+1,1000000) returning attempts into hour_count;
 delete from contact_intake_budgets where window_start<now()-interval '2 days';
 return minute_count<=120 and hour_count<=1000;
end $$

create function public.contact_intake_receipt(p_request_id uuid,p_capability_hash text) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 if p_request_id is null or p_capability_hash is null or p_capability_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid request proof' using errcode='23514';end if;
 return jsonb_build_object('received',exists(select 1 from contact_intake_requests where request_id=p_request_id and capability_hash=p_capability_hash));
end $$

create or replace function public.accept_contact_intake(p_request_id uuid,p_capability_hash text,p_email_budget_hash text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare prior public.contact_intake_requests;submission uuid;attempt_count integer;
begin
 if p_request_id is null or p_capability_hash is null or p_capability_hash !~ '^[a-f0-9]{64}$' or p_email_budget_hash is null or p_email_budget_hash !~ '^[a-f0-9]{64}$' or p_payload is null or jsonb_typeof(p_payload)<>'object' or p_payload-array['name','email','phone','subject','message']<>'{}'::jsonb or not(p_payload ?& array['name','email','phone','subject','message']) then raise exception 'Invalid intake payload' using errcode='23514';end if;
 if jsonb_typeof(p_payload->'name')<>'string' or jsonb_typeof(p_payload->'email')<>'string' or jsonb_typeof(p_payload->'subject')<>'string' or jsonb_typeof(p_payload->'message')<>'string' or jsonb_typeof(p_payload->'phone') not in ('string','null') then raise exception 'Invalid intake field types' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('contact-intake:'||p_request_id::text,0));
 select * into prior from contact_intake_requests where request_id=p_request_id;
 if found then
  if prior.capability_hash<>p_capability_hash or prior.payload<>p_payload then raise exception 'Request ID already used with different content or proof' using errcode='23505';end if;
  return jsonb_build_object('received',true);
 end if;
 -- Claimed email is an abuse bucket, never sender authentication or consent.
 insert into contact_intake_budgets values('email:'||p_email_budget_hash,date_trunc('hour',now()),1) on conflict(bucket,window_start) do update set attempts=least(contact_intake_budgets.attempts+1,1000000) returning attempts into attempt_count;
 if attempt_count>5 then return jsonb_build_object('received',false,'limited',true);end if;
 insert into contact_submissions(name,email,phone,subject,message) values(p_payload->>'name',p_payload->>'email',p_payload->>'phone',p_payload->>'subject',p_payload->>'message') returning id into submission;
 insert into contact_intake_requests(request_id,capability_hash,payload,submission_id) values(p_request_id,p_capability_hash,p_payload,submission);
 return jsonb_build_object('received',true);
end $$

do $$ declare f record;begin
 for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname in ('consume_contact_intake_budget','contact_intake_receipt','accept_contact_intake') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $$

do $$ declare name text;definition text;begin
 foreach name in array array['preview_record_release_v1','preview_record_release_v2','release_preview_internal','release_read_internal'] loop
  select pg_get_functiondef(p.oid) into definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=name;
  if definition is null or position('perform public.clinical_require_staff();' in definition)=0 then raise exception 'Expected release staff wrapper not found: %',name;end if;
  definition:=replace(definition,'perform public.clinical_require_staff();','');
  if name='release_read_internal' then definition:=replace(definition,'public.preview_record_release(','public.release_preview_internal(');end if;
  execute definition;
 end loop;
end $$

create function public.guard_release_email_history() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='UPDATE' and TG_TABLE_NAME='release_email_payloads' then
 if current_user='postgres' and OLD.payload_text is not null and NEW.payload_text is null and NEW.purged_at=now() and (to_jsonb(NEW)-array['payload_text','purged_at'])=(to_jsonb(OLD)-array['payload_text','purged_at']) and OLD.captured_at<now()-interval '90 days' then return NEW;end if;
 end if;
 if TG_OP='UPDATE' and TG_TABLE_NAME='release_email_requests' then
 if (to_jsonb(NEW)-'state')=(to_jsonb(OLD)-'state') and ((OLD.state='preparing' and NEW.state in ('ready','abandoned')) or (OLD.state='ready' and NEW.state in ('queued','abandoned'))) then return NEW;end if;
 end if;
 raise exception 'Release email history is immutable' using errcode='23514';
end $$

do $$ declare t text;begin
 foreach t in array array['release_email_requests','release_email_payloads','release_email_outbox_links'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('create trigger release_email_immutable before update or delete on public.%I for each row execute function public.guard_release_email_history()',t);
 end loop;
end $$

-- Private core: every service call supplies an immutable request, never an arbitrary recipient.
create function public.release_email_context(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.release_email_requests;b jsonb;
begin
 select * into r from public.release_email_requests where id=p_request_id for share;
 if not found or r.state='abandoned' or not public.is_active_staff(r.actor_id) then raise exception 'Release email actor or request is unavailable' using errcode='42501';end if;
 perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=(select (snapshot->>'schema_version')::integer from public.record_releases where id=r.release_id) for share;
 if not found then raise exception 'Clinical release acceptance is not active' using errcode='42501';end if;
 b:=public.release_read_internal(r.release_id);
 if (b->>'eligible')::boolean is distinct from true or b#>>'{release,source_hash}' is distinct from r.release_hash or b#>>'{release,client_id}' is distinct from r.client_id::text or b#>>'{release,channel}' is distinct from 'EMAIL' or b#>>'{release,recipient}' is distinct from r.recipient
 or not exists(select 1 from public.conversations where id=r.conversation_id and client_id=r.client_id)
 or public.communication_is_suppressed('EMAIL',r.recipient,r.client_id) then raise exception 'Release, household or recipient is no longer eligible' using errcode='42501';end if;
 return b;
end $$

create function public.recover_release_email(p_release_id uuid,p_request_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.release_email_requests;p public.release_email_payloads;o public.communication_outbox;
begin
 select * into r from public.release_email_requests where actor_id=actor and release_id=p_release_id and ((p_request_id is null and state<>'abandoned') or id=p_request_id) order by created_at desc,id limit 1;
 if not found then return null;end if;
 select * into p from public.release_email_payloads where request_id=r.id;
 select box.* into o from public.communication_outbox box join public.release_email_outbox_links l on l.outbox_id=box.id where l.request_id=r.id;
 return jsonb_build_object('request',to_jsonb(r),'payload_hash',p.payload_hash,'manifest',p.manifest,
 'purged_at',p.purged_at,'report_html',case when p.payload_text is not null then convert_from(decode((p.payload_text::jsonb)#>>'{attachments,0,content}','base64'),'UTF8') end,
 'receipt',case when o.id is not null then jsonb_build_object('outbox_id',o.id,'message_id',o.message_id,'state',o.state,'queued',true,'delivered',o.state='delivered') end);
end $$

create function public.prepare_release_email(p_request_id uuid,p_release_id uuid,p_conversation_id uuid,p_subject text,p_body text,p_release_hash text) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.release_email_requests;b jsonb;client uuid;recipient text;
begin
 if p_request_id is null or p_release_hash is null or p_release_hash !~ '^[a-f0-9]{64}$' or p_subject is null or length(trim(p_subject)) not between 1 and 500 or p_body is null or length(trim(p_body)) not between 1 and 100000 then raise exception 'Stable request ID and complete email intent are required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,2200));
 select * into r from public.release_email_requests where id=p_request_id;
 if found then
  if r.actor_id<>actor or row(r.release_id,r.conversation_id,r.subject,r.body,r.release_hash) is distinct from row(p_release_id,p_conversation_id,p_subject,p_body,p_release_hash) or r.state='abandoned' then raise exception 'Release email request already used or abandoned' using errcode='23505';end if;
  return public.recover_release_email(p_release_id,p_request_id);
 end if;
 select client_id into client from public.conversations where id=p_conversation_id;
 select record.recipient into recipient from public.record_releases record where id=p_release_id and channel='EMAIL';
 b:=public.authorize_record_release(p_release_id,client,'EMAIL',recipient);
 if b#>>'{release,source_hash}' is distinct from p_release_hash or public.communication_is_suppressed('EMAIL',recipient,client) then raise exception 'Reviewed release or recipient is no longer eligible' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_release_id::text,2200));
 if exists(select 1 from public.release_email_requests where actor_id=actor and release_id=p_release_id and state in ('preparing','ready')) then raise exception 'Recover or abandon the unresolved release email first' using errcode='23505';end if;
 insert into public.release_email_requests(id,release_id,actor_id,conversation_id,client_id,recipient,subject,body,release_hash) values(p_request_id,p_release_id,actor,p_conversation_id,client,recipient,p_subject,p_body,p_release_hash);
 return public.recover_release_email(p_release_id,p_request_id);
end $$

create function public.release_email_capture_context(p_request_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.release_email_requests;
begin perform public.communication_require_service();select * into r from public.release_email_requests where id=p_request_id;
 if not found or r.actor_id is distinct from p_actor_id then raise exception 'Request ownership mismatch' using errcode='42501';end if;
 return jsonb_build_object('request',to_jsonb(r),'bundle',public.release_email_context(p_request_id),'captured',exists(select 1 from public.release_email_payloads where request_id=p_request_id));end $$

create function public.capture_release_email_payload(p_request_id uuid,p_actor_id uuid,p_payload_text text) returns void language plpgsql security definer set search_path=public as $$
declare r public.release_email_requests;existing public.release_email_payloads;b jsonb;payload jsonb;a jsonb;doc jsonb;decoded bytea;manifest jsonb:='[]';i integer:=0;hash text;filename text;
begin
 perform public.communication_require_service();
 if p_payload_text is null or octet_length(p_payload_text) not between 1 and 33554432 then raise exception 'Encoded email exceeds application limits' using errcode='23514';end if;
 select * into r from public.release_email_requests where id=p_request_id for update;
 if not found or r.actor_id is distinct from p_actor_id or r.state='abandoned' or not public.is_active_staff(r.actor_id) then raise exception 'Request ownership mismatch or abandoned' using errcode='42501';end if;
 b:=public.release_email_context(p_request_id);
 hash:=encode(sha256(convert_to(p_payload_text,'UTF8')),'hex');
 select * into existing from public.release_email_payloads where request_id=p_request_id;
 if found then if existing.payload_text is distinct from p_payload_text then raise exception 'Captured provider payload is immutable' using errcode='23505';end if;return;end if;
 b:=public.release_email_context(p_request_id);payload:=p_payload_text::jsonb;
 if jsonb_typeof(payload)<>'object' or payload-array['from','reply_to','to','subject','text','attachments']<>'{}' or payload->'to' is distinct from jsonb_build_array(r.recipient) or payload->>'subject' is distinct from r.subject or payload->>'text' is distinct from r.body or public.communication_recipient('EMAIL',payload->>'reply_to') is null or jsonb_typeof(payload->'from') is distinct from 'string' or length(payload->>'from') not between 1 and 500 or public.communication_recipient('EMAIL',coalesce(substring(payload->>'from' from '<([^<>]+)>$'),payload->>'from')) is null then raise exception 'Provider payload differs from reviewed email intent' using errcode='23514';end if;
 if jsonb_typeof(payload->'attachments') is distinct from 'array' then raise exception 'Frozen attachments are required' using errcode='23514';end if;
 if jsonb_array_length(payload->'attachments')<>jsonb_array_length(b#>'{release,snapshot,attachments}')+1 or jsonb_array_length(payload->'attachments')>25 then raise exception 'Attachment manifest must exactly match the release and report within 25 files' using errcode='23514';end if;
 for a in select value from jsonb_array_elements(payload->'attachments') loop
  if jsonb_typeof(a)<>'object' or a-array['filename','content_type','content']<>'{}' or jsonb_typeof(a->'filename') is distinct from 'string' or jsonb_typeof(a->'content') is distinct from 'string' or a->>'filename' ~ '[[:cntrl:]/\\]' or length(a->>'filename') not between 1 and 180 or a->>'content' !~ '^[A-Za-z0-9+/]*={0,2}$' then raise exception 'Attachment metadata is invalid' using errcode='23514';end if;
  decoded:=decode(a->>'content','base64');
  if octet_length(decoded)<1 then raise exception 'Empty attachment rejected' using errcode='23514';end if;
  if i=0 then
   if a->>'filename' is distinct from 'medical-records-'||r.release_id::text||'.html' or a->>'content_type' is distinct from 'text/html' then raise exception 'Rendered report must be a truthful HTML attachment' using errcode='23514';end if;
   perform convert_from(decoded,'UTF8');
  else
   doc:=(b#>'{release,snapshot,attachments}')->(i-1);
   filename:=i::text||'-'||coalesce(nullif(left(trim(both ' .' from regexp_replace(regexp_replace(doc->>'file_name','\.[^.]*$',''),'[^A-Za-z0-9 _.-]','_','g')),100),''),'record')||case doc->>'mime_type' when 'application/pdf' then '.pdf' when 'image/jpeg' then '.jpg' when 'image/png' then '.png' else null end;
   if a->>'filename' is distinct from filename or a->>'content_type' is distinct from doc->>'mime_type' or octet_length(decoded)::bigint is distinct from (doc->>'file_size')::bigint then raise exception 'Original attachment metadata differs from release' using errcode='23514';end if;
  end if;
  manifest:=manifest||jsonb_build_array(jsonb_build_object('filename',a->>'filename','mime_type',a->>'content_type','file_size',octet_length(decoded),'sha256',encode(sha256(decoded),'hex'),'document_id',case when i>0 then doc->'id' else null end));i:=i+1;
 end loop;
 insert into public.release_email_payloads(request_id,payload_text,payload_hash,manifest) values(p_request_id,p_payload_text,hash,manifest);
 update public.release_email_requests set state='ready' where id=p_request_id;
exception when invalid_text_representation or character_not_in_repertoire then raise exception 'Malformed frozen email payload' using errcode='23514';
end $$

create function public.enqueue_release_email(p_request_id uuid,p_reviewed_payload_hash text,p_attest boolean) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.release_email_requests;p public.release_email_payloads;l public.release_email_outbox_links;o public.communication_outbox;
begin
 if p_attest is distinct from true then raise exception 'Review the exact report, originals and message before queueing' using errcode='23514';end if;
 select * into r from public.release_email_requests where id=p_request_id for update;
 select * into p from public.release_email_payloads where request_id=p_request_id;
 if r.id is null or r.actor_id<>actor or r.state='abandoned' or p.request_id is null or p.payload_hash is distinct from p_reviewed_payload_hash then raise exception 'Prepared release email or reviewed payload does not match' using errcode='42501';end if;
 select * into l from public.release_email_outbox_links where request_id=p_request_id;
 if found then select * into o from public.communication_outbox where id=l.outbox_id;return o;end if;
 perform public.release_email_context(p_request_id);
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,914));
 if exists(select 1 from public.communication_outbox where request_id=p_request_id) then raise exception 'Request ID already belongs to another queue workflow' using errcode='23505';end if;
 o:=public.enqueue_prepared_communication_internal(actor,r.id,r.conversation_id,'EMAIL',r.recipient,r.subject,r.body,'{}');
 insert into public.release_email_outbox_links(outbox_id,request_id,reviewed_payload_hash,queued_by) values(o.id,r.id,p.payload_hash,actor);
 update public.release_email_requests set state='queued' where id=r.id;
 return o;
end $$

create function public.abandon_release_email(p_request_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.release_email_requests;
begin select * into r from public.release_email_requests where id=p_request_id for update;
 if not found or r.actor_id<>actor or r.state='queued' then raise exception 'Only own unqueued preparation can be abandoned' using errcode='42501';end if;
 if r.state<>'abandoned' then update public.release_email_requests set state='abandoned' where id=p_request_id;end if;end $$

create function public.read_release_email_payload(p_outbox_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;l public.release_email_outbox_links;p public.release_email_payloads;
begin perform public.communication_require_service();select * into o from public.communication_outbox where id=p_outbox_id;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 select * into l from public.release_email_outbox_links where outbox_id=o.id;
 if not found then return null;end if;
 perform public.release_email_context(l.request_id);
 select * into p from public.release_email_payloads where request_id=l.request_id;
 if not found or p.payload_text is null or l.reviewed_payload_hash<>p.payload_hash then raise exception 'Frozen release payload unavailable' using errcode='23514';end if;
 return jsonb_build_object('payload_text',p.payload_text,'payload_hash',p.payload_hash);
end $$

create function public.start_communication_attempt(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;l public.release_email_outbox_links;p public.release_email_payloads;payload jsonb;valid boolean:=true;
begin perform public.communication_require_service();select * into o from public.communication_outbox where id=p_id for update;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 select * into l from public.release_email_outbox_links where outbox_id=o.id;
 if found then
  begin
   perform public.release_email_context(l.request_id);
   select * into p from public.release_email_payloads where request_id=l.request_id;
   payload:=p.payload_text::jsonb;
   valid:=p.request_id is not null and p.payload_hash=l.reviewed_payload_hash and p.payload_hash=encode(sha256(convert_to(p.payload_text,'UTF8')),'hex') and payload->>'from'=p_provider_config->>'from' and payload->>'reply_to'=p_provider_config->>'reply_to';
  exception when sqlstate '23514' or sqlstate '42501' then valid:=false;end;
  if valid is distinct from true then update public.communication_outbox set state='failed',last_error='release_source_or_payload_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=o.id returning * into o;return o;end if;
 end if;
 return public.start_communication_attempt_without_release_guard(p_id,p_lease_token,p_provider_config);
end $$

do $$ declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('guard_release_email_history','audit_release_email','release_email_context','recover_release_email','prepare_release_email','release_email_capture_context','capture_release_email_payload','enqueue_release_email','abandon_release_email','read_release_email_payload','start_communication_attempt') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('recover_release_email','prepare_release_email','enqueue_release_email','abandon_release_email') then execute format('grant execute on function %s to authenticated',f.signature);
  elsif f.proname in ('release_email_capture_context','capture_release_email_payload','read_release_email_payload','start_communication_attempt') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

create function public.read_release_email_attachment(p_request_id uuid,p_index integer) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();p public.release_email_payloads;
begin
 if p_index is null or p_index not between 0 and 24 or not exists(select 1 from public.release_email_requests where id=p_request_id and actor_id=actor) then raise exception 'Attachment request unavailable' using errcode='42501';end if;
 select * into p from public.release_email_payloads where request_id=p_request_id;
 if p.payload_text is null or p_index>=jsonb_array_length(p.manifest) then raise exception 'Frozen attachment unavailable or expired' using errcode='23514';end if;
 return (p.payload_text::jsonb->'attachments')->p_index;
end $$

-- Retain hash/manifest/review/receipt evidence. Never purge pending or uncertain delivery bytes.
create function public.purge_expired_release_email_payloads(p_limit integer default 100) returns integer language plpgsql security definer set search_path=public as $$
declare count_purged integer;
begin perform public.communication_require_service();
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'Purge limit must be 1 to 100' using errcode='23514';end if;
 with expired as(select p.request_id from public.release_email_payloads p join public.release_email_requests r on r.id=p.request_id where p.payload_text is not null and p.captured_at<now()-interval '90 days' and (r.state='abandoned' or exists(select 1 from public.release_email_outbox_links l join public.communication_outbox o on o.id=l.outbox_id where l.request_id=r.id and o.state in ('accepted','delivered') and o.provider_message_id is not null)) order by p.captured_at limit p_limit for update of p skip locked)
 update public.release_email_payloads set payload_text=null,purged_at=now() where request_id in(select request_id from expired);
 get diagnostics count_purged=row_count;return count_purged;
end $$

create table public.ezyvet_weight_runs (
 run_id uuid primary key references public.ezyvet_import_runs(id),animal_link_id uuid not null references public.ezyvet_record_links(id),created_at timestamptz not null default now()
)

create function public.prepare_ezyvet_weight_request(p_request_id uuid,p_snapshot_id uuid,p_payload jsonb) returns public.ezyvet_weight_requests language plpgsql security definer set search_path=public as $$
declare r public.ezyvet_weight_requests;begin
 if public.ezyvet_is_active_admin(auth.uid()) is not true then raise exception 'Active administrator required' using errcode='42501';end if;
 if p_request_id is null or p_payload is null or jsonb_typeof(p_payload)<>'object' or p_payload->>'snapshot_id' is distinct from p_snapshot_id::text or octet_length(p_payload::text)>10000 then raise exception 'Invalid weight preparation' using errcode='23514';end if;
 perform 1 from ezyvet_import_snapshots where id=p_snapshot_id and resource='healthstatus';if not found then raise exception 'Weight source required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('weight-approval:'||p_request_id::text,0));
 select * into r from ezyvet_weight_requests where request_id=p_request_id;
 if found then if r.actor_id<>auth.uid() or r.snapshot_id<>p_snapshot_id or r.payload is distinct from p_payload or r.status='abandoned' then raise exception 'Prepared request cannot change or revive' using errcode='42501';end if;return r;end if;
 insert into ezyvet_weight_requests(request_id,actor_id,snapshot_id,payload,status) values(p_request_id,auth.uid(),p_snapshot_id,p_payload,'prepared') returning * into r;return r;
end $$

do $$declare t text;begin foreach t in array array['ezyvet_weight_runs','ezyvet_weight_approvals','ezyvet_weight_source_reviews'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('grant select on public.%I to authenticated,service_role',t);
 execute format('create policy "Administrator weight import read" on public.%I for select to authenticated using(public.ezyvet_is_active_admin(auth.uid()))',t);
 execute format('create trigger immutable_weight_import before update or delete on public.%I for each row execute function public.guard_inquiry_history()',t);
end loop;end $$

create function public.claim_ezyvet_weight_import(p_id uuid,p_actor uuid,p_site_uid text,p_source_origin text,p_animal_link_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare link public.ezyvet_record_links;r public.ezyvet_import_runs;context public.ezyvet_weight_runs;
begin
 if public.ezyvet_is_active_admin(p_actor) is not true then raise exception 'Active administrator required' using errcode='42501';end if;
 select * into link from public.ezyvet_record_links where id=p_animal_link_id and resource='animal' and source_origin=p_source_origin and source_site_uid=p_site_uid for share;
 if not found or link.external_id !~ '^[0-9]+$' or not exists(select 1 from public.pets where id=link.pet_id and client_id=link.client_id) then raise exception 'Reviewed patient mapping required for this source site' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('weight-run:'||p_id::text,0));
 select * into context from public.ezyvet_weight_runs where run_id=p_id;
 if found and context.animal_link_id<>p_animal_link_id then raise exception 'Import mapping cannot change' using errcode='42501';end if;
 r:=public.claim_ezyvet_import_core(p_id,p_actor,p_site_uid,'healthstatus',p_source_origin);
 insert into public.ezyvet_weight_runs(run_id,animal_link_id) values(p_id,p_animal_link_id) on conflict(run_id) do nothing;
 return to_jsonb(r)||jsonb_build_object('animal_external_id',link.external_id,'animal_link_id',link.id);
end $$

create function public.stage_ezyvet_import_page(p_id uuid,p_actor uuid,p_lease_id uuid,p_page integer,p_complete boolean,p_items jsonb) returns public.ezyvet_import_runs language plpgsql security definer set search_path=public as $$
declare r public.ezyvet_import_runs;link public.ezyvet_record_links;
begin
 select * into strict r from public.ezyvet_import_runs where id=p_id;
 if r.resource='healthstatus' then
  select l.* into link from public.ezyvet_weight_runs w join public.ezyvet_record_links l on l.id=w.animal_link_id where w.run_id=p_id;
  if not found or p_items is null or jsonb_typeof(p_items)<>'array' then raise exception 'Patient-scoped page required' using errcode='23514';end if;
  if exists(select 1 from jsonb_array_elements(p_items) x where x#>>'{payload,animal_id}' is distinct from link.external_id) then raise exception 'Source patient mismatch' using errcode='23514';end if;
 end if;
 return public.stage_ezyvet_import_page_core(p_id,p_actor,p_lease_id,p_page,p_complete,p_items);
end $$

create function public.search_ezyvet_weight_patients(p_search text,p_limit integer default 20) returns table(link_id uuid,pet_id uuid,patient_name text,household_name text,source_origin text,source_site_uid text,external_id text,patient_version integer) language plpgsql stable security definer set search_path=public as $$
begin
 if public.ezyvet_is_active_admin(auth.uid()) is not true then raise exception 'Active administrator required' using errcode='42501';end if;
 if p_search is null or length(trim(p_search))<2 or length(p_search)>200 or p_limit is null or p_limit not between 1 and 50 then raise exception 'Enter a bounded patient search' using errcode='23514';end if;
 return query select l.id,p.id,p.name,c.full_name,l.source_origin,l.source_site_uid,l.external_id,p.version from ezyvet_record_links l join pets p on p.id=l.pet_id and p.client_id=l.client_id join clients c on c.id=p.client_id where l.resource='animal' and (p.name ilike '%'||trim(p_search)||'%' or c.full_name ilike '%'||trim(p_search)||'%') order by p.name,l.id limit p_limit;
end $$

create function public.list_ezyvet_weight_candidates(p_animal_link_id uuid,p_before_at timestamptz default null,p_before_id uuid default null,p_limit integer default 20) returns setof jsonb language plpgsql stable security definer set search_path=public as $$
declare link public.ezyvet_record_links;
begin
 if public.ezyvet_is_active_admin(auth.uid()) is not true then raise exception 'Active administrator required' using errcode='42501';end if;
 if p_limit is null or p_limit not between 1 and 50 or (p_before_at is null)<>(p_before_id is null) then raise exception 'Invalid cursor' using errcode='23514';end if;
 select * into strict link from ezyvet_record_links where id=p_animal_link_id and resource='animal';
 return query select to_jsonb(s)||jsonb_build_object('head_version',h.version,'current_snapshot_id',h.snapshot_id,'approval_id',a.request_id,'weight_id',a.weight_id,'approved_snapshot_id',a.snapshot_id,'patient_version',p.version)
 from ezyvet_import_snapshots s join ezyvet_identity_heads h on h.source_origin=s.source_origin and h.source_site_uid=s.source_site_uid and h.resource=s.resource and h.external_id=s.external_id
 join pets p on p.id=link.pet_id and p.client_id=link.client_id
 left join ezyvet_weight_approvals a on a.source_origin=s.source_origin and a.source_site_uid=s.source_site_uid and a.external_id=s.external_id
 where s.source_origin=link.source_origin and s.source_site_uid=link.source_site_uid and s.resource='healthstatus' and s.payload->>'animal_id'=link.external_id and (p_before_at is null or (s.created_at,s.id)<(p_before_at,p_before_id)) order by s.created_at desc,s.id desc limit p_limit;
end $$

create function public.resolve_ezyvet_weight_request(p_request_id uuid,p_snapshot_id uuid,p_discard boolean) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.ezyvet_weight_requests;a public.ezyvet_weight_approvals;begin
 if public.ezyvet_is_active_admin(auth.uid()) is not true then raise exception 'Active administrator required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('weight-approval:'||p_request_id::text,0));
 select * into r from ezyvet_weight_requests where request_id=p_request_id;
 if found and (r.actor_id<>auth.uid() or r.snapshot_id<>p_snapshot_id) then raise exception 'Request owner mismatch' using errcode='42501';end if;
 select * into a from ezyvet_weight_approvals where request_id=p_request_id and approved_by=auth.uid();
 if found then update ezyvet_weight_requests set status='completed' where request_id=p_request_id;return jsonb_build_object('approved',true,'weight_id',a.weight_id);end if;
 if p_discard is distinct from true then raise exception 'Unconfirmed approval needs explicit discard or recovery' using errcode='23514';end if;
 insert into ezyvet_weight_requests(request_id,actor_id,snapshot_id,payload,status) values(p_request_id,auth.uid(),p_snapshot_id,null,'abandoned') on conflict(request_id) do update set status='abandoned';
 return jsonb_build_object('approved',false,'abandoned',true);
end $$

create function public.approve_ezyvet_weight(p_request_id uuid,p_actor_id uuid,p_snapshot_id uuid,p_expected_hash text,p_head_version integer,p_animal_link_id uuid,p_patient_version integer,p_action text,p_weight_id uuid,p_weight numeric,p_unit text,p_measured_at date,p_confirmed boolean,p_reason text) returns public.ezyvet_weight_approvals language plpgsql security definer set search_path=public,extensions as $$
declare actor uuid:=auth.uid();fingerprint text;s public.ezyvet_import_snapshots;h public.ezyvet_identity_heads;link public.ezyvet_record_links;w public.patient_weights;r public.ezyvet_weight_approvals;
begin
 if actor is distinct from p_actor_id or public.ezyvet_is_active_admin(actor) is not true then raise exception 'Active administrator actor required' using errcode='42501';end if;
 if p_request_id is null or p_confirmed is distinct from true or p_action is null or p_action not in ('create','link') or p_reason is null or length(trim(p_reason)) not between 5 and 2000 or p_weight is null or p_weight::text in ('NaN','Infinity','-Infinity') or p_weight<=0 or p_weight>10000 or p_unit is null or p_unit not in ('kg','lb') or p_measured_at is null or not isfinite(p_measured_at) or p_measured_at>(now() at time zone 'America/Denver')::date then raise exception 'Review finite weight, unit, date, identity and reason' using errcode='23514';end if;
 fingerprint:=encode(digest(jsonb_build_array(p_snapshot_id,p_expected_hash,p_head_version,p_animal_link_id,p_patient_version,p_action,p_weight_id,p_weight,p_unit,p_measured_at,p_reason)::text,'sha256'),'hex');
 perform pg_advisory_xact_lock(hashtextextended('weight-approval:'||p_request_id::text,0));
 select * into r from ezyvet_weight_approvals where request_id=p_request_id;
 if found then if r.approved_by<>actor or r.request_hash<>fingerprint then raise exception 'Approval ID belongs to a different request' using errcode='42501';end if;return r;end if;
 if not exists(select 1 from ezyvet_weight_requests where request_id=p_request_id and actor_id=actor and snapshot_id=p_snapshot_id and status='prepared' and payload=jsonb_build_object('snapshot_id',p_snapshot_id,'expected_hash',p_expected_hash,'head_version',p_head_version,'animal_link_id',p_animal_link_id,'patient_version',p_patient_version,'action',p_action,'weight_id',p_weight_id,'weight',p_weight,'unit',p_unit,'measured_at',p_measured_at,'reason',p_reason)) then raise exception 'Exact prepared weight request required' using errcode='42501';end if;
 select * into strict s from ezyvet_import_snapshots where id=p_snapshot_id and resource='healthstatus';
 if coalesce(s.payload->>'active','') not in ('true','1') then raise exception 'Only an active source observation can create or link a weight' using errcode='23514';end if;
 select * into h from ezyvet_identity_heads where source_origin=s.source_origin and source_site_uid=s.source_site_uid and resource=s.resource and external_id=s.external_id for update;
 if h.snapshot_id is distinct from s.id or h.version is distinct from p_head_version or s.payload_hash is distinct from p_expected_hash then raise exception 'Source changed; review current observation' using errcode='40001';end if;
 select * into link from ezyvet_record_links where id=p_animal_link_id and resource='animal' and source_origin=s.source_origin and source_site_uid=s.source_site_uid and external_id=s.payload->>'animal_id' for share;
 if not found then raise exception 'Source patient mapping mismatch' using errcode='42501';end if;
 perform 1 from pets where id=link.pet_id and client_id=link.client_id and version=p_patient_version for share;
 if not found then raise exception 'Patient changed; review mapping again' using errcode='40001';end if;
 if exists(select 1 from ezyvet_weight_approvals where source_origin=s.source_origin and source_site_uid=s.source_site_uid and external_id=s.external_id) then raise exception 'Source already approved; review changes without replacing local history' using errcode='23505';end if;
 if p_action='create' then
  if p_weight_id is not null then raise exception 'New weight cannot specify existing target' using errcode='23514';end if;
  w:=public.record_patient_weight(link.pet_id,p_weight,p_unit,p_measured_at);
 else
  select * into w from patient_weights where id=p_weight_id and pet_id=link.pet_id and weight=p_weight and unit=p_unit and measured_at=p_measured_at for share;
  if not found then raise exception 'Existing weight must match reviewed patient and values exactly' using errcode='23514';end if;
 end if;
 insert into ezyvet_weight_approvals(request_id,request_hash,source_origin,source_site_uid,external_id,snapshot_id,head_version,animal_link_id,pet_id,patient_version,weight_id,action,reviewed_values,reason,approved_by)
 values(p_request_id,fingerprint,s.source_origin,s.source_site_uid,s.external_id,s.id,h.version,link.id,link.pet_id,p_patient_version,w.id,p_action,jsonb_build_object('weight',p_weight,'unit',p_unit,'measured_at',p_measured_at),trim(p_reason),actor) returning * into r;
 update ezyvet_weight_requests set status='completed' where request_id=p_request_id;
 return r;
end $$

create function public.review_ezyvet_weight_change(p_request_id uuid,p_approval_id uuid,p_snapshot_id uuid,p_head_version integer,p_reason text) returns public.ezyvet_weight_source_reviews language plpgsql security definer set search_path=public as $$
declare a public.ezyvet_weight_approvals;s public.ezyvet_import_snapshots;h public.ezyvet_identity_heads;r public.ezyvet_weight_source_reviews;
begin
 if public.ezyvet_is_active_admin(auth.uid()) is not true then raise exception 'Active administrator required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('weight-change:'||p_request_id::text,0));
 select * into r from ezyvet_weight_source_reviews where request_id=p_request_id;
 if found then if row(r.approval_id,r.snapshot_id,r.head_version,r.reason,r.reviewed_by) is distinct from row(p_approval_id,p_snapshot_id,p_head_version,trim(p_reason),auth.uid()) then raise exception 'Review ID mismatch' using errcode='42501';end if;return r;end if;
 select * into strict a from ezyvet_weight_approvals where request_id=p_approval_id;
 select * into strict s from ezyvet_import_snapshots where id=p_snapshot_id and resource='healthstatus' and source_origin=a.source_origin and source_site_uid=a.source_site_uid and external_id=a.external_id;
 select * into h from ezyvet_identity_heads where source_origin=s.source_origin and source_site_uid=s.source_site_uid and resource=s.resource and external_id=s.external_id for share;
 if h.snapshot_id is distinct from s.id or h.version is distinct from p_head_version then raise exception 'Source changed; review current observation' using errcode='40001';end if;
 insert into ezyvet_weight_source_reviews(request_id,approval_id,snapshot_id,head_version,reason,reviewed_by) values(p_request_id,a.request_id,s.id,h.version,trim(p_reason),auth.uid()) returning * into r;return r;
end $$

do $$declare f record;begin
 for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in ('claim_ezyvet_import','claim_ezyvet_weight_import','stage_ezyvet_import_page','search_ezyvet_weight_patients','list_ezyvet_weight_candidates','approve_ezyvet_weight','review_ezyvet_weight_change','prepare_ezyvet_weight_request','resolve_ezyvet_weight_request') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 execute format('grant execute on function %s to %I',f.signature,case when f.proname in ('claim_ezyvet_import','claim_ezyvet_weight_import','stage_ezyvet_import_page') then 'service_role' else 'authenticated' end);
 end loop;
end $$

create function public.read_weight_import_provenance(p_pet_id uuid,p_weight_ids uuid[]) returns table(weight_id uuid,source_record_id text,source_weight text,source_unit text,source_timestamp text,reviewed_at timestamptz,reviewer_name text,reviewed_measurement_date text) language plpgsql stable security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 if p_pet_id is null or p_weight_ids is null or cardinality(p_weight_ids)>50 then raise exception 'Bounded patient weight list required' using errcode='23514';end if;
 return query select a.weight_id,a.external_id,s.payload->>'weight',s.payload->>'weight_unit',s.payload->>'timestamp',a.created_at,p.full_name,a.reviewed_values->>'measured_at'
 from ezyvet_weight_approvals a join ezyvet_import_snapshots s on s.id=a.snapshot_id join profiles p on p.id=a.approved_by
 where a.pet_id=p_pet_id and a.weight_id=any(p_weight_ids);
end $$

-- Stopping delivery must not depend on an active wording template.
create function public.disable_reminder_automation_policy(p_id uuid,p_expected_version integer,p_review_note text)
returns public.reminder_automation_policies language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.care_require_admin();r public.reminder_automation_policies;
begin
 if p_id is null or p_expected_version is null or p_review_note is null or length(trim(p_review_note)) not between 1 and 2000 then
  raise exception 'Policy version and review reason are required' using errcode='23514';
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,18));
 select * into r from public.reminder_automation_policies where id=p_id for update;
 if not found then raise exception 'Policy unavailable' using errcode='23514';end if;
 if r.approved_by=actor and r.version=p_expected_version+1 and not r.enabled and r.review_note=trim(p_review_note) then return r;end if;
 if r.version<>p_expected_version then raise exception 'Automation policy version conflict' using errcode='40001';end if;
 update public.reminder_automation_policies set enabled=false,version=version+1,review_note=trim(p_review_note),approved_by=actor,approved_at=now() where id=p_id returning * into r;
 insert into public.reminder_automation_policy_history(policy_id,version,snapshot) values(r.id,r.version,to_jsonb(r));
 return r;
end $$

create function public.release_preview_internal(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare result jsonb;s jsonb;weights jsonb:='[]';w jsonb;provenance jsonb;
begin
 result:=public.release_preview_v3_internal(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);
 if jsonb_array_length(coalesce(p_selection->'weight_ids','[]'))=0 then return result;end if;
 for w in select value from jsonb_array_elements(result#>'{snapshot,weights}') loop
  -- Shared locks remain held through confirmation or the provider preflight transaction.
  perform 1 from public.patient_weights where id=(w->>'id')::uuid for share;
  select coalesce(jsonb_agg(jsonb_build_object(
   'approval_id',a.request_id,'source','ezyVet','source_record_id',a.external_id,
   'action',a.action,'latest_source_version',h.version,'approved_source_version',a.head_version,'latest_source_reviewed',h.snapshot_id=a.snapshot_id or exists(select 1 from public.ezyvet_weight_source_reviews sr where sr.approval_id=a.request_id and sr.snapshot_id=h.snapshot_id),'original',jsonb_build_object('weight',s.payload->>'weight','unit',s.payload->>'weight_unit','timestamp',s.payload->>'timestamp'),
   'reviewed_values',a.reviewed_values,'review_reason',a.reason,'reviewer_id',a.approved_by,'reviewed_at',a.created_at,
   'source_clinician',null,'source_reviews',coalesce((select jsonb_agg(jsonb_build_object(
    'id',r.request_id,'source_version',r.head_version,'reviewer_id',r.reviewed_by,'reviewed_at',r.created_at,'reason',r.reason,
    'source',jsonb_build_object('weight',rs.payload->>'weight','unit',rs.payload->>'weight_unit','timestamp',rs.payload->>'timestamp','active',rs.payload->>'active')) order by r.created_at,r.request_id)
    from public.ezyvet_weight_source_reviews r join public.ezyvet_import_snapshots rs on rs.id=r.snapshot_id where r.approval_id=a.request_id),'[]'::jsonb)) order by a.created_at,a.request_id),'[]'::jsonb)
  into provenance from public.ezyvet_weight_approvals a join public.ezyvet_import_snapshots s on s.id=a.snapshot_id join public.ezyvet_identity_heads h on h.source_origin=a.source_origin and h.source_site_uid=a.source_site_uid and h.resource='healthstatus' and h.external_id=a.external_id
  where a.weight_id=(w->>'id')::uuid and a.pet_id=p_pet_id;
  weights:=weights||jsonb_build_array(w||jsonb_build_object('import_provenance',provenance));
 end loop;
 s:=(result->'snapshot')||jsonb_build_object('schema_version',4,'weights',weights);
 if octet_length(s::text)>1048576 then raise exception 'Release exceeds the reviewed snapshot limit; split into smaller packages' using errcode='23514';end if;
 return jsonb_build_object('snapshot',s,'source_hash',encode(digest(s::text,'sha256'),'hex'));
end $$

-- Preserve exact old-package comparison, while v4 comparison includes the frozen ledger.
do $$declare definition text;begin
 select pg_get_functiondef('public.release_read_internal(uuid)'::regprocedure) into definition;
 if position('else current_preview:=public.release_preview_internal(' in definition)=0 then raise exception 'Release read definition drifted; v4 migration requires review';end if;
 definition:=replace(definition,'else current_preview:=public.release_preview_internal(', 'elsif r.snapshot->>''schema_version''=''3'' then current_preview:=public.release_preview_v3_internal(r.pet_id,r.client_id,r.channel,r.recipient,r.selection); else current_preview:=public.release_preview_internal(');
 execute definition;
 select pg_get_functiondef('public.confirm_record_release(uuid,uuid,uuid,text,text,jsonb,jsonb,text,boolean)'::regprocedure) into definition;
 if position('preview:=public.preview_record_release(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);' in definition)=0 then raise exception 'Release confirmation definition drifted; v4 migration requires review';end if;
 definition:=replace(definition,'preview:=public.preview_record_release(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);',
 'if (p_reviewed_snapshot->>''schema_version'')::integer=4 then preview:=public.release_preview_internal(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);
 else
  preview:=public.preview_record_release(p_pet_id,p_client_id,p_channel,p_recipient,p_selection);
  if exists(select 1 from public.ezyvet_weight_approvals where pet_id=p_pet_id and weight_id in(select v::uuid from jsonb_array_elements_text(coalesce(p_selection->''weight_ids'',''[]'')) v)) then raise exception ''Preview and review weight provenance with release form version 4'' using errcode=''23514'';end if;
 end if;');
 execute definition;
end $$

-- Ledger appends serialize on the same native weight row; only v4 packages are invalidated.
create function public.release_weight_provenance_changed() returns trigger language plpgsql security definer set search_path=public as $$
declare target uuid;
begin
 if TG_TABLE_NAME='ezyvet_weight_approvals' then target:=NEW.weight_id;else select weight_id into strict target from public.ezyvet_weight_approvals where request_id=NEW.approval_id;end if;
 perform 1 from public.patient_weights where id=target for update;
 insert into public.record_release_events(id,release_id,kind,reason,created_by)
 select gen_random_uuid(),s.release_id,'source_changed','Reviewed weight source provenance changed; prepare a fresh package',auth.uid()
 from public.record_release_sources s join public.record_releases r on r.id=s.release_id
 where s.source_kind='weight' and s.source_id=target and r.snapshot->>'schema_version'='4';
 return NEW;
end $$

create function public.release_weight_source_head_changed() returns trigger language plpgsql security definer set search_path=public as $$
declare target uuid;
begin
 if NEW.resource<>'healthstatus' or NEW.snapshot_id=OLD.snapshot_id then return NEW;end if;
 for target in select distinct weight_id from public.ezyvet_weight_approvals where source_origin=NEW.source_origin and source_site_uid=NEW.source_site_uid and external_id=NEW.external_id order by weight_id loop
  perform 1 from public.patient_weights where id=target for update;
  insert into public.record_release_events(id,release_id,kind,reason,created_by)
  select gen_random_uuid(),s.release_id,'source_changed','External weight source changed; review provenance in a fresh package',auth.uid()
  from public.record_release_sources s join public.record_releases r on r.id=s.release_id
  where s.source_kind='weight' and s.source_id=target and r.snapshot->>'schema_version'='4';
 end loop;
 return NEW;
end $$

