create function public.invoice_email_preview_internal(p_invoice_id uuid,p_client_id uuid) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare i public.billing_invoices;c public.clients;doc jsonb;recipient text;hash text;
begin
 select * into i from public.billing_invoices where id=p_invoice_id and client_id=p_client_id for share;
 if not found or i.status<>'issued' then raise exception 'Only an issued invoice for this household can be emailed' using errcode='42501';end if;
 select * into strict c from public.clients where id=p_client_id for share;
 recipient:=public.communication_recipient('EMAIL',c.primary_email);
 if recipient is null or public.communication_is_suppressed('EMAIL',recipient,c.id) then raise exception 'Current household email is unavailable or suppressed' using errcode='42501';end if;
 doc:=public.invoice_document_internal(i.id,c.id);
 hash:=encode(digest(jsonb_build_object('document',doc-'rendered_at','client_version',c.version,'recipient',recipient)::text,'sha256'),'hex');
 return jsonb_build_object('document',doc,'source_hash',hash,'client_id',c.id,'recipient',recipient);
end $$

create function public.guard_invoice_email_history() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='UPDATE' and TG_TABLE_NAME='invoice_email_payloads' then
 if current_user='postgres' and OLD.payload_text is not null and NEW.payload_text is null and NEW.purged_at=now() and (to_jsonb(NEW)-array['payload_text','purged_at'])=(to_jsonb(OLD)-array['payload_text','purged_at']) and OLD.captured_at<now()-interval '90 days' then return NEW;end if;
 end if;
 if TG_OP='UPDATE' and TG_TABLE_NAME='invoice_email_requests' then
 if (to_jsonb(NEW)-'state')=(to_jsonb(OLD)-'state') and ((OLD.state='preparing' and NEW.state in ('ready','abandoned')) or (OLD.state='ready' and NEW.state in ('queued','abandoned'))) then return NEW;end if;
 end if;
 raise exception 'Invoice email history is immutable' using errcode='23514';
end $$

do $$ declare t text;begin
 foreach t in array array['invoice_email_requests','invoice_email_payloads','invoice_email_outbox_links'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('create trigger invoice_email_immutable before update or delete on public.%I for each row execute function public.guard_invoice_email_history()',t);
 end loop;
end $$

create function public.invoice_email_context(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.invoice_email_requests;current_doc jsonb;
begin
 select * into r from public.invoice_email_requests where id=p_request_id for share;
 if not found or r.state='abandoned' or not public.is_active_staff(r.actor_id) then raise exception 'Invoice email actor or request is unavailable' using errcode='42501';end if;
 perform 1 from public.conversations where id=r.conversation_id and client_id=r.client_id for share;
 if not found then raise exception 'Invoice email conversation no longer belongs to household' using errcode='42501';end if;
 current_doc:=public.invoice_email_preview_internal(r.invoice_id,r.client_id);
 if current_doc->>'source_hash' is distinct from r.invoice_hash or current_doc->>'recipient' is distinct from r.recipient then raise exception 'Invoice or household changed; prepare and review a fresh invoice email' using errcode='42501';end if;
 return jsonb_build_object('document',r.invoice_snapshot,'source_hash',r.invoice_hash,'client_id',r.client_id,'recipient',r.recipient);
end $$

create function public.recover_invoice_email(p_invoice_id uuid,p_request_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.invoice_email_requests;p public.invoice_email_payloads;o public.communication_outbox;
begin
 select * into r from public.invoice_email_requests where actor_id=actor and invoice_id=p_invoice_id and ((p_request_id is null and state<>'abandoned') or id=p_request_id) order by created_at desc,id limit 1;
 if not found then return null;end if;
 select * into p from public.invoice_email_payloads where request_id=r.id;
 select box.* into o from public.communication_outbox box join public.invoice_email_outbox_links l on l.outbox_id=box.id where l.request_id=r.id;
 return jsonb_build_object('request',to_jsonb(r),'payload_hash',p.payload_hash,'manifest',p.manifest,
 'purged_at',p.purged_at,'report_html',case when p.payload_text is not null then convert_from(decode((p.payload_text::jsonb)#>>'{attachments,0,content}','base64'),'UTF8') end,
 'receipt',case when o.id is not null then jsonb_build_object('outbox_id',o.id,'message_id',o.message_id,'state',o.state,'queued',true,'delivered',o.state='delivered') end);
end $$

create function public.prepare_invoice_email(p_request_id uuid,p_invoice_id uuid,p_client_id uuid,p_conversation_id uuid,p_recipient text,p_subject text,p_body text,p_invoice_hash text) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.invoice_email_requests;preview jsonb;
begin
 if p_request_id is null or p_invoice_hash is null or p_invoice_hash !~ '^[a-f0-9]{64}$' or p_recipient is null or p_subject is null or length(trim(p_subject)) not between 1 and 500 or p_body is null or length(trim(p_body)) not between 1 and 100000 then raise exception 'Stable request ID and complete reviewed invoice email intent are required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,2700));
 select * into r from public.invoice_email_requests where id=p_request_id;
 if found then
  if r.actor_id<>actor or row(r.invoice_id,r.client_id,r.conversation_id,r.recipient,r.subject,r.body,r.invoice_hash) is distinct from row(p_invoice_id,p_client_id,p_conversation_id,p_recipient,p_subject,p_body,p_invoice_hash) or r.state='abandoned' then raise exception 'Invoice email request already used or abandoned' using errcode='23505';end if;
  return public.recover_invoice_email(p_invoice_id,p_request_id);
 end if;
 perform 1 from public.conversations where id=p_conversation_id and client_id=p_client_id for share;
 if not found then raise exception 'Invoice conversation does not belong to the reviewed household' using errcode='42501';end if;
 preview:=public.invoice_email_preview_internal(p_invoice_id,p_client_id);
 if preview->>'source_hash' is distinct from p_invoice_hash or preview->>'recipient' is distinct from p_recipient then raise exception 'Invoice or recipient changed; review the current invoice' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(actor::text||':'||p_invoice_id::text,2700));
 if exists(select 1 from public.invoice_email_requests where actor_id=actor and invoice_id=p_invoice_id and state in ('preparing','ready')) then raise exception 'Recover or abandon the unresolved invoice email first' using errcode='23505';end if;
 insert into public.invoice_email_requests(id,invoice_id,actor_id,conversation_id,client_id,recipient,subject,body,invoice_hash,invoice_snapshot) values(p_request_id,p_invoice_id,actor,p_conversation_id,p_client_id,p_recipient,p_subject,p_body,p_invoice_hash,preview->'document');
 return public.recover_invoice_email(p_invoice_id,p_request_id);
end $$

create function public.invoice_email_capture_context(p_request_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.invoice_email_requests;
begin perform public.communication_require_service();select * into r from public.invoice_email_requests where id=p_request_id;
 if not found or r.actor_id is distinct from p_actor_id then raise exception 'Request ownership mismatch' using errcode='42501';end if;
 return jsonb_build_object('request',to_jsonb(r),'bundle',public.invoice_email_context(p_request_id),'captured',exists(select 1 from public.invoice_email_payloads where request_id=p_request_id));end $$

create function public.capture_invoice_email_payload(p_request_id uuid,p_actor_id uuid,p_payload_text text) returns void language plpgsql security definer set search_path=public as $$
declare r public.invoice_email_requests;existing public.invoice_email_payloads;payload jsonb;a jsonb;decoded bytea;hash text;manifest jsonb;
begin
 perform public.communication_require_service();
 if p_payload_text is null or octet_length(p_payload_text) not between 1 and 33554432 then raise exception 'Encoded invoice email exceeds application limits' using errcode='23514';end if;
 select * into r from public.invoice_email_requests where id=p_request_id for update;
 if not found or r.actor_id is distinct from p_actor_id or r.state='abandoned' or not public.is_active_staff(r.actor_id) then raise exception 'Request ownership mismatch or abandoned' using errcode='42501';end if;
 perform public.invoice_email_context(p_request_id);
 hash:=encode(sha256(convert_to(p_payload_text,'UTF8')),'hex');
 select * into existing from public.invoice_email_payloads where request_id=p_request_id;
 if found then if existing.payload_text is distinct from p_payload_text then raise exception 'Captured provider payload is immutable' using errcode='23505';end if;return;end if;
 payload:=p_payload_text::jsonb;
 if jsonb_typeof(payload)<>'object' or payload-array['from','reply_to','to','subject','text','attachments']<>'{}' or payload->'to' is distinct from jsonb_build_array(r.recipient) or payload->>'subject' is distinct from r.subject or payload->>'text' is distinct from r.body or public.communication_recipient('EMAIL',payload->>'reply_to') is null or jsonb_typeof(payload->'from') is distinct from 'string' or length(payload->>'from') not between 1 and 500 or public.communication_recipient('EMAIL',coalesce(substring(payload->>'from' from '<([^<>]+)>$'),payload->>'from')) is null then raise exception 'Provider payload differs from reviewed invoice intent' using errcode='23514';end if;
 if jsonb_typeof(payload->'attachments') is distinct from 'array' or jsonb_array_length(payload->'attachments')<>1 then raise exception 'Exactly one reviewed invoice HTML attachment is required' using errcode='23514';end if;
 a:=payload#>'{attachments,0}';
 if jsonb_typeof(a)<>'object' or a-array['filename','content_type','content']<>'{}' or a->>'filename' is distinct from 'invoice-'||r.invoice_id::text||'.html' or a->>'content_type' is distinct from 'text/html' or jsonb_typeof(a->'content') is distinct from 'string' or a->>'content' !~ '^[A-Za-z0-9+/]*={0,2}$' then raise exception 'Reviewed invoice attachment metadata is invalid' using errcode='23514';end if;
 decoded:=decode(a->>'content','base64');if octet_length(decoded)<1 then raise exception 'Empty invoice attachment rejected' using errcode='23514';end if;perform convert_from(decoded,'UTF8');
 manifest:=jsonb_build_array(jsonb_build_object('filename',a->>'filename','mime_type','text/html','file_size',octet_length(decoded),'sha256',encode(sha256(decoded),'hex'),'document_id',null));
 insert into public.invoice_email_payloads(request_id,payload_text,payload_hash,manifest) values(r.id,p_payload_text,hash,manifest);
 update public.invoice_email_requests set state='ready' where id=r.id;
exception when invalid_text_representation or character_not_in_repertoire then raise exception 'Malformed frozen invoice payload' using errcode='23514';
end $$

create function public.enqueue_invoice_email(p_request_id uuid,p_reviewed_payload_hash text,p_attest boolean) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.invoice_email_requests;p public.invoice_email_payloads;l public.invoice_email_outbox_links;o public.communication_outbox;
begin
 if p_attest is distinct from true then raise exception 'Review the exact invoice attachment and message before queueing' using errcode='23514';end if;
 select * into r from public.invoice_email_requests where id=p_request_id for update;
 select * into p from public.invoice_email_payloads where request_id=p_request_id;
 if r.id is null or r.actor_id<>actor or r.state='abandoned' or p.request_id is null or p.payload_hash is distinct from p_reviewed_payload_hash then raise exception 'Prepared invoice email or reviewed payload does not match' using errcode='42501';end if;
 select * into l from public.invoice_email_outbox_links where request_id=p_request_id;
 if found then select * into o from public.communication_outbox where id=l.outbox_id;return o;end if;
 perform public.invoice_email_context(p_request_id);
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,914));
 if exists(select 1 from public.communication_outbox where request_id=p_request_id) then raise exception 'Request ID already belongs to another queue workflow' using errcode='23505';end if;
 o:=public.enqueue_prepared_communication_internal(actor,r.id,r.conversation_id,'EMAIL',r.recipient,r.subject,r.body,'{}');
 insert into public.invoice_email_outbox_links(outbox_id,request_id,reviewed_payload_hash,queued_by) values(o.id,r.id,p.payload_hash,actor);
 update public.invoice_email_requests set state='queued' where id=r.id;
 return o;
end $$

create function public.abandon_invoice_email(p_request_id uuid) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.invoice_email_requests;
begin select * into r from public.invoice_email_requests where id=p_request_id for update;
 if not found or r.actor_id<>actor or r.state='queued' then raise exception 'Only own unqueued preparation can be abandoned' using errcode='42501';end if;
 if r.state<>'abandoned' then update public.invoice_email_requests set state='abandoned' where id=p_request_id;end if;end $$

create function public.read_invoice_email_payload(p_outbox_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;l public.invoice_email_outbox_links;p public.invoice_email_payloads;
begin perform public.communication_require_service();select * into o from public.communication_outbox where id=p_outbox_id;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 select * into l from public.invoice_email_outbox_links where outbox_id=o.id;
 if not found then return null;end if;
 perform public.invoice_email_context(l.request_id);
 select * into p from public.invoice_email_payloads where request_id=l.request_id;
 if not found or p.payload_text is null or l.reviewed_payload_hash<>p.payload_hash then raise exception 'Frozen invoice payload unavailable' using errcode='23514';end if;
 return jsonb_build_object('payload_text',p.payload_text,'payload_hash',p.payload_hash);
end $$

create function public.read_frozen_email_payload(p_outbox_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare payload jsonb;
begin
 perform public.communication_require_service();
 if exists(select 1 from public.invoice_email_outbox_links where outbox_id=p_outbox_id) and exists(select 1 from public.release_email_outbox_links where outbox_id=p_outbox_id) then raise exception 'Ambiguous frozen email association' using errcode='23514';end if;
 payload:=public.read_invoice_email_payload(p_outbox_id,p_lease_token);
 if payload is not null then return payload||jsonb_build_object('artifact_kind','invoice');end if;
 payload:=public.read_release_email_payload(p_outbox_id,p_lease_token);
 if payload is not null then return payload||jsonb_build_object('artifact_kind','record_release');end if;
 return null;
end $$

create function public.start_communication_attempt(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;l public.invoice_email_outbox_links;p public.invoice_email_payloads;payload jsonb;valid boolean:=true;
begin perform public.communication_require_service();select * into o from public.communication_outbox where id=p_id for update;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 select * into l from public.invoice_email_outbox_links where outbox_id=o.id;
 if found then
  begin
   perform public.invoice_email_context(l.request_id);
   select * into p from public.invoice_email_payloads where request_id=l.request_id;
   payload:=p.payload_text::jsonb;
   valid:=p.request_id is not null and p.payload_hash=l.reviewed_payload_hash and p.payload_hash=encode(sha256(convert_to(p.payload_text,'UTF8')),'hex') and p_provider_config->>'invoice_payload_hash'=p.payload_hash and payload->>'from'=p_provider_config->>'from' and payload->>'reply_to'=p_provider_config->>'reply_to';
  exception when sqlstate '23514' or sqlstate '42501' then valid:=false;end;
  if valid is distinct from true then update public.communication_outbox set state='failed',last_error='invoice_source_or_payload_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=o.id returning * into o;return o;end if;
  return public.start_communication_attempt_without_invoice_guard(p_id,p_lease_token,p_provider_config-'invoice_payload_hash');
 end if;
 return public.start_communication_attempt_without_invoice_guard(p_id,p_lease_token,p_provider_config);
end $$

create function public.read_invoice_email_attachment(p_request_id uuid,p_index integer) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();p public.invoice_email_payloads;
begin
 if p_index is null or p_index <>0 or not exists(select 1 from public.invoice_email_requests where id=p_request_id and actor_id=actor) then raise exception 'Attachment request unavailable' using errcode='42501';end if;
 select * into p from public.invoice_email_payloads where request_id=p_request_id;
 if p.payload_text is null or p_index>=jsonb_array_length(p.manifest) then raise exception 'Frozen attachment unavailable or expired' using errcode='23514';end if;
 return (p.payload_text::jsonb->'attachments')->p_index;
end $$

-- Retain hash/manifest/review/receipt evidence. Never purge pending or uncertain delivery bytes.
create function public.purge_expired_invoice_email_payloads(p_limit integer default 100) returns integer language plpgsql security definer set search_path=public as $$
declare count_purged integer;
begin perform public.communication_require_service();
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'Purge limit must be 1 to 100' using errcode='23514';end if;
 with expired as(select p.request_id from public.invoice_email_payloads p join public.invoice_email_requests r on r.id=p.request_id where p.payload_text is not null and p.captured_at<now()-interval '90 days' and (r.state='abandoned' or exists(select 1 from public.invoice_email_outbox_links l join public.communication_outbox o on o.id=l.outbox_id where l.request_id=r.id and o.state in ('accepted','delivered') and o.provider_message_id is not null)) order by p.captured_at limit p_limit for update of p skip locked)
 update public.invoice_email_payloads set payload_text=null,purged_at=now() where request_id in(select request_id from expired);
 get diagnostics count_purged=row_count;return count_purged;
end $$

do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('guard_invoice_email_history','audit_invoice_email','invoice_email_context','recover_invoice_email','prepare_invoice_email','invoice_email_capture_context','capture_invoice_email_payload','enqueue_invoice_email','abandon_invoice_email','read_invoice_email_payload','read_frozen_email_payload','start_communication_attempt') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('recover_invoice_email','prepare_invoice_email','enqueue_invoice_email','abandon_invoice_email') then execute format('grant execute on function %s to authenticated',f.signature);
  elsif f.proname in ('invoice_email_capture_context','capture_invoice_email_payload','read_invoice_email_payload','read_frozen_email_payload','start_communication_attempt') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

-- One bounded maintenance entry point covers both artifact families without purging uncertain sends.
create function public.purge_expired_frozen_email_payloads(p_limit integer default 100) returns jsonb language plpgsql security definer set search_path=public as $$
declare releases integer;invoices integer;
begin perform public.communication_require_service();
 releases:=public.purge_expired_release_email_payloads(p_limit);
 invoices:=public.purge_expired_invoice_email_payloads(p_limit);
 return jsonb_build_object('record_release_payloads',releases,'invoice_payloads',invoices);
end $$

-- Reviewed, expiring capabilities. Usable tokens and materialized URLs are never persisted.
create function public.document_link_source(p_family text,p_source_id uuid,p_client_id uuid) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare c public.clients;i public.billing_invoices;b jsonb;doc jsonb;phone text;hash text;
begin
 select * into c from public.clients where id=p_client_id for share;
 if not found then raise exception 'Source unavailable' using errcode='42501';end if;
 phone:=public.communication_recipient('SMS',c.primary_phone);
 if phone is null or public.communication_is_suppressed('SMS',phone,c.id) then raise exception 'SMS recipient unavailable' using errcode='42501';end if;
 if p_family='invoice' then
  select * into i from public.billing_invoices where id=p_source_id and client_id=c.id for share;
  if not found or i.status<>'issued' then raise exception 'Issued invoice unavailable' using errcode='42501';end if;
  doc:=public.invoice_document_internal(i.id,c.id);
  hash:=encode(digest(jsonb_build_object('document',doc-'rendered_at','client_version',c.version,'recipient',phone)::text,'sha256'),'hex');
  b:=jsonb_build_object('document',doc);
 elsif p_family='record_release' then
  b:=public.release_read_internal(p_source_id);
  if (b->>'eligible')::boolean is distinct from true or b#>>'{release,client_id}' is distinct from c.id::text or b#>>'{release,channel}' is distinct from 'SMS' or b#>>'{release,recipient}' is distinct from phone then raise exception 'SMS release unavailable' using errcode='42501';end if;
  perform 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=(b#>>'{release,snapshot,schema_version}')::integer for share;
  if not found then raise exception 'Clinical release acceptance unavailable' using errcode='42501';end if;
  hash:=b#>>'{release,source_hash}';
 else raise exception 'Unsupported source family' using errcode='23514';end if;
 return jsonb_build_object('family',p_family,'source_id',p_source_id,'client_id',c.id,'recipient',phone,'source_hash',hash,'bundle',b,'summary',jsonb_build_object('family',p_family,'household_name',c.full_name));
end $$

create table public.document_link_access_budget (
 grant_id uuid primary key references public.document_link_grants(id) on delete restrict,used integer not null default 0 check(used between 0 and 200)
)

create function public.guard_document_link_history() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='UPDATE' and TG_TABLE_NAME='document_link_grants' and (to_jsonb(NEW)-'state')=(to_jsonb(OLD)-'state') and (((to_jsonb(OLD)->>'state')='preparing' and (to_jsonb(NEW)->>'state') in ('captured','revoked')) or ((to_jsonb(OLD)->>'state')='captured' and (to_jsonb(NEW)->>'state') in ('reviewed','revoked')) or ((to_jsonb(OLD)->>'state')='reviewed' and (to_jsonb(NEW)->>'state')='revoked')) then return NEW;end if;
 raise exception 'Document link history is immutable' using errcode='23514';
end $$

do $$declare t text;begin
 foreach t in array array['document_link_grants','document_link_payloads','document_link_events','document_link_access_budget'] loop
  execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  if t<>'document_link_access_budget' then
   execute format('create trigger document_link_immutable before update or delete on public.%I for each row execute function public.guard_document_link_history()',t);
   execute format('create trigger document_link_audit after insert or update on public.%I for each row execute function public.audit_document_link()',t);
  end if;
 end loop;
end $$

create function public.document_link_current(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare g public.document_link_grants;s jsonb;
begin
 select * into g from public.document_link_grants where id=p_id for share;
 if not found or g.state='revoked' or g.expires_at<=clock_timestamp() or not public.is_active_staff(g.actor_id) then raise exception 'Document link unavailable' using errcode='42501';end if;
 s:=public.document_link_source(g.family,g.source_id,g.client_id);
 if s->>'source_hash' is distinct from g.source_hash or s->>'recipient' is distinct from g.recipient or not exists(select 1 from public.conversations where id=g.conversation_id and client_id=g.client_id) then raise exception 'Document link source changed' using errcode='42501';end if;
 return s;
end $$

create function public.recover_document_link(p_family text,p_source_id uuid,p_request_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();g public.document_link_grants;p public.document_link_payloads;events jsonb;
begin
 select * into g from public.document_link_grants where actor_id=actor and family=p_family and source_id=p_source_id and (p_request_id is null or id=p_request_id) order by created_at desc,id limit 1;
 if not found then return null;end if;
 select * into p from public.document_link_payloads where grant_id=g.id;
 select coalesce(jsonb_agg(to_jsonb(e) order by created_at,id),'[]') into events from public.document_link_events e where grant_id=g.id;
 return jsonb_build_object('grant',to_jsonb(g)-'source_bundle','artifact_hash',p.artifact_hash,'message_hash',p.message_hash,'manifest',p.manifest,'report_html',case when p.payload_text is not null then convert_from(decode((p.payload_text::jsonb)#>>'{artifacts,0,content}','base64'),'UTF8') end,'events',events,'receipt',null);
end $$

create function public.prepare_document_link(p_request_id uuid,p_family text,p_source_id uuid,p_client_id uuid,p_conversation_id uuid,p_recipient text,p_source_hash text,p_expires_at timestamptz,p_message_template text,p_origin text,p_key_version text) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();g public.document_link_grants;s jsonb;context text;
begin
 perform pg_advisory_xact_lock(hashtextextended('document-link:'||p_request_id::text,0));
 select * into g from public.document_link_grants where id=p_request_id for update;
 if found then
  if g.actor_id<>actor or g.family<>p_family or g.source_id<>p_source_id or g.client_id<>p_client_id or g.conversation_id<>p_conversation_id or g.recipient<>p_recipient or g.source_hash<>p_source_hash or g.expires_at<>p_expires_at or g.message_template<>p_message_template or g.origin<>p_origin or g.key_version<>p_key_version then raise exception 'Immutable document link intent differs' using errcode='23505';end if;
  return public.recover_document_link(g.family,g.source_id,g.id);
 end if;
 if p_expires_at is null or not isfinite(p_expires_at) or p_expires_at<=clock_timestamp() or p_expires_at>clock_timestamp()+interval '7 days' then raise exception 'Expiry must be within seven days' using errcode='23514';end if;
 s:=public.document_link_source(p_family,p_source_id,p_client_id);
 if s->>'source_hash' is distinct from p_source_hash or s->>'recipient' is distinct from p_recipient or not exists(select 1 from public.conversations where id=p_conversation_id and client_id=p_client_id) then raise exception 'Source or recipient differs' using errcode='42501';end if;
 context:=jsonb_build_object('domain','lrv-document-link/v1','id',p_request_id,'family',p_family,'source_id',p_source_id,'client_id',p_client_id,'actor_id',actor,'recipient',p_recipient,'source_hash',p_source_hash,'message_template',p_message_template,'origin',p_origin,'key_version',p_key_version,'expires_at',to_char(p_expires_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'created_at',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text;
 insert into public.document_link_grants(id,family,source_id,client_id,actor_id,conversation_id,recipient,source_hash,source_bundle,message_template,origin,key_version,capability_context,expires_at) values(p_request_id,p_family,p_source_id,p_client_id,actor,p_conversation_id,p_recipient,p_source_hash,s->'bundle',p_message_template,p_origin,p_key_version,context,p_expires_at);
 insert into public.document_link_access_budget(grant_id) values(p_request_id);
 return public.recover_document_link(p_family,p_source_id,p_request_id);
end $$

create function public.document_link_capture_context(p_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare g public.document_link_grants;
begin select * into g from public.document_link_grants where id=p_id for share;if not found or g.actor_id<>p_actor_id then raise exception 'Unavailable' using errcode='42501';end if;
 if not exists(select 1 from public.document_link_payloads where grant_id=g.id) then perform public.document_link_current(g.id);end if;
 return jsonb_build_object('grant',to_jsonb(g),'captured',exists(select 1 from public.document_link_payloads where grant_id=g.id));end $$

create function public.capture_document_link(p_id uuid,p_actor_id uuid,p_payload_text text,p_token_hash text,p_message_hash text) returns void language plpgsql security definer set search_path=public,extensions as $$
declare g public.document_link_grants;old public.document_link_payloads;payload jsonb;a jsonb;d jsonb;bytes bytea;manifest jsonb:='[]';n integer:=0;expected_count integer;
begin
 select * into g from public.document_link_grants where id=p_id for update;
 if not found or g.actor_id<>p_actor_id then raise exception 'Unavailable' using errcode='42501';end if;
 select * into old from public.document_link_payloads where grant_id=p_id;
 if found then
  if old.payload_text<>p_payload_text or old.token_hash<>p_token_hash or old.message_hash<>p_message_hash then raise exception 'Captured bytes differ' using errcode='23505';end if;return;
 end if;
 perform public.document_link_current(p_id);
 if g.state<>'preparing' or p_payload_text is null or octet_length(p_payload_text)>33554432 or p_token_hash !~ '^[a-f0-9]{64}$' or p_message_hash !~ '^[a-f0-9]{64}$' then raise exception 'Capture invalid' using errcode='23514';end if;
 payload:=p_payload_text::jsonb;
 expected_count:=case when g.family='invoice' then 1 else 1+jsonb_array_length(g.source_bundle#>'{release,snapshot,attachments}') end;
 if jsonb_typeof(payload) is distinct from 'object' or (select count(*) from jsonb_object_keys(payload))<>1 or jsonb_typeof(payload->'artifacts') is distinct from 'array' or jsonb_array_length(payload->'artifacts')<>expected_count or expected_count>25 then raise exception 'Artifact count invalid' using errcode='23514';end if;
 for a in select value from jsonb_array_elements(payload->'artifacts') loop
  if jsonb_typeof(a) is distinct from 'object' or (select count(*) from jsonb_object_keys(a))<>4 or jsonb_typeof(a->'content') is distinct from 'string' or jsonb_typeof(a->'mime_type') is distinct from 'string' or jsonb_typeof(a->'filename') is distinct from 'string' or a->>'filename' !~ '^[A-Za-z0-9 _.-]{1,180}$' then raise exception 'Artifact invalid' using errcode='23514';end if;
  bytes:=decode(a->>'content','base64');
  if octet_length(bytes)<1 then raise exception 'Empty artifact' using errcode='23514';end if;
  if n=0 then
   if a->>'mime_type'<>'text/html' or a->>'document_id' is not null or octet_length(bytes)>20971520 then raise exception 'Report invalid' using errcode='23514';end if;
  else
   d:=g.source_bundle#>array['release','snapshot','attachments',(n-1)::text];
   if a->>'document_id' is distinct from d->>'id' or a->>'mime_type' is distinct from d->>'mime_type' or octet_length(bytes)<>(d->>'file_size')::bigint or octet_length(bytes)>20971520 then raise exception 'Original differs' using errcode='23514';end if;
   if (a->>'mime_type'='application/pdf' and substring(bytes from 1 for 5)<>convert_to('%PDF-','UTF8')) or (a->>'mime_type'='image/png' and substring(bytes from 1 for 8)<>decode('89504e470d0a1a0a','hex')) or (a->>'mime_type'='image/jpeg' and substring(bytes from 1 for 3)<>decode('ffd8ff','hex')) or a->>'mime_type' not in ('application/pdf','image/png','image/jpeg') then raise exception 'Original signature differs' using errcode='23514';end if;
  end if;
  manifest:=manifest||jsonb_build_array(jsonb_build_object('index',n,'filename',a->>'filename','mime_type',a->>'mime_type','file_size',octet_length(bytes),'sha256',encode(digest(bytes,'sha256'),'hex')));n:=n+1;
 end loop;
 insert into public.document_link_payloads(grant_id,payload_text,artifact_hash,token_hash,message_hash,manifest) values(g.id,p_payload_text,encode(digest(p_payload_text,'sha256'),'hex'),p_token_hash,p_message_hash,manifest);
 update public.document_link_grants set state='captured' where id=g.id;
end $$

create function public.attest_document_link(p_request_id uuid,p_reviewed_artifact_hash text,p_reviewed_message_hash text,p_attest boolean) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();g public.document_link_grants;p public.document_link_payloads;
begin
 select * into g from public.document_link_grants where id=p_request_id for update;select * into p from public.document_link_payloads where grant_id=p_request_id;
 if g.actor_id is distinct from actor or g.state not in ('captured','reviewed') or p_attest is distinct from true or p.artifact_hash is distinct from p_reviewed_artifact_hash or p.message_hash is distinct from p_reviewed_message_hash then raise exception 'Exact review required' using errcode='42501';end if;
 if g.state='reviewed' then return;end if;perform public.document_link_current(g.id);
 insert into public.document_link_events(grant_id,actor_id,kind,artifact_hash,message_hash) values(g.id,actor,'reviewed',p.artifact_hash,p.message_hash);update public.document_link_grants set state='reviewed' where id=g.id;
end $$

create function public.revoke_document_link(p_request_id uuid,p_reason text) returns void language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();g public.document_link_grants;
begin select * into g from public.document_link_grants where id=p_request_id for update;
 if not found or g.actor_id<>actor then raise exception 'Unavailable' using errcode='42501';end if;
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Reason required' using errcode='23514';end if;
 if g.state='revoked' then return;end if;
 insert into public.document_link_events(grant_id,actor_id,kind,reason) values(g.id,actor,'revoked',trim(p_reason));update public.document_link_grants set state='revoked' where id=g.id;end $$

create function public.document_link_access_context(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare g public.document_link_grants;p public.document_link_payloads;
begin select * into g from public.document_link_grants where id=p_id;select * into p from public.document_link_payloads where grant_id=p_id;
 if g.id is null or p.grant_id is null then raise exception 'Unavailable' using errcode='42501';end if;
 return jsonb_build_object('id',g.id,'key_version',g.key_version,'origin',g.origin,'capability_context',g.capability_context,'token_hash',p.token_hash);end $$

create function public.retrieve_document_link(p_id uuid,p_token_hash text,p_artifact_index integer default null) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare g public.document_link_grants;p public.document_link_payloads;a jsonb;m jsonb;bytes bytea;used integer;
begin
 select * into g from public.document_link_grants where id=p_id for update;select * into p from public.document_link_payloads where grant_id=p_id;
 if g.id is null or g.state<>'reviewed' or p.token_hash is distinct from p_token_hash then raise exception 'Unavailable' using errcode='42501';end if;
 perform public.document_link_current(g.id);
 if encode(digest(p.payload_text,'sha256'),'hex')<>p.artifact_hash then raise exception 'Unavailable' using errcode='42501';end if;
 if p_artifact_index is not null then
  if p_artifact_index<0 or p_artifact_index>=jsonb_array_length(p.manifest) then raise exception 'Unavailable' using errcode='42501';end if;
  a:=(p.payload_text::jsonb)->'artifacts'->p_artifact_index;m:=p.manifest->p_artifact_index;bytes:=decode(a->>'content','base64');
  if octet_length(bytes)<>(m->>'file_size')::bigint or encode(digest(bytes,'sha256'),'hex')<>m->>'sha256' then raise exception 'Unavailable' using errcode='42501';end if;
 end if;
 update public.document_link_access_budget set used=document_link_access_budget.used+1 where grant_id=g.id and document_link_access_budget.used<200 returning document_link_access_budget.used into used;
 if used is null then raise exception 'Unavailable' using errcode='42501';end if;
 if p_artifact_index is null then return jsonb_build_object('grant_id',g.id,'expires_at',g.expires_at,'manifest',p.manifest);end if;
 return jsonb_build_object('filename',m->>'filename','mime_type',m->>'mime_type','file_size',m->'file_size','sha256',m->>'sha256','content',a->>'content');
end $$

create function public.read_document_link_artifact(p_request_id uuid,p_index integer) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare actor uuid:=public.clinical_require_staff();g public.document_link_grants;p public.document_link_payloads;a jsonb;m jsonb;bytes bytea;
begin
 select * into g from public.document_link_grants where id=p_request_id;
 select * into p from public.document_link_payloads where grant_id=p_request_id;
 if g.actor_id is distinct from actor or p.grant_id is null or p_index is null or p_index<0 or p_index>=jsonb_array_length(p.manifest) then raise exception 'Unavailable' using errcode='42501';end if;
 if encode(digest(p.payload_text,'sha256'),'hex')<>p.artifact_hash then raise exception 'Unavailable' using errcode='42501';end if;
 a:=(p.payload_text::jsonb)->'artifacts'->p_index;m:=p.manifest->p_index;bytes:=decode(a->>'content','base64');
 if octet_length(bytes)<>(m->>'file_size')::bigint or encode(digest(bytes,'sha256'),'hex')<>m->>'sha256' then raise exception 'Unavailable' using errcode='42501';end if;
 return jsonb_build_object('filename',m->>'filename','mime_type',m->>'mime_type','file_size',m->'file_size','sha256',m->>'sha256','content',a->>'content');
end $$

do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('read_document_link_artifact','document_link_source','preview_document_link','guard_document_link_history','audit_document_link','document_link_current','recover_document_link','prepare_document_link','document_link_capture_context','capture_document_link','attest_document_link','revoke_document_link','document_link_access_context','retrieve_document_link') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('read_document_link_artifact','preview_document_link','recover_document_link','prepare_document_link','attest_document_link','revoke_document_link') then execute format('grant execute on function %s to authenticated',f.signature);
  elsif f.proname in ('document_link_capture_context','capture_document_link','document_link_access_context','retrieve_document_link') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

create function public.enqueue_document_link_sms(p_request_id uuid,p_reviewed_artifact_hash text,p_reviewed_message_hash text,p_attest boolean) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();g public.document_link_grants;p public.document_link_payloads;l public.document_link_outbox_links;o public.communication_outbox;
begin
 select * into g from public.document_link_grants where id=p_request_id for update;
 select * into p from public.document_link_payloads where grant_id=p_request_id;
 if g.actor_id is distinct from actor or p.grant_id is null or p_attest is distinct from true or p.artifact_hash is distinct from p_reviewed_artifact_hash or p.message_hash is distinct from p_reviewed_message_hash then raise exception 'Exact reviewed document and message are required' using errcode='42501';end if;
 select * into l from public.document_link_outbox_links where grant_id=g.id;
 if found then select * into o from public.communication_outbox where id=l.outbox_id;return o;end if;
 if g.state<>'reviewed' or not exists(select 1 from public.document_link_events where grant_id=g.id and kind='reviewed' and actor_id=actor and artifact_hash=p.artifact_hash and message_hash=p.message_hash) then raise exception 'Review document link before queueing' using errcode='42501';end if;
 perform public.document_link_current(g.id);
 if not exists(select 1 from public.document_link_access_budget where grant_id=g.id and used<200) then raise exception 'Document retrieval budget exhausted' using errcode='42501';end if;
 if p.artifact_hash<>encode(sha256(convert_to(p.payload_text,'UTF8')),'hex') then raise exception 'Frozen document integrity failed' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(g.id::text,914));
 if exists(select 1 from public.communication_outbox where request_id=g.id) then raise exception 'Request ID belongs to another queue workflow' using errcode='23505';end if;
 o:=public.enqueue_prepared_communication_internal(actor,g.id,g.conversation_id,'SMS',g.recipient,'',g.message_template,'{}');
 insert into public.document_link_outbox_links(outbox_id,grant_id,reviewed_artifact_hash,reviewed_message_hash,queued_by) values(o.id,g.id,p.artifact_hash,p.message_hash,actor);
 return o;
end $$

create function public.recover_document_link(p_family text,p_source_id uuid,p_request_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;o public.communication_outbox;
begin
 result:=public.recover_document_link_without_receipt(p_family,p_source_id,p_request_id);
 if result is null then return null;end if;
 select box.* into o from public.communication_outbox box join public.document_link_outbox_links l on l.outbox_id=box.id where l.grant_id=(result#>>'{grant,id}')::uuid;
 if found then result:=result||jsonb_build_object('receipt',jsonb_build_object('outbox_id',o.id,'message_id',o.message_id,'state',o.state,'queued',true,'delivered',o.state='delivered'));end if;
 return result;
end $$

create function public.document_link_delivery_context(p_outbox_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;l public.document_link_outbox_links;g public.document_link_grants;p public.document_link_payloads;
begin
 perform public.communication_require_service();
 select * into o from public.communication_outbox where id=p_outbox_id for update;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 select * into l from public.document_link_outbox_links where outbox_id=o.id;
 if not found then return null;end if;
 select * into g from public.document_link_grants where id=l.grant_id for share;
 select * into p from public.document_link_payloads where grant_id=g.id;
 perform public.document_link_current(g.id);
 if not exists(select 1 from public.document_link_access_budget where grant_id=g.id and used<200) then raise exception 'Document retrieval budget exhausted' using errcode='42501';end if;
 if g.state<>'reviewed' or p.grant_id is null or p.artifact_hash is distinct from l.reviewed_artifact_hash or p.message_hash is distinct from l.reviewed_message_hash or p.artifact_hash<>encode(sha256(convert_to(p.payload_text,'UTF8')),'hex') or row(o.channel,o.recipient,o.body,o.created_by,o.client_id,o.conversation_id) is distinct from row('SMS'::text,g.recipient,g.message_template,g.actor_id,g.client_id,g.conversation_id) then raise exception 'Document link delivery unavailable' using errcode='42501';end if;
 return jsonb_build_object('grant',jsonb_build_object('id',g.id,'origin',g.origin,'key_version',g.key_version,'capability_context',g.capability_context,'message_template',g.message_template),'token_hash',p.token_hash,'message_hash',p.message_hash,'artifact_hash',p.artifact_hash);
end $$

create function public.start_communication_attempt(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;context jsonb;valid boolean:=true;
begin
 perform public.communication_require_service();
 select * into o from public.communication_outbox where id=p_id for update;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 if exists(select 1 from public.document_link_outbox_links where outbox_id=o.id) then
  begin
   context:=public.document_link_delivery_context(p_id,p_lease_token);
   valid:=context is not null and p_provider_config->>'document_link_message_hash'=context->>'message_hash' and p_provider_config->>'document_link_token_hash'=context->>'token_hash' and p_provider_config->>'document_link_artifact_hash'=context->>'artifact_hash';
  exception when sqlstate '42501' or sqlstate '23514' then valid:=false;end;
  if valid is distinct from true then update public.communication_outbox set state='failed',last_error='document_link_source_or_materialization_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=o.id returning * into o;return o;end if;
  return public.start_communication_attempt_without_document_link_guard(p_id,p_lease_token,p_provider_config-array['document_link_message_hash','document_link_token_hash','document_link_artifact_hash']);
 end if;
 return public.start_communication_attempt_without_document_link_guard(p_id,p_lease_token,p_provider_config);
end $$

-- Block accidental pasting of usable capabilities into generic outbound persistence.
create function public.reject_persisted_document_capability() returns trigger language plpgsql set search_path=public as $$
begin
 if to_jsonb(NEW)::text ~ 'v1\.[A-Za-z0-9_-]{43}' then raise exception 'Use the reviewed document-link workflow; private capabilities cannot be stored in message history' using errcode='23514';end if;
 return NEW;
end $$

do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('enqueue_document_link_sms','recover_document_link','document_link_delivery_context','start_communication_attempt','reject_persisted_document_capability') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('enqueue_document_link_sms','recover_document_link') then execute format('grant execute on function %s to authenticated',f.signature);
  elsif f.proname in ('document_link_delivery_context','start_communication_attempt') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

do $$declare t text;begin
 foreach t in array array['payment_provider_profiles','invoice_checkout_attempts','invoice_payment_evidence','invoice_payments','invoice_refund_requests','invoice_refund_evidence','invoice_refunds'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 execute format('grant select on public.%I to authenticated',t);
 execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
 execute format('create trigger financial_history_immutable before update or delete on public.%I for each row execute function public.payment_immutable()',t);
 end loop;
end $$

create function public.configure_payment_provider(p_account_id text,p_livemode boolean,p_return_origin text) returns public.payment_provider_profiles language plpgsql security definer set search_path=public as $$
declare result public.payment_provider_profiles;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text,3006));
 select * into result from public.payment_provider_profiles where account_id=p_account_id and livemode=p_livemode;
 if found then
 if result.return_origin is distinct from p_return_origin then raise exception 'Payment provider profile already configured' using errcode='23514';end if;return result;end if;
 insert into public.payment_provider_profiles(account_id,livemode,return_origin) values(p_account_id,p_livemode,p_return_origin) returning * into result;return result;
end $$

create function public.read_invoice_payment_state(p_invoice_id uuid,p_client_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 perform public.invoice_document_internal(p_invoice_id,p_client_id);
 return jsonb_build_object('invoice_id',p_invoice_id,'client_id',p_client_id,'source_hash',public.payment_source_hash_internal(p_invoice_id,p_client_id),
 'balance',public.payment_balance_internal(p_invoice_id),
 'attempts',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('amount_cents',a.amount_cents::text,'state',public.checkout_state_internal(a.id)) order by a.created_at,a.id) from public.invoice_checkout_attempts a where a.invoice_id=p_invoice_id),'[]'::jsonb),
 'payments',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('amount_cents',p.amount_cents::text) order by p.created_at,p.id) from public.invoice_payments p where p.invoice_id=p_invoice_id),'[]'::jsonb),
 'refund_requests',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('amount_cents',r.amount_cents::text,'state',public.refund_state_internal(r.id)) order by r.created_at,r.id) from public.invoice_refund_requests r where r.invoice_id=p_invoice_id),'[]'::jsonb),
 'evidence',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.invoice_payment_evidence e join public.invoice_checkout_attempts a on a.id=e.request_id where a.invoice_id=p_invoice_id),'[]'::jsonb),
 'refund_evidence',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.invoice_refund_evidence e join public.invoice_refund_requests r on r.id=e.request_id where r.invoice_id=p_invoice_id),'[]'::jsonb));
end $$

create function public.prepare_invoice_checkout(p_request_id uuid,p_invoice_id uuid,p_client_id uuid,p_source_hash text,p_amount_cents bigint,p_account_id text,p_livemode boolean,p_success_url text,p_cancel_url text)
returns public.invoice_checkout_attempts language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); a public.invoice_checkout_attempts; i public.billing_invoices;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,3000));
 select * into a from public.invoice_checkout_attempts where id=p_request_id;
 if found then
 if row(a.actor_id,a.invoice_id,a.client_id,a.source_hash,a.amount_cents,a.account_id,a.livemode,a.success_url,a.cancel_url) is distinct from row(actor,p_invoice_id,p_client_id,p_source_hash,p_amount_cents,p_account_id,p_livemode,p_success_url,p_cancel_url) then raise exception 'Checkout identifier already used' using errcode='23514';end if;
 return a;end if;
 if not exists(select 1 from public.payment_provider_profiles where account_id=p_account_id and livemode=p_livemode and p_success_url=return_origin||'/payment/return' and p_cancel_url=return_origin||'/payment/cancel') then raise exception 'Payment provider or return destination not configured' using errcode='23514';end if;
 select * into i from public.billing_invoices where id=p_invoice_id and client_id=p_client_id for update;
 if not found or i.status<>'issued' then raise exception 'Issued invoice required' using errcode='23514';end if;
 if exists(select 1 from public.invoice_checkout_attempts where invoice_id=i.id and public.checkout_state_internal(id) not in ('paid','expired')) then raise exception 'Resolve existing checkout first' using errcode='23514';end if;
 if exists(select 1 from public.invoice_refund_requests where invoice_id=i.id and public.refund_state_internal(id) in ('pending','reconciliation')) then raise exception 'Resolve existing refund first' using errcode='23514';end if;
 if p_source_hash is distinct from public.payment_source_hash_internal(i.id,i.client_id) or p_amount_cents is distinct from (public.payment_balance_internal(i.id)->>'outstanding_cents')::bigint then raise exception 'Invoice payment balance changed' using errcode='40001';end if;
 insert into public.invoice_checkout_attempts(id,invoice_id,client_id,actor_id,source_hash,amount_cents,account_id,livemode,success_url,cancel_url,idempotency_key)
 values(p_request_id,i.id,i.client_id,actor,p_source_hash,p_amount_cents,p_account_id,p_livemode,p_success_url,p_cancel_url,'lrv-checkout-'||p_request_id) returning * into a;
 return a;
end $$

create function public.provider_checkout_context(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare a public.invoice_checkout_attempts;
begin
 select * into a from public.invoice_checkout_attempts where id=p_request_id;
 if not found then raise exception 'Checkout unavailable' using errcode='42501';end if;
 return to_jsonb(a)||jsonb_build_object('amount_cents',a.amount_cents::text,'state',public.checkout_state_internal(a.id),
 'current_source_matches',a.source_hash=public.payment_source_hash_internal(a.invoice_id,a.client_id),
 'session_id',(select session_id from public.invoice_payment_evidence where request_id=a.id and disposition='accepted' and session_id is not null order by created_at,id limit 1),
 'payment_id',(select payment_id from public.invoice_payments where request_id=a.id order by created_at,id limit 1));
end $$

create function public.checkout_payment_context(p_request_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
begin
 if not public.is_active_staff(p_actor_id) or not exists(select 1 from public.invoice_checkout_attempts where id=p_request_id and actor_id=p_actor_id) then raise exception 'Checkout unavailable' using errcode='42501';end if;
 return public.provider_checkout_context(p_request_id);
end $$

create function public.apply_checkout_evidence(p_event_id text,p_request_id uuid,p_account_id text,p_livemode boolean,p_kind text,p_session_id text,p_payment_id text,p_amount_cents bigint,p_currency text,p_source_hash text)
returns public.invoice_payment_evidence language plpgsql security definer set search_path=public as $$
declare a public.invoice_checkout_attempts; e public.invoice_payment_evidence; reason text:=''; prior_session text; paid public.invoice_payments;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text||':'||p_event_id,3001));
 select * into e from public.invoice_payment_evidence where account_id=p_account_id and livemode=p_livemode and event_id=p_event_id;
 if found then
 if row(e.request_id,e.kind,e.session_id,e.payment_id,e.amount_cents,e.currency,e.source_hash) is distinct from row(p_request_id,p_kind,p_session_id,p_payment_id,p_amount_cents,p_currency,p_source_hash) then raise exception 'Provider event identifier already used' using errcode='23514';end if;
 return e;end if;
 select * into strict a from public.invoice_checkout_attempts where id=p_request_id;
 perform 1 from public.billing_invoices where id=a.invoice_id for update;
 -- Serialize the same provider payment across invoices as well as events.
 if p_payment_id is not null then perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text||':'||p_payment_id,3002));end if;
 select session_id into prior_session from public.invoice_payment_evidence where request_id=a.id and disposition='accepted' and session_id is not null limit 1;
 if row(p_account_id,p_livemode,p_amount_cents,p_currency,p_source_hash) is distinct from row(a.account_id,a.livemode,a.amount_cents,a.currency,a.source_hash) then reason:='provider_context_mismatch';
 elsif p_session_id is null or p_session_id !~ '^cs_[A-Za-z0-9_]+$' then reason:='invalid_session';
 elsif prior_session is not null and prior_session<>p_session_id then reason:='session_mismatch';
 elsif p_kind='reconciliation' then reason:='provider_reconciliation_required';
 elsif p_kind='payment_succeeded' and (p_payment_id is null or p_payment_id !~ '^pi_[A-Za-z0-9]+$') then reason:='invalid_payment';
 elsif p_kind='payment_succeeded' and exists(select 1 from public.invoice_payments where request_id=a.id and payment_id<>p_payment_id) then reason:='multiple_payments_for_checkout';
 elsif p_kind='payment_succeeded' and exists(select 1 from public.invoice_payments where account_id=p_account_id and livemode=p_livemode and payment_id=p_payment_id and request_id<>a.id) then reason:='payment_already_attributed';
 elsif p_kind='payment_succeeded' and not exists(select 1 from public.invoice_payments where request_id=a.id) and a.source_hash is distinct from public.payment_source_hash_internal(a.invoice_id,a.client_id) then reason:='invoice_source_changed';
 end if;
 insert into public.invoice_payment_evidence(event_id,request_id,account_id,livemode,kind,session_id,payment_id,amount_cents,currency,source_hash,disposition,reason)
 values(p_event_id,a.id,p_account_id,p_livemode,p_kind,p_session_id,p_payment_id,p_amount_cents,p_currency,p_source_hash,case when reason='' then 'accepted' else 'quarantined' end,reason) returning * into e;
 if reason='' and p_kind='payment_succeeded' then
 insert into public.invoice_payments(request_id,evidence_id,invoice_id,account_id,livemode,payment_id,amount_cents,currency)
 values(a.id,e.id,a.invoice_id,a.account_id,a.livemode,p_payment_id,a.amount_cents,a.currency) on conflict(account_id,livemode,payment_id) do nothing;
 end if;
 return e;
end $$

create function public.prepare_invoice_refund(p_request_id uuid,p_invoice_id uuid,p_payment_id uuid,p_amount_cents bigint,p_reason text)
returns public.invoice_refund_requests language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); r public.invoice_refund_requests; p public.invoice_payments; remaining bigint;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,3003));
 select * into r from public.invoice_refund_requests where id=p_request_id;
 if found then
 if row(r.actor_id,r.invoice_id,r.payment_id,r.amount_cents,r.reason) is distinct from row(actor,p_invoice_id,p_payment_id,p_amount_cents,p_reason) then raise exception 'Refund identifier already used' using errcode='23514';end if;return r;end if;
 perform 1 from public.billing_invoices where id=p_invoice_id and status='issued' for update;
 if not found then raise exception 'Issued invoice required' using errcode='23514';end if;
 if exists(select 1 from public.invoice_checkout_attempts where invoice_id=p_invoice_id and public.checkout_state_internal(id) not in ('paid','expired')) then raise exception 'Resolve existing checkout first' using errcode='23514';end if;
 select * into p from public.invoice_payments where id=p_payment_id and invoice_id=p_invoice_id;
 if not found then raise exception 'Captured payment required' using errcode='23514';end if;
 remaining:=p.amount_cents-coalesce((select sum(amount_cents) from public.invoice_refund_requests where payment_id=p.id and public.refund_state_internal(id)<>'failed'),0);
 if p_amount_cents is null or p_amount_cents<=0 or p_amount_cents>remaining or p_amount_cents>(public.payment_balance_internal(p_invoice_id)->>'refundable_cents')::bigint then raise exception 'Refund exceeds credited or unreserved cash' using errcode='23514';end if;
 insert into public.invoice_refund_requests(id,invoice_id,payment_id,actor_id,amount_cents,reason,idempotency_key)
 values(p_request_id,p_invoice_id,p_payment_id,actor,p_amount_cents,p_reason,'lrv-refund-'||p_request_id) returning * into r;return r;
end $$

create function public.provider_refund_context(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.invoice_refund_requests;p public.invoice_payments;
begin
 select * into r from public.invoice_refund_requests where id=p_request_id;
 if not found then raise exception 'Refund unavailable' using errcode='42501';end if;
 select * into strict p from public.invoice_payments where id=r.payment_id;
 return to_jsonb(r)||jsonb_build_object('amount_cents',r.amount_cents::text,'state',public.refund_state_internal(r.id),'provider_payment_id',p.payment_id,'account_id',p.account_id,'livemode',p.livemode,'currency',p.currency,
 'refund_id',(select refund_id from public.invoice_refund_evidence where request_id=r.id and disposition='accepted' order by created_at,id limit 1));
end $$

create function public.refund_payment_context(p_request_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
begin
 if not public.is_active_staff(p_actor_id) or not exists(select 1 from public.invoice_refund_requests where id=p_request_id and actor_id=p_actor_id) then raise exception 'Refund unavailable' using errcode='42501';end if;
 return public.provider_refund_context(p_request_id);
end $$

create function public.apply_refund_evidence(p_event_id text,p_request_id uuid,p_account_id text,p_livemode boolean,p_refund_id text,p_provider_payment_id text,p_amount_cents bigint,p_currency text,p_status text)
returns public.invoice_refund_evidence language plpgsql security definer set search_path=public as $$
declare r public.invoice_refund_requests;p public.invoice_payments;e public.invoice_refund_evidence;reason text:='';prior_refund text;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text||':'||p_event_id,3004));
 select * into e from public.invoice_refund_evidence where account_id=p_account_id and livemode=p_livemode and event_id=p_event_id;
 if found then
 if row(e.request_id,e.refund_id,e.provider_payment_id,e.amount_cents,e.currency,e.status) is distinct from row(p_request_id,p_refund_id,p_provider_payment_id,p_amount_cents,p_currency,p_status) then raise exception 'Provider refund event identifier already used' using errcode='23514';end if;return e;end if;
 select * into strict r from public.invoice_refund_requests where id=p_request_id;
 perform 1 from public.billing_invoices where id=r.invoice_id for update;
 select * into strict p from public.invoice_payments where id=r.payment_id;
 perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text||':'||p_refund_id,3005));
 select refund_id into prior_refund from public.invoice_refund_evidence where request_id=r.id and disposition='accepted' limit 1;
 if row(p_account_id,p_livemode,p_provider_payment_id,p_amount_cents,p_currency) is distinct from row(p.account_id,p.livemode,p.payment_id,r.amount_cents,p.currency) then reason:='provider_context_mismatch';
 elsif p_refund_id !~ '^re_[A-Za-z0-9]+$' then reason:='invalid_refund';
 elsif prior_refund is not null and prior_refund<>p_refund_id then reason:='refund_mismatch';
 elsif exists(select 1 from public.invoice_refunds where account_id=p_account_id and livemode=p_livemode and refund_id=p_refund_id and request_id<>r.id) then reason:='refund_already_attributed';
 elsif p_status='succeeded' and public.refund_state_internal(r.id)='failed' then reason:='success_after_terminal_failure';
 end if;
 insert into public.invoice_refund_evidence(request_id,event_id,account_id,livemode,refund_id,provider_payment_id,amount_cents,currency,status,disposition,reason)
 values(r.id,p_event_id,p_account_id,p_livemode,p_refund_id,p_provider_payment_id,p_amount_cents,p_currency,p_status,case when reason='' then 'accepted' else 'quarantined' end,reason) returning * into e;
 if reason='' and p_status='succeeded' then
 insert into public.invoice_refunds(request_id,evidence_id,invoice_id,payment_id,account_id,livemode,refund_id,amount_cents)
 values(r.id,e.id,r.invoice_id,p.id,p.account_id,p.livemode,p_refund_id,r.amount_cents) on conflict(request_id) do nothing;
 end if;return e;
end $$

-- Guards apply to the existing RPCs and any future write paths, using the same invoice row lock.
create function public.guard_invoice_collection() returns trigger language plpgsql security definer set search_path=public as $$
declare invoice uuid;
begin
 if TG_TABLE_NAME='billing_credits' then invoice:=NEW.invoice_id;
 else
 invoice:=NEW.id;
 if NEW.status is not distinct from OLD.status or NEW.status<>'void' then return NEW;end if;
 end if;
 perform 1 from public.billing_invoices where id=invoice for update;
 if exists(select 1 from public.invoice_checkout_attempts where invoice_id=invoice and public.checkout_state_internal(id) not in ('paid','expired')) then raise exception 'Resolve existing checkout first' using errcode='23514';end if;
 if TG_TABLE_NAME='billing_invoices' and exists(select 1 from public.invoice_payments where invoice_id=invoice) then raise exception 'Invoices with payment history cannot be voided' using errcode='23514';end if;
 return NEW;
end $$

do $$declare f record;begin
 for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in (
 'provider_checkout_context','provider_refund_context','configure_payment_provider','payment_immutable','checkout_state_internal','refund_state_internal','payment_balance_internal','payment_source_hash_internal','read_invoice_payment_state','prepare_invoice_checkout','checkout_payment_context','apply_checkout_evidence','prepare_invoice_refund','refund_payment_context','apply_refund_evidence','guard_invoice_collection') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname in ('read_invoice_payment_state','prepare_invoice_checkout','prepare_invoice_refund') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 if f.proname in ('provider_checkout_context','provider_refund_context','configure_payment_provider','checkout_payment_context','apply_checkout_evidence','refund_payment_context','apply_refund_evidence') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

create function public.receive_stripe_event(p_receipt jsonb) returns uuid language plpgsql security definer set search_path=public as $$
declare r public.stripe_event_receipts; supplied public.stripe_event_receipts; disposition text;reason text;request uuid;
begin
 if jsonb_typeof(p_receipt) is distinct from 'object' or octet_length(p_receipt::text)>4096 then raise exception 'Invalid Stripe receipt' using errcode='23514';end if;
 if (select count(*) from jsonb_object_keys(p_receipt))<>10 or exists(select 1 from jsonb_object_keys(p_receipt) k where k not in ('event_id','event_type','provider_created_at','account_id','livemode','object_id','request_id','raw_sha256','disposition','reason')) then raise exception 'Invalid Stripe receipt keys' using errcode='23514';end if;
 if exists(select 1 from unnest(array['event_id','event_type','account_id','raw_sha256','disposition','reason']) k where jsonb_typeof(p_receipt->k) is distinct from 'string') or jsonb_typeof(p_receipt->'livemode') is distinct from 'boolean' or jsonb_typeof(p_receipt->'provider_created_at') is distinct from 'number' or (p_receipt->>'provider_created_at') !~ '^[0-9]{1,12}$' or jsonb_typeof(p_receipt->'object_id') not in ('string','null') or jsonb_typeof(p_receipt->'request_id') not in ('string','null') then raise exception 'Invalid Stripe receipt types' using errcode='23514';end if;
 if p_receipt->>'raw_sha256' !~ '^[a-f0-9]{64}$' then raise exception 'Invalid Stripe receipt hash' using errcode='23514';end if;
 supplied:=jsonb_populate_record(null::public.stripe_event_receipts,p_receipt);
 perform pg_advisory_xact_lock(hashtextextended(supplied.account_id||':'||supplied.livemode::text||':'||supplied.event_id,3100));
 select * into r from public.stripe_event_receipts where account_id=supplied.account_id and livemode=supplied.livemode and event_id=supplied.event_id;
 if found then
 -- Dedupe against the supplied envelope, not a silently modified provider payload.
 if row(r.event_type,r.provider_created_at,r.object_id,r.request_id,r.received_disposition,r.received_reason) is distinct from row(supplied.event_type,supplied.provider_created_at,supplied.object_id,supplied.request_id,supplied.disposition,supplied.reason) then raise exception 'Stripe event identifier conflict; reconcile delivery' using errcode='23514';end if;
 return r.id;end if;
 disposition:=supplied.disposition;reason:=supplied.reason;
 if disposition not in ('queued','quarantined','ignored') or reason not in ('','account_or_mode_mismatch','api_version_mismatch','unattributed_provider_object','external_adjustment_review','unsupported_event') then raise exception 'Invalid Stripe receipt disposition' using errcode='23514';end if;
 if disposition='queued' and reason<>'' then raise exception 'Queued Stripe receipt has a rejection reason' using errcode='23514';end if;
 if not exists(select 1 from public.payment_provider_profiles where account_id=supplied.account_id and livemode=supplied.livemode) then disposition:='quarantined';reason:='provider_not_configured';
 elsif disposition='queued' then
 if supplied.event_type in ('checkout.session.completed','checkout.session.expired','checkout.session.async_payment_succeeded','checkout.session.async_payment_failed') then
 if supplied.object_id is null or supplied.object_id not like 'cs_%' or not exists(select 1 from public.invoice_checkout_attempts where id=supplied.request_id and account_id=supplied.account_id and livemode=supplied.livemode) then disposition:='quarantined';reason:='unattributed_provider_object';end if;
 elsif supplied.event_type in ('refund.created','refund.updated','refund.failed') then
 if supplied.object_id is null or supplied.object_id not like 're_%' or not exists(select 1 from public.invoice_refund_requests rr join public.invoice_payments p on p.id=rr.payment_id where rr.id=supplied.request_id and p.account_id=supplied.account_id and p.livemode=supplied.livemode) then disposition:='quarantined';reason:='unattributed_provider_object';end if;
 else disposition:='quarantined';reason:='unsupported_event';end if;
 end if;
 insert into public.stripe_event_receipts(event_id,event_type,provider_created_at,account_id,livemode,object_id,request_id,raw_sha256,received_disposition,received_reason,disposition,reason)
 values(supplied.event_id,supplied.event_type,supplied.provider_created_at,supplied.account_id,supplied.livemode,supplied.object_id,supplied.request_id,supplied.raw_sha256,supplied.disposition,supplied.reason,disposition,reason) returning * into r;
 insert into public.stripe_event_work(receipt_id,state,reason) values(r.id,case when disposition='queued' then 'queued' else disposition end,reason);
 return r.id;
end $$

create function public.claim_stripe_event() returns jsonb language plpgsql security definer set search_path=public as $$
declare w public.stripe_event_work;r public.stripe_event_receipts;
begin
 -- At most one candidate per call. An expired fifth lease becomes visible quarantine.
 select * into w from public.stripe_event_work where (state='queued' and available_at<=clock_timestamp()) or (state='processing' and lease_expires_at<=clock_timestamp()) order by available_at,receipt_id for update skip locked limit 1;
 if not found then return null;end if;
 if w.attempt_count>=5 then
 update public.stripe_event_work set state='quarantined',lease_token=null,lease_expires_at=null,reason='retry_exhausted',updated_at=clock_timestamp() where receipt_id=w.receipt_id;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason) values(w.receipt_id,'exhausted',w.attempt_count,'retry_exhausted');return null;
 end if;
 update public.stripe_event_work set state='processing',attempt_count=attempt_count+1,lease_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '2 minutes',updated_at=clock_timestamp() where receipt_id=w.receipt_id returning * into w;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason) values(w.receipt_id,'claimed',w.attempt_count,'');
 select * into strict r from public.stripe_event_receipts where id=w.receipt_id;
 return jsonb_build_object('receipt',to_jsonb(r),'lease_token',w.lease_token,'lease_expires_at',w.lease_expires_at,'attempt_count',w.attempt_count);
end $$

create function public.finish_stripe_event(p_receipt_id uuid,p_lease_token uuid,p_evidence jsonb) returns text language plpgsql security definer set search_path=public as $$
declare w public.stripe_event_work;r public.stripe_event_receipts;checkout public.invoice_payment_evidence;refund public.invoice_refund_evidence;outcome_reason text:='';outcome_state text:='completed';family text;
begin
 select * into w from public.stripe_event_work where receipt_id=p_receipt_id for update;
 if not found or w.state<>'processing' or w.lease_token is distinct from p_lease_token or w.lease_expires_at<=clock_timestamp() then raise exception 'Stripe worker lease is unavailable' using errcode='42501';end if;
 select * into strict r from public.stripe_event_receipts where id=p_receipt_id;
 if jsonb_typeof(p_evidence) is distinct from 'object' or octet_length(p_evidence::text)>4096 then raise exception 'Invalid Stripe completion' using errcode='23514';end if;
 family:=p_evidence->>'family';
 if family='quarantine' then
 if (select count(*) from jsonb_object_keys(p_evidence))<>2 or exists(select 1 from jsonb_object_keys(p_evidence) k where k not in ('family','reason')) or p_evidence->>'reason' not in ('provider_context_mismatch','provider_object_unavailable','unattributed_provider_object','unsupported_event','external_adjustment_review','provider_reconciliation_required') then raise exception 'Invalid Stripe quarantine' using errcode='23514';end if;
 outcome_reason:=p_evidence->>'reason';outcome_state:='quarantined';
 elsif family in ('checkout','refund') then
 if jsonb_typeof(p_evidence->'account_id') is distinct from 'string' or jsonb_typeof(p_evidence->'livemode') is distinct from 'boolean' or jsonb_typeof(p_evidence->'amount_cents') is distinct from 'string' or (p_evidence->>'amount_cents') !~ '^[0-9]{1,8}$' or jsonb_typeof(p_evidence->'currency') is distinct from 'string' then raise exception 'Invalid Stripe completion types' using errcode='23514';end if;
 if row(p_evidence->>'account_id',(p_evidence->>'livemode')::boolean) is distinct from row(r.account_id,r.livemode) then raise exception 'Stripe receipt context mismatch' using errcode='23514';end if;
 if family='checkout' then
 if exists(select 1 from unnest(array['kind','session_id','source_hash']) k where jsonb_typeof(p_evidence->k) is distinct from 'string') or jsonb_typeof(p_evidence->'payment_id') not in ('string','null') then raise exception 'Invalid Checkout completion types' using errcode='23514';end if;
 if (select count(*) from jsonb_object_keys(p_evidence))<>9 or exists(select 1 from jsonb_object_keys(p_evidence) k where k not in ('family','account_id','livemode','kind','session_id','payment_id','amount_cents','currency','source_hash')) then raise exception 'Invalid Checkout completion keys' using errcode='23514';end if;
 if r.event_type not in ('checkout.session.completed','checkout.session.expired','checkout.session.async_payment_succeeded','checkout.session.async_payment_failed') or p_evidence->>'session_id' is distinct from r.object_id then raise exception 'Stripe Checkout receipt object mismatch' using errcode='23514';end if;
 checkout:=public.apply_checkout_evidence(r.event_id,r.request_id,r.account_id,r.livemode,p_evidence->>'kind',p_evidence->>'session_id',p_evidence->>'payment_id',(p_evidence->>'amount_cents')::bigint,p_evidence->>'currency',p_evidence->>'source_hash');
 if checkout.disposition='quarantined' then outcome_state:='quarantined';outcome_reason:=checkout.reason;end if;
 else
 if exists(select 1 from unnest(array['refund_id','provider_payment_id','status']) k where jsonb_typeof(p_evidence->k) is distinct from 'string') then raise exception 'Invalid refund completion types' using errcode='23514';end if;
 if (select count(*) from jsonb_object_keys(p_evidence))<>8 or exists(select 1 from jsonb_object_keys(p_evidence) k where k not in ('family','account_id','livemode','refund_id','provider_payment_id','amount_cents','currency','status')) then raise exception 'Invalid refund completion keys' using errcode='23514';end if;
 if r.event_type not in ('refund.created','refund.updated','refund.failed') or p_evidence->>'refund_id' is distinct from r.object_id then raise exception 'Stripe refund receipt object mismatch' using errcode='23514';end if;
 refund:=public.apply_refund_evidence(r.event_id,r.request_id,r.account_id,r.livemode,p_evidence->>'refund_id',p_evidence->>'provider_payment_id',(p_evidence->>'amount_cents')::bigint,p_evidence->>'currency',p_evidence->>'status');
 if refund.disposition='quarantined' then outcome_state:='quarantined';outcome_reason:=refund.reason;end if;
 end if;
 else raise exception 'Invalid Stripe completion family' using errcode='23514';end if;
 update public.stripe_event_work set state=outcome_state,reason=outcome_reason,lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where receipt_id=w.receipt_id;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason) values(w.receipt_id,outcome_state,w.attempt_count,outcome_reason);
 return outcome_state;
end $$

create function public.retry_stripe_event(p_receipt_id uuid,p_lease_token uuid,p_reason text) returns text language plpgsql security definer set search_path=public as $$
declare w public.stripe_event_work;next_state text;
begin
 if p_reason is null or p_reason not in ('provider_unavailable','rate_limited','transport_unknown','processing_error') then raise exception 'Invalid Stripe retry reason' using errcode='23514';end if;
 select * into w from public.stripe_event_work where receipt_id=p_receipt_id for update;
 if not found or w.state<>'processing' or w.lease_token is distinct from p_lease_token or w.lease_expires_at<=clock_timestamp() then raise exception 'Stripe worker lease is unavailable' using errcode='42501';end if;
 next_state:=case when w.attempt_count>=5 then 'quarantined' else 'queued' end;
 update public.stripe_event_work set state=next_state,reason=case when next_state='quarantined' then 'retry_exhausted' else p_reason end,available_at=clock_timestamp()+make_interval(secs=>least(3600,30*(2^w.attempt_count)::integer)),lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where receipt_id=w.receipt_id;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason) values(w.receipt_id,case when next_state='quarantined' then 'exhausted' else 'retry' end,w.attempt_count,p_reason);
 return next_state;
end $$

create function public.read_stripe_event_queue(p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 return coalesce((select jsonb_agg(item order by created_at desc,id) from (select r.id,r.created_at,to_jsonb(r)||jsonb_build_object('work_state',w.state,'attempt_count',w.attempt_count,'work_reason',w.reason,'available_at',w.available_at) item from public.stripe_event_receipts r join public.stripe_event_work w on w.receipt_id=r.id order by r.created_at desc,r.id limit greatest(1,least(coalesce(p_limit,100),250))) selected),'[]'::jsonb);
end $$

do $$declare f record;begin
 for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in ('receive_stripe_event','claim_stripe_event','finish_stripe_event','retry_stripe_event','read_stripe_event_queue') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname='read_stripe_event_queue' then execute format('grant execute on function %s to authenticated',f.signature);
 else execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

create function public.record_payment_reconciliation(p_family text,p_request_id uuid,p_reason text)
returns public.payment_reconciliation_observations language plpgsql security definer set search_path=public as $$
declare invoice uuid; result public.payment_reconciliation_observations;
begin
 if p_family is null or p_family not in ('checkout','refund') or p_reason is null or p_reason not in ('provider_context_mismatch','provider_object_unavailable','provider_reconciliation_required') then
 raise exception 'Invalid payment reconciliation observation' using errcode='23514';end if;
 if p_family='checkout' then select invoice_id into invoice from public.invoice_checkout_attempts where id=p_request_id;
 else select invoice_id into invoice from public.invoice_refund_requests where id=p_request_id;end if;
 if invoice is null then raise exception 'Payment request unavailable' using errcode='42501';end if;
 perform 1 from public.billing_invoices where id=invoice for update;
 select * into result from public.payment_reconciliation_observations where family=p_family and request_id=p_request_id and reason=p_reason;
 if found then return result;end if;
 insert into public.payment_reconciliation_observations(family,request_id,invoice_id,reason)
 values(p_family,p_request_id,invoice,p_reason) returning * into result;
 return result;
end $$

create or replace function public.read_invoice_payment_state(p_invoice_id uuid,p_client_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 perform public.invoice_document_internal(p_invoice_id,p_client_id);
 return jsonb_build_object('invoice_id',p_invoice_id,'client_id',p_client_id,'source_hash',public.payment_source_hash_internal(p_invoice_id,p_client_id),
 'balance',public.payment_balance_internal(p_invoice_id),
 'reconciliation_observations',coalesce((select jsonb_agg(to_jsonb(o) order by o.created_at,o.id) from public.payment_reconciliation_observations o where o.invoice_id=p_invoice_id),'[]'::jsonb),
 'attempts',coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('amount_cents',a.amount_cents::text,'state',public.checkout_state_internal(a.id)) order by a.created_at,a.id) from public.invoice_checkout_attempts a where a.invoice_id=p_invoice_id),'[]'::jsonb),
 'payments',coalesce((select jsonb_agg(to_jsonb(p)||jsonb_build_object('amount_cents',p.amount_cents::text) order by p.created_at,p.id) from public.invoice_payments p where p.invoice_id=p_invoice_id),'[]'::jsonb),
 'refund_requests',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('amount_cents',r.amount_cents::text,'state',public.refund_state_internal(r.id)) order by r.created_at,r.id) from public.invoice_refund_requests r where r.invoice_id=p_invoice_id),'[]'::jsonb),
 'evidence',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.invoice_payment_evidence e join public.invoice_checkout_attempts a on a.id=e.request_id where a.invoice_id=p_invoice_id),'[]'::jsonb),
 'refund_evidence',coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at,e.id) from public.invoice_refund_evidence e join public.invoice_refund_requests r on r.id=e.request_id where r.invoice_id=p_invoice_id),'[]'::jsonb));
end $$

-- All new money/obligation changes serialize with observation recording. Existing
-- intent retries remain readable, and provider settlement evidence may still arrive.
create function public.guard_payment_reconciliation() returns trigger language plpgsql security definer set search_path=public as $$
declare invoice uuid;
begin
 if TG_TABLE_NAME='billing_invoices' then
 if NEW.status is not distinct from OLD.status or NEW.status<>'void' then return NEW;end if;
 invoice:=NEW.id;
 else invoice:=NEW.invoice_id;end if;
 perform 1 from public.billing_invoices where id=invoice for update;
 if exists(select 1 from public.payment_reconciliation_observations where invoice_id=invoice) then
 raise exception 'Resolve payment reconciliation first' using errcode='23514';end if;
 return NEW;
end $$

-- Presentation reconciliation must not hide a terminal failure that released refund capacity.
create or replace function public.apply_refund_evidence(p_event_id text,p_request_id uuid,p_account_id text,p_livemode boolean,p_refund_id text,p_provider_payment_id text,p_amount_cents bigint,p_currency text,p_status text)
returns public.invoice_refund_evidence language plpgsql security definer set search_path=public as $$
declare r public.invoice_refund_requests;p public.invoice_payments;e public.invoice_refund_evidence;reason text:='';prior_refund text;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text||':'||p_event_id,3004));
 select * into e from public.invoice_refund_evidence where account_id=p_account_id and livemode=p_livemode and event_id=p_event_id;
 if found then
 if row(e.request_id,e.refund_id,e.provider_payment_id,e.amount_cents,e.currency,e.status) is distinct from row(p_request_id,p_refund_id,p_provider_payment_id,p_amount_cents,p_currency,p_status) then raise exception 'Provider refund event identifier already used' using errcode='23514';end if;return e;end if;
 select * into strict r from public.invoice_refund_requests where id=p_request_id;
 perform 1 from public.billing_invoices where id=r.invoice_id for update;
 select * into strict p from public.invoice_payments where id=r.payment_id;
 perform pg_advisory_xact_lock(hashtextextended(p_account_id||':'||p_livemode::text||':'||p_refund_id,3005));
 select refund_id into prior_refund from public.invoice_refund_evidence where request_id=r.id and disposition='accepted' limit 1;
 if row(p_account_id,p_livemode,p_provider_payment_id,p_amount_cents,p_currency) is distinct from row(p.account_id,p.livemode,p.payment_id,r.amount_cents,p.currency) then reason:='provider_context_mismatch';
 elsif p_refund_id !~ '^re_[A-Za-z0-9]+$' then reason:='invalid_refund';
 elsif prior_refund is not null and prior_refund<>p_refund_id then reason:='refund_mismatch';
 elsif exists(select 1 from public.invoice_refunds where account_id=p_account_id and livemode=p_livemode and refund_id=p_refund_id and request_id<>r.id) then reason:='refund_already_attributed';
 elsif p_status='succeeded'
 and exists(select 1 from public.invoice_refund_evidence where request_id=r.id and disposition='accepted' and status='failed')
 and not exists(select 1 from public.invoice_refunds where request_id=r.id)
 then reason:='success_after_terminal_failure';
 end if;
 insert into public.invoice_refund_evidence(request_id,event_id,account_id,livemode,refund_id,provider_payment_id,amount_cents,currency,status,disposition,reason)
 values(r.id,p_event_id,p_account_id,p_livemode,p_refund_id,p_provider_payment_id,p_amount_cents,p_currency,p_status,case when reason='' then 'accepted' else 'quarantined' end,reason) returning * into e;
 if reason='' and p_status='succeeded' then
 insert into public.invoice_refunds(request_id,evidence_id,invoice_id,payment_id,account_id,livemode,refund_id,amount_cents)
 values(r.id,e.id,r.invoice_id,p.id,p.account_id,p.livemode,p_refund_id,r.amount_cents) on conflict(request_id) do nothing;
 end if;return e;
end $$

