create function public.payment_reconciliation_target_internal(p_invoice_id uuid,p_family text,p_request_id uuid,p_object_id text) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare context jsonb;known text;refs jsonb;
begin
 if exists(select 1 from public.payment_reconciliation_observations where invoice_id=p_invoice_id and family=p_family and request_id=p_request_id and reason='provider_context_mismatch' and public.payment_blocker_is_open('observation',id)) then raise exception 'Conflicting provider observation requires separate review' using errcode='23514';end if;
 if p_family='checkout' then
 context:=public.provider_checkout_context(p_request_id);known:=context->>'session_id';
 if exists(select 1 from public.invoice_payment_evidence where request_id=p_request_id and disposition='quarantined' and reason<>'provider_reconciliation_required' and public.payment_blocker_is_open('checkout_evidence',id)) then raise exception 'Conflicting financial evidence requires separate review' using errcode='23514';end if;
 elsif p_family='refund' then
 context:=public.provider_refund_context(p_request_id);known:=context->>'refund_id';
 if exists(select 1 from public.invoice_refund_evidence where request_id=p_request_id and disposition='quarantined' and public.payment_blocker_is_open('refund_evidence',id)) or
 (exists(select 1 from public.invoice_refund_evidence where request_id=p_request_id and disposition='accepted' and status='failed') and not exists(select 1 from public.invoice_refunds where request_id=p_request_id)) then raise exception 'Conflicting or released refund requires separate review' using errcode='23514';end if;
 else raise exception 'Unsupported reconciliation family' using errcode='23514';end if;
 if context->>'invoice_id' is distinct from p_invoice_id::text or known is null or known is distinct from p_object_id then raise exception 'Known matching provider object required' using errcode='23514';end if;
 select coalesce(jsonb_agg(ref order by ref->>'kind',ref->>'id'),'[]'::jsonb) into refs from (
 select jsonb_build_object('kind','observation','id',id) ref from public.payment_reconciliation_observations where invoice_id=p_invoice_id and family=p_family and request_id=p_request_id and reason in ('provider_object_unavailable','provider_reconciliation_required') and public.payment_blocker_is_open('observation',id)
 union all select jsonb_build_object('kind','checkout_evidence','id',id) from public.invoice_payment_evidence where p_family='checkout' and request_id=p_request_id and disposition='quarantined' and reason='provider_reconciliation_required' and public.payment_blocker_is_open('checkout_evidence',id)
 ) targets;
 return jsonb_build_object('context',context,'blocker_refs',refs,'snapshot_hash',public.payment_reconciliation_hash_internal(p_invoice_id));
end $$

create function public.prepare_payment_reconciliation(p_case_id uuid,p_invoice_id uuid,p_family text,p_request_id uuid,p_provider_object_id text,p_blocker_refs jsonb,p_expected_case_hash text) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.payment_require_admin();c public.payment_reconciliation_cases;target jsonb;refs jsonb;
begin
 if jsonb_typeof(p_blocker_refs) is distinct from 'array' or jsonb_array_length(p_blocker_refs) not between 1 and 100 then raise exception 'Explicit bounded blocker review required' using errcode='23514';end if;
 if exists(select 1 from jsonb_array_elements(p_blocker_refs) r where jsonb_typeof(r)<>'object' or (select count(*) from jsonb_object_keys(r))<>2 or not r ?& array['kind','id'] or r->>'kind' not in ('observation','checkout_evidence','refund_evidence') or r->>'id' !~ '^[a-f0-9-]{36}$') then raise exception 'Invalid blocker references' using errcode='23514';end if;
 select jsonb_agg(r order by r->>'kind',r->>'id') into refs from jsonb_array_elements(p_blocker_refs) r;
 if (select count(distinct r) from jsonb_array_elements(refs) r)<>jsonb_array_length(refs) then raise exception 'Duplicate blocker reference' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_case_id::text,3500));
 select * into c from public.payment_reconciliation_cases where id=p_case_id;
 if found then
 if row(c.actor_id,c.invoice_id,c.family,c.request_id,c.provider_object_id,c.blocker_refs,c.snapshot_hash) is distinct from row(actor,p_invoice_id,p_family,p_request_id,p_provider_object_id,refs,p_expected_case_hash) then raise exception 'Reconciliation review identifier already used' using errcode='23514';end if;return public.read_payment_reconciliation(c.id);end if;
 perform 1 from public.billing_invoices where id=p_invoice_id for update;
 if not found then raise exception 'Invoice unavailable' using errcode='42501';end if;
 target:=public.payment_reconciliation_target_internal(p_invoice_id,p_family,p_request_id,p_provider_object_id);
 if p_expected_case_hash is distinct from target->>'snapshot_hash' then raise exception 'Reconciliation facts changed' using errcode='40001';end if;
 if exists(select 1 from jsonb_array_elements(refs) r where not (target->'blocker_refs') @> jsonb_build_array(r)) then raise exception 'Blocker is not eligible for this review' using errcode='23514';end if;
 insert into public.payment_reconciliation_cases(id,invoice_id,actor_id,family,request_id,provider_object_id,blocker_refs,snapshot_hash) values(p_case_id,p_invoice_id,actor,p_family,p_request_id,p_provider_object_id,refs,p_expected_case_hash);
 return public.read_payment_reconciliation(p_case_id);
end $$

create function public.capture_payment_reconciliation(p_case_id uuid,p_reviewer_id uuid,p_provider_evidence jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare c public.payment_reconciliation_cases;p public.payment_reconciliation_captures;context jsonb;observed timestamptz;proof text;
begin
 select * into c from public.payment_reconciliation_cases where id=p_case_id and actor_id=p_reviewer_id for update;
 if not found or not public.is_active_staff(p_reviewer_id) or not public.has_role(p_reviewer_id,'ADMIN') then raise exception 'Reconciliation capture unavailable' using errcode='42501';end if;
 select * into p from public.payment_reconciliation_captures where case_id=c.id;
 if found then if p.evidence is distinct from p_provider_evidence then raise exception 'Captured proof is immutable; prepare another review' using errcode='23514';end if;return to_jsonb(p);end if;
 perform 1 from public.billing_invoices where id=c.invoice_id for update;
 if c.snapshot_hash is distinct from public.payment_reconciliation_hash_internal(c.invoice_id) then raise exception 'Reconciliation facts changed' using errcode='40001';end if;
 context:=public.payment_reconciliation_target_internal(c.invoice_id,c.family,c.request_id,c.provider_object_id)->'context';
 if jsonb_typeof(p_provider_evidence) is distinct from 'object' or octet_length(p_provider_evidence::text)>4096 then raise exception 'Invalid verified proof' using errcode='23514';end if;
 if exists(select 1 from unnest(array['family','request_id','object_id','account_id','amount_cents','currency','provider_observed_at','status']) k where jsonb_typeof(p_provider_evidence->k) is distinct from 'string') or jsonb_typeof(p_provider_evidence->'livemode') is distinct from 'boolean' then raise exception 'Invalid verified proof types' using errcode='23514';end if;
 if row(p_provider_evidence->>'family',p_provider_evidence->>'request_id',p_provider_evidence->>'object_id',p_provider_evidence->>'account_id',p_provider_evidence->'livemode',p_provider_evidence->>'amount_cents',p_provider_evidence->>'currency') is distinct from row(c.family,c.request_id::text,c.provider_object_id,context->>'account_id',context->'livemode',context->>'amount_cents',context->>'currency') then raise exception 'Provider proof does not match immutable request' using errcode='23514';end if;
 observed:=(p_provider_evidence->>'provider_observed_at')::timestamptz;
 if not isfinite(observed) or observed>clock_timestamp() or observed<clock_timestamp()-interval '5 minutes' then raise exception 'Fresh provider proof required' using errcode='23514';end if;
 if c.family='checkout' then
 if (select count(*) from jsonb_object_keys(p_provider_evidence))<>11 or exists(select 1 from jsonb_object_keys(p_provider_evidence) k where k not in ('family','request_id','object_id','account_id','livemode','amount_cents','currency','provider_observed_at','status','payment_id','source_hash')) or p_provider_evidence->>'source_hash' is distinct from context->>'source_hash' or p_provider_evidence->>'status' not in ('session_open','session_expired','payment_succeeded') or jsonb_typeof(p_provider_evidence->'payment_id') not in ('null','string') then raise exception 'Invalid matching Checkout proof' using errcode='23514';end if;
 if (p_provider_evidence->>'status'='session_open' and exists(select 1 from public.invoice_payment_evidence where request_id=c.request_id and disposition='accepted' and kind='session_expired')) or
 (p_provider_evidence->>'status'<>'payment_succeeded' and exists(select 1 from public.invoice_payments where request_id=c.request_id)) then raise exception 'Provider proof conflicts with terminal financial evidence' using errcode='23514';end if;
 if p_provider_evidence->>'status'='payment_succeeded' and coalesce(p_provider_evidence->>'payment_id','') !~ '^pi_[A-Za-z0-9]+$' then raise exception 'Verified payment identifier required' using errcode='23514';end if;
 else
 if (select count(*) from jsonb_object_keys(p_provider_evidence))<>10 or exists(select 1 from jsonb_object_keys(p_provider_evidence) k where k not in ('family','request_id','object_id','account_id','livemode','amount_cents','currency','provider_observed_at','status','provider_payment_id')) or p_provider_evidence->>'provider_payment_id' is distinct from context->>'provider_payment_id' or p_provider_evidence->>'status' not in ('pending','failed','succeeded') then raise exception 'Invalid matching refund proof' using errcode='23514';end if;
 if p_provider_evidence->>'status'<>'succeeded' and exists(select 1 from public.invoice_refunds where request_id=c.request_id) then raise exception 'Provider proof conflicts with terminal financial evidence' using errcode='23514';end if;
 end if;
 proof:=encode(digest(jsonb_build_object('case_id',c.id,'snapshot_hash',c.snapshot_hash,'blockers',c.blocker_refs,'evidence',p_provider_evidence)::text,'sha256'),'hex');
 insert into public.payment_reconciliation_captures(case_id,evidence,proof_hash,provider_observed_at) values(c.id,p_provider_evidence,proof,observed) returning * into p;
 return to_jsonb(p);
end $$

create function public.complete_payment_reconciliation(p_case_id uuid,p_reviewed_proof_hash text,p_expected_case_hash text,p_attest boolean) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.payment_require_admin();c public.payment_reconciliation_cases;p public.payment_reconciliation_captures;r public.payment_reconciliation_resolutions;e jsonb;applied_id uuid;disposition text;target jsonb;
begin
 select * into c from public.payment_reconciliation_cases where id=p_case_id and actor_id=actor for update;
 if not found then raise exception 'Reconciliation review unavailable' using errcode='42501';end if;
 select * into p from public.payment_reconciliation_captures where case_id=c.id;
 if not found or p_attest is distinct from true or p.proof_hash is distinct from p_reviewed_proof_hash or c.snapshot_hash is distinct from p_expected_case_hash then raise exception 'Exact captured review required' using errcode='23514';end if;
 select * into r from public.payment_reconciliation_resolutions where case_id=c.id;
 if found then return public.read_payment_reconciliation(c.id);end if;
 perform 1 from public.billing_invoices where id=c.invoice_id for update;
 if c.snapshot_hash is distinct from public.payment_reconciliation_hash_internal(c.invoice_id) then raise exception 'Reconciliation facts changed' using errcode='40001';end if;
 if p.provider_observed_at<clock_timestamp()-interval '5 minutes' then raise exception 'Provider proof expired; prepare another review' using errcode='23514';end if;
 target:=public.payment_reconciliation_target_internal(c.invoice_id,c.family,c.request_id,c.provider_object_id);
 if exists(select 1 from jsonb_array_elements(c.blocker_refs) ref where not (target->'blocker_refs') @> jsonb_build_array(ref)) then raise exception 'Reconciliation blockers changed' using errcode='40001';end if;
 e:=p.evidence;
 if c.family='checkout' then
 select x.id,x.disposition into applied_id,disposition from public.apply_checkout_evidence('reconcile:'||c.id,c.request_id,e->>'account_id',(e->>'livemode')::boolean,e->>'status',e->>'object_id',e->>'payment_id',(e->>'amount_cents')::bigint,e->>'currency',e->>'source_hash') x;
 else
 select x.id,x.disposition into applied_id,disposition from public.apply_refund_evidence('reconcile:'||c.id,c.request_id,e->>'account_id',(e->>'livemode')::boolean,e->>'object_id',e->>'provider_payment_id',(e->>'amount_cents')::bigint,e->>'currency',e->>'status') x;
 end if;
 if disposition is distinct from 'accepted' then raise exception 'Financial evidence still requires separate review' using errcode='23514';end if;
 insert into public.payment_reconciliation_resolutions(case_id,actor_id,proof_hash,ledger_evidence_id) values(c.id,actor,p.proof_hash,applied_id);
 insert into public.payment_reconciliation_resolved_blockers(kind,blocker_id,case_id) select ref->>'kind',(ref->>'id')::uuid,c.id from jsonb_array_elements(c.blocker_refs) ref;
 return public.read_payment_reconciliation(c.id);
end $$

create or replace function public.record_payment_reconciliation(p_family text,p_request_id uuid,p_reason text) returns public.payment_reconciliation_observations language plpgsql security definer set search_path=public as $$
declare invoice uuid;result public.payment_reconciliation_observations;
begin
 if p_family is null or p_family not in ('checkout','refund') or p_reason is null or p_reason not in ('provider_context_mismatch','provider_object_unavailable','provider_reconciliation_required') then raise exception 'Invalid payment reconciliation observation' using errcode='23514';end if;
 if p_family='checkout' then select invoice_id into invoice from public.invoice_checkout_attempts where id=p_request_id;else select invoice_id into invoice from public.invoice_refund_requests where id=p_request_id;end if;
 if invoice is null then raise exception 'Payment request unavailable' using errcode='42501';end if;
 perform 1 from public.billing_invoices where id=invoice for update;
 select * into result from public.payment_reconciliation_observations where family=p_family and request_id=p_request_id and reason=p_reason and public.payment_blocker_is_open('observation',id) order by created_at,id limit 1;
 if found then return result;end if;
 insert into public.payment_reconciliation_observations(family,request_id,invoice_id,reason) values(p_family,p_request_id,invoice,p_reason) returning * into result;return result;
end $$

-- Update the live function definitions without editing prior migration files.
do $$declare signature text;definition text;original text;required text;begin
 foreach signature in array array['public.checkout_state_internal(uuid)','public.refund_state_internal(uuid)','public.guard_payment_reconciliation()','public.inspect_payment_collection(uuid,text,text,text)','public.read_invoice_payment_state(uuid,uuid)'] loop
 select pg_get_functiondef(signature::regprocedure) into definition;
 original:=definition;
 required:=case signature
 when 'public.checkout_state_internal(uuid)' then 'where family=''checkout'' and request_id=p_request_id)'
 when 'public.refund_state_internal(uuid)' then 'where family=''refund'' and request_id=p_request_id)'
 when 'public.guard_payment_reconciliation()' then 'exists(select 1 from public.payment_reconciliation_observations where invoice_id=invoice)'
 when 'public.inspect_payment_collection(uuid,text,text,text)' then 'exists(select 1 from public.payment_reconciliation_observations where invoice_id=g.invoice_id)'
 else 'jsonb_agg(to_jsonb(o) order by o.created_at,o.id)' end;
 if strpos(definition,required)=0 or (signature in ('public.checkout_state_internal(uuid)','public.refund_state_internal(uuid)') and strpos(definition,'and disposition=''quarantined'')')=0) then raise exception 'Reconciliation migration expected definition pattern missing: %',signature;end if;
 definition:=replace(definition,'where family=''checkout'' and request_id=p_request_id)','where family=''checkout'' and request_id=p_request_id and public.payment_blocker_is_open(''observation'',id))');
 definition:=replace(definition,'where family=''refund'' and request_id=p_request_id)','where family=''refund'' and request_id=p_request_id and public.payment_blocker_is_open(''observation'',id))');
 if signature='public.checkout_state_internal(uuid)' then definition:=replace(definition,'and disposition=''quarantined'')','and disposition=''quarantined'' and public.payment_blocker_is_open(''checkout_evidence'',id))');end if;
 if signature='public.refund_state_internal(uuid)' then definition:=replace(definition,'and disposition=''quarantined'')','and disposition=''quarantined'' and public.payment_blocker_is_open(''refund_evidence'',id))');end if;
 definition:=replace(definition,'exists(select 1 from public.payment_reconciliation_observations where invoice_id=invoice)','public.payment_invoice_has_observations(invoice)');
 definition:=replace(definition,'exists(select 1 from public.payment_reconciliation_observations where invoice_id=g.invoice_id)','public.payment_invoice_has_observations(g.invoice_id)');
 definition:=replace(definition,'jsonb_agg(to_jsonb(o) order by o.created_at,o.id)','jsonb_agg(to_jsonb(o)||jsonb_build_object(''resolved'',not public.payment_blocker_is_open(''observation'',o.id)) order by o.created_at,o.id)');
 if definition=original then raise exception 'Reconciliation migration expected definition pattern missing: %',signature;end if;
 execute definition;
 end loop;
end $$

do $$declare f record;begin
 for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in ('payment_require_admin','payment_blocker_is_open','payment_invoice_has_observations','payment_reconciliation_hash_internal','payment_reconciliation_target_internal','preview_payment_reconciliation','read_payment_reconciliation','prepare_payment_reconciliation','capture_payment_reconciliation','complete_payment_reconciliation') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname in ('preview_payment_reconciliation','read_payment_reconciliation','prepare_payment_reconciliation','complete_payment_reconciliation') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 if f.proname='capture_payment_reconciliation' then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

-- Preserve existing trigger permissions and reject usable payment capabilities at persistence boundaries.
create or replace function public.reject_persisted_document_capability() returns trigger language plpgsql set search_path=public as $$
begin
 if to_jsonb(NEW)::text ~ '(v1|p1|s1)\.[A-Za-z0-9_-]{43}' then
  raise exception 'Use the reviewed private-link workflow; private capabilities cannot be stored in message history' using errcode='23514';
 end if;
 return NEW;
end $$

do $$declare t text;begin foreach t in array array['payment_delivery_requests','payment_delivery_captures','payment_delivery_outbox_links'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 execute format('create trigger payment_delivery_immutable before update or delete on public.%I for each row execute function public.payment_immutable()',t);
 execute format('create trigger reject_payment_capability before insert or update on public.%I for each row execute function public.reject_persisted_document_capability()',t);
 end loop;end $$

create function public.payment_delivery_current(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.payment_delivery_requests;g public.payment_collection_grants;c public.payment_collection_captures;a public.invoice_email_requests;p public.invoice_email_payloads;attachment jsonb;
begin
 select * into r from public.payment_delivery_requests where id=p_id for share;
 if not found or not public.is_active_staff(r.actor_id) then raise exception 'Payment delivery unavailable' using errcode='42501';end if;
 select * into g from public.payment_collection_grants where id=r.grant_id for share;
 select * into c from public.payment_collection_captures where grant_id=g.id;
 perform 1 from public.billing_invoices where id=r.invoice_id for share;
 perform 1 from public.clients where id=r.client_id and public.communication_recipient(r.channel,case when r.channel='EMAIL' then primary_email else primary_phone end)=r.recipient for share;
 if not found or public.communication_is_suppressed(r.channel,r.recipient,r.client_id) then raise exception 'Payment delivery contact unavailable' using errcode='42501';end if;
 perform 1 from public.conversations where id=r.conversation_id and client_id=r.client_id for share;
 if not found then raise exception 'Payment delivery conversation unavailable' using errcode='42501';end if;
 if g.actor_id<>r.actor_id or public.payment_collection_state_internal(g.id)<>'reviewed' or g.expires_at<=clock_timestamp() or c.grant_id is null or r.source_hash is distinct from public.payment_source_hash_internal(r.invoice_id,r.client_id) or r.amount_cents::text is distinct from public.payment_balance_internal(r.invoice_id)->>'outstanding_cents' then raise exception 'Payment collection no longer eligible for delivery' using errcode='42501';end if;
 if public.inspect_payment_collection(g.id,c.collection_token_hash,c.origin,c.key_version)->>'state' in ('paid','partially_refunded','refunded','reconciliation') then raise exception 'Payment collection is not collectible' using errcode='42501';end if;
 if r.invoice_email_request_id is not null then
 select * into a from public.invoice_email_requests where id=r.invoice_email_request_id for share;
 select * into p from public.invoice_email_payloads where request_id=a.id for share;
 perform public.invoice_email_context(a.id);
 if row(a.actor_id,a.invoice_id,a.client_id,a.conversation_id,a.recipient,a.subject,a.body) is distinct from row(r.actor_id,r.invoice_id,r.client_id,r.conversation_id,r.recipient,r.subject,r.body_template) or a.state<>'ready' or p.payload_text is null or p.payload_hash is distinct from r.invoice_payload_hash or p.payload_hash<>encode(sha256(convert_to(p.payload_text,'UTF8')),'hex') then raise exception 'Reviewed invoice attachment unavailable' using errcode='42501';end if;
 attachment:=p.payload_text::jsonb;
 -- Inspect the decoded supported HTML; do not claim arbitrary attachment encodings are scrubbed.
 if convert_from(decode(attachment#>>'{attachments,0,content}','base64'),'UTF8') ~ '(v1|p1|s1)\.[A-Za-z0-9_-]{43}' then raise exception 'Private capabilities cannot enter invoice attachments' using errcode='23514';end if;
 end if;
 return jsonb_build_object('request',to_jsonb(r)||jsonb_build_object('amount_cents',r.amount_cents::text),'grant',public.payment_collection_read_internal(g.id)->'grant','capability',to_jsonb(c),'invoice_payload',attachment,'invoice_payload_text',p.payload_text);
end $$

create function public.recover_payment_delivery(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.payment_delivery_requests;p public.payment_delivery_captures;o public.communication_outbox;
begin
 select * into r from public.payment_delivery_requests where id=p_request_id and actor_id=actor;
 if not found then return null;end if;
 select * into p from public.payment_delivery_captures where request_id=r.id;
 select box.* into o from public.communication_outbox box join public.payment_delivery_outbox_links l on l.outbox_id=box.id where l.request_id=r.id;
 return jsonb_build_object('request',to_jsonb(r)||jsonb_build_object('amount_cents',r.amount_cents::text),'capture',case when p.request_id is not null then to_jsonb(p) end,'receipt',case when o.id is not null then jsonb_build_object('outbox_id',o.id,'message_id',o.message_id,'state',o.state,'queued',true,'delivered',o.state='delivered') end);
end $$

create function public.prepare_payment_delivery(p_request_id uuid,p_grant_id uuid,p_conversation_id uuid,p_channel text,p_recipient text,p_subject text,p_body_template text,p_invoice_email_request_id uuid default null,p_invoice_payload_hash text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.payment_delivery_requests;g public.payment_collection_grants;
begin
 if p_request_id is null or p_channel is null or p_channel not in ('SMS','EMAIL') or p_recipient is null or public.communication_recipient(p_channel,p_recipient) is distinct from p_recipient or p_subject is null or p_body_template is null or length(p_body_template) not between 16 and 100000 or (length(p_body_template)-length(replace(p_body_template,'{{payment_link}}','')))<>16 or (p_channel='SMS' and (p_subject<>'' or length(p_body_template)>1600)) or (p_channel='EMAIL' and length(trim(p_subject)) not between 1 and 500) or p_subject like '%{{payment_link}}%' then raise exception 'Exact payment message template required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_request_id::text,3700));
 select * into r from public.payment_delivery_requests where id=p_request_id;
 if found then
 if r.actor_id<>actor or row(r.grant_id,r.conversation_id,r.channel,r.recipient,r.subject,r.body_template,r.invoice_email_request_id,r.invoice_payload_hash) is distinct from row(p_grant_id,p_conversation_id,p_channel,p_recipient,p_subject,p_body_template,p_invoice_email_request_id,p_invoice_payload_hash) then raise exception 'Payment delivery request already used' using errcode='23505';end if;
 return public.recover_payment_delivery(r.id);end if;
 select * into g from public.payment_collection_grants where id=p_grant_id and actor_id=actor;
 if not found then raise exception 'Own reviewed collection required' using errcode='42501';end if;
 insert into public.payment_delivery_requests(id,grant_id,actor_id,invoice_id,client_id,source_hash,amount_cents,conversation_id,channel,recipient,subject,body_template,invoice_email_request_id,invoice_payload_hash) values(p_request_id,g.id,actor,g.invoice_id,g.client_id,g.source_hash,g.amount_cents,p_conversation_id,p_channel,p_recipient,p_subject,p_body_template,p_invoice_email_request_id,p_invoice_payload_hash);
 perform public.payment_delivery_current(p_request_id);
 return public.recover_payment_delivery(p_request_id);
end $$

create function public.payment_delivery_capture_context(p_request_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
begin perform public.communication_require_service();
 if not exists(select 1 from public.payment_delivery_requests where id=p_request_id and actor_id=p_actor_id) then raise exception 'Payment delivery ownership mismatch' using errcode='42501';end if;
 return public.payment_delivery_current(p_request_id)||jsonb_build_object('capture',(select to_jsonb(p) from public.payment_delivery_captures p where request_id=p_request_id));end $$

create function public.capture_payment_delivery(p_request_id uuid,p_actor_id uuid,p_sender_config jsonb,p_message_hash text,p_payload_hash text) returns void language plpgsql security definer set search_path=public as $$
declare r public.payment_delivery_requests;p public.payment_delivery_captures;context jsonb;
begin perform public.communication_require_service();
 select * into r from public.payment_delivery_requests where id=p_request_id and actor_id=p_actor_id for update;
 if not found then raise exception 'Payment delivery ownership mismatch' using errcode='42501';end if;
 select * into p from public.payment_delivery_captures where request_id=r.id;
 if found then if row(p.sender_config,p.message_hash,p.payload_hash) is distinct from row(p_sender_config,p_message_hash,p_payload_hash) then raise exception 'Captured payment delivery is immutable' using errcode='23505';end if;return;end if;
 context:=public.payment_delivery_current(r.id);
 if p_sender_config is null or jsonb_typeof(p_sender_config)<>'object' or octet_length(p_sender_config::text)>2048 or exists(select 1 from jsonb_each(p_sender_config) e where jsonb_typeof(e.value)<>'string') or (r.channel='EMAIL' and (not p_sender_config ?& array['from','reply_to'] or p_sender_config-array['from','reply_to']<>'{}' or public.communication_recipient('EMAIL',p_sender_config->>'reply_to') is null or public.communication_recipient('EMAIL',coalesce(substring(p_sender_config->>'from' from '<([^<>]+)>$'),p_sender_config->>'from')) is null)) or (r.channel='SMS' and (not p_sender_config ?& array['from','account_sid'] or p_sender_config-array['from','account_sid']<>'{}' or public.communication_recipient('SMS',p_sender_config->>'from') is null or coalesce(p_sender_config->>'account_sid','') !~ '^AC[A-Za-z0-9]{32}$')) then raise exception 'Invalid frozen payment sender configuration' using errcode='23514';end if;
 if r.invoice_email_request_id is not null and row(context#>>'{invoice_payload,from}',context#>>'{invoice_payload,reply_to}') is distinct from row(p_sender_config->>'from',p_sender_config->>'reply_to') then raise exception 'Invoice attachment sender differs from payment message' using errcode='23514';end if;
 insert into public.payment_delivery_captures(request_id,sender_config,message_hash,payload_hash) values(r.id,p_sender_config,p_message_hash,p_payload_hash);
end $$

create function public.enqueue_payment_delivery(p_request_id uuid,p_reviewed_message_hash text,p_reviewed_payload_hash text,p_attest boolean) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.payment_delivery_requests;p public.payment_delivery_captures;o public.communication_outbox;
begin
 select * into r from public.payment_delivery_requests where id=p_request_id and actor_id=actor for update;
 select * into p from public.payment_delivery_captures where request_id=r.id;
 if r.id is null or p.request_id is null or p_attest is distinct from true or row(p.message_hash,p.payload_hash) is distinct from row(p_reviewed_message_hash,p_reviewed_payload_hash) then raise exception 'Exact payment message and attachment review required' using errcode='42501';end if;
 select box.* into o from public.communication_outbox box join public.payment_delivery_outbox_links l on l.outbox_id=box.id where l.request_id=r.id;
 if found then return o;end if;
 perform public.payment_delivery_current(r.id);
 perform pg_advisory_xact_lock(hashtextextended(r.id::text,914));
 if exists(select 1 from public.communication_outbox where request_id=r.id) then raise exception 'Request belongs to another queue workflow' using errcode='23505';end if;
 o:=public.enqueue_prepared_communication_internal(actor,r.id,r.conversation_id,r.channel,r.recipient,r.subject,r.body_template,'{}');
 insert into public.payment_delivery_outbox_links(outbox_id,request_id,reviewed_message_hash,reviewed_payload_hash,queued_by) values(o.id,r.id,p.message_hash,p.payload_hash,actor);
 return o;
end $$

create function public.payment_delivery_context(p_outbox_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;l public.payment_delivery_outbox_links;r public.payment_delivery_requests;p public.payment_delivery_captures;context jsonb;
begin perform public.communication_require_service();
 select * into o from public.communication_outbox where id=p_outbox_id for update;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 select * into l from public.payment_delivery_outbox_links where outbox_id=o.id;
 if not found then return null;end if;
 select * into r from public.payment_delivery_requests where id=l.request_id;
 select * into p from public.payment_delivery_captures where request_id=r.id;
 context:=public.payment_delivery_current(r.id);
 if row(o.channel,o.recipient,o.subject,o.body,o.created_by,o.client_id,o.conversation_id) is distinct from row(r.channel,r.recipient,r.subject,r.body_template,r.actor_id,r.client_id,r.conversation_id) or row(p.message_hash,p.payload_hash) is distinct from row(l.reviewed_message_hash,l.reviewed_payload_hash) then raise exception 'Payment delivery review unavailable' using errcode='42501';end if;
 return context||jsonb_build_object('capture',to_jsonb(p));
end $$

create function public.start_communication_attempt(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare o public.communication_outbox;context jsonb;valid boolean;
begin perform public.communication_require_service();
 select * into o from public.communication_outbox where id=p_id for update;
 if not found or o.state<>'claimed' or o.lease_token is distinct from p_lease_token or o.lease_expires_at<=now() or o.attempt_started_at is not null then raise exception 'Outbox lease unavailable' using errcode='40001';end if;
 if exists(select 1 from public.payment_delivery_outbox_links where outbox_id=o.id) then
 begin
 context:=public.payment_delivery_context(p_id,p_lease_token);
 valid:=p_provider_config->>'payment_delivery_message_hash'=context#>>'{capture,message_hash}' and p_provider_config->>'payment_delivery_payload_hash'=context#>>'{capture,payload_hash}' and p_provider_config-array['payment_delivery_message_hash','payment_delivery_payload_hash']=context#>'{capture,sender_config}';
 exception when sqlstate '42501' or sqlstate '23514' then valid:=false;end;
 if valid is distinct from true then update public.communication_outbox set state='failed',last_error='payment_delivery_source_or_materialization_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=o.id returning * into o;return o;end if;
 return public.start_communication_attempt_without_payment_delivery_guard(p_id,p_lease_token,p_provider_config-array['payment_delivery_message_hash','payment_delivery_payload_hash']);
 end if;
 return public.start_communication_attempt_without_payment_delivery_guard(p_id,p_lease_token,p_provider_config);
end $$

do $$declare f record;begin for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in ('payment_delivery_current','recover_payment_delivery','prepare_payment_delivery','payment_delivery_capture_context','capture_payment_delivery','enqueue_payment_delivery','payment_delivery_context','start_communication_attempt') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname in ('recover_payment_delivery','prepare_payment_delivery','enqueue_payment_delivery') then execute format('grant execute on function %s to authenticated',f.signature);
 elsif f.proname<>'payment_delivery_current' then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;end $$

-- Invoice-scoped administrator discovery uses only already attributed provider IDs.
create function public.list_payment_reconciliation_workspace(p_invoice_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare actor uuid:=public.payment_require_admin();r record;context jsonb;target jsonb;known text;reviewable boolean;targets jsonb:='[]'::jsonb;cases jsonb;
begin
 if not exists(select 1 from public.billing_invoices where id=p_invoice_id) then raise exception 'Invoice unavailable' using errcode='42501';end if;
 for r in
 select 'checkout'::text family,id,created_at from public.invoice_checkout_attempts where invoice_id=p_invoice_id
 union all select 'refund'::text family,id,created_at from public.invoice_refund_requests where invoice_id=p_invoice_id
 order by created_at desc,id
 loop
  if r.family='checkout' then context:=public.provider_checkout_context(r.id);known:=context->>'session_id';
  else context:=public.provider_refund_context(r.id);known:=context->>'refund_id';end if;
  if known is null then continue;end if;
  reviewable:=false;
  begin
   target:=public.payment_reconciliation_target_internal(p_invoice_id,r.family,r.id,known);
   reviewable:=jsonb_array_length(target->'blocker_refs')>0;
  exception when check_violation or insufficient_privilege then
   -- Unsupported conflicts remain visible, never converted into a clear-all action.
   reviewable:=false;
  end;
  targets:=targets||jsonb_build_array(jsonb_build_object('family',r.family,'request_id',r.id,'provider_object_id',known,'amount_cents',context->>'amount_cents','currency',context->>'currency','state',context->>'state','reviewable',reviewable));
 end loop;
 select coalesce(jsonb_agg(public.read_payment_reconciliation(c.id) order by c.created_at desc,c.id),'[]'::jsonb) into cases
 from (select id,created_at from public.payment_reconciliation_cases where invoice_id=p_invoice_id and actor_id=actor order by created_at desc,id limit 100) c;
 return jsonb_build_object('invoice_id',p_invoice_id,'targets',targets,'cases',cases,'has_more_cases',exists(select 1 from public.payment_reconciliation_cases where invoice_id=p_invoice_id and actor_id=actor offset 100));
end $$

-- Original actor-scoped discovery; receipt/history reads do not reauthorize delivery.
create function public.list_payment_deliveries(p_invoice_id uuid,p_grant_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();client uuid;items jsonb;more boolean;
begin
 select client_id into client from public.billing_invoices where id=p_invoice_id;
 if not found then raise exception 'Invoice unavailable' using errcode='42501';end if;
 if p_grant_id is not null and not exists(select 1 from public.payment_collection_grants where id=p_grant_id and invoice_id=p_invoice_id and client_id=client and actor_id=actor) then raise exception 'Payment grant unavailable for this invoice' using errcode='42501';end if;
 select coalesce(jsonb_agg(public.recover_payment_delivery(r.id) order by r.created_at desc,r.id desc),'[]'::jsonb) into items
 from (select id,created_at from public.payment_delivery_requests where invoice_id=p_invoice_id and client_id=client and actor_id=actor and (p_grant_id is null or grant_id=p_grant_id) order by created_at desc,id desc limit 100) r;
 select exists(select 1 from public.payment_delivery_requests where invoice_id=p_invoice_id and client_id=client and actor_id=actor and (p_grant_id is null or grant_id=p_grant_id) offset 100) into more;
 return jsonb_build_object('invoice_id',p_invoice_id,'client_id',client,'grant_id',p_grant_id,'deliveries',items,'has_more',more);
end $$

create function public.stripe_event_retry_target(p_receipt_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare r public.stripe_event_receipts;w public.stripe_event_work;c jsonb;invoice uuid;family text;last_reason text;
begin
 select * into r from public.stripe_event_receipts where id=p_receipt_id;
 select * into w from public.stripe_event_work where receipt_id=p_receipt_id;
 if r.id is null or r.disposition<>'queued' or w.state<>'quarantined' or w.reason<>'retry_exhausted' or w.cycle_attempt_count<>5 or w.lease_token is not null then raise exception 'Receipt is not eligible for audited retry' using errcode='23514';end if;
 select reason into last_reason from public.stripe_event_work_history where receipt_id=r.id and action='exhausted' and cycle_no=w.cycle_no order by created_at desc,id desc limit 1;
 if last_reason is null or last_reason not in ('provider_unavailable','rate_limited','transport_unknown','processing_error') then raise exception 'Documented recoverable processing failure required' using errcode='23514';end if;
 if not exists(select 1 from public.payment_provider_profiles where account_id=r.account_id and livemode=r.livemode) then raise exception 'Receipt provider configuration differs' using errcode='23514';end if;
 if r.event_type in ('checkout.session.completed','checkout.session.expired','checkout.session.async_payment_succeeded','checkout.session.async_payment_failed') then family:='checkout';c:=public.provider_checkout_context(r.request_id);
 elsif r.event_type in ('refund.created','refund.updated','refund.failed') then family:='refund';c:=public.provider_refund_context(r.request_id);
 else raise exception 'Unsupported receipt cannot be requeued' using errcode='23514';end if;
 if row(c->>'account_id',c->'livemode') is distinct from row(r.account_id,to_jsonb(r.livemode)) then raise exception 'Receipt provider configuration differs' using errcode='23514';end if;
 invoice:=(c->>'invoice_id')::uuid;
 -- Requires an accepted matching object and preserves all 3500 mismatch exclusions.
 perform public.payment_reconciliation_target_internal(invoice,family,r.request_id,r.object_id);
 return jsonb_build_object('invoice_id',invoice,'family',family,'request_id',r.request_id,'object_id',r.object_id,'last_failure',last_reason);
end $$

create function public.preview_stripe_event_retry(p_receipt_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare target jsonb;eligible boolean:=true;
begin perform public.payment_require_admin();
 if not exists(select 1 from public.stripe_event_receipts where id=p_receipt_id) then raise exception 'Receipt unavailable' using errcode='42501';end if;
 begin target:=public.stripe_event_retry_target(p_receipt_id);exception when check_violation or insufficient_privilege then eligible:=false;target:=null;end;
 return jsonb_build_object('receipt',(select to_jsonb(r) from public.stripe_event_receipts r where id=p_receipt_id),'work',(select to_jsonb(w)-array['lease_token'] from public.stripe_event_work w where receipt_id=p_receipt_id),'eligible',eligible,'target',target,'expected_work_hash',public.stripe_event_retry_hash(p_receipt_id),
 'cycles',coalesce((select jsonb_agg(to_jsonb(c) order by cycle_no) from public.stripe_event_retry_cycles c where receipt_id=p_receipt_id),'[]'::jsonb),
 'history',coalesce((select jsonb_agg((to_jsonb(h)-'lease_token')||jsonb_build_object('cycle_attempt_count',coalesce(h.cycle_attempt_count,h.attempt_count)) order by created_at,id) from public.stripe_event_work_history h where receipt_id=p_receipt_id),'[]'::jsonb));
end $$

create function public.requeue_stripe_event(p_resolution_id uuid,p_receipt_id uuid,p_expected_work_hash text,p_reason text,p_attest boolean) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.payment_require_admin();saved public.stripe_event_retry_cycles;w public.stripe_event_work;target jsonb;
begin
 if p_resolution_id is null or p_attest is distinct from true or p_expected_work_hash is null or p_expected_work_hash !~ '^[a-f0-9]{64}$' or p_reason is null or p_reason not in ('provider_recovered','rate_limit_resolved','processor_repaired') then raise exception 'Exact administrator retry review required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_resolution_id::text,4000));
 select * into saved from public.stripe_event_retry_cycles where id=p_resolution_id;
 if found then
 if row(saved.receipt_id,saved.actor_id,saved.expected_work_hash,saved.reason) is distinct from row(p_receipt_id,actor,p_expected_work_hash,p_reason) then raise exception 'Retry review identifier already used' using errcode='23505';end if;
 return to_jsonb(saved);end if;
 select * into w from public.stripe_event_work where receipt_id=p_receipt_id for update;
 if not found then raise exception 'Receipt unavailable' using errcode='42501';end if;
 target:=public.stripe_event_retry_target(p_receipt_id);
 perform 1 from public.billing_invoices where id=(target->>'invoice_id')::uuid for update;
 if public.stripe_event_retry_hash(p_receipt_id) is distinct from p_expected_work_hash then raise exception 'Retry work or financial context changed' using errcode='40001';end if;
 perform public.stripe_event_retry_target(p_receipt_id);
 insert into public.stripe_event_retry_cycles(id,receipt_id,actor_id,cycle_no,expected_work_hash,reason,previous_attempt_count,previous_cycle_attempt_count) values(p_resolution_id,p_receipt_id,actor,w.cycle_no+1,p_expected_work_hash,p_reason,w.attempt_count,w.cycle_attempt_count) returning * into saved;
 update public.stripe_event_work set state='queued',cycle_no=w.cycle_no+1,cycle_attempt_count=0,available_at=clock_timestamp(),reason='',lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where receipt_id=p_receipt_id;
 return to_jsonb(saved);
end $$

create or replace function public.claim_stripe_event() returns jsonb language plpgsql security definer set search_path=public as $$
declare w public.stripe_event_work;r public.stripe_event_receipts;
begin
 select * into w from public.stripe_event_work where (state='queued' and available_at<=clock_timestamp()) or (state='processing' and lease_expires_at<=clock_timestamp()) order by available_at,receipt_id for update skip locked limit 1;
 if not found then return null;end if;
 if w.cycle_attempt_count>=5 then
 update public.stripe_event_work set state='quarantined',lease_token=null,lease_expires_at=null,reason='retry_exhausted',updated_at=clock_timestamp() where receipt_id=w.receipt_id;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason,cycle_no,cycle_attempt_count,lease_token) values(w.receipt_id,'exhausted',w.attempt_count,'retry_exhausted',w.cycle_no,w.cycle_attempt_count,w.lease_token);return null;
 end if;
 update public.stripe_event_work set state='processing',attempt_count=attempt_count+1,cycle_attempt_count=cycle_attempt_count+1,lease_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '2 minutes',updated_at=clock_timestamp() where receipt_id=w.receipt_id returning * into w;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason,cycle_no,cycle_attempt_count,lease_token) values(w.receipt_id,'claimed',w.attempt_count,'',w.cycle_no,w.cycle_attempt_count,w.lease_token);
 select * into strict r from public.stripe_event_receipts where id=w.receipt_id;
 return jsonb_build_object('receipt',to_jsonb(r),'lease_token',w.lease_token,'lease_expires_at',w.lease_expires_at,'attempt_count',w.attempt_count,'cycle_no',w.cycle_no,'cycle_attempt_count',w.cycle_attempt_count);
end $$

create or replace function public.retry_stripe_event(p_receipt_id uuid,p_lease_token uuid,p_reason text) returns text language plpgsql security definer set search_path=public as $$
declare w public.stripe_event_work;next_state text;
begin
 if p_reason is null or p_reason not in ('provider_unavailable','rate_limited','transport_unknown','processing_error') then raise exception 'Invalid Stripe retry reason' using errcode='23514';end if;
 select * into w from public.stripe_event_work where receipt_id=p_receipt_id for update;
 if not found or w.state<>'processing' or w.lease_token is distinct from p_lease_token or w.lease_expires_at<=clock_timestamp() then raise exception 'Stripe worker lease is unavailable' using errcode='42501';end if;
 next_state:=case when w.cycle_attempt_count>=5 then 'quarantined' else 'queued' end;
 update public.stripe_event_work set state=next_state,reason=case when next_state='quarantined' then 'retry_exhausted' else p_reason end,available_at=clock_timestamp()+make_interval(secs=>least(3600,30*(2^w.cycle_attempt_count)::integer)),lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where receipt_id=w.receipt_id;
 insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason,cycle_no,cycle_attempt_count,lease_token) values(w.receipt_id,case when next_state='quarantined' then 'exhausted' else 'retry' end,w.attempt_count,p_reason,w.cycle_no,w.cycle_attempt_count,w.lease_token);
 return next_state;
end $$

do $$declare definition text;old text:='insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason) values(w.receipt_id,outcome_state,w.attempt_count,outcome_reason);';begin
 select pg_get_functiondef('public.finish_stripe_event(uuid,uuid,jsonb)'::regprocedure) into definition;
 if strpos(definition,old)=0 then raise exception 'Stripe completion history definition drifted';end if;
 execute replace(definition,old,'insert into public.stripe_event_work_history(receipt_id,action,attempt_count,reason,cycle_no,cycle_attempt_count,lease_token) values(w.receipt_id,outcome_state,w.attempt_count,outcome_reason,w.cycle_no,w.cycle_attempt_count,w.lease_token);');
end $$

create or replace function public.read_stripe_event_queue(p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin perform public.clinical_require_staff();
 return coalesce((select jsonb_agg(item order by created_at desc,id) from (select r.id,r.created_at,to_jsonb(r)||jsonb_build_object('work_state',w.state,'attempt_count',w.attempt_count,'cycle_no',w.cycle_no,'cycle_attempt_count',w.cycle_attempt_count,'work_reason',w.reason,'available_at',w.available_at) item from public.stripe_event_receipts r join public.stripe_event_work w on w.receipt_id=r.id order by r.created_at desc,r.id limit greatest(1,least(coalesce(p_limit,100),250))) selected),'[]'::jsonb);
end $$

create table public.lab_report_acknowledgments (
 id uuid primary key,actor_id uuid not null references auth.users(id),report_id uuid not null references public.lab_report_versions(id),capture_hash text not null,document_version integer not null,created_at timestamptz not null default now(),unique(report_id,actor_id)
)

do $$declare t text;begin foreach t in array array['lab_source_accounts','lab_report_receipts','lab_report_byte_captures','lab_order_source_reviews','lab_report_versions','lab_report_acknowledgments'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 execute format('create trigger immutable_lab_provenance before update or delete on public.%I for each row execute function public.lab_provenance_immutable()',t);
 end loop;end $$

create function public.review_lab_source_account(p_id uuid,p_provider_label text,p_account_reference text,p_environment_label text,p_review_note text) returns public.lab_source_accounts language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.lab_source_accounts;
begin
 if not public.has_role(actor,'ADMIN') then raise exception 'Active administrator required' using errcode='42501';end if;
 if p_id is null or p_provider_label is null or length(trim(p_provider_label)) not between 1 and 200 or p_account_reference is null or length(trim(p_account_reference)) not between 1 and 200 or p_environment_label is null or length(trim(p_environment_label)) not between 1 and 100 or p_review_note is null or length(trim(p_review_note)) not between 1 and 2000 then raise exception 'Reviewed nonsecret source identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,4100));
 select * into r from public.lab_source_accounts where id=p_id;
 if found then if row(r.actor_id,r.provider_label,r.account_reference,r.environment_label,r.review_note) is distinct from row(actor,p_provider_label,p_account_reference,p_environment_label,p_review_note) then raise exception 'Source review UUID already used' using errcode='23505';end if;return r;end if;
 insert into public.lab_source_accounts(id,actor_id,provider_label,account_reference,environment_label,review_note) values(p_id,actor,p_provider_label,p_account_reference,p_environment_label,p_review_note) returning * into r;return r;
end $$

create function public.stage_lab_report_receipt(p_id uuid,p_source_account_id uuid,p_document_id uuid,p_document_version integer,p_source_patient_reference text,p_source_order_reference text,p_source_report_reference text,p_received_at timestamptz) returns public.lab_report_receipts language plpgsql security definer set search_path=public,extensions as $$
declare actor uuid:=public.clinical_require_staff();r public.lab_report_receipts;d public.patient_documents;fingerprint text;
begin
 if p_id is null or p_received_at is null or not isfinite(p_received_at) or p_received_at>clock_timestamp() or exists(select 1 from unnest(array[p_source_patient_reference,p_source_order_reference,p_source_report_reference]) v where v is null or length(trim(v)) not between 1 and 500) then raise exception 'Explicit staff-entered report provenance required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,4101));
 select * into r from public.lab_report_receipts where id=p_id;
 if found then if row(r.actor_id,r.source_account_id,r.document_id,r.document_version,r.source_patient_reference,r.source_order_reference,r.source_report_reference,r.received_at) is distinct from row(actor,p_source_account_id,p_document_id,p_document_version,p_source_patient_reference,p_source_order_reference,p_source_report_reference,p_received_at) then raise exception 'Receipt UUID already used' using errcode='23505';end if;return r;end if;
 perform 1 from public.lab_source_accounts where id=p_source_account_id and manual_import_enabled;
 if not found then raise exception 'Reviewed source account required' using errcode='42501';end if;
 select * into d from public.patient_documents where id=p_document_id and status='ready' and version=p_document_version for share;
 if not found then raise exception 'Ready private document and exact version required' using errcode='42501';end if;
 fingerprint:=encode(digest(jsonb_build_array(p_id,actor,p_source_account_id,d.id,d.version,d.pet_id,d.mime_type,d.file_size,p_source_patient_reference,p_source_order_reference,p_source_report_reference,p_received_at,'staff_entered_v1')::text,'sha256'),'hex');
 insert into public.lab_report_receipts(id,actor_id,source_account_id,document_id,document_version,pet_id,source_patient_reference,source_order_reference,source_report_reference,received_at,mime_type,file_size,receipt_hash) values(p_id,actor,p_source_account_id,d.id,d.version,d.pet_id,p_source_patient_reference,p_source_order_reference,p_source_report_reference,p_received_at,d.mime_type,d.file_size,fingerprint) returning * into r;return r;
end $$

create function public.lab_report_capture_context(p_receipt_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.lab_report_receipts;d public.patient_documents;
begin
 select * into r from public.lab_report_receipts where id=p_receipt_id and actor_id=p_actor_id;
 if not found or not public.is_active_staff(p_actor_id) then raise exception 'Staged receipt actor unavailable' using errcode='42501';end if;
 select * into d from public.patient_documents where id=r.document_id and pet_id=r.pet_id and status='ready' and version=r.document_version for share;
 if not found then raise exception 'Original document no longer ready at staged version' using errcode='40001';end if;
 return jsonb_build_object('receipt',to_jsonb(r),'document',jsonb_build_object('id',d.id,'version',d.version,'bucket','patient-documents','file_path',d.file_path,'mime_type',d.mime_type,'file_size',d.file_size),'capture',(select to_jsonb(c) from public.lab_report_byte_captures c where receipt_id=r.id));
end $$

create function public.capture_lab_report_bytes(p_receipt_id uuid,p_actor_id uuid,p_expected_receipt_hash text,p_document_version integer,p_content_sha256 text,p_file_size bigint,p_mime_type text) returns public.lab_report_byte_captures language plpgsql security definer set search_path=public,extensions as $$
declare r public.lab_report_receipts;c public.lab_report_byte_captures;fingerprint text;
begin
 select * into r from public.lab_report_receipts where id=p_receipt_id and actor_id=p_actor_id for update;
 if not found or not public.is_active_staff(p_actor_id) then raise exception 'Staged receipt actor unavailable' using errcode='42501';end if;
 if p_content_sha256 is null or p_content_sha256 !~ '^[a-f0-9]{64}$' or row(r.receipt_hash,r.document_version,r.file_size,r.mime_type) is distinct from row(p_expected_receipt_hash,p_document_version,p_file_size,p_mime_type) then raise exception 'Verified bytes differ from staged document provenance' using errcode='23514';end if;
 select * into c from public.lab_report_byte_captures where receipt_id=r.id;
 if found then if row(c.actor_id,c.content_sha256,c.receipt_hash,c.document_version,c.file_size,c.mime_type) is distinct from row(p_actor_id,p_content_sha256,p_expected_receipt_hash,p_document_version,p_file_size,p_mime_type) then raise exception 'Original byte capture is immutable' using errcode='23505';end if;return c;end if;
 perform public.lab_report_capture_context(r.id,p_actor_id);
 fingerprint:=encode(digest(jsonb_build_array(r.id,r.receipt_hash,p_content_sha256,p_document_version,p_file_size,p_mime_type)::text,'sha256'),'hex');
 insert into public.lab_report_byte_captures(receipt_id,actor_id,receipt_hash,document_version,content_sha256,file_size,mime_type,capture_hash) values(r.id,p_actor_id,r.receipt_hash,p_document_version,p_content_sha256,p_file_size,p_mime_type,fingerprint) returning * into c;return c;
end $$

create function public.review_lab_order_source(p_id uuid,p_order_id uuid,p_pet_id uuid,p_expected_order_version integer,p_source_account_id uuid,p_source_patient_reference text,p_source_order_reference text,p_previous_review_id uuid,p_review_reason text,p_attest boolean) returns public.lab_order_source_reviews language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.lab_order_source_reviews;o public.patient_lab_orders;prior public.lab_order_source_reviews;
begin
 if p_id is null or p_attest is distinct from true or p_review_reason is null or length(trim(p_review_reason)) not between 1 and 2000 or exists(select 1 from unnest(array[p_source_patient_reference,p_source_order_reference]) v where v is null or length(trim(v)) not between 1 and 500) then raise exception 'Explicit source identity review required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,4102));
 select * into r from public.lab_order_source_reviews where id=p_id;
 if found then if row(r.actor_id,r.order_id,r.pet_id,r.order_version,r.source_account_id,r.source_patient_reference,r.source_order_reference,r.previous_review_id,r.review_reason) is distinct from row(actor,p_order_id,p_pet_id,p_expected_order_version,p_source_account_id,p_source_patient_reference,p_source_order_reference,p_previous_review_id,p_review_reason) then raise exception 'Source mapping UUID already used' using errcode='23505';end if;return r;end if;
 select * into o from public.patient_lab_orders where id=p_order_id and pet_id=p_pet_id for update;
 if not found then raise exception 'Lab order belongs to another patient or is unavailable' using errcode='42501';end if;
 if o.version is distinct from p_expected_order_version then raise exception 'Lab order changed' using errcode='40001';end if;
 perform 1 from public.lab_source_accounts where id=p_source_account_id and manual_import_enabled;
 if not found then raise exception 'Reviewed source account required' using errcode='42501';end if;
 select * into prior from public.lab_order_source_reviews where order_id=o.id order by revision desc limit 1;
 if prior.id is distinct from p_previous_review_id then raise exception 'Source identity mapping changed' using errcode='40001';end if;
 insert into public.lab_order_source_reviews(id,actor_id,order_id,pet_id,order_version,source_account_id,source_patient_reference,source_order_reference,previous_review_id,revision,review_reason) values(p_id,actor,o.id,o.pet_id,o.version,p_source_account_id,p_source_patient_reference,p_source_order_reference,prior.id,coalesce(prior.revision,0)+1,p_review_reason) returning * into r;return r;
end $$

create function public.link_lab_report_version(p_id uuid,p_receipt_id uuid,p_expected_receipt_hash text,p_expected_capture_hash text,p_order_id uuid,p_pet_id uuid,p_expected_order_version integer,p_source_review_id uuid,p_previous_report_id uuid,p_kind text,p_review_reason text,p_attest boolean) returns public.lab_report_versions language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.lab_report_versions;o public.patient_lab_orders;s public.lab_order_source_reviews;receipt public.lab_report_receipts;capture public.lab_report_byte_captures;prior public.lab_report_versions;
begin
 if p_id is null or p_attest is distinct from true or p_kind is null or p_kind not in ('original','corrected') or p_review_reason is null or length(trim(p_review_reason)) not between 1 and 2000 then raise exception 'Explicit report provenance review required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,4103));
 select * into r from public.lab_report_versions where id=p_id;
 if found then if row(r.actor_id,r.receipt_id,r.receipt_hash,r.capture_hash,r.order_id,r.pet_id,r.order_version,r.source_review_id,r.previous_report_id,r.kind,r.review_reason) is distinct from row(actor,p_receipt_id,p_expected_receipt_hash,p_expected_capture_hash,p_order_id,p_pet_id,p_expected_order_version,p_source_review_id,p_previous_report_id,p_kind,p_review_reason) then raise exception 'Report review UUID already used' using errcode='23505';end if;return r;end if;
 select * into o from public.patient_lab_orders where id=p_order_id and pet_id=p_pet_id for update;
 if not found then raise exception 'Lab order belongs to another patient or is unavailable' using errcode='42501';end if;
 if o.version is distinct from p_expected_order_version then raise exception 'Lab order changed' using errcode='40001';end if;
 select * into s from public.lab_order_source_reviews where order_id=o.id order by revision desc limit 1;
 if s.id is null or s.id is distinct from p_source_review_id then raise exception 'Review current source identity mapping' using errcode='40001';end if;
 select * into receipt from public.lab_report_receipts where id=p_receipt_id;
 if receipt.id is null or receipt.receipt_hash is distinct from p_expected_receipt_hash or row(receipt.pet_id,receipt.source_account_id,receipt.source_patient_reference,receipt.source_order_reference) is distinct from row(o.pet_id,s.source_account_id,s.source_patient_reference,s.source_order_reference) then raise exception 'Report patient or source identity does not match reviewed order' using errcode='42501';end if;
 select * into capture from public.lab_report_byte_captures where receipt_id=receipt.id;
 if capture.receipt_id is null or capture.capture_hash is distinct from p_expected_capture_hash then raise exception 'Verified original byte capture and explicit review required' using errcode='42501';end if;
 perform 1 from public.patient_documents where id=receipt.document_id and pet_id=o.pet_id and status='ready' and version=receipt.document_version for share;
 if not found then raise exception 'Report document is no longer ready at reviewed version' using errcode='40001';end if;
 select * into prior from public.lab_report_versions where order_id=o.id order by version desc limit 1;
 if prior.id is distinct from p_previous_report_id then raise exception 'Report history changed; review the current version' using errcode='40001';end if;
 if (prior.id is null and p_kind<>'original') or (prior.id is not null and (p_kind<>'corrected' or prior.document_id=receipt.document_id or (select source_account_id from public.lab_report_receipts where id=prior.receipt_id)<>receipt.source_account_id)) then raise exception 'Corrected report requires a new document within the same source account' using errcode='23514';end if;
 insert into public.lab_report_versions(id,actor_id,order_id,pet_id,order_version,source_review_id,receipt_id,receipt_hash,capture_hash,document_id,document_version,previous_report_id,version,kind,review_reason) values(p_id,actor,o.id,o.pet_id,o.version,s.id,receipt.id,receipt.receipt_hash,capture.capture_hash,receipt.document_id,receipt.document_version,prior.id,coalesce(prior.version,0)+1,p_kind,p_review_reason) returning * into r;return r;
end $$

create function public.acknowledge_lab_report(p_id uuid,p_report_id uuid,p_pet_id uuid,p_expected_capture_hash text,p_expected_document_version integer,p_attest boolean) returns public.lab_report_acknowledgments language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();a public.lab_report_acknowledgments;r public.lab_report_versions;
begin
 if not public.has_role(actor,'DVM') then raise exception 'Veterinarian acknowledgment required' using errcode='42501';end if;
 if p_id is null or p_attest is distinct from true then raise exception 'Explicit report acknowledgment required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,4104));
 select * into a from public.lab_report_acknowledgments where id=p_id;
 if found then
 if row(a.actor_id,a.report_id,a.capture_hash,a.document_version) is distinct from row(actor,p_report_id,p_expected_capture_hash,p_expected_document_version) or not exists(select 1 from public.lab_report_versions where id=a.report_id and pet_id=p_pet_id) then raise exception 'Acknowledgment UUID already used' using errcode='23505';end if;return a;end if;
 select * into r from public.lab_report_versions where id=p_report_id and pet_id=p_pet_id;
 if not found or r.capture_hash is distinct from p_expected_capture_hash or r.document_version is distinct from p_expected_document_version then raise exception 'Exact report acknowledgment required' using errcode='42501';end if;
 perform 1 from public.patient_documents where id=r.document_id and pet_id=r.pet_id and status='ready' and version=r.document_version for share;
 if not found then raise exception 'Reviewed report document unavailable' using errcode='40001';end if;
 insert into public.lab_report_acknowledgments(id,actor_id,report_id,capture_hash,document_version) values(p_id,actor,r.id,r.capture_hash,r.document_version) returning * into a;return a;
end $$

create function public.read_lab_result_history(p_pet_id uuid,p_order_id uuid default null) returns jsonb language plpgsql stable security definer set search_path=public as $$
begin perform public.clinical_require_staff();
 if not exists(select 1 from public.pets where id=p_pet_id) or (p_order_id is not null and not exists(select 1 from public.patient_lab_orders where id=p_order_id and pet_id=p_pet_id)) then raise exception 'Patient or lab order unavailable' using errcode='42501';end if;
 return jsonb_build_object('pet_id',p_pet_id,'order_id',p_order_id,
 'sources',coalesce((select jsonb_agg(to_jsonb(s) order by created_at,id) from public.lab_source_accounts s),'[]'::jsonb),
 'staged_receipts',coalesce((select jsonb_agg(to_jsonb(r)||jsonb_build_object('capture',(select to_jsonb(c) from public.lab_report_byte_captures c where receipt_id=r.id)) order by created_at,id) from public.lab_report_receipts r where pet_id=p_pet_id and not exists(select 1 from public.lab_report_versions v where v.receipt_id=r.id)),'[]'::jsonb),
 'source_reviews',coalesce((select jsonb_agg(to_jsonb(s) order by order_id,revision) from public.lab_order_source_reviews s where pet_id=p_pet_id and (p_order_id is null or order_id=p_order_id)),'[]'::jsonb),
 'reports',coalesce((select jsonb_agg(to_jsonb(v)||jsonb_build_object('capture',(select to_jsonb(c) from public.lab_report_byte_captures c where receipt_id=v.receipt_id),'document_status',(select status from public.patient_documents where id=v.document_id),'acknowledgments',coalesce((select jsonb_agg(to_jsonb(a) order by created_at,id) from public.lab_report_acknowledgments a where report_id=v.id),'[]'::jsonb)) order by order_id,version) from public.lab_report_versions v where pet_id=p_pet_id and (p_order_id is null or order_id=p_order_id)),'[]'::jsonb));
end $$

create function public.recover_lab_report_receipt(p_receipt_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.lab_report_receipts;
begin select * into r from public.lab_report_receipts where id=p_receipt_id and actor_id=actor;
 if not found then return null;end if;
 return jsonb_build_object('receipt',to_jsonb(r),'capture',(select to_jsonb(c) from public.lab_report_byte_captures c where receipt_id=r.id),'report',(select to_jsonb(v) from public.lab_report_versions v where receipt_id=r.id));
end $$

