create function public.release_preview_v7_internal(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare result jsonb;s jsonb;ids jsonb;refs jsonb;vaccinations jsonb:='[]';older jsonb;k text;older_count integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_pet_id::text,4700));
 if p_selection is null or jsonb_typeof(p_selection)<>'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f not in('encounter_ids','certificate_ids','lab_order_ids','document_ids','dental_ids','qol_ids','anesthesia_ids','lesion_ids','problem_ids','weight_ids','treatment_ids','patient_summary_ids','lab_report_ids','external_record_ids','imported_history_ids','imported_vaccination_ids')) then raise exception 'Choose explicit release sources' using errcode='23514';end if;
 ids:=coalesce(p_selection->'imported_vaccination_ids','[]');
 if jsonb_typeof(ids)<>'array' or jsonb_array_length(ids)>20 or exists(select 1 from jsonb_array_elements(ids) v where jsonb_typeof(v)<>'string') or (select count(*)<>count(distinct v::uuid) from jsonb_array_elements_text(ids) v) then raise exception 'Select at most20 distinct reviewed vaccination versions' using errcode='23514';end if;
 older:=p_selection-'imported_vaccination_ids';
 for k in select jsonb_object_keys(older) loop
  if jsonb_typeof(older->k)<>'array' then raise exception 'Source selections must be arrays' using errcode='23514';end if;
  older_count:=older_count+jsonb_array_length(older->k);
 end loop;
 if jsonb_array_length(ids)>0 then
  select jsonb_agg(jsonb_build_object('id',v.id,'version_hash',v.version_hash) order by v.id) into refs from public.ezyvet_imported_vaccinations v where v.id in(select x::uuid from jsonb_array_elements_text(ids) x);
  if coalesce(jsonb_array_length(refs),0)<>jsonb_array_length(ids) then raise exception 'Selected vaccination version unavailable' using errcode='23514';end if;
  vaccinations:=public.ezyvet_validate_reviewed_vaccinations(p_pet_id,refs);
 end if;
 if older_count=0 and jsonb_array_length(ids)>0 then
  -- Original core validates recipient/patient with no fabricated implicit source.
  result:=public.preview_record_release_v1(p_pet_id,p_client_id,p_channel,p_recipient,'{}');s:=result->'snapshot';
  foreach k in array array['dental_charts','qol_records','anesthesia_records','lesions','problems','weights','treatments','patient_summaries','lab_reports','external_records','imported_histories','problem_source_extractions'] loop s:=s||jsonb_build_object(k,'[]'::jsonb);end loop;
 else result:=public.release_preview_v6_internal(p_pet_id,p_client_id,p_channel,p_recipient,older);s:=result->'snapshot';end if;
 s:=s||jsonb_build_object('schema_version',7,'selection',coalesce(s->'selection','{}')||jsonb_build_object('imported_vaccination_ids',ids),'imported_vaccinations',vaccinations);
 if octet_length(s::text)>1048576 then raise exception 'Release exceeds maximum reviewed snapshot size' using errcode='23514';end if;
 return jsonb_build_object('snapshot',s,'source_hash',encode(sha256(convert_to(s::text,'UTF8')),'hex'));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';end $$

do $$declare d text;needle text;begin
 select pg_get_functiondef('public.confirm_record_release(uuid,uuid,uuid,text,text,jsonb,jsonb,text,boolean)'::regprocedure) into d;
 needle:='if (p_reviewed_snapshot->>''schema_version'')::integer=6 then';if strpos(d,needle)=0 then raise exception 'Expected schema6 confirmation dispatch missing';end if;
 d:=replace(d,needle,'if (p_reviewed_snapshot->>''schema_version'')::integer=7 then preview:=public.release_preview_v7_internal(p_pet_id,p_client_id,p_channel,p_recipient,p_selection); elsif (p_reviewed_snapshot->>''schema_version'')::integer=6 then');
 d:=replace(d,'p_reviewed_snapshot->>''schema_version'' not in (''5'',''6'')','p_reviewed_snapshot->>''schema_version'' not in (''5'',''6'',''7'')');
 d:=replace(d,'p_reviewed_snapshot->>''schema_version''<>''6''','p_reviewed_snapshot->>''schema_version'' not in (''6'',''7'')');
 needle:='''external_record_ids'',''imported_history_ids''] loop';if strpos(d,needle)=0 then raise exception 'Expected source registry loop missing';end if;
 d:=replace(d,needle,'''external_record_ids'',''imported_history_ids'',''imported_vaccination_ids''] loop');
 d:=replace(d,'when ''imported_history_ids'' then ''imported_history'' else','when ''imported_history_ids'' then ''imported_history'' when ''imported_vaccination_ids'' then ''imported_vaccination'' else');execute d;
 select pg_get_functiondef('public.release_read_internal(uuid)'::regprocedure) into d;
 needle:='if r.snapshot->>''schema_version''=''6'' then';if strpos(d,needle)=0 then raise exception 'Expected schema6 recovery dispatch missing';end if;
 d:=replace(d,needle,'if r.snapshot->>''schema_version''=''7'' then current_preview:=public.release_preview_v7_internal(r.pet_id,r.client_id,r.channel,r.recipient,r.selection); elsif r.snapshot->>''schema_version''=''6'' then');
 d:=replace(d,'r.snapshot->>''schema_version'' not in (''5'',''6'')','r.snapshot->>''schema_version'' not in (''5'',''6'',''7'')');
 d:=replace(d,'r.snapshot->>''schema_version''<>''6''','r.snapshot->>''schema_version'' not in (''6'',''7'')');execute d;
 select pg_get_functiondef(oid) into d from pg_proc where pronamespace='public'::regnamespace and proname='verify_release_source_original_v5';
 needle:='p_snapshot->>''schema_version'' is distinct from ''6''';if d is null or strpos(d,needle)=0 then raise exception 'Expected schema6 byte verification guard missing';end if;
 execute replace(d,needle,needle||' and p_snapshot->>''schema_version'' is distinct from ''7''');
end $$

do $$declare name text;d text;needle text;replacement text;begin
 foreach name in array array['invalidate_release_source_provenance','release_weight_provenance_changed','release_weight_source_head_changed'] loop
  select pg_get_functiondef(oid) into d from pg_proc where pronamespace='public'::regnamespace and proname=name;
  if name='invalidate_release_source_provenance' then needle:='in (''5'',''6'')';replacement:='in (''5'',''6'',''7'')';else needle:='in (''4'',''5'',''6'')';replacement:='in (''4'',''5'',''6'',''7'')';end if;
  if d is null or strpos(d,needle)=0 then raise exception 'Expected inherited provenance event guard missing: %',name;end if;execute replace(d,needle,replacement);
 end loop;
end $$

create function public.invalidate_imported_vaccination_release() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if TG_TABLE_NAME='ezyvet_identity_heads' then
  if NEW.resource not in('vaccination','consult') or row(NEW.snapshot_id,NEW.version) is not distinct from row(OLD.snapshot_id,OLD.version) then return NEW;end if;
  insert into public.record_release_events(id,release_id,kind,reason,created_by)
  select gen_random_uuid(),r.id,'source_changed','Reviewed vaccination source changed; review a fresh package',auth.uid() from public.record_releases r where exists(select 1 from public.record_release_sources rs join public.ezyvet_imported_vaccinations v on v.id=rs.source_id where rs.release_id=r.id and rs.source_kind='imported_vaccination' and v.source_origin=NEW.source_origin and v.source_site_uid=NEW.source_site_uid and ((NEW.resource='vaccination' and v.vaccination_external_id=NEW.external_id) or (NEW.resource='consult' and v.consult->>'external_id'=NEW.external_id)));
 else
  insert into public.record_release_events(id,release_id,kind,reason,created_by)
  select gen_random_uuid(),r.id,'source_changed','Reviewed vaccination superseded; review a fresh package',auth.uid() from public.record_releases r where exists(select 1 from public.record_release_sources rs join public.ezyvet_imported_vaccinations v on v.id=rs.source_id where rs.release_id=r.id and rs.source_kind='imported_vaccination' and v.source_origin=NEW.source_origin and v.source_site_uid=NEW.source_site_uid and v.animal_link_id=NEW.animal_link_id and v.vaccination_external_id=NEW.vaccination_external_id);
 end if;
 -- Append-only events avoid acquiring a release row behind a source-head lock.
 return NEW;
end $$

create function public.list_record_release_sources_v7(p_pet_id uuid,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;rows jsonb;more boolean;begin
 perform public.clinical_require_staff();result:=public.list_record_release_sources_v6(p_pet_id,p_offset);
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'version',version,'recorded_at',approved_at,'label','Outside vaccination '||vaccination_external_id||' · reviewed version '||version,'source_label','ezyVet · '||source_site_uid) order by approved_at desc,id desc),'[]') into rows from(select * from public.ezyvet_imported_vaccinations v where pet_id=p_pet_id and public.ezyvet_vaccination_current(v.id) @> '{"is_current":true,"is_latest":true,"identity_valid":true}'::jsonb order by approved_at desc,id desc offset p_offset limit 101) selected;
 more:=jsonb_array_length(rows)>100;if more then rows:=rows-100;end if;
 return result||jsonb_build_object('imported_vaccination_ids',rows,'has_more',result->'has_more'||jsonb_build_object('imported_vaccination_ids',more),'policy_v7_accepted',exists(select 1 from public.record_release_policy where id and enabled and accepted_at<=now() and accepted_schema_version>=7));
end $$

create function public.select_all_record_release_sources_v7(p_pet_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;ids jsonb;begin
 perform public.clinical_require_staff();result:=public.select_all_record_release_sources_v6(p_pet_id);
 select coalesce(jsonb_agg(id order by id),'[]') into ids from public.ezyvet_imported_vaccinations v where pet_id=p_pet_id and public.ezyvet_vaccination_current(v.id) @> '{"is_current":true,"is_latest":true,"identity_valid":true}'::jsonb;
 if jsonb_array_length(ids)>20 then raise exception 'More than20 reviewed vaccinations; split into explicit packages' using errcode='23514';end if;
 return result||jsonb_build_object('selection',result->'selection'||jsonb_build_object('imported_vaccination_ids',ids));
end $$

