 for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in('release_preview_v7_internal','preview_record_release_v7','invalidate_imported_vaccination_release','list_record_release_sources_v7','select_all_record_release_sources_v7') loop
