  or coalesce(p_payload->>'item_run_id','') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
  or jsonb_typeof(p_payload->'patient_version') is distinct from 'number'
