)

create table public.native_estimate_draft_revisions (
 estimate_id uuid not null references public.native_estimate_drafts(id),version integer not null check(version>0),operation_id uuid not null unique references public.native_estimate_draft_operations(id) deferrable initially deferred,document jsonb not null,catalog jsonb not null,previous_hash text,record_hash text not null,primary key(estimate_id,version)
)

create table public.native_estimate_draft_closures (
 id uuid primary key,actor_id uuid not null references public.profiles(id),request jsonb not null,request_hash text not null,closed_at timestamptz not null,record_hash text not null
)

do $$declare tab text;begin
 foreach tab in array array['native_estimate_drafts','native_estimate_draft_operations','native_estimate_draft_revisions','native_estimate_draft_closures'] loop
 execute format('alter table public.%I enable row level security',tab);execute format('revoke all on public.%I from public,anon,authenticated,service_role',tab);
 execute format('create trigger native_estimate_immutable before update or delete on public.%I for each row execute function public.native_correction_immutable()',tab);
 execute format('create trigger native_estimate_no_truncate before truncate on public.%I for each statement execute function public.native_correction_immutable()',tab);
 execute format('create trigger native_estimate_audit after insert on public.%I for each row execute function public.native_rx_audit()',tab);
 end loop;
end $$

create function public.native_estimate_positive_int(v jsonb) returns integer language plpgsql immutable security definer set search_path=public as $$begin
 if jsonb_typeof(v) is distinct from 'number' or v::text !~ '^[1-9][0-9]{0,9}$' or (v::text)::numeric>2147483647 then raise exception 'Positive integer version required' using errcode='23514';end if;return(v::text)::integer;
end $$

-- p_catalog null validates syntax/totals only. Frozen evidence validates historical prices.
create function public.native_estimate_fields_total(p_fields jsonb,p_catalog jsonb default null) returns text language plpgsql immutable security definer set search_path=public as $$
declare line jsonb;entry jsonb;ids text[]:='{}';products text[]:='{}';quantity numeric;amount numeric;total numeric:=0;price numeric;reason text;begin
 perform public.native_rx_keys(p_fields,array['title','notes','terms','accept_by','lines']);perform public.native_rx_text(p_fields->'title',200);perform public.native_rx_text(p_fields->'terms',8000);
 if p_fields->'notes' is distinct from '""'::jsonb then perform public.native_rx_text(p_fields->'notes',4000);end if;perform public.native_rx_day(p_fields->'accept_by');
 if jsonb_typeof(p_fields->'lines') is distinct from 'array' or jsonb_array_length(p_fields->'lines') not between 1 and 100 then raise exception 'One to 100 estimate lines required' using errcode='23514';end if;
 if p_catalog is not null and jsonb_typeof(p_catalog) is distinct from 'object' then raise exception 'Exact historical catalog evidence required' using errcode='23514';end if;
 for line in select value from jsonb_array_elements(p_fields->'lines') loop
  perform public.native_rx_keys(line,array['id','product_id','product_version','description','kind','unit','quantity','pricing','pricing_reason']);perform public.native_correction_uuid(line->'id',false);perform public.native_correction_uuid(line->'product_id',false);perform public.native_estimate_positive_int(line->'product_version');
  if line->>'id'=any(ids) then raise exception 'Duplicate estimate line identity' using errcode='23514';end if;ids:=array_append(ids,line->>'id');
  if not(line->>'product_id'=any(products)) then products:=array_append(products,line->>'product_id');end if;
  perform public.native_rx_text(line->'description',300);perform public.native_rx_text(line->'unit',50);
  if jsonb_typeof(line->'kind') is distinct from 'string' or line->>'kind' not in('service','medication','vaccine') or jsonb_typeof(line->'quantity') is distinct from 'string' or line->>'quantity' !~ '^(0|[1-9][0-9]{0,10})(\.[0-9]{0,2}[1-9])?$' then raise exception 'Invalid estimate kind or canonical quantity' using errcode='23514';end if;
  quantity:=(line->>'quantity')::numeric;if quantity<=0 then raise exception 'Positive estimate quantity required' using errcode='23514';end if;
  reason:=null;if line->'pricing_reason' is distinct from 'null'::jsonb then reason:=public.native_rx_text(line->'pricing_reason',2000);end if;
  if line#>>'{pricing,kind}'='unit' then
   perform public.native_rx_keys(line->'pricing',array['kind','unit_price_cents']);price:=public.native_finance_money(line#>'{pricing,unit_price_cents}');amount:=round(quantity*price);
  elsif line#>>'{pricing,kind}'='allocated' then
   perform public.native_rx_keys(line->'pricing',array['kind','amount_cents']);amount:=public.native_finance_money(line#>'{pricing,amount_cents}');if reason is null then raise exception 'Allocated pricing requires reason' using errcode='23514';end if;
  else raise exception 'Exact estimate pricing required' using errcode='23514';end if;
  if amount=0 and reason is null then raise exception 'Zero pricing requires reason' using errcode='23514';end if;
  perform public.native_finance_cents(amount);total:=total+amount;perform public.native_finance_cents(total);
  if p_catalog is not null then
   entry:=p_catalog->(line->>'product_id');perform public.native_rx_keys(entry,array['id','version','kind','unit','unit_price_cents','active']);perform public.native_correction_uuid(entry->'id',false);perform public.native_estimate_positive_int(entry->'version');perform public.native_finance_money(entry->'unit_price_cents');
   if entry->'id' is distinct from line->'product_id' or entry->'version' is distinct from line->'product_version' or entry->'kind' is distinct from line->'kind' or entry->'unit' is distinct from line->'unit' or entry->'active' is distinct from 'true'::jsonb then raise exception 'Estimate catalog evidence mismatch' using errcode='23514';end if;
   if line#>>'{pricing,kind}'='unit' and line#>'{pricing,unit_price_cents}' is distinct from entry->'unit_price_cents' and reason is null then raise exception 'Price override requires reason' using errcode='23514';end if;
  end if;
 end loop;
 if p_catalog is not null and (select count(*) from jsonb_object_keys(p_catalog))<>cardinality(products) then raise exception 'Extraneous estimate catalog evidence' using errcode='23514';end if;
 return public.native_finance_cents(total);
end $$

create function public.native_estimate_validate_request(p_request jsonb) returns void language plpgsql immutable security definer set search_path=public as $$declare key_name text;begin
 perform public.native_rx_keys(p_request,array['estimate_id','client_id','pet_id','expected_version','fields']);foreach key_name in array array['estimate_id','client_id','pet_id'] loop perform public.native_correction_uuid(p_request->key_name,false);end loop;
 if p_request->'expected_version' is distinct from 'null'::jsonb then perform public.native_estimate_positive_int(p_request->'expected_version');end if;perform public.native_estimate_fields_total(p_request->'fields');
end $$

-- Verify the entire requested prefix without consulting today's catalog or patient household.
create function public.native_estimate_verified_revision(p_id uuid,p_version integer) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare root public.native_estimate_drafts;rev public.native_estimate_draft_revisions;op public.native_estimate_draft_operations;prior_hash text;previous_stamp timestamptz;next_version bigint:=1;doc jsonb;begin
 select * into root from public.native_estimate_drafts d where d.id=p_id;if not found then return null;end if;
 if p_version is null or p_version<1 then raise exception 'Exact estimate revision required' using errcode='23514';end if;
 for rev in select r.* from public.native_estimate_draft_revisions r where r.estimate_id=p_id and r.version<=p_version order by r.version loop
  select * into op from public.native_estimate_draft_operations o where o.id=rev.operation_id;
  if op.id is null or op.estimate_id<>p_id or op.version<>rev.version or rev.version<>next_version or rev.previous_hash is distinct from prior_hash or exists(select 1 from public.native_estimate_draft_closures c where c.id=op.id) then raise exception 'Estimate revision chain or operation invalid' using errcode='23514';end if;
  perform public.native_estimate_validate_request(op.request);doc:=rev.document;perform public.native_rx_keys(doc,array['id','client_id','pet_id','version','fields','total_cents','created_by','created_at','updated_by','updated_at']);
  if doc->'id' is distinct from to_jsonb(root.id) or doc->'client_id' is distinct from to_jsonb(root.client_id) or doc->'pet_id' is distinct from to_jsonb(root.pet_id) or doc->'version' is distinct from to_jsonb(rev.version) or doc->'created_by' is distinct from to_jsonb(root.created_by) or doc->'created_at' is distinct from to_jsonb(root.created_at) or doc->'updated_by' is distinct from to_jsonb(op.actor_id) or doc->'updated_at' is distinct from to_jsonb(op.created_at)
   or op.request->'estimate_id' is distinct from doc->'id' or op.request->'client_id' is distinct from doc->'client_id' or op.request->'pet_id' is distinct from doc->'pet_id' or op.request->'fields' is distinct from doc->'fields' or op.request->'expected_version' is distinct from(case when rev.version=1 then 'null'::jsonb else to_jsonb(rev.version-1) end)
   or doc->'total_cents' is distinct from to_jsonb(public.native_estimate_fields_total(doc->'fields',rev.catalog)) or not isfinite(root.created_at) or not isfinite(op.created_at) or op.created_at<root.created_at or op.created_at<previous_stamp or (rev.version=1 and (op.actor_id<>root.created_by or op.created_at<>root.created_at)) then raise exception 'Estimate revision document mismatch' using errcode='23514';end if;
  if op.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',op.actor_id,'operation','save_estimate_draft','request',op.request)) or rev.record_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('document',doc,'catalog',rev.catalog,'previous_hash',rev.previous_hash,'operation_id',rev.operation_id,'request_hash',op.request_hash)) then raise exception 'Estimate revision hash mismatch' using errcode='23514';end if;
  prior_hash:=rev.record_hash;previous_stamp:=op.created_at;next_version:=next_version+1;
 end loop;
 if next_version-1<>p_version then raise exception 'Estimate revision missing' using errcode='23514';end if;return doc;
end $$

create function public.native_estimate_verified_operation(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare op public.native_estimate_draft_operations;doc jsonb;begin
 select * into op from public.native_estimate_draft_operations o where o.id=p_id;if not found then return null;end if;doc:=public.native_estimate_verified_revision(op.estimate_id,op.version);
 if doc is null or not exists(select 1 from public.native_estimate_draft_revisions r where r.estimate_id=op.estimate_id and r.version=op.version and r.operation_id=op.id) then raise exception 'Estimate operation revision missing' using errcode='23514';end if;
 return jsonb_build_object('version',1,'id',op.id,'actor_id',op.actor_id,'request',op.request,'request_hash',op.request_hash,'result',doc,'created_at',op.created_at);
end $$

create function public.native_estimate_verified_closure(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare c public.native_estimate_draft_closures;doc jsonb;begin
 select * into c from public.native_estimate_draft_closures closed where closed.id=p_id;if not found then return null;end if;perform public.native_estimate_validate_request(c.request);
 if exists(select 1 from public.native_estimate_draft_operations o where o.id=p_id) or exists(select 1 from public.native_estimate_draft_revisions r where r.operation_id=p_id) or not isfinite(c.closed_at) or c.request_hash is distinct from public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',c.actor_id,'operation','save_estimate_draft','request',c.request)) then raise exception 'Estimate closure identity invalid' using errcode='23514';end if;
 doc:=jsonb_build_object('version',1,'id',c.id,'actor_id',c.actor_id,'request',c.request,'request_hash',c.request_hash,'closed_at',c.closed_at);if c.record_hash is distinct from public.native_fulfillment_hash(doc) then raise exception 'Estimate closure hash invalid' using errcode='23514';end if;return doc||jsonb_build_object('record_hash',c.record_hash);
end $$

create function public.native_estimate_integrity() returns trigger language plpgsql security definer set search_path=public as $$declare v integer;begin
 if TG_TABLE_NAME='native_estimate_draft_closures' then perform public.native_estimate_verified_closure(NEW.id);
 elsif TG_TABLE_NAME='native_estimate_draft_operations' then perform public.native_estimate_verified_operation(NEW.id);
 elsif TG_TABLE_NAME='native_estimate_draft_revisions' then perform public.native_estimate_verified_revision(NEW.estimate_id,NEW.version);
 else select max(r.version) into v from public.native_estimate_draft_revisions r where r.estimate_id=NEW.id;perform public.native_estimate_verified_revision(NEW.id,v);end if;return NEW;
end $$

create function public.save_native_estimate_draft(p_id uuid,p_request jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();root public.native_estimate_drafts;product public.catalog_products;doc jsonb;receipt jsonb;catalog jsonb:='{}';line jsonb;root_id uuid;target_client_id uuid;target_pet_id uuid;version_now integer;version_next integer;stamp timestamptz;total text;prior_hash text;request_digest text;begin
 if p_id is null then raise exception 'Stable estimate operation id required' using errcode='23514';end if;perform public.native_estimate_validate_request(p_request);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));perform public.clinical_require_staff();receipt:=public.native_estimate_verified_operation(p_id);
 if receipt is not null then if receipt->>'actor_id'<>actor::text then raise exception 'Estimate receipt unavailable' using errcode='42501';end if;if receipt->'request' is distinct from p_request then raise exception 'Estimate operation identifier already used' using errcode='23514';end if;return receipt;end if;
 doc:=public.native_estimate_verified_closure(p_id);if doc is not null then if doc->>'actor_id'<>actor::text then raise exception 'Estimate closure unavailable' using errcode='42501';end if;raise exception 'Estimate operation permanently closed' using errcode='23514';end if;
 root_id:=(p_request->>'estimate_id')::uuid;target_client_id:=(p_request->>'client_id')::uuid;target_pet_id:=(p_request->>'pet_id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('native-estimate:'||root_id::text,0));perform public.clinical_require_staff();
 select * into root from public.native_estimate_drafts d where d.id=root_id;select max(r.version) into version_now from public.native_estimate_draft_revisions r where r.estimate_id=root_id;
 if root.id is not null then
  perform public.native_estimate_verified_revision(root_id,version_now);if root.client_id<>target_client_id or root.pet_id<>target_pet_id then raise exception 'Estimate household and patient cannot change' using errcode='23514';end if;
 end if;
 if p_request->'expected_version' is distinct from coalesce(to_jsonb(version_now),'null'::jsonb) then raise exception 'Estimate draft changed; compare current version' using errcode='40001';end if;
 perform 1 from public.clients c where c.id=target_client_id for share;if not found then raise exception 'Estimate household not found' using errcode='23514';end if;
 perform 1 from public.pets p where p.id=target_pet_id and p.client_id=target_client_id for share;if not found then raise exception 'Estimate patient must belong to household' using errcode='23514';end if;
 for product in select p.* from public.catalog_products p where p.id in(select(value->>'product_id')::uuid from jsonb_array_elements(p_request#>'{fields,lines}')) order by p.id for share loop
  if not product.active then raise exception 'Estimate catalog changed' using errcode='40001';end if;
  catalog:=catalog||jsonb_build_object(product.id::text,jsonb_build_object('id',product.id,'version',product.version,'kind',product.kind,'unit',product.unit,'unit_price_cents',product.unit_price_cents::text,'active',product.active));
 end loop;
 perform public.clinical_require_staff();
 for line in select value from jsonb_array_elements(p_request#>'{fields,lines}') loop
  if catalog->(line->>'product_id') is null or catalog#>array[line->>'product_id','version'] is distinct from line->'product_version' then raise exception 'Estimate catalog changed; review current product' using errcode='40001';end if;
 end loop;
 total:=public.native_estimate_fields_total(p_request->'fields',catalog);
 if version_now=2147483647 then raise exception 'Estimate revision limit reached' using errcode='23514';end if;
 stamp:=greatest(clock_timestamp(),(select o.created_at from public.native_estimate_draft_operations o where o.estimate_id=root_id and o.version=version_now));version_next:=coalesce(version_now,0)+1;
 if root.id is null then insert into public.native_estimate_drafts values(root_id,target_client_id,target_pet_id,actor,stamp) returning * into root;end if;
 select r.record_hash into prior_hash from public.native_estimate_draft_revisions r where r.estimate_id=root_id and r.version=version_now;
 doc:=jsonb_build_object('id',root_id,'client_id',target_client_id,'pet_id',target_pet_id,'version',version_next,'fields',p_request->'fields','total_cents',total,'created_by',root.created_by,'created_at',root.created_at,'updated_by',actor,'updated_at',stamp);
 request_digest:=public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',actor,'operation','save_estimate_draft','request',p_request));
 insert into public.native_estimate_draft_operations values(p_id,actor,p_request,request_digest,root_id,version_next,stamp);
 insert into public.native_estimate_draft_revisions values(root_id,version_next,p_id,doc,catalog,prior_hash,public.native_fulfillment_hash(jsonb_build_object('document',doc,'catalog',catalog,'previous_hash',prior_hash,'operation_id',p_id,'request_hash',request_digest)));
 perform public.clinical_require_staff();return public.native_estimate_verified_operation(p_id);
end $$

create function public.recover_native_estimate_draft(p_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare actor uuid:=public.clinical_require_staff();receipt jsonb;begin
 receipt:=public.native_estimate_verified_operation(p_id);if receipt is not null and receipt->>'actor_id'<>actor::text then raise exception 'Estimate receipt unavailable' using errcode='42501';end if;return receipt;
end $$

create function public.close_native_estimate_draft(p_id uuid,p_request jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare actor uuid:=public.clinical_require_staff();doc jsonb;receipt jsonb;stamp timestamptz;digest text;begin
 if p_id is null then raise exception 'Stable estimate operation id required' using errcode='23514';end if;perform public.native_estimate_validate_request(p_request);perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));perform public.clinical_require_staff();receipt:=public.native_estimate_verified_operation(p_id);
 if receipt is not null then if receipt->>'actor_id'<>actor::text then raise exception 'Estimate receipt unavailable' using errcode='42501';end if;if receipt->'request' is distinct from p_request then raise exception 'Estimate operation identifier already used' using errcode='23514';end if;return jsonb_build_object('version',1,'status','recorded','receipt',receipt);end if;
 doc:=public.native_estimate_verified_closure(p_id);
 if doc is not null then if doc->>'actor_id'<>actor::text then raise exception 'Estimate closure unavailable' using errcode='42501';end if;if doc->'request' is distinct from p_request then raise exception 'Estimate operation identifier already closed' using errcode='23514';end if;
 else stamp:=clock_timestamp();digest:=public.native_fulfillment_hash(jsonb_build_object('version',1,'actor_id',actor,'operation','save_estimate_draft','request',p_request));doc:=jsonb_build_object('version',1,'id',p_id,'actor_id',actor,'request',p_request,'request_hash',digest,'closed_at',stamp);
 insert into public.native_estimate_draft_closures values(p_id,actor,p_request,digest,stamp,public.native_fulfillment_hash(doc));doc:=public.native_estimate_verified_closure(p_id);end if;
 perform public.clinical_require_staff();return jsonb_build_object('version',1,'status','closed_unrecorded','closure',doc);
end $$

create function public.read_native_estimate_draft(p_id uuid,p_client_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$declare actor uuid:=public.clinical_require_staff();root public.native_estimate_drafts;v integer;doc jsonb;begin
 if p_id is null or p_client_id is null then raise exception 'Exact household estimate identity required' using errcode='23514';end if;select * into root from public.native_estimate_drafts d where d.id=p_id;
 if root.id is not null then if root.client_id<>p_client_id then raise exception 'Estimate household mismatch' using errcode='23514';end if;select max(r.version) into v from public.native_estimate_draft_revisions r where r.estimate_id=p_id;doc:=public.native_estimate_verified_revision(p_id,v);end if;
 return jsonb_build_object('version',1,'actor_id',actor,'draft',doc);
end $$

create function public.list_native_estimate_drafts(p_client_id uuid,p_before_at timestamptz,p_before_id uuid,p_limit integer) returns jsonb language plpgsql stable security definer set search_path=public as $$declare actor uuid:=public.clinical_require_staff();root public.native_estimate_drafts;drafts jsonb:='[]';has_more boolean:=false;cursor_value jsonb;v integer;n integer:=0;begin
 if p_client_id is null or p_limit is null or p_limit not between 1 and 100 or(p_before_at is null)<>(p_before_id is null) or(p_before_at is not null and not isfinite(p_before_at)) then raise exception 'Valid estimate page required' using errcode='23514';end if;
 for root in select d.* from public.native_estimate_drafts d where d.client_id=p_client_id and(p_before_at is null or(d.created_at,d.id)<(p_before_at,p_before_id)) order by d.created_at desc,d.id desc limit p_limit+1 loop
  n:=n+1;if n>p_limit then has_more:=true;exit;end if;select max(r.version) into v from public.native_estimate_draft_revisions r where r.estimate_id=root.id;drafts:=drafts||jsonb_build_array(public.native_estimate_verified_revision(root.id,v));cursor_value:=jsonb_build_object('before_at',root.created_at,'before_id',root.id);
 end loop;
 return jsonb_build_object('version',1,'actor_id',actor,'client_id',p_client_id,'drafts',drafts,'has_more',has_more,'next_cursor',case when has_more then cursor_value else null end);
end $$

create function public.read_native_estimate_draft_history(p_id uuid,p_client_id uuid,p_before_version integer,p_limit integer) returns jsonb language plpgsql stable security definer set search_path=public as $$declare actor uuid:=public.clinical_require_staff();root public.native_estimate_drafts;rev_version integer;revisions jsonb:='[]';n integer:=0;has_more boolean:=false;cursor_version integer;begin
 if p_id is null or p_client_id is null or p_limit is null or p_limit not between 1 and 100 or(p_before_version is not null and p_before_version<1) then raise exception 'Valid estimate history page required' using errcode='23514';end if;select * into root from public.native_estimate_drafts d where d.id=p_id;
 if root.id is not null and root.client_id<>p_client_id then raise exception 'Estimate household mismatch' using errcode='23514';end if;
 for rev_version in select r.version from public.native_estimate_draft_revisions r where r.estimate_id=p_id and(p_before_version is null or r.version<p_before_version) order by r.version desc limit p_limit+1 loop
  n:=n+1;if n>p_limit then has_more:=true;exit;end if;revisions:=revisions||jsonb_build_array(public.native_estimate_verified_revision(p_id,rev_version));cursor_version:=rev_version;
 end loop;
 return jsonb_build_object('version',1,'actor_id',actor,'estimate_id',p_id,'client_id',p_client_id,'revisions',revisions,'has_more',has_more,'next_before_version',case when has_more then cursor_version else null end);
end $$

do $$declare fn record;begin
 for fn in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and(proname like 'native_estimate_%' or proname in('save_native_estimate_draft','recover_native_estimate_draft','close_native_estimate_draft','read_native_estimate_draft','list_native_estimate_drafts','read_native_estimate_draft_history')) loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',fn.signature);if fn.proname not like 'native_estimate_%' then execute format('grant execute on function %s to authenticated',fn.signature);end if;
 end loop;
end $$

do $$
declare
  t text;
begin
  foreach t in array array['native_estimate_publication_preparations', 'native_estimate_publication_artifacts', 'native_estimate_publication_events', 'native_estimate_publication_closures'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public,anon,authenticated,service_role', t);
    execute format('create trigger native_estimate_publication_immutable before update or delete on public.%I for each row execute function public.native_correction_immutable()', t);
    execute format('create trigger native_estimate_publication_no_truncate before truncate on public.%I for each statement execute function public.native_correction_immutable()', t);
    execute format('create trigger native_estimate_publication_audit after insert on public.%I for each row execute function public.native_rx_audit()', t);
  end loop;
end
$$

create function public.native_estpub_mutation (v jsonb)
  returns void
  language plpgsql
  immutable
  security definer
  set search_path = public
  as $$
declare
  q jsonb := v -> 'request';
begin
  perform
    public.native_rx_keys (v, array['kind', 'request']);
  if v ->> 'kind' = 'publish' then
    perform
      public.native_rx_keys (q, array['target', 'preparation_id', 'expected_draft_version', 'expected_publication_head', 'expected_content_hash', 'expected_artifact_hash', 'replaces_publication_id', 'attest_document_review', 'attest_pricing_review', 'attest_terms_review']);
    perform
      public.native_correction_uuid (q -> 'preparation_id', false);
    perform
      public.native_estimate_positive_int (q -> 'expected_draft_version');
    perform
      public.native_estpub_hash (q -> 'expected_content_hash');
    perform
      public.native_estpub_hash (q -> 'expected_artifact_hash');
    perform
      public.native_correction_uuid (q -> 'replaces_publication_id', true);
    if q -> 'attest_document_review' is distinct from 'true'::jsonb or q -> 'attest_pricing_review' is distinct from 'true'::jsonb or q -> 'attest_terms_review' is distinct from 'true'::jsonb then
      raise exception 'Publication review attestations required'
        using errcode = '23514';
    end if;
  elsif v ->> 'kind' = 'withdraw' then
    perform
      public.native_rx_keys (q, array['target', 'publication_id', 'expected_publication_head', 'reason', 'attest_review']);
    perform
      public.native_correction_uuid (q -> 'publication_id', false);
    perform
      public.native_rx_text (q -> 'reason', 2000);
    if q -> 'attest_review' is distinct from 'true'::jsonb then
      raise exception 'Withdrawal review required'
        using errcode = '23514';
    end if;
  else
    raise exception 'Exact publication mutation required'
      using errcode = '23514';
  end if;
  perform
    public.native_estpub_target (q -> 'target');
  perform
    public.native_estpub_head (q -> 'expected_publication_head');
end
$$

create function public.native_estpub_artifact (p_id uuid, p_snapshot jsonb, p_bytes bytea)
  returns jsonb
  language plpgsql
  immutable
  security definer
  set search_path = public
  as $$
declare
  html text;
begin
  if p_bytes is null or octet_length(p_bytes)
    not between 1 and 2097152 then
    raise exception 'Bounded publication artifact required'
      using errcode = '23514';
  end if;
  html := convert_from(p_bytes, 'UTF8');
  if strpos(html, 'default-src ''none''; style-src ''unsafe-inline''; base-uri ''none''; form-action ''none''') = 0 or html !~* '<!doctype html>' or html ~* '<[[:space:]]*(script|iframe|object|embed|base|form|a|link|img|video|audio|input|button|textarea|select|svg|math)([[:space:]/>])' or html ~* '<[a-z][^>]*[[:space:]]on[a-z]+[[:space:]]*=' or html ~* '<[a-z][^>]*javascript[[:space:]]*:' or html ~* '<[a-z][^>]*style[[:space:]]*=[^>]*(url[[:space:]]*\(|@import)' or html ~* '<style[^>]*>[^<]*(url[[:space:]]*\(|@import)' then
    raise exception 'Publication artifact contains unsupported active content'
      using errcode = '23514';
  end if;
  return jsonb_build_object('filename', 'estimate-' || (p_snapshot #>> '{target,estimate_id}') || '-draft-' || (p_snapshot ->> 'draft_version') || '-publication-' || p_id::text || '.html', 'mime_type', 'text/html; charset=utf-8', 'byte_length', octet_length(p_bytes), 'sha256', encode(sha256 (p_bytes), 'hex'), 'renderer_version', 1);
exception
  when character_not_in_repertoire
    or untranslatable_character then
    raise exception 'Publication artifact must be UTF-8' using errcode = '23514';
end
$$

-- No recursive lifecycle folds here. Callers verify the lifecycle separately when needed.
create function public.native_estpub_preparation (p_id uuid)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
declare
  p public.native_estimate_publication_preparations;
  a public.native_estimate_publication_artifacts;
  d jsonb;
  c jsonb;
  h jsonb;
  e public.native_estimate_publication_events;
begin
  select
    *
  into
    p
  from
    public.native_estimate_publication_preparations s
  where
    s.id = p_id;
  if not found then
    return null;
  end if;
  perform
    public.native_estpub_prepare_request (p.request);
  c := p.context;
  perform
    public.native_rx_keys (c, array['target', 'draft', 'draft_record_hash', 'publication_head', 'current_publication_id', 'practice', 'client', 'patient']);
  perform
    public.native_estpub_target (c -> 'target');
  perform
    public.native_estpub_head (c -> 'publication_head');
  perform
    public.native_correction_uuid (c -> 'current_publication_id', true);
  d := public.native_estimate_verified_revision ((c #>> '{target,estimate_id}')::uuid, (p.request ->> 'draft_version')::integer);
  if d is null or c -> 'draft' is distinct from d or c #> '{target,client_id}' is distinct from d -> 'client_id' or c #> '{target,pet_id}' is distinct from d -> 'pet_id' or c -> 'practice' is distinct from public.native_estpub_practice () or c -> 'target' is distinct from p.request -> 'target' or c -> 'publication_head' is distinct from p.request -> 'expected_publication_head' or c -> 'current_publication_id' is distinct from p.request -> 'replaces_publication_id' then
    raise exception 'Publication preparation source mismatch'
      using errcode = '23514';
  end if;
  if c ->> 'draft_record_hash' is distinct from (
    select
      r.record_hash
    from
      public.native_estimate_draft_revisions r
    where
      r.estimate_id = (d ->> 'id')::uuid and r.version = (d ->> 'version')::integer) then
    raise exception 'Publication draft hash mismatch'
      using errcode = '23514';
  end if;
  perform
    public.native_rx_keys (c -> 'client', array['id', 'version', 'name', 'mailing_address']);
  perform
    public.native_estimate_positive_int (c #> '{client,version}');
  perform
    public.native_rx_text (c #> '{client,name}', 301);
  if c #> '{client,mailing_address}' is distinct from 'null'::jsonb then
    perform
      public.native_rx_text (c #> '{client,mailing_address}', 1000);
  end if;
  perform
    public.native_rx_keys (c -> 'patient', array['id', 'version', 'name', 'species', 'breed']);
  perform
    public.native_estimate_positive_int (c #> '{patient,version}');
  perform
    public.native_rx_text (c #> '{patient,name}', 150);
  perform
    public.native_rx_text (c #> '{patient,species}', 100);
  if c #> '{patient,breed}' is distinct from 'null'::jsonb then
    perform
      public.native_rx_text (c #> '{patient,breed}', 150);
  end if;
  if c #> '{client,id}' is distinct from d -> 'client_id' or c #> '{patient,id}' is distinct from d -> 'pet_id' or not isfinite(p.created_at) or p.snapshot is distinct from public.native_estpub_snapshot (p.id, c, p.created_at) or p.created_at >= (p.snapshot #>> '{acceptance,expires_at}')::timestamptz or p.request_hash is distinct from public.native_fulfillment_hash (jsonb_build_object('version', 1, 'actor_id', p.actor_id, 'operation', 'prepare_estimate_publication', 'request', p.request)) or p.source_hash is distinct from public.native_fulfillment_hash (c) or p.request ->> 'expected_source_hash' is distinct from p.source_hash or p.content_hash is distinct from public.native_fulfillment_hash (p.snapshot) then
    raise exception 'Publication preparation evidence invalid'
      using errcode = '23514';
  end if;
  h := c -> 'publication_head';
  if h -> 'version' = '0'::jsonb then
    if c -> 'current_publication_id' is distinct from 'null'::jsonb then
      raise exception 'Empty publication context has current publication'
        using errcode = '23514';
    end if;
  else
    select
      *
    into
      e
    from
      public.native_estimate_publication_events ev
    where
      ev.id = (h ->> 'event_id')::uuid;
    if e.id is null or e.estimate_id <> (d ->> 'id')::uuid or e.version <> (h ->> 'version')::integer or e.document -> 'record_hash' is distinct from h -> 'record_hash' or e.document ->> 'record_hash' is distinct from public.native_fulfillment_hash (e.document - 'record_hash') or e.created_at > p.created_at or c -> 'current_publication_id' is distinct from (
  case when e.document ->> 'kind' = 'withdrawn' then
    'null'::jsonb
  else
    e.document -> 'publication_id'
  end) then
raise exception 'Publication preparation historical head invalid'
        using errcode = '23514';
    end if;
  end if;
  select
    *
  into
    a
  from
    public.native_estimate_publication_artifacts ar
  where
    ar.id = p_id;
  if a.id is not null and (a.metadata is distinct from public.native_estpub_artifact (p_id, p.snapshot, a.bytes) or not isfinite(a.captured_at) or a.captured_at < p.created_at) then
    raise exception 'Publication captured bytes invalid'
      using errcode = '23514';
  end if;
  return jsonb_build_object('version', 1, 'id', p.id, 'actor_id', p.actor_id, 'request', p.request, 'request_hash', p.request_hash, 'context', c, 'source_hash', p.source_hash, 'snapshot', p.snapshot, 'content_hash', p.content_hash, 'artifact', a.metadata, 'created_at', p.created_at);
end
$$

create function public.native_estpub_lifecycle (p_estimate_id uuid)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
declare
  r public.native_estimate_drafts;
  e public.native_estimate_publication_events;
  h jsonb := public.native_estpub_empty_head ();
  target jsonb;
  current_pub jsonb;
  latest_pub jsonb;
  events jsonb := '[]';
  p jsonb;
  q jsonb;
  expected jsonb;
  pub jsonb;
  stamp timestamptz;
begin
  select
    *
  into
    r
  from
    public.native_estimate_drafts dr
  where
    dr.id = p_estimate_id;
  if not found then
    raise exception 'Estimate root required'
      using errcode = '23514';
  end if;
  target := jsonb_build_object('estimate_id', r.id, 'client_id', r.client_id, 'pet_id', r.pet_id);
  for e in
  select
    ev.*
  from
    public.native_estimate_publication_events ev
  where
    ev.estimate_id = p_estimate_id
  order by
    ev.version loop
      perform
        public.native_estpub_mutation (e.mutation);
      q := e.mutation -> 'request';
      if e.version::bigint <> (h ->> 'version')::bigint + 1 or q -> 'target' is distinct from target or q -> 'expected_publication_head' is distinct from h or not isfinite(e.created_at) or e.created_at < stamp or exists (
      select
        1
      from
        public.native_estimate_publication_closures cl
      where
        cl.id = e.id) or e.request_hash is distinct from public.native_fulfillment_hash (jsonb_build_object('version', 1, 'actor_id', e.actor_id, 'operation', 'record_estimate_publication', 'mutation', e.mutation)) then
        raise exception 'Publication lifecycle identity mismatch'
          using errcode = '23514';
      end if;
      if e.mutation ->> 'kind' = 'publish' then
        p := public.native_estpub_preparation ((q ->> 'preparation_id')::uuid);
        if p is null or p ->> 'actor_id' <> e.actor_id::text or p #> '{request,target}' is distinct from target or p #> '{request,draft_version}' is distinct from q -> 'expected_draft_version' or p #> '{request,expected_publication_head}' is distinct from h or p -> 'content_hash' is distinct from q -> 'expected_content_hash' or p -> 'artifact' = 'null'::jsonb or p #> '{artifact,sha256}' is distinct from q -> 'expected_artifact_hash' or q -> 'replaces_publication_id' is distinct from coalesce(current_pub -> 'id', 'null'::jsonb) or p #> '{request,replaces_publication_id}' is distinct from q -> 'replaces_publication_id' or e.created_at < (p ->> 'created_at')::timestamptz or e.created_at >= (p #>> '{snapshot,acceptance,expires_at}')::timestamptz or e.created_at < (
      select
        a.captured_at
      from
        public.native_estimate_publication_artifacts a
      where
        a.id = (p ->> 'id')::uuid) then
          raise exception 'Published preparation mismatch'
            using errcode = '23514';
        end if;
        pub := jsonb_build_object('id', e.id, 'target', target, 'preparation_id', q -> 'preparation_id', 'draft_version', q -> 'expected_draft_version', 'draft_record_hash', p #> '{snapshot,draft_record_hash}', 'content_hash', p -> 'content_hash', 'artifact', p -> 'artifact', 'accept_by', p #> '{snapshot,acceptance,accept_by}', 'expires_at', p #> '{snapshot,acceptance,expires_at}', 'published_by', e.actor_id, 'published_at', e.created_at, 'replaces_publication_id', q -> 'replaces_publication_id');
        expected := jsonb_build_object('id', e.id, 'target', target, 'version', e.version, 'previous_hash', h -> 'record_hash', 'kind', 'published', 'actor_id', e.actor_id, 'created_at', e.created_at, 'publication_id', e.id, 'publication', pub, 'reason', null);
        current_pub := pub;
        latest_pub := pub;
      else
        if current_pub is null or current_pub -> 'id' is distinct from q -> 'publication_id' then
          raise exception 'Withdrawal must bind current publication'
            using errcode = '23514';
        end if;
        expected := jsonb_build_object('id', e.id, 'target', target, 'version', e.version, 'previous_hash', h -> 'record_hash', 'kind', 'withdrawn', 'actor_id', e.actor_id, 'created_at', e.created_at, 'publication_id', q -> 'publication_id', 'publication', null, 'reason', q -> 'reason');
        current_pub := null;
      end if;
      expected := expected || jsonb_build_object('record_hash', public.native_fulfillment_hash (expected));
      if e.document is distinct from expected then
        raise exception 'Publication event evidence mismatch'
          using errcode = '23514';
      end if;
      h := jsonb_build_object('event_id', e.id, 'version', e.version, 'record_hash', expected -> 'record_hash');
      stamp := e.created_at;
      events := events || jsonb_build_array(expected);
    end loop;
  return jsonb_build_object('target', target, 'head', h, 'current', current_pub, 'latest_publication', latest_pub, 'events', events);
end
$$

create function public.native_estpub_context (p_estimate_id uuid, p_client_id uuid, p_draft_version integer)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  d jsonb;
  l jsonb;
  c public.clients;
  p public.pets;
  v integer;
begin
  perform
    pg_advisory_xact_lock(hashtextextended('native-estimate:' || p_estimate_id::text, 0));
  perform
    public.clinical_require_staff ();
  l := public.native_estpub_lifecycle (p_estimate_id);
  if p_client_id is null or l #>> '{target,client_id}' is distinct from p_client_id::text then
    raise exception 'Publication household mismatch'
      using errcode = '23514';
  end if;
  select
    max(r.version)
  into
    v
  from
    public.native_estimate_draft_revisions r
  where
    r.estimate_id = p_estimate_id;
  if p_draft_version is distinct from v then
    raise exception 'Estimate draft changed'
      using errcode = '40001';
  end if;
  d := public.native_estimate_verified_revision (p_estimate_id, v);
  select
    *
  into
    c
  from
    public.clients cl
  where
    cl.id = p_client_id for share;
  select
    *
  into
    p
  from
    public.pets pt
  where
    pt.id = (d ->> 'pet_id')::uuid for share;
  perform
    public.clinical_require_staff ();
  if c.id is null or p.id is null or p.client_id <> c.id then
    raise exception 'Current publication household and patient mismatch'
      using errcode = '23514';
  end if;
  return jsonb_build_object('target', l -> 'target', 'draft', d, 'draft_record_hash', (
      select
        r.record_hash
      from public.native_estimate_draft_revisions r
      where
        r.estimate_id = p_estimate_id
        and r.version = v), 'publication_head', l -> 'head', 'current_publication_id', l #> '{current,id}', 'practice', public.native_estpub_practice (), 'client', jsonb_build_object('id', c.id, 'version', c.version, 'name', c.full_name, 'mailing_address', nullif (btrim(c.mailing_address), '')),'patient',jsonb_build_object('id',p.id,'version',p.version,'name',p.name,'species',p.species,'breed',nullif(btrim(p.breed),'')));
end
$$

create function public.prepare_native_estimate_publication (p_id uuid, p_request jsonb)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  p jsonb;
  c jsonb;
  s jsonb;
  stamp timestamptz;
begin
  if p_id is null then
    raise exception 'Preparation operation id required'
      using errcode = '23514';
  end if;
  perform
    public.native_estpub_prepare_request (p_request);
  perform
    pg_advisory_xact_lock(hashtextextended(p_id::text, 0));
  perform
    public.clinical_require_staff ();
  p := public.native_estpub_preparation (p_id);
  if p is not null then
    if p ->> 'actor_id' <> actor::text then
      raise exception 'Preparation unavailable'
        using errcode = '42501';
    end if;
    if p -> 'request' is distinct from p_request then
      raise exception 'Preparation id already used'
        using errcode = '23514';
    end if;
    perform
      public.native_estpub_lifecycle ((p_request #>> '{target,estimate_id}')::uuid);
    return p;
  end if;
  c := public.native_estpub_context ((p_request #>> '{target,estimate_id}')::uuid, (p_request #>> '{target,client_id}')::uuid, (p_request ->> 'draft_version')::integer);
  if c -> 'target' is distinct from p_request -> 'target' then
    raise exception 'Preparation target mismatch'
      using errcode = '23514';
  end if;
  if public.native_fulfillment_hash (c) is distinct from p_request ->> 'expected_source_hash' or c -> 'publication_head' is distinct from p_request -> 'expected_publication_head' or c -> 'current_publication_id' is distinct from p_request -> 'replaces_publication_id' then
    raise exception 'Publication preparation review changed'
      using errcode = '40001';
  end if;
  stamp := clock_timestamp();
  s := public.native_estpub_snapshot (p_id, c, stamp);
  if stamp >= (s #>> '{acceptance,expires_at}')::timestamptz then
    raise exception 'Estimate acceptance deadline expired'
      using errcode = '23514';
  end if;
  insert into public.native_estimate_publication_preparations
    values (p_id, actor, p_request, public.native_fulfillment_hash (jsonb_build_object('version', 1, 'actor_id', actor, 'operation', 'prepare_estimate_publication', 'request', p_request)), c, public.native_fulfillment_hash (c), s, public.native_fulfillment_hash (s), stamp);
  perform
    public.clinical_require_staff ();
  return public.native_estpub_preparation (p_id);
end
$$

create function public.recover_native_estimate_preparation (p_id uuid)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  p jsonb;
begin
  p := public.native_estpub_preparation (p_id);
  if p is not null then
    if p ->> 'actor_id' <> actor::text then
      raise exception 'Preparation unavailable'
        using errcode = '42501';
    end if;
    perform
      public.native_estpub_lifecycle ((p #>> '{request,target,estimate_id}')::uuid);
  end if;
  return p;
end
$$

create function public.native_estimate_capture_context (p_id uuid, p_actor_id uuid)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  p jsonb;
begin
  perform
    public.communication_require_service ();
  p := public.native_estpub_preparation (p_id);
  if p is null or p ->> 'actor_id' is distinct from p_actor_id::text or not public.is_active_staff (p_actor_id) then
    raise exception 'Preparation unavailable'
      using errcode = '42501';
  end if;
  perform
    public.native_estpub_lifecycle ((p #>> '{request,target,estimate_id}')::uuid);
  return jsonb_build_object('preparation', p, 'captured', p -> 'artifact' <> 'null'::jsonb);
end
$$

create function public.capture_native_estimate_publication_artifact (p_id uuid, p_actor_id uuid, p_content_hash text, p_renderer_version integer, p_html_utf8_base64 text)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  p jsonb;
  b bytea;
  m jsonb;
  a public.native_estimate_publication_artifacts;
begin
  perform
    public.communication_require_service ();
  if p_id is null or p_html_utf8_base64 is null or length(p_html_utf8_base64) > 2796204 or p_html_utf8_base64 !~ '^[A-Za-z0-9+/]*={0,2}$' then
    raise exception 'Bounded canonical artifact bytes required'
      using errcode = '23514';
  end if;
  perform
    pg_advisory_xact_lock(hashtextextended(p_id::text, 0));
  p := public.native_estpub_preparation (p_id);
  if p is null or p ->> 'actor_id' is distinct from p_actor_id::text then
    raise exception 'Preparation unavailable'
      using errcode = '42501';
  end if;
  perform
    pg_advisory_xact_lock(hashtextextended('native-estimate:' || (p #>> '{request,target,estimate_id}'), 0));
  if not public.is_active_staff (p_actor_id) then
    raise exception 'Active preparation creator required'
      using errcode = '42501';
  end if;
  perform
    public.native_estpub_lifecycle ((p #>> '{request,target,estimate_id}')::uuid);
  if p ->> 'content_hash' is distinct from p_content_hash or p_renderer_version is distinct from 1 then
    raise exception 'Capture source mismatch'
      using errcode = '23514';
  end if;
  b := decode(p_html_utf8_base64, 'base64');
  if replace(encode(b, 'base64'), E'\n', '') <> p_html_utf8_base64 then
    raise exception 'Canonical artifact encoding required'
      using errcode = '23514';
  end if;
  m := public.native_estpub_artifact (p_id, p -> 'snapshot', b);
  select
    *
  into
    a
  from
    public.native_estimate_publication_artifacts ar
  where
    ar.id = p_id;
  if found then
    if a.bytes is distinct from b or a.metadata is distinct from m then
      raise exception 'Captured artifact immutable'
        using errcode = '23514';
    end if;
    return a.metadata;
  end if;
  insert into public.native_estimate_publication_artifacts
  values
    (p_id, b, m, greatest (clock_timestamp(),
      (p ->> 'created_at')::timestamptz));
  if not public.is_active_staff (p_actor_id) then
    raise exception 'Active preparation creator required'
      using errcode = '42501';
  end if;
  perform
    public.native_estpub_preparation (p_id);
  return m;
exception
  when invalid_parameter_value
    or invalid_text_representation then
    raise exception 'Invalid encoded publication artifact' using errcode = '23514';
end
$$

create function public.native_estpub_record (p_id uuid, p_mutation jsonb)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  q jsonb := p_mutation -> 'request';
  l jsonb;
  p jsonb;
  c jsonb;
  d jsonb;
  pub jsonb;
  old jsonb;
  root_id uuid;
  stamp timestamptz;
  ver integer;
begin
  if p_id is null then
    raise exception 'Publication operation id required'
      using errcode = '23514';
  end if;
  perform
    public.native_estpub_mutation (p_mutation);
  perform
    pg_advisory_xact_lock(hashtextextended(p_id::text, 0));
  perform
    public.clinical_require_staff ();
  old := public.native_estpub_receipt (p_id);
  if old is not null then
    if old ->> 'actor_id' <> actor::text then
      raise exception 'Publication receipt unavailable'
        using errcode = '42501';
    end if;
    if old -> 'mutation' is distinct from p_mutation then
      raise exception 'Publication operation id already used'
        using errcode = '23514';
    end if;
    return old;
  end if;
  old := public.native_estpub_closure (p_id);
  if old is not null then
    if old ->> 'actor_id' <> actor::text then
      raise exception 'Publication closure unavailable'
        using errcode = '42501';
    end if;
    raise exception 'Publication operation permanently closed'
      using errcode = '23514';
  end if;
  root_id := (q #>> '{target,estimate_id}')::uuid;
  perform
    pg_advisory_xact_lock(hashtextextended('native-estimate:' || root_id::text, 0));
  perform
    public.clinical_require_staff ();
  l := public.native_estpub_lifecycle (root_id);
  if q -> 'target' is distinct from l -> 'target' then
    raise exception 'Publication target mismatch'
      using errcode = '23514';
  end if;
  if q -> 'expected_publication_head' is distinct from l -> 'head' then
    raise exception 'Publication lifecycle changed'
      using errcode = '40001';
  end if;
  if l #>> '{head,version}' = '2147483647' then
    raise exception 'Publication history version limit'
      using errcode = '23514';
  end if;
  ver := (l #>> '{head,version}')::integer + 1;
  if p_mutation ->> 'kind' = 'publish' then
    p := public.native_estpub_preparation ((q ->> 'preparation_id')::uuid);
    if p is null or p ->> 'actor_id' <> actor::text then
      raise exception 'Publication preparation unavailable'
        using errcode = '42501';
    end if;
    if p #> '{request,target}' is distinct from q -> 'target' or p #> '{request,draft_version}' is distinct from q -> 'expected_draft_version' or p -> 'content_hash' is distinct from q -> 'expected_content_hash' or p #> '{artifact,sha256}' is distinct from q -> 'expected_artifact_hash' then
      raise exception 'Exact captured preparation required'
        using errcode = '23514';
    end if;
    c := public.native_estpub_context (root_id, (q #>> '{target,client_id}')::uuid, (q ->> 'expected_draft_version')::integer);
    if c is distinct from p -> 'context' or q -> 'replaces_publication_id' is distinct from coalesce(l #> '{current,id}', 'null'::jsonb) then
      raise exception 'Prepared publication source changed'
        using errcode = '40001';
    end if;
    stamp := greatest (clock_timestamp(), (
      select
        max(ev.created_at)
      from public.native_estimate_publication_events ev
      where
        ev.estimate_id = root_id), (
        select
          a.captured_at
        from public.native_estimate_publication_artifacts a
        where
          a.id = (p ->> 'id')::uuid));
    if stamp >= (p #>> '{snapshot,acceptance,expires_at}')::timestamptz then
      raise exception 'Estimate acceptance deadline expired'
        using errcode = '23514';
    end if;
    pub := jsonb_build_object('id', p_id, 'target', q -> 'target', 'preparation_id', q -> 'preparation_id', 'draft_version', q -> 'expected_draft_version', 'draft_record_hash', p #> '{snapshot,draft_record_hash}', 'content_hash', p -> 'content_hash', 'artifact', p -> 'artifact', 'accept_by', p #> '{snapshot,acceptance,accept_by}', 'expires_at', p #> '{snapshot,acceptance,expires_at}', 'published_by', actor, 'published_at', stamp, 'replaces_publication_id', q -> 'replaces_publication_id');
    d := jsonb_build_object('id', p_id, 'target', q -> 'target', 'version', ver, 'previous_hash', l #> '{head,record_hash}', 'kind', 'published', 'actor_id', actor, 'created_at', stamp, 'publication_id', p_id, 'publication', pub, 'reason', null);
  else
    if l -> 'current' = 'null'::jsonb or l #> '{current,id}' is distinct from q -> 'publication_id' then
      raise exception 'Current publication changed'
        using errcode = '40001';
    end if;
    stamp := greatest (clock_timestamp(), (
      select
        max(ev.created_at)
      from public.native_estimate_publication_events ev
      where
        ev.estimate_id = root_id));
    d := jsonb_build_object('id', p_id, 'target', q -> 'target', 'version', ver, 'previous_hash', l #> '{head,record_hash}', 'kind', 'withdrawn', 'actor_id', actor, 'created_at', stamp, 'publication_id', q -> 'publication_id', 'publication', null, 'reason', q -> 'reason');
  end if;
  d := d || jsonb_build_object('record_hash', public.native_fulfillment_hash (d));
  perform
    public.clinical_require_staff ();
  insert into public.native_estimate_publication_events
    values (p_id, root_id, ver, actor, p_mutation, public.native_fulfillment_hash (jsonb_build_object('version', 1, 'actor_id', actor, 'operation', 'record_estimate_publication', 'mutation', p_mutation)), d, stamp);
  return public.native_estpub_receipt (p_id);
end
$$

create function public.recover_native_estimate_publication_operation (p_id uuid)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  r jsonb;
begin
  r := public.native_estpub_receipt (p_id);
  if r is not null and r ->> 'actor_id' <> actor::text then
    raise exception 'Publication receipt unavailable'
      using errcode = '42501';
  end if;
  return r;
end
$$

create function public.close_native_estimate_publication_operation (p_id uuid, p_mutation jsonb)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  r jsonb;
  d jsonb;
  stamp timestamptz;
  h text;
begin
  if p_id is null then
    raise exception 'Publication operation id required'
      using errcode = '23514';
  end if;
  perform
    public.native_estpub_mutation (p_mutation);
  perform
    pg_advisory_xact_lock(hashtextextended(p_id::text, 0));
  perform
    public.clinical_require_staff ();
  r := public.native_estpub_receipt (p_id);
  if r is not null then
    if r ->> 'actor_id' <> actor::text then
      raise exception 'Publication receipt unavailable'
        using errcode = '42501';
    end if;
    if r -> 'mutation' is distinct from p_mutation then
      raise exception 'Publication operation id already used'
        using errcode = '23514';
    end if;
    return jsonb_build_object('version', 1, 'status', 'recorded', 'receipt', r);
  end if;
  d := public.native_estpub_closure (p_id);
  if d is not null then
    if d ->> 'actor_id' <> actor::text then
      raise exception 'Publication closure unavailable'
        using errcode = '42501';
    end if;
    if d -> 'mutation' is distinct from p_mutation then
      raise exception 'Publication closure request changed'
        using errcode = '23514';
    end if;
  else
    stamp := clock_timestamp();
    h := public.native_fulfillment_hash (jsonb_build_object('version', 1, 'actor_id', actor, 'operation', 'record_estimate_publication', 'mutation', p_mutation));
    d := jsonb_build_object('version', 1, 'id', p_id, 'actor_id', actor, 'mutation', p_mutation, 'request_hash', h, 'closed_at', stamp);
    insert into public.native_estimate_publication_closures
      values (p_id, actor, p_mutation, h, stamp, public.native_fulfillment_hash (d));
    d := public.native_estpub_closure (p_id);
  end if;
  perform
    public.clinical_require_staff ();
  return jsonb_build_object('version', 1, 'status', 'closed_unrecorded', 'closure', d);
end
$$

create function public.read_native_estimate_publication_history (p_estimate_id uuid, p_client_id uuid, p_before_version integer, p_limit integer)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  l jsonb;
  e jsonb;
  events jsonb := '[]';
  n integer := 0;
  more boolean := false;
  cursor_version integer;
begin
  if p_limit is null or p_limit not between 1 and 100 or (p_before_version is not null and p_before_version < 1) then
    raise exception 'Valid publication history page required'
      using errcode = '23514';
  end if;
  l := public.native_estpub_lifecycle (p_estimate_id);
  if l #>> '{target,client_id}' is distinct from p_client_id::text then
    raise exception 'Publication household mismatch'
      using errcode = '23514';
  end if;
  for e in
  select
    value
  from
    jsonb_array_elements(l -> 'events')
  where
    p_before_version is null
    or (value ->> 'version')::integer < p_before_version
  order by
    (value ->> 'version')::integer desc
  limit p_limit + 1 loop
    n := n + 1;
    if n > p_limit then
      more := true;
      exit;
    end if;
    events := events || jsonb_build_array(e);
    cursor_version := (e ->> 'version')::integer;
  end loop;
  return jsonb_build_object('version', 1, 'actor_id', actor, 'target', l -> 'target', 'head', l -> 'head', 'events', events, 'has_more', more, 'next_before_version', case when more then
      cursor_version
    else
      null
    end);
end
$$

create function public.read_native_estimate_published_revision (p_publication_id uuid, p_client_id uuid)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  e public.native_estimate_publication_events;
  l jsonb;
  p jsonb;
  status text;
begin
  select
    *
  into
    e
  from
    public.native_estimate_publication_events ev
  where
    ev.id = p_publication_id;
  if not found or e.document ->> 'kind' <> 'published' then
    raise exception 'Published revision unavailable'
      using errcode = '23514';
  end if;
  l := public.native_estpub_lifecycle (e.estimate_id);
  if l #>> '{target,client_id}' is distinct from p_client_id::text then
    raise exception 'Publication household mismatch'
      using errcode = '23514';
  end if;
  p := public.native_estpub_preparation ((e.document #>> '{publication,preparation_id}')::uuid);
  status := case when l #>> '{latest_publication,id}' <> p_publication_id::text then
    'superseded'
  when l -> 'current' = 'null'::jsonb then
    'withdrawn'
  when clock_timestamp() >= (e.document #>> '{publication,expires_at}')::timestamptz then
    'expired'
  else
    'open'
  end;
  return jsonb_build_object('version', 1, 'actor_id', actor, 'publication', e.document -> 'publication', 'snapshot', p -> 'snapshot', 'head', l -> 'head', 'status', status);
end
$$

create function public.read_native_estimate_publication_artifact (p_preparation_id uuid, p_client_id uuid, p_expected_artifact_hash text)
  returns jsonb
  language plpgsql
  stable
  security definer
  set search_path = public
  as $$
declare
  actor uuid := public.clinical_require_staff ();
  p jsonb;
  a public.native_estimate_publication_artifacts;
begin
  p := public.native_estpub_preparation (p_preparation_id);
  if p is null or p #>> '{request,target,client_id}' is distinct from p_client_id::text then
    raise exception 'Publication artifact unavailable'
      using errcode = '42501';
  end if;
  perform
    public.native_estpub_lifecycle ((p #>> '{request,target,estimate_id}')::uuid);
  if p ->> 'actor_id' <> actor::text and not exists (
    select
      1
    from
      public.native_estimate_publication_events ev
    where
      ev.document #>> '{publication,preparation_id}' = p_preparation_id::text) then
    raise exception 'Unpublished artifact creator required'
      using errcode = '42501';
  end if;
  select
    *
  into
    a
  from
    public.native_estimate_publication_artifacts ar
  where
    ar.id = p_preparation_id;
  if a.id is null or a.metadata ->> 'sha256' is distinct from p_expected_artifact_hash then
    raise exception 'Exact captured artifact unavailable'
      using errcode = '23514';
  end if;
  return jsonb_build_object('artifact', a.metadata, 'content_base64', replace(encode(a.bytes, 'base64'), E'\n', ''));
end
$$

do $$
declare
  t text;
begin
  foreach t in array array['native_estimate_publication_preparations', 'native_estimate_publication_artifacts', 'native_estimate_publication_events', 'native_estimate_publication_closures'] loop
    execute format('create constraint trigger native_estimate_publication_valid after insert on public.%I deferrable initially deferred for each row execute function public.native_estpub_integrity()', t);
  end loop;
end
$$

create function public.guard_abandoned_attachment_cleanup() returns trigger language plpgsql set search_path=public as $$
begin
 if tg_op='DELETE' or old.state='complete' or
  (to_jsonb(new)-array['state','token','expires_at','completed_at']) is distinct from
  (to_jsonb(old)-array['state','token','expires_at','completed_at']) then
  raise exception 'Cleanup evidence is immutable' using errcode='23514';end if;
 if new.state='complete' and new.token is distinct from old.token then
  raise exception 'Cleanup completion must preserve the exact lease' using errcode='23514';end if;
 return new;
end $$

create function public.claim_abandoned_attachment_cleanup(p_upload_id uuid,p_grace_hours integer) returns jsonb
language plpgsql security definer set search_path=public as $$
declare upload public.conversation_attachment_uploads;receipt public.abandoned_attachment_cleanup;object_row storage.objects;
begin
 perform public.communication_require_service();
 if p_grace_hours is null or p_grace_hours not between 24 and 720 then
  raise exception 'Explicit cleanup grace from 24 to 720 hours required' using errcode='23514';end if;
 select * into upload from public.conversation_attachment_uploads where id=p_upload_id for update;
 if not found or upload.status<>'abandoned' then raise exception 'Only abandoned uploads may be cleaned' using errcode='42501';end if;
 -- Defense in depth: no abandoned object may have entered a prepared message manifest.
 if exists(select 1 from public.conversation_email_artifacts a cross join lateral jsonb_array_elements(a.manifest) f where f->>'upload_id'=upload.id::text) then
  raise exception 'Referenced attachment evidence must be retained' using errcode='42501';end if;
 select * into object_row from storage.objects where bucket_id='conversation-attachment-uploads' and name=upload.storage_path for share;
 select * into receipt from public.abandoned_attachment_cleanup where upload_id=upload.id and state='claimed' order by created_at limit 1 for update;
 if receipt.id is not null then
  if object_row.id is not null and row(object_row.id,object_row.created_at) is distinct from row(receipt.object_id,receipt.object_created_at) then
   raise exception 'Cleanup object identity changed' using errcode='42501';end if;
  if receipt.expires_at>clock_timestamp() then raise exception 'Cleanup already in progress' using errcode='40001';end if;
  update public.abandoned_attachment_cleanup set token=gen_random_uuid(),expires_at=clock_timestamp()+interval '2 minutes'
   where id=receipt.id returning * into receipt;
 else
  if object_row.id is null then return null;end if;
  if object_row.created_at>clock_timestamp()-make_interval(hours=>p_grace_hours)
   or upload.created_at>clock_timestamp()-make_interval(hours=>p_grace_hours) then return null;end if;
  if exists(select 1 from public.abandoned_attachment_cleanup where upload_id=upload.id and object_id=object_row.id) then
   raise exception 'Completed cleanup object unexpectedly exists' using errcode='23514';end if;
  insert into public.abandoned_attachment_cleanup(upload_id,object_id,object_created_at,storage_path,grace_hours,state,token,expires_at)
   values(upload.id,object_row.id,object_row.created_at,upload.storage_path,p_grace_hours,'claimed',gen_random_uuid(),clock_timestamp()+interval '2 minutes') returning * into receipt;
 end if;
 return public.abandoned_cleanup_lease(receipt,upload);
end $$

create function public.revalidate_abandoned_attachment_cleanup(p_id uuid,p_token uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare receipt public.abandoned_attachment_cleanup;upload public.conversation_attachment_uploads;object_row storage.objects;
begin
 perform public.communication_require_service();
 select * into receipt from public.abandoned_attachment_cleanup where id=p_id;
 if not found then raise exception 'Cleanup unavailable' using errcode='42501';end if;
 select * into upload from public.conversation_attachment_uploads where id=receipt.upload_id for update;
 select * into receipt from public.abandoned_attachment_cleanup where id=p_id for update;
 if upload.status<>'abandoned' or upload.storage_path is distinct from receipt.storage_path or receipt.state<>'claimed'
  or receipt.token is distinct from p_token then raise exception 'Cleanup lease or eligibility changed' using errcode='42501';end if;
 if receipt.expires_at<=clock_timestamp() then raise exception 'Cleanup lease expired' using errcode='40001';end if;
 if exists(select 1 from public.conversation_email_artifacts a cross join lateral jsonb_array_elements(a.manifest) f where f->>'upload_id'=upload.id::text) then
  raise exception 'Referenced attachment evidence must be retained' using errcode='42501';end if;
 select * into object_row from storage.objects where bucket_id='conversation-attachment-uploads' and name=receipt.storage_path for share;
 if object_row.id is not null and row(object_row.id,object_row.created_at) is distinct from row(receipt.object_id,receipt.object_created_at) then
  raise exception 'Cleanup object identity changed' using errcode='42501';end if;
 return public.abandoned_cleanup_lease(receipt,upload);
end $$

create function public.finalize_abandoned_attachment_cleanup(p_id uuid,p_token uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare receipt public.abandoned_attachment_cleanup;
begin
 perform public.communication_require_service();
 select * into receipt from public.abandoned_attachment_cleanup where id=p_id;
 if not found then raise exception 'Cleanup unavailable' using errcode='42501';end if;
 -- Preserve claim's upload-before-receipt lock order, including completion replay.
 perform 1 from public.conversation_attachment_uploads where id=receipt.upload_id for update;
 select * into receipt from public.abandoned_attachment_cleanup where id=p_id for update;
 if receipt.token is distinct from p_token then raise exception 'Cleanup lease changed' using errcode='42501';end if;
 if receipt.state='complete' then
  if exists(select 1 from storage.objects where bucket_id='conversation-attachment-uploads' and name=receipt.storage_path) then
   raise exception 'Completed cleanup object unexpectedly exists' using errcode='23514';end if;
  return jsonb_build_object('id',p_id,'status','complete');
 end if;
 perform public.revalidate_abandoned_attachment_cleanup(p_id,p_token);
 if exists(select 1 from storage.objects where bucket_id='conversation-attachment-uploads' and name=receipt.storage_path) then
  raise exception 'Cleanup object absence is unconfirmed' using errcode='23514';end if;
 update public.abandoned_attachment_cleanup set state='complete',expires_at=null,completed_at=clock_timestamp() where id=p_id;
 return jsonb_build_object('id',p_id,'status','complete');
end $$

create function public.native_estdec_instant(v jsonb) returns timestamptz
language plpgsql immutable security definer set search_path=public as $$
begin
  if jsonb_typeof(v) is distinct from 'string' or v#>>'{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?Z$' then
    raise exception 'Canonical UTC decision timestamp required' using errcode='23514';
  end if;
  return public.native_correction_instant(v);
end $$

create function public.native_estdec_binding(v jsonb) returns void
language plpgsql immutable security definer set search_path=public as $$
begin
  perform public.native_rx_keys(v,array['target','publication_id','content_hash','artifact_hash']);
  perform public.native_estpub_target(v->'target');
  perform public.native_correction_uuid(v->'publication_id',false);
  perform public.native_estpub_hash(v->'content_hash');
  perform public.native_estpub_hash(v->'artifact_hash');
end $$

create function public.native_estdec_principal(v jsonb) returns void
language plpgsql immutable security definer set search_path=public as $$
begin
  perform public.native_rx_keys(v,array['kind','id']);
  if jsonb_typeof(v->'kind') is distinct from 'string' or v->>'kind' not in ('staff','grant') then raise exception 'Invalid decision principal' using errcode='23514'; end if;
  perform public.native_correction_uuid(v->'id',false);
end $$

create function public.native_estdec_request(v jsonb,p_grant boolean) returns void
language plpgsql immutable security definer set search_path=public as $$
begin
  perform public.native_rx_keys(v,array['binding','grant_id','expected_publication_head','choice','signer_name','signer_relationship','comment','acknowledgment_version','attest_document_review','attest_authority','attest_choice']);
  perform public.native_estdec_binding(v->'binding');
  perform public.native_estpub_head(v->'expected_publication_head');
  perform public.native_correction_uuid(v->'grant_id',not p_grant);
  if not p_grant and v->'grant_id' is distinct from 'null'::jsonb then raise exception 'Witness cannot impersonate a grant' using errcode='23514'; end if;
  perform public.native_rx_text(v->'signer_name',200);
  if v->'comment'<>'null'::jsonb then perform public.native_rx_text(v->'comment',2000); end if;
  if jsonb_typeof(v->'choice') is distinct from 'string' or jsonb_typeof(v->'signer_relationship') is distinct from 'string' or v->>'choice' not in ('accept','decline') or v->>'signer_relationship' not in ('owner','authorized_agent')
    or v->'acknowledgment_version' is distinct from '1'::jsonb
    or v->'attest_document_review' is distinct from 'true'::jsonb
    or v->'attest_authority' is distinct from 'true'::jsonb
    or v->'attest_choice' is distinct from 'true'::jsonb then
    raise exception 'Exact decision and explicit attestations required' using errcode='23514';
  end if;
end $$

create function public.native_estdec_mutation(p_family text,v jsonb) returns void
language plpgsql immutable security definer set search_path=public as $$
declare q jsonb:=v->'request'; w jsonb;
begin
  perform public.native_rx_keys(v,array['kind','request']);
  if p_family='decision' and v->>'kind'='client_decision' then
    perform public.native_estdec_request(q,true);
  elsif p_family='decision' and v->>'kind'='witnessed_decision' then
    perform public.native_rx_keys(q,array['decision','witness']);
    perform public.native_estdec_request(q->'decision',false);
    w:=q->'witness';
    perform public.native_rx_keys(w,array['channel','occurred_at','note','attest_direct_client_instruction']);
    if jsonb_typeof(w->'channel') is distinct from 'string' or w->>'channel' not in ('in_person','telephone','video','written') or w->'attest_direct_client_instruction' is distinct from 'true'::jsonb then
      raise exception 'Direct witnessed client instruction required' using errcode='23514';
    end if;
    perform public.native_estdec_instant(w->'occurred_at');
    perform public.native_rx_text(w->'note',2000);
  elsif p_family='grant' and v->>'kind'='issue' then
    perform public.native_rx_keys(q,array['binding','expected_publication_head','expires_at','recipient_label','purpose','attest_recipient_authority']);
    perform public.native_estdec_binding(q->'binding');
    perform public.native_estpub_head(q->'expected_publication_head');
    perform public.native_estdec_instant(q->'expires_at');
    perform public.native_rx_text(q->'recipient_label',200);
    perform public.native_rx_text(q->'purpose',500);
    if q->'attest_recipient_authority' is distinct from 'true'::jsonb then raise exception 'Recipient review required' using errcode='23514'; end if;
  elsif p_family='grant' and v->>'kind'='activate' then
    perform public.native_rx_keys(q,array['grant_id','expected_grant_head','expected_publication_head','expected_context_hash','attest_review']);
    perform public.native_correction_uuid(q->'grant_id',false);
    perform public.native_estpub_head(q->'expected_grant_head');
    perform public.native_estpub_head(q->'expected_publication_head');
    perform public.native_estpub_hash(q->'expected_context_hash');
    if q->'attest_review' is distinct from 'true'::jsonb then raise exception 'Grant review required' using errcode='23514'; end if;
  elsif p_family='grant' and v->>'kind'='revoke' then
    perform public.native_rx_keys(q,array['grant_id','expected_grant_head','reason','attest_review']);
    perform public.native_correction_uuid(q->'grant_id',false);
    perform public.native_estpub_head(q->'expected_grant_head');
    perform public.native_rx_text(q->'reason',2000);
    if q->'attest_review' is distinct from 'true'::jsonb then raise exception 'Revocation review required' using errcode='23514'; end if;
  else raise exception 'Unknown estimate decision operation' using errcode='23514'; end if;
end $$

create function public.native_estdec_publication(p_binding jsonb,p_lifecycle jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare d jsonb; b jsonb;
begin
  perform public.native_estdec_binding(p_binding);
  select e.value->'publication' into d from jsonb_array_elements(p_lifecycle->'events') e
    where e.value->>'kind'='published' and e.value->'id'=p_binding->'publication_id';
  b:=jsonb_build_object('target',d->'target','publication_id',d->'id','content_hash',d->'content_hash','artifact_hash',d#>'{artifact,sha256}');
  if d is null or b is distinct from p_binding then raise exception 'Exact published estimate unavailable' using errcode='23514'; end if;
  return d;
end $$

-- Validate an historical reviewed publication prefix, without applying present-day eligibility.
create function public.native_estdec_prefix(p_lifecycle jsonb,p_binding jsonb,p_head jsonb,p_at timestamptz) returns void
language plpgsql security definer set search_path=public as $$
declare e jsonb; current_id jsonb:='null'; seen boolean:=false;
begin
  perform public.native_estpub_head(p_head);
  for e in select z.value from jsonb_array_elements(p_lifecycle->'events') z loop
    if (e->>'version')::integer>(p_head->>'version')::integer then
      if (e->>'created_at')::timestamptz<p_at then raise exception 'Publication prefix was already obsolete' using errcode='23514'; end if;
      exit;
    end if;
    if e->>'kind'='published' then current_id:=e->'publication_id'; else current_id:='null'; end if;
    if e->'id'=p_head->'event_id' then
      seen:=true;
      if jsonb_build_object('event_id',e->'id','version',e->'version','record_hash',e->'record_hash') is distinct from p_head
        or (e->>'created_at')::timestamptz>p_at then raise exception 'Invalid publication prefix' using errcode='23514'; end if;
    end if;
  end loop;
  if not seen or current_id is distinct from p_binding->'publication_id' then raise exception 'Reviewed publication was not current' using errcode='23514'; end if;
end $$

create function public.native_estdec_context(p_grant jsonb,p_origin text,p_key_version text) returns text
language plpgsql immutable security definer set search_path=public as $$
begin
  if p_origin is null or p_origin !~ '^https://[a-z0-9.-]+(:[0-9]+)?$' and p_origin !~ '^http://(127\.0\.0\.1|localhost)(:[0-9]+)?$'
    or p_key_version is null or p_key_version !~ '^[A-Za-z0-9_-]{1,40}$' then
    raise exception 'Estimate capability configuration unavailable' using errcode='23514';
  end if;
  return jsonb_build_object('domain','lrv-estimate-decision/v1','context_version',1,'grant_id',p_grant->'id',
    'actor_id',p_grant->'actor_id','binding',p_grant#>'{request,binding}','expires_at',p_grant#>'{request,expires_at}',
    'origin',p_origin,'key_version',p_key_version)::text;
end $$

-- Single fold for a grant. Receipt reconstruction never calls the operation verifier recursively.
create function public.native_estdec_grant_fold(p_id uuid) returns jsonb
language plpgsql security definer set search_path=public,extensions set timezone='UTC' as $$
declare g public.native_estimate_decision_grants; c public.native_estimate_decision_grant_captures;
  ev public.native_estimate_decision_grant_events; op public.native_estimate_decision_operations;
  life jsonb; pub jsonb; state jsonb; d jsonb; expected jsonb; head jsonb:=public.native_estpub_empty_head();
  receipts jsonb:='[]'; events jsonb:='[]'; n integer:=0; prior_at timestamptz; context_text text; cap jsonb;
  m jsonb; rh text; capture_json jsonb:='null'; capability jsonb:='null'; principal jsonb;
begin
  select * into g from public.native_estimate_decision_grants where id=p_id;
  if not found then return null; end if;
  m:=jsonb_build_object('kind','issue','request',g.request);
  perform public.native_estdec_mutation('grant',m);
  principal:=jsonb_build_object('kind','staff','id',g.actor_id);
  rh:=public.native_estdec_request_hash('grant',principal,m);
  if rh<>g.request_hash or g.estimate_id::text is distinct from g.request#>>'{binding,target,estimate_id}'
    or g.publication_id::text is distinct from g.request#>>'{binding,publication_id}'
    or g.expires_at is distinct from (g.request->>'expires_at')::timestamptz or g.expires_at<=g.created_at then
    raise exception 'Invalid immutable estimate grant' using errcode='23514';
  end if;
  life:=public.native_estpub_lifecycle(g.estimate_id);
  pub:=public.native_estdec_publication(g.request->'binding',life);
  perform public.native_estdec_prefix(life,g.request->'binding',g.request->'expected_publication_head',g.created_at);
  if g.expires_at>(pub->>'expires_at')::timestamptz then raise exception 'Grant outlives publication' using errcode='23514'; end if;
  state:=jsonb_build_object('version',1,'id',g.id,'actor_id',g.actor_id,'request',g.request,'request_hash',g.request_hash,
    'created_at',public.native_estdec_time(g.created_at),'capability',null,'capture',null,'head',head,'state','preparing','activation',null,'revocation',null);
  select * into c from public.native_estimate_decision_grant_captures where grant_id=g.id;
  if found then
    context_text:=public.native_estdec_context(state,c.origin,c.key_version);
    perform public.native_estpub_hash(to_jsonb(c.token_hash));
    cap:=to_jsonb(c)-'record_hash';
    if c.capability_context<>context_text or c.context_hash<>encode(digest(convert_to(context_text,'UTF8'),'sha256'),'hex')
      or c.record_hash<>public.native_fulfillment_hash(cap) or c.captured_at<g.created_at or c.captured_at>=g.expires_at then
      raise exception 'Invalid immutable estimate grant capture' using errcode='23514';
    end if;
    perform public.native_estdec_prefix(life,g.request->'binding',g.request->'expected_publication_head',c.captured_at);
    capability:=jsonb_build_object('origin',c.origin,'key_version',c.key_version,'context_hash',c.context_hash);
    capture_json:=jsonb_build_object('token_hash',c.token_hash,'captured_at',public.native_estdec_time(c.captured_at));
  end if;
  prior_at:=g.created_at;
  for ev in select * from public.native_estimate_decision_grant_events where grant_id=g.id order by grant_version loop
    n:=n+1; d:=ev.document;
    if ev.sequence<>(select count(*) from public.native_estimate_decision_grant_events ge where ge.estimate_id=g.estimate_id and ge.sequence<=ev.sequence) then raise exception 'Grant history sequence gap' using errcode='23514'; end if;
    select * into op from public.native_estimate_decision_operations where id=ev.id;
    if not found then raise exception 'Missing grant operation' using errcode='23514'; end if;
    perform public.native_estdec_mutation('grant',op.mutation);
    principal:=op.principal; perform public.native_estdec_principal(principal);
    if principal->>'kind'<>'staff' or not exists(select 1 from public.profiles p where p.id=(principal->>'id')::uuid)
      or op.family<>'grant' or ev.grant_version<>n or ev.previous_hash is distinct from head->>'record_hash'
      or ev.estimate_id<>g.estimate_id or ev.created_at<prior_at then raise exception 'Invalid grant event chain' using errcode='23514'; end if;
    if n=1 then
      if ev.id<>g.id or ev.created_at<>g.created_at or principal->>'id'<>g.actor_id::text or op.mutation is distinct from m then
        raise exception 'Grant issue evidence mismatch' using errcode='23514'; end if;
    else
      if op.mutation#>>'{request,grant_id}'<>g.id::text or op.mutation#>'{request,expected_grant_head}' is distinct from head then
        raise exception 'Grant event target or head mismatch' using errcode='23514'; end if;
      if c.grant_id is not null and c.captured_at<=ev.created_at then
        state:=state||jsonb_build_object('capability',capability,'capture',capture_json);
        if state->>'state'='preparing' then state:=jsonb_set(state,'{state}','"captured"'); end if;
      end if;
      if op.mutation->>'kind'='activate' then
        if state->>'state'<>'captured' or (op.mutation#>>'{request,expected_context_hash}') is distinct from c.context_hash
          or ev.created_at>=g.expires_at then raise exception 'Grant activation evidence invalid' using errcode='23514'; end if;
        perform public.native_estdec_prefix(life,g.request->'binding',op.mutation#>'{request,expected_publication_head}',ev.created_at);
        state:=state||jsonb_build_object('state','active','activation',jsonb_build_object('id',ev.id,'actor_id',principal->'id','created_at',public.native_estdec_time(ev.created_at)));
      elsif op.mutation->>'kind'='revoke' then
        if state->>'state'='revoked' then raise exception 'Grant already revoked' using errcode='23514'; end if;
        state:=state||jsonb_build_object('state','revoked','revocation',jsonb_build_object('id',ev.id,'actor_id',principal->'id','reason',op.mutation#>'{request,reason}','created_at',public.native_estdec_time(ev.created_at)));
      else raise exception 'Invalid subsequent grant action' using errcode='23514'; end if;
    end if;
    expected:=jsonb_build_object('id',ev.id,'grant_id',g.id,'target',g.request#>'{binding,target}','sequence',ev.sequence,
      'grant_version',n,'previous_hash',head->'record_hash','kind',case op.mutation->>'kind' when 'issue' then 'issued' when 'activate' then 'activated' else 'revoked' end,
      'actor_id',principal->'id','created_at',public.native_estdec_time(ev.created_at),'request',op.mutation->'request');
    expected:=expected||jsonb_build_object('record_hash',public.native_fulfillment_hash(expected));
    if d is distinct from expected then raise exception 'Grant event hash or shape invalid' using errcode='23514'; end if;
    head:=jsonb_build_object('event_id',ev.id,'version',n,'record_hash',d->'record_hash');
    state:=jsonb_set(state,'{head}',head);
    expected:=jsonb_build_object('version',1,'id',ev.id,'actor_id',principal->'id','mutation',op.mutation,
      'request_hash',public.native_estdec_request_hash('grant',principal,op.mutation),'result',public.native_estdec_grant_view(state),'created_at',public.native_estdec_time(ev.created_at));
    if op.receipt is distinct from expected or op.request_hash is distinct from expected->>'request_hash' or op.created_at<>ev.created_at
      or exists(select 1 from public.native_estimate_decision_closures cl where cl.id=ev.id) then
      raise exception 'Grant receipt integrity failure' using errcode='23514'; end if;
    receipts:=receipts||jsonb_build_array(expected); events:=events||jsonb_build_array(d||jsonb_build_object('grant',expected->'result'));
    prior_at:=ev.created_at;
  end loop;
  if n=0 then raise exception 'Missing grant issue event' using errcode='23514'; end if;
  if c.grant_id is not null then
    if state->'revocation'<>'null'::jsonb and c.captured_at>(state#>>'{revocation,created_at}')::timestamptz then raise exception 'Capture after revocation' using errcode='23514'; end if;
    state:=state||jsonb_build_object('capability',capability,'capture',capture_json);
    if state->>'state'='preparing' then state:=jsonb_set(state,'{state}','"captured"'); end if;
  end if;
  return jsonb_build_object('grant',state,'events',events,'receipts',receipts);
end $$

create function public.native_estdec_verified_state(p_estimate_id uuid) returns jsonb
language plpgsql security definer set search_path=public set timezone='UTC' as $$
declare life jsonb:=public.native_estpub_lifecycle(p_estimate_id); head jsonb:=public.native_estpub_empty_head();
  r public.native_estimate_decisions; op public.native_estimate_decision_operations;
  q jsonb; m jsonb; pub jsonb; g jsonb; d jsonb; receipt jsonb; prov jsonb;
  items jsonb:='[]'; receipts jsonb:='[]'; n integer:=0; prior_at timestamptz; at_time timestamptz;
begin
  for r in select * from public.native_estimate_decisions where estimate_id=p_estimate_id order by sequence loop
    n:=n+1;
    select * into op from public.native_estimate_decision_operations where id=r.id;
    if not found or op.family<>'decision' then raise exception 'Missing decision operation' using errcode='23514'; end if;
    m:=op.mutation;
    perform public.native_estdec_mutation('decision',m);
    perform public.native_estdec_principal(op.principal);
    q:=case when m->>'kind'='client_decision' then m->'request' else m#>'{request,decision}' end;
    pub:=public.native_estdec_publication(q->'binding',life);
    perform public.native_estdec_prefix(life,q->'binding',q->'expected_publication_head',r.created_at);
    if r.sequence<>n or r.principal is distinct from op.principal or r.request_hash<>public.native_estdec_request_hash('decision',op.principal,m)
      or r.request_hash<>op.request_hash or r.publication_id::text<>q#>>'{binding,publication_id}'
      or q#>'{binding,target}' is distinct from life->'target' or r.created_at<(pub->>'published_at')::timestamptz
      or r.created_at>=(pub->>'expires_at')::timestamptz or r.created_at<prior_at or op.created_at<>r.created_at
      or exists(select 1 from public.native_estimate_decision_closures c where c.id=r.id) then
      raise exception 'Decision source or sequence integrity failure' using errcode='23514';
    end if;
    if m->>'kind'='client_decision' then
      g:=public.native_estdec_verified_grant((q->>'grant_id')::uuid);
      if g is null or op.principal is distinct from jsonb_build_object('kind','grant','id',q->'grant_id')
        or g#>'{request,binding}' is distinct from q->'binding' or g->'activation'='null'::jsonb
        or (g#>>'{activation,created_at}')::timestamptz>r.created_at or (g#>>'{request,expires_at}')::timestamptz<=r.created_at
        or (g->'revocation'<>'null'::jsonb and (g#>>'{revocation,created_at}')::timestamptz<r.created_at) then
        raise exception 'Decision grant attribution invalid' using errcode='23514';
      end if;
      prov:=jsonb_build_object('kind','grant','grant_id',q->'grant_id');
    else
      at_time:=(m#>>'{request,witness,occurred_at}')::timestamptz;
      if op.principal->>'kind'<>'staff' or not exists(select 1 from public.profiles p where p.id=(op.principal->>'id')::uuid)
        or at_time>r.created_at or at_time<(pub->>'published_at')::timestamptz then raise exception 'Witness attribution invalid' using errcode='23514'; end if;
      prov:=jsonb_build_object('kind','staff_witness','actor_id',op.principal->'id','witness',m#>'{request,witness}');
    end if;
    d:=jsonb_build_object('version',1,'id',r.id,'sequence',n,'binding',q->'binding','choice',q->'choice',
      'signer_name',q->'signer_name','signer_relationship',q->'signer_relationship','comment',q->'comment','acknowledgment_version',1,
      'provenance',prov,'publication_head',q->'expected_publication_head','decision_head',head,'recorded_at',public.native_estdec_time(r.created_at));
    d:=d||jsonb_build_object('record_hash',public.native_fulfillment_hash(d));
    receipt:=jsonb_build_object('version',1,'id',r.id,'principal',op.principal,'mutation',m,'request_hash',r.request_hash,'result',d,'created_at',public.native_estdec_time(r.created_at));
    if r.document is distinct from d or op.receipt is distinct from receipt then raise exception 'Decision receipt or hash invalid' using errcode='23514'; end if;
    head:=jsonb_build_object('event_id',r.id,'version',n,'record_hash',d->'record_hash');
    items:=items||jsonb_build_array(d); receipts:=receipts||jsonb_build_array(receipt); prior_at:=r.created_at;
  end loop;
  return jsonb_build_object('target',life->'target','head',head,'decisions',items,'receipts',receipts);
end $$

create function public.native_estdec_verified_operation(p_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare op public.native_estimate_decision_operations; verified jsonb; root_id uuid; grant_id uuid;
begin
  select * into op from public.native_estimate_decision_operations where id=p_id;
  if not found then return null; end if;
  if op.family='grant' then
    select e.grant_id into grant_id from public.native_estimate_decision_grant_events e where e.id=p_id;
    select x.value into verified from jsonb_array_elements(public.native_estdec_grant_fold(grant_id)->'receipts') x where x.value->>'id'=p_id::text;
  else
    select d.estimate_id into root_id from public.native_estimate_decisions d where d.id=p_id;
    select x.value into verified from jsonb_array_elements(public.native_estdec_verified_state(root_id)->'receipts') x where x.value->>'id'=p_id::text;
  end if;
  if verified is null or verified is distinct from op.receipt then raise exception 'Orphaned decision operation' using errcode='23514'; end if;
  return verified;
end $$

create function public.native_estdec_scope(p_family text,p_mutation jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare b jsonb; g jsonb;
begin
  perform public.native_estdec_mutation(p_family,p_mutation);
  if p_family='grant' and p_mutation->>'kind'<>'issue' then
    g:=public.native_estdec_verified_grant((p_mutation#>>'{request,grant_id}')::uuid);
    if g is null then raise exception 'Estimate grant unavailable' using errcode='42501'; end if;
    b:=g#>'{request,binding}';
  elsif p_mutation->>'kind'='witnessed_decision' then b:=p_mutation#>'{request,decision,binding}';
  else b:=p_mutation#>'{request,binding}'; end if;
  perform public.native_estdec_publication(b,public.native_estpub_lifecycle((b#>>'{target,estimate_id}')::uuid));
  if p_mutation->>'kind'='client_decision' then
    g:=public.native_estdec_verified_grant((p_mutation#>>'{request,grant_id}')::uuid);
    if g is null or g#>'{request,binding}' is distinct from b then raise exception 'Grant request scope mismatch' using errcode='23514'; end if;
  end if;
  return b;
end $$

create function public.native_estdec_verified_closure(p_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare c public.native_estimate_decision_closures; d jsonb;
begin
  select * into c from public.native_estimate_decision_closures where id=p_id;
  if not found then return null; end if;
  perform public.native_estdec_mutation(c.family,c.mutation);
  perform public.native_estdec_principal(c.principal); perform public.native_estdec_principal(c.closed_by);
  perform public.native_estdec_scope(c.family,c.mutation);
  if c.family='grant' or c.mutation->>'kind'='witnessed_decision' then
    if c.principal->>'kind'<>'staff' or c.closed_by is distinct from c.principal or c.reason is not null
      or not exists(select 1 from public.profiles p where p.id=(c.principal->>'id')::uuid) then raise exception 'Closure staff attribution invalid' using errcode='23514'; end if;
  else
    if c.principal is distinct from jsonb_build_object('kind','grant','id',c.mutation#>'{request,grant_id}') then raise exception 'Closure grant attribution invalid' using errcode='23514'; end if;
    if c.closed_by->>'kind'='staff' then
      perform public.native_rx_text(to_jsonb(c.reason),2000);
      if not exists(select 1 from public.profiles p where p.id=(c.closed_by->>'id')::uuid) then raise exception 'Unknown closure reviewer' using errcode='23514'; end if;
    elsif c.closed_by is distinct from c.principal or c.reason is not null then raise exception 'Closure attribution invalid' using errcode='23514'; end if;
  end if;
  d:=public.native_estdec_closure_document(c);
  if c.request_hash<>public.native_estdec_request_hash(c.family,c.principal,c.mutation) or c.record_hash<>public.native_fulfillment_hash(d-'record_hash')
    or exists(select 1 from public.native_estimate_decision_operations o where o.id=c.id)
    or exists(select 1 from public.native_estimate_decisions x where x.id=c.id)
    or exists(select 1 from public.native_estimate_decision_grant_events x where x.id=c.id) then
    raise exception 'Closure evidence integrity failure' using errcode='23514'; end if;
  return d;
end $$

create function public.native_estdec_access(p_grant_id uuid,p_token_hash text,p_origin text,p_key_version text,p_current boolean) returns jsonb
language plpgsql security definer set search_path=public as $$
declare g jsonb:=public.native_estdec_verified_grant(p_grant_id); c public.native_estimate_decision_grant_captures; life jsonb;
begin
  select * into c from public.native_estimate_decision_grant_captures where grant_id=p_grant_id;
  if g is null or c.grant_id is null or p_token_hash is null or c.token_hash is distinct from p_token_hash
    or c.origin is distinct from p_origin or c.key_version is distinct from p_key_version
    or g->>'state'<>'active' or not public.is_active_staff((g->>'actor_id')::uuid)
    or clock_timestamp()>=(g#>>'{request,expires_at}')::timestamptz then
    raise exception 'Estimate access unavailable' using errcode='42501'; end if;
  if p_current then
    life:=public.native_estpub_lifecycle((g#>>'{request,binding,target,estimate_id}')::uuid);
    if life#>'{current,id}' is distinct from g#>'{request,binding,publication_id}' then raise exception 'Estimate publication changed' using errcode='40001'; end if;
  end if;
  return g;
end $$

create function public.native_estdec_current(p_binding jsonb,p_head jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare life jsonb:=public.native_estpub_lifecycle((p_binding#>>'{target,estimate_id}')::uuid); pub jsonb;
begin
  pub:=public.native_estdec_publication(p_binding,life);
  if life->'head' is distinct from p_head or life#>'{current,id}' is distinct from p_binding->'publication_id' then raise exception 'Estimate publication changed' using errcode='40001'; end if;
  if clock_timestamp()>=(pub->>'expires_at')::timestamptz then raise exception 'Estimate deadline expired' using errcode='23514'; end if;
  if exists(select 1 from public.native_estimate_decisions d where d.publication_id=(pub->>'id')::uuid) then
    perform public.native_estdec_verified_state((p_binding#>>'{target,estimate_id}')::uuid);
    raise exception 'Estimate already decided' using errcode='23514';
  end if;
  return pub;
end $$

-- The only mutable state is a private 60-read, one-minute budget. No lifetime lockout.
create function public.native_estdec_budget(p_grant_id uuid) returns void
language plpgsql security definer set search_path=public as $$
declare b public.native_estimate_decision_access_budget; stamp timestamptz;
begin
  insert into public.native_estimate_decision_access_budget values(p_grant_id,clock_timestamp(),0) on conflict(grant_id) do nothing;
  select * into strict b from public.native_estimate_decision_access_budget where grant_id=p_grant_id for update;
  stamp:=clock_timestamp();
  if stamp>=b.window_started_at+interval '1 minute' then
    update public.native_estimate_decision_access_budget set window_started_at=stamp,used=1 where grant_id=p_grant_id;
  elsif b.used>=60 then raise exception 'Estimate read limit reached' using errcode='54000';
  else update public.native_estimate_decision_access_budget set used=used+1 where grant_id=p_grant_id; end if;
end $$

create function public.native_estdec_authorize(p_principal jsonb,p_proof jsonb,p_current boolean default false) returns void
language plpgsql security definer set search_path=public as $$
begin
  if p_principal->>'kind'='staff' then
    if public.clinical_require_staff()::text is distinct from p_principal->>'id' then raise exception 'Decision actor changed' using errcode='42501'; end if;
  else
    perform public.communication_require_service();
    perform public.native_estdec_access((p_principal->>'id')::uuid,p_proof->>'token_hash',p_proof->>'origin',p_proof->>'key_version',p_current);
  end if;
end $$

create function public.native_estdec_lock(p_id uuid,p_family text,p_mutation jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare b jsonb;
begin
  if p_id is null then raise exception 'Operation identity required' using errcode='23514'; end if;
  perform public.native_estdec_mutation(p_family,p_mutation);
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
  b:=public.native_estdec_scope(p_family,p_mutation);
  perform pg_advisory_xact_lock(hashtextextended('native-estimate:'||(b#>>'{target,estimate_id}'),0));
  perform public.native_estdec_scope(p_family,p_mutation);
  return b;
end $$

create function public.native_estdec_existing(p_id uuid,p_family text,p_principal jsonb,p_mutation jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare o public.native_estimate_decision_operations; c public.native_estimate_decision_closures; r jsonb;
begin
  select * into o from public.native_estimate_decision_operations where id=p_id;
  if found then
    if o.principal is distinct from p_principal then raise exception 'Operation belongs to another principal' using errcode='42501'; end if;
    if o.family<>p_family or o.mutation is distinct from p_mutation then raise exception 'Operation identity already used' using errcode='23514'; end if;
    r:=public.native_estdec_verified_operation(p_id);
    return jsonb_build_object('version',1,'status','recorded','receipt',r);
  end if;
  select * into c from public.native_estimate_decision_closures where id=p_id;
  if found then
    if c.principal is distinct from p_principal then raise exception 'Closure belongs to another principal' using errcode='42501'; end if;
    if c.family<>p_family or c.mutation is distinct from p_mutation then raise exception 'Closed operation identity already used' using errcode='23514'; end if;
    return jsonb_build_object('version',1,'status','closed_unrecorded','closure',public.native_estdec_verified_closure(p_id));
  end if;
  return jsonb_build_object('version',1,'status','unrecorded');
end $$

create function public.record_native_estimate_decision_grant(p_id uuid,p_mutation jsonb) returns jsonb
language plpgsql security definer set search_path=public set timezone='UTC' as $$
declare actor uuid:=public.clinical_require_staff(); principal jsonb; b jsonb; previous jsonb;
  q jsonb:=p_mutation->'request'; g jsonb; gid uuid; root_id uuid; stamp timestamptz;
  seq integer; ver integer; d jsonb; receipt jsonb; rh text; old jsonb; kind text:=p_mutation->>'kind';
begin
  principal:=jsonb_build_object('kind','staff','id',actor);
  b:=public.native_estdec_lock(p_id,'grant',p_mutation); root_id:=(b#>>'{target,estimate_id}')::uuid;
  perform public.native_estdec_authorize(principal,null);
  old:=public.native_estdec_existing(p_id,'grant',principal,p_mutation);
  if old->>'status'='recorded' then return old->'receipt'; end if;
  if old->>'status'='closed_unrecorded' then raise exception 'Operation permanently closed' using errcode='23514'; end if;
  rh:=public.native_estdec_request_hash('grant',principal,p_mutation);
  select coalesce(max(e.sequence),0)+1 into seq from public.native_estimate_decision_grant_events e where e.estimate_id=root_id;
  stamp:=clock_timestamp();
  if kind='issue' then
    perform public.native_estdec_current(b,q->'expected_publication_head');
    if (q->>'expires_at')::timestamptz<=stamp or (q->>'expires_at')::timestamptz>(public.native_estdec_publication(b,public.native_estpub_lifecycle(root_id))->>'expires_at')::timestamptz then
      raise exception 'Grant deadline invalid' using errcode='23514'; end if;
    gid:=p_id; ver:=1; previous:=public.native_estpub_empty_head();
    g:=jsonb_build_object('version',1,'id',gid,'actor_id',actor,'request',q,'request_hash',rh,'created_at',public.native_estdec_time(stamp),
      'capability',null,'capture',null,'head',previous,'state','preparing','activation',null,'revocation',null);
  else
    gid:=(q->>'grant_id')::uuid; g:=public.native_estdec_verified_grant(gid); previous:=g->'head';
    if previous is distinct from q->'expected_grant_head' then raise exception 'Grant review changed' using errcode='40001'; end if;
    ver:=(previous->>'version')::integer+1;
    if kind='activate' then
      perform public.native_estdec_current(b,q->'expected_publication_head');
      if g->>'state'<>'captured' or not public.is_active_staff((g->>'actor_id')::uuid)
        or g#>'{capability,context_hash}' is distinct from q->'expected_context_hash' or stamp>=(g#>>'{request,expires_at}')::timestamptz then
        raise exception 'Captured grant unavailable for activation' using errcode='23514'; end if;
      g:=g||jsonb_build_object('state','active','activation',jsonb_build_object('id',p_id,'actor_id',actor,'created_at',public.native_estdec_time(stamp)));
    else
      if g->>'state'='revoked' then raise exception 'Grant already revoked' using errcode='23514'; end if;
      g:=g||jsonb_build_object('state','revoked','revocation',jsonb_build_object('id',p_id,'actor_id',actor,'reason',q->'reason','created_at',public.native_estdec_time(stamp)));
    end if;
  end if;
  d:=jsonb_build_object('id',p_id,'grant_id',gid,'target',b->'target','sequence',seq,'grant_version',ver,'previous_hash',previous->'record_hash',
    'kind',case kind when 'issue' then 'issued' when 'activate' then 'activated' else 'revoked' end,'actor_id',actor,'created_at',public.native_estdec_time(stamp),'request',q);
  d:=d||jsonb_build_object('record_hash',public.native_fulfillment_hash(d));
  g:=jsonb_set(g,'{head}',jsonb_build_object('event_id',p_id,'version',ver,'record_hash',d->'record_hash'));
  receipt:=jsonb_build_object('version',1,'id',p_id,'actor_id',actor,'mutation',p_mutation,'request_hash',rh,'result',public.native_estdec_grant_view(g),'created_at',public.native_estdec_time(stamp));
  perform public.native_estdec_authorize(principal,null);
  if kind='issue' then
    insert into public.native_estimate_decision_grants values(gid,actor,root_id,(b->>'publication_id')::uuid,q,rh,(q->>'expires_at')::timestamptz,stamp);
  end if;
  insert into public.native_estimate_decision_grant_events values(p_id,gid,root_id,seq,ver,previous->>'record_hash',d,stamp);
  insert into public.native_estimate_decision_operations values(p_id,'grant',principal,p_mutation,rh,receipt,stamp);
  return public.native_estdec_verified_operation(p_id);
end $$

create function public.native_estimate_decision_grant_capture_context(p_grant_id uuid,p_actor_id uuid,p_origin text,p_key_version text) returns jsonb
language plpgsql security definer set search_path=public,extensions as $$
declare g jsonb; c public.native_estimate_decision_grant_captures; ctxt text; life jsonb;
begin
  perform public.communication_require_service();
  perform pg_advisory_xact_lock(hashtextextended(p_grant_id::text,0));
  g:=public.native_estdec_verified_grant(p_grant_id);
  if g is null then raise exception 'Estimate grant unavailable' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('native-estimate:'||(g#>>'{request,binding,target,estimate_id}'),0));
  g:=public.native_estdec_verified_grant(p_grant_id);
  if g->>'actor_id' is distinct from p_actor_id::text or not public.is_active_staff(p_actor_id) then raise exception 'Grant creator unavailable' using errcode='42501'; end if;
  select * into c from public.native_estimate_decision_grant_captures where grant_id=p_grant_id;
  if found then
    return jsonb_build_object('grant',g,'capability_context',c.capability_context,'context_hash',c.context_hash,'captured',true);
  end if;
  life:=public.native_estpub_lifecycle((g#>>'{request,binding,target,estimate_id}')::uuid);
  perform public.native_estdec_current(g#>'{request,binding}',life->'head');
  if g->>'state'<>'preparing' or clock_timestamp()>=(g#>>'{request,expires_at}')::timestamptz then raise exception 'Grant capture unavailable' using errcode='42501'; end if;
  ctxt:=public.native_estdec_context(g,p_origin,p_key_version);
  return jsonb_build_object('grant',g,'capability_context',ctxt,'context_hash',encode(digest(convert_to(ctxt,'UTF8'),'sha256'),'hex'),'captured',false);
end $$

create function public.capture_native_estimate_decision_grant(p_grant_id uuid,p_actor_id uuid,p_origin text,p_key_version text,p_context_hash text,p_token_hash text) returns jsonb
language plpgsql security definer set search_path=public set timezone='UTC' as $$
declare ctx jsonb; c public.native_estimate_decision_grant_captures; stamp timestamptz;
begin
  ctx:=public.native_estimate_decision_grant_capture_context(p_grant_id,p_actor_id,p_origin,p_key_version);
  perform public.native_estpub_hash(to_jsonb(p_token_hash));
  if ctx->>'context_hash' is distinct from p_context_hash then raise exception 'Capability context changed' using errcode='23514'; end if;
  select * into c from public.native_estimate_decision_grant_captures where grant_id=p_grant_id;
  if found then
    if c.origin is distinct from p_origin or c.key_version is distinct from p_key_version or c.token_hash is distinct from p_token_hash then
      raise exception 'Captured capability cannot change' using errcode='23514'; end if;
    return public.native_estdec_grant_view(ctx->'grant');
  end if;
  stamp:=clock_timestamp();
  if not public.is_active_staff(p_actor_id) or stamp>=(ctx#>>'{grant,request,expires_at}')::timestamptz then raise exception 'Grant capture unavailable' using errcode='42501'; end if;
  c.grant_id:=p_grant_id; c.origin:=p_origin; c.key_version:=p_key_version; c.capability_context:=ctx->>'capability_context';
  c.context_hash:=p_context_hash; c.token_hash:=p_token_hash; c.captured_at:=stamp;
  c.record_hash:=public.native_fulfillment_hash(to_jsonb(c)-'record_hash');
  insert into public.native_estimate_decision_grant_captures select c.*;
  return public.native_estdec_grant_view(public.native_estdec_verified_grant(p_grant_id));
end $$

create function public.native_estimate_decision_access_context(p_grant_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare g jsonb; c public.native_estimate_decision_grant_captures;
begin
  perform public.communication_require_service();
  g:=public.native_estdec_verified_grant(p_grant_id);
  select * into c from public.native_estimate_decision_grant_captures where grant_id=p_grant_id;
  if g is null or not found then raise exception 'Estimate access unavailable' using errcode='42501'; end if;
  return jsonb_build_object('grant',g,'capability_context',c.capability_context,'context_hash',c.context_hash,'captured',true);
end $$

create function public.native_estdec_record(p_id uuid,p_mutation jsonb,p_principal jsonb,p_proof jsonb) returns jsonb
language plpgsql security definer set search_path=public set timezone='UTC' as $$
declare b jsonb; old jsonb; state jsonb; pub jsonb; q jsonb; d jsonb; receipt jsonb; prov jsonb; rh text; stamp timestamptz; seq integer;
begin
  perform public.native_estdec_principal(p_principal);
  b:=public.native_estdec_lock(p_id,'decision',p_mutation);
  perform public.native_estdec_authorize(p_principal,p_proof);
  if (p_mutation->>'kind'='client_decision' and p_principal is distinct from jsonb_build_object('kind','grant','id',p_mutation#>'{request,grant_id}'))
    or (p_mutation->>'kind'='witnessed_decision' and p_principal->>'kind'<>'staff') then raise exception 'Decision principal mismatch' using errcode='42501'; end if;
  old:=public.native_estdec_existing(p_id,'decision',p_principal,p_mutation);
  if old->>'status'='recorded' then return old->'receipt'; end if;
  if old->>'status'='closed_unrecorded' then raise exception 'Operation permanently closed' using errcode='23514'; end if;
  q:=case when p_mutation->>'kind'='client_decision' then p_mutation->'request' else p_mutation#>'{request,decision}' end;
  pub:=public.native_estdec_current(b,q->'expected_publication_head');
  state:=public.native_estdec_verified_state((b#>>'{target,estimate_id}')::uuid);
  seq:=(state#>>'{head,version}')::integer+1;
  stamp:=clock_timestamp();
  if stamp>=(pub->>'expires_at')::timestamptz then raise exception 'Estimate deadline expired' using errcode='23514'; end if;
  if p_principal->>'kind'='grant' then
    prov:=jsonb_build_object('kind','grant','grant_id',p_principal->'id');
  else
    if (p_mutation#>>'{request,witness,occurred_at}')::timestamptz>stamp or (p_mutation#>>'{request,witness,occurred_at}')::timestamptz<(pub->>'published_at')::timestamptz then
      raise exception 'Witness occurrence outside publication period' using errcode='23514'; end if;
    prov:=jsonb_build_object('kind','staff_witness','actor_id',p_principal->'id','witness',p_mutation#>'{request,witness}');
  end if;
  d:=jsonb_build_object('version',1,'id',p_id,'sequence',seq,'binding',b,'choice',q->'choice','signer_name',q->'signer_name',
    'signer_relationship',q->'signer_relationship','comment',q->'comment','acknowledgment_version',1,'provenance',prov,
    'publication_head',q->'expected_publication_head','decision_head',state->'head','recorded_at',public.native_estdec_time(stamp));
  d:=d||jsonb_build_object('record_hash',public.native_fulfillment_hash(d));
  rh:=public.native_estdec_request_hash('decision',p_principal,p_mutation);
  receipt:=jsonb_build_object('version',1,'id',p_id,'principal',p_principal,'mutation',p_mutation,'request_hash',rh,'result',d,'created_at',public.native_estdec_time(stamp));
  perform public.native_estdec_authorize(p_principal,p_proof,true);
  insert into public.native_estimate_decisions values(p_id,(b#>>'{target,estimate_id}')::uuid,(b->>'publication_id')::uuid,seq,p_principal,rh,d,stamp);
  insert into public.native_estimate_decision_operations values(p_id,'decision',p_principal,p_mutation,rh,receipt,stamp);
  return public.native_estdec_verified_operation(p_id);
end $$

create function public.record_native_estimate_witnessed_decision(p_id uuid,p_request jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();
begin
  return public.native_estdec_record(p_id,jsonb_build_object('kind','witnessed_decision','request',p_request),jsonb_build_object('kind','staff','id',actor),null);
