create or replace function public.cancel_appointment(
  p_id uuid,
  p_expected_version integer
)
returns public.appointments
language plpgsql
security definer
set search_path = public
as $$
declare
  result public.appointments;
  actor uuid;
begin
  actor := public.appointment_require_staff();

  if p_expected_version is null then
    raise exception 'Expected appointment version is required' using errcode = '23514';
  end if;

  update public.appointments
  set status = 'CANCELLED'::public.appointment_status,
    updated_by = actor
  where id = p_id
    and version = p_expected_version
  returning * into result;

  if not found then
    raise exception 'Appointment changed or no longer exists; reload before cancelling' using errcode = '40001';
  end if;

  return result;
end
$$

create or replace function public.record_outbound_delivery_result(
  p_delivery_id uuid,
  p_lease_owner text,
  p_status public.outbound_delivery_status,
  p_provider text default null,
  p_provider_message_id text default null,
  p_status_note text default null,
  p_error_text text default null,
  p_next_attempt_at timestamptz default null,
  p_recorded_at timestamptz default now()
)
returns public.outbound_deliveries
language plpgsql
set search_path = public
as $$
declare
  normalized_lease_owner text := nullif(btrim(p_lease_owner), '');
  normalized_provider text := nullif(btrim(coalesce(p_provider, '')), '');
  normalized_provider_message_id text := nullif(btrim(coalesce(p_provider_message_id, '')), '');
  normalized_note text := nullif(btrim(coalesce(p_status_note, '')), '');
  normalized_error text := nullif(btrim(coalesce(p_error_text, '')), '');
  result public.outbound_deliveries;
begin
  if p_delivery_id is null then
    raise exception 'Delivery id is required' using errcode = '23514';
  end if;

  if normalized_lease_owner is null or length(normalized_lease_owner) > 128 then
    raise exception 'Lease owner is required' using errcode = '23514';
  end if;

  if p_recorded_at is null then
    raise exception 'Result timestamp is required' using errcode = '23514';
  end if;

  if p_status not in (
    'QUEUED'::public.outbound_delivery_status,
    'ACCEPTED'::public.outbound_delivery_status,
    'DELIVERED'::public.outbound_delivery_status,
    'FAILED'::public.outbound_delivery_status,
    'UNKNOWN'::public.outbound_delivery_status
  ) then
    raise exception 'Unsupported outbound delivery result status' using errcode = '23514';
  end if;

  if p_status = 'QUEUED'::public.outbound_delivery_status then
    if p_next_attempt_at is null or p_next_attempt_at <= p_recorded_at then
      raise exception 'Retry results require a future next attempt timestamp' using errcode = '23514';
    end if;
  elsif p_next_attempt_at is not null then
    raise exception 'Terminal delivery results cannot set a retry timestamp' using errcode = '23514';
  end if;

  update public.outbound_deliveries od
  set status = p_status,
    provider = coalesce(normalized_provider, od.provider),
    provider_message_id = coalesce(normalized_provider_message_id, od.provider_message_id),
    status_note = normalized_note,
    last_error_text = normalized_error,
    next_attempt_at = case
      when p_status = 'QUEUED'::public.outbound_delivery_status then p_next_attempt_at
      else od.next_attempt_at
    end,
    leased_at = null,
    leased_until = null,
    lease_owner = null,
    accepted_at = case when p_status = 'ACCEPTED'::public.outbound_delivery_status then p_recorded_at else od.accepted_at end,
    delivered_at = case when p_status = 'DELIVERED'::public.outbound_delivery_status then p_recorded_at else od.delivered_at end,
    failed_at = case when p_status = 'FAILED'::public.outbound_delivery_status then p_recorded_at else od.failed_at end,
    unknown_at = case when p_status = 'UNKNOWN'::public.outbound_delivery_status then p_recorded_at else od.unknown_at end
  where od.id = p_delivery_id
    and od.status = 'LEASED'::public.outbound_delivery_status
    and od.lease_owner = normalized_lease_owner
    and od.leased_until > p_recorded_at
    and (
      p_status <> 'QUEUED'::public.outbound_delivery_status
      or od.attempt_count < od.max_attempts
    )
  returning od.* into result;

  if not found then
    raise exception 'Outbound delivery is not actively leased to this worker' using errcode = '40001';
  end if;

  if result.appointment_reminder_id is not null then
    update public.appointment_reminders ar
    set status = case
        when p_status in ('ACCEPTED'::public.outbound_delivery_status, 'DELIVERED'::public.outbound_delivery_status) then 'SENT'::public.reminder_status
        when p_status in ('FAILED'::public.outbound_delivery_status, 'UNKNOWN'::public.outbound_delivery_status) then 'FAILED'::public.reminder_status
        else ar.status
      end,
      sent_at = case
        when p_status in ('ACCEPTED'::public.outbound_delivery_status, 'DELIVERED'::public.outbound_delivery_status) then p_recorded_at
        else ar.sent_at
      end,
      error_message = case
        when p_status in ('FAILED'::public.outbound_delivery_status, 'UNKNOWN'::public.outbound_delivery_status) then coalesce(normalized_error, normalized_note, 'Outbound delivery did not complete')
        when p_status in ('ACCEPTED'::public.outbound_delivery_status, 'DELIVERED'::public.outbound_delivery_status) then null
        else ar.error_message
      end
    where ar.id = result.appointment_reminder_id;
  end if;

  return result;
end
$$

create or replace function public.record_outbound_delivery_callback(
  p_provider text,
  p_provider_message_id text,
  p_status public.outbound_delivery_status,
  p_status_note text default null,
  p_error_text text default null,
  p_recorded_at timestamptz default now()
)
returns public.outbound_deliveries
language plpgsql
set search_path = public
as $$
declare
  normalized_provider text := nullif(btrim(coalesce(p_provider, '')), '');
  normalized_provider_message_id text := nullif(btrim(coalesce(p_provider_message_id, '')), '');
  normalized_note text := nullif(btrim(coalesce(p_status_note, '')), '');
  normalized_error text := nullif(btrim(coalesce(p_error_text, '')), '');
  result public.outbound_deliveries;
begin
  if normalized_provider is null or length(normalized_provider) > 128 then
    raise exception 'Provider is required' using errcode = '23514';
  end if;

  if normalized_provider_message_id is null or length(normalized_provider_message_id) > 256 then
    raise exception 'Provider message id is required' using errcode = '23514';
  end if;

  if p_recorded_at is null then
    raise exception 'Callback timestamp is required' using errcode = '23514';
  end if;

  if p_status not in (
    'DELIVERED'::public.outbound_delivery_status,
    'FAILED'::public.outbound_delivery_status,
    'UNKNOWN'::public.outbound_delivery_status
  ) then
    raise exception 'Unsupported outbound delivery callback status' using errcode = '23514';
  end if;

  update public.outbound_deliveries od
  set status = p_status,
    status_note = normalized_note,
    last_error_text = normalized_error,
    delivered_at = case
      when p_status = 'DELIVERED'::public.outbound_delivery_status then coalesce(od.delivered_at, p_recorded_at)
      else od.delivered_at
    end,
    failed_at = case
      when p_status = 'FAILED'::public.outbound_delivery_status then coalesce(od.failed_at, p_recorded_at)
      else od.failed_at
    end,
    unknown_at = case
      when p_status = 'UNKNOWN'::public.outbound_delivery_status then coalesce(od.unknown_at, p_recorded_at)
      else od.unknown_at
    end
  where od.provider = normalized_provider
    and od.provider_message_id = normalized_provider_message_id
    and (
      od.status in ('ACCEPTED'::public.outbound_delivery_status, 'UNKNOWN'::public.outbound_delivery_status)
      or od.status = p_status
    )
  returning od.* into result;

  if not found then
    raise exception 'Outbound delivery is not callback-eligible' using errcode = '40001';
  end if;

  if result.appointment_reminder_id is not null then
    update public.appointment_reminders ar
    set status = case
        when p_status = 'DELIVERED'::public.outbound_delivery_status then 'SENT'::public.reminder_status
        when p_status in ('FAILED'::public.outbound_delivery_status, 'UNKNOWN'::public.outbound_delivery_status) then 'FAILED'::public.reminder_status
        else ar.status
      end,
      sent_at = case
        when p_status = 'DELIVERED'::public.outbound_delivery_status then coalesce(ar.sent_at, p_recorded_at)
        else ar.sent_at
      end,
      error_message = case
        when p_status in ('FAILED'::public.outbound_delivery_status, 'UNKNOWN'::public.outbound_delivery_status) then coalesce(normalized_error, normalized_note, 'Outbound delivery callback did not confirm delivery')
        when p_status = 'DELIVERED'::public.outbound_delivery_status then null
        else ar.error_message
      end
    where ar.id = result.appointment_reminder_id;
  end if;

  return result;
end
$$

create or replace function public.record_inbound_sms(
  p_from text,
  p_to text,
  p_body text,
  p_provider_message_id text,
  p_opt_out_type text default null,
  p_received_at timestamptz default now()
)
returns table (
  client_id uuid,
  conversation_id uuid,
  message_id uuid,
  consent_action text
)
language plpgsql
set search_path = public
as $$
declare
  normalized_from text := public.normalize_sms_phone(p_from);
  normalized_to text := public.normalize_sms_phone(p_to);
  normalized_body text := nullif(btrim(coalesce(p_body, '')), '');
  normalized_provider_message_id text := nullif(btrim(coalesce(p_provider_message_id, '')), '');
  normalized_opt_out_type text := upper(nullif(btrim(coalesce(p_opt_out_type, '')), ''));
  keyword text;
  selected_client_id uuid;
  selected_conversation_id uuid;
  selected_message_id uuid;
  selected_consent_action text := 'NONE';
begin
  if normalized_from is null then
    raise exception 'Inbound SMS sender phone is invalid' using errcode = '23514';
  end if;

  if normalized_to is null then
    raise exception 'Inbound SMS recipient phone is invalid' using errcode = '23514';
  end if;

  if normalized_body is null or length(normalized_body) > 1600 then
    raise exception 'Inbound SMS body must be between 1 and 1600 characters' using errcode = '23514';
  end if;

  if normalized_provider_message_id is null or length(normalized_provider_message_id) > 256 then
    raise exception 'Inbound SMS provider message id is required' using errcode = '23514';
  end if;

  select m.id, c.id, c.client_id
  into selected_message_id, selected_conversation_id, selected_client_id
  from public.messages m
  join public.conversations c on c.id = m.conversation_id
  where m.provider = 'twilio'
    and m.provider_message_id = normalized_provider_message_id
  limit 1;

  if selected_message_id is not null then
    client_id := selected_client_id;
    conversation_id := selected_conversation_id;
    message_id := selected_message_id;
    consent_action := 'DUPLICATE';
    return next;
    return;
  end if;

  select c.id
  into selected_client_id
  from public.clients c
  where public.normalize_sms_phone(c.primary_phone) = normalized_from
  order by c.created_at, c.id
  limit 1;

  if selected_client_id is null then
    insert into public.clients (
      first_name,
      last_name,
      full_name,
      primary_phone,
      preferred_channel
    )
    values (
      'Unknown',
      right(normalized_from, 4),
      'Unknown SMS ' || normalized_from,
      normalized_from,
      'SMS'::public.channel_type
    )
    returning id into selected_client_id;
  end if;

  keyword := upper(regexp_replace(normalized_body, '\s+', ' ', 'g'));
  if normalized_opt_out_type is null then
    if keyword in ('STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT', 'REVOKE') then
      normalized_opt_out_type := 'STOP';
    elsif keyword in ('START', 'YES', 'UNSTOP') then
      normalized_opt_out_type := 'START';
    elsif keyword in ('HELP', 'INFO') then
      normalized_opt_out_type := 'HELP';
    end if;
  end if;

  if normalized_opt_out_type = 'STOP' then
    insert into public.sms_consent (
      client_id,
      phone_number,
      opted_in,
      opted_out_at,
      consent_method,
      consent_details
    )
    values (
      selected_client_id,
      normalized_from,
      false,
      p_received_at,
      'SMS_KEYWORD'::public.consent_method,
      'Twilio inbound opt-out keyword'
    )
    on conflict on constraint sms_consent_client_phone_unique do update
      set opted_in = false,
        opted_out_at = excluded.opted_out_at,
        consent_method = excluded.consent_method,
        consent_details = excluded.consent_details,
        updated_at = now();
    selected_consent_action := 'OPTED_OUT';
  elsif normalized_opt_out_type = 'START' then
    insert into public.sms_consent (
      client_id,
      phone_number,
      opted_in,
      opted_in_at,
      opted_out_at,
      consent_method,
      consent_details
    )
    values (
      selected_client_id,
      normalized_from,
      true,
      p_received_at,
      null,
      'SMS_KEYWORD'::public.consent_method,
      'Twilio inbound opt-in keyword'
    )
    on conflict on constraint sms_consent_client_phone_unique do update
      set opted_in = true,
        opted_in_at = excluded.opted_in_at,
        opted_out_at = null,
        consent_method = excluded.consent_method,
        consent_details = excluded.consent_details,
        updated_at = now();
    selected_consent_action := 'OPTED_IN';
  elsif normalized_opt_out_type = 'HELP' then
    selected_consent_action := 'HELP';
  end if;

  select c.id
  into selected_conversation_id
  from public.conversations c
  where c.client_id = selected_client_id
    and c.status = 'ACTIVE'::public.conversation_status
  order by c.last_message_at desc, c.created_at desc, c.id
  limit 1;

  if selected_conversation_id is null then
    insert into public.conversations (
      client_id,
      status,
      priority,
      first_message_at,
      last_message_at,
      is_read
    )
    values (
      selected_client_id,
      'ACTIVE'::public.conversation_status,
      'NORMAL'::public.conversation_priority,
      p_received_at,
      p_received_at,
      false
    )
    returning id into selected_conversation_id;
  end if;

  insert into public.messages (
    conversation_id,
    type,
    sender_type,
    content,
    is_internal,
    provider,
    provider_message_id,
    created_at
  )
  values (
    selected_conversation_id,
    'SMS'::public.message_type,
    'CLIENT'::public.sender_type,
    normalized_body,
    false,
    'twilio',
    normalized_provider_message_id,
    p_received_at
  )
  returning id into selected_message_id;

  update public.conversations c
  set last_message_at = p_received_at,
    first_message_at = coalesce(c.first_message_at, p_received_at),
    is_read = false,
    status = 'ACTIVE'::public.conversation_status
  where c.id = selected_conversation_id;

  client_id := selected_client_id;
  conversation_id := selected_conversation_id;
  message_id := selected_message_id;
  consent_action := selected_consent_action;
  return next;
end
$$

create or replace function public.enqueue_staff_outbound_message(
  p_actor_id uuid,
  p_conversation_id uuid,
  p_channel public.channel_type,
  p_recipient text,
  p_subject text default null,
  p_body text default null,
  p_requested_at timestamptz default now(),
  p_idempotency_key text default null
)
returns table (
  message_id uuid,
  outbound_delivery_id uuid,
  enqueue_status text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  normalized_recipient text := nullif(btrim(coalesce(p_recipient, '')), '');
  normalized_subject text := nullif(btrim(coalesce(p_subject, '')), '');
  normalized_body text := nullif(btrim(coalesce(p_body, '')), '');
  normalized_idempotency_key text := nullif(btrim(coalesce(p_idempotency_key, '')), '');
  selected_client_id uuid;
  selected_message_id uuid;
  selected_delivery_id uuid;
  selected_status text := 'QUEUED';
begin
  if p_actor_id is null or not public.is_active_staff(p_actor_id) then
    raise exception 'Active staff access required' using errcode = '42501';
  end if;

  if p_conversation_id is null then
    raise exception 'Conversation is required' using errcode = '23514';
  end if;

  if p_requested_at is null then
    raise exception 'Request timestamp is required' using errcode = '23514';
  end if;

  if p_channel not in ('EMAIL'::public.channel_type, 'SMS'::public.channel_type) then
    raise exception 'Outbound channel must be EMAIL or SMS' using errcode = '23514';
  end if;

  if normalized_body is null
    or (p_channel = 'SMS'::public.channel_type and length(normalized_body) > 1600)
    or (p_channel = 'EMAIL'::public.channel_type and length(normalized_body) > 100000)
  then
    raise exception 'Message body is invalid for this channel' using errcode = '23514';
  end if;

  if normalized_idempotency_key is not null and length(normalized_idempotency_key) > 256 then
    raise exception 'Idempotency key is too long' using errcode = '23514';
  end if;

  if p_channel = 'EMAIL'::public.channel_type and (normalized_subject is null or length(normalized_subject) > 500) then
    raise exception 'Email subject is required' using errcode = '23514';
  end if;

  select c.client_id
  into selected_client_id
  from public.conversations c
  where c.id = p_conversation_id;

  if selected_client_id is null then
    raise exception 'Conversation not found' using errcode = '23514';
  end if;

  if normalized_idempotency_key is not null then
    select od.message_id, od.id
    into selected_message_id, selected_delivery_id
    from public.outbound_deliveries od
    where od.channel = p_channel
      and od.idempotency_key = normalized_idempotency_key
    limit 1;

    if selected_delivery_id is not null then
      if not exists (
        select 1
        from public.outbound_deliveries od
        where od.id = selected_delivery_id
          and od.requested_by = p_actor_id
          and od.conversation_id = p_conversation_id
          and od.client_id = selected_client_id
      ) then
        raise exception 'Idempotency key was already used for a different outbound message' using errcode = '23514';
      end if;

      message_id := selected_message_id;
      outbound_delivery_id := selected_delivery_id;
      enqueue_status := 'DUPLICATE';
      return next;
      return;
    end if;
  end if;

  if p_channel = 'EMAIL'::public.channel_type then
    if normalized_recipient is null
      or normalized_recipient !~* '^[a-z0-9.!#$%&''*+/=?^_`{|}~-]+@[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$'
      or exists (select 1 where lower(normalized_recipient) like '.%' or lower(normalized_recipient) like '%.@%' or lower(normalized_recipient) like '%..%')
    then
      raise exception 'Email recipient is invalid' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.clients cl
      where cl.id = selected_client_id
        and lower(btrim(coalesce(cl.primary_email, ''))) = lower(normalized_recipient)
    ) then
      raise exception 'Recipient does not match the conversation client' using errcode = '42501';
    end if;
  else
    normalized_recipient := public.normalize_sms_phone(normalized_recipient);
    if normalized_recipient is null then
      raise exception 'SMS recipient is invalid' using errcode = '23514';
    end if;

    if not exists (
      select 1
      from public.clients cl
      where cl.id = selected_client_id
        and public.normalize_sms_phone(cl.primary_phone) = normalized_recipient
    ) then
      raise exception 'Recipient does not match the conversation client' using errcode = '42501';
    end if;

    if not exists (
      select 1
      from public.sms_consent sc
      where sc.client_id = selected_client_id
        and public.normalize_sms_phone(sc.phone_number) = normalized_recipient
    ) or exists (
      select 1
      from public.sms_consent sc
      where sc.client_id = selected_client_id
        and public.normalize_sms_phone(sc.phone_number) = normalized_recipient
        and sc.opted_in is not true
    ) then
      raise exception 'No SMS consent on record for this number' using errcode = '42501';
    end if;
  end if;

  insert into public.messages (
    conversation_id,
    type,
    sender_type,
    sender_id,
    content,
    is_internal,
    created_at
  )
  values (
    p_conversation_id,
    p_channel::text::public.message_type,
    'STAFF'::public.sender_type,
    p_actor_id,
    normalized_body,
    false,
    p_requested_at
  )
  returning id into selected_message_id;

  normalized_idempotency_key := coalesce(
    normalized_idempotency_key,
    'staff:' || lower(p_channel::text) || ':' || selected_message_id::text
  );

  insert into public.outbound_deliveries (
    idempotency_key,
    channel,
    recipient,
    payload,
    requested_by,
    client_id,
    conversation_id,
    message_id,
    status,
    status_note,
    scheduled_at,
    next_attempt_at,
    created_at
  )
  values (
    normalized_idempotency_key,
    p_channel,
    normalized_recipient,
    jsonb_strip_nulls(jsonb_build_object(
      'kind', 'staff_message',
      'source', case when p_channel = 'SMS'::public.channel_type then 'send-sms' else 'send-email' end,
      'subject', normalized_subject,
      'body', normalized_body
    )),
    p_actor_id,
    selected_client_id,
    p_conversation_id,
    selected_message_id,
    'QUEUED'::public.outbound_delivery_status,
    'Queued for outbound delivery dispatcher',
    p_requested_at,
    p_requested_at,
    p_requested_at
  )
  returning id into selected_delivery_id;

  update public.conversations c
  set last_message_at = p_requested_at,
    first_message_at = coalesce(c.first_message_at, p_requested_at),
    is_read = true,
    status = 'ACTIVE'::public.conversation_status
  where c.id = p_conversation_id;

  message_id := selected_message_id;
  outbound_delivery_id := selected_delivery_id;
  enqueue_status := selected_status;
  return next;
end
$$

create or replace function public.cancel_outbound_delivery(
  p_delivery_id uuid,
  p_expected_updated_at timestamptz default null,
  p_requested_at timestamptz default now()
)
returns public.outbound_deliveries
language plpgsql
security definer
set search_path = public
as $$
declare
  actor_id uuid := auth.uid();
  result public.outbound_deliveries;
begin
  if actor_id is null or not public.is_active_staff(actor_id) then
    raise exception 'Active staff access required' using errcode = '42501';
  end if;

  if p_delivery_id is null then
    raise exception 'Delivery id is required' using errcode = '23514';
  end if;

  if p_requested_at is null then
    raise exception 'Cancel timestamp is required' using errcode = '23514';
  end if;

  update public.outbound_deliveries od
  set status = 'CANCELED'::public.outbound_delivery_status,
    status_note = 'Manually canceled by staff',
    last_error_text = null,
    next_attempt_at = greatest(od.next_attempt_at, p_requested_at),
    leased_at = null,
    leased_until = null,
    lease_owner = null,
    canceled_at = p_requested_at
  where od.id = p_delivery_id
    and od.status in (
      'QUEUED'::public.outbound_delivery_status
    )
    and (
      p_expected_updated_at is null
      or od.updated_at = p_expected_updated_at
    )
  returning od.* into result;

  if not found then
    raise exception 'Outbound delivery is not cancelable' using errcode = '40001';
  end if;

  if result.appointment_reminder_id is not null then
    update public.appointment_reminders ar
    set status = 'SKIPPED'::public.reminder_status,
      error_message = 'Outbound delivery manually canceled by staff'
    where ar.id = result.appointment_reminder_id;
  end if;

  return result;
end
$$

create or replace function public.guard_contact_submission()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  normalized_email text;
  matching_recent_count integer;
begin
  if tg_op = 'DELETE' then
    raise exception 'Original website submissions are immutable' using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
      or new.name is distinct from old.name
      or new.email is distinct from old.email
      or new.phone is distinct from old.phone
      or new.subject is distinct from old.subject
      or new.message is distinct from old.message
      or new.created_at is distinct from old.created_at
    then
      raise exception 'Original website submissions are immutable' using errcode = '23514';
    end if;

    if (new.reviewed_by is not null and new.reviewed_by is distinct from old.reviewed_by and new.reviewed_by is distinct from auth.uid())
      or (new.contacted_by is not null and new.contacted_by is distinct from old.contacted_by and new.contacted_by is distinct from auth.uid())
      or (new.closed_by is not null and new.closed_by is distinct from old.closed_by and new.closed_by is distinct from auth.uid())
    then
      raise exception 'Contact submission triage actor must match authenticated user' using errcode = '23514';
    end if;

    return new;
  end if;

  if length(trim(new.name)) not between 1 and 100
    or length(new.email) not between 3 and 255
    or new.email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
    or coalesce(length(new.phone), 0) > 20
    or length(trim(new.subject)) not between 1 and 200
    or length(trim(new.message)) not between 1 and 2000
  then
    raise exception 'Invalid website contact fields' using errcode = '23514';
  end if;

  normalized_email := lower(btrim(new.email));

  select count(*)
  into matching_recent_count
  from public.contact_submissions cs
  where lower(btrim(cs.email)) = normalized_email
    and cs.created_at >= now() - interval '24 hours';

  if matching_recent_count >= 3 then
    raise exception 'Too many contact submissions from this email address; please try again later'
      using errcode = '23514';
  end if;

  if exists (
    select 1
    from public.contact_submissions cs
    where lower(btrim(cs.email)) = normalized_email
      and lower(btrim(cs.subject)) = lower(btrim(new.subject))
      and lower(btrim(cs.message)) = lower(btrim(new.message))
      and cs.created_at >= now() - interval '15 minutes'
  ) then
    raise exception 'Duplicate contact submission received too recently; please try again later'
      using errcode = '23514';
  end if;

  return new;
end
$$

-- Keep every appointment write on the housecall-aware contract.
-- Earlier launch-readiness migrations briefly reintroduced a slim appointment
-- RPC and a default reminder trigger. Those bypassed visit/travel/reminder
-- fields and conflicted with the revisioned reminder uniqueness contract.

create or replace function public.guard_appointment_write()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  actor uuid := auth.uid();
  patient record;
begin
  if tg_op = 'DELETE' then
    raise exception 'Appointments cannot be deleted; cancel them instead' using errcode = '23514';
  end if;

  if actor is not null and not public.is_active_staff(actor) then
    raise exception 'Active staff access required' using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' then
    if new.id is distinct from old.id
      or new.created_at is distinct from old.created_at
      or new.created_by is distinct from old.created_by
    then
      raise exception 'Appointment identity and creation metadata are immutable' using errcode = '23514';
    end if;

    if old.status in ('CANCELLED'::public.appointment_status, 'COMPLETED'::public.appointment_status, 'NO_SHOW'::public.appointment_status)
      and new.status in ('SCHEDULED'::public.appointment_status, 'CONFIRMED'::public.appointment_status)
    then
      raise exception 'Closed appointments cannot be reactivated; create a new appointment' using errcode = '23514';
    end if;
  end if;

  if new.duration_minutes is null or new.duration_minutes < 15 or new.duration_minutes > 480 then
    raise exception 'Appointment duration must be between 15 and 480 minutes' using errcode = '23514';
  end if;

  if nullif(btrim(coalesce(new.appointment_type, '')), '') is null
    or length(btrim(new.appointment_type)) > 160
  then
    raise exception 'Appointment type is required' using errcode = '23514';
  end if;

  new.appointment_type := btrim(new.appointment_type);
  new.notes := nullif(btrim(coalesce(new.notes, '')), '');

  if new.notes is not null and length(new.notes) > 10000 then
    raise exception 'Appointment notes are too long' using errcode = '23514';
  end if;

  if new.pet_id is not null then
    select p.client_id, p.archived_at, p.deceased_at
    into patient
    from public.pets p
    where p.id = new.pet_id;

    if not found then
      raise exception 'Appointment patient does not exist' using errcode = '23503';
    end if;

    if patient.client_id is distinct from new.client_id then
      raise exception 'Appointment patient must belong to the selected client' using errcode = '23514';
    end if;

    if actor is not null
      and new.status in ('SCHEDULED'::public.appointment_status, 'CONFIRMED'::public.appointment_status)
      and patient.archived_at is not null
    then
      raise exception 'Archived patients cannot be scheduled' using errcode = '23514';
    end if;

    if actor is not null
      and new.status in ('SCHEDULED'::public.appointment_status, 'CONFIRMED'::public.appointment_status)
      and patient.deceased_at is not null
    then
      raise exception 'Deceased patients cannot be scheduled' using errcode = '23514';
    end if;
  end if;

  if actor is not null and new.assigned_dvm_id is not null and not public.is_active_staff(new.assigned_dvm_id) then
    raise exception 'Assigned clinician must be active staff' using errcode = '23514';
  end if;

  if tg_op = 'INSERT' then
    new.version := 1;
    if actor is not null then
      new.created_by := actor;
      new.updated_by := actor;
    end if;
  else
    if new.version is null or new.version <= old.version then
      new.version := old.version + 1;
    elsif new.version <> old.version + 1 then
      raise exception 'Appointment version increments must be sequential' using errcode = '23514';
    end if;

    if actor is not null then
      new.updated_by := actor;
    end if;
  end if;

  return new;
end
$$

create function public.ingest_cloudtalk_event(
  p_event_id text, p_event_type text, p_occurred_at timestamptz, p_data jsonb
) returns boolean language plpgsql security definer set search_path = public as $$
declare
  call_key text;
  number_internal text;
  number_external text;
  message_key text;
begin
  perform public.communication_require_service();
  if p_event_id is null or length(p_event_id) not between 1 and 200
    or p_event_type not in ('call.ended', 'call.recording_ready', 'transcript.ready', 'cidata.ready', 'message.sent', 'message.received')
    or p_occurred_at is null or p_occurred_at > now() + interval '5 minutes'
    or p_data is null or jsonb_typeof(p_data) <> 'object'
    or octet_length(p_data::text) > 262144 then
    raise exception 'Invalid CloudTalk event' using errcode = '23514';
  end if;
  insert into public.cloudtalk_events(event_id, event_type, occurred_at)
  values(p_event_id, p_event_type, p_occurred_at) on conflict do nothing;
  if not found then return false; end if;

  if p_event_type like 'call.%' or p_event_type in ('transcript.ready', 'cidata.ready') then
    call_key := p_data->>'call_uuid';
    if call_key is null or length(call_key) not between 1 and 200 then
      raise exception 'Invalid CloudTalk call' using errcode = '23514';
    end if;
    number_external := p_data->>'external_number';
    number_internal := p_data#>>'{internal_number,number_e164}';
    insert into public.cloudtalk_calls(
      call_uuid, call_id, direction, external_number, internal_number,
      started_at, ended_at, duration_seconds, is_voicemail, recording_ready,
      transcript_ready, ai_summary, ai_language, trusted_number, last_event_at
    ) values (
      call_key, p_data->>'call_id', p_data->>'direction', number_external, number_internal,
      nullif(p_data->>'started_at', '')::timestamptz,
      nullif(p_data->>'ended_at', '')::timestamptz,
      case when (p_data->>'duration') ~ '^[0-9]{1,8}$' then (p_data->>'duration')::integer end,
      coalesce((p_data->>'is_voicemail')::boolean, false),
      p_event_type = 'call.recording_ready',
      p_event_type = 'transcript.ready',
      case when p_event_type = 'cidata.ready' then left(p_data#>>'{summary,summary}', 10000) end,
      case when p_event_type in ('transcript.ready', 'cidata.ready') then left(p_data->>'language', 20) end,
      p_event_type = 'call.ended',
      p_occurred_at
    ) on conflict(call_uuid) do update set
      call_id = coalesce(excluded.call_id, cloudtalk_calls.call_id),
      direction = coalesce(excluded.direction, cloudtalk_calls.direction),
      external_number = coalesce(excluded.external_number, cloudtalk_calls.external_number),
      internal_number = coalesce(excluded.internal_number, cloudtalk_calls.internal_number),
      started_at = coalesce(excluded.started_at, cloudtalk_calls.started_at),
      ended_at = coalesce(excluded.ended_at, cloudtalk_calls.ended_at),
      duration_seconds = coalesce(excluded.duration_seconds, cloudtalk_calls.duration_seconds),
      is_voicemail = excluded.is_voicemail or cloudtalk_calls.is_voicemail,
      recording_ready = excluded.recording_ready or cloudtalk_calls.recording_ready,
      transcript_ready = excluded.transcript_ready or cloudtalk_calls.transcript_ready,
      ai_summary = coalesce(excluded.ai_summary, cloudtalk_calls.ai_summary),
      ai_language = coalesce(excluded.ai_language, cloudtalk_calls.ai_language),
      trusted_number = excluded.trusted_number or cloudtalk_calls.trusted_number,
      last_event_at = greatest(excluded.last_event_at, cloudtalk_calls.last_event_at);
  else
    message_key := p_data->>'id';
    number_external := p_data->>'external_number';
    number_internal := p_data#>>'{internal_number,number_e164}';
    if message_key is null or length(message_key) not between 1 and 200
      or public.communication_recipient('SMS', number_external) is null
      or public.communication_recipient('SMS', number_internal) is null
      or p_data->>'channel' not in ('sms', 'mms', 'whatsapp')
      or length(coalesce(p_data->>'body', '')) > 100000 then
      raise exception 'Invalid CloudTalk message' using errcode = '23514';
    end if;
    insert into public.cloudtalk_messages(
      message_id, direction, channel, external_number, internal_number, body, occurred_at
    ) values (
      message_key, case when p_event_type = 'message.received' then 'inbound' else 'outbound' end,
      p_data->>'channel', number_external, number_internal, coalesce(p_data->>'body', ''), p_occurred_at
    ) on conflict(message_id) do nothing;
    -- A signed inbound STOP blocks any future SMS request, including one
    -- queued before the message arrived. Re-enabling requires staff review.
    if p_event_type = 'message.received' and p_data->>'channel' = 'sms' and upper(btrim(coalesce(p_data->>'body', ''))) in ('STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT') then
      insert into public.communication_suppressions(channel, recipient, reason)
      values ('SMS', public.communication_recipient('SMS', number_external), 'cloudtalk_sms_stop')
      on conflict (channel, recipient) do nothing;
      update public.sms_consent set opted_in = false, opted_out_at = greatest(coalesce(opted_out_at, p_occurred_at), p_occurred_at)
      where public.communication_recipient('SMS', phone_number) = public.communication_recipient('SMS', number_external);
      update public.communication_outbox set state = 'failed', last_error = 'recipient_suppressed', updated_at = now()
      where channel = 'SMS' and recipient = public.communication_recipient('SMS', number_external) and state = 'pending';
      update public.outbound_deliveries set status = 'CANCELED', canceled_at = now(), updated_at = now(), status_note = 'Recipient sent STOP to CloudTalk'
      where channel = 'SMS' and recipient = public.communication_recipient('SMS', number_external) and status = 'QUEUED';
    end if;
  end if;
  return true;
end $$

-- sms_consent joins the exact-replay payload. A payload without it (an edge
-- function deployed before this migration, or a receipt stored before it) is
-- normalized to sms_consent=false on both sides of the replay comparison.
create or replace function public.accept_contact_intake(p_request_id uuid,p_capability_hash text,p_email_budget_hash text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare prior public.contact_intake_requests;submission uuid;attempt_count integer;body jsonb;consent boolean;
begin
 if p_request_id is null or p_capability_hash is null or p_capability_hash !~ '^[a-f0-9]{64}$' or p_email_budget_hash is null or p_email_budget_hash !~ '^[a-f0-9]{64}$' or p_payload is null or jsonb_typeof(p_payload)<>'object' or p_payload-array['name','email','phone','subject','message','sms_consent']<>'{}'::jsonb or not(p_payload ?& array['name','email','phone','subject','message']) then raise exception 'Invalid intake payload' using errcode='23514';end if;
 body:=p_payload||jsonb_build_object('sms_consent',coalesce(p_payload->'sms_consent','false'::jsonb));
 if jsonb_typeof(body->'name')<>'string' or jsonb_typeof(body->'email')<>'string' or jsonb_typeof(body->'subject')<>'string' or jsonb_typeof(body->'message')<>'string' or jsonb_typeof(body->'phone') not in ('string','null') or jsonb_typeof(body->'sms_consent')<>'boolean' then raise exception 'Invalid intake field types' using errcode='23514';end if;
 consent:=(body->>'sms_consent')::boolean;
 if consent and coalesce(btrim(body->>'phone'),'')='' then raise exception 'Text message consent requires a phone number' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('contact-intake:'||p_request_id::text,0));
 select * into prior from contact_intake_requests where request_id=p_request_id;
 if found then
  if prior.capability_hash<>p_capability_hash or (prior.payload||jsonb_build_object('sms_consent',coalesce(prior.payload->'sms_consent','false'::jsonb)))<>body then raise exception 'Request ID already used with different content or proof' using errcode='23505';end if;
  return jsonb_build_object('received',true);
 end if;
 -- Claimed email is an abuse bucket, never sender authentication or consent.
 insert into contact_intake_budgets values('email:'||p_email_budget_hash,date_trunc('hour',now()),1) on conflict(bucket,window_start) do update set attempts=least(contact_intake_budgets.attempts+1,1000000) returning attempts into attempt_count;
 if attempt_count>5 then return jsonb_build_object('received',false,'limited',true);end if;
 insert into contact_submissions(name,email,phone,subject,message,sms_consent,sms_consent_text,sms_consent_at) values(body->>'name',body->>'email',body->>'phone',body->>'subject',body->>'message',consent,case when consent then contact_sms_consent_disclosure() end,case when consent then now() end) returning id into submission;
 insert into contact_intake_requests(request_id,capability_hash,payload,submission_id) values(p_request_id,p_capability_hash,body,submission);
 return jsonb_build_object('received',true);
end $$

do $$ declare f record;begin
 for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname='accept_contact_intake' loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $$

create function public.communication_sms_provider() returns text language plpgsql stable security definer set search_path=public as $$
declare result text;
begin
 select provider into result from public.communication_sms_provider_setting where singleton;
 if result is null then raise exception 'SMS provider is not configured' using errcode='55000'; end if;
 return result;
end $$

-- Final pre-request check. Unchanged from 20260913020000_communications_outbox.sql
-- except that a CloudTalk row must carry exactly {from, provider:'cloudtalk'},
-- with an E.164 practice sender, and must match the current SMS provider setting.
create or replace function public.start_communication_attempt_without_reminder_guard(p_id uuid,p_lease_token uuid,p_provider_config jsonb) returns public.communication_outbox language plpgsql security definer set search_path=public as $$
declare result public.communication_outbox;
begin
 perform public.communication_require_service();
 select * into result from public.communication_outbox where id=p_id for update;
 if not found or result.state<>'claimed' or result.lease_token is distinct from p_lease_token or result.lease_expires_at<=now() or result.attempt_started_at is not null then raise exception 'Outbox lease is unavailable' using errcode='40001'; end if;
 -- Re-check immediately before the external request, including actor revocation and contact changes.
 if not public.is_active_staff(result.created_by) or public.communication_is_suppressed(result.channel,result.recipient,result.client_id)
 or not exists(select 1 from public.clients c where c.id=result.client_id and public.communication_recipient(result.channel,case when result.channel='EMAIL' then c.primary_email else c.primary_phone end)=result.recipient) then
  update public.communication_outbox set state='failed',last_error='recipient_or_actor_ineligible',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into result;
  return result;
 end if;
 if result.channel='SMS' and result.provider is distinct from public.communication_sms_provider() then
  update public.communication_outbox set state='failed',last_error='sms_provider_mismatch',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into result;
  return result;
 end if;
 if p_provider_config is null or jsonb_typeof(p_provider_config)<>'object' or (result.provider='resend' and (not(p_provider_config ?& array['from','reply_to']) or p_provider_config-array['from','reply_to']<>'{}'::jsonb)) or (result.provider='twilio' and (not(p_provider_config ?& array['from','account_sid']) or p_provider_config-array['from','account_sid']<>'{}'::jsonb))
 or (result.provider='cloudtalk' and (not(p_provider_config ?& array['from','provider']) or p_provider_config-array['from','provider']<>'{}'::jsonb or p_provider_config->>'provider'<>'cloudtalk' or jsonb_typeof(p_provider_config->'from')<>'string' or public.communication_recipient('SMS',p_provider_config->>'from') is distinct from p_provider_config->>'from')) then raise exception 'Invalid provider metadata' using errcode='23514'; end if;
 if result.provider_config is not null and result.provider_config<>p_provider_config then raise exception 'Provider sender metadata changed; reconcile before sending' using errcode='23514'; end if;
 if result.first_attempt_at is not null and result.provider='resend' and result.first_attempt_at<=now()-interval '23 hours' then
  update public.communication_outbox set state='uncertain',last_error='idempotency_window_expired',lease_token=null,lease_expires_at=null,updated_at=now() where id=p_id returning * into result; return result;
 end if;
 update public.communication_outbox set provider_config=coalesce(provider_config,p_provider_config),first_attempt_at=coalesce(first_attempt_at,now()),attempt_started_at=now(),attempt_count=attempt_count+1,updated_at=now() where id=p_id returning * into result;
 insert into public.communication_attempts(outbox_id,lease_token,attempt_number) values(result.id,p_lease_token,result.attempt_count);
 return result;
end $$

-- Unchanged from 20260913370000_payment_link_delivery.sql except the SMS sender
-- shape: CloudTalk {from, provider:'cloudtalk'} or Twilio {from, account_sid},
-- whichever the SMS provider setting selects.
create or replace function public.capture_payment_delivery(p_request_id uuid,p_actor_id uuid,p_sender_config jsonb,p_message_hash text,p_payload_hash text) returns void language plpgsql security definer set search_path=public as $$
declare r public.payment_delivery_requests;p public.payment_delivery_captures;context jsonb;
begin perform public.communication_require_service();
 select * into r from public.payment_delivery_requests where id=p_request_id and actor_id=p_actor_id for update;
 if not found then raise exception 'Payment delivery ownership mismatch' using errcode='42501';end if;
 select * into p from public.payment_delivery_captures where request_id=r.id;
 if found then if row(p.sender_config,p.message_hash,p.payload_hash) is distinct from row(p_sender_config,p_message_hash,p_payload_hash) then raise exception 'Captured payment delivery is immutable' using errcode='23505';end if;return;end if;
 context:=public.payment_delivery_current(r.id);
 if p_sender_config is null or jsonb_typeof(p_sender_config)<>'object' or octet_length(p_sender_config::text)>2048 or exists(select 1 from jsonb_each(p_sender_config) e where jsonb_typeof(e.value)<>'string') or (r.channel='EMAIL' and (not p_sender_config ?& array['from','reply_to'] or p_sender_config-array['from','reply_to']<>'{}' or public.communication_recipient('EMAIL',p_sender_config->>'reply_to') is null or public.communication_recipient('EMAIL',coalesce(substring(p_sender_config->>'from' from '<([^<>]+)>$'),p_sender_config->>'from')) is null))
 or (r.channel='SMS' and public.communication_sms_provider()='twilio' and (not p_sender_config ?& array['from','account_sid'] or p_sender_config-array['from','account_sid']<>'{}' or public.communication_recipient('SMS',p_sender_config->>'from') is null or coalesce(p_sender_config->>'account_sid','') !~ '^AC[A-Za-z0-9]{32}$'))
 or (r.channel='SMS' and public.communication_sms_provider()='cloudtalk' and (not p_sender_config ?& array['from','provider'] or p_sender_config-array['from','provider']<>'{}' or p_sender_config->>'provider'<>'cloudtalk' or public.communication_recipient('SMS',p_sender_config->>'from') is distinct from p_sender_config->>'from')) then raise exception 'Invalid frozen payment sender configuration' using errcode='23514';end if;
 if r.invoice_email_request_id is not null and row(context#>>'{invoice_payload,from}',context#>>'{invoice_payload,reply_to}') is distinct from row(p_sender_config->>'from',p_sender_config->>'reply_to') then raise exception 'Invoice attachment sender differs from payment message' using errcode='23514';end if;
 insert into public.payment_delivery_captures(request_id,sender_config,message_hash,payload_hash) values(r.id,p_sender_config,p_message_hash,p_payload_hash);
end $$

-- The outbound_deliveries worker checked consent only at enqueue. This final
-- check applies the same suppression and consent rules as the outbox (CloudTalk
-- and Twilio STOP, staff suppression, missing or withdrawn consent) to a row the
-- calling worker currently leases.
create function public.outbound_delivery_sms_permitted(p_delivery_id uuid,p_lease_owner text) returns boolean language plpgsql stable security definer set search_path=public as $$
declare d public.outbound_deliveries;recipient text;
begin
 perform public.communication_require_service();
 select * into d from public.outbound_deliveries where id=p_delivery_id;
 if not found or d.status<>'LEASED'::public.outbound_delivery_status or d.lease_owner is distinct from nullif(btrim(p_lease_owner),'') or d.leased_until<=now() then
  raise exception 'Outbound delivery is not actively leased to this worker' using errcode='40001';
 end if;
 if d.channel<>'SMS'::public.channel_type or d.client_id is null then return false; end if;
 recipient:=public.communication_recipient('SMS',d.recipient);
 return recipient is not null and not public.communication_is_suppressed('SMS',recipient,d.client_id);
end $$

-- CloudTalk originals never change or disappear once accepted. Calls merge
-- lifecycle events by design, but are never deleted.
create function public.guard_cloudtalk_original() returns trigger language plpgsql set search_path = public as $$
begin
  if TG_OP = 'DELETE' then raise exception 'CloudTalk history cannot be deleted' using errcode = '23514'; end if;
  if TG_TABLE_NAME in ('cloudtalk_messages', 'cloudtalk_events') then
    raise exception 'CloudTalk originals are immutable' using errcode = '23514';
  end if;
  if NEW.call_uuid is distinct from OLD.call_uuid then raise exception 'CloudTalk call identity is immutable' using errcode = '23514'; end if;
  return NEW;
end $$

alter table public.communication_inbound add constraint communication_inbound_source_check check (
  case when provider = 'cloudtalk'
    then event_id is null and resource_id ~ '^(message|call):.{1,200}$' and channel <> 'EMAIL'
    else event_id is not null and direction = 'inbound' and channel in ('EMAIL', 'SMS')
  end
)

create function public.guard_cloudtalk_inbound() returns trigger language plpgsql set search_path = public as $$
begin
  if TG_OP = 'DELETE' then
    if OLD.provider = 'cloudtalk' then raise exception 'Received communication history cannot be deleted' using errcode = '23514'; end if;
    return OLD;
  end if;
  if (OLD.provider = 'cloudtalk' or NEW.provider = 'cloudtalk') and
    row(NEW.id, NEW.provider, NEW.resource_id, NEW.event_id, NEW.channel, NEW.direction, NEW.sender, NEW.recipient, NEW.subject, NEW.body, NEW.occurred_at, NEW.received_at)
    is distinct from row(OLD.id, OLD.provider, OLD.resource_id, OLD.event_id, OLD.channel, OLD.direction, OLD.sender, OLD.recipient, OLD.subject, OLD.body, OLD.occurred_at, OLD.received_at) then
    raise exception 'Received CloudTalk communication is immutable' using errcode = '23514';
  end if;
  return NEW;
end $$

-- Thread entries keyed as CloudTalk are written only by the projection and
-- review assignment (security definer, running as the function owner). Staff
-- sessions keep their general messages insert policy but cannot forge a
-- CloudTalk-labelled entry or squat on a key a real webhook will need.
create function public.guard_cloudtalk_thread_message() returns trigger language plpgsql set search_path = public as $$
begin
  if (NEW.provider = 'cloudtalk' or (TG_OP = 'UPDATE' and OLD.provider = 'cloudtalk'))
    and current_user in ('anon', 'authenticated', 'service_role') then
    raise exception 'CloudTalk thread entries are written only by CloudTalk ingestion' using errcode = '42501';
  end if;
  return NEW;
end $$

-- Activity started in CloudTalk Phone has no app staff identity to attribute a
-- response time to. Response metrics stay limited to attributable replies.
create or replace function public.track_response_metric() returns trigger
language plpgsql security definer set search_path = public as $$
declare _client_msg record;
begin
  if NEW.sender_type = 'STAFF' and NEW.is_internal = false and NEW.sender_id is not null then
    select id, created_at, type into _client_msg
    from public.messages
    where conversation_id = NEW.conversation_id and sender_type = 'CLIENT' and created_at < NEW.created_at
    order by created_at desc limit 1;
    if _client_msg.id is not null then
      insert into public.response_metrics(conversation_id, message_id, staff_id, client_message_at, staff_reply_at, channel)
      values (NEW.conversation_id, NEW.id, NEW.sender_id, _client_msg.created_at, NEW.created_at, NEW.type);
    end if;
  end if;
  return NEW;
end $$

-- Projects one CloudTalk original ('message:<id>' or 'call:<uuid>'). Idempotent:
-- a second call for the same source returns the existing projection. Returns
-- null when the source is not projectable (unknown, unfinished, internal call).
create function public.project_cloudtalk_source(p_resource_id text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_msg public.cloudtalk_messages;
  v_call public.cloudtalk_calls;
  result public.communication_inbound;
  v_direction text;
  v_channel text;
  v_external text;
  v_internal text;
  v_body text;
  v_at timestamptz;
  v_client uuid;
  v_conversation uuid;
  v_message uuid;
  matches integer;
  answered_seconds integer;
  app_sends integer;
  echo_rank integer;
begin
  if p_resource_id is null or p_resource_id !~ '^(message|call):.{1,200}$' then return null; end if;
  if p_resource_id like 'message:%' then
    select * into v_msg from public.cloudtalk_messages where message_id = substr(p_resource_id, 9);
    if not found then return null; end if;
    v_direction := v_msg.direction;
    v_channel := 'SMS';
    v_external := public.communication_recipient('SMS', v_msg.external_number);
    v_internal := public.communication_recipient('SMS', v_msg.internal_number);
    -- Texts the app itself sent through CloudTalk already have their staff
    -- message (with outbox delivery state) in the thread; CloudTalk's
    -- message.sent echo of them must not add a second copy. There is no shared
    -- identifier, so an echo is matched on recipient, exact body and a send
    -- window, and at most one echo is absorbed per app send (so an identical
    -- text typed in CloudTalk Phone within the window still appears).
    if v_direction = 'outbound' and v_external is not null then
      select count(*) into app_sends from (
        select 1 from public.communication_outbox o
        where o.channel = 'SMS' and o.message_id is not null and o.recipient = v_external and o.body = v_msg.body
          and coalesce(o.first_attempt_at, o.created_at) between v_msg.occurred_at - interval '1 hour' and v_msg.occurred_at + interval '10 minutes'
        union all
        select 1 from public.outbound_deliveries d
        where d.channel = 'SMS'::public.channel_type and d.message_id is not null
          and public.communication_recipient('SMS', d.recipient) = v_external and d.payload->>'body' = v_msg.body
          and coalesce(d.leased_at, d.accepted_at, d.created_at) between v_msg.occurred_at - interval '1 hour' and v_msg.occurred_at + interval '10 minutes'
      ) app;
      if app_sends > 0 then
        select count(*) into echo_rank from public.cloudtalk_messages m
        where m.direction = 'outbound' and m.body = v_msg.body
          and public.communication_recipient('SMS', m.external_number) = v_external
          and m.occurred_at between v_msg.occurred_at - interval '70 minutes' and v_msg.occurred_at
          and (m.occurred_at, m.message_id) <= (v_msg.occurred_at, v_msg.message_id);
        if echo_rank <= app_sends then return null; end if;
      end if;
    end if;
    v_body := case when btrim(v_msg.body) = '' then '[' || upper(v_msg.channel) || ' with no text. Open CloudTalk to view attachments.]' else v_msg.body end;
    v_at := v_msg.occurred_at;
  else
    select * into v_call from public.cloudtalk_calls where call_uuid = substr(p_resource_id, 6);
    -- Partial AI/recording rows and unowned numbers are never shown alone.
    if not found or v_call.ended_at is null or not v_call.trusted_number then return null; end if;
    v_direction := case lower(coalesce(v_call.direction, '')) when 'incoming' then 'inbound' when 'inbound' then 'inbound'
      when 'outgoing' then 'outbound' when 'outbound' then 'outbound' end;
    if v_direction is null then return null; end if; -- internal and monitor legs are not client contact
    v_channel := case when v_call.is_voicemail then 'VOICEMAIL' when v_direction = 'inbound' then 'CALL_INBOUND' else 'CALL_OUTBOUND' end;
    v_external := public.communication_recipient('SMS', v_call.external_number);
    v_internal := public.communication_recipient('SMS', v_call.internal_number);
    answered_seconds := coalesce(v_call.talking_seconds, v_call.duration_seconds);
    v_body := case
      when v_call.is_voicemail then 'Voicemail'
      when v_call.talking_seconds = 0 and v_direction = 'inbound' then 'Missed incoming call'
      when v_call.talking_seconds = 0 then 'Outgoing call, not answered'
      when v_direction = 'inbound' then 'Incoming call'
      else 'Outgoing call' end
      || coalesce(' · ' || public.cloudtalk_duration_text(case when v_call.is_voicemail then v_call.duration_seconds when v_call.talking_seconds = 0 then null else answered_seconds end), '');
    v_at := coalesce(v_call.started_at, v_call.ended_at);
  end if;

  -- Same per-number lock as email/SMS ingestion so matching is serialized.
  perform pg_advisory_xact_lock(hashtextextended('SMS:' || coalesce(v_external, 'withheld'), 936));
  select * into result from public.communication_inbound where provider = 'cloudtalk' and resource_id = p_resource_id;
  if found then return result.id; end if;

  -- Exact normalized household match only; shared or unknown numbers stay in review.
  if v_external is not null then
    select count(*), (array_agg(c.id))[1] into matches, v_client
    from public.clients c where public.communication_recipient('SMS', c.primary_phone) = v_external;
    if matches <> 1 then v_client := null; end if;
  end if;
  if v_client is not null then
    perform pg_advisory_xact_lock(hashtextextended('conversation:' || v_client::text, 950));
    select count(*), (array_agg(c.id))[1] into matches, v_conversation
    from public.conversations c where c.client_id = v_client and c.status = 'ACTIVE';
    if matches > 1 then v_conversation := null;
    elsif matches = 0 then insert into public.conversations(client_id) values (v_client) returning id into v_conversation;
    end if;
  end if;

  if v_conversation is not null then
    insert into public.messages(conversation_id, type, sender_type, content, is_internal, provider, provider_message_id, created_at)
    values (v_conversation, v_channel::public.message_type, case when v_direction = 'inbound' then 'CLIENT' else 'STAFF' end::public.sender_type,
      v_body, false, 'cloudtalk', p_resource_id, v_at)
    returning id into v_message;
    update public.conversations set
      last_message_at = greatest(coalesce(last_message_at, v_at), v_at),
      is_read = case when v_direction = 'inbound' then false else is_read end
    where id = v_conversation;
  end if;

  insert into public.communication_inbound(provider, resource_id, event_id, channel, direction, sender, recipient, subject, body, occurred_at,
    client_id, conversation_id, message_id, review_reason)
  values ('cloudtalk', p_resource_id, null, v_channel, v_direction,
    coalesce(case when v_direction = 'inbound' then v_external else v_internal end, 'withheld'),
    coalesce(case when v_direction = 'inbound' then v_internal else v_external end, 'withheld'),
    '', v_body, v_at, v_client, v_conversation, v_message,
    case when v_external is null then 'Caller number withheld' when v_client is null then 'Unknown or shared sender'
      when v_conversation is null then 'Multiple possible conversation threads' end)
  returning * into result;
  delete from public.cloudtalk_projection_failures where resource_id = p_resource_id;
  return result.id;
end $$

create function public.project_cloudtalk_source_safely(p_resource_id text) returns uuid
language plpgsql security definer set search_path = public as $$
declare state text; projected uuid;
begin
  projected := public.project_cloudtalk_source(p_resource_id);
  -- Not client contact (for example an absorbed app-send echo): nothing is left to retry.
  if projected is null then delete from public.cloudtalk_projection_failures where resource_id = p_resource_id; end if;
  return projected;
exception when others then
  get stacked diagnostics state = returned_sqlstate;
  insert into public.cloudtalk_projection_failures(resource_id, sqlstate) values (p_resource_id, state)
  on conflict (resource_id) do update set sqlstate = excluded.sqlstate, attempts = cloudtalk_projection_failures.attempts + 1, last_failed_at = now();
  return null;
end $$

create function public.project_cloudtalk_message_trigger() returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.project_cloudtalk_source_safely('message:' || NEW.message_id);
  return null;
end $$

create function public.project_cloudtalk_call_trigger() returns trigger language plpgsql security definer set search_path = public as $$
begin
  perform public.project_cloudtalk_source_safely('call:' || NEW.call_uuid);
  return null;
end $$

-- Administrators can re-run projection after a recorded failure is fixed.
-- Every CloudTalk original is projected by trigger (or the backfill below), so
-- the recorded failures are the complete set to retry. Sources that are simply
-- not client contact (internal legs, app-sent echoes) are never rescanned.
create function public.retry_cloudtalk_projections(p_limit integer default 100)
returns table(projected integer, still_failing integer)
language plpgsql security definer set search_path = public as $$
declare actor uuid; source text; ok_count integer := 0; fail_count integer := 0;
begin
  actor := public.clinical_require_staff();
  if not public.has_role(actor, 'ADMIN') then raise exception 'Administrator access required' using errcode = '42501'; end if;
  if p_limit is null or p_limit not between 1 and 500 then raise exception 'Invalid retry limit' using errcode = '23514'; end if;
  for source in
    select f.resource_id from public.cloudtalk_projection_failures f order by f.first_failed_at, f.resource_id limit p_limit
  loop
    if public.project_cloudtalk_source_safely(source) is not null then ok_count := ok_count + 1;
    elsif exists (select 1 from public.cloudtalk_projection_failures f where f.resource_id = source) then fail_count := fail_count + 1;
    end if;
  end loop;
  projected := ok_count; still_failing := fail_count;
  return next;
end $$

-- Review assignment now covers CloudTalk directions and keeps the thread
-- chronological and idempotency-keyed for CloudTalk entries.
create or replace function public.assign_inbound_communication(p_actor_id uuid,p_id uuid,p_expected_version integer,p_client_id uuid,p_conversation_id uuid,p_reason text) returns public.communication_inbound language plpgsql security definer set search_path=public as $$
declare actor uuid;result public.communication_inbound;message uuid;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 select * into result from public.communication_inbound where id=p_id for update;
 if not found or result.version is distinct from p_expected_version or result.message_id is not null then raise exception 'Inbound review changed; reload' using errcode='40001';end if;
 if p_reason is null or length(trim(p_reason)) not between 5 and 1000 or not exists(select 1 from public.conversations where id=p_conversation_id and client_id=p_client_id) then raise exception 'Choose a conversation belonging to the selected household and provide a reason' using errcode='23514';end if;
 if result.provider='cloudtalk' then
  insert into public.messages(conversation_id,type,sender_type,content,is_internal,provider,provider_message_id,created_at)
  values(p_conversation_id,result.channel::public.message_type,case when result.direction='inbound' then 'CLIENT' else 'STAFF' end::public.sender_type,result.body,false,'cloudtalk',result.resource_id,result.occurred_at) returning id into message;
 else
  insert into public.messages(conversation_id,type,sender_type,content,is_internal) values(p_conversation_id,result.channel::public.message_type,'CLIENT',result.body,false) returning id into message;
 end if;
 update public.communication_inbound set client_id=p_client_id,conversation_id=p_conversation_id,message_id=message,review_reason=null,version=version+1 where id=p_id returning * into result;
 insert into public.communication_inbound_assignments(inbound_id,client_id,conversation_id,assigned_by,reason) values(p_id,p_client_id,p_conversation_id,actor,p_reason);
 update public.conversations set last_message_at=now(),is_read=false where id=p_conversation_id;
 return result;
end $$

-- Same contract as 20260926090000, plus talking_seconds so missed calls are known.
create or replace function public.ingest_cloudtalk_event(
  p_event_id text, p_event_type text, p_occurred_at timestamptz, p_data jsonb
) returns boolean language plpgsql security definer set search_path = public as $$
declare
  call_key text;
  number_internal text;
  number_external text;
  message_key text;
begin
  perform public.communication_require_service();
  if p_event_id is null or length(p_event_id) not between 1 and 200
    or p_event_type not in ('call.ended', 'call.recording_ready', 'transcript.ready', 'cidata.ready', 'message.sent', 'message.received')
    or p_occurred_at is null or p_occurred_at > now() + interval '5 minutes'
    or p_data is null or jsonb_typeof(p_data) <> 'object'
    or octet_length(p_data::text) > 262144 then
    raise exception 'Invalid CloudTalk event' using errcode = '23514';
  end if;
  insert into public.cloudtalk_events(event_id, event_type, occurred_at)
  values(p_event_id, p_event_type, p_occurred_at) on conflict do nothing;
  if not found then return false; end if;

  if p_event_type like 'call.%' or p_event_type in ('transcript.ready', 'cidata.ready') then
    call_key := p_data->>'call_uuid';
    if call_key is null or length(call_key) not between 1 and 200 then
      raise exception 'Invalid CloudTalk call' using errcode = '23514';
    end if;
    number_external := p_data->>'external_number';
    number_internal := p_data#>>'{internal_number,number_e164}';
    insert into public.cloudtalk_calls(
      call_uuid, call_id, direction, external_number, internal_number,
      started_at, ended_at, duration_seconds, talking_seconds, is_voicemail, recording_ready,
      transcript_ready, ai_summary, ai_language, trusted_number, last_event_at
    ) values (
      call_key, p_data->>'call_id', p_data->>'direction', number_external, number_internal,
      nullif(p_data->>'started_at', '')::timestamptz,
      nullif(p_data->>'ended_at', '')::timestamptz,
      case when (p_data->>'duration') ~ '^[0-9]{1,8}$' then (p_data->>'duration')::integer end,
      case when p_event_type = 'call.ended' and (p_data->>'talking_time') ~ '^[0-9]{1,8}$' then (p_data->>'talking_time')::integer end,
      coalesce((p_data->>'is_voicemail')::boolean, false),
      p_event_type = 'call.recording_ready',
      p_event_type = 'transcript.ready',
      case when p_event_type = 'cidata.ready' then left(p_data#>>'{summary,summary}', 10000) end,
      case when p_event_type in ('transcript.ready', 'cidata.ready') then left(p_data->>'language', 20) end,
      p_event_type = 'call.ended',
      p_occurred_at
    ) on conflict(call_uuid) do update set
      call_id = coalesce(excluded.call_id, cloudtalk_calls.call_id),
      direction = coalesce(excluded.direction, cloudtalk_calls.direction),
      external_number = coalesce(excluded.external_number, cloudtalk_calls.external_number),
      internal_number = coalesce(excluded.internal_number, cloudtalk_calls.internal_number),
      started_at = coalesce(excluded.started_at, cloudtalk_calls.started_at),
      ended_at = coalesce(excluded.ended_at, cloudtalk_calls.ended_at),
      duration_seconds = coalesce(excluded.duration_seconds, cloudtalk_calls.duration_seconds),
      talking_seconds = coalesce(excluded.talking_seconds, cloudtalk_calls.talking_seconds),
      is_voicemail = excluded.is_voicemail or cloudtalk_calls.is_voicemail,
      recording_ready = excluded.recording_ready or cloudtalk_calls.recording_ready,
      transcript_ready = excluded.transcript_ready or cloudtalk_calls.transcript_ready,
      ai_summary = coalesce(excluded.ai_summary, cloudtalk_calls.ai_summary),
      ai_language = coalesce(excluded.ai_language, cloudtalk_calls.ai_language),
      trusted_number = excluded.trusted_number or cloudtalk_calls.trusted_number,
      last_event_at = greatest(excluded.last_event_at, cloudtalk_calls.last_event_at);
  else
    message_key := p_data->>'id';
    number_external := p_data->>'external_number';
    number_internal := p_data#>>'{internal_number,number_e164}';
    if message_key is null or length(message_key) not between 1 and 200
      or public.communication_recipient('SMS', number_external) is null
      or public.communication_recipient('SMS', number_internal) is null
      or p_data->>'channel' not in ('sms', 'mms', 'whatsapp')
      or length(coalesce(p_data->>'body', '')) > 100000 then
      raise exception 'Invalid CloudTalk message' using errcode = '23514';
    end if;
    insert into public.cloudtalk_messages(
      message_id, direction, channel, external_number, internal_number, body, occurred_at
    ) values (
      message_key, case when p_event_type = 'message.received' then 'inbound' else 'outbound' end,
      p_data->>'channel', number_external, number_internal, coalesce(p_data->>'body', ''), p_occurred_at
    ) on conflict(message_id) do nothing;
    -- A signed inbound STOP blocks any future SMS request, including one
    -- queued before the message arrived. Re-enabling requires staff review.
    if p_event_type = 'message.received' and p_data->>'channel' = 'sms' and upper(btrim(coalesce(p_data->>'body', ''))) in ('STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT') then
      insert into public.communication_suppressions(channel, recipient, reason)
      values ('SMS', public.communication_recipient('SMS', number_external), 'cloudtalk_sms_stop')
      on conflict (channel, recipient) do nothing;
      update public.sms_consent set opted_in = false, opted_out_at = greatest(coalesce(opted_out_at, p_occurred_at), p_occurred_at)
      where public.communication_recipient('SMS', phone_number) = public.communication_recipient('SMS', number_external);
      update public.communication_outbox set state = 'failed', last_error = 'recipient_suppressed', updated_at = now()
      where channel = 'SMS' and recipient = public.communication_recipient('SMS', number_external) and state = 'pending';
      update public.outbound_deliveries set status = 'CANCELED', canceled_at = now(), updated_at = now(), status_note = 'Recipient sent STOP to CloudTalk'
      where channel = 'SMS' and recipient = public.communication_recipient('SMS', number_external) and status = 'QUEUED';
    end if;
  end if;
  return true;
end $$

do $$ declare f record; begin
  for f in select p.oid::regprocedure signature, p.proname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname in ('cloudtalk_duration_text', 'project_cloudtalk_source', 'project_cloudtalk_source_safely',
      'project_cloudtalk_message_trigger', 'project_cloudtalk_call_trigger', 'retry_cloudtalk_projections', 'assign_inbound_communication') loop
    execute format('revoke all on function %s from public, anon, authenticated, service_role', f.signature);
    if f.proname in ('retry_cloudtalk_projections', 'assign_inbound_communication') then
      execute format('grant execute on function %s to authenticated', f.signature);
    end if;
  end loop;
end $$

create function public.catalog_vaccine_profile_guard() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='DELETE' then raise exception 'Vaccine profiles are retained; clear fields with a reviewed update' using errcode='23514'; end if;
 if TG_OP='UPDATE' and (NEW.product_id<>OLD.product_id or NEW.id<>OLD.id) then raise exception 'Vaccine profile product is immutable' using errcode='23514'; end if;
 if not exists(select 1 from public.catalog_products where id=NEW.product_id and kind='vaccine') then raise exception 'Vaccine metadata applies only to vaccine products' using errcode='23514'; end if;
 return NEW;
end $$

-- Catalog maintainers with clinical or administrative authority record the label facts and their source.
create function public.save_catalog_vaccine_profile(p_product_id uuid,p_expected_version integer,p_group_key text,p_species text[],p_vaccine_type text,p_labeled_duration text,p_default_booster_interval_days integer,p_review_note text) returns public.catalog_vaccine_profiles language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); r public.catalog_vaccine_profiles; g text; s text[]; vt text;
begin
 if not exists(select 1 from public.user_roles where user_id=actor and role in ('ADMIN','DVM')) then raise exception 'Veterinarian or administrator required for vaccine catalog metadata' using errcode='42501'; end if;
 if p_product_id is null then raise exception 'Vaccine product required' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_product_id::text,28120));
 perform 1 from public.catalog_products where id=p_product_id and kind='vaccine' for share;
 if not found then raise exception 'Vaccine metadata applies only to vaccine products' using errcode='23514'; end if;
 g:=nullif(lower(trim(coalesce(p_group_key,''))),'');
 if g is not null and g!~'^[a-z0-9][a-z0-9_-]{0,79}$' then raise exception 'Vaccine group key uses lowercase letters, digits, hyphen or underscore' using errcode='23514'; end if;
 if p_species is null or cardinality(p_species)>10 or exists(select 1 from unnest(p_species) x where x is null or length(trim(x)) not between 1 and 80) then raise exception 'List up to 10 species labels of 1-80 characters' using errcode='23514'; end if;
 select coalesce(array_agg(distinct lower(trim(x)) order by lower(trim(x))),'{}') into s from unnest(p_species) x;
 vt:=nullif(trim(coalesce(p_vaccine_type,'')),'');
 if vt is not null and length(vt)>200 then raise exception 'Vaccine type is too long' using errcode='23514'; end if;
 if p_labeled_duration is not null and p_labeled_duration not in ('1 year','3 years','other licensed duration') then raise exception 'Labeled duration must match the product label choices' using errcode='23514'; end if;
 if p_default_booster_interval_days is not null and p_default_booster_interval_days not between 1 and 36500 then raise exception 'Booster interval must be between 1 and 36500 days' using errcode='23514'; end if;
 if length(trim(coalesce(p_review_note,''))) not between 1 and 2000 then raise exception 'Record the label source or reviewer for this metadata' using errcode='23514'; end if;
 select * into r from public.catalog_vaccine_profiles where product_id=p_product_id for update;
 if found then
  -- A lost response retried by the same reviewer returns the saved row instead of conflicting.
  if r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and row(r.group_key,r.species,r.vaccine_type,r.labeled_duration,r.default_booster_interval_days,r.review_note) is not distinct from row(g,s,vt,p_labeled_duration,p_default_booster_interval_days,trim(p_review_note)) then return r; end if;
  if r.version is distinct from p_expected_version then raise exception 'Vaccine profile changed; reload before saving' using errcode='40001'; end if;
  update public.catalog_vaccine_profiles set group_key=g,species=s,vaccine_type=vt,labeled_duration=p_labeled_duration,default_booster_interval_days=p_default_booster_interval_days,review_note=trim(p_review_note),version=version+1,updated_by=actor,updated_at=now() where product_id=p_product_id returning * into r;
 else
  if p_expected_version is not null then raise exception 'Vaccine profile changed; reload before saving' using errcode='40001'; end if;
  insert into public.catalog_vaccine_profiles(product_id,group_key,species,vaccine_type,labeled_duration,default_booster_interval_days,review_note,updated_by) values(p_product_id,g,s,vt,p_labeled_duration,p_default_booster_interval_days,trim(p_review_note),actor) returning * into r;
 end if;
 return r;
end $$

-- Status precedence per vaccine group (documented in docs/vaccine-status-and-catalog.md):
--  1. a CURRENT reviewed patient due plan supplies the due date;
--  2. otherwise the latest uncorrected administration's recorded next due date
--     (practice administration, historical entry, or reviewed outside ezyVet record) is shown with its source;
--  3. otherwise no due date. Proposed plans never supply a date; they are flagged as awaiting review.
-- Combination products count toward every active reviewed template group that lists them.
-- The due-soon window is display policy and is applied by the client, not here.
create function public.patient_vaccine_status_summary(p_pet_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;
begin
 perform public.clinical_require_staff();
 if p_pet_id is null or not exists(select 1 from public.pets where id=p_pet_id) then raise exception 'Patient not found' using errcode='23514'; end if;
 with native as (
  select t.id record_id,case when t.historical then 'historical_record' else 'practice_administration' end source,t.product_id,t.product_name,(t.administered_at at time zone 'America/Denver')::date administered_on,t.administered_at,t.next_due_on
  from public.patient_treatments t where t.pet_id=p_pet_id and t.kind='vaccine' and not exists(select 1 from public.patient_treatment_corrections c where c.treatment_id=t.id)
 ), outside as (
  -- Only the latest reviewed version of an outside record counts, and only when reviewed as administered on a known date.
  select v.id record_id,'outside_record' source,case when jsonb_typeof(v.product)='object' then (v.product->>'id')::uuid end product_id,
   coalesce(nullif(trim(case when jsonb_typeof(v.product)='object' then v.product->>'name' end),''),'Outside vaccination #'||v.vaccination_external_id) product_name,
   (v.reviewed->>'administered_on')::date administered_on,null::timestamptz administered_at,case when v.reviewed->>'next_date_status'='date' then (v.reviewed->>'source_next_due_on')::date end next_due_on
  from public.ezyvet_imported_vaccinations v where v.pet_id=p_pet_id and v.reviewed->>'status'='administered' and v.reviewed->>'administration_date_status'='date' and not exists(select 1 from public.ezyvet_imported_vaccinations n where n.replaces_id=v.id)
 ), recs as (select * from native union all select * from outside
 ), members as (
  select t.group_key,t.name group_name,0 group_rank,r.* from recs r join public.vaccine_due_templates t on t.active and r.product_id=any(t.product_ids)
  union all
  select p.group_key,p.group_key,1,r.* from recs r join public.catalog_vaccine_profiles p on p.product_id=r.product_id and p.group_key is not null
   where not exists(select 1 from public.vaccine_due_templates t where t.active and r.product_id=any(t.product_ids) and t.group_key=p.group_key)
  union all
  select case when r.product_id is not null then 'product:'||r.product_id::text else 'record:'||lower(trim(r.product_name)) end,r.product_name,2,r.* from recs r
   where not exists(select 1 from public.vaccine_due_templates t where t.active and r.product_id=any(t.product_ids))
   and not exists(select 1 from public.catalog_vaccine_profiles p where p.product_id=r.product_id and p.group_key is not null)
 ), plans as (select * from public.patient_vaccine_due_plans v where v.pet_id=p_pet_id and v.status<>'retired'
 ), keys as (select group_key from members union select group_key from plans
 ), latest as (
  select distinct on (m.group_key) m.* from members m
  order by m.group_key,m.administered_on desc,m.administered_at desc nulls last,case m.source when 'practice_administration' then 0 when 'historical_record' then 1 else 2 end,m.record_id
 ), labels as (
  select distinct on (m.group_key) m.group_key,m.group_name,case m.group_rank when 0 then 'due_template' when 1 then 'catalog_profile' else 'product' end group_source from members m order by m.group_key,m.group_rank,m.record_id
 ), counts as (select m.group_key,count(*)::integer n from members m group by m.group_key
 ), resolved as (
  select k.group_key,coalesce(nullif(p.template_snapshot->>'name',''),lb.group_name,k.group_key) group_name,coalesce(lb.group_source,'due_template') group_source,
   case when p.id is not null and (l.administered_on is null or p.last_administered_on>l.administered_on) then p.last_administered_on else l.administered_on end last_given_on,
   case when p.id is not null and (l.administered_on is null or p.last_administered_on>l.administered_on) then 'due_plan_anchor' else l.source end last_given_source,
   l.record_id last_record_id,l.product_name last_product_name,
   case when p.status='current' then p.current_due_on else l.next_due_on end due_on,
   case when p.status='current' then 'reviewed_due_plan' when l.next_due_on is not null then l.source end due_source,
   coalesce(c.n,0) record_count,
   case when p.id is null then null else jsonb_build_object('id',p.id,'version',p.version,'status',p.status,'current_due_on',p.current_due_on,'last_administered_on',p.last_administered_on) end plan,
   array_remove(array[case when p.status='proposed' then 'plan_awaiting_review' end,case when p.status='current' and l.administered_on>p.last_administered_on then 'administration_after_plan_anchor' end],null) flags
  from keys k left join plans p on p.group_key=k.group_key left join latest l on l.group_key=k.group_key left join labels lb on lb.group_key=k.group_key left join counts c on c.group_key=k.group_key
 )
 select jsonb_build_object('pet_id',p_pet_id,'as_of',(now() at time zone 'America/Denver')::date,'groups',coalesce(jsonb_agg(jsonb_build_object(
  'group_key',r.group_key,'group_name',r.group_name,'group_source',r.group_source,'last_given_on',r.last_given_on,'last_given_source',r.last_given_source,
  'last_record_id',r.last_record_id,'last_product_name',r.last_product_name,'due_on',r.due_on,'due_source',r.due_source,'record_count',r.record_count,
  'plan',r.plan,'flags',to_jsonb(r.flags)) order by lower(r.group_name),r.group_key),'[]'::jsonb)) into result from resolved r;
 return result;
end $$

create function public.preview_vaccine_certificate(p_pet_id uuid,p_kind text,p_rabies_treatment_id uuid,p_details jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare serial jsonb; snapshot jsonb;
begin
 if p_kind is distinct from 'rabies' or p_details is null or jsonb_typeof(p_details)<>'object' then
  return public.preview_vaccine_certificate_v2_internal(p_pet_id,p_kind,p_rabies_treatment_id,p_details);
 end if;
 serial:=coalesce(p_details->'vaccine_serial_number','null'::jsonb);
 if jsonb_typeof(serial) not in ('string','null') then raise exception 'Invalid certificate detail type' using errcode='23514'; end if;
 if jsonb_typeof(serial)='string' then
  if length(p_details->>'vaccine_serial_number')>200 then raise exception 'Vaccine serial number is too long' using errcode='23514'; end if;
  serial:=case when trim(p_details->>'vaccine_serial_number')='' then 'null'::jsonb else to_jsonb(trim(p_details->>'vaccine_serial_number')) end;
 end if;
 snapshot:=public.preview_vaccine_certificate_v2_internal(p_pet_id,p_kind,p_rabies_treatment_id,p_details-'vaccine_serial_number');
 return jsonb_set(snapshot,'{details,vaccine_serial_number}',serial,true);
end $$

create function public.qol_scale_guard() returns trigger language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();
begin
 if TG_OP='DELETE' then raise exception 'Quality-of-life scale history cannot be deleted' using errcode='23514'; end if;
 if TG_TABLE_NAME='patient_qol_scale_addenda' then
  if TG_OP='UPDATE' then raise exception 'Addenda are append-only' using errcode='23514'; end if;
  NEW.created_by:=actor; NEW.created_at:=now(); return NEW;
 end if;
 if TG_OP='UPDATE' then
  if OLD.status='signed' then raise exception 'Signed quality-of-life assessments are immutable; add an addendum' using errcode='23514'; end if;
  NEW.id:=OLD.id; NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.pet_id:=OLD.pet_id; NEW.scale_version:=OLD.scale_version; NEW.version:=OLD.version+1;
 else NEW.created_by:=actor; NEW.created_at:=now(); NEW.version:=1; end if;
 NEW.updated_by:=actor; NEW.updated_at:=now();
 if NEW.status='signed' then
  if num_nulls(NEW.hurt,NEW.hunger,NEW.hydration,NEW.hygiene,NEW.happiness,NEW.mobility,NEW.more_good_days)>0 then raise exception 'Score all seven categories before signing' using errcode='23514'; end if;
  NEW.signed_by:=actor; NEW.signed_at:=now();
 else NEW.signed_by:=null; NEW.signed_at:=null; end if;
 return NEW;
end $$

create function public.qol_scale_settings_guard() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if TG_OP<>'UPDATE' then raise exception 'Quality-of-life reference setting is a single reviewed row' using errcode='23514'; end if;
 NEW.id:=OLD.id; NEW.version:=OLD.version+1; NEW.updated_by:=public.care_require_admin(); NEW.updated_at:=now(); return NEW;
end $$

do $$ declare t text; begin
 foreach t in array array['patient_qol_scale_assessments','patient_qol_scale_addenda','qol_scale_reference_settings'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated,service_role',t);
  execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
  execute format('create trigger care_chart_audit after insert or update on public.%I for each row execute function public.audit_trigger_fn()',t);
 end loop;
end $$

create function public.save_patient_qol_scale(p_id uuid,p_pet_id uuid,p_expected_version integer,p_assessed_at timestamptz,p_assessor text,p_hurt integer,p_hunger integer,p_hydration integer,p_hygiene integer,p_happiness integer,p_mobility integer,p_more_good_days integer,p_hurt_note text,p_hunger_note text,p_hydration_note text,p_hygiene_note text,p_happiness_note text,p_mobility_note text,p_more_good_days_note text,p_notes text) returns public.patient_qol_scale_assessments language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_qol_scale_assessments;
begin
 if p_id is null or p_pet_id is null then raise exception 'Stable assessment and patient IDs required' using errcode='23514'; end if;
 if p_assessed_at is null or not isfinite(p_assessed_at) or p_assessed_at>now()+interval '5 minutes' then raise exception 'Invalid assessment time' using errcode='23514'; end if;
 if exists(select 1 from unnest(array[p_hurt,p_hunger,p_hydration,p_hygiene,p_happiness,p_mobility,p_more_good_days]) s where s not between 0 and 10) then raise exception 'Each category score must be a whole number from 0 to 10' using errcode='23514'; end if;
 if num_nulls(p_hurt_note,p_hunger_note,p_hydration_note,p_hygiene_note,p_happiness_note,p_mobility_note,p_more_good_days_note,p_notes)>0 then raise exception 'Notes must be text (use an empty string when blank)' using errcode='23514'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,0));
 select * into result from public.patient_qol_scale_assessments where id=p_id for update;
 if found then
  if result.pet_id<>p_pet_id then raise exception 'Patient does not match assessment' using errcode='23514'; end if;
  if (case when p_expected_version is null then result.created_by else result.updated_by end)=actor and result.version=coalesce(p_expected_version+1,1)
   and row(result.assessed_at,result.assessor,result.hurt,result.hunger,result.hydration,result.hygiene,result.happiness,result.mobility,result.more_good_days,result.hurt_note,result.hunger_note,result.hydration_note,result.hygiene_note,result.happiness_note,result.mobility_note,result.more_good_days_note,result.notes)
   is not distinct from row(p_assessed_at,p_assessor,p_hurt::smallint,p_hunger::smallint,p_hydration::smallint,p_hygiene::smallint,p_happiness::smallint,p_mobility::smallint,p_more_good_days::smallint,p_hurt_note,p_hunger_note,p_hydration_note,p_hygiene_note,p_happiness_note,p_mobility_note,p_more_good_days_note,p_notes) then return result; end if;
  if result.version is distinct from p_expected_version then raise exception 'Assessment changed; reload before saving' using errcode='40001'; end if;
  update public.patient_qol_scale_assessments set assessed_at=p_assessed_at,assessor=p_assessor,hurt=p_hurt,hunger=p_hunger,hydration=p_hydration,hygiene=p_hygiene,happiness=p_happiness,mobility=p_mobility,more_good_days=p_more_good_days,
   hurt_note=p_hurt_note,hunger_note=p_hunger_note,hydration_note=p_hydration_note,hygiene_note=p_hygiene_note,happiness_note=p_happiness_note,mobility_note=p_mobility_note,more_good_days_note=p_more_good_days_note,notes=p_notes where id=p_id returning * into result;
 else
  if p_expected_version is not null then raise exception 'Assessment no longer exists' using errcode='40001'; end if;
  insert into public.patient_qol_scale_assessments(id,pet_id,assessed_at,assessor,hurt,hunger,hydration,hygiene,happiness,mobility,more_good_days,hurt_note,hunger_note,hydration_note,hygiene_note,happiness_note,mobility_note,more_good_days_note,notes,created_by,updated_by)
   values(p_id,p_pet_id,p_assessed_at,p_assessor,p_hurt,p_hunger,p_hydration,p_hygiene,p_happiness,p_mobility,p_more_good_days,p_hurt_note,p_hunger_note,p_hydration_note,p_hygiene_note,p_happiness_note,p_mobility_note,p_more_good_days_note,p_notes,actor,actor) returning * into result;
 end if;
 return result;
end $$

create function public.sign_patient_qol_scale(p_id uuid,p_expected_version integer) returns public.patient_qol_scale_assessments language plpgsql security definer set search_path=public as $$
declare result public.patient_qol_scale_assessments; actor uuid:=public.clinical_require_staff();
begin
 select * into result from public.patient_qol_scale_assessments where id=p_id for update;
 if found and result.status='signed' and result.signed_by=actor and result.version=p_expected_version+1 then return result; end if;
 update public.patient_qol_scale_assessments set status='signed' where id=p_id and version=p_expected_version returning * into result;
 if not found then raise exception 'Assessment changed; reload before signing' using errcode='40001'; end if; return result;
end $$

create function public.add_patient_qol_scale_addendum(p_id uuid,p_assessment_id uuid,p_content text) returns public.patient_qol_scale_addenda language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); result public.patient_qol_scale_addenda;
begin
 perform 1 from public.patient_qol_scale_assessments where id=p_assessment_id and status='signed' for share;
 if not found then raise exception 'Addenda require a signed assessment' using errcode='23514'; end if;
 insert into public.patient_qol_scale_addenda(id,assessment_id,content,created_by) values(p_id,p_assessment_id,p_content,actor) on conflict(id) do nothing;
 select * into result from public.patient_qol_scale_addenda where id=p_id;
 if result.created_by<>actor or (result.assessment_id,result.content) is distinct from (p_assessment_id,p_content) then raise exception 'Addendum identifier already used' using errcode='23514'; end if; return result;
end $$

create function public.save_qol_scale_reference(p_expected_version integer,p_enabled boolean,p_reference_total integer,p_reference_label text,p_review_note text) returns public.qol_scale_reference_settings language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.care_require_admin(); result public.qol_scale_reference_settings;
begin
 select * into result from public.qol_scale_reference_settings where id='00000000-0000-4000-8000-000000000070' for update;
 if result.updated_by=actor and result.version=p_expected_version+1 and row(result.enabled,result.reference_total,result.reference_label,result.review_note) is not distinct from row(p_enabled,p_reference_total::smallint,trim(coalesce(p_reference_label,'')),trim(coalesce(p_review_note,''))) then return result; end if;
 if result.version is distinct from p_expected_version then raise exception 'Reference setting changed; reload before saving' using errcode='40001'; end if;
 if p_enabled is null then raise exception 'Choose whether the reference is shown' using errcode='23514'; end if;
 if p_reference_total is not null and p_reference_total not between 0 and 70 then raise exception 'Reference total must be between 0 and 70' using errcode='23514'; end if;
 if p_enabled and (p_reference_total is null or length(trim(coalesce(p_reference_label,'')))=0 or length(trim(coalesce(p_review_note,'')))=0) then raise exception 'An enabled reference needs a total, wording and review note' using errcode='23514'; end if;
 update public.qol_scale_reference_settings set enabled=p_enabled,reference_total=p_reference_total,reference_label=trim(coalesce(p_reference_label,'')),review_note=trim(coalesce(p_review_note,'')) where id='00000000-0000-4000-8000-000000000070' returning * into result;
 return result;
end $$

do $$ declare f record; begin
 for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname in ('save_patient_qol_scale','sign_patient_qol_scale','add_patient_qol_scale_addendum','save_qol_scale_reference') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  execute format('grant execute on function %s to authenticated',f.signature);
 end loop;
end $$

-- Draft edits may not move the procedure window away from drugs already charged against it.
create function public.anesthesia_drug_window_guard() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if (new.started_at,new.ended_at) is distinct from (old.started_at,old.ended_at) and exists(select 1 from public.anesthesia_drug_administrations a join public.patient_treatments t on t.id=a.id where a.record_id=new.id and (t.administered_at<new.started_at or t.administered_at>coalesce(new.ended_at,'infinity'::timestamptz))) then raise exception 'Recorded anesthesia drugs must stay within the procedure times' using errcode='23514';end if;
 return new;
end $$

create function public.record_anesthesia_drug_administration(p_id uuid,p_record_id uuid,p_pet_id uuid,p_request jsonb) returns public.patient_treatments language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();rec public.patient_anesthesia_records;link public.anesthesia_drug_administrations;treatment_request jsonb;product_kind text;admin_at timestamptz;result public.patient_treatments;
begin
 if p_id is null or p_record_id is null or p_pet_id is null or p_request is null or jsonb_typeof(p_request)<>'object' or exists(select 1 from jsonb_object_keys(p_request) k where k not in ('lot_id','invoice_id','quantity','dose','route','site','veterinarian','veterinarian_license','administered_at','alert_review')) then raise exception 'Invalid anesthesia drug fields' using errcode='23514';end if;
 if jsonb_typeof(p_request->'lot_id') is distinct from 'string' or jsonb_typeof(p_request->'invoice_id') is distinct from 'string' then raise exception 'Anesthesia drugs require a stock lot and the household draft invoice' using errcode='23514';end if;
 -- Server-owned patient and source keep the treatment fingerprint deterministic for retries.
 treatment_request:=p_request||jsonb_build_object('pet_id',p_pet_id,'source','Anesthesia record '||p_record_id::text);
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,14));
 perform public.clinical_require_staff();
 select * into link from public.anesthesia_drug_administrations where id=p_id;
 if found then
  if link.created_by<>actor or link.record_id<>p_record_id or link.pet_id<>p_pet_id or link.request<>treatment_request then raise exception 'Anesthesia drug identifier already used' using errcode='23514';end if;
  select * into strict result from public.patient_treatments where id=p_id;return result;
 end if;
 if exists(select 1 from public.patient_treatments where id=p_id) then raise exception 'Treatment identifier already used' using errcode='23514';end if;
 -- SHARE blocks a concurrent save/sign until this entry commits; signing then includes it.
 select * into rec from public.patient_anesthesia_records where id=p_record_id for share;
 if not found then raise exception 'Anesthesia record not found' using errcode='23514';end if;
 if rec.pet_id<>p_pet_id then raise exception 'Anesthesia record belongs to another patient' using errcode='42501';end if;
 if rec.status<>'draft' then raise exception 'Signed anesthesia records are locked; record later drugs in Treatments and append an anesthesia addendum' using errcode='23514';end if;
 admin_at:=(p_request->>'administered_at')::timestamptz;
 if admin_at is null or not isfinite(admin_at) or admin_at<rec.started_at or admin_at>coalesce(rec.ended_at,now()+interval '5 minutes') then raise exception 'Drug administration time must fall within the recorded procedure' using errcode='23514';end if;
 -- Lot product and product kind are immutable, so this unlocked read cannot change before the treatment locks.
 select p.kind into product_kind from public.inventory_lots l join public.catalog_products p on p.id=l.product_id where l.id=(p_request->>'lot_id')::uuid;
 if not found then raise exception 'Lot not found' using errcode='23514';end if;
 if product_kind<>'medication' then raise exception 'Anesthesia drug entries require a medication stock lot' using errcode='23514';end if;
 result:=public.record_patient_treatment(p_id,treatment_request);
 insert into public.anesthesia_drug_administrations(id,record_id,pet_id,request,created_by) values(p_id,p_record_id,p_pet_id,treatment_request,actor);
 return result;
end $$

-- 2. Appointment reminder channel: preference first, then the other consented channel.
create function public.appointment_reminder_channel(p_client_id uuid) returns text
language plpgsql stable security definer set search_path=public as $$
declare c public.clients;sms text;email text;sms_ok boolean;email_ok boolean;preferred text;
begin
 select * into c from public.clients where id=p_client_id;
 if c.id is null then return null;end if;
 sms=public.communication_recipient('SMS',c.primary_phone);email=public.communication_recipient('EMAIL',c.primary_email);
 -- communication_is_suppressed covers opt-outs for both channels and requires SMS opt-in.
 sms_ok=sms is not null and not public.communication_is_suppressed('SMS',sms,c.id);
 email_ok=email is not null and not public.communication_is_suppressed('EMAIL',email,c.id);
 preferred=coalesce(c.preferred_channel::text,'SMS');
 if preferred='EMAIL' and email_ok then return 'EMAIL';end if;
 if preferred='SMS' and sms_ok then return 'SMS';end if;
 -- Preferred channel unreachable, unconsented or not automatable (VOICE): use the other consented channel.
 if sms_ok then return 'SMS';end if;
 if email_ok then return 'EMAIL';end if;
 return null;
end $$

-- Unchanged from 20260912230000_scheduling.sql except the reminder channel.
create or replace function public.save_appointment(p_actor_id uuid,p_id uuid,p_expected_version integer,p_client_id uuid,p_pet_id uuid,p_scheduled_at timestamptz,p_duration_minutes integer,p_appointment_type text,p_status public.appointment_status,p_assigned_dvm_id uuid,p_visit_type text,p_address_snapshot text,p_travel_before_minutes integer,p_travel_after_minutes integer,p_resource_name text,p_notes text,p_reminder_offsets integer[])
returns public.appointments language plpgsql security definer set search_path=public as $$
declare actor uuid; result public.appointments; previous public.appointments; offset_hours integer; busy_start timestamptz; busy_end timestamptz; reminder_channel text;
begin
 actor := public.clinical_require_staff();
 if p_actor_id is distinct from actor then raise exception 'Actor mismatch' using errcode='42501'; end if;
 -- A transaction-scoped schedule lock also covers clinician reassignment and shared rooms.
 perform pg_advisory_xact_lock(73260123);
 if p_id is not null then
  select * into previous from public.appointments where id=p_id for update;
  if not found or previous.version is distinct from p_expected_version then raise exception 'Appointment changed; reload before saving' using errcode='40001'; end if;
 end if;
 if p_client_id is null or p_pet_id is null or not exists(select 1 from public.pets where id=p_pet_id and client_id=p_client_id and ((archived_at is null and deceased_at is null) or (p_status='CANCELLED' and previous.pet_id=p_pet_id and previous.client_id=p_client_id))) then raise exception 'Select an active patient belonging to this household' using errcode='23514'; end if;
 if p_assigned_dvm_id is null or (not public.is_active_staff(p_assigned_dvm_id) and not coalesce(p_status='CANCELLED' and previous.assigned_dvm_id=p_assigned_dvm_id,false)) then raise exception 'Select an active staff clinician' using errcode='23514'; end if;
 if p_scheduled_at is null or not isfinite(p_scheduled_at) or p_duration_minutes is null or p_duration_minutes not between 5 and 480 or p_visit_type is null or p_visit_type not in ('clinic','housecall') or p_status is null or p_travel_before_minutes is null or p_travel_before_minutes not between 0 and 240 or p_travel_after_minutes is null or p_travel_after_minutes not between 0 and 240 then raise exception 'Invalid appointment time or duration' using errcode='23514'; end if;
 if p_appointment_type is null or length(trim(p_appointment_type)) not between 1 and 150 or p_address_snapshot is null or length(trim(p_address_snapshot)) not between 1 and 1000 or length(p_notes)>10000 or length(p_resource_name)>150 then raise exception 'Appointment fields are missing or too long' using errcode='23514'; end if;
 if p_reminder_offsets is null or cardinality(p_reminder_offsets)>5 or exists(select 1 from unnest(p_reminder_offsets) h where h is null or h not between 1 and 720) or cardinality(p_reminder_offsets)<>(select count(distinct h) from unnest(p_reminder_offsets) h) then raise exception 'Use up to five distinct reminder offsets between 1 and 720 hours' using errcode='23514'; end if;
 busy_start := p_scheduled_at - make_interval(mins=>p_travel_before_minutes);
 busy_end := p_scheduled_at + make_interval(mins=>p_duration_minutes+p_travel_after_minutes);
 if p_status in ('SCHEDULED','CONFIRMED') and exists (
  select 1 from public.appointments a where a.id is distinct from p_id and a.status in ('SCHEDULED','CONFIRMED')
  and (a.assigned_dvm_id=p_assigned_dvm_id or (nullif(trim(p_resource_name),'') is not null and lower(a.resource_name)=lower(trim(p_resource_name))))
  and a.scheduled_at-make_interval(mins=>a.travel_before_minutes)<busy_end
  and a.scheduled_at+make_interval(mins=>a.duration_minutes+a.travel_after_minutes)>busy_start
 ) then raise exception 'Clinician or room is already booked, including travel buffers' using errcode='23P01'; end if;
 if p_id is null then
  insert into public.appointments(client_id,pet_id,scheduled_at,duration_minutes,appointment_type,status,assigned_dvm_id,visit_type,address_snapshot,travel_before_minutes,travel_after_minutes,resource_name,notes,reminder_offsets,updated_by)
  values(p_client_id,p_pet_id,p_scheduled_at,p_duration_minutes,trim(p_appointment_type),p_status,p_assigned_dvm_id,p_visit_type,case when p_visit_type='clinic' then '2619 Spruce Street, Boulder, CO' else trim(p_address_snapshot) end,p_travel_before_minutes,p_travel_after_minutes,nullif(trim(p_resource_name),''),p_notes,p_reminder_offsets,actor) returning * into result;
 else
  update public.appointments set client_id=p_client_id,pet_id=p_pet_id,scheduled_at=p_scheduled_at,duration_minutes=p_duration_minutes,appointment_type=trim(p_appointment_type),status=p_status,assigned_dvm_id=p_assigned_dvm_id,visit_type=p_visit_type,address_snapshot=case when p_visit_type='clinic' then '2619 Spruce Street, Boulder, CO' else trim(p_address_snapshot) end,travel_before_minutes=p_travel_before_minutes,travel_after_minutes=p_travel_after_minutes,resource_name=nullif(trim(p_resource_name),''),notes=p_notes,reminder_offsets=p_reminder_offsets,updated_by=actor,version=version+1 where id=p_id returning * into result;
 end if;
 update public.appointment_reminders set status='SKIPPED',error_message='Appointment revised' where appointment_id=result.id and status='PENDING';
 if result.status in ('SCHEDULED','CONFIRMED') then
  -- Chosen per appointment revision; a household change takes effect on the next save.
  -- With no consented channel yet, keep the preferred one: consent given before the
  -- reminder is due still lets it send, and the queue preflight blocks it otherwise.
  select coalesce(public.appointment_reminder_channel(c.id),case when c.preferred_channel::text='EMAIL' then 'EMAIL' else 'SMS' end) into reminder_channel from public.clients c where c.id=result.client_id;
  foreach offset_hours in array result.reminder_offsets loop
   insert into public.appointment_reminders(appointment_id,appointment_version,remind_at,channel,status)
   values(result.id,result.version,result.scheduled_at-make_interval(hours=>offset_hours),reminder_channel,case when result.scheduled_at-make_interval(hours=>offset_hours)>now() then 'PENDING'::public.reminder_status else 'SKIPPED'::public.reminder_status end);
  end loop;
 end if;
 return result;
end $$

-- Unchanged from 20260913100000_lab_work.sql except reminders_enabled.
create or replace function public.save_patient_lab_order(p_id uuid,p_pet_id uuid,p_expected_version integer,p_values jsonb,p_correction_reason text) returns public.patient_lab_orders language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.patient_lab_orders;n public.patient_lab_orders;t public.lab_due_templates;existed boolean;
begin
 actor=public.clinical_require_staff();
 if p_id is null or p_values is null or jsonb_typeof(p_values)<>'object' or exists(select 1 from jsonb_object_keys(p_values) k where k not in ('test_name','status','due_date','collected_date','result_date','accession','notes','result_document_id','template_id','template_version','interval_days','interval_anchor','override_reason','reminders_enabled')) then raise exception 'Invalid lab order fields' using errcode='23514';end if;
 if p_values ? 'reminders_enabled' and jsonb_typeof(p_values->'reminders_enabled')<>'boolean' then raise exception 'Invalid lab order fields' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,11));
 select * into r from public.patient_lab_orders where id=p_id for update;existed=found;
 if existed and r.pet_id<>p_pet_id then raise exception 'Order belongs to another patient' using errcode='42501';end if;
 n=jsonb_populate_record(null::public.patient_lab_orders,p_values);
 n.test_name=trim(n.test_name);n.notes=coalesce(n.notes,'');n.accession=coalesce(n.accession,'');n.override_reason=coalesce(n.override_reason,'');
 -- Callers that omit the switch keep the stored choice; only open orders can remind.
 n.reminders_enabled=case when p_values ? 'reminders_enabled' then (p_values->>'reminders_enabled')::boolean else coalesce(r.reminders_enabled,false) end;
 if n.status is null or n.status not in ('planned','ordered') then n.reminders_enabled=false;end if;
 -- Exact retry after an uncertain response returns its prior version without creating history twice.
 if existed and r.updated_by=actor and r.version=coalesce(p_expected_version,0)+1 and exists(select 1 from public.lab_work_revisions where entity='order' and entity_id=r.id and version=r.version and reason=coalesce(trim(p_correction_reason),'')) and
  (to_jsonb(r)-array['id','pet_id','version','created_by','updated_by','created_at','updated_at'])=(to_jsonb(n)-array['id','pet_id','version','created_by','updated_by','created_at','updated_at']) then return r;end if;
 if existed and r.version is distinct from p_expected_version or not existed and p_expected_version is not null then raise exception 'Lab order version conflict; reload before saving' using errcode='40001';end if;
 if not exists(select 1 from public.pets where id=p_pet_id) then raise exception 'Patient not found' using errcode='23514';end if;
 if not existed and not exists(select 1 from public.pets where id=p_pet_id and archived_at is null and deceased_at is null) then raise exception 'New orders require an active patient' using errcode='23514';end if;
 if existed and (r.status in ('resulted','cancelled') or r.result_date is not null or r.result_document_id is not null) and nullif(trim(p_correction_reason),'') is null then raise exception 'Historical result changes require a correction reason' using errcode='23514';end if;
 if length(coalesce(p_correction_reason,''))>2000 then raise exception 'Correction reason too long' using errcode='23514';end if;
 if n.status in ('collected','resulted') and n.collected_date is null or n.status='resulted' and n.result_date is null then raise exception 'Record collection and result dates for this status' using errcode='23514';end if;
 if n.collected_date>(now() at time zone 'America/Denver')::date or n.result_date>(now() at time zone 'America/Denver')::date then raise exception 'Collection and result dates cannot be in the future' using errcode='23514';end if;
 if n.reminders_enabled and n.due_date is null then raise exception 'Set a lab due date before enabling reminders' using errcode='23514';end if;
 if n.result_document_id is not null then
  perform 1 from public.patient_documents where id=n.result_document_id and pet_id=p_pet_id and status='ready' for share;
  if not found then raise exception 'Choose a ready document belonging to this patient' using errcode='42501';end if;
 end if;
 if n.template_id is not null then
  select * into t from public.lab_due_templates where id=n.template_id for share;
  -- Existing provenance remains valid when a reusable template is later revised/retired.
  if not (existed and row(r.template_id,r.template_version,r.interval_days,r.interval_anchor,r.due_date,r.override_reason) is not distinct from row(n.template_id,n.template_version,n.interval_days,n.interval_anchor,n.due_date,n.override_reason)) then
   if t.id is null or not t.active or t.version is distinct from n.template_version then raise exception 'Template changed or retired; review current settings' using errcode='40001';end if;
   if n.interval_days is distinct from t.interval_days and nullif(trim(n.override_reason),'') is null then raise exception 'Patient interval override requires a reason' using errcode='23514';end if;
  end if;
 elsif n.template_version is not null then raise exception 'Template version requires a template' using errcode='23514';end if;
 if n.interval_days is not null then
  if n.interval_anchor is null or not isfinite(n.interval_anchor) or n.due_date is distinct from n.interval_anchor+n.interval_days then raise exception 'Review interval anchor and due date' using errcode='23514';end if;
 elsif n.interval_anchor is not null or n.template_id is not null then raise exception 'Interval required' using errcode='23514';end if;
 if existed then
  update public.patient_lab_orders set test_name=n.test_name,status=n.status,due_date=n.due_date,collected_date=n.collected_date,result_date=n.result_date,accession=n.accession,notes=n.notes,result_document_id=n.result_document_id,template_id=n.template_id,template_version=n.template_version,interval_days=n.interval_days,interval_anchor=n.interval_anchor,override_reason=n.override_reason,reminders_enabled=n.reminders_enabled,version=version+1,updated_by=actor,updated_at=now() where id=p_id returning * into r;
 else
  insert into public.patient_lab_orders(id,pet_id,test_name,status,due_date,collected_date,result_date,accession,notes,result_document_id,template_id,template_version,interval_days,interval_anchor,override_reason,reminders_enabled,created_by,updated_by) values(p_id,p_pet_id,n.test_name,n.status,n.due_date,n.collected_date,n.result_date,n.accession,n.notes,n.result_document_id,n.template_id,n.template_version,n.interval_days,n.interval_anchor,n.override_reason,n.reminders_enabled,actor,actor) returning * into r;
 end if;
 insert into public.lab_work_revisions(entity,entity_id,version,snapshot,reason,actor_id) values('order',r.id,r.version,to_jsonb(r),coalesce(trim(p_correction_reason),''),actor);return r;
end $$

create or replace function public.list_care_reminder_candidates(p_through date,p_after_kind text default '',p_after_id uuid default '00000000-0000-0000-0000-000000000000',p_limit integer default 100)
returns table(source_kind text,source_id uuid,source_version integer,pet_id uuid,due_on date) language plpgsql security definer set search_path=public as $$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service discovery only' using errcode='42501';end if;
 if p_through is null or not isfinite(p_through) or p_limit is null or p_limit not between 1 and 500 or p_after_kind is null or p_after_id is null then raise exception 'Finite discovery horizon and bounded page required' using errcode='23514';end if;
 return query select x.kind,x.id,x.version,x.patient,x.due from (
 select 'vaccine'::text kind,v.id,v.version,v.pet_id patient,v.current_due_on due from public.patient_vaccine_due_plans v where v.status='current' and v.reminders_enabled
 union all select 'lab'::text,l.id,l.version,l.pet_id,l.due_date from public.patient_lab_orders l where l.status in ('planned','ordered') and l.reminders_enabled and l.due_date is not null
 ) x join public.pets p on p.id=x.patient where p.archived_at is null and p.deceased_at is null and x.due<=p_through and row(x.kind,x.id)>row(p_after_kind,p_after_id) order by x.kind,x.id limit p_limit;
end $$

create or replace function public.enqueue_care_reminder(p_id uuid,p_source_kind text,p_source_id uuid,p_expected_source_version integer,p_message_template_id uuid,p_expected_template_version integer) returns public.care_reminder_jobs language plpgsql security definer set search_path=public as $$
declare r public.care_reminder_jobs;t public.care_message_templates;p public.pets;v public.patient_vaccine_due_plans;l public.patient_lab_orders;patient_id uuid;due date;care_name text;snapshot jsonb;body text;part record;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service enqueue only' using errcode='42501';end if;
 if p_id is null then raise exception 'Stable job ID required' using errcode='23514';end if;
 if p_source_kind='vaccine' then select pet_id into patient_id from public.patient_vaccine_due_plans where id=p_source_id;
 elsif p_source_kind='lab' then select pet_id into patient_id from public.patient_lab_orders where id=p_source_id;
 else raise exception 'Unsupported reminder source' using errcode='23514';end if;
 select * into p from public.pets where id=patient_id and archived_at is null and deceased_at is null for share;if not found then raise exception 'Reminder requires an active patient' using errcode='23514';end if;
 if p_source_kind='vaccine' then
  select * into v from public.patient_vaccine_due_plans where id=p_source_id for share;
  if v.version is distinct from p_expected_source_version or v.status<>'current' or not v.reminders_enabled or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.treatment_id) then raise exception 'Vaccine due source is not current or enabled' using errcode='40001';end if;
  due=v.current_due_on;care_name=v.template_snapshot->>'name';snapshot=to_jsonb(v);
 else
  select * into l from public.patient_lab_orders where id=p_source_id for share;
  if l.version is distinct from p_expected_source_version or l.status not in ('planned','ordered') or not l.reminders_enabled or l.due_date is null then raise exception 'Lab due source is not current or enabled' using errcode='40001';end if;
  due=l.due_date;care_name=l.test_name;snapshot=to_jsonb(l);
 end if;
 select * into t from public.care_message_templates where id=p_message_template_id for share;
 if t.id is null or not t.active or t.version is distinct from p_expected_template_version then raise exception 'Message template changed or retired' using errcode='40001';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,16));
 select * into r from public.care_reminder_jobs where id=p_id;
 if found then if row(r.source_kind,r.source_id,r.source_version,r.message_template_id,r.message_template_version) is distinct from row(p_source_kind,p_source_id,p_expected_source_version,p_message_template_id,p_expected_template_version) then raise exception 'Job ID reused with changed request' using errcode='42501';end if;return r;end if;
 -- A separate stable request ID for the same source/template version still returns the one canonical job.
 perform pg_advisory_xact_lock(hashtextextended(p_source_kind||p_source_id::text||p_expected_source_version::text||p_message_template_id::text||p_expected_template_version::text,17));
 select * into r from public.care_reminder_jobs where source_kind=p_source_kind and source_id=p_source_id and source_version=p_expected_source_version and message_template_id=p_message_template_id and message_template_version=p_expected_template_version;if found then return r;end if;
 body='';for part in select m[1] as token from regexp_matches(t.body,'(\{\{patient_name\}\}|\{\{care_name\}\}|\{\{due_date\}\}|[^{}]+)','g') m loop body=body||case part.token when '{{patient_name}}' then p.name when '{{care_name}}' then care_name when '{{due_date}}' then due::text else part.token end;end loop;
 insert into public.care_reminder_jobs(id,source_kind,source_id,source_version,pet_id,client_id,message_template_id,message_template_version,channel,scheduled_on,due_on,rendered_body,source_snapshot,template_snapshot) values(p_id,p_source_kind,p_source_id,p_expected_source_version,p.id,p.client_id,t.id,t.version,t.channel,due-t.days_before,due,body,snapshot,to_jsonb(t)) returning * into r;return r;
end $$

create or replace function public.reminder_delivery_context(p_job_kind text,p_job_id uuid,p_policy_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare policy public.reminder_automation_policies;t public.care_message_templates;j public.care_reminder_jobs;ar public.appointment_reminders;a public.appointments;v public.patient_vaccine_due_plans;l public.patient_lab_orders;p public.pets;c public.clients;actor uuid;source jsonb;body text;care_name text;due date;part record;recipient text;
begin
 select * into policy from public.reminder_automation_policies where id=p_policy_id for share;
 if policy.id is null or not policy.enabled or not public.is_active_staff(policy.approved_by) then return null;end if;
 select * into t from public.care_message_templates where id=policy.message_template_id for share;
 if t.id is null or not t.active or t.version<>policy.message_template_version or upper(t.channel)<>policy.channel or not public.is_active_staff(t.updated_by) then return null;end if;
 if p_job_kind='care' then
  select * into j from public.care_reminder_jobs where id=p_job_id for update;
  if j.id is null or j.status<>'pending' or j.source_kind<>policy.source_kind or upper(j.channel)<>policy.channel or j.message_template_id<>t.id or j.message_template_version<>t.version or j.scheduled_on>(now() at time zone 'America/Denver')::date then return null;end if;
  if j.source_kind='vaccine' then select * into v from public.patient_vaccine_due_plans where id=j.source_id for share;
   if v.id is null or v.version<>j.source_version or v.status<>'current' or not v.reminders_enabled or v.pet_id<>j.pet_id or v.current_due_on<>j.due_on or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.treatment_id) then return null;end if;
   source=to_jsonb(v);actor=v.updated_by;
  else select * into l from public.patient_lab_orders where id=j.source_id for share;
   if l.id is null or l.version<>j.source_version or l.status not in ('planned','ordered') or not l.reminders_enabled or l.pet_id<>j.pet_id or l.due_date is distinct from j.due_on then return null;end if;
   source=to_jsonb(l);actor=l.updated_by;
  end if;
  if source is distinct from j.source_snapshot or actor is distinct from (j.source_snapshot->>'updated_by')::uuid then return null;end if;
  select * into p from public.pets where id=j.pet_id for share;
  if p.client_id is distinct from j.client_id then return null;end if;body=j.rendered_body;due=j.due_on;
 elsif p_job_kind='appointment' then
  select * into ar from public.appointment_reminders where id=p_job_id for update;
  if ar.id is null or ar.status<>'PENDING' or ar.remind_at>now() or ar.channel<>policy.channel or policy.source_kind<>'appointment' then return null;end if;
  select * into a from public.appointments where id=ar.appointment_id for share;
  if a.id is null or a.version<>ar.appointment_version or a.status not in ('SCHEDULED','CONFIRMED') or a.scheduled_at<=now() or a.pet_id is null then return null;end if;
  actor=a.updated_by;source=to_jsonb(a);select * into p from public.pets where id=a.pet_id for share;
  if p.client_id is distinct from a.client_id then return null;end if;
  due=(a.scheduled_at at time zone 'America/Denver')::date;
  care_name=a.appointment_type||' · '||to_char(a.scheduled_at at time zone 'America/Denver','YYYY-MM-DD HH24:MI')||' America/Denver · '||a.address_snapshot;
  body='';for part in select m[1] token from regexp_matches(t.body,'(\{\{patient_name\}\}|\{\{care_name\}\}|\{\{due_date\}\}|[^{}]+)','g') m loop body=body||case part.token when '{{patient_name}}' then p.name when '{{care_name}}' then care_name when '{{due_date}}' then due::text else part.token end;end loop;
 else return null;end if;
 if p.id is null or p.archived_at is not null or p.deceased_at is not null or actor is null or not public.is_active_staff(actor) then return null;end if;
 select * into c from public.clients where id=p.client_id for share;
 recipient=public.communication_recipient(policy.channel,case when policy.channel='EMAIL' then c.primary_email else c.primary_phone end);
 if recipient is null or public.communication_is_suppressed(policy.channel,recipient,c.id) or length(body)<1 or (policy.channel='SMS' and length(body)>1600) then return null;end if;
 return jsonb_build_object('job_kind',p_job_kind,'job_id',p_job_id,'policy',to_jsonb(policy),'template',to_jsonb(t),'source',source,'actor_id',actor,'pet_id',p.id,'patient_name',p.name,'client_id',c.id,'recipient',recipient,'channel',policy.channel,'subject',policy.subject,'body',body,'due_on',due);
end $$

create function public.redact_cloudtalk_capabilities() returns trigger language plpgsql set search_path = public as $$
begin
  if TG_TABLE_NAME = 'cloudtalk_messages' then
    NEW.body := public.redact_private_capabilities(NEW.body);
  else
    NEW.ai_summary := public.redact_private_capabilities(NEW.ai_summary);
  end if;
  return NEW;
end $$

-- Trigger names sort before reject_document_capability, so redaction runs first.
create trigger redact_cloudtalk_capabilities before insert on public.cloudtalk_messages
  for each row execute function public.redact_cloudtalk_capabilities()

-- CloudTalk message originals stay immutable with exactly one exception: the
-- body may be replaced by its own redaction, with every other column unchanged.
-- That change can only remove a capability, never add or alter content, and it
-- is audited here. The guards are not disabled, not even for this migration.
create or replace function public.guard_cloudtalk_original() returns trigger language plpgsql set search_path = public as $$
begin
  if TG_OP = 'DELETE' then raise exception 'CloudTalk history cannot be deleted' using errcode = '23514'; end if;
  if TG_TABLE_NAME = 'cloudtalk_messages' then
    if row(NEW.message_id, NEW.direction, NEW.channel, NEW.external_number, NEW.internal_number, NEW.occurred_at)
        is not distinct from row(OLD.message_id, OLD.direction, OLD.channel, OLD.external_number, OLD.internal_number, OLD.occurred_at)
      and NEW.body is distinct from OLD.body
      and NEW.body = public.redact_private_capabilities(OLD.body) then
      insert into public.cloudtalk_capability_redactions(source, field) values ('message:' || OLD.message_id, 'body');
      return NEW;
    end if;
  end if;
  if TG_TABLE_NAME in ('cloudtalk_messages', 'cloudtalk_events') then
    raise exception 'CloudTalk originals are immutable' using errcode = '23514';
  end if;
  if NEW.call_uuid is distinct from OLD.call_uuid then raise exception 'CloudTalk call identity is immutable' using errcode = '23514'; end if;
  return NEW;
end $$

-- Same as 20260928110000 except that app-send echoes are compared after
-- template-to-placeholder mapping (so a document-link or payment-link text the
-- app sent is absorbed like any other app send), and the thread text is passed
-- through redaction once more.
create or replace function public.project_cloudtalk_source(p_resource_id text) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_msg public.cloudtalk_messages;
  v_call public.cloudtalk_calls;
  result public.communication_inbound;
  v_direction text;
  v_channel text;
  v_external text;
  v_internal text;
  v_body text;
  v_at timestamptz;
  v_client uuid;
  v_conversation uuid;
  v_message uuid;
  matches integer;
  answered_seconds integer;
  app_sends integer;
  echo_rank integer;
begin
  if p_resource_id is null or p_resource_id !~ '^(message|call):.{1,200}$' then return null; end if;
  if p_resource_id like 'message:%' then
    select * into v_msg from public.cloudtalk_messages where message_id = substr(p_resource_id, 9);
    if not found then return null; end if;
    v_direction := v_msg.direction;
    v_channel := 'SMS';
    v_external := public.communication_recipient('SMS', v_msg.external_number);
    v_internal := public.communication_recipient('SMS', v_msg.internal_number);
    -- Texts the app itself sent through CloudTalk already have their staff
    -- message (with outbox delivery state) in the thread; CloudTalk's
    -- message.sent echo of them must not add a second copy. There is no shared
    -- identifier, so an echo is matched on recipient, exact (redacted) body and
    -- a send window, and at most one echo is absorbed per app send (so an
    -- identical text typed in CloudTalk Phone within the window still appears).
    if v_direction = 'outbound' and v_external is not null then
      select count(*) into app_sends from (
        select 1 from public.communication_outbox o
        where o.channel = 'SMS' and o.message_id is not null and o.recipient = v_external
          and public.cloudtalk_app_send_text(o.body) = v_msg.body
          and coalesce(o.first_attempt_at, o.created_at) between v_msg.occurred_at - interval '1 hour' and v_msg.occurred_at + interval '10 minutes'
        union all
        select 1 from public.outbound_deliveries d
        where d.channel = 'SMS'::public.channel_type and d.message_id is not null
          and public.communication_recipient('SMS', d.recipient) = v_external
          and public.cloudtalk_app_send_text(d.payload->>'body') = v_msg.body
          and coalesce(d.leased_at, d.accepted_at, d.created_at) between v_msg.occurred_at - interval '1 hour' and v_msg.occurred_at + interval '10 minutes'
      ) app;
      if app_sends > 0 then
        select count(*) into echo_rank from public.cloudtalk_messages m
        where m.direction = 'outbound' and m.body = v_msg.body
          and public.communication_recipient('SMS', m.external_number) = v_external
          and m.occurred_at between v_msg.occurred_at - interval '70 minutes' and v_msg.occurred_at
          and (m.occurred_at, m.message_id) <= (v_msg.occurred_at, v_msg.message_id);
        if echo_rank <= app_sends then return null; end if;
      end if;
    end if;
    v_body := case when btrim(v_msg.body) = '' then '[' || upper(v_msg.channel) || ' with no text. Open CloudTalk to view attachments.]'
      else public.redact_private_capabilities(v_msg.body) end;
    v_at := v_msg.occurred_at;
  else
    select * into v_call from public.cloudtalk_calls where call_uuid = substr(p_resource_id, 6);
    -- Partial AI/recording rows and unowned numbers are never shown alone.
    if not found or v_call.ended_at is null or not v_call.trusted_number then return null; end if;
    v_direction := case lower(coalesce(v_call.direction, '')) when 'incoming' then 'inbound' when 'inbound' then 'inbound'
      when 'outgoing' then 'outbound' when 'outbound' then 'outbound' end;
    if v_direction is null then return null; end if; -- internal and monitor legs are not client contact
    v_channel := case when v_call.is_voicemail then 'VOICEMAIL' when v_direction = 'inbound' then 'CALL_INBOUND' else 'CALL_OUTBOUND' end;
    v_external := public.communication_recipient('SMS', v_call.external_number);
    v_internal := public.communication_recipient('SMS', v_call.internal_number);
    answered_seconds := coalesce(v_call.talking_seconds, v_call.duration_seconds);
    v_body := case
      when v_call.is_voicemail then 'Voicemail'
      when v_call.talking_seconds = 0 and v_direction = 'inbound' then 'Missed incoming call'
      when v_call.talking_seconds = 0 then 'Outgoing call, not answered'
      when v_direction = 'inbound' then 'Incoming call'
      else 'Outgoing call' end
      || coalesce(' · ' || public.cloudtalk_duration_text(case when v_call.is_voicemail then v_call.duration_seconds when v_call.talking_seconds = 0 then null else answered_seconds end), '');
    v_at := coalesce(v_call.started_at, v_call.ended_at);
  end if;

  -- Same per-number lock as email/SMS ingestion so matching is serialized.
  perform pg_advisory_xact_lock(hashtextextended('SMS:' || coalesce(v_external, 'withheld'), 936));
  select * into result from public.communication_inbound where provider = 'cloudtalk' and resource_id = p_resource_id;
  if found then return result.id; end if;

  -- Exact normalized household match only; shared or unknown numbers stay in review.
  if v_external is not null then
    select count(*), (array_agg(c.id))[1] into matches, v_client
    from public.clients c where public.communication_recipient('SMS', c.primary_phone) = v_external;
    if matches <> 1 then v_client := null; end if;
  end if;
  if v_client is not null then
    perform pg_advisory_xact_lock(hashtextextended('conversation:' || v_client::text, 950));
    select count(*), (array_agg(c.id))[1] into matches, v_conversation
    from public.conversations c where c.client_id = v_client and c.status = 'ACTIVE';
    if matches > 1 then v_conversation := null;
    elsif matches = 0 then insert into public.conversations(client_id) values (v_client) returning id into v_conversation;
    end if;
  end if;

  if v_conversation is not null then
    insert into public.messages(conversation_id, type, sender_type, content, is_internal, provider, provider_message_id, created_at)
    values (v_conversation, v_channel::public.message_type, case when v_direction = 'inbound' then 'CLIENT' else 'STAFF' end::public.sender_type,
      v_body, false, 'cloudtalk', p_resource_id, v_at)
    returning id into v_message;
    update public.conversations set
      last_message_at = greatest(coalesce(last_message_at, v_at), v_at),
      is_read = case when v_direction = 'inbound' then false else is_read end
    where id = v_conversation;
  end if;

  insert into public.communication_inbound(provider, resource_id, event_id, channel, direction, sender, recipient, subject, body, occurred_at,
    client_id, conversation_id, message_id, review_reason)
  values ('cloudtalk', p_resource_id, null, v_channel, v_direction,
    coalesce(case when v_direction = 'inbound' then v_external else v_internal end, 'withheld'),
    coalesce(case when v_direction = 'inbound' then v_internal else v_external end, 'withheld'),
    '', v_body, v_at, v_client, v_conversation, v_message,
    case when v_external is null then 'Caller number withheld' when v_client is null then 'Unknown or shared sender'
      when v_conversation is null then 'Multiple possible conversation threads' end)
  returning * into result;
  delete from public.cloudtalk_projection_failures where resource_id = p_resource_id;
  return result.id;
end $$

-- Redacts capabilities already stored in CloudTalk originals and re-projects the
-- affected texts, clearing the failures their tokens caused. Idempotent: a
-- second run finds nothing to change and returns 0. Owner-only; the migration
-- runs it once. communication_inbound, messages and cloudtalk_projection_failures
-- need no redaction: the first two refused tokens via
-- reject_persisted_document_capability and the third never stores content.
create function public.redact_stored_cloudtalk_capabilities() returns integer
language plpgsql security definer set search_path = public as $$
declare message_ids text[]; call_count integer; source text;
begin
  with changed as (
    update public.cloudtalk_messages set body = public.redact_private_capabilities(body)
    where body is distinct from public.redact_private_capabilities(body)
    returning message_id, occurred_at
  ) select coalesce(array_agg(message_id order by occurred_at, message_id), '{}') into message_ids from changed;
  with changed as (
    update public.cloudtalk_calls set ai_summary = public.redact_private_capabilities(ai_summary)
    where ai_summary is distinct from public.redact_private_capabilities(ai_summary)
    returning call_uuid
  ), audited as (
    insert into public.cloudtalk_capability_redactions(source, field) select 'call:' || call_uuid, 'ai_summary' from changed returning 1
  ) select count(*) into call_count from audited;
  foreach source in array message_ids loop
    perform public.project_cloudtalk_source_safely('message:' || source);
  end loop;
  return cardinality(message_ids) + call_count;
end $$

-- Fail closed if a capability ever reaches a CloudTalk original unredacted.
create trigger reject_document_capability before insert or update on public.cloudtalk_messages
  for each row execute function public.reject_persisted_document_capability()

-- Estimate lifecycle summary for display. The publication and decision
-- workspaces remain authoritative (they verify the hash chains); this only
-- reports where an estimate stands so staff know whether it needs attention.
create function public.patient_360_estimate_status_internal(p_estimate_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  pub public.native_estimate_publication_events;
  choice text;
  expires timestamptz;
  total text;
  state text;
begin
  select r.document->>'total_cents' into total from public.native_estimate_draft_revisions r
  where r.estimate_id = p_estimate_id order by r.version desc limit 1;
  select * into pub from public.native_estimate_publication_events e
  where e.estimate_id = p_estimate_id order by e.version desc limit 1;
  if pub.id is null then
    state := 'draft';
  elsif pub.document->>'kind' = 'withdrawn' then
    state := 'withdrawn';
  else
    select d.document->>'choice' into choice from public.native_estimate_decisions d where d.publication_id = pub.id;
    expires := case when pub.document #>> '{publication,expires_at}' ~ '^\d{4}-' then (pub.document #>> '{publication,expires_at}')::timestamptz end;
    state := case choice when 'accept' then 'accepted' when 'decline' then 'declined'
      else case when expires is not null and expires <= now() then 'expired' else 'awaiting_decision' end end;
  end if;
  return jsonb_build_object('status', state, 'publication_id', pub.id, 'published_at', case when pub.document->>'kind' = 'published' then pub.created_at end,
    'expires_at', expires, 'total_cents', total);
end $$

create function public.patient_360_header_internal(p_client_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients;
  consent jsonb;
begin
  select * into c from public.clients where id = p_client_id;
  consent := public.current_sms_consent(p_client_id);
  return jsonb_build_object(
    'household', jsonb_build_object('id', c.id, 'full_name', c.full_name, 'first_name', c.first_name, 'last_name', c.last_name,
      'primary_phone', c.primary_phone, 'primary_email', c.primary_email, 'preferred_channel', c.preferred_channel,
      'housecall_address', c.housecall_address, 'mailing_address', c.mailing_address),
    'pets', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'species', p.species, 'breed', p.breed,
        'archived_at', p.archived_at, 'deceased_at', p.deceased_at, 'allergies', nullif(trim(p.allergies), '')) order by (p.archived_at is not null or p.deceased_at is not null), p.name, p.id)
      from public.pets p where p.client_id = p_client_id), '[]'),
    'sms_consent', jsonb_build_object('opted_in', coalesce((consent->>'opted_in')::boolean, false), 'can_message', coalesce((consent->>'can_message')::boolean, false),
      'phone_number', consent->>'phone_number', 'updated_at', consent->>'updated_at'),
    'balance', (select jsonb_build_object('outstanding_cents', coalesce(sum(b.outstanding), 0)::text, 'open_invoice_count', count(*) filter (where b.outstanding > 0))
      from (select (public.payment_balance_internal(i.id)->>'outstanding_cents')::bigint outstanding
            from public.billing_invoices i where i.client_id = p_client_id and i.status = 'issued') b),
    'high_priority_problems', coalesce((select jsonb_agg(jsonb_build_object('id', pr.id, 'pet_id', pr.pet_id, 'pet_name', p.name, 'title', pr.title) order by p.name, pr.title, pr.id)
      from public.patient_problems pr join public.pets p on p.id = pr.pet_id
      where p.client_id = p_client_id and pr.status = 'active' and pr.importance = 'high'), '[]')
  );
end $$

create function public.read_patient_360(p_patient_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  actor uuid := public.clinical_require_staff();
  pet public.pets;
  header jsonb;
begin
  if p_patient_id is null then raise exception 'Patient required' using errcode = '23514'; end if;
  select * into pet from public.pets where id = p_patient_id;
  if not found then raise exception 'Patient not found' using errcode = 'P0002'; end if;
  header := public.patient_360_header_internal(pet.client_id);
  return jsonb_build_object('version', 1, 'scope', 'patient', 'actor_id', actor, 'generated_at', now(),
    'patient', jsonb_build_object('id', pet.id, 'client_id', pet.client_id, 'name', pet.name, 'species', pet.species, 'breed', pet.breed,
      'sex', pet.sex, 'neuter_status', pet.neuter_status, 'dob', pet.dob, 'birth_date_precision', pet.birth_date_precision, 'color', pet.color,
      'microchip_id', pet.microchip_id, 'allergies', nullif(trim(pet.allergies), ''), 'archived_at', pet.archived_at, 'deceased_at', pet.deceased_at,
      'active_problem_count', (select count(*) from public.patient_problems pr where pr.pet_id = pet.id and pr.status = 'active')),
    'household', header->'household', 'pets', header->'pets', 'sms_consent', header->'sms_consent', 'balance', header->'balance',
    'high_priority_problems', coalesce((select jsonb_agg(x) from jsonb_array_elements(header->'high_priority_problems') x where x->>'pet_id' = pet.id::text), '[]'),
    'signals', public.patient_360_signals_internal(pet.client_id, pet.id));
end $$

create function public.read_household_360(p_client_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  actor uuid := public.clinical_require_staff();
  header jsonb;
begin
  if p_client_id is null then raise exception 'Household required' using errcode = '23514'; end if;
  if not exists(select 1 from public.clients where id = p_client_id) then raise exception 'Household not found' using errcode = 'P0002'; end if;
  header := public.patient_360_header_internal(p_client_id);
  return jsonb_build_object('version', 1, 'scope', 'household', 'actor_id', actor, 'generated_at', now(), 'patient', null,
    'household', header->'household', 'pets', header->'pets', 'sms_consent', header->'sms_consent', 'balance', header->'balance',
    'high_priority_problems', header->'high_priority_problems',
    'signals', public.patient_360_signals_internal(p_client_id, null));
end $$

create function public.list_patient_timeline(p_patient_id uuid, p_kinds text[] default null, p_before_at timestamptz default null, p_before_key text default null, p_limit integer default 25)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare household uuid;
begin
  perform public.clinical_require_staff();
  if p_patient_id is null then raise exception 'Patient required' using errcode = '23514'; end if;
  select client_id into household from public.pets where id = p_patient_id;
  if not found then raise exception 'Patient not found' using errcode = 'P0002'; end if;
  return public.patient_360_timeline_internal(household, p_patient_id, p_kinds, p_before_at, p_before_key, p_limit);
end $$

create function public.list_household_timeline(p_client_id uuid, p_kinds text[] default null, p_before_at timestamptz default null, p_before_key text default null, p_limit integer default 25)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.clinical_require_staff();
  if p_client_id is null then raise exception 'Household required' using errcode = '23514'; end if;
  if not exists(select 1 from public.clients where id = p_client_id) then raise exception 'Household not found' using errcode = 'P0002'; end if;
  return public.patient_360_timeline_internal(p_client_id, null, p_kinds, p_before_at, p_before_key, p_limit);
end $$

revoke all on function public.patient_360_estimate_status_internal(uuid), public.patient_360_signals_internal(uuid, uuid),
