 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result public.patient_documents;
begin
 perform public.clinical_require_staff();
 if p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'A void reason is required (maximum 2000 characters)' using errcode='23514'; end if;
 update public.patient_documents set status='void',void_reason=trim(p_reason) where id=p_id and version=p_expected_version and status='ready' returning * into result;
 if not found then raise exception 'Record changed or no longer exists; reload before voiding' using errcode='PT409'; end if;
 return result;
end $function$

-- Deploy-time guard: no function in the public schema may raise or catch a SQLSTATE that
-- PostgREST retries automatically.
do $guard$
declare offenders text;
begin
  select string_agg(p.oid::regprocedure::text, ', ' order by 1) into offenders
  from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public' and p.prosrc ~ '40001|40P01';
  if offenders is not null then
    raise exception 'Functions still use a PostgREST-retryable SQLSTATE (40001/40P01): %', offenders;
  end if;
end
$guard$

-- ---------------------------------------------------------------------------
-- Internal helpers. Callers hold pg_advisory_xact_lock(hashtextextended('SMS:'||phone,936)),
-- the lock record_sms_consent and the Twilio inbound path already use for a number.

-- Write (or refresh) an opt-out suppression and audit it. Only opt-out kinds are replaced;
-- carrier, complaint and manual suppressions are kept as they are.
create function public.sms_record_opt_out_internal(
  p_recipient text, p_reason text, p_source text, p_occurred_at timestamptz, p_client_id uuid,
  p_provider text, p_provider_message_id text, p_actor_id uuid
) returns boolean language plpgsql set search_path = public as $$
declare written boolean;
begin
  insert into public.communication_suppressions(channel, recipient, reason, created_by, occurred_at, provider, provider_message_id)
  values ('SMS', p_recipient, p_reason, p_actor_id, p_occurred_at, p_provider, p_provider_message_id)
  on conflict (channel, recipient) do update set
    reason = excluded.reason, created_by = excluded.created_by, created_at = now(),
    occurred_at = excluded.occurred_at, provider = excluded.provider, provider_message_id = excluded.provider_message_id
  where communication_suppressions.reason in ('cloudtalk_sms_stop', 'provider_sms_stop', 'staff_sms_opt_out')
    and excluded.occurred_at >= coalesce(communication_suppressions.occurred_at, communication_suppressions.created_at);
  written := found;
  if written then
    insert into public.sms_suppression_events(recipient, action, source, keyword, suppression_reason, client_id, provider, provider_message_id, actor_id, occurred_at)
    values (p_recipient, 'suppressed', p_source, case when p_source = 'sms_keyword' then 'STOP' end, p_reason, p_client_id, p_provider, p_provider_message_id, p_actor_id, p_occurred_at)
    on conflict (provider, provider_message_id) where provider_message_id is not null do nothing;
  end if;
  return written;
end $$

-- Lift an opt-out suppression that began before p_occurred_at. A START keyword lifts only a
-- STOP-keyword suppression; explicit staff consent also lifts a staff opt-out. Anything else
-- (bounce, complaint, manual do-not-text) keeps blocking.
create function public.sms_lift_opt_out_internal(
  p_recipient text, p_source text, p_occurred_at timestamptz, p_client_id uuid,
  p_provider text, p_provider_message_id text, p_actor_id uuid, p_note text default null
) returns boolean language plpgsql set search_path = public as $$
declare s public.communication_suppressions; since timestamptz;
begin
  select * into s from public.communication_suppressions where channel = 'SMS' and recipient = p_recipient for update;
  if not found then return false; end if;
  if not (s.reason in ('cloudtalk_sms_stop', 'provider_sms_stop') or (p_source = 'staff_consent' and s.reason = 'staff_sms_opt_out')) then
    return false;
  end if;
  since := coalesce(s.occurred_at, s.created_at);
  -- Only a keyword that arrived after the STOP counts. Staff consent is recorded now and so
  -- always follows the suppression it reviews.
  if p_occurred_at < since or (p_source = 'sms_keyword' and p_occurred_at = since) then return false; end if;
  insert into public.sms_suppression_events(recipient, action, source, keyword, suppression_reason, suppressed_at, client_id, provider, provider_message_id, actor_id, note, occurred_at)
  values (p_recipient, 'lifted', p_source, case when p_source = 'sms_keyword' then 'START' end, s.reason, since, p_client_id, p_provider, p_provider_message_id, p_actor_id, p_note, p_occurred_at)
  on conflict (provider, provider_message_id) where provider_message_id is not null do nothing;
  if not found then return false; end if;
  delete from public.communication_suppressions where channel = 'SMS' and recipient = p_recipient;
  return true;
end $$

-- START keyword: lift, then restore consent for an unambiguous household unless a newer
-- consent decision already exists. Shared numbers stay blocked for staff review.
create function public.sms_apply_start_keyword_internal(
  p_recipient text, p_occurred_at timestamptz, p_provider text, p_provider_message_id text, p_note text default null
) returns boolean language plpgsql set search_path = public as $$
declare matches integer; household uuid; withdrawn_at timestamptz; details text;
begin
  select count(*), (array_agg(c.id))[1] into matches, household from public.clients c
  where public.communication_recipient('SMS', c.primary_phone) = p_recipient;
  -- A staff withdrawal recorded after this START occurred wins.
  select max(opted_out_at) into withdrawn_at from public.sms_consent where public.communication_recipient('SMS', phone_number) = p_recipient;
  if withdrawn_at is not null and p_occurred_at <= withdrawn_at then return false; end if;
  if not public.sms_lift_opt_out_internal(p_recipient, 'sms_keyword', p_occurred_at, case when matches = 1 then household end,
      p_provider, p_provider_message_id, null, p_note) then
    return false;
  end if;
  if matches = 1 then
    details := 'Client replied START by SMS (' || p_provider || ' message ' || p_provider_message_id || ')';
    update public.sms_consent set opted_in = true, opted_in_at = p_occurred_at, opted_out_at = null,
      consent_method = 'SMS_KEYWORD', consent_details = details
    where client_id = household and public.communication_recipient('SMS', phone_number) = p_recipient
      and not opted_in and coalesce(opted_out_at, '-infinity'::timestamptz) < p_occurred_at;
    if not exists (select 1 from public.sms_consent where client_id = household and public.communication_recipient('SMS', phone_number) = p_recipient) then
      insert into public.sms_consent(client_id, phone_number, opted_in, opted_in_at, consent_method, consent_details)
      values (household, p_recipient, true, p_occurred_at, 'SMS_KEYWORD', details);
    end if;
  end if;
  return true;
end $$

-- ---------------------------------------------------------------------------
-- CloudTalk ingest: same contract as 20260928110000, with STOP audited and START honored.

create or replace function public.ingest_cloudtalk_event(
  p_event_id text, p_event_type text, p_occurred_at timestamptz, p_data jsonb
) returns boolean language plpgsql security definer set search_path = public as $$
declare
  call_key text;
  number_internal text;
  number_external text;
  message_key text;
  keyword text;
  sender text;
begin
  perform public.communication_require_service();
  if p_event_id is null or length(p_event_id) not between 1 and 200
    or p_event_type not in ('call.ended', 'call.recording_ready', 'transcript.ready', 'cidata.ready', 'message.sent', 'message.received')
    or p_occurred_at is null or p_occurred_at > now() + interval '5 minutes'
    or p_data is null or jsonb_typeof(p_data) <> 'object'
    or octet_length(p_data::text) > 262144 then
    raise exception 'Invalid CloudTalk event' using errcode = '23514';
  end if;
  insert into public.cloudtalk_events(event_id, event_type, occurred_at)
  values(p_event_id, p_event_type, p_occurred_at) on conflict do nothing;
  if not found then return false; end if;

  if p_event_type like 'call.%' or p_event_type in ('transcript.ready', 'cidata.ready') then
    call_key := p_data->>'call_uuid';
    if call_key is null or length(call_key) not between 1 and 200 then
      raise exception 'Invalid CloudTalk call' using errcode = '23514';
    end if;
    number_external := p_data->>'external_number';
    number_internal := p_data#>>'{internal_number,number_e164}';
    insert into public.cloudtalk_calls(
      call_uuid, call_id, direction, external_number, internal_number,
      started_at, ended_at, duration_seconds, talking_seconds, is_voicemail, recording_ready,
      transcript_ready, ai_summary, ai_language, trusted_number, last_event_at
    ) values (
      call_key, p_data->>'call_id', p_data->>'direction', number_external, number_internal,
      nullif(p_data->>'started_at', '')::timestamptz,
      nullif(p_data->>'ended_at', '')::timestamptz,
      case when (p_data->>'duration') ~ '^[0-9]{1,8}$' then (p_data->>'duration')::integer end,
      case when p_event_type = 'call.ended' and (p_data->>'talking_time') ~ '^[0-9]{1,8}$' then (p_data->>'talking_time')::integer end,
      coalesce((p_data->>'is_voicemail')::boolean, false),
      p_event_type = 'call.recording_ready',
      p_event_type = 'transcript.ready',
      case when p_event_type = 'cidata.ready' then left(p_data#>>'{summary,summary}', 10000) end,
      case when p_event_type in ('transcript.ready', 'cidata.ready') then left(p_data->>'language', 20) end,
      p_event_type = 'call.ended',
      p_occurred_at
    ) on conflict(call_uuid) do update set
      call_id = coalesce(excluded.call_id, cloudtalk_calls.call_id),
      direction = coalesce(excluded.direction, cloudtalk_calls.direction),
      external_number = coalesce(excluded.external_number, cloudtalk_calls.external_number),
      internal_number = coalesce(excluded.internal_number, cloudtalk_calls.internal_number),
      started_at = coalesce(excluded.started_at, cloudtalk_calls.started_at),
      ended_at = coalesce(excluded.ended_at, cloudtalk_calls.ended_at),
      duration_seconds = coalesce(excluded.duration_seconds, cloudtalk_calls.duration_seconds),
      talking_seconds = coalesce(excluded.talking_seconds, cloudtalk_calls.talking_seconds),
      is_voicemail = excluded.is_voicemail or cloudtalk_calls.is_voicemail,
      recording_ready = excluded.recording_ready or cloudtalk_calls.recording_ready,
      transcript_ready = excluded.transcript_ready or cloudtalk_calls.transcript_ready,
      ai_summary = coalesce(excluded.ai_summary, cloudtalk_calls.ai_summary),
      ai_language = coalesce(excluded.ai_language, cloudtalk_calls.ai_language),
      trusted_number = excluded.trusted_number or cloudtalk_calls.trusted_number,
      last_event_at = greatest(excluded.last_event_at, cloudtalk_calls.last_event_at);
  else
    message_key := p_data->>'id';
    number_external := p_data->>'external_number';
    number_internal := p_data#>>'{internal_number,number_e164}';
    if message_key is null or length(message_key) not between 1 and 200
      or public.communication_recipient('SMS', number_external) is null
      or public.communication_recipient('SMS', number_internal) is null
      or p_data->>'channel' not in ('sms', 'mms', 'whatsapp')
      or length(coalesce(p_data->>'body', '')) > 100000 then
      raise exception 'Invalid CloudTalk message' using errcode = '23514';
    end if;
    insert into public.cloudtalk_messages(
      message_id, direction, channel, external_number, internal_number, body, occurred_at
    ) values (
      message_key, case when p_event_type = 'message.received' then 'inbound' else 'outbound' end,
      p_data->>'channel', number_external, number_internal, coalesce(p_data->>'body', ''), p_occurred_at
    ) on conflict(message_id) do nothing;
    keyword := case when p_event_type = 'message.received' and p_data->>'channel' = 'sms' then public.sms_keyword(p_data->>'body') end;
    if keyword in ('STOP', 'START') then
      sender := public.communication_recipient('SMS', number_external);
      perform pg_advisory_xact_lock(hashtextextended('SMS:' || sender, 936));
    end if;
    -- A signed inbound STOP blocks any future SMS request, including one queued before the
    -- message arrived, unless the client already resumed texting after it (a delayed STOP
    -- webhook must not undo a later START or staff re-consent).
    if keyword = 'STOP' and not exists (
        select 1 from public.sms_suppression_events e
        where e.recipient = sender and e.action = 'lifted' and e.occurred_at > p_occurred_at) then
      perform public.sms_record_opt_out_internal(sender, 'cloudtalk_sms_stop', 'sms_keyword', p_occurred_at, null, 'cloudtalk', message_key, null);
      update public.sms_consent set opted_in = false, opted_out_at = greatest(coalesce(opted_out_at, p_occurred_at), p_occurred_at)
      where public.communication_recipient('SMS', phone_number) = sender;
      update public.communication_outbox set state = 'failed', last_error = 'recipient_suppressed', updated_at = now()
      where channel = 'SMS' and recipient = sender and state = 'pending';
      update public.outbound_deliveries set status = 'CANCELED', canceled_at = now(), updated_at = now(), status_note = 'Recipient sent STOP to CloudTalk'
      where channel = 'SMS' and recipient = sender and status = 'QUEUED';
    elsif keyword = 'START' then
      -- START / UNSTOP / YES after a STOP from this number resumes texting (CTIA).
      perform public.sms_apply_start_keyword_internal(sender, p_occurred_at, 'cloudtalk', message_key);
    end if;
  end if;
  return true;
end $$

-- ---------------------------------------------------------------------------
-- Staff consent: same contract as 20260928190000, plus audited lifting of STOP-type
-- suppressions on explicit agreement and audited re-suppression on withdrawal.

create or replace function public.record_sms_consent(p_actor_id uuid, p_client_id uuid, p_phone text, p_opted_in boolean, p_method public.consent_method, p_details text, p_expected_updated_at timestamptz default null)
returns public.sms_consent language plpgsql security definer set search_path = public as $$
declare actor uuid;normalized_phone text;latest timestamptz;result public.sms_consent;
begin
 actor:=public.clinical_require_staff();if actor is distinct from p_actor_id then raise exception 'Actor mismatch' using errcode='42501';end if;
 normalized_phone:=public.communication_recipient('SMS',p_phone);
 if normalized_phone is null or p_opted_in is null or p_method is null or p_method not in ('VERBAL','WRITTEN','WEB_FORM') or p_details is null or length(trim(p_details)) not between 5 and 1000 or not exists(select 1 from public.clients where id=p_client_id and public.communication_recipient('SMS',primary_phone)=normalized_phone) then raise exception 'Matching household number and documented consent method required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('SMS:'||normalized_phone,936));
 if p_opted_in and (select count(*) from public.clients where public.communication_recipient('SMS',primary_phone)=normalized_phone)<>1 then raise exception 'Shared phone numbers require separate consent review' using errcode='23514';end if;
 select max(updated_at) into latest from public.sms_consent where client_id=p_client_id and public.communication_recipient('SMS',phone_number)=normalized_phone;
 if latest is distinct from p_expected_updated_at then raise exception 'Consent changed; reload before saving' using errcode='PT409';end if;
 insert into public.sms_consent(client_id,phone_number,opted_in,opted_in_at,opted_out_at,consent_method,consent_details)
 values(p_client_id,normalized_phone,p_opted_in,case when p_opted_in then now() else null end,case when not p_opted_in then now() else null end,p_method,trim(p_details))
 on conflict(client_id,phone_number) do update set opted_in=excluded.opted_in,opted_in_at=excluded.opted_in_at,opted_out_at=excluded.opted_out_at,consent_method=excluded.consent_method,consent_details=excluded.consent_details;
 update public.sms_consent set opted_in=p_opted_in,opted_in_at=case when p_opted_in then now() else null end,opted_out_at=case when not p_opted_in then now() else null end,consent_method=p_method,consent_details=trim(p_details)
 where client_id=p_client_id and public.communication_recipient('SMS',phone_number)=normalized_phone;
 if p_opted_in then
  -- Explicit, evidenced agreement lifts a STOP reply or staff opt-out; never carrier,
  -- complaint or manual suppressions.
  perform public.sms_lift_opt_out_internal(normalized_phone,'staff_consent',now(),p_client_id,null,null,actor,null);
 else
  perform public.sms_record_opt_out_internal(normalized_phone,'staff_sms_opt_out','staff_withdrawal',now(),p_client_id,null,null,actor);
  update public.communication_outbox set state='failed',last_error='recipient_suppressed' where channel='SMS' and communication_outbox.recipient=normalized_phone and state='pending';
 end if;
 select * into result from public.sms_consent where client_id=p_client_id and phone_number=normalized_phone;
 return result;
end $$

-- ---------------------------------------------------------------------------
-- Consent display: why texting is blocked and how it last resumed.

create or replace function public.current_sms_consent(p_client_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare phone text; selected public.sms_consent; result jsonb; s public.communication_suppressions; lift public.sms_suppression_events;
 lifted_by text; can boolean; block text; since timestamptz;
begin
 perform public.clinical_require_staff();
 select public.communication_recipient('SMS',primary_phone) into phone from public.clients where id=p_client_id;
 if not found then raise exception 'Household not found' using errcode='P0002'; end if;
 select * into selected from public.sms_consent where client_id=p_client_id and public.communication_recipient('SMS',phone_number)=phone order by updated_at desc,id desc limit 1;
 result:=case when selected.id is null then jsonb_build_object('id',null,'client_id',p_client_id,'phone_number',phone,'opted_in',false,'updated_at',null) else to_jsonb(selected) end;
 can:=phone is not null and not public.communication_is_suppressed('SMS',phone,p_client_id);
 if phone is not null then
  select * into s from public.communication_suppressions where channel='SMS' and recipient=phone;
  select * into lift from public.sms_suppression_events where recipient=phone and action='lifted' order by occurred_at desc,created_at desc,id desc limit 1;
  if lift.actor_id is not null then
   select coalesce(nullif(btrim(p.full_name),''),nullif(btrim(p.first_name||' '||p.last_name),'')) into lifted_by from public.profiles p where p.id=lift.actor_id;
  end if;
 end if;
 if not can then
  if phone is null then block:='no_phone';
  elsif s.recipient is not null then
   since:=coalesce(s.occurred_at,s.created_at);
   block:=case when s.reason in ('cloudtalk_sms_stop','provider_sms_stop') then 'sms_stop'
    when s.reason='staff_sms_opt_out' then 'staff_opt_out'
    when s.reason in ('provider_bounced','provider_failed','provider_undelivered') then 'undeliverable'
    when s.reason='provider_complained' then 'complaint'
    else 'suppressed' end;
  elsif exists(select 1 from public.communication_provider_events where provider='twilio' and event_type='inbound' and state in ('pending','claimed','review') and metadata->>'opt_action'='STOP' and metadata->>'from'=phone) then
   block:='sms_stop';
  elsif (select count(*) from public.clients where public.communication_recipient('SMS',primary_phone)=phone)>1 then block:='shared_phone';
  elsif selected.id is not null and not selected.opted_in and selected.opted_out_at is not null then block:='consent_withdrawn';since:=selected.opted_out_at;
  else block:='consent_missing';
  end if;
 end if;
 return result || jsonb_build_object('can_message',can,'block_reason',block,'blocked_since',since,
  'last_resumed',case when lift.id is null then null else jsonb_build_object('source',lift.source,'keyword',lift.keyword,'at',lift.occurred_at,
   'by',case when lift.source='staff_consent' then lifted_by end,'after_reason',lift.suppression_reason,'after_since',lift.suppressed_at) end);
end $$

-- Patient 360 header: same contract as 20260928170000, plus the consent explanation.
create or replace function public.patient_360_header_internal(p_client_id uuid) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  c public.clients;
  consent jsonb;
begin
  select * into c from public.clients where id = p_client_id;
  consent := public.current_sms_consent(p_client_id);
  return jsonb_build_object(
    'household', jsonb_build_object('id', c.id, 'full_name', c.full_name, 'first_name', c.first_name, 'last_name', c.last_name,
      'primary_phone', c.primary_phone, 'primary_email', c.primary_email, 'preferred_channel', c.preferred_channel,
      'housecall_address', c.housecall_address, 'mailing_address', c.mailing_address),
    'pets', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'species', p.species, 'breed', p.breed,
        'archived_at', p.archived_at, 'deceased_at', p.deceased_at, 'allergies', nullif(trim(p.allergies), '')) order by (p.archived_at is not null or p.deceased_at is not null), p.name, p.id)
      from public.pets p where p.client_id = p_client_id), '[]'),
    'sms_consent', jsonb_build_object('opted_in', coalesce((consent->>'opted_in')::boolean, false), 'can_message', coalesce((consent->>'can_message')::boolean, false),
      'phone_number', consent->>'phone_number', 'updated_at', consent->>'updated_at',
      'block_reason', consent->'block_reason', 'blocked_since', consent->'blocked_since', 'last_resumed', consent->'last_resumed'),
    'balance', (select jsonb_build_object('outstanding_cents', coalesce(sum(b.outstanding), 0)::text, 'open_invoice_count', count(*) filter (where b.outstanding > 0))
      from (select (public.payment_balance_internal(i.id)->>'outstanding_cents')::bigint outstanding
            from public.billing_invoices i where i.client_id = p_client_id and i.status = 'issued') b),
    'high_priority_problems', coalesce((select jsonb_agg(jsonb_build_object('id', pr.id, 'pet_id', pr.pet_id, 'pet_name', p.name, 'title', pr.title) order by p.name, pr.title, pr.id)
      from public.patient_problems pr join public.pets p on p.id = pr.pet_id
      where p.client_id = p_client_id and pr.status = 'active' and pr.importance = 'high'), '[]')
  );
end $$

-- ---------------------------------------------------------------------------
-- Reconcile existing STOP suppressions (production had STOP -> START -> staff consent).

create function public.sms_reconcile_opt_outs_internal() returns integer
language plpgsql set search_path = public as $$
declare lifted integer := 0; s record; stop_at timestamptz; stop_id text; start_at timestamptz; start_id text;
  consent_id uuid; consent_client uuid; consent_at timestamptz; actor uuid;
begin
  for s in select * from public.communication_suppressions
    where channel = 'SMS' and reason in ('cloudtalk_sms_stop', 'provider_sms_stop') order by recipient
  loop
    perform pg_advisory_xact_lock(hashtextextended('SMS:' || s.recipient, 936));
    stop_at := null; stop_id := null; start_at := null; start_id := null;
    consent_id := null; consent_client := null; consent_at := null; actor := null;
    if s.occurred_at is not null then
      stop_at := s.occurred_at;
    else
      -- Legacy row: date the opt-out by the latest inbound STOP message from that number.
      select m.occurred_at, m.message_id into stop_at, stop_id from public.cloudtalk_messages m
      where m.direction = 'inbound' and m.channel = 'sms' and public.communication_recipient('SMS', m.external_number) = s.recipient
        and public.sms_keyword(m.body) = 'STOP' and m.occurred_at <= s.created_at + interval '5 minutes'
      order by m.occurred_at desc, m.message_id desc limit 1;
      stop_at := coalesce(stop_at, s.created_at);
      update public.communication_suppressions set occurred_at = stop_at,
        provider = case when stop_id is not null then 'cloudtalk' end, provider_message_id = stop_id
      where channel = 'SMS' and recipient = s.recipient;
    end if;

    -- 1. A START / UNSTOP / YES keyword after the STOP.
    select m.occurred_at, m.message_id into start_at, start_id from public.cloudtalk_messages m
    where m.direction = 'inbound' and m.channel = 'sms' and public.communication_recipient('SMS', m.external_number) = s.recipient
      and public.sms_keyword(m.body) = 'START' and m.occurred_at > stop_at
    order by m.occurred_at desc, m.message_id desc limit 1;
    if start_id is not null and public.sms_apply_start_keyword_internal(s.recipient, start_at, 'cloudtalk', start_id,
        'Reconciled by migration 20260930100000') then
      lifted := lifted + 1;
      continue;
    end if;

    -- 2. Explicit staff consent recorded after the STOP (the consent saved but the STOP kept blocking).
    select c.id, c.client_id, c.opted_in_at into consent_id, consent_client, consent_at from public.sms_consent c
    where public.communication_recipient('SMS', c.phone_number) = s.recipient and c.opted_in
      and c.consent_method in ('VERBAL', 'WRITTEN', 'WEB_FORM') and c.opted_in_at > stop_at
      and (select count(*) from public.clients k where public.communication_recipient('SMS', k.primary_phone) = s.recipient) = 1
    order by c.opted_in_at desc limit 1;
    if consent_id is not null then
      select a.user_id into actor from public.audit_logs a
      where a.table_name = 'sms_consent' and a.record_id = consent_id and a.user_id is not null
        and exists (select 1 from auth.users u where u.id = a.user_id)
      order by a.created_at desc limit 1;
      if public.sms_lift_opt_out_internal(s.recipient, 'staff_consent', consent_at, consent_client, null, null, actor,
          'Reconciled by migration 20260930100000') then
        lifted := lifted + 1;
      end if;
    end if;
  end loop;
  return lifted;
end $$

do $$
declare t text;
begin
  -- refill_requests is excluded: legacy_refill_read_only already refuses every
  -- insert/update (even privileged), so a NOT VALID FK there could never check
  -- a row; it would only leave a permanently unvalidated constraint.
  foreach t in array array['lab_results','consent_submissions','wellness_reminders','waitlist_entries','follow_up_instances'] loop
    execute format(
      'alter table public.%I add constraint %I foreign key (pet_id, client_id) references public.pets(id, client_id) deferrable initially immediate not valid',
      t, t || '_pet_household_fkey'
    );
  end loop;
end $$

-- Scheduler follow-up (2026-09-30 linkage audit, items B3 and B12).
--
-- B3. The scheduler's pg_net timeout was 5 s. Queue workers now process a
--     bounded batch per call (up to 25 items within a 20 s budget, see
--     supabase/functions/_shared/worker-batch.ts), and a single provider call
--     can legitimately take several seconds, so a 5 s timeout recorded healthy
--     batches as "request timed out" on the ops card. The timeout is raised to
--     30 s, which stays above the worker budget so an ordinary batch answers
--     before pg_net gives up. scheduler_dispatch is otherwise unchanged from
--     20260922120000_b1_scheduler.sql, its only previous definition.
--
-- B12. purge_expired_frozen_email_payloads (which runs both
--     purge_expired_release_email_payloads and purge_expired_invoice_email_payloads)
--     was documented as "a production daily operator/scheduled call is still
--     required" but nothing ever called it. It is now on the timetable once a
--     day. It is safe to run unattended: it only clears payload bytes older than
--     90 days for abandoned requests or provider-accepted/delivered sends with a
--     receipt, never pending, failed or uncertain sends; it keeps the manifest,
--     hashes and audit rows; it is bounded (100 rows per family per call) and
--     uses SKIP LOCKED. It runs in the database, so it does not go through
--     scheduler_dispatch (no HTTP, no Vault secret, no scheduler_job_runs row);
--     its outcome is in cron.job_run_details.
--
--     This is not apply_retention_policies(), which must never be scheduled
--     (B1 contract section 7). The b1 test asserts no cron command mentions
--     "retention"; the job below does not.

create or replace function public.scheduler_dispatch(p_job text) returns jsonb
language plpgsql security definer set search_path = public, extensions
as $$
declare
  _project_url text;
  _worker_key text;
  _run_id uuid;
  _request_id bigint;
  _missing text;
begin
  if p_job is null or p_job not in ('dispatch-outbox','process-inbound','process-stripe-events','queue-reminders','cleanup-abandoned-attachment') then
    raise exception 'Unknown scheduler job' using errcode = '22023';
  end if;

  select decrypted_secret into _project_url from vault.decrypted_secrets where name = 'project_url';
  select decrypted_secret into _worker_key from vault.decrypted_secrets where name = 'scheduler_worker_key';
  _missing := nullif(concat_ws(', ',
    case when _project_url is null then 'project_url' end,
    case when _worker_key is null then 'scheduler_worker_key' end), '');

  if _missing is not null then
    -- Recorded at most once an hour per job; see 20260922120000_b1_scheduler.sql.
    if not exists (
      select 1 from public.scheduler_job_results s
        join public.scheduler_job_runs r on r.id = s.run_id
       where r.job = p_job
         and s.outcome = 'configuration_missing'
         and s.recorded_at > now() - interval '1 hour'
    ) then
      insert into public.scheduler_job_runs(job, url_path) values (p_job, '/functions/v1/' || p_job) returning id into _run_id;
      insert into public.scheduler_job_results(run_id, outcome, error_message)
        values (_run_id, 'configuration_missing', 'Missing Vault secret(s): ' || _missing);
    end if;
    raise warning 'scheduler job % is installed but not configured; missing Vault secret(s): %', p_job, _missing;
    return jsonb_build_object('job', p_job, 'outcome', 'configuration_missing', 'missing', _missing, 'run_id', _run_id);
  end if;

  -- 30 s: above the workers' 20 s batch budget (B3).
  _request_id := net.http_post(
    url := _project_url || '/functions/v1/' || p_job,
    headers := jsonb_build_object('apikey', _worker_key, 'Content-Type', 'application/json'),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000);

  insert into public.scheduler_job_runs(job, url_path, request_id)
    values (p_job, '/functions/v1/' || p_job, _request_id) returning id into _run_id;

  return jsonb_build_object('job', p_job, 'outcome', 'dispatched', 'request_id', _request_id, 'run_id', _run_id);
end $$

-- The purge functions authorize with communication_require_service(), which
-- reads auth.role() from request.jwt.claims. A cron job runs as the database
-- owner with no claims, so this wrapper supplies the service role claim for
-- the duration of the call only and restores the previous value. It is
-- callable by no client role.
create function public.scheduler_purge_expired_email_payloads() returns jsonb
language plpgsql security definer set search_path = public
as $$
declare
  _previous text := current_setting('request.jwt.claims', true);
  _round jsonb;
  _releases integer := 0;
  _invoices integer := 0;
  _rounds integer := 0;
begin
  perform set_config('request.jwt.claims', '{"role":"service_role"}', true);
  -- Each call purges at most 100 rows per family. Repeat while a family filled
  -- its batch, bounded so one daily run cannot hold the job open indefinitely.
  loop
    _round := public.purge_expired_frozen_email_payloads(100);
    _rounds := _rounds + 1;
    _releases := _releases + (_round->>'record_release_payloads')::integer;
    _invoices := _invoices + (_round->>'invoice_payloads')::integer;
    exit when _rounds >= 20
      or ((_round->>'record_release_payloads')::integer < 100 and (_round->>'invoice_payloads')::integer < 100);
  end loop;
  perform set_config('request.jwt.claims', coalesce(_previous, ''), true);
  return jsonb_build_object('record_release_payloads', _releases, 'invoice_payloads', _invoices, 'rounds', _rounds);
end $$

-- Same pg_cron database guard as the B1 timetable: clones and scratch
-- databases used by the concurrency harnesses skip it.
do $$
declare
  _cron_database text := coalesce(current_setting('cron.database_name', true), 'postgres');
begin
  if current_database() <> _cron_database then
    raise notice 'Email payload purge job not created in %: pg_cron schedules in % only. This database is a clone or a scratch database.',
      current_database(), _cron_database;
    return;
  end if;

  create extension if not exists pg_cron;

  -- 09:17 UTC daily (03:17 Mountain in summer, 02:17 in winter): outside clinic hours.
  perform cron.schedule('purge-expired-email-payloads', '17 9 * * *',
    $cmd$select public.scheduler_purge_expired_email_payloads()$cmd$);
end $$

create function public.guard_client_required_contacts()
returns trigger language plpgsql set search_path=public as $$
begin
 if not public.client_contacts_complete(new.primary_phone,new.primary_email) then
  raise exception 'A valid phone number and email are both required for a client' using errcode='23514';
 end if;
 new.primary_phone := regexp_replace(btrim(new.primary_phone),'[ ().-]','','g');
 new.primary_email := lower(btrim(new.primary_email));
 return new;
end $$

create function public.guard_patient_complete_client()
returns trigger language plpgsql set search_path=public as $$
declare household public.clients;
begin
 if tg_op='UPDATE' and new.client_id is not distinct from old.client_id then return new;end if;
 -- Serialize this precondition with contact changes/deletion for the same household.
 select * into household from public.clients where id=new.client_id for share;
 if not found or not public.client_contacts_complete(household.primary_phone,household.primary_email) then
  raise exception 'Save an existing client with a valid phone number and email before adding a patient' using errcode='23514';
 end if;
 return new;
end $$

CREATE OR REPLACE FUNCTION public.save_client(p_actor_id uuid, p_client_id uuid, p_expected_version integer, p_first_name text, p_last_name text, p_primary_phone text, p_primary_email text, p_preferred_channel channel_type, p_mailing_address text, p_housecall_address text)
 RETURNS clients
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result public.clients; actor uuid;
begin
 actor := public.clinical_require_staff();
 if p_actor_id is distinct from actor then raise exception 'Actor does not match signed-in staff' using errcode='42501'; end if;
 if not public.client_contacts_complete(p_primary_phone,p_primary_email) then raise exception 'A valid phone number and email are both required for a client' using errcode='23514'; end if;
 p_primary_phone := public.communication_recipient('SMS',p_primary_phone);
 p_primary_email := public.communication_recipient('EMAIL',p_primary_email);
 if p_first_name is null or length(trim(p_first_name)) not between 1 and 150 or p_last_name is null or length(trim(p_last_name)) not between 1 and 150 or length(p_primary_phone)>50 or length(p_primary_email)>254 or length(p_mailing_address)>1000 or length(p_housecall_address)>1000 then raise exception 'Client fields are missing or too long' using errcode='23514'; end if;
 if nullif(trim(p_primary_email),'') is not null and p_primary_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'Client email is invalid' using errcode='23514'; end if;
 if p_client_id is null then
  insert into public.clients(first_name,last_name,full_name,primary_phone,primary_email,preferred_channel,mailing_address,housecall_address) values(trim(p_first_name),trim(p_last_name),trim(p_first_name)||' '||trim(p_last_name),nullif(trim(p_primary_phone),''),nullif(trim(p_primary_email),''),p_preferred_channel,nullif(trim(p_mailing_address),''),nullif(trim(p_housecall_address),'')) returning * into result;
 else
  update public.clients set first_name=trim(p_first_name),last_name=trim(p_last_name),full_name=trim(p_first_name)||' '||trim(p_last_name),primary_phone=nullif(trim(p_primary_phone),''),primary_email=nullif(trim(p_primary_email),''),preferred_channel=p_preferred_channel,mailing_address=nullif(trim(p_mailing_address),''),housecall_address=nullif(trim(p_housecall_address),'') where id=p_client_id and version=p_expected_version returning * into result;
  if not found then raise exception 'Record changed or no longer exists; reload before saving' using errcode='PT409'; end if;
 end if;
 return result;
end $function$

create or replace function public.record_inbound_sms(
  p_from text,
  p_to text,
  p_body text,
  p_provider_message_id text,
  p_opt_out_type text default null,
  p_received_at timestamptz default now()
)
returns table (
  client_id uuid,
  conversation_id uuid,
  message_id uuid,
  consent_action text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  normalized_from text := public.normalize_sms_phone(p_from);
  normalized_to text := public.normalize_sms_phone(p_to);
  normalized_body text := nullif(btrim(coalesce(p_body, '')), '');
  normalized_provider_message_id text := nullif(btrim(coalesce(p_provider_message_id, '')), '');
  normalized_opt_out_type text := upper(nullif(btrim(coalesce(p_opt_out_type, '')), ''));
  keyword text;
  selected_client_id uuid;
  selected_conversation_id uuid;
  selected_message_id uuid;
  selected_consent_action text := 'NONE';
  event public.communication_provider_events;
  inbound public.communication_inbound;
  metadata jsonb;
  token uuid;
  matches integer;
  canonical_resource_id text;
begin
  if normalized_from is null then
    raise exception 'Inbound SMS sender phone is invalid' using errcode = '23514';
  end if;

  if normalized_to is null then
    raise exception 'Inbound SMS recipient phone is invalid' using errcode = '23514';
  end if;

  if normalized_body is null or length(normalized_body) > 1600 then
    raise exception 'Inbound SMS body must be between 1 and 1600 characters' using errcode = '23514';
  end if;

  if normalized_provider_message_id is null or length(normalized_provider_message_id) > 256 then
    raise exception 'Inbound SMS provider message id is required' using errcode = '23514';
  end if;

  perform public.communication_require_service();
  canonical_resource_id := case when length(normalized_provider_message_id)<=200 then normalized_provider_message_id
    else 'legacy-sms/'||encode(extensions.digest(normalized_provider_message_id,'sha256'),'hex') end;
  metadata := jsonb_build_object('from',normalized_from,'to',normalized_to,
    'body',normalized_body,'opt_out_type',normalized_opt_out_type,'provider_message_id',normalized_provider_message_id);
  perform pg_advisory_xact_lock(hashtextextended('twilio:'||canonical_resource_id,927));

  select m.id, c.id, c.client_id
  into selected_message_id, selected_conversation_id, selected_client_id
  from public.messages m
  join public.conversations c on c.id = m.conversation_id
  where m.provider = 'twilio'
    and m.provider_message_id = normalized_provider_message_id
  limit 1;

  if selected_message_id is not null then
    client_id := selected_client_id;
    conversation_id := selected_conversation_id;
    message_id := selected_message_id;
    consent_action := 'DUPLICATE';
    return next;
    return;
  end if;

  -- A later household creation/assignment must not turn a reviewed webhook retry into a second message.
  select * into inbound from public.communication_inbound
    where provider='twilio' and resource_id=canonical_resource_id;
  if found then
    if (select payload_hash from public.communication_provider_events where id=inbound.event_id)
      is distinct from encode(extensions.digest(metadata::text,'sha256'),'hex') then
      raise exception 'Provider event identifier reused' using errcode='23505';
    end if;
    client_id := inbound.client_id;
    conversation_id := inbound.conversation_id;
    message_id := inbound.message_id;
    consent_action := 'DUPLICATE';
    return next;
    return;
  end if;

  select count(*), (array_agg(c.id))[1]
  into matches, selected_client_id
  from public.clients c
  where public.communication_recipient('SMS',c.primary_phone) = normalized_from;

  if matches <> 1 then
    -- Preserve unknown/shared senders in the canonical review queue. No placeholder household.
    event := public.receive_communication_event('twilio',canonical_resource_id,
      canonical_resource_id,'inbound',
      encode(extensions.digest(metadata::text,'sha256'),'hex'),metadata);
    if event.state = 'processed' then
      select * into inbound from public.communication_inbound
        where event_id = event.id;
      if not found then
        raise exception 'Processed provider event has no inbound record; reconcile before retrying' using errcode='PT409';
      end if;
    else
      if event.state='review' or (event.state='claimed' and event.lease_expires_at>now()) then
        raise exception 'Provider event lease unavailable' using errcode='PT409';
      end if;
      token := gen_random_uuid();
      update public.communication_provider_events
        set state='claimed',lease_token=token,lease_expires_at=now()+interval '2 minutes',attempts=attempts+1
        where id=event.id;
      inbound := public.complete_inbound_communication(event.id,token,
        normalized_from,normalized_to,'',normalized_body,null,null,'{}','[]',p_received_at,
        coalesce(normalized_opt_out_type,public.sms_keyword(normalized_body)));
    end if;
    client_id := inbound.client_id;
    conversation_id := inbound.conversation_id;
    message_id := inbound.message_id;
    consent_action := 'REVIEW_REQUIRED';
    return next;
    return;
  end if;

  keyword := upper(regexp_replace(normalized_body, '\s+', ' ', 'g'));
  if normalized_opt_out_type is null then
    if keyword in ('STOP', 'STOPALL', 'UNSUBSCRIBE', 'CANCEL', 'END', 'QUIT', 'REVOKE') then
      normalized_opt_out_type := 'STOP';
    elsif keyword in ('START', 'YES', 'UNSTOP') then
      normalized_opt_out_type := 'START';
    elsif keyword in ('HELP', 'INFO') then
      normalized_opt_out_type := 'HELP';
    end if;
  end if;

  if normalized_opt_out_type = 'STOP' then
    insert into public.sms_consent (
      client_id,
      phone_number,
      opted_in,
      opted_out_at,
      consent_method,
      consent_details
    )
    values (
      selected_client_id,
      normalized_from,
      false,
      p_received_at,
      'SMS_KEYWORD'::public.consent_method,
      'Twilio inbound opt-out keyword'
    )
    on conflict on constraint sms_consent_client_phone_unique do update
      set opted_in = false,
        opted_out_at = excluded.opted_out_at,
        consent_method = excluded.consent_method,
        consent_details = excluded.consent_details,
        updated_at = now();
    selected_consent_action := 'OPTED_OUT';
  elsif normalized_opt_out_type = 'START' then
    insert into public.sms_consent (
      client_id,
      phone_number,
      opted_in,
      opted_in_at,
      opted_out_at,
      consent_method,
      consent_details
    )
    values (
      selected_client_id,
      normalized_from,
      true,
      p_received_at,
      null,
      'SMS_KEYWORD'::public.consent_method,
      'Twilio inbound opt-in keyword'
    )
    on conflict on constraint sms_consent_client_phone_unique do update
      set opted_in = true,
        opted_in_at = excluded.opted_in_at,
        opted_out_at = null,
        consent_method = excluded.consent_method,
        consent_details = excluded.consent_details,
        updated_at = now();
    selected_consent_action := 'OPTED_IN';
  elsif normalized_opt_out_type = 'HELP' then
    selected_consent_action := 'HELP';
  end if;

  select c.id
  into selected_conversation_id
  from public.conversations c
  where c.client_id = selected_client_id
    and c.status = 'ACTIVE'::public.conversation_status
  order by c.last_message_at desc, c.created_at desc, c.id
  limit 1;

  if selected_conversation_id is null then
    insert into public.conversations (
      client_id,
      status,
      priority,
      first_message_at,
      last_message_at,
      is_read
    )
    values (
      selected_client_id,
      'ACTIVE'::public.conversation_status,
      'NORMAL'::public.conversation_priority,
      p_received_at,
      p_received_at,
      false
    )
    returning id into selected_conversation_id;
  end if;

  insert into public.messages (
    conversation_id,
    type,
    sender_type,
    content,
    is_internal,
    provider,
    provider_message_id,
    created_at
  )
  values (
    selected_conversation_id,
    'SMS'::public.message_type,
    'CLIENT'::public.sender_type,
    normalized_body,
    false,
    'twilio',
    normalized_provider_message_id,
    p_received_at
  )
  returning id into selected_message_id;

  update public.conversations c
  set last_message_at = p_received_at,
    first_message_at = coalesce(c.first_message_at, p_received_at),
    is_read = false,
    status = 'ACTIVE'::public.conversation_status
  where c.id = selected_conversation_id;

  client_id := selected_client_id;
  conversation_id := selected_conversation_id;
  message_id := selected_message_id;
  consent_action := selected_consent_action;
  return next;
end
$$

create function public.read_patient_photo(p_pet_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare s patient_photo_state;d patient_documents;
begin
 perform clinical_require_staff();
 if not exists(select 1 from pets where id=p_pet_id) then raise exception 'Patient unavailable' using errcode='42501';end if;
 select * into s from patient_photo_state where pet_id=p_pet_id;
 select * into d from patient_documents where id=s.document_id and pet_id=p_pet_id and status='ready' and visibility='internal';
 return jsonb_build_object('pet_id',p_pet_id,'version',coalesce(s.version,0),'document_id',s.document_id,
  'document',case when d.id is null then null else jsonb_build_object('id',d.id,'pet_id',d.pet_id,'file_path',d.file_path,'mime_type',d.mime_type) end);
end $$

create function public.prepare_patient_photo(p_id uuid,p_pet_id uuid,p_expected_version integer,p_sha256 text,p_file_size bigint,p_mime_type text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=clinical_require_staff();u patient_photo_uploads;d patient_documents;s patient_photo_state;
begin
 if p_expected_version is null or p_expected_version<0 or p_sha256 is null or p_sha256 !~ '^[a-f0-9]{64}$'
  or p_file_size is null or p_file_size not between 1 and 5242880 or p_mime_type is null or p_mime_type<>'image/png' then
  raise exception 'A supported image of at most 5 MiB is required' using errcode='23514';end if;
 perform 1 from pets where id=p_pet_id for update;
 if not found then raise exception 'Patient unavailable' using errcode='42501';end if;
 select * into u from patient_photo_uploads where document_id=p_id;
 if found and (u.actor_id<>actor or row(u.pet_id,u.expected_version,u.expected_sha256) is distinct from row(p_pet_id,p_expected_version,p_sha256)) then
  raise exception 'Photo reservation belongs to a different request' using errcode='23514';end if;
 if u.document_id is null then
  select * into s from patient_photo_state where pet_id=p_pet_id;
  if coalesce(s.version,0)<>p_expected_version then raise exception 'Photo changed; reload before choosing another image' using errcode='PT409';end if;
 end if;
 d:=prepare_patient_document(p_id,p_pet_id,null,'patient-photo.png',p_mime_type,p_file_size,'other','Patient identity photo',null,'internal');
 insert into patient_photo_uploads(document_id,pet_id,actor_id,expected_version,expected_sha256)
 values(d.id,p_pet_id,actor,p_expected_version,p_sha256) on conflict(document_id) do nothing;
 return jsonb_build_object('document',to_jsonb(d),'expected_version',p_expected_version,'expected_sha256',p_sha256);
end $$

create function public.read_patient_photo_upload(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=clinical_require_staff();u patient_photo_uploads;d patient_documents;
begin
 select * into u from patient_photo_uploads where document_id=p_id and actor_id=actor;
 if not found then raise exception 'Owned photo reservation required' using errcode='42501';end if;
 select * into d from patient_documents where id=p_id and pet_id=u.pet_id and created_by=actor and status in ('uploading','ready');
 if not found then raise exception 'Photo reservation unavailable' using errcode='PT409';end if;
 return jsonb_build_object('document',to_jsonb(d),'expected_version',u.expected_version,'expected_sha256',u.expected_sha256,
  'object_id',(select id from storage.objects where bucket_id='patient-documents' and name=d.file_path));
end $$

-- Freeze an image after byte capture, even before the uploader finalizes its document.
create or replace function public.patient_document_storage_write(p_path text) returns boolean language plpgsql security definer set search_path=public as $$
declare doc patient_documents;
begin
 if auth.uid() is null or not is_active_staff(auth.uid()) then return false;end if;
 select * into doc from patient_documents where file_path=p_path for update;
 return found and doc.created_by=auth.uid() and doc.status='uploading'
  and not exists(select 1 from patient_photo_uploads where document_id=doc.id and verified_at is not null);
end $$

create function public.verify_patient_photo_bytes(p_id uuid,p_actor_id uuid,p_object_id uuid,p_sha256 text,p_width integer,p_height integer)
returns jsonb language plpgsql security definer set search_path=public as $$
declare u patient_photo_uploads;d patient_documents;o storage.objects;
begin
 perform communication_require_service();
 if not is_active_staff(p_actor_id) then raise exception 'Active uploader required' using errcode='42501';end if;
 select * into d from patient_documents where id=p_id for update;
 select * into u from patient_photo_uploads where document_id=p_id for update;
 if u.document_id is null or u.actor_id<>p_actor_id or d.created_by<>p_actor_id or d.pet_id<>u.pet_id or d.status not in ('uploading','ready')
  or d.visibility<>'internal' or d.source<>'Patient identity photo' or d.file_size>5242880 or d.mime_type<>'image/png' then
  raise exception 'Owned private photo required' using errcode='42501';end if;
 if p_sha256 is null or p_sha256<>u.expected_sha256 or p_width is null or p_height is null
  or p_width not between 1 and 1024 or p_height not between 1 and 1024 or p_width::bigint*p_height>1048576 then
  raise exception 'Image bytes differ from the reserved photo' using errcode='23514';end if;
 select * into o from storage.objects where bucket_id='patient-documents' and name=d.file_path for share;
 if not found or p_object_id is null or o.id<>p_object_id or o.metadata->>'size' is distinct from d.file_size::text or o.metadata->>'mimetype' is distinct from d.mime_type then
  raise exception 'Stored image does not match reservation' using errcode='23514';end if;
 if u.verified_at is not null and row(u.verified_sha256,u.object_id,u.width,u.height) is distinct from row(p_sha256,o.id,p_width,p_height) then
  raise exception 'Verified image identity changed' using errcode='PT409';end if;
 update patient_photo_uploads set verified_sha256=p_sha256,object_id=o.id,width=p_width,height=p_height,verified_at=coalesce(verified_at,now()) where document_id=p_id;
 return jsonb_build_object('id',p_id,'actor_id',p_actor_id,'sha256',p_sha256,'width',p_width,'height',p_height);
end $$

create function public.set_patient_photo(p_id uuid,p_pet_id uuid,p_document_id uuid,p_expected_version integer)
returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=clinical_require_staff();s patient_photo_state;a patient_photo_actions;u patient_photo_uploads;d patient_documents;
begin
 if p_expected_version is null or p_expected_version<0 then raise exception 'Photo version required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('patient-photo-action:'||p_id::text,927));
 select * into a from patient_photo_actions where id=p_id;
 if found then
  if row(a.actor_id,a.pet_id,a.document_id,a.expected_version) is distinct from row(actor,p_pet_id,p_document_id,p_expected_version) then
   raise exception 'Photo action identifier reused' using errcode='23505';end if;
  return jsonb_build_object('id',a.id,'pet_id',a.pet_id,'document_id',a.document_id,'version',a.result_version);
 end if;
 perform 1 from pets where id=p_pet_id for update;
 if not found then raise exception 'Patient unavailable' using errcode='42501';end if;
 insert into patient_photo_state(pet_id,version,updated_by) values(p_pet_id,0,actor) on conflict(pet_id) do nothing;
 select * into s from patient_photo_state where pet_id=p_pet_id for update;
 if s.version<>p_expected_version then raise exception 'Photo changed; reload before choosing another image' using errcode='PT409';end if;
 if p_document_id is not null then
  select * into d from patient_documents where id=p_document_id for share;
  select * into u from patient_photo_uploads where document_id=p_document_id;
  if u.document_id is null or u.pet_id<>p_pet_id or u.actor_id<>actor or u.expected_version<>p_expected_version
   or u.verified_at is null or d.pet_id<>p_pet_id or d.status<>'ready' or d.visibility<>'internal' then
   raise exception 'Verified, ready photo for this patient required' using errcode='23514';end if;
 end if;
 update patient_photo_state set document_id=p_document_id,version=version+1,updated_by=actor,updated_at=now() where pet_id=p_pet_id returning * into s;
 insert into patient_photo_actions(id,pet_id,actor_id,document_id,expected_version,result_version) values(p_id,p_pet_id,actor,p_document_id,p_expected_version,s.version) returning * into a;
 return jsonb_build_object('id',a.id,'pet_id',a.pet_id,'document_id',a.document_id,'version',a.result_version);
end $$

do $$declare t text;begin
 foreach t in array array['patient_service_events','patient_service_corrections'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on public.%I to authenticated',t);
  execute format('create policy "Active staff read" on public.%I for select to authenticated using(public.is_active_staff(auth.uid()))',t);
  execute format('create trigger service_immutable before update or delete on public.%I for each row execute function public.guard_inquiry_history()',t);
  execute format('create trigger service_no_truncate before truncate on public.%I for each statement execute function public.native_correction_immutable()',t);
  execute format('create trigger service_audit after insert on public.%I for each row execute function public.audit_trigger_fn()',t);
 end loop;
end $$

create function public.record_patient_service(p_id uuid,p_request jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff(); r public.patient_service_events; e public.clinical_encounters; p public.catalog_products;
 pet uuid; clinician uuid; clinician_name text; stamp timestamptz; invoice uuid;
begin
 if p_id is null then raise exception 'Service event identity required' using errcode='23514';end if;
 perform public.native_rx_keys(p_request,array['pet_id','encounter_id','product_id','clinician_id','performed_at','notes','invoice_id']);
 if octet_length(p_request::text)>8192 then raise exception 'Bounded service record required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('patient-service:'||p_id::text,0));
 perform public.clinical_require_staff();
 select * into r from public.patient_service_events where id=p_id;
 if found then
  if r.created_by<>actor or r.request is distinct from p_request then raise exception 'Service identity already used' using errcode='23505';end if;
  return to_jsonb(r);
 end if;
 pet:=public.native_rx_uuid(p_request->'pet_id');clinician:=public.native_rx_uuid(p_request->'clinician_id');
 stamp:=public.native_correction_instant(p_request->'performed_at');invoice:=public.native_rx_uuid(p_request->'invoice_id',true);
 if stamp>clock_timestamp() then raise exception 'Service must already have been performed' using errcode='23514';end if;
 if jsonb_typeof(p_request->'notes') is distinct from 'string' or length(p_request->>'notes')>2000 then raise exception 'Bounded service notes required' using errcode='23514';end if;
 perform 1 from public.pets where id=pet and archived_at is null and deceased_at is null for share;
 if not found then raise exception 'Active patient required for service completion' using errcode='23514';end if;
 select * into e from public.clinical_encounters where id=public.native_rx_uuid(p_request->'encounter_id') and pet_id=pet for share;
 if not found then raise exception 'Saved encounter for this patient required' using errcode='23514';end if;
 if stamp<e.visit_at then raise exception 'Service time cannot precede this encounter' using errcode='23514';end if;
 select * into p from public.catalog_products where id=public.native_rx_uuid(p_request->'product_id') and kind='service' and active for share;
 if not found then raise exception 'Active service catalog item required' using errcode='23514';end if;
 select full_name into clinician_name from public.profiles where id=clinician and public.is_active_staff(id) for share;
 if not found or nullif(trim(clinician_name),'') is null then raise exception 'Named active performing clinician required' using errcode='23514';end if;
 if invoice is not null then
  perform 1 from public.billing_invoices b join public.pets pt on pt.client_id=b.client_id where b.id=invoice and pt.id=pet and b.status<>'void' for share of b;
  if not found then raise exception 'Invoice must belong to this patient household' using errcode='23514';end if;
 end if;
 insert into public.patient_service_events(id,pet_id,encounter_id,product_id,product_name,clinician_id,clinician_name,performed_at,notes,invoice_id,request,created_by)
 values(p_id,pet,e.id,p.id,p.name,clinician,clinician_name,stamp,p_request->>'notes',invoice,p_request,actor) returning * into r;
 return to_jsonb(r);
end $$

create function public.correct_patient_service(p_id uuid,p_pet_id uuid,p_event_id uuid,p_reason text,p_replacement_id uuid default null) returns jsonb
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.patient_service_corrections;event public.patient_service_events;
begin
 if p_id is null or p_reason is null or length(trim(p_reason)) not between 1 and 2000 then raise exception 'Correction identity and reason required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('patient-service-correction:'||p_id::text,0));
 perform public.clinical_require_staff();
 select * into r from public.patient_service_corrections where id=p_id;
 if found then
  if r.created_by<>actor or r.service_event_id is distinct from p_event_id or r.reason is distinct from trim(p_reason) or r.replacement_id is distinct from p_replacement_id
    or not exists(select 1 from public.patient_service_events where id=r.service_event_id and pet_id=p_pet_id)
  then raise exception 'Correction identity already used' using errcode='23505';end if;
  return to_jsonb(r);
 end if;
 select * into event from public.patient_service_events where id=p_event_id and pet_id=p_pet_id for update;
 if not found then raise exception 'Service event for this patient required' using errcode='23514';end if;
 if p_replacement_id is not null and (p_replacement_id=p_event_id or not exists(select 1 from public.patient_service_events where id=p_replacement_id and pet_id=event.pet_id and encounter_id=event.encounter_id)) then raise exception 'Replacement must be another service in the same patient encounter' using errcode='23514';end if;
 insert into public.patient_service_corrections(id,service_event_id,replacement_id,reason,created_by) values(p_id,p_event_id,p_replacement_id,trim(p_reason),actor) returning * into r;
 return to_jsonb(r);
end $$

-- Search aliases are names already linked to the same stable catalog identity.
-- Never infer a mapping for unlinked historical free-text records.
create function public.search_whogot_products(p_search text default '',p_limit integer default 50) returns jsonb
language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();
 if p_search is null or length(p_search)>200 or p_limit is null or p_limit not between 1 and 101 then raise exception 'Bounded product search required' using errcode='23514';end if;
 with aliases as (
  select id product_id,name alias from public.catalog_products
  union select product_id,product_name from public.patient_treatments where product_id is not null
  union select product_id,description from public.billing_invoice_items
  union select product_id,product_name from public.patient_service_events
 ), matches as (
  select p.id,p.name,p.kind,p.active,array_agg(distinct a.alias order by a.alias) aliases
  from public.catalog_products p join aliases a on a.product_id=p.id
  group by p.id having bool_or(strpos(lower(a.alias),lower(trim(p_search)))>0)
  order by lower(p.name),p.id limit p_limit
 ) select coalesce(jsonb_agg(to_jsonb(matches)),'[]') into result from matches;
 return result;
end $$

create function public.list_patient_services(p_pet_id uuid) returns jsonb
language plpgsql stable security invoker set search_path=public as $$
declare result jsonb;begin
 if auth.uid() is null or not public.is_active_staff(auth.uid()) then raise exception 'Active staff access required' using errcode='42501';end if;
 select coalesce(jsonb_agg(to_jsonb(s)||jsonb_build_object('correction',to_jsonb(c)) order by s.performed_at desc,s.id desc),'[]') into result
 from public.patient_service_events s left join public.patient_service_corrections c on c.service_event_id=s.id where s.pet_id=p_pet_id;
 return result;
end $$

create function public.list_service_clinicians() returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',full_name) order by full_name,id),'[]') into result
 from public.profiles where public.is_active_staff(id) and nullif(trim(full_name),'') is not null;
 return result;
end $$

-- Direct patient-scoped source access works even when the event is on an older history page.
create function public.read_whogot_source(p_pet_id uuid,p_event_type text,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();
 if p_event_type='administered' then
  select jsonb_build_object('event_type','administered','record',to_jsonb(t),'corrections',coalesce((select jsonb_agg(to_jsonb(c)) from public.patient_treatment_corrections c where c.treatment_id=t.id),'[]')) into result
  from public.patient_treatments t where t.id=p_id and t.pet_id=p_pet_id;
 elsif p_event_type='dispensed' then
  select jsonb_build_object('event_type','dispensed','record',public.native_fulfillment_verified_dispense(d.id),
   'corrections',coalesce((select jsonb_agg(to_jsonb(c) order by c.sequence) from public.native_dispense_correction_events c where c.dispense_id=d.id),'[]')) into result
  from public.native_dispenses d where d.id=p_id and d.pet_id=p_pet_id;
 elsif p_event_type='performed' then
  select jsonb_build_object('event_type','performed','record',to_jsonb(s),'corrections',coalesce((select jsonb_agg(to_jsonb(c)) from public.patient_service_corrections c where c.service_event_id=s.id),'[]')) into result
  from public.patient_service_events s where s.id=p_id and s.pet_id=p_pet_id;
 else raise exception 'Received-care event type required' using errcode='23514';end if;
 return result;
end $$

create function public.list_daily_communications(
 p_from date default (statement_timestamp() at time zone 'America/Denver')::date,
 p_to date default (statement_timestamp() at time zone 'America/Denver')::date,
 p_channel text default null,p_status text default null,p_search text default '',
 p_before jsonb default null,p_limit integer default 50
) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;before_at timestamptz;before_source text;before_id uuid;
begin
 perform public.clinical_require_staff();
 if p_from is null or p_to is null or not isfinite(p_from) or not isfinite(p_to) or p_to<p_from or p_to-p_from>365
  or p_limit is null or p_limit not between 1 and 100 or p_search is null or length(p_search)>200
  or (p_channel is not null and p_channel not in ('EMAIL','SMS'))
  or (p_status is not null and p_status not in ('scheduled','queued','processing','accepted','delivered','failed','uncertain','suppressed','cancelled'))
 then raise exception 'Valid dates (up to 366 days), channel, status and bounded search required' using errcode='23514';end if;
 if p_before is not null then
  perform public.native_rx_keys(p_before,array['activity_at','source','id']);
  before_at:=public.native_correction_instant(p_before->'activity_at');before_source:=p_before->>'source';before_id:=public.native_rx_uuid(p_before->'id');
  if before_source is null or before_source not in ('outbox','legacy','care','appointment') then raise exception 'Invalid communication cursor' using errcode='23514';end if;
 end if;
 with filtered as (
  select r.* from public.daily_communication_rows_internal() r
  where r.activity_at >= (p_from::timestamp at time zone 'America/Denver')
   and r.activity_at < ((p_to+1)::timestamp at time zone 'America/Denver')
   and (p_channel is null or r.channel=p_channel) and (p_status is null or r.status=p_status)
   and (trim(p_search)='' or strpos(lower(coalesce(r.client_name,'')),lower(trim(p_search)))>0
    or strpos(lower(coalesce(r.patient_name,'')),lower(trim(p_search)))>0)
   and (p_before is null or (r.activity_at,r.source,r.id)<(before_at,before_source,before_id))
  order by r.activity_at desc,r.source desc,r.id desc limit p_limit+1
 ), page as (select * from filtered order by activity_at desc,source desc,id desc limit p_limit)
 select jsonb_build_object('read_at',statement_timestamp(),'rows',coalesce((select jsonb_agg(to_jsonb(page) order by activity_at desc,source desc,id desc) from page),'[]'),
  'next',case when (select count(*) from filtered)>p_limit then (select jsonb_build_object('activity_at',activity_at,'source',source,'id',id) from page order by activity_at,source,id limit 1) else null end) into result;
 return result;
end $$

create function public.read_daily_communication(p_source text,p_id uuid) returns jsonb
language plpgsql stable security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();
 if p_source is null or p_source not in ('outbox','legacy','care','appointment') or p_id is null then raise exception 'Communication identity required' using errcode='23514';end if;
 select jsonb_build_object('record',to_jsonb(r),'attempts',case when p_source='outbox' then coalesce((
  select jsonb_agg(jsonb_build_object('attempt_number',a.attempt_number,'started_at',a.started_at,'finished_at',a.finished_at,'outcome',a.outcome) order by a.attempt_number)
  from public.communication_attempts a where a.outbox_id=p_id),'[]') else '[]'::jsonb end) into result
 from public.daily_communication_rows_internal() r where r.source=p_source and r.id=p_id;
 return result;
end $$

create function public.care_require_clinician() returns uuid
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();
begin
 if not exists(select 1 from public.user_roles r join public.profiles p on p.id=r.user_id
  where r.user_id=actor and r.role='DVM' and nullif(trim(p.full_name),'') is not null)
 then raise exception 'Active named veterinarian required for clinical review' using errcode='42501';end if;
 return actor;
end $$

create function public.care_date(p_value jsonb) returns date language plpgsql immutable set search_path=public as $$
declare value text;result date;
begin
 if jsonb_typeof(p_value) is distinct from 'string' then raise exception 'Calendar date required' using errcode='23514';end if;
 value:=p_value#>>'{}';
 if value!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or left(value,4)='0000' then raise exception 'Complete valid calendar date required' using errcode='23514';end if;
 result:=value::date;
 if result::text<>value or not isfinite(result) then raise exception 'Valid calendar date required' using errcode='23514';end if;
 return result;
exception when datetime_field_overflow or invalid_datetime_format then raise exception 'Valid calendar date required' using errcode='23514';
end $$

create function public.care_calendar_due(p_anchor date,p_amount integer,p_unit text,p_month_end text,p_cycle integer default 1)
returns date language plpgsql immutable set search_path=public as $$
declare target date;months integer;
begin
 if p_anchor is null or not isfinite(p_anchor) or p_anchor<'0001-01-01' or p_anchor>'9999-12-31'
 or p_amount is null or p_cycle is null or p_cycle not between 1 and 1000000 or p_amount<1
 or p_unit is null or p_unit not in ('days','weeks','months','years') or p_month_end is null or p_month_end not in ('clamp','preserve_end')
 or p_amount>(case p_unit when 'days' then 36500 when 'weeks' then 5200 when 'months' then 1200 else 100 end)
 then raise exception 'Bounded calendar interval, anchor and month-end rule required' using errcode='23514';end if;
 if p_unit in ('days','weeks') then target:=p_anchor+(p_amount::bigint*p_cycle*case when p_unit='weeks' then 7 else 1 end)::integer;
 else
  months:=(p_amount::bigint*p_cycle*case when p_unit='years' then 12 else 1 end)::integer;
  target:=(p_anchor+make_interval(months=>months))::date;
  if p_month_end='preserve_end' and p_anchor=(date_trunc('month',p_anchor)+interval '1 month - 1 day')::date
  then target:=(date_trunc('month',target)+interval '1 month - 1 day')::date;end if;
 end if;
 if target>'9999-12-31' or target<p_anchor then raise exception 'Calendar due date exceeds supported range' using errcode='23514';end if;
 return target;
exception when datetime_field_overflow or numeric_value_out_of_range then
 raise exception 'Calendar due date exceeds supported range' using errcode='23514';
end $$

-- Separate branches avoid referencing a missing record field in a trigger's other table.
create function public.care_workflow_revision() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if tg_argv[0]='template' then
  insert into public.care_workflow_revisions values('template',new.id,new.version,to_jsonb(new),new.approved_by,clock_timestamp());
 else insert into public.care_workflow_revisions values('plan',new.id,new.version,to_jsonb(new),auth.uid(),clock_timestamp());end if;
 return new;
end $$

do $$declare t text;begin
 foreach t in array array['recurring_care_templates','patient_care_plans','care_plan_completions','care_workflow_actions','care_workflow_revisions','care_plan_delivery_windows','care_delivery_deferrals'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 end loop;
