create function public.care_recover_action(p_action_id uuid,p_kind text,p_entity_id uuid,p_pet_id uuid,p_request jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.care_workflow_actions;
begin
 if p_action_id is null or p_entity_id is null then raise exception 'Stable action and entity identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('care-action:'||p_action_id::text,0));
 select * into r from public.care_workflow_actions where id=p_action_id;
 if not found then return null;end if;
 if row(r.kind,r.entity_id,r.pet_id,r.actor_id,r.request) is distinct from row(p_kind,p_entity_id,p_pet_id,auth.uid(),p_request)
 then raise exception 'Care action identity reused with changed request' using errcode='23505';end if;
 return r.receipt;
end $$

create function public.care_completion_source(p_pet_id uuid,p_source_kind text,p_source_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare s public.patient_service_events;v public.patient_treatments;l public.patient_lab_orders;day date;label text;ver integer;instant timestamptz;
begin
 if p_source_kind='service' then
  select * into s from public.patient_service_events where id=p_source_id and pet_id=p_pet_id for share;
  if s.id is null or s.performed_at>clock_timestamp() or exists(select 1 from public.patient_service_corrections where service_event_id=s.id) then return null;end if;
  day:=(s.performed_at at time zone 'America/Denver')::date;label:=s.product_name;ver:=1;instant:=s.performed_at;
 elsif p_source_kind='vaccine' then
  select * into v from public.patient_treatments where id=p_source_id and pet_id=p_pet_id and kind='vaccine' and not historical for share;
  if v.id is null or v.administered_at>clock_timestamp() or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.id) then return null;end if;
  day:=(v.administered_at at time zone 'America/Denver')::date;label:=v.product_name;ver:=1;instant:=v.administered_at;
 elsif p_source_kind='lab' then
  select * into l from public.patient_lab_orders where id=p_source_id and pet_id=p_pet_id for share;
  if l.id is null or l.status not in ('collected','resulted') or l.collected_date is null then return null;end if;
  day:=l.collected_date;label:=l.test_name;ver:=l.version;instant:=day::timestamp at time zone 'America/Denver';
 else return null;end if;
 if day is null or not isfinite(day) or day>(clock_timestamp() at time zone 'America/Denver')::date then return null;end if;
 return jsonb_build_object('source_kind',p_source_kind,'id',p_source_id,'pet_id',p_pet_id,'completed_on',day,'source_version',ver,'label',label,'at',instant);
end $$

create function public.care_plan_source_is_current(p_plan_id uuid) returns boolean
language plpgsql security definer set search_path=public as $$
declare p public.patient_care_plans;c public.care_plan_completions;source jsonb;
begin
 select * into p from public.patient_care_plans where id=p_plan_id;
 if p.id is null or p.status<>'current' or not public.is_active_staff(p.approved_by)
 or not exists(select 1 from public.user_roles where user_id=p.approved_by and role='DVM') then return false;end if;
 if p.last_completion_id is not null then
  select * into c from public.care_plan_completions where id=p.last_completion_id;
  source:=public.care_completion_source(p.pet_id,c.source_kind,c.source_id);
  if source is null or source is distinct from c.source_snapshot then return false;end if;
 end if;
 return true;
end $$

create function public.save_recurring_care_template(p_action_id uuid,p_id uuid,p_expected_version integer,p_request jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;receipt jsonb;r public.recurring_care_templates;request jsonb;
begin
 perform public.care_eligibility_lock();actor:=public.care_require_clinician();
 perform public.native_rx_keys(p_request,array['care_key','name','care_kind','interval_amount','interval_unit','anchor_mode','month_end','active','review_note']);
 request:=jsonb_build_object('expected_version',p_expected_version,'values',p_request);
 receipt:=public.care_recover_action(p_action_id,'template',p_id,null,request);if receipt is not null then return receipt;end if;
 perform public.native_rx_text(p_request->'name',160);perform public.native_rx_text(p_request->'review_note',2000);
 perform public.care_calendar_due('2000-01-31',public.native_rx_revision(p_request->'interval_amount'),p_request->>'interval_unit',p_request->>'month_end');
 if p_request->>'care_key' is null or p_request->>'care_key'!~'^[a-z0-9][a-z0-9_-]{0,79}$'
 or p_request->>'care_kind' is null or p_request->>'care_kind' not in ('wellness','bloodwork','vaccine','custom')
 or p_request->>'anchor_mode' is null or p_request->>'anchor_mode' not in ('completed_care','fixed_schedule')
 or jsonb_typeof(p_request->'active') is distinct from 'boolean' then raise exception 'Reviewed care default fields required' using errcode='23514';end if;
 select * into r from public.recurring_care_templates where id=p_id for update;
 if r.id is null and p_expected_version is not null or r.id is not null and r.version is distinct from p_expected_version
 then raise exception 'Care default changed; review latest saved version' using errcode='PT409';end if;
 if r.id is not null and row(r.care_key,r.care_kind) is distinct from row(p_request->>'care_key',p_request->>'care_kind')
 then raise exception 'Care key and category are immutable; create a different default' using errcode='23514';end if;
 if r.id is null then
  insert into public.recurring_care_templates(id,care_key,name,care_kind,interval_amount,interval_unit,anchor_mode,month_end,active,review_note,approved_by)
  values(p_id,p_request->>'care_key',trim(p_request->>'name'),p_request->>'care_kind',(p_request->>'interval_amount')::integer,p_request->>'interval_unit',
   p_request->>'anchor_mode',p_request->>'month_end',(p_request->>'active')::boolean,trim(p_request->>'review_note'),actor) returning * into r;
 else update public.recurring_care_templates set name=trim(p_request->>'name'),interval_amount=(p_request->>'interval_amount')::integer,
  interval_unit=p_request->>'interval_unit',anchor_mode=p_request->>'anchor_mode',month_end=p_request->>'month_end',
  active=(p_request->>'active')::boolean,review_note=trim(p_request->>'review_note'),version=version+1,approved_by=actor,approved_at=clock_timestamp()
  where id=p_id returning * into r;end if;
 receipt:=to_jsonb(r);
 insert into public.care_workflow_actions(id,kind,entity_id,request,receipt,actor_id) values(p_action_id,'template',p_id,request,receipt,actor);
 return receipt;
end $$

create function public.save_patient_care_plan(p_action_id uuid,p_id uuid,p_pet_id uuid,p_expected_version integer,p_request jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;receipt jsonb;r public.patient_care_plans;t public.recurring_care_templates;snapshot jsonb;request jsonb;
 v_template_id uuid;v_template_version integer;anchor date;due date;cycle integer:=1;calculated date;approved uuid;approval_at timestamptz;v_status text;completion public.care_plan_completions;
begin
 perform public.care_eligibility_lock();actor:=public.clinical_require_staff();
 perform public.native_rx_keys(p_request,array['template_id','template_version','name','interval_amount','interval_unit','anchor_mode','month_end','anchor_on','due_on','status','reminders_enabled','override_reason','review_note','replace_anchor_evidence']);
 request:=jsonb_build_object('expected_version',p_expected_version,'values',p_request);
 receipt:=public.care_recover_action(p_action_id,'plan',p_id,p_pet_id,request);if receipt is not null then return receipt;end if;
 if p_pet_id is null then raise exception 'Patient required' using errcode='23514';end if;
 perform 1 from public.pets where id=p_pet_id and archived_at is null and deceased_at is null for update;
 if not found then raise exception 'Active patient required for care planning' using errcode='23514';end if;
 v_template_id:=public.native_rx_uuid(p_request->'template_id');v_template_version:=public.native_rx_revision(p_request->'template_version');
 anchor:=public.care_date(p_request->'anchor_on');due:=public.care_date(p_request->'due_on');v_status:=p_request->>'status';
 perform public.native_rx_text(p_request->'name',160);perform public.native_rx_text(p_request->'review_note',2000);
 if anchor is null or anchor>(clock_timestamp() at time zone 'America/Denver')::date or due is null
 or v_status is null or v_status not in ('proposed','current','paused','retired') or jsonb_typeof(p_request->'reminders_enabled') is distinct from 'boolean'
 or jsonb_typeof(p_request->'replace_anchor_evidence') is distinct from 'boolean'
 or jsonb_typeof(p_request->'override_reason') is distinct from 'string' or length(p_request->>'override_reason')>2000
 then raise exception 'Reviewed finite care dates, state and rationale required' using errcode='23514';end if;
 select * into r from public.patient_care_plans where id=p_id for update;
 if r.id is not null and r.pet_id<>p_pet_id then raise exception 'Care plan belongs to another patient' using errcode='42501';end if;
 if r.id is null and p_expected_version is not null or r.id is not null and r.version is distinct from p_expected_version
 then raise exception 'Care plan changed; review latest saved version' using errcode='PT409';end if;
 if r.status='retired' then raise exception 'Retired care plan is immutable; create a new plan' using errcode='23514';end if;
 select * into t from public.recurring_care_templates where id=v_template_id for share;
 if r.id is not null and row(r.template_id,r.template_version) is not distinct from row(v_template_id,v_template_version)
 then snapshot:=r.template_snapshot;
 else
  if t.id is null or not t.active or t.version is distinct from v_template_version then raise exception 'Care default changed or retired; review latest version' using errcode='PT409';end if;
  snapshot:=to_jsonb(t);
 end if;
 if r.id is not null and r.care_key is distinct from snapshot->>'care_key' then raise exception 'Plan cannot change care key' using errcode='23514';end if;
 if r.id is not null and row(r.anchor_on,r.interval_amount,r.interval_unit,r.anchor_mode,r.month_end)
 is not distinct from row(anchor,public.native_rx_revision(p_request->'interval_amount'),p_request->>'interval_unit',p_request->>'anchor_mode',p_request->>'month_end')
 then cycle:=r.cycle_index;end if;
 calculated:=public.care_calendar_due(anchor,public.native_rx_revision(p_request->'interval_amount'),p_request->>'interval_unit',p_request->>'month_end',cycle);
 if p_request->>'anchor_mode' is null or p_request->>'anchor_mode' not in ('completed_care','fixed_schedule') then raise exception 'Calendar anchor rule required' using errcode='23514';end if;
 if (row(trim(p_request->>'name'),p_request->'interval_amount',p_request->>'interval_unit',p_request->>'anchor_mode',p_request->>'month_end')
  is distinct from row(snapshot->>'name',snapshot->'interval_amount',snapshot->>'interval_unit',snapshot->>'anchor_mode',snapshot->>'month_end') or due<>calculated)
 and nullif(trim(p_request->>'override_reason'),'') is null then raise exception 'Patient-specific interval, date or name override requires rationale' using errcode='23514';end if;
 if (p_request->>'replace_anchor_evidence')::boolean and nullif(trim(p_request->>'override_reason'),'') is null
 then raise exception 'Replacing completion evidence with a reviewed baseline requires rationale' using errcode='23514';end if;
 if v_status='current' then
  approved:=public.care_require_clinician();approval_at:=clock_timestamp();
  -- A corrected prior anchor cannot be restored by acknowledging unchanged stale evidence.
  if r.last_completion_id is not null then
   select * into completion from public.care_plan_completions where id=r.last_completion_id;
   if public.care_completion_source(p_pet_id,completion.source_kind,completion.source_id) is distinct from completion.source_snapshot
   and not (p_request->>'replace_anchor_evidence')::boolean then raise exception 'Completion evidence changed; explicitly review the calendar anchor' using errcode='PT409';end if;
  end if;
 elsif v_status in ('paused','retired') then approved:=r.approved_by;approval_at:=r.approved_at;end if;
 if r.id is null then
  if v_status not in ('proposed','current') then raise exception 'New plan must be proposed or clinically reviewed' using errcode='23514';end if;
  insert into public.patient_care_plans(id,pet_id,template_id,template_version,template_snapshot,care_key,name,care_kind,interval_amount,interval_unit,anchor_mode,month_end,anchor_on,cycle_index,due_on,status,reminders_enabled,override_reason,review_note,approved_by,approved_at,created_by,updated_by)
  values(p_id,p_pet_id,v_template_id,v_template_version,snapshot,snapshot->>'care_key',trim(p_request->>'name'),snapshot->>'care_kind',
   (p_request->>'interval_amount')::integer,p_request->>'interval_unit',p_request->>'anchor_mode',p_request->>'month_end',anchor,cycle,due,v_status,
   v_status='current' and (p_request->>'reminders_enabled')::boolean,trim(p_request->>'override_reason'),trim(p_request->>'review_note'),approved,approval_at,actor,actor)
  returning * into r;
 else update public.patient_care_plans set template_id=v_template_id,template_version=v_template_version,template_snapshot=snapshot,
  name=trim(p_request->>'name'),interval_amount=(p_request->>'interval_amount')::integer,interval_unit=p_request->>'interval_unit',
  anchor_mode=p_request->>'anchor_mode',month_end=p_request->>'month_end',anchor_on=anchor,cycle_index=cycle,due_on=due,status=v_status,
  reminders_enabled=v_status='current' and (p_request->>'reminders_enabled')::boolean,override_reason=trim(p_request->>'override_reason'),
  review_note=trim(p_request->>'review_note'),approved_by=approved,approved_at=approval_at,
  last_completion_id=case when v_status='current' and ((p_request->>'replace_anchor_evidence')::boolean or anchor<>r.anchor_on) then null else r.last_completion_id end,
  occurrence_id=case when due<>r.due_on then gen_random_uuid() else r.occurrence_id end,
  version=version+1,updated_by=actor,updated_at=clock_timestamp() where id=p_id returning * into r;end if;
 receipt:=to_jsonb(r);
 insert into public.care_workflow_actions(id,kind,entity_id,pet_id,request,receipt,actor_id) values(p_action_id,'plan',p_id,p_pet_id,request,receipt,actor);
 return receipt;
end $$

create function public.care_completion_next(p_plan_id uuid,p_pet_id uuid,p_source_kind text,p_source_id uuid,p_source_version integer) returns jsonb
language plpgsql security definer set search_path=public as $$
declare p public.patient_care_plans;source jsonb;day date;next_due date;anchor date;cycle integer;months integer;c public.care_plan_completions;
begin
 select * into p from public.patient_care_plans where id=p_plan_id and pet_id=p_pet_id for share;
 if p.id is null or not public.care_plan_source_is_current(p.id) then raise exception 'Current clinically reviewed care plan required' using errcode='23514';end if;
 source:=public.care_completion_source(p_pet_id,p_source_kind,p_source_id);
 if source is null or (source->>'source_version')::integer is distinct from p_source_version then raise exception 'Completed care source changed or is ineligible for this patient' using errcode='PT409';end if;
 if p.care_kind='wellness' and p_source_kind<>'service' or p.care_kind='bloodwork' and p_source_kind<>'lab' or p.care_kind='vaccine' and p_source_kind<>'vaccine'
 then raise exception 'Choose completed evidence for this care category' using errcode='23514';end if;
 if exists(select 1 from public.care_plan_completions where plan_id=p.id and source_kind=p_source_kind and source_id=p_source_id)
 then raise exception 'This completed care already advanced this plan' using errcode='23514';end if;
 day:=(source->>'completed_on')::date;
 if p.last_completion_id is not null then select * into c from public.care_plan_completions where id=p.last_completion_id;end if;
 if day<=p.anchor_on or c.id is not null and day<=c.completed_on then raise exception 'Completed care date must advance the prior anchor/completion' using errcode='23514';end if;
 if p.anchor_mode='completed_care' then anchor:=day;cycle:=1;
 else
  anchor:=p.anchor_on;
  if p.interval_unit in ('days','weeks') then cycle:=greatest(p.cycle_index+1,(day-anchor)/(p.interval_amount*case when p.interval_unit='weeks' then 7 else 1 end)+1);
  else
   months:=(extract(year from day)::integer-extract(year from anchor)::integer)*12+extract(month from day)::integer-extract(month from anchor)::integer;
   cycle:=greatest(p.cycle_index+1,months/(p.interval_amount*case when p.interval_unit='years' then 12 else 1 end));
  end if;
 end if;
 next_due:=public.care_calendar_due(anchor,p.interval_amount,p.interval_unit,p.month_end,cycle);
 if next_due<=day then cycle:=cycle+1;next_due:=public.care_calendar_due(anchor,p.interval_amount,p.interval_unit,p.month_end,cycle);end if;
 return jsonb_build_object('source',source,'completed_on',day,'next_due_on',next_due,'next_anchor_on',anchor,'next_cycle_index',cycle);
end $$

create function public.preview_care_plan_completion(p_plan_id uuid,p_pet_id uuid,p_expected_version integer,p_source_kind text,p_source_id uuid,p_source_version integer)
returns jsonb language plpgsql security definer set search_path=public as $$
begin
 perform public.care_eligibility_lock();perform public.care_require_clinician();
 perform 1 from public.pets where id=p_pet_id and archived_at is null and deceased_at is null for share;
 if not found then raise exception 'Active patient required' using errcode='23514';end if;
 perform 1 from public.patient_care_plans where id=p_plan_id and pet_id=p_pet_id and version=p_expected_version for share;
 if not found then raise exception 'Care plan changed; review latest version' using errcode='PT409';end if;
 return public.care_completion_next(p_plan_id,p_pet_id,p_source_kind,p_source_id,p_source_version);
end $$

create function public.complete_patient_care_plan(p_action_id uuid,p_plan_id uuid,p_pet_id uuid,p_expected_version integer,p_request jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;receipt jsonb;r public.patient_care_plans;c public.care_plan_completions;request jsonb;preview jsonb;
begin
 perform public.care_eligibility_lock();actor:=public.care_require_clinician();
 perform public.native_rx_keys(p_request,array['source_kind','source_id','source_version','review_note']);
 request:=jsonb_build_object('expected_version',p_expected_version,'values',p_request);
 receipt:=public.care_recover_action(p_action_id,'completion',p_plan_id,p_pet_id,request);if receipt is not null then return receipt;end if;
 perform public.native_rx_text(p_request->'review_note',2000);
 perform 1 from public.pets where id=p_pet_id and archived_at is null and deceased_at is null for update;
 if not found then raise exception 'Active patient required' using errcode='23514';end if;
 select * into r from public.patient_care_plans where id=p_plan_id and pet_id=p_pet_id for update;
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Care plan changed; review latest version' using errcode='PT409';end if;
 preview:=public.care_completion_next(p_plan_id,p_pet_id,p_request->>'source_kind',public.native_rx_uuid(p_request->'source_id'),public.native_rx_revision(p_request->'source_version'));
 insert into public.care_plan_completions(id,plan_id,pet_id,plan_version,source_kind,source_id,source_version,source_snapshot,completed_on,next_due_on,review_note,created_by)
 values(p_action_id,p_plan_id,p_pet_id,r.version,p_request->>'source_kind',(p_request->>'source_id')::uuid,(p_request->>'source_version')::integer,
  preview->'source',(preview->>'completed_on')::date,(preview->>'next_due_on')::date,trim(p_request->>'review_note'),actor) returning * into c;
 update public.patient_care_plans set anchor_on=(preview->>'next_anchor_on')::date,cycle_index=(preview->>'next_cycle_index')::integer,
  due_on=c.next_due_on,last_completion_id=c.id,occurrence_id=gen_random_uuid(),version=version+1,updated_by=actor,updated_at=clock_timestamp(),approved_by=actor,approved_at=clock_timestamp()
  where id=p_plan_id returning * into r;
 receipt:=jsonb_build_object('plan',to_jsonb(r),'completion',to_jsonb(c));
 insert into public.care_workflow_actions(id,kind,entity_id,pet_id,request,receipt,actor_id) values(p_action_id,'completion',p_plan_id,p_pet_id,request,receipt,actor);
 return receipt;
end $$

create function public.care_window_next_open(p_start integer,p_end integer,p_at timestamptz)
returns timestamptz language plpgsql stable set search_path=public as $$
declare local_at timestamp;minutes integer;day date;
begin
 if p_start is null or p_end is null or p_start not between 0 and 1439 or p_end not between 1 and 1440 or p_end<=p_start
 or p_at is null or not isfinite(p_at) then raise exception 'Finite Denver daytime send window required' using errcode='23514';end if;
 local_at:=p_at at time zone 'America/Denver';minutes:=extract(hour from local_at)::integer*60+extract(minute from local_at)::integer;day:=local_at::date;
 if minutes>=p_start and minutes<p_end then return p_at;end if;
 if minutes>=p_end then day:=day+1;end if;
 return (day::timestamp+make_interval(mins=>p_start)) at time zone 'America/Denver';
end $$

create function public.save_care_plan_delivery_policy(p_action_id uuid,p_id uuid,p_expected_version integer,p_request jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.reminder_automation_policies;t public.care_message_templates;w public.care_plan_delivery_windows;
 receipt jsonb;request jsonb;channel text;start_at integer;end_at integer;
begin
 perform public.care_eligibility_lock();actor:=public.care_require_admin();
 perform public.native_rx_keys(p_request,array['channel','message_template_id','message_template_version','subject','enabled','review_note','start_minute','end_minute']);
 request:=jsonb_build_object('expected_version',p_expected_version,'values',p_request);
 receipt:=public.care_recover_action(p_action_id,'delivery_policy',p_id,null,request);if receipt is not null then return receipt;end if;
 channel:=p_request->>'channel';perform public.native_rx_text(p_request->'review_note',2000);
 if channel is null or channel not in ('EMAIL','SMS') or jsonb_typeof(p_request->'enabled') is distinct from 'boolean'
 or jsonb_typeof(p_request->'subject') is distinct from 'string' or length(p_request->>'subject')>300
 or jsonb_typeof(p_request->'start_minute') is distinct from 'number' or (p_request->>'start_minute')!~'^[0-9]+$'
 or jsonb_typeof(p_request->'end_minute') is distinct from 'number' or (p_request->>'end_minute')!~'^[0-9]+$'
 then raise exception 'Reviewed channel, wording and send window required' using errcode='23514';end if;
 start_at:=(p_request->>'start_minute')::integer;end_at:=(p_request->>'end_minute')::integer;
 perform public.care_window_next_open(start_at,end_at,clock_timestamp());
 select * into r from public.reminder_automation_policies where id=p_id for update;
 if r.id is null and p_expected_version is not null or r.id is not null and r.version is distinct from p_expected_version
 then raise exception 'Recurring care delivery policy changed' using errcode='PT409';end if;
 if r.id is not null and (r.source_kind<>'care_plan' or r.channel<>channel) then raise exception 'Policy source and channel are immutable' using errcode='23514';end if;
 if r.id is not null and not (p_request->>'enabled')::boolean then
  if public.native_rx_uuid(p_request->'message_template_id') is distinct from r.message_template_id
  or public.native_rx_revision(p_request->'message_template_version') is distinct from r.message_template_version
  then raise exception 'Disabling retains previously reviewed wording' using errcode='23514';end if;
  t.id:=r.message_template_id;t.version:=r.message_template_version;
 else
  select * into t from public.care_message_templates where id=public.native_rx_uuid(p_request->'message_template_id') for share;
  if t.id is null or not t.active or t.version is distinct from public.native_rx_revision(p_request->'message_template_version') or upper(t.channel)<>channel
  then raise exception 'Current reviewed message wording for this channel required' using errcode='23514';end if;
 end if;
 if r.id is null then
  insert into public.reminder_automation_policies(id,source_kind,channel,message_template_id,message_template_version,subject,enabled,review_note,approved_by)
  values(p_id,'care_plan',channel,t.id,t.version,p_request->>'subject',(p_request->>'enabled')::boolean,trim(p_request->>'review_note'),actor) returning * into r;
 else update public.reminder_automation_policies set message_template_id=t.id,message_template_version=t.version,
  subject=p_request->>'subject',enabled=(p_request->>'enabled')::boolean,review_note=trim(p_request->>'review_note'),
  version=version+1,approved_by=actor,approved_at=clock_timestamp() where id=p_id returning * into r;end if;
 insert into public.care_plan_delivery_windows(policy_id,start_minute,end_minute) values(r.id,start_at,end_at)
 on conflict(policy_id) do update set start_minute=excluded.start_minute,end_minute=excluded.end_minute returning * into w;
 receipt:=jsonb_build_object('policy',to_jsonb(r),'window',to_jsonb(w));
 insert into public.reminder_automation_policy_history(policy_id,version,snapshot) values(r.id,r.version,receipt);
 insert into public.care_workflow_actions(id,kind,entity_id,request,receipt,actor_id) values(p_action_id,'delivery_policy',p_id,request,receipt,actor);
 return receipt;
end $$

create function public.care_defer_attempt(p_id uuid,p_lease_token uuid) returns public.communication_outbox
language plpgsql security definer set search_path=public as $$
declare r public.communication_outbox;w public.care_plan_delivery_windows;next_open timestamptz;instant timestamptz:=clock_timestamp();
begin
 perform public.care_eligibility_lock();perform public.communication_require_service();
 select * into r from public.communication_outbox where id=p_id for update;
 if r.id is null or r.state<>'claimed' or r.lease_token is distinct from p_lease_token or r.attempt_started_at is not null
 or r.lease_expires_at<=clock_timestamp() then raise exception 'Outbox lease is unavailable' using errcode='PT409';end if;
 select windows.* into w from public.reminder_outbox_links link
 join public.reminder_automation_policies policy on policy.id=link.policy_id and policy.source_kind='care_plan'
 join public.care_plan_delivery_windows windows on windows.policy_id=policy.id where link.outbox_id=r.id;
 if w.policy_id is null then return null;end if;
 instant:=clock_timestamp();next_open:=public.care_window_next_open(w.start_minute,w.end_minute,instant);
 if next_open<=instant then return null;end if;
 insert into public.care_delivery_deferrals(outbox_id,eligible_at) values(p_id,next_open)
 on conflict(outbox_id) do update set eligible_at=excluded.eligible_at,recorded_at=clock_timestamp();
 update public.communication_outbox set state='pending',lease_token=null,lease_expires_at=null,updated_at=clock_timestamp()
 where id=p_id returning * into r;
 return r;
end $$

create function public.care_plan_invalidate_jobs() returns trigger language plpgsql security definer set search_path=public as $$
begin
 update public.care_reminder_jobs set status='invalidated',invalidated_at=clock_timestamp(),invalidation_reason='Recurring care plan revised, completed, paused or retired'
 where source_kind='care_plan' and source_id=new.id and status='pending';
 return new;
end $$

create function public.care_plan_patient_changed() returns trigger language plpgsql security definer set search_path=public as $$
begin
 if (new.archived_at is not null or new.deceased_at is not null) or new.client_id is distinct from old.client_id then
  update public.patient_care_plans set status='proposed',reminders_enabled=false,approved_by=null,approved_at=null,
   review_note='Patient status/household changed; veterinarian must review before reminders resume',
   version=version+1,updated_at=clock_timestamp(),updated_by=coalesce(auth.uid(),updated_by)
  where pet_id=new.id and status in ('current','paused');
 elsif new.name is distinct from old.name then
  update public.patient_care_plans set version=version+1,updated_at=clock_timestamp(),updated_by=coalesce(auth.uid(),updated_by)
  where pet_id=new.id and status='current';
 end if;
 return new;
end $$

create function public.care_plan_completion_source_changed() returns trigger language plpgsql security definer set search_path=public as $$
declare v_kind text;v_source_id uuid;actor uuid;
begin
 if tg_table_name='patient_service_corrections' then v_kind:='service';v_source_id:=new.service_event_id;actor:=new.created_by;
 elsif tg_table_name='patient_treatment_corrections' then v_kind:='vaccine';v_source_id:=new.treatment_id;actor:=new.created_by;
 else
  if row(new.version,new.collected_date,new.status,new.test_name) is not distinct from row(old.version,old.collected_date,old.status,old.test_name) then return new;end if;
  v_kind:='lab';v_source_id:=new.id;actor:=new.updated_by;
 end if;
 update public.patient_care_plans p set status='proposed',reminders_enabled=false,approved_by=null,approved_at=null,
  review_note='Completed care evidence corrected or revised; veterinarian must review the schedule',
  version=p.version+1,updated_at=clock_timestamp(),updated_by=actor
 where p.status in ('current','paused') and exists(select 1 from public.care_plan_completions c where c.plan_id=p.id and c.source_kind=v_kind and c.source_id=v_source_id);
 return new;
end $$

create function public.list_recurring_care_templates(p_after uuid default null,p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 perform public.clinical_require_staff();
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'Bounded default page required' using errcode='23514';end if;
 with page as (select t.* from public.recurring_care_templates t where p_after is null or t.id>p_after order by t.id limit p_limit+1),
 rows as(select * from page order by id limit p_limit)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(rows) order by id) from rows),'[]'),
  'next',case when (select count(*) from page)>p_limit then (select id from rows order by id desc limit 1) else null end) into result;
 return result;
end $$

create function public.read_recurring_care_template(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 if p_id is null then raise exception 'Default identity required' using errcode='23514';end if;
 return (select to_jsonb(t) from public.recurring_care_templates t where id=p_id);
end $$

create function public.care_plan_display(p_plan_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.patient_care_plans;pet public.pets;reason text;deferred timestamptz;
begin
 select * into p from public.patient_care_plans where id=p_plan_id;
 if p.id is null then return null;end if;
 select * into pet from public.pets where id=p.pet_id;
 reason:=case when pet.archived_at is not null or pet.deceased_at is not null then 'Patient inactive; routine reminders stopped'
 when p.status='proposed' then 'Awaiting veterinarian review' when p.status='paused' then 'Paused' when p.status='retired' then 'Retired'
 when not p.reminders_enabled then 'Reminders off' when not public.care_plan_source_is_current(p.id) then 'Clinical approval or completion evidence requires review'
 else 'Uses reviewed delivery policies, channel preference and final eligibility checks' end;
 select min(d.eligible_at) into deferred from public.care_reminder_jobs j
 join public.reminder_outbox_links link on link.job_kind='care' and link.job_id=j.id and link.invalidated_at is null
 join public.communication_outbox o on o.id=link.outbox_id and o.state='pending'
 join public.care_delivery_deferrals d on d.outbox_id=o.id and d.eligible_at>clock_timestamp()
 where j.source_kind='care_plan' and j.source_id=p.id and j.source_version=p.version;
 return jsonb_build_object('plan',to_jsonb(p),'patient_name',pet.name,'patient_inactive',pet.archived_at is not null or pet.deceased_at is not null,
  'reminder_reason',reason,'next_send_at',deferred);
end $$

create function public.list_patient_care_plans(p_pet_id uuid,p_after uuid default null,p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 perform public.clinical_require_staff();
 if p_pet_id is null or p_limit is null or p_limit not between 1 and 100 then raise exception 'Patient and bounded plan page required' using errcode='23514';end if;
 with page as (select id from public.patient_care_plans where pet_id=p_pet_id and (p_after is null or id>p_after) order by id limit p_limit+1),
 rows as(select * from page order by id limit p_limit)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(public.care_plan_display(id) order by id) from rows),'[]'),
  'next',case when (select count(*) from page)>p_limit then (select id from rows order by id desc limit 1) else null end) into result;
 return result;
end $$

create function public.read_patient_care_plan(p_plan_id uuid,p_pet_id uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();
 if p_plan_id is null or p_pet_id is null then raise exception 'Patient plan identity required' using errcode='23514';end if;
 if not exists(select 1 from public.patient_care_plans where id=p_plan_id and pet_id=p_pet_id) then return null;end if;
 return public.care_plan_display(p_plan_id);
end $$

create function public.list_care_plan_history(p_plan_id uuid,p_pet_id uuid,p_before_version integer default null,p_limit integer default 20)
returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;
begin
 perform public.clinical_require_staff();
 if not exists(select 1 from public.patient_care_plans where id=p_plan_id and pet_id=p_pet_id) then raise exception 'Patient plan unavailable' using errcode='42501';end if;
 if p_limit is null or p_limit not between 1 and 100 or p_before_version<1 then raise exception 'Bounded history page required' using errcode='23514';end if;
 with page as(select r.version,r.snapshot,r.actor_id,r.recorded_at,
   (select to_jsonb(c) from public.care_plan_completions c where c.plan_id=p_plan_id and c.plan_version+1=r.version) completion
  from public.care_workflow_revisions r where r.entity='plan' and r.entity_id=p_plan_id and (p_before_version is null or r.version<p_before_version)
  order by r.version desc limit p_limit+1),rows as(select * from page order by version desc limit p_limit)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(rows) order by version desc) from rows),'[]'),
  'next',case when (select count(*) from page)>p_limit then (select min(version) from rows) else null end) into result;
 return result;
end $$

create function public.list_care_completion_sources(p_pet_id uuid,p_source_kind text default null,p_before jsonb default null,p_limit integer default 50,p_plan_id uuid default null)
returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;before_at timestamptz;before_kind text;before_id uuid;after_day date;
begin
 perform public.clinical_require_staff();
 if p_pet_id is null or p_limit is null or p_limit not between 1 and 100 or p_source_kind is not null and p_source_kind not in ('service','vaccine','lab')
 then raise exception 'Patient and bounded completion-source page required' using errcode='23514';end if;
 if p_plan_id is not null then
  select greatest(p.anchor_on,c.completed_on) into after_day from public.patient_care_plans p
  left join public.care_plan_completions c on c.id=p.last_completion_id where p.id=p_plan_id and p.pet_id=p_pet_id;
  if not found then raise exception 'Patient plan unavailable' using errcode='42501';end if;
 end if;
 if p_before is not null then
  perform public.native_rx_keys(p_before,array['at','source_kind','id']);
  before_at:=public.native_correction_instant(p_before->'at');before_kind:=p_before->>'source_kind';before_id:=public.native_rx_uuid(p_before->'id');
  if before_kind is null or before_kind not in ('service','vaccine','lab') then raise exception 'Invalid source cursor' using errcode='23514';end if;
 end if;
 with candidates as(
  select 'service'::text kind,s.id,s.performed_at at_instant from public.patient_service_events s where s.pet_id=p_pet_id and s.performed_at<=clock_timestamp()
   and not exists(select 1 from public.patient_service_corrections c where c.service_event_id=s.id)
  union all select 'vaccine',v.id,v.administered_at from public.patient_treatments v where v.pet_id=p_pet_id and v.kind='vaccine' and not v.historical
   and v.administered_at<=clock_timestamp() and not exists(select 1 from public.patient_treatment_corrections c where c.treatment_id=v.id)
  union all select 'lab',l.id,l.collected_date::timestamp at time zone 'America/Denver' from public.patient_lab_orders l where l.pet_id=p_pet_id
   and l.status in ('collected','resulted') and l.collected_date is not null and l.collected_date<=(clock_timestamp() at time zone 'America/Denver')::date
 ),page as(select * from candidates where (p_source_kind is null or kind=p_source_kind)
  and (after_day is null or (at_instant at time zone 'America/Denver')::date>after_day)
  and (p_plan_id is null or not exists(select 1 from public.care_plan_completions c where c.plan_id=p_plan_id and c.source_kind=candidates.kind and c.source_id=candidates.id))
  and (p_before is null or (at_instant,kind,id)<(before_at,before_kind,before_id)) order by at_instant desc,kind desc,id desc limit p_limit+1),
 rows as(select *,public.care_completion_source(p_pet_id,kind,id) source from page order by at_instant desc,kind desc,id desc limit p_limit)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(source order by at_instant desc,kind desc,id desc) from rows where source is not null),'[]'),
  'next',case when (select count(*) from page)>p_limit then (select jsonb_build_object('at',at_instant,'source_kind',kind,'id',id) from rows order by at_instant,kind,id limit 1) else null end) into result;
 return result;
end $$

create function public.list_recurring_care_due(p_filter text default 'upcoming',p_before jsonb default null,p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path=public as $$
declare result jsonb;today date:=(clock_timestamp() at time zone 'America/Denver')::date;before_due date;before_id uuid;
begin
 perform public.clinical_require_staff();
 if p_filter is null or p_filter not in ('upcoming','overdue','all','review') or p_limit is null or p_limit not between 1 and 100
 then raise exception 'Due filter and bounded page required' using errcode='23514';end if;
 if p_before is not null then
  perform public.native_rx_keys(p_before,array['due_on','id']);before_due:=public.care_date(p_before->'due_on');before_id:=public.native_rx_uuid(p_before->'id');
 end if;
 with page as(select p.* from public.patient_care_plans p join public.pets pet on pet.id=p.pet_id
  where pet.archived_at is null and pet.deceased_at is null and p.status=case when p_filter='review' then 'proposed' else 'current' end
   and (p_filter in ('all','review') or p_filter='overdue' and p.due_on<today or p_filter='upcoming' and p.due_on between today and today+30)
   and (p_before is null or (p.due_on,p.id)>(before_due,before_id)) order by p.due_on,p.id limit p_limit+1),
 rows as(select * from page order by due_on,id limit p_limit)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(public.care_plan_display(id) order by due_on,id) from rows),'[]'),
  'next',case when (select count(*) from page)>p_limit then (select jsonb_build_object('due_on',due_on,'id',id) from rows order by due_on desc,id desc limit 1) else null end) into result;
 return result;
end $$

create function public.list_care_plan_delivery_windows() returns jsonb language plpgsql security definer set search_path=public as $$
begin
 perform public.care_require_admin();
 return coalesce((select jsonb_agg(to_jsonb(w) order by policy_id) from public.care_plan_delivery_windows w),'[]');
end $$

create function public.read_care_workflow_action(p_action_id uuid,p_kind text,p_entity_id uuid,p_pet_id uuid,p_request jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare actor uuid;r public.care_workflow_actions;
begin
 actor:=public.clinical_require_staff();
 if p_action_id is null or p_entity_id is null or p_kind is null or p_kind not in ('template','plan','completion','delivery_policy')
 or jsonb_typeof(p_request) is distinct from 'object' then raise exception 'Exact action identity and request required' using errcode='23514';end if;
 select * into r from public.care_workflow_actions where id=p_action_id;
 if not found then return null;end if;
 if row(r.kind,r.entity_id,r.pet_id,r.actor_id,r.request) is distinct from row(p_kind,p_entity_id,p_pet_id,actor,p_request)
 then raise exception 'Care action identity reused with changed request' using errcode='23505';end if;
 return r.receipt;
end $$

-- Public reads/writes require actual staff authorization; helpers and physical tables stay private.
do $$declare p record;begin
 for p in select oid from pg_proc where pronamespace='public'::regnamespace and proname=any(array[
  'save_recurring_care_template','save_patient_care_plan','preview_care_plan_completion','complete_patient_care_plan','save_care_plan_delivery_policy',
  'list_recurring_care_templates','read_recurring_care_template','list_patient_care_plans','read_patient_care_plan','list_care_plan_history','list_care_completion_sources',
  'list_recurring_care_due','list_care_plan_delivery_windows','read_care_workflow_action']) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',p.oid::regprocedure);
  execute format('grant execute on function %s to authenticated',p.oid::regprocedure);
 end loop;
end $$

-- Extend list_care_reminder_candidates; preserve the existing signature and grants.
CREATE OR REPLACE FUNCTION public.list_care_reminder_candidates(p_through date, p_after_kind text DEFAULT ''::text, p_after_id uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid, p_limit integer DEFAULT 100)
 RETURNS TABLE(source_kind text, source_id uuid, source_version integer, pet_id uuid, due_on date)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service discovery only' using errcode='42501';end if;
 if p_through is null or not isfinite(p_through) or p_limit is null or p_limit not between 1 and 500 or p_after_kind is null or p_after_id is null then raise exception 'Finite discovery horizon and bounded page required' using errcode='23514';end if;
 return query select x.kind,x.id,x.version,x.patient,x.due from (
 select 'vaccine'::text kind,v.id,v.version,v.pet_id patient,v.current_due_on due from public.patient_vaccine_due_plans v where v.status='current' and v.reminders_enabled
 union all select 'lab'::text,l.id,l.version,l.pet_id,l.due_date from public.patient_lab_orders l where l.status in ('planned','ordered') and l.reminders_enabled and l.due_date is not null
 union all select 'care_plan',cp.id,cp.version,cp.pet_id,cp.due_on from public.patient_care_plans cp where cp.status='current' and cp.reminders_enabled and public.care_plan_source_is_current(cp.id)
 ) x join public.pets p on p.id=x.patient where p.archived_at is null and p.deceased_at is null and x.due<=p_through and row(x.kind,x.id)>row(p_after_kind,p_after_id) order by x.kind,x.id limit p_limit;
end $function$

-- Extend enqueue_care_reminder; preserve the existing signature and grants.
CREATE OR REPLACE FUNCTION public.enqueue_care_reminder(p_id uuid, p_source_kind text, p_source_id uuid, p_expected_source_version integer, p_message_template_id uuid, p_expected_template_version integer)
 RETURNS care_reminder_jobs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.care_reminder_jobs;t public.care_message_templates;p public.pets;v public.patient_vaccine_due_plans;l public.patient_lab_orders;cp public.patient_care_plans;patient_id uuid;due date;care_name text;snapshot jsonb;body text;part record;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Service enqueue only' using errcode='42501';end if;
 if p_id is null then raise exception 'Stable job ID required' using errcode='23514';end if;
 if p_source_kind='vaccine' then select pet_id into patient_id from public.patient_vaccine_due_plans where id=p_source_id;
 elsif p_source_kind='lab' then select pet_id into patient_id from public.patient_lab_orders where id=p_source_id;
 elsif p_source_kind='care_plan' then select pet_id into patient_id from public.patient_care_plans where id=p_source_id;
 else raise exception 'Unsupported reminder source' using errcode='23514';end if;
 select * into p from public.pets where id=patient_id and archived_at is null and deceased_at is null for share;if not found then raise exception 'Reminder requires an active patient' using errcode='23514';end if;
 if p_source_kind='vaccine' then
  select * into v from public.patient_vaccine_due_plans where id=p_source_id for share;
  if v.version is distinct from p_expected_source_version or v.status<>'current' or not v.reminders_enabled or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.treatment_id) then raise exception 'Vaccine due source is not current or enabled' using errcode='PT409';end if;
  due=v.current_due_on;care_name=v.template_snapshot->>'name';snapshot=to_jsonb(v);
 elsif p_source_kind='care_plan' then
  select * into cp from public.patient_care_plans where id=p_source_id for share;
  if cp.id is null or cp.version is distinct from p_expected_source_version or not cp.reminders_enabled or not public.care_plan_source_is_current(cp.id) then raise exception 'Reviewed recurring care source is not current or enabled' using errcode='PT409';end if;
  due=cp.due_on;care_name=cp.name;snapshot=to_jsonb(cp);
 else
  select * into l from public.patient_lab_orders where id=p_source_id for share;
  if l.version is distinct from p_expected_source_version or l.status not in ('planned','ordered') or not l.reminders_enabled or l.due_date is null then raise exception 'Lab due source is not current or enabled' using errcode='PT409';end if;
  due=l.due_date;care_name=l.test_name;snapshot=to_jsonb(l);
 end if;
 select * into t from public.care_message_templates where id=p_message_template_id for share;
 if t.id is null or not t.active or t.version is distinct from p_expected_template_version then raise exception 'Message template changed or retired' using errcode='PT409';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,16));
 select * into r from public.care_reminder_jobs where id=p_id;
 if found then if row(r.source_kind,r.source_id,r.source_version,r.message_template_id,r.message_template_version) is distinct from row(p_source_kind,p_source_id,p_expected_source_version,p_message_template_id,p_expected_template_version) then raise exception 'Job ID reused with changed request' using errcode='42501';end if;return r;end if;
 -- A separate stable request ID for the same source/template version still returns the one canonical job.
 perform pg_advisory_xact_lock(hashtextextended(p_source_kind||p_source_id::text||p_expected_source_version::text||p_message_template_id::text||p_expected_template_version::text,17));
 select * into r from public.care_reminder_jobs where source_kind=p_source_kind and source_id=p_source_id and source_version=p_expected_source_version and message_template_id=p_message_template_id and message_template_version=p_expected_template_version;if found then return r;end if;
 body='';for part in select m[1] as token from regexp_matches(t.body,'(\{\{patient_name\}\}|\{\{care_name\}\}|\{\{due_date\}\}|[^{}]+)','g') m loop body=body||case part.token when '{{patient_name}}' then p.name when '{{care_name}}' then care_name when '{{due_date}}' then due::text else part.token end;end loop;
 insert into public.care_reminder_jobs(id,source_kind,source_id,source_version,pet_id,client_id,message_template_id,message_template_version,channel,scheduled_on,due_on,rendered_body,source_snapshot,template_snapshot) values(p_id,p_source_kind,p_source_id,p_expected_source_version,p.id,p.client_id,t.id,t.version,t.channel,due-t.days_before,due,body,snapshot,to_jsonb(t)) returning * into r;return r;
end $function$

-- Extend reminder_delivery_context; preserve the existing signature and grants.
CREATE OR REPLACE FUNCTION public.reminder_delivery_context(p_job_kind text, p_job_id uuid, p_policy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare policy public.reminder_automation_policies;t public.care_message_templates;j public.care_reminder_jobs;ar public.appointment_reminders;a public.appointments;v public.patient_vaccine_due_plans;l public.patient_lab_orders;p public.pets;c public.clients;actor uuid;source jsonb;body text;care_name text;due date;part record;recipient text;cp public.patient_care_plans;w public.care_plan_delivery_windows;result jsonb;own_outbox uuid;
begin
 select * into policy from public.reminder_automation_policies where id=p_policy_id for share;
 if policy.id is null or not policy.enabled or not public.is_active_staff(policy.approved_by) then return null;end if;
 select * into t from public.care_message_templates where id=policy.message_template_id for share;
 if t.id is null or not t.active or t.version<>policy.message_template_version or upper(t.channel)<>policy.channel or not public.is_active_staff(t.updated_by) then return null;end if;
 if p_job_kind='care' then
  select * into j from public.care_reminder_jobs where id=p_job_id for update;
  if j.id is null or j.status<>'pending' or j.source_kind<>policy.source_kind or upper(j.channel)<>policy.channel or j.message_template_id<>t.id or j.message_template_version<>t.version or j.scheduled_on>(clock_timestamp() at time zone 'America/Denver')::date then return null;end if;
  if j.source_kind='vaccine' then select * into v from public.patient_vaccine_due_plans where id=j.source_id for share;
   if v.id is null or v.version<>j.source_version or v.status<>'current' or not v.reminders_enabled or v.pet_id<>j.pet_id or v.current_due_on<>j.due_on or exists(select 1 from public.patient_treatment_corrections where treatment_id=v.treatment_id) then return null;end if;
   source=to_jsonb(v);actor=v.updated_by;
  elsif j.source_kind='care_plan' then
   select * into cp from public.patient_care_plans where id=j.source_id for share;
   if cp.id is null or cp.version<>j.source_version or not cp.reminders_enabled or cp.pet_id<>j.pet_id or cp.due_on<>j.due_on or not public.care_plan_source_is_current(cp.id) then return null;end if;
   select outbox_id into own_outbox from public.reminder_outbox_links where job_kind='care' and job_id=j.id;
   if public.care_occurrence_has_handoff(cp.occurrence_id,own_outbox) then return null;end if;
   source=to_jsonb(cp);actor=cp.updated_by;
  else select * into l from public.patient_lab_orders where id=j.source_id for share;
   if l.id is null or l.version<>j.source_version or l.status not in ('planned','ordered') or not l.reminders_enabled or l.pet_id<>j.pet_id or l.due_date is distinct from j.due_on then return null;end if;
   source=to_jsonb(l);actor=l.updated_by;
  end if;
  if source is distinct from j.source_snapshot or actor is distinct from (j.source_snapshot->>'updated_by')::uuid then return null;end if;
  select * into p from public.pets where id=j.pet_id for share;
  if p.client_id is distinct from j.client_id then return null;end if;body=j.rendered_body;due=j.due_on;
 elsif p_job_kind='appointment' then
  select * into ar from public.appointment_reminders where id=p_job_id for update;
  if ar.id is null or ar.status<>'PENDING' or ar.remind_at>clock_timestamp() or ar.channel<>policy.channel or policy.source_kind<>'appointment' then return null;end if;
  select * into a from public.appointments where id=ar.appointment_id for share;
  if a.id is null or a.version<>ar.appointment_version or a.status not in ('SCHEDULED','CONFIRMED') or a.scheduled_at<=clock_timestamp() or a.pet_id is null then return null;end if;
  actor=a.updated_by;source=to_jsonb(a);select * into p from public.pets where id=a.pet_id for share;
  if p.client_id is distinct from a.client_id then return null;end if;
  due=(a.scheduled_at at time zone 'America/Denver')::date;
  care_name=a.appointment_type||' · '||to_char(a.scheduled_at at time zone 'America/Denver','YYYY-MM-DD HH24:MI')||' America/Denver · '||a.address_snapshot;
  body='';for part in select m[1] token from regexp_matches(t.body,'(\{\{patient_name\}\}|\{\{care_name\}\}|\{\{due_date\}\}|[^{}]+)','g') m loop body=body||case part.token when '{{patient_name}}' then p.name when '{{care_name}}' then care_name when '{{due_date}}' then due::text else part.token end;end loop;
 else return null;end if;
 if p.id is null or p.archived_at is not null or p.deceased_at is not null or actor is null or not public.is_active_staff(actor) then return null;end if;
 select * into c from public.clients where id=p.client_id for share;
 recipient=public.communication_recipient(policy.channel,case when policy.channel='EMAIL' then c.primary_email else c.primary_phone end);
 if recipient is null or public.communication_is_suppressed(policy.channel,recipient,c.id) or length(body)<1 or (policy.channel='SMS' and length(body)>1600) then return null;end if;
 if policy.source_kind='care_plan' then
  select * into w from public.care_plan_delivery_windows where policy_id=policy.id for share;
  if w.policy_id is null or public.appointment_reminder_channel(c.id) is distinct from policy.channel then return null;end if;
 end if;
 result:=jsonb_build_object('job_kind',p_job_kind,'job_id',p_job_id,'policy',to_jsonb(policy),'template',to_jsonb(t),'source',source,'actor_id',actor,'pet_id',p.id,'patient_name',p.name,'client_id',c.id,'recipient',recipient,'channel',policy.channel,'subject',policy.subject,'body',body,'due_on',due);
 if policy.source_kind='care_plan' then result:=result||jsonb_build_object('send_window',to_jsonb(w));end if;
 return result;
end $function$

-- Extend save_reminder_automation_policy; preserve the existing signature and grants.
CREATE OR REPLACE FUNCTION public.save_reminder_automation_policy(p_id uuid, p_expected_version integer, p_source_kind text, p_channel text, p_message_template_id uuid, p_message_template_version integer, p_subject text, p_enabled boolean, p_review_note text)
 RETURNS reminder_automation_policies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare actor uuid;r public.reminder_automation_policies;t public.care_message_templates;
begin if p_source_kind='care_plan' then raise exception 'Use reviewed recurring care delivery policy with its send window' using errcode='23514';end if;actor=public.care_require_admin();if p_id is null then raise exception 'Stable policy ID required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,18));select * into r from public.reminder_automation_policies where id=p_id for update;
 if found then
  if r.approved_by=actor and r.version=coalesce(p_expected_version,0)+1 and row(r.source_kind,r.channel,r.message_template_id,r.message_template_version,r.subject,r.enabled,r.review_note) is not distinct from row(p_source_kind,p_channel,p_message_template_id,p_message_template_version,coalesce(p_subject,''),p_enabled,trim(p_review_note)) then return r;end if;
  if r.version is distinct from p_expected_version then raise exception 'Automation policy version conflict' using errcode='PT409';end if;
  if row(r.source_kind,r.channel) is distinct from row(p_source_kind,p_channel) then raise exception 'Policy source and channel are immutable' using errcode='23514';end if;
 elsif p_expected_version is not null then raise exception 'Automation policy version conflict' using errcode='PT409';end if;
 select * into t from public.care_message_templates where id=p_message_template_id for share;
 if t.id is null or not t.active or t.version is distinct from p_message_template_version or upper(t.channel) is distinct from p_channel then raise exception 'Select current reviewed wording for the policy channel' using errcode='23514';end if;
 if r.id is null then insert into public.reminder_automation_policies(id,source_kind,channel,message_template_id,message_template_version,subject,enabled,review_note,approved_by) values(p_id,p_source_kind,p_channel,t.id,t.version,coalesce(p_subject,''),p_enabled,trim(p_review_note),actor) returning * into r;
 else update public.reminder_automation_policies set message_template_id=t.id,message_template_version=t.version,subject=coalesce(p_subject,''),enabled=p_enabled,review_note=trim(p_review_note),version=version+1,approved_by=actor,approved_at=now() where id=p_id returning * into r;end if;
 insert into public.reminder_automation_policy_history(policy_id,version,snapshot) values(r.id,r.version,to_jsonb(r));return r;
end $function$

-- Extend claim_communication; preserve the existing signature and grants.
CREATE OR REPLACE FUNCTION public.claim_communication()
 RETURNS communication_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result public.communication_outbox;
begin
 perform public.communication_require_service();
 -- A dead worker with an in-flight request is ambiguous, including after provider acceptance.
 update public.communication_attempts a set outcome='uncertain',finished_at=now(),error_code='worker_lease_expired'
 from public.communication_outbox o where o.state='claimed' and o.lease_expires_at<now() and o.attempt_started_at is not null and a.lease_token=o.lease_token and a.finished_at is null;
 update public.communication_outbox set state=case when attempt_started_at is null then 'pending' else 'uncertain' end,last_error='worker_lease_expired',lease_token=null,lease_expires_at=null,updated_at=now() where state='claimed' and lease_expires_at<now();
 select * into result from public.communication_outbox where state='pending' and not exists(select 1 from public.care_delivery_deferrals d where d.outbox_id=communication_outbox.id and d.eligible_at>clock_timestamp()) order by created_at for update skip locked limit 1;
 if not found then return null; end if;
 update public.communication_outbox set state='claimed',lease_token=gen_random_uuid(),lease_expires_at=now()+interval '2 minutes',attempt_started_at=null,updated_at=now() where id=result.id returning * into result;
 return result;
end $function$

-- Extend start_communication_attempt_without_reminder_guard; preserve the existing signature and grants.
CREATE OR REPLACE FUNCTION public.start_communication_attempt_without_reminder_guard(p_id uuid, p_lease_token uuid, p_provider_config jsonb)
 RETURNS communication_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result public.communication_outbox;deferred public.communication_outbox;
begin
 perform public.communication_require_service();
 select * into result from public.communication_outbox where id=p_id for update;
 if not found or result.state<>'claimed' or result.lease_token is distinct from p_lease_token or result.lease_expires_at<=clock_timestamp() or result.attempt_started_at is not null then raise exception 'Outbox lease is unavailable' using errcode='PT409'; end if;
 -- Re-check immediately before the external request, including actor revocation and contact changes.
 if not public.is_active_staff(result.created_by) or public.communication_is_suppressed(result.channel,result.recipient,result.client_id)
 or not exists(select 1 from public.clients c where c.id=result.client_id and public.communication_recipient(result.channel,case when result.channel='EMAIL' then c.primary_email else c.primary_phone end)=result.recipient) then
  update public.communication_outbox set state='failed',last_error='recipient_or_actor_ineligible',lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where id=p_id returning * into result;
  return result;
 end if;
 if result.channel='SMS' and result.provider is distinct from public.communication_sms_provider() then
  update public.communication_outbox set state='failed',last_error='sms_provider_mismatch',lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where id=p_id returning * into result;
  return result;
 end if;
 if p_provider_config is null or jsonb_typeof(p_provider_config)<>'object' or (result.provider='resend' and (not(p_provider_config ?& array['from','reply_to']) or p_provider_config-array['from','reply_to']<>'{}'::jsonb)) or (result.provider='twilio' and (not(p_provider_config ?& array['from','account_sid']) or p_provider_config-array['from','account_sid']<>'{}'::jsonb))
 or (result.provider='cloudtalk' and (not(p_provider_config ?& array['from','provider']) or p_provider_config-array['from','provider']<>'{}'::jsonb or p_provider_config->>'provider'<>'cloudtalk' or jsonb_typeof(p_provider_config->'from')<>'string' or public.communication_recipient('SMS',p_provider_config->>'from') is distinct from p_provider_config->>'from')) then raise exception 'Invalid provider metadata' using errcode='23514'; end if;
 if result.provider_config is not null and result.provider_config<>p_provider_config then raise exception 'Provider sender metadata changed; reconcile before sending' using errcode='23514'; end if;
 if result.first_attempt_at is not null and result.provider='resend' and result.first_attempt_at<=clock_timestamp()-interval '23 hours' then
  update public.communication_outbox set state='uncertain',last_error='idempotency_window_expired',lease_token=null,lease_expires_at=null,updated_at=clock_timestamp() where id=p_id returning * into result; return result;
 end if;
 deferred:=public.care_defer_attempt(p_id,p_lease_token);if deferred.id is not null then return deferred;end if;
 update public.communication_outbox set provider_config=coalesce(provider_config,p_provider_config),first_attempt_at=coalesce(first_attempt_at,clock_timestamp()),attempt_started_at=clock_timestamp(),attempt_count=attempt_count+1,updated_at=clock_timestamp() where id=p_id returning * into result;
 insert into public.communication_attempts(outbox_id,lease_token,attempt_number) values(result.id,p_lease_token,result.attempt_count);
 return result;
end $function$

do $guard$
declare ids oid[];prior_count integer;p record;body text;definition text;passes integer:=0;
begin
 select coalesce(array_agg(f.oid),'{}'::oid[]) into ids from pg_proc f join pg_language l on l.oid=f.prolang
 where f.pronamespace='public'::regnamespace and l.lanname='plpgsql'
 and (f.proname ~ '^start_communication_attempt' or f.proname=any(array[
  'enqueue_care_reminder','queue_reminder_outbox','queue_due_reminders','preview_outbox_retry',
  'requeue_outbox_retry','outbox_retry_preview_internal','reminder_delivery_context'])
 or f.prosrc ~* '(insert[[:space:]]+into|update|delete[[:space:]]+from)[[:space:]]+(public\.)?(pets|appointments|patient_vaccine_due_plans|patient_lab_orders|care_message_templates|reminder_automation_policies|patient_treatment_corrections|patient_service_corrections)\M');
 loop
  prior_count:=cardinality(ids);
  select coalesce(array_agg(f.oid),'{}'::oid[]) into ids from pg_proc f join pg_language l on l.oid=f.prolang
  where f.pronamespace='public'::regnamespace and l.lanname='plpgsql'
  and (f.oid=any(ids) or exists(select 1 from pg_proc guarded where guarded.oid=any(ids)
   and f.prosrc ~* ('\m'||guarded.proname||'[[:space:]]*\(')));
  passes:=passes+1;
  exit when cardinality(ids)=prior_count;
  if passes>30 then raise exception 'Eligibility entry-point discovery did not converge';end if;
 end loop;
 for p in select oid,proname,prosrc from pg_proc where oid=any(ids) order by oid loop
  body:=p.prosrc;
  if position('public.care_eligibility_lock()' in body)=0 then
   if body ~* '(?m)^[[:space:]]*declare\M' then
    body:=regexp_replace(body,'(?im)^([[:space:]]*declare)\M','\1 _lrv_care_gate boolean:=public.care_eligibility_lock();',1,1);
   elsif body ~* '(?m)^[[:space:]]*begin\M' then
    body:=regexp_replace(body,'(?im)^([[:space:]]*begin)\M','\1 perform public.care_eligibility_lock();',1,1);
   else raise exception 'Cannot safely guard eligibility entry point %',p.oid::regprocedure;end if;
  end if;
  if p.proname ~ '^start_communication_attempt' then body:=replace(body,'now()','clock_timestamp()');end if;
  definition:=replace(pg_get_functiondef(p.oid),p.prosrc,body);
  execute definition;
 end loop;
end $guard$

create function public.record_request_revision() returns trigger language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();begin
 if TG_OP='DELETE' then raise exception 'Request history cannot be deleted' using errcode='23514';end if;
 if TG_OP='UPDATE' then
  if row(NEW.id,NEW.client_id,NEW.pet_id,NEW.direction,NEW.created_by,NEW.created_at) is distinct from
     row(OLD.id,OLD.client_id,OLD.pet_id,OLD.direction,OLD.created_by,OLD.created_at)
  then raise exception 'Request identity is immutable' using errcode='23514';end if;
  NEW.version:=OLD.version+1;NEW.updated_by:=actor;NEW.updated_at:=clock_timestamp();
 else NEW.version:=1;NEW.created_by:=actor;NEW.updated_by:=actor;end if;
 return NEW;
end $$

create function public.record_request_inventory(p_pet_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare pages jsonb;page jsonb;candidate jsonb;k text;key text;nodes jsonb:='{}';excluded jsonb:='[]';requires jsonb;missing text[];raw jsonb;table_name text;doc public.patient_documents;raw_count integer:=0;
begin
 perform public.clinical_require_staff();
 with recursive capture(page_offset,contents) as (
  select 0,public.list_record_release_sources_v13(p_pet_id,0)
  union all
  select page_offset+100,public.list_record_release_sources_v13(p_pet_id,page_offset+100) from capture
  where page_offset<9900 and exists(select 1 from jsonb_each(contents->'has_more') h where h.value='true'::jsonb)
 ) select jsonb_agg(contents order by page_offset) into pages from capture;
 if exists(select 1 from jsonb_each(pages->(jsonb_array_length(pages)-1)->'has_more') h where h.value='true'::jsonb)
 then raise exception 'Chart exceeds complete-capture capacity; no partial manifest was created' using errcode='23514';end if;
 for page in select value from jsonb_array_elements(pages) loop
  foreach k in array public.record_request_families() loop
   for candidate in select value from jsonb_array_elements(page->k) loop
    key:=k||':'||(candidate->>'id');
    if nodes ? key then raise exception 'Duplicate source in captured discovery' using errcode='23514';end if;
    requires:='[]';
    if candidate ? 'required_document_id' then requires:=jsonb_build_array('document_ids:'||coalesce(candidate->>'required_document_id','missing'));end if;
    if k='document_ids' then
     select * into doc from public.patient_documents where id=(candidate->>'id')::uuid and pet_id=p_pet_id;
     if doc.status<>'ready' or doc.visibility<>'client_shareable' or not exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=doc.file_path and o.metadata->>'size'=doc.file_size::text and o.metadata->>'mimetype'=doc.mime_type) then
      excluded:=excluded||jsonb_build_array(jsonb_build_object('family',k,'id',candidate->>'id','label',candidate->>'label','reason','Original file is unavailable or no longer matches its metadata'));continue;
     end if;
     requires:=coalesce((select jsonb_agg('lab_report_ids:'||v) from jsonb_array_elements_text(coalesce(candidate->'required_lab_report_ids','[]')) v),'[]')||coalesce((select jsonb_agg('external_record_ids:'||v) from jsonb_array_elements_text(coalesce(candidate->'required_external_record_ids','[]')) v),'[]');
     candidate:=candidate||jsonb_build_object('document_category',doc.category);
    end if;
    nodes:=nodes||jsonb_build_object(key,candidate||jsonb_build_object('family',k,'requires',requires));
   end loop;
  end loop;
 end loop;
 -- Remove incomplete dependency groups explicitly. Never attach a private/missing original.
 loop
  select array_agg(n.key order by n.key) into missing from jsonb_each(nodes) n
  where exists(select 1 from jsonb_array_elements_text(n.value->'requires') d where not nodes ? d);
  exit when missing is null;
  foreach key in array missing loop
   candidate:=nodes->key;
   excluded:=excluded||jsonb_build_array(jsonb_build_object('family',candidate->>'family','id',candidate->>'id','label',candidate->>'label','reason','Required original or reviewed provenance version is unavailable'));
   nodes:=nodes-key;
  end loop;
 end loop;
 -- Explain raw records outside discovery: unsigned, internal, invalidated and unreviewed history.
 foreach k in array public.record_request_families() loop
  table_name:=case k when 'problem_ids' then 'patient_problems' when 'patient_summary_ids' then 'pets' when 'weight_ids' then 'patient_weights' when 'treatment_ids' then 'patient_treatments' when 'encounter_ids' then 'clinical_encounters' when 'certificate_ids' then 'vaccine_certificates' when 'lab_order_ids' then 'patient_lab_orders' when 'lab_report_ids' then 'lab_report_versions' when 'native_prescription_ids' then 'native_prescription_authorizations' when 'native_dispense_ids' then 'native_dispenses' when 'imported_prescription_ids' then 'ezyvet_imported_prescriptions' when 'imported_vaccination_ids' then 'ezyvet_imported_vaccinations' when 'imported_history_ids' then 'ezyvet_imported_histories' when 'external_record_ids' then 'external_record_versions' when 'api_attachment_ids' then 'ezyvet_attachment_record_versions' when 'document_ids' then 'patient_documents' when 'dental_ids' then 'dental_charts' when 'qol_ids' then 'patient_qol_records' when 'anesthesia_ids' then 'patient_anesthesia_records' else 'patient_lesions' end;
  for raw in execute format('select to_jsonb(t) from public.%I t where %s=$1 order by id',table_name,case k when 'patient_summary_ids' then 'id' else 'pet_id' end) using p_pet_id loop
   raw_count:=raw_count+1;if raw_count>20000 then raise exception 'Chart census exceeds complete-capture capacity; no partial manifest was created' using errcode='23514';end if;
   key:=k||':'||(raw->>'id');
   if not nodes ? key and not exists(select 1 from jsonb_array_elements(excluded) e where e->>'family'=k and e->>'id'=raw->>'id') then
    excluded:=excluded||jsonb_build_array(jsonb_build_object('family',k,'id',raw->>'id','label',coalesce(raw->>'file_name',raw->>'test_name',raw->>'title',raw->>'label','Unavailable source'),
     'reason',case when k in ('encounter_ids','dental_ids','qol_ids','anesthesia_ids') then 'Unsigned clinical record' when k='certificate_ids' then 'Invalidated certificate' when k='document_ids' then 'Internal, pending, voided or abandoned original' when k='lab_order_ids' and raw->>'status'<>'resulted' then 'Laboratory work is not resulted' when k='lab_order_ids' then 'Resulted laboratory record lacks a shareable original' else 'Source identity, version, original or clinical review is not eligible' end));
   end if;
  end loop;
 end loop;
 if (select count(*) from jsonb_each(nodes))>10000 then raise exception 'Chart exceeds complete-capture capacity; no partial manifest was created' using errcode='23514';end if;
 perform public.clinical_require_staff();
 return jsonb_build_object('nodes',nodes,'exclusions',excluded,'captured_at',statement_timestamp());
end $$

create function public.record_request_bounded_preview(p_request public.record_requests,p_nodes jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare selection jsonb:=public.record_request_selection(p_nodes);k text;preview jsonb;original_bytes bigint;report_budget bigint;count_sources integer;previous_context text:=current_setting('lrv.record_request_preview_id',true);
begin
 for k in select jsonb_object_keys(selection) loop
  if jsonb_array_length(selection->k)>(case when k in ('api_attachment_ids','imported_vaccination_ids','imported_prescription_ids','native_prescription_ids','native_dispense_ids') then 20 else 100 end) then return null;end if;
 end loop;
 if jsonb_array_length(coalesce(selection->'document_ids','[]'))+jsonb_array_length(coalesce(selection->'api_attachment_ids','[]'))>24 then return null;end if;
 begin
  perform set_config('lrv.record_request_preview_id',p_request.id::text,true);
  preview:=public.preview_record_release_v13(p_request.pet_id,p_request.client_id,p_request.channel,p_request.recipient,selection);
  perform set_config('lrv.record_request_preview_id',coalesce(previous_context,''),true);
 exception when check_violation then
  perform set_config('lrv.record_request_preview_id',coalesce(previous_context,''),true);
  if SQLERRM in ('Release exceeds maximum reviewed snapshot size','Release exceeds the reviewed snapshot limit; split into smaller packages') then return null;end if;
  raise;
 end;
 select count(*) into count_sources from jsonb_each(p_nodes);
 -- Conservative escaping/markup allowance; production builders still check the actual bytes.
 report_budget:=octet_length((preview->'snapshot')::text)::bigint*12+count_sources::bigint*8192+16384;
 select coalesce(sum(4*((coalesce((a->>'file_size')::bigint,0)+2)/3)+2048),0) into original_bytes from jsonb_array_elements(preview#>'{snapshot,attachments}') a;
 if original_bytes+4*((report_budget+2)/3)+16384>33554432 then return null;end if;
 return preview;
end $$

create function public.record_request_audit_revision() returns trigger language plpgsql security definer set search_path=public as $$
begin
 insert into public.record_request_revisions(request_id,version,snapshot,actor_id) values(NEW.id,NEW.version,to_jsonb(NEW),auth.uid());
 insert into public.audit_logs(user_id,action,table_name,record_id,new_data) values(auth.uid(),TG_OP,'record_requests',NEW.id,to_jsonb(NEW));
 return NEW;
end $$

do $$declare t text;begin
 foreach t in array array['record_requests','record_request_actions','record_request_revisions','record_request_receipts','record_request_manifests','record_request_packages','record_request_release_links','record_request_recipient_authorizations','record_request_authorization_revocations','record_request_disclosure_policy'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
  if t not in ('record_requests','record_request_disclosure_policy') then execute format('create trigger record_request_immutable before update or delete on public.%I for each row execute function public.record_request_immutable()',t);end if;
 end loop;
end $$

create function public.record_request_recover(p_action_id uuid,p_request_id uuid,p_kind text,p_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare a public.record_request_actions;actor uuid:=public.clinical_require_staff();begin
 if p_action_id is null or p_request_id is null or p_values is null or jsonb_typeof(p_values)<>'object' then raise exception 'Bounded request action required' using errcode='23514';end if;
 select * into a from public.record_request_actions where id=p_action_id;
 if not found then return null;end if;
 if a.actor_id<>actor or a.intent is distinct from public.record_request_intent(p_request_id,p_kind,p_version,p_values) then raise exception 'Action identifier conflicts with saved work' using errcode='23505';end if;
 return a.receipt;
end $$

create function public.record_request_commit_action(p_action_id uuid,p_request_id uuid,p_kind text,p_version integer,p_values jsonb,p_receipt jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
begin
 insert into public.record_request_actions(id,request_id,kind,intent,receipt,actor_id)
 values(p_action_id,p_request_id,p_kind,public.record_request_intent(p_request_id,p_kind,p_version,p_values),p_receipt,public.clinical_require_staff());
 return p_receipt;
end $$

create function public.save_record_request(p_action_id uuid,p_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;old_receipt jsonb;k text;pet uuid;client uuid;direction text;v_subset text;v_channel text;v_recipient text;v_recipient_kind text;v_recipient_name text;assigned uuid;ticket uuid;conversation uuid;requested date;due date;
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 old_receipt:=public.record_request_recover(p_action_id,p_id,'save',p_expected_version,p_values);if old_receipt is not null then return old_receipt;end if;
 for k in select jsonb_object_keys(p_values) loop if k<>all(array['pet_id','client_id','direction','subset','channel','recipient_kind','recipient_name','recipient_email','requester_name','request_note','requested_on','due_on','assigned_to','ticket_id','conversation_id']) then raise exception 'Unknown request field' using errcode='23514';end if;end loop;
 pet:=public.native_rx_uuid(p_values->'pet_id');client:=public.native_rx_uuid(p_values->'client_id');direction:=p_values->>'direction';v_subset:=p_values->>'subset';v_channel:=nullif(p_values->>'channel','');
 assigned:=public.native_rx_uuid(coalesce(p_values->'assigned_to','null'::jsonb),true);ticket:=public.native_rx_uuid(coalesce(p_values->'ticket_id','null'::jsonb),true);conversation:=public.native_rx_uuid(coalesce(p_values->'conversation_id','null'::jsonb),true);
 requested:=public.care_date(p_values->'requested_on');due:=case when p_values->>'due_on' is null then null else public.care_date(p_values->'due_on') end;
 if pet is null or client is null or direction not in ('incoming','outgoing') or v_subset not in ('full','vaccines','labs','custom') or direction is null or v_subset is null or requested is null
 or length(trim(coalesce(p_values->>'requester_name',''))) not between 1 and 160 or length(coalesce(p_values->>'request_note',''))>2000 or (due is not null and due<requested)
 then raise exception 'Review patient, scope, requester and calendar dates' using errcode='23514';end if;
 if not exists(select 1 from public.pets where id=pet and client_id=client) then raise exception 'Patient does not belong to household' using errcode='42501';end if;
 if assigned is not null and not public.is_active_staff(assigned) then raise exception 'Assignee must be active staff' using errcode='23514';end if;
 if conversation is not null and not exists(select 1 from public.conversations where id=conversation and client_id=client) then raise exception 'Conversation does not belong to household' using errcode='42501';end if;
 if ticket is not null and not exists(select 1 from public.tickets where id=ticket) then raise exception 'Linked ticket is missing' using errcode='23514';end if;
 if ticket is not null and exists(select 1 from public.tickets t join public.conversations c on c.id=t.conversation_id where t.id=ticket and c.client_id is distinct from client) then raise exception 'Ticket conversation belongs to another household' using errcode='42501';end if;
 if direction='outgoing' then
  if v_channel is null or v_channel not in ('EMAIL','SMS') then raise exception 'Choose client email or text' using errcode='23514';end if;
  v_recipient_kind:=coalesce(p_values->>'recipient_kind','client');
  if v_recipient_kind='third_party' then
   v_recipient_name:=trim(coalesce(p_values->>'recipient_name',''));v_recipient:=public.communication_recipient('EMAIL',p_values->>'recipient_email');
   if v_channel<>'EMAIL' or length(v_recipient_name) not between 1 and 160 or v_recipient is null or length(v_recipient)>254 or v_recipient !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' then raise exception 'Named third-party email destination required' using errcode='23514';end if;
  elsif v_recipient_kind='client' then
   select full_name,public.communication_recipient(v_channel,case v_channel when 'EMAIL' then primary_email else primary_phone end) into v_recipient_name,v_recipient from public.clients where id=client;
  else raise exception 'Unknown recipient scope' using errcode='23514';end if;
  if v_recipient is null or v_recipient='' then raise exception 'Verified client contact required' using errcode='23514';end if;
 else v_channel:=null;v_recipient:=null;v_recipient_kind:='client';v_recipient_name:=null;end if;
 select * into r from public.record_requests where id=p_id for update;
 perform public.clinical_require_staff();
 if r.id is null then
  if p_expected_version is not null then raise exception 'Request changed; reload' using errcode='PT409';end if;
  insert into public.record_requests(id,client_id,pet_id,direction,subset,channel,recipient,recipient_kind,recipient_name,requester_name,request_note,requested_on,due_on,assigned_to,ticket_id,conversation_id,created_by,updated_by)
  values(p_id,client,pet,direction,v_subset,v_channel,v_recipient,v_recipient_kind,v_recipient_name,trim(p_values->>'requester_name'),coalesce(p_values->>'request_note',''),requested,due,assigned,ticket,conversation,actor,actor) returning * into r;
 else
  if r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
  if row(r.pet_id,r.client_id,r.direction) is distinct from row(pet,client,direction) then raise exception 'Request association cannot change' using errcode='42501';end if;
  if r.status in ('fulfilled','cancelled') then raise exception 'Closed request cannot be edited' using errcode='23514';end if;
  if r.active_manifest_id is not null and row(r.subset,r.channel,r.recipient,r.recipient_kind,r.recipient_name) is distinct from row(v_subset,v_channel,v_recipient,v_recipient_kind,v_recipient_name) then raise exception 'Frozen package scope or contact changed; cancel and create a new request' using errcode='PT409';end if;
  update public.record_requests set subset=v_subset,channel=v_channel,recipient=v_recipient,recipient_kind=v_recipient_kind,recipient_name=v_recipient_name,requester_name=trim(p_values->>'requester_name'),request_note=coalesce(p_values->>'request_note',''),requested_on=requested,due_on=due,assigned_to=assigned,ticket_id=ticket,conversation_id=conversation where id=r.id returning * into r;
 end if;
 return public.record_request_commit_action(p_action_id,r.id,'save',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r)));
end $$

create function public.prepare_record_request_manifest(p_action_id uuid,p_request_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;recovered jsonb;inventory jsonb;pool jsonb;selected jsonb;exclusions jsonb;seed text[]:='{}';source record;k text;v text;v_manifest_id uuid;v_component jsonb;current_nodes jsonb:='{}';candidate_nodes jsonb;current_preview jsonb;next_preview jsonb;ordinal integer:=0;summary jsonb;fingerprint text;scoped_expansion boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 recovered:=public.record_request_recover(p_action_id,p_request_id,'manifest',p_expected_version,p_values);if recovered is not null then return recovered;end if;
 if exists(select 1 from jsonb_object_keys(p_values) fields(key) where fields.key<>all(array['manifest_id','selection','review_note'])) or length(trim(coalesce(p_values->>'review_note',''))) not between 1 and 2000 then raise exception 'Review the requested package scope' using errcode='23514';end if;
 v_manifest_id:=public.native_rx_uuid(p_values->'manifest_id');if v_manifest_id is null then raise exception 'Manifest identifier required' using errcode='23514';end if;
 select * into r from public.record_requests where id=p_request_id for update;
 perform public.clinical_require_staff();
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
 if r.direction<>'outgoing' or r.status not in ('requested','preparing','ready') then raise exception 'Outgoing request is not available for preparation' using errcode='23514';end if;
 if r.active_manifest_id is not null and exists(select 1 from public.record_request_packages p join public.record_request_release_links l on l.package_id=p.id where p.manifest_id=r.active_manifest_id) then raise exception 'Confirmed manifest cannot be replaced; create a new request for a different disclosure' using errcode='23514';end if;
 inventory:=public.record_request_inventory(r.pet_id);pool:=inventory->'nodes';exclusions:=inventory->'exclusions';
 if r.subset='custom' then
  if jsonb_typeof(p_values->'selection') is distinct from 'object' then raise exception 'Explicit custom source selection required' using errcode='23514';end if;
  for k in select jsonb_object_keys(p_values->'selection') loop
   if k<>all(public.record_request_families()) or jsonb_typeof(p_values#>array['selection',k])<>'array' or jsonb_array_length(p_values#>array['selection',k])>10000 then raise exception 'Bounded known source families required' using errcode='23514';end if;
   for v in select value from jsonb_array_elements_text(p_values#>array['selection',k]) loop
    if not pool ? (k||':'||v) or (k||':'||v)=any(seed) then raise exception 'Selected source is unavailable or duplicated' using errcode='23514';end if;
    seed:=array_append(seed,k||':'||v);
   end loop;
  end loop;
 else
  if coalesce(p_values->'selection','{}')<>'{}'::jsonb then raise exception 'Preset source selection is server-authoritative' using errcode='23514';end if;
  for source in select * from jsonb_each(pool) order by key loop
   if r.subset='full' or (r.subset='labs' and source.value->>'family' in ('lab_order_ids','lab_report_ids')) or
    (r.subset='vaccines' and (source.value->>'family' in ('certificate_ids','imported_vaccination_ids') or
      (source.value->>'family'='treatment_ids' and exists(select 1 from public.patient_treatments t where t.id=(source.value->>'id')::uuid and t.pet_id=r.pet_id and t.kind='vaccine'))))
   then seed:=array_append(seed,source.key);end if;
  end loop;
 end if;
 if cardinality(seed)=0 then raise exception 'No eligible sources in the requested subset; no partial package was created' using errcode='23514';end if;
 -- Directed closure adds exactly the originals/provenance required by the chosen sources.
 with recursive closure(key) as (
  select unnest(seed)
  union
  select d.value from closure c cross join lateral jsonb_array_elements_text(pool->c.key->'requires') d
 ) select jsonb_object_agg(c.key,pool->c.key order by c.key) into selected from closure c;
 for source in select * from jsonb_each(pool) where not selected ? key order by key loop
  exclusions:=exclusions||jsonb_build_array(jsonb_build_object('family',source.value->>'family','id',source.value->>'id','label',source.value->>'label','reason','Outside the explicitly requested subset'));
 end loop;
 -- Undirected dependency components may not be split across package boundaries.
 for v_component in
  with recursive nodes as materialized (select * from jsonb_each(selected)), edges as materialized (
   select n.key a,d.value b from nodes n cross join lateral jsonb_array_elements_text(n.value->'requires') d
   union select d.value,n.key from nodes n cross join lateral jsonb_array_elements_text(n.value->'requires') d
  ), reach(root,key) as (
   select key,key from nodes
   union select w.root,e.b from reach w join edges e on e.a=w.key
  ), membership as (select key,min(root) component from reach group by key), components as (
   select m.component,jsonb_object_agg(n.key,n.value order by n.key) contents from membership m join nodes n on n.key=m.key group by m.component
  ) select contents from components order by component
 loop
  candidate_nodes:=current_nodes||v_component;
  next_preview:=public.record_request_bounded_preview(r,candidate_nodes);
  if next_preview is null then
   if current_nodes='{}'::jsonb then raise exception 'A connected source/original group exceeds reviewed package capacity; no sources were omitted' using errcode='23514';end if;
   ordinal:=ordinal+1;
   scoped_expansion:=r.subset='labs' and exists(select 1 from jsonb_each(current_nodes) n where n.value->>'family'='external_record_ids' or (n.value->>'family'='document_ids' and n.value->>'document_category'<>'lab_result'));
   insert into public.record_request_packages(id,manifest_id,ordinal,release_id,selection,preview,scope_expansion) values(gen_random_uuid(),v_manifest_id,ordinal,gen_random_uuid(),public.record_request_selection(current_nodes),current_preview,scoped_expansion);
   current_nodes:=v_component;current_preview:=public.record_request_bounded_preview(r,v_component);
   if current_preview is null then raise exception 'A connected source/original group exceeds reviewed package capacity; no sources were omitted' using errcode='23514';end if;
  else current_nodes:=candidate_nodes;current_preview:=next_preview;end if;
 end loop;
 ordinal:=ordinal+1;
 scoped_expansion:=r.subset='labs' and exists(select 1 from jsonb_each(current_nodes) n where n.value->>'family'='external_record_ids' or (n.value->>'family'='document_ids' and n.value->>'document_category'<>'lab_result'));
 insert into public.record_request_packages(id,manifest_id,ordinal,release_id,selection,preview,scope_expansion) values(gen_random_uuid(),v_manifest_id,ordinal,gen_random_uuid(),public.record_request_selection(current_nodes),current_preview,scoped_expansion);
 -- Detect mutable discovery drift rather than labeling a changing chart complete.
 if (public.record_request_inventory(r.pet_id)-'captured_at') is distinct from (inventory-'captured_at') then raise exception 'Chart inventory changed during preparation; review and capture again' using errcode='PT409';end if;
 if exists(
  with emitted as (select k.key family,x.value id from public.record_request_packages p cross join lateral jsonb_each(p.selection) k cross join lateral jsonb_array_elements_text(k.value) x where p.manifest_id=v_manifest_id),
  intended as (select value->>'family' family,value->>'id' id from jsonb_each(selected))
  select 1 from ((select family,id from emitted except select family,id from intended) union all (select family,id from intended except select family,id from emitted) union all (select family,id from emitted group by family,id having count(*)<>1)) mismatch
 ) then raise exception 'Manifest partition does not match selected inventory' using errcode='23514';end if;
 select jsonb_agg(jsonb_build_object('id',p.id,'ordinal',p.ordinal,'release_id',p.release_id,'selection',p.selection,'source_hash',p.preview->>'source_hash','scope_expansion',p.scope_expansion) order by p.ordinal) into summary from public.record_request_packages p where p.manifest_id=v_manifest_id;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('request_id',r.id,'pet_id',r.pet_id,'client_id',r.client_id,'subset',r.subset,'channel',r.channel,'recipient',r.recipient,'recipient_kind',r.recipient_kind,'recipient_name',r.recipient_name,'inventory',selected,'exclusions',exclusions,'packages',summary,'captured_at',inventory->'captured_at')::text,'UTF8')),'hex');
 insert into public.record_request_manifests(id,request_id,subset,channel,recipient,captured_at,inventory,exclusions,fingerprint,package_count,source_count,created_by)
 values(v_manifest_id,r.id,r.subset,r.channel,r.recipient,(inventory->>'captured_at')::timestamptz,selected,exclusions,fingerprint,ordinal,(select count(*) from jsonb_each(selected)),actor);
 update public.record_requests set active_manifest_id=v_manifest_id,status='preparing' where id=r.id returning * into r;
 perform public.clinical_require_staff();
 return public.record_request_commit_action(p_action_id,r.id,'manifest',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r),'manifest_id',v_manifest_id,'fingerprint',fingerprint,'package_count',ordinal,'source_count',(select count(*) from jsonb_each(selected))));
end $$

create function public.receive_record_request(p_action_id uuid,p_request_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;recovered jsonb;reference jsonb;d public.patient_documents;seen uuid[]:='{}';ids jsonb:='[]';
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 recovered:=public.record_request_recover(p_action_id,p_request_id,'receive',p_expected_version,p_values);if recovered is not null then return recovered;end if;
 if exists(select 1 from jsonb_object_keys(p_values) fields(key) where fields.key<>all(array['documents','review_note'])) or jsonb_typeof(p_values->'documents') is distinct from 'array' or jsonb_array_length(p_values->'documents') not between 1 and 100 or length(trim(coalesce(p_values->>'review_note',''))) not between 1 and 2000 then raise exception 'Select actual originals and record the receipt review' using errcode='23514';end if;
 select * into r from public.record_requests where id=p_request_id for update;perform public.clinical_require_staff();
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
 if r.direction<>'incoming' or r.status not in ('requested','awaiting_response','received') then raise exception 'Incoming request is not available for receipt' using errcode='23514';end if;
 for reference in select value from jsonb_array_elements(p_values->'documents') order by value->>'id' loop
  if jsonb_typeof(reference)<>'object' or exists(select 1 from jsonb_object_keys(reference) fields(key) where fields.key<>all(array['id','version'])) then raise exception 'Exact original identity and version required' using errcode='23514';end if;
  select * into d from public.patient_documents where id=public.native_rx_uuid(reference->'id') and pet_id=r.pet_id for share;
  if d.id is null or d.status<>'ready' or d.version is distinct from public.native_rx_revision(reference->'version') or d.id=any(seen) or not exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type) then raise exception 'Original is missing, changed or belongs to another patient' using errcode='PT409';end if;
  seen:=array_append(seen,d.id);
  insert into public.record_request_receipts(id,request_id,document_id,document_version,original,review_note,created_by)
  values(gen_random_uuid(),r.id,d.id,d.version,to_jsonb(d)-array['file_path','created_by','voided_by'],trim(p_values->>'review_note'),actor);
  ids:=ids||jsonb_build_array(jsonb_build_object('id',d.id,'version',d.version));
 end loop;
 update public.record_requests set status='received' where id=r.id returning * into r;
 return public.record_request_commit_action(p_action_id,r.id,'receive',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r),'documents',ids));
end $$

create function public.transition_record_request(p_action_id uuid,p_request_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;recovered jsonb;target text:=p_values->>'status';proof jsonb:='{}';n integer;previous_context text:=current_setting('lrv.record_request_preview_id',true);
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 recovered:=public.record_request_recover(p_action_id,p_request_id,'transition',p_expected_version,p_values);if recovered is not null then return recovered;end if;
 if exists(select 1 from jsonb_object_keys(p_values) fields(key) where fields.key<>all(array['status','review_note'])) or target is null or target not in ('requested','awaiting_response','received','preparing','ready','fulfilled','blocked','cancelled') or length(trim(coalesce(p_values->>'review_note',''))) not between 1 and 2000 then raise exception 'Choose a workflow state and record the reason' using errcode='23514';end if;
 select * into r from public.record_requests where id=p_request_id for update;perform public.clinical_require_staff();
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
 if r.status in ('fulfilled','cancelled') or r.status=target then raise exception 'Closed or unchanged request cannot transition' using errcode='23514';end if;
 if r.direction='incoming' and target in ('fulfilled','received') then
  perform 1 from public.patient_documents where id in (select document_id from public.record_request_receipts where request_id=r.id) order by id for share;
 end if;
 if target='received' then
  if r.direction<>'incoming' or r.status<>'blocked' or not exists(select 1 from public.record_request_receipts where request_id=r.id) or exists(select 1 from public.record_request_receipts e left join public.patient_documents d on d.id=e.document_id and d.pet_id=r.pet_id and d.version=e.document_version and d.status='ready' where e.request_id=r.id and (d.id is null or not exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type))) then raise exception 'Resume requires verified saved incoming originals' using errcode='23514';end if;
 elsif target='fulfilled' then
  if r.direction='incoming' then
   if r.status<>'received' or not exists(select 1 from public.record_request_receipts where request_id=r.id) or exists(
    select 1 from public.record_request_receipts e left join public.patient_documents d on d.id=e.document_id and d.pet_id=r.pet_id and d.version=e.document_version and d.status='ready'
    where e.request_id=r.id and (d.id is null or not exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type))
   ) then raise exception 'Verify the actual received originals before fulfillment' using errcode='PT409';end if;
   select jsonb_build_object('documents',jsonb_agg(jsonb_build_object('id',document_id,'version',document_version) order by document_id)) into proof from public.record_request_receipts where request_id=r.id;
  else
   if r.status<>'ready' or r.active_manifest_id is null or exists(
    select 1 from public.record_request_packages p where p.manifest_id=r.active_manifest_id and not exists(select 1 from jsonb_array_elements(public.record_request_deliveries(p.id)) d where d->>'state'='delivered')
   ) then raise exception 'Every numbered package needs provider-confirmed delivery; preparation or acceptance is not delivery' using errcode='23514';end if;
   select jsonb_build_object('packages',jsonb_agg(jsonb_build_object('package_id',p.id,'release_id',p.release_id,'deliveries',public.record_request_deliveries(p.id)) order by p.ordinal),'recipient_read_confirmed',false) into proof from public.record_request_packages p where p.manifest_id=r.active_manifest_id;
  end if;
 elsif target not in ('blocked','cancelled') then
  if r.direction='incoming' then
   if target not in ('requested','awaiting_response') or (r.status='received' and target='requested') then raise exception 'Incoming workflow requires actual original receipt' using errcode='23514';end if;
  else
   if r.status<>'blocked' then raise exception 'Preparation and readiness come from reviewed package actions' using errcode='23514';end if;
   select count(*) into n from public.record_request_packages p join public.record_request_release_links l on l.package_id=p.id where p.manifest_id=r.active_manifest_id;
   if target is distinct from (case when r.active_manifest_id is null then 'requested' when n=(select package_count from public.record_request_manifests where id=r.active_manifest_id) then 'ready' else 'preparing' end) then raise exception 'Resume the actual saved package state' using errcode='23514';end if;
  end if;
 end if;
 -- Cancellation does not acquire any outbox or clinical-source lock. Final authorization
 -- takes SHARE on this row; a provider call already started is not recalled.
 update public.record_requests set status=target where id=r.id returning * into r;
 return public.record_request_commit_action(p_action_id,r.id,'transition',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r),'evidence',proof));
end $$

create function public.confirm_record_request_package(p_action_id uuid,p_request_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;m public.record_request_manifests;p public.record_request_packages;recovered jsonb;release public.record_releases;n integer;previous_context text:=current_setting('lrv.record_request_preview_id',true);
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 recovered:=public.record_request_recover(p_action_id,p_request_id,'confirm',p_expected_version,p_values);if recovered is not null then return recovered;end if;
 if exists(select 1 from jsonb_object_keys(p_values) fields(key) where fields.key<>all(array['package_id','manifest_hash','attest_review','attest_scope_expansion'])) or p_values->'attest_review' is distinct from 'true'::jsonb then raise exception 'Review exact package contents and recipient' using errcode='23514';end if;
 select * into r from public.record_requests where id=p_request_id for update;perform public.clinical_require_staff();
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
 select * into m from public.record_request_manifests where id=r.active_manifest_id and request_id=r.id;
 select * into p from public.record_request_packages where id=public.native_rx_uuid(p_values->'package_id') and manifest_id=m.id;
 if r.direction<>'outgoing' or r.status<>'preparing' or m.id is null or p.id is null or m.fingerprint is distinct from p_values->>'manifest_hash' or row(m.subset,m.channel,m.recipient) is distinct from row(r.subset,r.channel,r.recipient) then raise exception 'Request scope or numbered manifest changed' using errcode='PT409';end if;
 if p.scope_expansion and p_values->'attest_scope_expansion' is distinct from 'true'::jsonb then raise exception 'Review the additional required original/provenance disclosure' using errcode='23514';end if;
 if exists(select 1 from public.record_request_release_links where package_id=p.id) then raise exception 'Package was already confirmed; inspect saved history' using errcode='23505';end if;
 if not public.record_request_authorization_current(r.id,m.id) then raise exception 'Current recipient authority and disclosure review required' using errcode='42501';end if;
 perform set_config('lrv.record_request_preview_id',r.id::text,true);
 release:=public.confirm_record_release_without_record_request(p.release_id,r.pet_id,r.client_id,m.channel,m.recipient,p.selection,p.preview->'snapshot',p.preview->>'source_hash',true);
 perform set_config('lrv.record_request_preview_id',coalesce(previous_context,''),true);
 if not public.record_request_authorization_current(r.id,m.id) then raise exception 'Recipient authorization changed during confirmation' using errcode='42501';end if;
 if release.source_hash is distinct from p.preview->>'source_hash' or release.selection is distinct from p.selection then raise exception 'Release does not match numbered package' using errcode='23514';end if;
 insert into public.record_request_release_links(package_id,release_id,created_by) values(p.id,release.id,actor);
 select count(*) into n from public.record_request_packages pkg join public.record_request_release_links l on l.package_id=pkg.id where pkg.manifest_id=m.id;
 update public.record_requests set status=case when n=m.package_count then 'ready' else 'preparing' end where id=r.id returning * into r;
 return public.record_request_commit_action(p_action_id,r.id,'confirm',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r),'package_id',p.id,'release_id',release.id,'ordinal',p.ordinal,'package_count',m.package_count));
end $$

create function public.authorize_record_request_recipient(p_action_id uuid,p_request_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;m public.record_request_manifests;recovered jsonb;authorization_id uuid;document_id uuid;document_version integer;d public.patient_documents;expiry date;expires timestamptz;
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 recovered:=public.record_request_recover(p_action_id,p_request_id,'authorize',p_expected_version,p_values);if recovered is not null then return recovered;end if;
 if exists(select 1 from jsonb_object_keys(p_values) fields(key) where fields.key<>all(array['authorization_id','manifest_hash','client_authority','destination_verification','evidence_document_id','evidence_document_version','expires_on','attest_client_authority','attest_destination','attest_source_scope'])) or p_values->'attest_client_authority' is distinct from 'true'::jsonb or p_values->'attest_destination' is distinct from 'true'::jsonb or p_values->'attest_source_scope' is distinct from 'true'::jsonb
 or length(trim(coalesce(p_values->>'client_authority',''))) not between 1 and 2000 or length(trim(coalesce(p_values->>'destination_verification',''))) not between 1 and 2000 then raise exception 'Independently verify client authority, destination and exact source scope' using errcode='23514';end if;
 authorization_id:=public.native_rx_uuid(p_values->'authorization_id');document_id:=public.native_rx_uuid(coalesce(p_values->'evidence_document_id','null'::jsonb),true);document_version:=public.native_rx_revision(coalesce(p_values->'evidence_document_version','null'::jsonb));expiry:=public.care_date(p_values->'expires_on');
 expires:=((expiry+1)::timestamp at time zone 'America/Denver');
 if authorization_id is null or expires is null or expires<=clock_timestamp() or expiry>(clock_timestamp() at time zone 'America/Denver')::date+366 or (document_id is null)<>(document_version is null) then raise exception 'Exact authority evidence and a future expiry within one year are required' using errcode='23514';end if;
 select * into r from public.record_requests where id=p_request_id for update;perform public.clinical_require_staff();
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
 select * into m from public.record_request_manifests where id=r.active_manifest_id and request_id=r.id;
 if r.direction<>'outgoing' or r.recipient_kind<>'third_party' or r.channel<>'EMAIL' or r.status<>'preparing' or m.id is null or m.fingerprint is distinct from p_values->>'manifest_hash' then raise exception 'Review the current third-party manifest' using errcode='PT409';end if;
 if document_id is not null then
  select * into d from public.patient_documents where id=document_id and pet_id=r.pet_id and status='ready' and version=document_version for share;
  if d.id is null or not exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type) then raise exception 'Authority evidence original is unavailable' using errcode='PT409';end if;
 end if;
 insert into public.record_request_recipient_authorizations(id,request_id,manifest_id,manifest_hash,recipient_name,recipient,client_authority,destination_verification,evidence_document_id,evidence_document_version,expires_at,created_by)
 values(authorization_id,r.id,m.id,m.fingerprint,r.recipient_name,r.recipient,trim(p_values->>'client_authority'),trim(p_values->>'destination_verification'),document_id,document_version,expires,actor);
 update public.record_requests set request_note=record_requests.request_note where id=r.id returning * into r;
 return public.record_request_commit_action(p_action_id,r.id,'authorize',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r),'authorization_id',authorization_id,'manifest_hash',m.fingerprint,'expires_at',expires));
end $$

create function public.revoke_record_request_authorization(p_action_id uuid,p_request_id uuid,p_expected_version integer,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.record_requests;a public.record_request_recipient_authorizations;recovered jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('record-request-action:'||p_action_id::text,0));
 recovered:=public.record_request_recover(p_action_id,p_request_id,'revoke_authorization',p_expected_version,p_values);if recovered is not null then return recovered;end if;
 if exists(select 1 from jsonb_object_keys(p_values) fields(key) where fields.key<>all(array['authorization_id','review_note'])) or length(trim(coalesce(p_values->>'review_note',''))) not between 1 and 2000 then raise exception 'Record the revocation reason' using errcode='23514';end if;
 select * into r from public.record_requests where id=p_request_id for update;perform public.clinical_require_staff();
 if r.id is null or r.version is distinct from p_expected_version then raise exception 'Request changed; reload' using errcode='PT409';end if;
 select * into a from public.record_request_recipient_authorizations where id=public.native_rx_uuid(p_values->'authorization_id') and request_id=r.id;
 if a.id is null then raise exception 'Authorization does not belong to request' using errcode='42501';end if;
 insert into public.record_request_authorization_revocations(authorization_id,reason,created_by) values(a.id,trim(p_values->>'review_note'),actor);
 update public.record_requests set request_note=record_requests.request_note where id=r.id returning * into r;
 return public.record_request_commit_action(p_action_id,r.id,'revoke_authorization',p_expected_version,p_values,jsonb_build_object('request',to_jsonb(r),'authorization_id',a.id,'revoked',true));
end $$

create function public.record_request_authorization_current(p_request_id uuid,p_manifest_id uuid) returns boolean language plpgsql security definer set search_path=public as $$
declare r public.record_requests;a public.record_request_recipient_authorizations;d public.patient_documents;
begin
 select * into r from public.record_requests where id=p_request_id for share;
 if p_manifest_id is null or r.id is null or r.direction<>'outgoing' or r.active_manifest_id is distinct from p_manifest_id or r.status in ('blocked','cancelled') then return false;end if;
 if r.recipient_kind='client' then return true;end if;
 perform 1 from public.record_request_disclosure_policy where id and enabled and accepted_at<=clock_timestamp() for share;
 if not found then return false;end if;
 select * into a from public.record_request_recipient_authorizations where request_id=r.id and manifest_id=p_manifest_id;
 if a.id is null or a.recipient is distinct from r.recipient or a.recipient_name is distinct from r.recipient_name or a.expires_at<=clock_timestamp()
 or a.manifest_hash is distinct from (select fingerprint from public.record_request_manifests where id=p_manifest_id)
 or exists(select 1 from public.record_request_authorization_revocations where authorization_id=a.id) then return false;end if;
 if a.evidence_document_id is not null then
  select * into d from public.patient_documents where id=a.evidence_document_id and pet_id=r.pet_id and status='ready' and version=a.evidence_document_version for share;
  if d.id is null or not exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type) then return false;end if;
 end if;
 return true;
end $$

-- A private transaction-local pointer selects draft preview context. It does NOT
-- authorize disclosure: confirmation and transport independently require stored
-- package association, current client authority, destination and manifest hash.
create function public.record_request_preview_recipient(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text) returns jsonb language plpgsql security definer set search_path=public as $$
declare context text:=current_setting('lrv.record_request_preview_id',true);r public.record_requests;c public.clients;
begin
 if context is null or context !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then return null;end if;
 select * into r from public.record_requests where id=context::uuid and pet_id=p_pet_id and client_id=p_client_id and recipient_kind='third_party' and channel='EMAIL' and channel=p_channel and recipient=p_recipient and status not in ('blocked','cancelled');
 if r.id is null or (auth.uid() is not null and not public.is_active_staff(auth.uid())) then return null;end if;
 if auth.uid() is null and not public.record_request_authorization_current(r.id,r.active_manifest_id) then return null;end if;
 select * into c from public.clients where id=r.client_id;
 return jsonb_build_object('client_id',c.id,'client_version',c.version,'name',r.recipient_name,'channel','EMAIL','address',r.recipient,'recipient_kind','third_party','record_request_id',r.id,'authorizing_client_name',c.full_name);
end $$

-- Change one audited private clinical-core recipient comparison. General message,
-- invoice and public legacy preview APIs retain their household recipient boundary.
do $$declare d text;needle text;recipient_object text;begin
 d:=pg_get_functiondef('public.preview_record_release_v1(uuid,uuid,text,text,jsonb)'::regprocedure);
 needle:='recipient is distinct from public.communication_recipient(p_channel,case when p_channel=''EMAIL'' then owner.primary_email else owner.primary_phone end)';
 recipient_object:='jsonb_build_object(''client_id'',owner.id,''client_version'',owner.version,''name'',owner.full_name,''channel'',p_channel,''address'',recipient)';
 if position(needle in d)=0 or position(recipient_object in d)=0 then raise exception 'Reviewed private recipient boundary changed';end if;
 d:=replace(d,needle,'('||needle||' and public.record_request_preview_recipient(p_pet_id,p_client_id,p_channel,recipient) is null)');
 d:=replace(d,recipient_object,'coalesce(public.record_request_preview_recipient(p_pet_id,p_client_id,p_channel,recipient),'||recipient_object||')');
 execute d;
end $$

create function public.confirm_record_release(p_id uuid,p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb,p_reviewed_snapshot jsonb,p_reviewed_hash text,p_attest_review boolean) returns public.record_releases language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();p public.record_request_packages;result public.record_releases;previous_context text:=current_setting('lrv.record_request_preview_id',true);
begin
 -- Retain exact original receipt recovery even after cancellation/revocation.
 if exists(select 1 from public.record_releases where id=p_id) then return public.confirm_record_release_without_record_request(p_id,p_pet_id,p_client_id,p_channel,p_recipient,p_selection,p_reviewed_snapshot,p_reviewed_hash,p_attest_review);end if;
 select * into p from public.record_request_packages where release_id=p_id;
 if p.id is not null then
  raise exception 'Numbered releases must be confirmed through their records request' using errcode='42501';
 else
  if p_reviewed_snapshot#>>'{recipient,recipient_kind}'='third_party' then raise exception 'Third-party releases require an authorized numbered request package' using errcode='42501';end if;
  perform set_config('lrv.record_request_preview_id','',true);
 end if;
 result:=public.confirm_record_release_without_record_request(p_id,p_pet_id,p_client_id,p_channel,p_recipient,p_selection,p_reviewed_snapshot,p_reviewed_hash,p_attest_review);
 perform set_config('lrv.record_request_preview_id',coalesce(previous_context,''),true);
 return result;
end $$

create function public.release_read_internal(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.record_request_packages;m public.record_request_manifests;r public.record_requests;result jsonb;allowed boolean;previous_context text:=current_setting('lrv.record_request_preview_id',true);
begin
 select packages.* into p from public.record_request_release_links l join public.record_request_packages packages on packages.id=l.package_id where l.release_id=p_id;
 if p.id is not null then
  select * into m from public.record_request_manifests where id=p.manifest_id;
  select * into r from public.record_requests where id=m.request_id for share;
  allowed:=public.record_request_authorization_current(r.id,m.id);
  perform set_config('lrv.record_request_preview_id',r.id::text,true);
 else
  -- Unbound legacy artifacts cannot inherit another request's transaction context.
  perform set_config('lrv.record_request_preview_id','',true);
 end if;
 result:=public.release_read_internal_without_record_request(p_id);
 if p.id is not null then
  if not allowed or not public.record_request_authorization_current(r.id,m.id) then result:=result||jsonb_build_object('eligible',false,'ineligibility_reason','Records request or recipient authorization no longer permits disclosure');end if;
  result:=result||jsonb_build_object('package_context',public.record_request_package_context(p.id));
 end if;
 perform set_config('lrv.record_request_preview_id',coalesce(previous_context,''),true);
 return result;
end $$

create function public.record_request_bound_release(p_release_id uuid) returns boolean language plpgsql security definer set search_path=public as $$
declare p public.record_request_packages;m public.record_request_manifests;
begin
 select packages.* into p from public.record_request_release_links l join public.record_request_packages packages on packages.id=l.package_id where l.release_id=p_release_id;
 if p.id is null then return true;end if;
 select * into m from public.record_request_manifests where id=p.manifest_id;
 return public.record_request_authorization_current(m.request_id,m.id);
end $$

create function public.release_email_context(p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare release_id uuid;result jsonb;begin
 select e.release_id into release_id from public.release_email_requests e where e.id=p_request_id;
 if release_id is not null and not public.record_request_bound_release(release_id) then raise exception 'Records request no longer permits email delivery' using errcode='42501';end if;
 result:=public.release_email_context_without_record_request(p_request_id);
 if release_id is not null and not public.record_request_bound_release(release_id) then raise exception 'Records request authorization expired during delivery validation' using errcode='42501';end if;
 return result;
end $$

create function public.document_link_current(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare g public.document_link_grants;result jsonb;begin
 select * into g from public.document_link_grants where id=p_id;
 if g.family='record_release' and not public.record_request_bound_release(g.source_id) then raise exception 'Records request no longer permits document retrieval' using errcode='42501';end if;
 result:=public.document_link_current_without_record_request(p_id);
 if g.family='record_release' and not public.record_request_bound_release(g.source_id) then raise exception 'Records request authorization expired during retrieval validation' using errcode='42501';end if;
 return result;
end $$

create function public.record_request_outbox_recipient_allowed(p_outbox_id uuid) returns boolean language plpgsql security definer set search_path=public as $$
declare r public.record_requests;m public.record_request_manifests;begin
 select requests.* into r from public.communication_outbox o join public.release_email_outbox_links l on l.outbox_id=o.id
 join public.release_email_requests e on e.id=l.request_id and e.client_id=o.client_id and e.recipient=o.recipient and e.actor_id=o.created_by
 join public.record_request_release_links link on link.release_id=e.release_id join public.record_request_packages p on p.id=link.package_id and p.preview->>'source_hash'=e.release_hash
 join public.record_request_manifests manifests on manifests.id=p.manifest_id join public.record_requests requests on requests.id=manifests.request_id and requests.client_id=o.client_id and requests.recipient=o.recipient
 where o.id=p_outbox_id and o.channel='EMAIL' and requests.recipient_kind='third_party';
 if r.id is null then return false;end if;
 select manifests.* into m from public.record_request_manifests manifests where manifests.id=r.active_manifest_id;
 return public.record_request_authorization_current(r.id,m.id);
end $$

create function public.record_request_prepared_recipient_allowed(p_actor uuid,p_id uuid,p_conversation uuid,p_recipient text,p_subject text,p_body text) returns boolean language plpgsql security definer set search_path=public as $$
declare r public.record_requests;m public.record_request_manifests;begin
 select requests.* into r from public.release_email_requests e join public.record_request_release_links l on l.release_id=e.release_id
 join public.record_request_packages p on p.id=l.package_id and p.preview->>'source_hash'=e.release_hash
 join public.record_request_manifests manifests on manifests.id=p.manifest_id
 join public.record_requests requests on requests.id=manifests.request_id and requests.client_id=e.client_id and requests.recipient=e.recipient
 where e.id=p_id and e.actor_id=p_actor and e.conversation_id=p_conversation and e.recipient=p_recipient and e.subject=p_subject and e.body=p_body
 and e.state='ready' and requests.recipient_kind='third_party';
 if r.id is null then return false;end if;
 select * into m from public.record_request_manifests where id=r.active_manifest_id;
 return public.record_request_authorization_current(r.id,m.id);
end $$

create function public.record_request_outbox_current(p_id uuid) returns boolean language plpgsql security definer set search_path=public as $$
declare release_id uuid;begin
 select e.release_id into release_id from public.release_email_outbox_links l join public.release_email_requests e on e.id=l.request_id where l.outbox_id=p_id;
 if release_id is null then select g.source_id into release_id from public.document_link_outbox_links l join public.document_link_grants g on g.id=l.grant_id where l.outbox_id=p_id and g.family='record_release';end if;
 return release_id is null or public.record_request_bound_release(release_id);
end $$

-- Extend only the typed release-email path; ordinary inbox/invoice recipients stay unchanged.
do $$declare d text;needle text;begin
 d:=pg_get_functiondef('public.enqueue_prepared_communication_internal(uuid,uuid,uuid,text,text,text,text,uuid[])'::regprocedure);
 needle:='recipient is distinct from public.communication_recipient(p_channel,case when p_channel=''EMAIL'' then client.primary_email else client.primary_phone end)';
 if strpos(d,needle)=0 then raise exception 'Prepared recipient guard changed';end if;
 d:=replace(d,needle,'('||needle||' and not (p_channel=''EMAIL'' and public.record_request_prepared_recipient_allowed(actor,p_request_id,p_conversation_id,recipient,p_subject,p_body)))');execute d;
 d:=pg_get_functiondef('public.start_communication_attempt_without_reminder_guard(uuid,uuid,jsonb)'::regprocedure);
 needle:='or not exists(select 1 from public.clients c where c.id=result.client_id and public.communication_recipient(result.channel,case when result.channel=''EMAIL'' then c.primary_email else c.primary_phone end)=result.recipient)';
 if strpos(d,needle)=0 then raise exception 'Final attempt recipient guard changed';end if;
 d:=replace(d,needle,'or not public.record_request_outbox_current(result.id) or (not exists(select 1 from public.clients c where c.id=result.client_id and public.communication_recipient(result.channel,case when result.channel=''EMAIL'' then c.primary_email else c.primary_phone end)=result.recipient) and not public.record_request_outbox_recipient_allowed(result.id))');execute d;
end $$

create function public.list_record_requests(p_filter jsonb default '{}',p_before jsonb default null,p_limit integer default 50) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();
 if p_limit is null or p_limit not between 1 and 50 or jsonb_typeof(p_filter) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_filter) k where k<>all(array['pet_id','client_id','ticket_id','status','direction','assigned_to','overdue']))
 or (p_before is not null and (jsonb_typeof(p_before)<>'object' or p_before-array['updated_at','id']<>'{}')) then raise exception 'Bounded queue filters required' using errcode='23514';end if;
 with rows as materialized (
 select r.*,p.name pet_name,c.full_name client_name,coalesce(a.full_name,'') assignee_name
 from public.record_requests r join public.pets p on p.id=r.pet_id join public.clients c on c.id=r.client_id left join public.profiles a on a.id=r.assigned_to
 where (not p_filter?'pet_id' or r.pet_id=public.native_rx_uuid(p_filter->'pet_id')) and (not p_filter?'client_id' or r.client_id=public.native_rx_uuid(p_filter->'client_id'))
 and (not p_filter?'ticket_id' or r.ticket_id=public.native_rx_uuid(p_filter->'ticket_id')) and (not p_filter?'status' or r.status=p_filter->>'status')
 and (not p_filter?'direction' or r.direction=p_filter->>'direction') and (not p_filter?'assigned_to' or r.assigned_to=public.native_rx_uuid(p_filter->'assigned_to'))
 and (coalesce((p_filter->>'overdue')::boolean,false)=false or (r.due_on<(clock_timestamp() at time zone 'America/Denver')::date and r.status not in ('fulfilled','cancelled')))
 and (p_before is null or row(r.updated_at,r.id)<row((p_before->>'updated_at')::timestamptz,public.native_rx_uuid(p_before->'id')))
 order by r.updated_at desc,r.id desc limit p_limit+1
 ), page as (select * from rows order by updated_at desc,id desc limit p_limit)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by updated_at desc,id desc) from page),'[]'),
 'next',case when (select count(*) from rows)>p_limit then (select jsonb_build_object('id',id,'updated_at',updated_at) from page order by updated_at,id limit 1) else null end) into result;
 return result;
end $$

create function public.read_record_request(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.record_requests;m public.record_request_manifests;result jsonb;begin
 perform public.clinical_require_staff();select * into r from public.record_requests where id=p_id;if r.id is null then return null;end if;
 select * into m from public.record_request_manifests where id=r.active_manifest_id;
 result:=jsonb_build_object('request',to_jsonb(r),'pet_name',(select name from public.pets where id=r.pet_id),'client_name',(select full_name from public.clients where id=r.client_id),
 'manifest',case when m.id is null then null else to_jsonb(m)-'inventory'-'exclusions' end,
 'receipt_count',(select count(*) from public.record_request_receipts where request_id=r.id),
 'disclosure_policy_accepted',exists(select 1 from public.record_request_disclosure_policy where id and enabled and accepted_at<=clock_timestamp()),
 'authorization',(select to_jsonb(a)||jsonb_build_object('revoked',exists(select 1 from public.record_request_authorization_revocations where authorization_id=a.id),'current',public.record_request_authorization_current(r.id,m.id)) from public.record_request_recipient_authorizations a where a.manifest_id=m.id));
 return result;
end $$

create function public.list_record_request_packages(p_request_id uuid,p_manifest_id uuid,p_after integer default 0,p_limit integer default 20) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();if p_after is null or p_limit is null or p_after<0 or p_limit not between 1 and 20 then raise exception 'Bounded package page required' using errcode='23514';end if;
 if not exists(select 1 from public.record_request_manifests where id=p_manifest_id and request_id=p_request_id) then raise exception 'Manifest belongs to another request' using errcode='42501';end if;
 with rows as materialized (select p.id,p.ordinal,p.release_id,p.selection,p.scope_expansion,p.preview->>'source_hash' source_hash,l.package_id is not null confirmed,public.record_request_deliveries(p.id) deliveries from public.record_request_packages p left join public.record_request_release_links l on l.package_id=p.id where p.manifest_id=p_manifest_id and p.ordinal>p_after order by p.ordinal limit p_limit+1),page as (select * from rows order by ordinal limit p_limit)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by ordinal) from page),'[]'),'next',case when (select count(*) from rows)>p_limit then (select max(ordinal) from page) else null end) into result;return result;
end $$

create function public.read_record_request_package(p_request_id uuid,p_package_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.record_request_packages;m public.record_request_manifests;begin
 perform public.clinical_require_staff();select * into p from public.record_request_packages where id=p_package_id;select * into m from public.record_request_manifests where id=p.manifest_id and request_id=p_request_id;
 if m.id is null then raise exception 'Package belongs to another request' using errcode='42501';end if;
 return to_jsonb(p)||jsonb_build_object('package_context',public.record_request_package_context(p.id),'confirmed',exists(select 1 from public.record_request_release_links where package_id=p.id),'deliveries',public.record_request_deliveries(p.id));
end $$

create function public.list_record_request_evidence(p_id uuid,p_kind text,p_after integer default 0,p_limit integer default 50) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.record_requests;items jsonb;total integer;begin
 perform public.clinical_require_staff();select * into r from public.record_requests where id=p_id;
 if r.id is null then raise exception 'Request unavailable' using errcode='42501';end if;
 if p_after is null or p_limit is null or p_kind is null or p_after<0 or p_limit not between 1 and 50 or p_kind not in ('sources','exclusions','receipts','history') then raise exception 'Bounded evidence page required' using errcode='23514';end if;
 if p_kind='history' then
  select count(*) into total from public.record_request_revisions where request_id=r.id;
  select coalesce(jsonb_agg(to_jsonb(x) order by version desc),'[]') into items from (select v.version,v.snapshot,v.actor_id,v.created_at,(select jsonb_build_object('kind',a.kind,'review_note',coalesce(a.intent#>>'{values,review_note}',a.intent#>>'{values,client_authority}','Request details saved'),'ordinal',a.receipt->'ordinal') from public.record_request_actions a where a.request_id=v.request_id and a.receipt#>>'{request,version}'=v.version::text order by a.created_at desc,a.id desc limit 1) action from public.record_request_revisions v where v.request_id=r.id order by v.version desc offset p_after limit p_limit) x;
 elsif p_kind='receipts' then
  select count(*) into total from public.record_request_receipts where request_id=r.id;
  select coalesce(jsonb_agg(to_jsonb(x) order by created_at,id),'[]') into items from (select e.*,d.status='ready' and d.version=e.document_version and exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type) current_available from public.record_request_receipts e join public.patient_documents d on d.id=e.document_id where e.request_id=r.id order by e.created_at,e.id offset p_after limit p_limit) x;
 elsif p_kind='exclusions' then
  select jsonb_array_length(exclusions) into total from public.record_request_manifests where id=r.active_manifest_id;
  select coalesce(jsonb_agg(value order by ordinal),'[]') into items from public.record_request_manifests m cross join lateral jsonb_array_elements(m.exclusions) with ordinality x(value,ordinal) where m.id=r.active_manifest_id and ordinal>p_after and ordinal<=p_after+p_limit;
 else
  with pool as (select public.record_request_inventory(r.pet_id)->'nodes' nodes), nodes as (select key,value from pool cross join lateral jsonb_each(nodes)) select count(*) into total from nodes;
  select coalesce(jsonb_agg(x.value order by x.key),'[]') into items from (select key,value-'requires'-'file_size'-'mime_type' value from jsonb_each(public.record_request_inventory(r.pet_id)->'nodes') order by key offset p_after limit p_limit) x;
 end if;
 return jsonb_build_object('items',items,'next',case when p_after+p_limit<coalesce(total,0) then p_after+p_limit else null end);
end $$

create function public.record_request_choices(p_search text default '',p_pet_id uuid default null,p_client_id uuid default null,p_after uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
begin
 perform public.clinical_require_staff();if p_search is null or length(p_search)>160 then raise exception 'Bounded patient search required' using errcode='23514';end if;
 return jsonb_build_object('patients',coalesce((select jsonb_agg(to_jsonb(x) order by id) from (select p.id,p.name,p.client_id,c.full_name client_name from public.pets p join public.clients c on c.id=p.client_id where (p_pet_id is null or p.id=p_pet_id) and (p_client_id is null or p.client_id=p_client_id) and (p_after is null or p.id>p_after) and (p_search='' or strpos(lower(p.name||' '||c.full_name),lower(p_search))>0) order by p.id limit 51) x),'[]'),
 'staff',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',full_name) order by full_name,id) from public.profiles where public.is_active_staff(id)),'[]'));
end $$

create function public.list_record_request_documents(p_request_id uuid,p_after uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare r public.record_requests;begin
 perform public.clinical_require_staff();select * into r from public.record_requests where id=p_request_id;if r.id is null then raise exception 'Request unavailable' using errcode='42501';end if;
 return coalesce((select jsonb_agg(to_jsonb(x) order by id) from (select d.id,d.version,d.file_name,d.category,d.created_at from public.patient_documents d where d.pet_id=r.pet_id and d.status='ready' and (p_after is null or d.id>p_after) and exists(select 1 from storage.objects o where o.bucket_id='patient-documents' and o.name=d.file_path and o.metadata->>'size'=d.file_size::text and o.metadata->>'mimetype'=d.mime_type) order by d.id limit 51) x),'[]');
end $$

-- Every new security-definer helper and renamed core is private. Only explicit staff RPCs are exposed.
do $$declare f record;begin
 for f in select oid::regprocedure signature,proname from pg_proc where pronamespace='public'::regnamespace and (proname like 'record_request_%' or proname in ('save_record_request','read_record_request','read_record_request_action','prepare_record_request_manifest','receive_record_request','transition_record_request','confirm_record_request_package','authorize_record_request_recipient','revoke_record_request_authorization','list_record_requests','list_record_request_packages','read_record_request_package','list_record_request_evidence','list_record_request_documents','confirm_record_release_without_record_request','release_read_internal_without_record_request','release_email_context_without_record_request','document_link_current_without_record_request','release_read_internal','release_email_context','document_link_current')) loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in ('save_record_request','read_record_request','read_record_request_action','prepare_record_request_manifest','receive_record_request','transition_record_request','confirm_record_request_package','authorize_record_request_recipient','revoke_record_request_authorization','list_record_requests','list_record_request_packages','read_record_request_package','list_record_request_evidence','list_record_request_documents','record_request_choices') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$

create function public.record_request_policy_audit() returns trigger language plpgsql security definer set search_path=public as $$
begin
 insert into public.audit_logs(user_id,action,table_name,record_id,new_data) values(auth.uid(),TG_OP,'record_request_disclosure_policy','00000000-0000-4000-8000-000000000001',case when TG_OP='DELETE' then to_jsonb(OLD) else to_jsonb(NEW) end);
 return coalesce(NEW,OLD);
end $$

create function public.diagnostic_root_guard() returns trigger language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();begin
 if TG_OP='DELETE' then raise exception 'Diagnostic history cannot be deleted' using errcode='23514';end if;
 if TG_OP='UPDATE' then
  if row(NEW.id,NEW.pet_id,NEW.created_by,NEW.created_at) is distinct from row(OLD.id,OLD.pet_id,OLD.created_by,OLD.created_at) then raise exception 'Diagnostic patient identity is immutable' using errcode='23514';end if;
  NEW.version:=OLD.version+1;
 else NEW.version:=1;NEW.created_by:=actor;NEW.created_at:=clock_timestamp();end if;
 if NEW.draft is not null then select coalesce(full_name,'') into NEW.draft_entered_name from public.profiles where id=actor;else NEW.draft_entered_name:=OLD.draft_entered_name;end if;
 NEW.updated_by:=actor;NEW.updated_at:=clock_timestamp();return NEW;
end $$

do $$declare t text;begin foreach t in array array['diagnostic_panel_versions','diagnostic_panel_actions','diagnostic_panel_revisions'] loop
 execute format('create trigger diagnostic_immutable before update or delete on public.%I for each row execute function public.diagnostic_immutable()',t);
end loop;
foreach t in array array['diagnostic_panels','diagnostic_panel_versions','diagnostic_panel_actions','diagnostic_panel_revisions'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
end loop;end $$

create function public.diagnostic_validate(p_values jsonb) returns jsonb language plpgsql immutable set search_path=public as $$
declare o jsonb;lo numeric;hi numeric;a date;b date;k text;keys text[]:=array['panel_name','category','collected_on','reported_on','specimen','method','source','interpretation','observations','lab_order_id','lab_order_version','encounter_id','encounter_version','document_id','document_version'];
begin
 if jsonb_typeof(p_values) is distinct from 'object' or p_values-keys<>'{}' or not p_values?&keys or octet_length(p_values::text)>131072 then raise exception 'Bounded complete diagnostic fields required' using errcode='23514';end if;
 foreach k in array array['panel_name','specimen','method','source'] loop
  if jsonb_typeof(p_values->k) is distinct from 'string' or length(trim(p_values->>k)) not between 1 and 160 or trim(p_values->>k)<>p_values->>k then raise exception 'Diagnostic labels must be nonempty exact text' using errcode='23514';end if;
 end loop;
 if jsonb_typeof(p_values->'category') is distinct from 'string' or p_values->>'category' not in ('laboratory','other') or jsonb_typeof(p_values->'interpretation') is distinct from 'string' or length(p_values->>'interpretation')>4000 then raise exception 'Diagnostic category or interpretation invalid' using errcode='23514';end if;
 if jsonb_typeof(p_values->'collected_on') is distinct from 'string' or jsonb_typeof(p_values->'reported_on') is distinct from 'string' or p_values->>'collected_on'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or p_values->>'reported_on'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Diagnostic calendar dates required' using errcode='23514';end if;
 begin a:=(p_values->>'collected_on')::date;b:=(p_values->>'reported_on')::date;exception when others then raise exception 'Invalid diagnostic calendar date' using errcode='23514';end;
 if not isfinite(a) or not isfinite(b) or b<a or to_char(a,'YYYY-MM-DD')<>p_values->>'collected_on' or to_char(b,'YYYY-MM-DD')<>p_values->>'reported_on' then raise exception 'Report date must follow collection date' using errcode='23514';end if;
 foreach k in array array['lab_order','encounter','document'] loop
  if (p_values->(k||'_id')='null')<>(p_values->(k||'_version')='null') then raise exception 'Source identity and reviewed version required together' using errcode='23514';end if;
  if p_values->(k||'_id')<>'null' then
   perform public.native_rx_uuid(p_values->(k||'_id'));
   if jsonb_typeof(p_values->(k||'_version')) is distinct from 'number' or (p_values->>(k||'_version'))!~'^[1-9][0-9]{0,8}$' then raise exception 'Positive source version required' using errcode='23514';end if;
  end if;
 end loop;
 if jsonb_typeof(p_values->'observations') is distinct from 'array' or jsonb_array_length(p_values->'observations') not between 1 and 100 then raise exception 'One to 100 diagnostic findings required' using errcode='23514';end if;
 for o in select value from jsonb_array_elements(p_values->'observations') loop
  keys:=array['id','analyte_key','label','kind','value_number','value_text','unit','reference_low','reference_high','reference_text','source_flag'];
  if jsonb_typeof(o) is distinct from 'object' or o-keys<>'{}' or not o?&keys then raise exception 'Exact diagnostic finding fields required' using errcode='23514';end if;
  perform public.native_rx_uuid(o->'id');
  foreach k in array array['analyte_key','label'] loop
   if jsonb_typeof(o->k) is distinct from 'string' or length(trim(o->>k)) not between 1 and 160 or trim(o->>k)<>o->>k then raise exception 'Exact finding identity and original label required' using errcode='23514';end if;
  end loop;
  if o->>'kind'='numeric' then
   if jsonb_typeof(o->'value_number') is distinct from 'number' or o->'value_text'<>'null' or jsonb_typeof(o->'unit') is distinct from 'string' or length(trim(o->>'unit')) not between 1 and 40 or trim(o->>'unit')<>o->>'unit' then raise exception 'Numeric finding requires finite number and explicit original unit' using errcode='23514';end if;
   if abs((o->>'value_number')::numeric)>1e100 or ((o->>'value_number')::numeric<>0 and abs((o->>'value_number')::numeric)<1e-100) then raise exception 'Diagnostic value exceeds numeric capacity' using errcode='23514';end if;
  elsif o->>'kind'='qualitative' then
   if o->'value_number'<>'null' or jsonb_typeof(o->'value_text') is distinct from 'string' or length(trim(o->>'value_text')) not between 1 and 1000 or o->'unit'<>'null' or o->'reference_low'<>'null' or o->'reference_high'<>'null' then raise exception 'Qualitative finding requires text without numeric fields' using errcode='23514';end if;
  else raise exception 'Explicit numeric or qualitative finding kind required' using errcode='23514';end if;
  lo:=null;hi:=null;
  foreach k in array array['reference_low','reference_high'] loop
   if o->k<>'null' then
    if jsonb_typeof(o->k) is distinct from 'number' or abs((o->>k)::numeric)>1e100 or ((o->>k)::numeric<>0 and abs((o->>k)::numeric)<1e-100) then raise exception 'Finite manually entered reference bound required' using errcode='23514';end if;
    if k='reference_low' then lo:=(o->>k)::numeric;else hi:=(o->>k)::numeric;end if;
   end if;
  end loop;
  if lo>hi then raise exception 'Reference bounds are reversed' using errcode='23514';end if;
  foreach k in array array['reference_text','source_flag'] loop
   if jsonb_typeof(o->k) is distinct from 'string' or length(o->>k)>1000 then raise exception 'Bounded documentary reference and source flag required' using errcode='23514';end if;
  end loop;
 end loop;
 if exists(select 1 from jsonb_array_elements(p_values->'observations') finding group by finding->>'id' having count(*)>1) or exists(select 1 from jsonb_array_elements(p_values->'observations') finding group by finding->>'analyte_key' having count(*)>1) then raise exception 'Finding IDs and analyte identities must be unique within a panel' using errcode='23514';end if;
 return p_values;
end $$

create function public.diagnostic_sources(p_pet_id uuid,p_values jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare context jsonb:='{}';o public.patient_lab_orders;e public.clinical_encounters;d public.patient_documents;
begin
 if p_values->'lab_order_id'<>'null' then
  select * into o from public.patient_lab_orders where id=(p_values->>'lab_order_id')::uuid for share;
  if not found or o.pet_id<>p_pet_id then raise exception 'Diagnostic order belongs to another patient or is unavailable' using errcode='42501';end if;
  if o.version<>(p_values->>'lab_order_version')::integer or o.status='cancelled' then raise exception 'Diagnostic order changed; review its current version' using errcode='PT409';end if;
  context:=context||jsonb_build_object('lab_order',jsonb_build_object('id',o.id,'version',o.version,'test_name',o.test_name));
 end if;
 if p_values->'encounter_id'<>'null' then
  select * into e from public.clinical_encounters where id=(p_values->>'encounter_id')::uuid for share;
  if not found or e.pet_id<>p_pet_id then raise exception 'Diagnostic encounter belongs to another patient or is unavailable' using errcode='42501';end if;
  if e.version<>(p_values->>'encounter_version')::integer then raise exception 'Diagnostic encounter changed; review its current version' using errcode='PT409';end if;
  context:=context||jsonb_build_object('encounter',jsonb_build_object('id',e.id,'version',e.version,'visit_at',e.visit_at));
 end if;
 if p_values->'document_id'<>'null' then
  select * into d from public.patient_documents where id=(p_values->>'document_id')::uuid for share;
  if not found or d.pet_id<>p_pet_id then raise exception 'Diagnostic original belongs to another patient or is unavailable' using errcode='42501';end if;
  if d.version<>(p_values->>'document_version')::integer or d.status<>'ready' or not exists(select 1 from storage.objects x where x.bucket_id='patient-documents' and x.name=d.file_path and x.metadata->>'size'=d.file_size::text and x.metadata->>'mimetype'=d.mime_type) then raise exception 'Diagnostic original changed or is not finalized' using errcode='PT409';end if;
  context:=context||jsonb_build_object('document',jsonb_build_object('id',d.id,'version',d.version,'file_name',d.file_name,'file_size',d.file_size,'mime_type',d.mime_type));
 end if;
 return context;
end $$

create function public.read_diagnostic_action(p_action_id uuid,p_id uuid,p_pet_id uuid,p_expected_version integer,p_kind text,p_values jsonb,p_review_note text,p_correction_reason text) returns jsonb language plpgsql security definer set search_path=public as $$
declare a public.diagnostic_panel_actions;actor uuid:=public.clinical_require_staff();intent jsonb:=jsonb_build_object('kind',p_kind,'version',p_expected_version,'values',p_values,'review_note',p_review_note,'correction_reason',p_correction_reason);
begin select * into a from public.diagnostic_panel_actions where id=p_action_id;if not found then return null;end if;
 if a.actor_id<>actor or a.panel_id<>p_id or a.pet_id<>p_pet_id or a.intent is distinct from intent then raise exception 'Diagnostic action conflicts with saved work' using errcode='23505';end if;return a.receipt;
end $$

create function public.save_diagnostic_panel(p_action_id uuid,p_id uuid,p_pet_id uuid,p_expected_version integer,p_kind text,p_values jsonb,p_review_note text default '',p_correction_reason text default '') returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();r public.diagnostic_panels;v public.diagnostic_panel_versions;old_version public.diagnostic_panel_versions;recovered jsonb;result jsonb;context jsonb;intent jsonb;pat public.pets;reviewer text;reviewed_time timestamptz;
begin
 if p_action_id is null or p_id is null or p_pet_id is null or p_kind is null or p_kind not in ('draft','finalize') or p_review_note is null or p_correction_reason is null then raise exception 'Stable diagnostic action identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_action_id::text,417));
 recovered:=public.read_diagnostic_action(p_action_id,p_id,p_pet_id,p_expected_version,p_kind,p_values,p_review_note,p_correction_reason);if recovered is not null then return recovered;end if;
 perform public.diagnostic_validate(p_values);
 -- Diagnostic root before read-only order/encounter/original locks; no request locks are acquired.
 select * into pat from public.pets where id=p_pet_id for share;if not found then raise exception 'Diagnostic patient unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,418));select * into r from public.diagnostic_panels where id=p_id for update;
 if found then
  if r.pet_id<>p_pet_id then raise exception 'Diagnostic panel belongs to another patient' using errcode='42501';end if;
  if p_expected_version is distinct from r.version then raise exception 'Diagnostic panel changed; reload before resolving your draft' using errcode='PT409';end if;
 else
  if p_expected_version is not null or p_kind<>'draft' then raise exception 'Save a diagnostic draft before finalization' using errcode='PT409';end if;
 end if;
 context:=public.diagnostic_sources(p_pet_id,p_values);perform public.clinical_require_staff();
 if p_kind='draft' then
  if p_review_note<>'' or p_correction_reason<>'' then raise exception 'Draft save cannot claim clinical review' using errcode='23514';end if;
  if r.id is null then insert into public.diagnostic_panels(id,pet_id,draft,created_by,updated_by) values(p_id,p_pet_id,p_values,actor,actor) returning * into r;
  else update public.diagnostic_panels set draft=p_values where id=p_id returning * into r;end if;
 else
  perform public.care_require_clinician();
  if r.draft is null or r.draft is distinct from p_values then raise exception 'Finalize only the exact saved diagnostic draft' using errcode='PT409';end if;
  if length(trim(p_review_note)) not between 1 and 2000 or trim(p_review_note)<>p_review_note or length(p_correction_reason)>2000 or trim(p_correction_reason)<>p_correction_reason or (r.current_finalized_id is null and p_correction_reason<>'') or (r.current_finalized_id is not null and length(p_correction_reason)=0) then raise exception 'Explicit exact review and correction reason required' using errcode='23514';end if;
  if (p_values->>'reported_on')::date>(clock_timestamp() at time zone 'America/Denver')::date then raise exception 'Future diagnostic result cannot be finalized' using errcode='23514';end if;
  if r.current_finalized_id is not null then select * into strict old_version from public.diagnostic_panel_versions where id=r.current_finalized_id; if old_version.snapshot=p_values then raise exception 'Correction must change reviewed findings' using errcode='23514';end if;end if;
  select full_name into reviewer from public.profiles where id=actor;reviewed_time:=clock_timestamp();
  insert into public.diagnostic_panel_versions(id,panel_id,pet_id,number,predecessor_id,snapshot,source_context,source_hash,correction_reason,review_note,entered_by,entered_by_name,reviewed_by,reviewer_name,reviewed_at)
  values(p_action_id,p_id,p_pet_id,r.current_finalized_number+1,r.current_finalized_id,p_values,context,encode(extensions.digest(convert_to(jsonb_build_object('version_id',p_action_id,'panel_id',p_id,'pet_id',p_pet_id,'number',r.current_finalized_number+1,'values',p_values,'sources',context,'predecessor',r.current_finalized_id,'entered_by',r.updated_by,'entered_by_name',r.draft_entered_name,'reviewed_by',actor,'reviewer_name',reviewer,'reviewed_at',reviewed_time,'review_note',p_review_note,'correction_reason',p_correction_reason)::text,'UTF8'),'sha256'),'hex'),p_correction_reason,p_review_note,r.updated_by,r.draft_entered_name,actor,reviewer,reviewed_time) returning * into v;
  update public.diagnostic_panels set draft=null,current_finalized_id=v.id,current_finalized_number=v.number where id=p_id returning * into r;
 end if;
 result:=public.diagnostic_detail(p_id,p_pet_id);intent:=jsonb_build_object('kind',p_kind,'version',p_expected_version,'values',p_values,'review_note',p_review_note,'correction_reason',p_correction_reason);
 insert into public.diagnostic_panel_actions(id,panel_id,pet_id,actor_id,intent,receipt) values(p_action_id,p_id,p_pet_id,actor,intent,result);return result;
end $$

create function public.list_diagnostic_panels(p_pet_id uuid,p_before jsonb default null,p_limit integer default 20) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;begin perform public.clinical_require_staff();
 if p_pet_id is null or p_limit is null or p_limit not between 1 and 50 or (p_before is not null and (jsonb_typeof(p_before)<>'object' or p_before-array['id','updated_at']<>'{}' or not p_before?&array['id','updated_at'])) then raise exception 'Bounded diagnostic cursor required' using errcode='23514';end if;
 with rows as materialized (select * from public.diagnostic_panels where pet_id=p_pet_id and (p_before is null or row(updated_at,id)<row((p_before->>'updated_at')::timestamptz,public.native_rx_uuid(p_before->'id'))) order by updated_at desc,id desc limit p_limit+1),page as(select * from rows order by updated_at desc,id desc limit p_limit)
 select jsonb_build_object('items',coalesce((select jsonb_agg(public.diagnostic_detail(id,pet_id) order by updated_at desc,id desc) from page),'[]'),'next',case when (select count(*) from rows)>p_limit then (select jsonb_build_object('updated_at',updated_at,'id',id) from page order by updated_at,id limit 1) else null end) into result;return result;
end $$

create function public.list_diagnostic_history(p_id uuid,p_pet_id uuid,p_before integer default null,p_limit integer default 20) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;begin perform public.clinical_require_staff();
 if p_limit is null or p_limit not between 1 and 50 or p_before<1 then raise exception 'Bounded diagnostic history required' using errcode='23514';end if;
 if not exists(select 1 from public.diagnostic_panels where id=p_id and pet_id=p_pet_id) then return jsonb_build_object('items','[]'::jsonb,'next',null);end if;
 with rows as materialized(select v.* from public.diagnostic_panel_versions v where v.panel_id=p_id and v.pet_id=p_pet_id and (p_before is null or v.number<p_before) order by v.number desc limit p_limit+1),page as(select * from rows order by number desc limit p_limit)
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(page) order by number desc) from page),'[]'),'next',case when (select count(*) from rows)>p_limit then (select min(number) from page) else null end) into result;return result;
end $$

-- A paginated census of current finalized versions, not drafts or superseded values.
create function public.list_diagnostic_trends(p_pet_id uuid,p_after uuid default null,p_limit integer default 50,p_census_hash text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb;begin
 perform public.clinical_require_staff();if p_pet_id is null or p_limit is null or p_limit not between 1 and 100 then raise exception 'Bounded diagnostic trend page required' using errcode='23514';end if;
 -- Fingerprint and rows share this single SQL statement snapshot, including concurrent corrections.
 with census as materialized(select id,current_finalized_id from public.diagnostic_panels where pet_id=p_pet_id and current_finalized_id is not null order by id limit 10001),
 meta as(select count(*) total,encode(sha256(convert_to(coalesce(string_agg(id::text||':'||current_finalized_id::text,'|' order by id),''),'UTF8')),'hex') hash from census),
 rows as materialized(select v.* from census p join public.diagnostic_panel_versions v on v.id=p.current_finalized_id where p_after is null or p.id>p_after order by p.id limit p_limit+1),
 page as(select * from rows order by panel_id limit p_limit)
 select jsonb_build_object('total',(select total from meta),'census_hash',(select hash from meta),'items',coalesce((select jsonb_agg(to_jsonb(page) order by panel_id) from page),'[]'),'next',case when (select count(*) from rows)>p_limit then (select max(panel_id::text)::uuid from page) else null end) into result;
 if (result->>'total')::integer>10000 then raise exception 'Diagnostic trend census exceeds capacity; no partial history returned' using errcode='23514';end if;
 if (p_after is not null and p_census_hash is null) or (p_census_hash is not null and p_census_hash is distinct from result->>'census_hash') then raise exception 'Diagnostic trend census changed; reload the complete series' using errcode='PT409';end if;
 perform public.clinical_require_staff();return result-'total';
end $$

create function public.record_request_inventory(p_pet_id uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$
declare result jsonb;excluded jsonb;n integer;begin perform public.clinical_require_staff();result:=public.record_request_inventory_before_diagnostics(p_pet_id);
 select count(*) into n from public.diagnostic_panels where pet_id=p_pet_id;if n>10000 then raise exception 'Diagnostic census exceeds complete-capture capacity; no partial manifest was created' using errcode='23514';end if;
 select coalesce(jsonb_agg(jsonb_build_object('family','diagnostic_panel_ids','id',p.id,'label',coalesce(p.draft->>'panel_name',v.snapshot->>'panel_name'),'reason',case when p.current_finalized_id is null then 'Unfinalized diagnostic draft' else 'Structured diagnostics await verified PDF and reviewed release support' end) order by p.id),'[]') into excluded from public.diagnostic_panels p left join public.diagnostic_panel_versions v on v.id=p.current_finalized_id where p.pet_id=p_pet_id;
 return jsonb_set(result,'{exclusions}',result->'exclusions'||excluded);
end $$

-- Explicit ACLs; private helpers are never staff endpoints.
do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'diagnostic_%' or p.proname in ('read_diagnostic_panel','read_diagnostic_action','save_diagnostic_panel','list_diagnostic_panels','list_diagnostic_history','list_diagnostic_trends','record_request_inventory_before_diagnostics','record_request_inventory')) loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname in ('read_diagnostic_panel','read_diagnostic_action','save_diagnostic_panel','list_diagnostic_panels','list_diagnostic_history','list_diagnostic_trends') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$

create function public.diagnostic_pdf_guard() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP='DELETE' or TG_OP='TRUNCATE' then raise exception 'PDF job evidence cannot be removed' using errcode='23514';end if;
 if TG_OP='UPDATE' then
  if row(NEW.id,NEW.panel_id,NEW.pet_id,NEW.source_hash,NEW.snapshot,NEW.snapshot_hash,NEW.created_by,NEW.created_at) is distinct from row(OLD.id,OLD.panel_id,OLD.pet_id,OLD.source_hash,OLD.snapshot,OLD.snapshot_hash,OLD.created_by,OLD.created_at) then raise exception 'PDF source evidence is immutable' using errcode='23514';end if;
  if OLD.renderer_sha is not null and row(NEW.renderer_sha,NEW.settings_sha) is distinct from row(OLD.renderer_sha,OLD.settings_sha) then raise exception 'PDF renderer binding is immutable' using errcode='23514';end if;
  if OLD.status='captured_unverified' and NEW.status<>OLD.status then raise exception 'Captured PDF bytes cannot be regenerated' using errcode='23514';end if;
  if NEW.fence<OLD.fence then raise exception 'PDF fence cannot regress' using errcode='23514';end if;
  NEW.version:=OLD.version+1;
 else NEW.version:=1;end if;
 NEW.updated_at:=clock_timestamp();return NEW;
end $$

do $$declare t text;begin
 foreach t in array array['diagnostic_pdf_attempts','diagnostic_pdf_captures','diagnostic_pdf_actions','diagnostic_pdf_revisions'] loop
 execute format('create trigger diagnostic_pdf_immutable before update or delete on public.%I for each row execute function public.diagnostic_immutable()',t);
 execute format('create trigger diagnostic_pdf_no_truncate before truncate on public.%I for each statement execute function public.diagnostic_immutable()',t);
 end loop;
 foreach t in array array['diagnostic_pdf_worker_policy','diagnostic_pdf_jobs','diagnostic_pdf_attempts','diagnostic_pdf_captures','diagnostic_pdf_actions','diagnostic_pdf_revisions'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 end loop;
end $$

create function public.diagnostic_pdf_queue(p_id uuid,p_actor uuid) returns void language plpgsql security definer set search_path=public as $$
declare v public.diagnostic_panel_versions;p public.pets;s jsonb;
begin
 select * into strict v from public.diagnostic_panel_versions where id=p_id;
 select * into strict p from public.pets where id=v.pet_id for share;
 s:=jsonb_build_object('schema',1,'purpose','diagnostic_result','diagnostic',to_jsonb(v),'patient',jsonb_build_object('id',p.id,'name',p.name,'species',p.species,'breed',p.breed,'dob',p.dob,'birth_date_precision',p.birth_date_precision,'microchip_id',p.microchip_id));
 insert into public.diagnostic_pdf_jobs(id,panel_id,pet_id,source_hash,snapshot,snapshot_hash,requested_by,created_by,updated_by)
 values(v.id,v.panel_id,v.pet_id,v.source_hash,s,encode(sha256(convert_to(s::text,'UTF8')),'hex'),p_actor,p_actor,p_actor) on conflict(id) do nothing;
end $$

create function public.request_diagnostic_pdf_job(p_action_id uuid,p_id uuid,p_pet_id uuid,p_source_hash text) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();v public.diagnostic_panel_versions;a public.diagnostic_pdf_actions;intent jsonb:=jsonb_build_object('kind','request','source_hash',p_source_hash);result jsonb;
begin
 if p_action_id is null or p_id is null or p_pet_id is null then raise exception 'Stable PDF request identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_action_id::text,491));
 select * into a from public.diagnostic_pdf_actions where id=p_action_id;
 if found then if a.actor_id<>actor or a.job_id<>p_id or a.intent is distinct from intent or a.receipt#>>'{job,pet_id}'<>p_pet_id::text then raise exception 'PDF action conflicts with saved work' using errcode='23505';end if;return a.receipt;end if;
 select * into v from public.diagnostic_panel_versions where id=p_id and pet_id=p_pet_id;
 if not found then raise exception 'Reviewed PDF source unavailable' using errcode='42501';end if;
 if p_source_hash is distinct from v.source_hash then raise exception 'Exact reviewed PDF source hash required' using errcode='PT409';end if;
 perform public.diagnostic_pdf_queue(p_id,actor);perform public.clinical_require_staff();result:=public.diagnostic_pdf_detail(p_id,p_pet_id);
 insert into public.diagnostic_pdf_actions(id,job_id,actor_id,intent,receipt) values(p_action_id,p_id,actor,intent,result);return result;
end $$

create function public.retry_diagnostic_pdf_job(p_action_id uuid,p_id uuid,p_pet_id uuid,p_expected_version integer,p_reason text) returns jsonb language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();j public.diagnostic_pdf_jobs;a public.diagnostic_pdf_actions;intent jsonb:=jsonb_build_object('kind','retry','version',p_expected_version,'reason',p_reason);result jsonb;
begin
 if p_action_id is null or p_id is null or p_pet_id is null or p_reason is null or length(trim(p_reason)) not between 1 and 2000 or p_reason<>trim(p_reason) then raise exception 'Explicit bounded PDF recovery reason required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_action_id::text,491));select * into a from public.diagnostic_pdf_actions where id=p_action_id;
 if found then if a.actor_id<>actor or a.job_id<>p_id or a.intent is distinct from intent or a.receipt#>>'{job,pet_id}'<>p_pet_id::text then raise exception 'PDF action conflicts with saved work' using errcode='23505';end if;return a.receipt;end if;
 select * into j from public.diagnostic_pdf_jobs where id=p_id and pet_id=p_pet_id for update;
 if not found then raise exception 'PDF job unavailable' using errcode='42501';end if;
 if j.version is distinct from p_expected_version or (j.status='claimed' and j.lease_until>clock_timestamp()) or (j.status='captured_unverified' and public.is_active_staff(j.requested_by)) then raise exception 'PDF job changed or is not retryable' using errcode='PT409';end if;
 perform public.clinical_require_staff();update public.diagnostic_pdf_jobs set status=case when status='captured_unverified' then status else 'pending' end,requested_by=actor,updated_by=actor,claim_id=null,lease_until=null,last_error='' where id=p_id;
 result:=public.diagnostic_pdf_detail(p_id,p_pet_id);insert into public.diagnostic_pdf_actions(id,job_id,actor_id,intent,receipt) values(p_action_id,p_id,actor,intent,result);return result;
end $$

create function public.claim_diagnostic_pdf_job(p_id uuid,p_claim_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;a public.diagnostic_pdf_attempts;p public.diagnostic_pdf_worker_policy;receipt jsonb;deadline timestamptz;
begin
 perform public.communication_require_service();if p_id is null or p_claim_id is null then raise exception 'Stable PDF claim identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_claim_id::text,492));
 select * into a from public.diagnostic_pdf_attempts where id=p_claim_id;
 select * into j from public.diagnostic_pdf_jobs where id=p_id for update;
 if j.id is null then return null;end if;
 if a.id is not null then
  if a.job_id<>p_id then raise exception 'PDF claim belongs to another job' using errcode='23505';end if;
  if j.claim_id is distinct from a.id or j.fence<>a.fence or j.lease_until<=clock_timestamp() then raise exception 'PDF claim expired or was superseded' using errcode='PT409';end if;
  if not public.is_active_staff(j.requested_by) then raise exception 'Active PDF request owner required' using errcode='42501';end if;
  return a.receipt;
 end if;
 select * into p from public.diagnostic_pdf_worker_policy where singleton and enabled for share;
 if not found then return null;end if;
 if not public.is_active_staff(j.requested_by) then raise exception 'Active PDF request owner required' using errcode='42501';end if;
 if j.status not in ('pending','claimed') or (j.status='claimed' and j.lease_until>clock_timestamp()) then return null;end if;
 if j.renderer_sha is not null and row(j.renderer_sha,j.settings_sha) is distinct from row(p.renderer_sha,p.settings_sha) then raise exception 'Bound PDF renderer policy changed' using errcode='PT409';end if;
 deadline:=clock_timestamp()+interval '90 seconds';
 update public.diagnostic_pdf_jobs set status='claimed',claim_id=p_claim_id,lease_until=deadline,fence=fence+1,renderer_sha=p.renderer_sha,settings_sha=p.settings_sha,updated_by=requested_by,last_error='' where id=p_id returning * into j;
 if not public.is_active_staff(j.requested_by) then raise exception 'Active PDF request owner required' using errcode='42501';end if;
 receipt:=jsonb_build_object('job_id',j.id,'pet_id',j.pet_id,'claim_id',p_claim_id,'fence',j.fence,'actor_id',j.requested_by,'lease_until',deadline,'source_hash',j.source_hash,'snapshot_hash',j.snapshot_hash,'renderer_sha',j.renderer_sha,'settings_sha',j.settings_sha);
 insert into public.diagnostic_pdf_attempts(id,job_id,fence,actor_id,renderer_sha,settings_sha,lease_until,receipt) values(p_claim_id,j.id,j.fence,j.requested_by,j.renderer_sha,j.settings_sha,deadline,receipt);return receipt;
end $$

create function public.diagnostic_pdf_live_claim(p_id uuid,p_claim_id uuid,p_fence integer,p_actor_id uuid) returns public.diagnostic_pdf_jobs language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;begin
 select * into j from public.diagnostic_pdf_jobs where id=p_id for update;
 if not found or j.claim_id is distinct from p_claim_id or j.fence is distinct from p_fence or j.requested_by is distinct from p_actor_id or j.status<>'claimed' or j.lease_until<=clock_timestamp() then raise exception 'PDF claim expired or was superseded' using errcode='PT409';end if;
 if not public.is_active_staff(p_actor_id) then raise exception 'Active PDF request owner required' using errcode='42501';end if;
 perform 1 from public.diagnostic_pdf_worker_policy where singleton and enabled and renderer_sha=j.renderer_sha and settings_sha=j.settings_sha for share;
 if not found then raise exception 'Bound PDF worker policy unavailable' using errcode='PT409';end if;
 -- Recheck time/actor after policy lock waits.
 if j.lease_until<=clock_timestamp() then raise exception 'PDF claim expired or was superseded' using errcode='PT409';end if;
 if not public.is_active_staff(p_actor_id) then raise exception 'Active PDF request owner required' using errcode='42501';end if;
 return j;
end $$

create function public.fail_diagnostic_pdf_job(p_id uuid,p_claim_id uuid,p_fence integer,p_actor_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;begin
 perform public.communication_require_service();if p_reason is null or length(trim(p_reason)) not between 1 and 2000 or trim(p_reason)<>p_reason then raise exception 'Explicit bounded PDF failure required' using errcode='23514';end if;
 j:=public.diagnostic_pdf_live_claim(p_id,p_claim_id,p_fence,p_actor_id);
 update public.diagnostic_pdf_jobs set status='failed',claim_id=null,lease_until=null,last_error=p_reason,updated_by=p_actor_id where id=p_id;return public.diagnostic_pdf_detail(p_id,j.pet_id);
end $$

create function public.capture_diagnostic_pdf_bytes(p_id uuid,p_claim_id uuid,p_fence integer,p_actor_id uuid,p_source_hash text,p_snapshot_hash text,p_renderer_sha text,p_settings_sha text,p_base64 text) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;c public.diagnostic_pdf_captures;b bytea;m jsonb;begin
 perform public.communication_require_service();
 if p_id is null or p_base64 is null or length(p_base64)>4194304 or p_base64!~'^[A-Za-z0-9+/]*={0,2}$' then raise exception 'Bounded canonical PDF capture bytes required' using errcode='23514';end if;
 b:=decode(p_base64,'base64');if replace(encode(b,'base64'),E'\n','')<>p_base64 or octet_length(b) not between 1 and 3145728 then raise exception 'Bounded canonical PDF capture bytes required' using errcode='23514';end if;
 if substring(b from 1 for 5)<>convert_to('%PDF-','UTF8') then raise exception 'PDF format marker required; capture remains unverified' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_id::text,493));select * into c from public.diagnostic_pdf_captures where job_id=p_id;
 if found then
  if row(c.claim_id,c.fence,c.actor_id,c.source_hash,c.snapshot_hash,c.renderer_sha,c.settings_sha,c.bytes) is distinct from row(p_claim_id,p_fence,p_actor_id,p_source_hash,p_snapshot_hash,p_renderer_sha,p_settings_sha,b) then raise exception 'Captured PDF identity and bytes are immutable' using errcode='23505';end if;return c.metadata;
 end if;
 j:=public.diagnostic_pdf_live_claim(p_id,p_claim_id,p_fence,p_actor_id);
 if row(j.source_hash,j.snapshot_hash,j.renderer_sha,j.settings_sha) is distinct from row(p_source_hash,p_snapshot_hash,p_renderer_sha,p_settings_sha) then raise exception 'PDF capture source or renderer binding differs' using errcode='23514';end if;
 m:=jsonb_build_object('job_id',j.id,'pet_id',j.pet_id,'claim_id',p_claim_id,'fence',p_fence,'actor_id',p_actor_id,'source_hash',j.source_hash,'snapshot_hash',j.snapshot_hash,'renderer_sha',j.renderer_sha,'settings_sha',j.settings_sha,'byte_length',octet_length(b),'sha256',encode(sha256(b),'hex'),'validation_status','not_validated','storage_status','not_uploaded','export_eligible',false);
 insert into public.diagnostic_pdf_captures(job_id,claim_id,fence,actor_id,source_hash,snapshot_hash,renderer_sha,settings_sha,bytes,sha256,byte_length,metadata) values(j.id,p_claim_id,p_fence,p_actor_id,j.source_hash,j.snapshot_hash,j.renderer_sha,j.settings_sha,b,m->>'sha256',octet_length(b),m);
 update public.diagnostic_pdf_jobs set status='captured_unverified',claim_id=null,lease_until=null,updated_by=p_actor_id where id=p_id;
 if j.lease_until<=clock_timestamp() then raise exception 'PDF claim expired or was superseded' using errcode='PT409';end if;
 if not public.is_active_staff(p_actor_id) then raise exception 'Active PDF request owner required' using errcode='42501';end if;return m;
end $$

create function public.read_diagnostic_pdf_capture(p_id uuid,p_pet_id uuid,p_actor_id uuid,p_source_hash text,p_snapshot_hash text) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;c public.diagnostic_pdf_captures;begin
 perform public.communication_require_service();select * into j from public.diagnostic_pdf_jobs where id=p_id and pet_id=p_pet_id;
 if not found or j.requested_by is distinct from p_actor_id or not public.is_active_staff(p_actor_id) then raise exception 'Active PDF request owner required' using errcode='42501';end if;
 if j.source_hash is distinct from p_source_hash or j.snapshot_hash is distinct from p_snapshot_hash then raise exception 'Exact PDF capture context required' using errcode='PT409';end if;
 select * into c from public.diagnostic_pdf_captures where job_id=p_id;if not found then return null;end if;
 return jsonb_build_object('metadata',c.metadata,'base64',replace(encode(c.bytes,'base64'),E'\n',''));
end $$

-- No policy seed, backfill, scheduler, Storage readiness, registration or release-family change.
do $$declare f record;begin
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'diagnostic_pdf_%' or p.proname in ('read_diagnostic_pdf_job','request_diagnostic_pdf_job','retry_diagnostic_pdf_job','claim_diagnostic_pdf_job','read_diagnostic_pdf_claim','fail_diagnostic_pdf_job','capture_diagnostic_pdf_bytes','read_diagnostic_pdf_capture')) loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname in ('read_diagnostic_pdf_job','request_diagnostic_pdf_job','retry_diagnostic_pdf_job') then execute format('grant execute on function %s to authenticated',f.signature);end if;
 if f.proname in ('claim_diagnostic_pdf_job','read_diagnostic_pdf_claim','fail_diagnostic_pdf_job','capture_diagnostic_pdf_bytes','read_diagnostic_pdf_capture') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

create function public.diagnostic_pdf_processing_guard() returns trigger language plpgsql set search_path=public as $$
begin
 if TG_OP<>'UPDATE' then raise exception 'PDF processing cannot be removed' using errcode='23514';end if;
 if NEW.job_id<>OLD.job_id or NEW.fence<OLD.fence or (OLD.state='stored' and NEW is distinct from OLD) then raise exception 'PDF processing history cannot regress' using errcode='23514';end if;
 if OLD.state='stored' then return OLD;end if;NEW.updated_at:=clock_timestamp();return NEW;
end $$

do $$declare t text;begin
 foreach t in array array['diagnostic_pdf_manifests','diagnostic_pdf_processing_attempts','diagnostic_pdf_validations','diagnostic_pdf_upload_intents','diagnostic_pdf_artifacts'] loop
 execute format('create trigger diagnostic_pdf_immutable before update or delete on public.%I for each row execute function public.diagnostic_immutable()',t);
 execute format('create trigger diagnostic_pdf_no_truncate before truncate on public.%I for each statement execute function public.diagnostic_immutable()',t);
 end loop;
 foreach t in array array['diagnostic_pdf_runtime_policy','diagnostic_pdf_manifests','diagnostic_pdf_processing','diagnostic_pdf_processing_attempts','diagnostic_pdf_validations','diagnostic_pdf_upload_intents','diagnostic_pdf_artifacts'] loop
 execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 end loop;
end $$

-- All mutators: job → profile → ordered role rows → worker/runtime policies → processing → object.
-- Operator policy writers must remain policy-only, or acquire actor eligibility first.
create function public.diagnostic_pdf_processing_owner(p_id uuid,p_actor uuid) returns public.diagnostic_pdf_jobs language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;rt public.diagnostic_pdf_runtime_policy;begin
 select * into j from public.diagnostic_pdf_jobs where id=p_id for update;
 if not found or j.requested_by is distinct from p_actor then raise exception 'Active PDF processing owner required' using errcode='42501';end if;
 perform 1 from public.profiles where id=p_actor for share;
 perform 1 from public.user_roles where user_id=p_actor order by id for share;
 if not public.is_active_staff(p_actor) then raise exception 'Active PDF processing owner required' using errcode='42501';end if;
 perform 1 from public.diagnostic_pdf_worker_policy where singleton and enabled and renderer_sha=j.renderer_sha and settings_sha=j.settings_sha for share;
 if not found then raise exception 'PDF processing policy unavailable' using errcode='PT409';end if;
 select * into rt from public.diagnostic_pdf_runtime_policy where singleton and enabled for share;
 if not found or substring(rt.image from 'sha256:([a-f0-9]{64})$') is distinct from j.renderer_sha or encode(sha256(convert_to((rt.provenance->'settings')::text,'UTF8')),'hex') is distinct from j.settings_sha then raise exception 'PDF runtime binding differs' using errcode='PT409';end if;
 if not public.is_active_staff(p_actor) then raise exception 'Active PDF processing owner required' using errcode='42501';end if;return j;
end $$

create function public.read_diagnostic_pdf_runtime_config() returns jsonb language plpgsql security definer set search_path=public as $$
declare rt public.diagnostic_pdf_runtime_policy;wp public.diagnostic_pdf_worker_policy;begin
 perform public.communication_require_service();select * into rt from public.diagnostic_pdf_runtime_policy where singleton and enabled;select * into wp from public.diagnostic_pdf_worker_policy where singleton and enabled;
 if rt.singleton is null or wp.singleton is null then return null;end if;
 return jsonb_build_object('image',rt.image,'provenance',rt.provenance,'renderer_sha',wp.renderer_sha,'settings_sha',wp.settings_sha);
end $$

create function public.read_diagnostic_pdf_render_source(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;m public.diagnostic_pdf_manifests;begin
 perform public.communication_require_service();j:=public.diagnostic_pdf_processing_owner(p_id,p_actor);j:=public.diagnostic_pdf_live_claim(p_id,p_claim,p_fence,p_actor);
 select * into m from public.diagnostic_pdf_manifests where job_id=p_id;if found then return m.source;end if;
 return public.diagnostic_pdf_render_source(j);
end $$

create function public.prepare_diagnostic_pdf_manifest(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid,p_source jsonb,p_input jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;m public.diagnostic_pdf_manifests;rt public.diagnostic_pdf_runtime_policy;actual text;fingerprint text;begin
 perform public.communication_require_service();j:=public.diagnostic_pdf_processing_owner(p_id,p_actor);j:=public.diagnostic_pdf_live_claim(p_id,p_claim,p_fence,p_actor);
 select * into m from public.diagnostic_pdf_manifests where job_id=p_id;
 if found then if row(m.source,m.input) is distinct from row(p_source,p_input) then raise exception 'PDF rendering manifest is immutable' using errcode='23505';end if;return to_jsonb(m);end if;
 if p_source is distinct from public.diagnostic_pdf_render_source(j) then raise exception 'PDF history census changed' using errcode='PT409';end if;
 if p_input is null or not p_input ?& array['version','job_id','source_hash','snapshot_hash','html_sha256','html_bytes','html','expected_texts'] or jsonb_typeof(p_input->'html') is distinct from 'string' or jsonb_typeof(p_input->'html_bytes') is distinct from 'number' then raise exception 'Exact bounded rendering input required' using errcode='23514';end if;
 actual:=encode(sha256(convert_to(p_input->>'html','UTF8')),'hex');
 if p_input is null or jsonb_typeof(p_input)<>'object' or (p_input-array['version','job_id','source_hash','snapshot_hash','html_sha256','html_bytes','html','expected_texts'])<>'{}' or (p_input->>'version') is distinct from '1' or (p_input->>'job_id') is distinct from j.id::text or (p_input->>'source_hash') is distinct from j.source_hash or (p_input->>'snapshot_hash') is distinct from j.snapshot_hash or (p_input->>'html_sha256') is distinct from actual or octet_length(p_input->>'html') not between 1 and 524288 or (p_input->>'html_bytes')::integer<>octet_length(p_input->>'html') or jsonb_typeof(p_input->'expected_texts') is distinct from 'array' or jsonb_array_length(p_input->'expected_texts') not between 1 and 500 or octet_length(p_input::text)>1100000 then raise exception 'Exact bounded rendering input required' using errcode='23514';end if;
 if exists(select 1 from jsonb_array_elements(p_input->'expected_texts') t where jsonb_typeof(t)<>'string' or length(t#>>'{}') not between 1 and 4000) then raise exception 'Exact bounded rendering input required' using errcode='23514';end if;
 select * into strict rt from public.diagnostic_pdf_runtime_policy where singleton;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('source',p_source,'input',p_input,'image',rt.image,'provenance',rt.provenance)::text,'UTF8')),'hex');
 insert into public.diagnostic_pdf_manifests(job_id,source,input,source_hash,html_sha256,manifest_sha256,provenance,image,actor_id) values(p_id,p_source,p_input,j.source_hash,actual,fingerprint,rt.provenance,rt.image,p_actor) returning * into m;
 if j.lease_until<=clock_timestamp() then raise exception 'PDF claim expired or was superseded' using errcode='PT409';end if;return to_jsonb(m);
end $$

create function public.capture_manifest_diagnostic_pdf(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid,p_base64 text) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;m public.diagnostic_pdf_manifests;begin
 perform public.communication_require_service();j:=public.diagnostic_pdf_processing_owner(p_id,p_actor);select * into m from public.diagnostic_pdf_manifests where job_id=p_id;
 if not found then raise exception 'Frozen rendering manifest required' using errcode='23514';end if;
 return public.capture_diagnostic_pdf_bytes(p_id,p_claim,p_fence,p_actor,j.source_hash,j.snapshot_hash,j.renderer_sha,j.settings_sha,p_base64);
end $$

create function public.claim_diagnostic_pdf_processing(p_id uuid,p_claim uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;p public.diagnostic_pdf_processing;a public.diagnostic_pdf_processing_attempts;m public.diagnostic_pdf_manifests;c public.diagnostic_pdf_captures;r jsonb;until_at timestamptz;begin
 perform public.communication_require_service();if p_claim is null then raise exception 'Stable processing claim required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_claim::text,496));
 select * into j from public.diagnostic_pdf_jobs where id=p_id;if not found then return null;end if;j:=public.diagnostic_pdf_processing_owner(p_id,j.requested_by);
 select * into m from public.diagnostic_pdf_manifests where job_id=p_id;select * into c from public.diagnostic_pdf_captures where job_id=p_id;
 if m.job_id is null or c.job_id is null then return null;end if;
 select * into p from public.diagnostic_pdf_processing where job_id=p_id for update;
 select * into a from public.diagnostic_pdf_processing_attempts where id=p_claim;
 if found then if a.job_id<>p_id then raise exception 'Processing claim identity conflicts' using errcode='23505';end if;
 if p.state<>'claimed' or p.claim_id is distinct from p_claim or p.fence<>a.fence or p.actor_id<>j.requested_by or p.lease_until<=clock_timestamp() then raise exception 'Processing claim expired or superseded' using errcode='PT409';end if;return a.receipt;end if;
 if p.state='stored' or (p.state='claimed' and p.lease_until>clock_timestamp() and p.actor_id=j.requested_by) then return null;end if;
 until_at:=clock_timestamp()+interval '90 seconds';
 insert into public.diagnostic_pdf_processing(job_id,state,fence,claim_id,actor_id,lease_until) values(p_id,'claimed',1,p_claim,j.requested_by,until_at)
 on conflict(job_id) do update set state='claimed',fence=diagnostic_pdf_processing.fence+1,claim_id=p_claim,actor_id=j.requested_by,lease_until=until_at,last_error='' returning * into p;
 r:=jsonb_build_object('job_id',p_id,'pet_id',j.pet_id,'claim_id',p_claim,'fence',p.fence,'actor_id',j.requested_by,'lease_until',until_at,'manifest',to_jsonb(m),'capture',c.metadata);
 insert into public.diagnostic_pdf_processing_attempts(id,job_id,fence,actor_id,lease_until,receipt) values(p_claim,p_id,p.fence,j.requested_by,until_at,r);return r;
end $$

create function public.diagnostic_pdf_live_processing(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid) returns public.diagnostic_pdf_processing language plpgsql security definer set search_path=public as $$
declare p public.diagnostic_pdf_processing;begin
 perform public.diagnostic_pdf_processing_owner(p_id,p_actor);select * into p from public.diagnostic_pdf_processing where job_id=p_id for update;
 if not found or p.state<>'claimed' or p.claim_id is distinct from p_claim or p.fence is distinct from p_fence or p.actor_id is distinct from p_actor or p.lease_until<=clock_timestamp() then raise exception 'Processing claim expired or superseded' using errcode='PT409';end if;return p;
end $$

create function public.validate_diagnostic_pdf_capture(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid,p_receipt jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.diagnostic_pdf_processing;c public.diagnostic_pdf_captures;m public.diagnostic_pdf_manifests;v public.diagnostic_pdf_validations;begin
 perform public.communication_require_service();p:=public.diagnostic_pdf_live_processing(p_id,p_claim,p_fence,p_actor);
 select * into strict c from public.diagnostic_pdf_captures where job_id=p_id;select * into strict m from public.diagnostic_pdf_manifests where job_id=p_id;
 if p_receipt is null or exists(select 1 from unnest(array['byte_length','page_count','object_count','stream_count','inflated_bytes']) k where jsonb_typeof(p_receipt->k) is distinct from 'number') then raise exception 'Exact admitted capture receipt required' using errcode='23514';end if;
 if p_receipt is null or jsonb_typeof(p_receipt)<>'object' or (p_receipt-array['sha256','byte_length','page_count','object_count','stream_count','inflated_bytes','admission','qpdf_clean'])<>'{}' or p_receipt->>'sha256' is distinct from c.sha256 or (p_receipt->>'byte_length')::integer is distinct from c.byte_length or p_receipt->>'admission' is distinct from 'chromium-classic-pdf1.4-v1' or p_receipt->'qpdf_clean' is distinct from 'true'::jsonb or (p_receipt->>'page_count')::integer not between 1 and 40 or (p_receipt->>'object_count')::integer not between 1 and 5000 or (p_receipt->>'stream_count')::integer not between 0 and 5000 or (p_receipt->>'inflated_bytes')::integer not between 0 and 16777216 then raise exception 'Exact admitted capture receipt required' using errcode='23514';end if;
 -- All fields must exist; SQL NULL cannot bypass bounds.
 if not p_receipt ?& array['sha256','byte_length','page_count','object_count','stream_count','inflated_bytes','admission','qpdf_clean'] then raise exception 'Exact admitted capture receipt required' using errcode='23514';end if;
 select * into v from public.diagnostic_pdf_validations where claim_id=p_claim;
 if found then if v.receipt is distinct from p_receipt then raise exception 'Validation receipt is immutable' using errcode='23505';end if;return to_jsonb(v);end if;
 insert into public.diagnostic_pdf_validations(claim_id,job_id,manifest_sha256,sha256,byte_length,receipt,actor_id) values(p_claim,p_id,m.manifest_sha256,c.sha256,c.byte_length,p_receipt,p_actor) returning * into v;
 if p.lease_until<=clock_timestamp() then raise exception 'Processing claim expired or superseded' using errcode='PT409';end if;return to_jsonb(v);
end $$

create function public.reserve_diagnostic_pdf_upload(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.diagnostic_pdf_processing;i public.diagnostic_pdf_upload_intents;v public.diagnostic_pdf_validations;c public.diagnostic_pdf_captures;j public.diagnostic_pdf_jobs;begin
 perform public.communication_require_service();p:=public.diagnostic_pdf_live_processing(p_id,p_claim,p_fence,p_actor);
 select * into v from public.diagnostic_pdf_validations where claim_id=p_claim and job_id=p_id;if not found then raise exception 'Current admitted-byte receipt required' using errcode='23514';end if;
 select * into strict c from public.diagnostic_pdf_captures where job_id=p_id;select * into strict j from public.diagnostic_pdf_jobs where id=p_id;
 select * into i from public.diagnostic_pdf_upload_intents where job_id=p_id;if found then return to_jsonb(i);end if;
 insert into public.diagnostic_pdf_upload_intents(job_id,bucket_id,object_path,sha256,byte_length,manifest_sha256,actor_id) values(p_id,'diagnostic-pdfs',j.pet_id::text||'/'||p_id::text||'/'||c.sha256||'.pdf',c.sha256,c.byte_length,v.manifest_sha256,p_actor) returning * into i;
 if p.lease_until<=clock_timestamp() then raise exception 'Processing claim expired or superseded' using errcode='PT409';end if;return to_jsonb(i);
end $$

create function public.read_diagnostic_pdf_upload_object(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare p public.diagnostic_pdf_processing;i public.diagnostic_pdf_upload_intents;o storage.objects;begin
 perform public.communication_require_service();p:=public.diagnostic_pdf_live_processing(p_id,p_claim,p_fence,p_actor);select * into strict i from public.diagnostic_pdf_upload_intents where job_id=p_id;
 select * into o from storage.objects where bucket_id=i.bucket_id and name=i.object_path for share;if not found then return null;end if;
 if o.version is null or length(o.version) not between 1 and 100 or o.metadata->>'mimetype' is distinct from 'application/pdf' or o.metadata->>'size' is distinct from i.byte_length::text then raise exception 'PDF Storage object differs' using errcode='23514';end if;
 if p.lease_until<=clock_timestamp() then raise exception 'Processing claim expired or superseded' using errcode='PT409';end if;return jsonb_build_object('id',o.id,'created_at',o.created_at,'updated_at',o.updated_at,'version',o.version,'bucket_id',o.bucket_id,'name',o.name,'mime_type','application/pdf','byte_length',i.byte_length);
end $$

create function public.register_diagnostic_pdf_artifact(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid,p_object uuid,p_object_created_at timestamptz,p_object_updated_at timestamptz,p_object_version text,p_readback_base64 text) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;p public.diagnostic_pdf_processing;i public.diagnostic_pdf_upload_intents;a public.diagnostic_pdf_artifacts;c public.diagnostic_pdf_captures;o storage.objects;r jsonb;b bytea;begin
 perform public.communication_require_service();j:=public.diagnostic_pdf_processing_owner(p_id,p_actor);
 select * into strict i from public.diagnostic_pdf_upload_intents where job_id=p_id;select * into strict c from public.diagnostic_pdf_captures where job_id=p_id;
 if p_readback_base64 is null or length(p_readback_base64)>4194304 or p_readback_base64!~'^[A-Za-z0-9+/]*={0,2}$' then raise exception 'Exact bounded Storage readback required' using errcode='23514';end if;
 b:=decode(p_readback_base64,'base64');if replace(encode(b,'base64'),E'\n','')<>p_readback_base64 or b is distinct from c.bytes then raise exception 'Actual Storage readback bytes differ' using errcode='23514';end if;
 select * into p from public.diagnostic_pdf_processing where job_id=p_id for update;select * into a from public.diagnostic_pdf_artifacts where job_id=p_id;
 if a.job_id is not null then
 if a.claim_id is distinct from p_claim or p.fence is distinct from p_fence or a.actor_id is distinct from p_actor or row(a.object_id,a.object_created_at,a.object_updated_at,a.object_version) is distinct from row(p_object,p_object_created_at,p_object_updated_at,p_object_version) then raise exception 'Artifact registration is immutable' using errcode='23505';end if;
 else p:=public.diagnostic_pdf_live_processing(p_id,p_claim,p_fence,p_actor);
 if not exists(select 1 from public.diagnostic_pdf_validations where claim_id=p_claim and job_id=p_id and sha256=c.sha256 and byte_length=c.byte_length and manifest_sha256=i.manifest_sha256) then raise exception 'Current admitted-byte receipt required' using errcode='23514';end if;end if;
 select * into o from storage.objects where id=p_object and bucket_id=i.bucket_id and name=i.object_path for share;
 if not found or o.created_at is distinct from p_object_created_at or o.updated_at is distinct from p_object_updated_at or o.version is distinct from p_object_version or p_object_version is null or length(p_object_version) not between 1 and 100 or o.metadata->>'size' is distinct from c.byte_length::text or o.metadata->>'mimetype' is distinct from 'application/pdf' then raise exception 'PDF Storage object differs' using errcode='23514';end if;
 if a.job_id is not null then return a.receipt;end if;
 if p.lease_until<=clock_timestamp() then raise exception 'Processing claim expired or superseded' using errcode='PT409';end if;
 r:=jsonb_build_object('job_id',p_id,'pet_id',j.pet_id,'claim_id',p_claim,'fence',p_fence,'capture_actor_id',c.actor_id,'processing_actor_id',p_actor,'manifest_sha256',i.manifest_sha256,'sha256',c.sha256,'byte_length',c.byte_length,'bucket_id',i.bucket_id,'object_path',i.object_path,'object_id',o.id,'object_created_at',o.created_at,'object_updated_at',o.updated_at,'object_version',o.version,'mime_type','application/pdf','status','stored_private','export_eligible',false);
 insert into public.diagnostic_pdf_artifacts(job_id,claim_id,object_id,object_created_at,object_updated_at,object_version,receipt,actor_id) values(p_id,p_claim,o.id,o.created_at,o.updated_at,o.version,r,p_actor);
 update public.diagnostic_pdf_processing set state='stored',claim_id=null,lease_until=null where job_id=p_id;return r;
end $$

create function public.fail_diagnostic_pdf_processing(p_id uuid,p_claim uuid,p_fence integer,p_actor uuid,p_code text) returns void language plpgsql security definer set search_path=public as $$
begin perform public.communication_require_service();perform public.diagnostic_pdf_live_processing(p_id,p_claim,p_fence,p_actor);
 if p_code is null or p_code not in('ADMISSION_FAILED','STORAGE_UNCERTAIN','OBJECT_CHANGED','CAPACITY_EXCEEDED') then raise exception 'Safe PDF failure code required' using errcode='23514';end if;
 update public.diagnostic_pdf_processing set state='failed',claim_id=null,lease_until=null,last_error=p_code where job_id=p_id;
end $$

create function public.read_diagnostic_pdf_artifact_state(p_id uuid,p_pet uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;p public.diagnostic_pdf_processing;a public.diagnostic_pdf_artifacts;present boolean;begin
 perform public.clinical_require_staff();select * into j from public.diagnostic_pdf_jobs where id=p_id and pet_id=p_pet;if not found then return null;end if;
 select * into p from public.diagnostic_pdf_processing where job_id=p_id;select * into a from public.diagnostic_pdf_artifacts where job_id=p_id;
 select exists(select 1 from storage.objects o join public.diagnostic_pdf_upload_intents i on i.job_id=p_id and o.bucket_id=i.bucket_id and o.name=i.object_path where o.id=a.object_id and o.created_at=a.object_created_at and o.updated_at=a.object_updated_at and o.version=a.object_version and o.metadata->>'mimetype'='application/pdf' and o.metadata->>'size'=i.byte_length::text) into present;
 return jsonb_build_object('job_id',p_id,'pet_id',p_pet,'has_registration',a.job_id is not null,'object_present',present,'state',coalesce(p.state,'not_processed'),'last_error',coalesce(p.last_error,''),'stored_private',a.job_id is not null and present,'export_eligible',false,'download_available',false);
end $$

create function public.read_diagnostic_pdf_processing_context(p_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;m public.diagnostic_pdf_manifests;c public.diagnostic_pdf_captures;a public.diagnostic_pdf_artifacts;present boolean;begin
 perform public.communication_require_service();select * into j from public.diagnostic_pdf_jobs where id=p_id;
 if not found then return null;end if;if not public.is_active_staff(j.requested_by) then raise exception 'Active PDF processing owner required' using errcode='42501';end if;
 select * into m from public.diagnostic_pdf_manifests where job_id=p_id;select * into c from public.diagnostic_pdf_captures where job_id=p_id;select * into a from public.diagnostic_pdf_artifacts where job_id=p_id;
 select exists(select 1 from storage.objects o join public.diagnostic_pdf_upload_intents i on i.job_id=p_id and o.bucket_id=i.bucket_id and o.name=i.object_path where o.id=a.object_id and o.created_at=a.object_created_at and o.updated_at=a.object_updated_at and o.version=a.object_version and o.metadata->>'mimetype'='application/pdf' and o.metadata->>'size'=i.byte_length::text) into present;
 return jsonb_build_object('object_present',present,'job',to_jsonb(j),'manifest',case when m.job_id is null then null else to_jsonb(m) end,'capture',c.metadata,'artifact',a.receipt);
end $$

do $$declare f record;begin
 for f in select oid::regprocedure as signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in('diagnostic_pdf_processing_guard','diagnostic_pdf_processing_owner','read_diagnostic_pdf_runtime_config','read_diagnostic_pdf_processing_context','diagnostic_pdf_render_source','read_diagnostic_pdf_render_source','prepare_diagnostic_pdf_manifest','capture_manifest_diagnostic_pdf','claim_diagnostic_pdf_processing','diagnostic_pdf_live_processing','validate_diagnostic_pdf_capture','reserve_diagnostic_pdf_upload','read_diagnostic_pdf_upload_object','register_diagnostic_pdf_artifact','fail_diagnostic_pdf_processing','read_diagnostic_pdf_artifact_state') loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
 if f.proname in('read_diagnostic_pdf_runtime_config','read_diagnostic_pdf_processing_context','read_diagnostic_pdf_render_source','prepare_diagnostic_pdf_manifest','capture_manifest_diagnostic_pdf','claim_diagnostic_pdf_processing','validate_diagnostic_pdf_capture','reserve_diagnostic_pdf_upload','read_diagnostic_pdf_upload_object','register_diagnostic_pdf_artifact','fail_diagnostic_pdf_processing') then execute format('grant execute on function %s to service_role',f.signature);end if;
 if f.proname='read_diagnostic_pdf_artifact_state' then execute format('grant execute on function %s to authenticated',f.signature);end if;
 end loop;
end $$

do $$declare t text;begin
 foreach t in array array['diagnostic_pdf_staff_disclosure_policy','diagnostic_pdf_download_authorities','diagnostic_pdf_download_responses'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 end loop;
 foreach t in array array['diagnostic_pdf_download_authorities','diagnostic_pdf_download_responses'] loop
  execute format('create trigger diagnostic_pdf_download_immutable before update or delete on public.%I for each row execute function public.diagnostic_immutable()',t);
  execute format('create trigger diagnostic_pdf_download_no_truncate before truncate on public.%I for each statement execute function public.diagnostic_immutable()',t);
 end loop;
end $$

-- Job → actual reader profile → sorted role rows → disclosure policy → object.
-- Authority rows and artifacts are immutable. Historical capture actors are never authorization.
create function public.diagnostic_pdf_download_current(p_job uuid,p_pet uuid,p_actor uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;a public.diagnostic_pdf_artifacts;i public.diagnostic_pdf_upload_intents;
 c public.diagnostic_pdf_captures;policy public.diagnostic_pdf_staff_disclosure_policy;o storage.objects;begin
 select * into j from public.diagnostic_pdf_jobs where id=p_job and pet_id=p_pet for share;
 if not found then raise exception 'Diagnostic PDF unavailable' using errcode='42501';end if;
 perform 1 from public.profiles where id=p_actor for share;
 perform 1 from public.user_roles where user_id=p_actor order by id for share;
 if not public.is_active_staff(p_actor) then raise exception 'Active staff reader required' using errcode='42501';end if;
 select * into policy from public.diagnostic_pdf_staff_disclosure_policy where singleton for share;
 if not found or not policy.enabled then raise exception 'Internal PDF disclosure disabled' using errcode='PT409';end if;
 select * into a from public.diagnostic_pdf_artifacts where job_id=p_job;
 select * into i from public.diagnostic_pdf_upload_intents where job_id=p_job;
 select * into c from public.diagnostic_pdf_captures where job_id=p_job;
 if a.job_id is null or i.job_id is null or c.job_id is null then raise exception 'Registered PDF required' using errcode='PT409';end if;
 select * into o from storage.objects where id=a.object_id for share;
 if not found or row(o.bucket_id,o.name,o.created_at,o.updated_at,o.version,o.metadata->>'mimetype',o.metadata->>'size')
  is distinct from row(i.bucket_id,i.object_path,a.object_created_at,a.object_updated_at,a.object_version,'application/pdf'::text,i.byte_length::text)
  or row(c.source_hash,c.snapshot_hash,c.sha256,c.byte_length) is distinct from row(j.source_hash,j.snapshot_hash,i.sha256,i.byte_length)
 then raise exception 'Registered PDF object unavailable' using errcode='PT409';end if;
 if not public.is_active_staff(p_actor) then raise exception 'Active staff reader required' using errcode='42501';end if;
 return jsonb_build_object('job_id',j.id,'pet_id',j.pet_id,'actor_id',p_actor,'source_hash',j.source_hash,
  'snapshot_hash',j.snapshot_hash,'manifest_sha256',i.manifest_sha256,'sha256',c.sha256,'byte_length',c.byte_length,
  'object_id',o.id,'object_created_at',o.created_at,'object_updated_at',o.updated_at,'object_version',o.version,
  'policy_hash',encode(sha256(convert_to(to_jsonb(policy)::text,'UTF8')),'hex'));
end $$

create function public.authorize_diagnostic_pdf_download(p_id uuid,p_job uuid,p_pet uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();binding jsonb;a public.diagnostic_pdf_download_authorities;begin
 if p_id is null then raise exception 'Download request identity required' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended('diagnostic-pdf-download:'||p_id::text,0));
 binding:=public.diagnostic_pdf_download_current(p_job,p_pet,actor);
 select * into a from public.diagnostic_pdf_download_authorities where id=p_id;
 if found then
  if row(a.job_id,a.pet_id,a.actor_id,a.binding) is distinct from row(p_job,p_pet,actor,binding) then raise exception 'Download request intent changed' using errcode='23505';end if;
  if a.expires_at<=clock_timestamp() then raise exception 'Download authorization expired' using errcode='PT409';end if;
 else
  insert into public.diagnostic_pdf_download_authorities(id,job_id,pet_id,actor_id,binding,expires_at)
   values(p_id,p_job,p_pet,actor,binding,clock_timestamp()+interval '30 seconds') returning * into a;
 end if;
 return jsonb_build_object('authority_id',a.id,'job_id',a.job_id,'pet_id',a.pet_id,'actor_id',a.actor_id,
  'sha256',binding->>'sha256','byte_length',(binding->>'byte_length')::integer,'expires_at',a.expires_at);
end $$

create function public.diagnostic_pdf_download_authority(p_id uuid,p_actor uuid) returns public.diagnostic_pdf_download_authorities
language plpgsql security definer set search_path=public as $$
declare a public.diagnostic_pdf_download_authorities;current_binding jsonb;begin
 select * into a from public.diagnostic_pdf_download_authorities where id=p_id and actor_id=p_actor;
 if not found then raise exception 'Diagnostic PDF authority unavailable' using errcode='42501';end if;
 current_binding:=public.diagnostic_pdf_download_current(a.job_id,a.pet_id,p_actor);
 if a.expires_at<=clock_timestamp() or a.binding is distinct from current_binding then raise exception 'Diagnostic PDF authority stale' using errcode='PT409';end if;
 return a;
end $$

create function public.read_diagnostic_pdf_download_context(p_id uuid,p_actor uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare a public.diagnostic_pdf_download_authorities;i public.diagnostic_pdf_upload_intents;begin
 perform public.communication_require_service();a:=public.diagnostic_pdf_download_authority(p_id,p_actor);
 select * into i from public.diagnostic_pdf_upload_intents where job_id=a.job_id;
 return jsonb_build_object('authority_id',a.id,'job_id',a.job_id,'pet_id',a.pet_id,'actor_id',a.actor_id,
  'sha256',i.sha256,'byte_length',i.byte_length,'expires_at',a.expires_at,'bucket',i.bucket_id,'object_path',i.object_path);
end $$

create function public.complete_diagnostic_pdf_download(p_id uuid,p_actor uuid,p_base64 text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare a public.diagnostic_pdf_download_authorities;c public.diagnostic_pdf_captures;b bytea;r jsonb;begin
 perform public.communication_require_service();a:=public.diagnostic_pdf_download_authority(p_id,p_actor);
 if p_base64 is null or length(p_base64)>4194304 or p_base64!~'^[A-Za-z0-9+/]*={0,2}$' then raise exception 'Bounded PDF bytes required' using errcode='23514';end if;
 b:=decode(p_base64,'base64');select * into c from public.diagnostic_pdf_captures where job_id=a.job_id;
 if replace(encode(b,'base64'),E'\n','')<>p_base64 or b is distinct from c.bytes or octet_length(b)<>c.byte_length then raise exception 'Registered PDF bytes differ' using errcode='23514';end if;
 if a.expires_at<=clock_timestamp() then raise exception 'Diagnostic PDF authority expired' using errcode='PT409';end if;
 r:=jsonb_build_object('authority_id',a.id,'job_id',a.job_id,'pet_id',a.pet_id,'actor_id',p_actor,'sha256',c.sha256,
  'byte_length',c.byte_length,'outcome','response_prepared');
 insert into public.diagnostic_pdf_download_responses(authority_id,actor_id,receipt) values(a.id,p_actor,r) on conflict do nothing;
 -- A concurrent replay can wait on the unique audit row past authority expiry.
 if a.expires_at<=clock_timestamp() then raise exception 'Diagnostic PDF authority expired after audit wait' using errcode='PT409';end if;
 return r;
end $$

-- Safe staff projection; object presence is metadata availability, verified again during download.
create function public.read_diagnostic_pdf_review(p_job uuid,p_pet uuid) returns jsonb
language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;v public.diagnostic_panel_versions;p public.diagnostic_pdf_processing;
 a public.diagnostic_pdf_artifacts;c public.diagnostic_pdf_captures;present boolean;disclosure_on boolean;begin
 perform public.clinical_require_staff();select * into j from public.diagnostic_pdf_jobs where id=p_job and pet_id=p_pet;
 if not found then return null;end if;
 select * into v from public.diagnostic_panel_versions where id=j.id;
 select * into p from public.diagnostic_pdf_processing where job_id=j.id;
 select * into a from public.diagnostic_pdf_artifacts where job_id=j.id;
 select * into c from public.diagnostic_pdf_captures where job_id=j.id;
 select exists(select 1 from storage.objects o join public.diagnostic_pdf_upload_intents i on i.job_id=j.id and o.bucket_id=i.bucket_id and o.name=i.object_path
  where o.id=a.object_id and o.created_at=a.object_created_at and o.updated_at=a.object_updated_at and o.version=a.object_version
  and o.metadata->>'mimetype'='application/pdf' and o.metadata->>'size'=i.byte_length::text) into present;
 select exists(select 1 from public.diagnostic_pdf_staff_disclosure_policy where singleton and enabled) into disclosure_on;
 return jsonb_build_object('job_id',j.id,'pet_id',j.pet_id,'version',v.number,'reviewed_at',v.reviewed_at,
  'historical',exists(select 1 from public.diagnostic_panel_versions later where later.panel_id=j.panel_id and later.number>v.number),
  'state',case when a.job_id is not null and not present then 'unavailable' when a.job_id is not null then 'stored_private'
   when p.state='failed' or j.status='failed' then 'failed' when p.state='claimed' or j.status='claimed' then 'preparing'
   when not exists(select 1 from public.diagnostic_pdf_worker_policy where singleton and enabled) then 'off' else 'waiting' end,
  'last_error',coalesce(p.last_error,''),'download_available',disclosure_on and a.job_id is not null and present,
  'sha256',case when a.job_id is not null then c.sha256 else null end,'byte_length',case when a.job_id is not null then c.byte_length else null end,
  'export_eligible',false);
end $$

do $$declare f record;begin
 for f in select oid::regprocedure as signature,proname from pg_proc where pronamespace='public'::regnamespace and proname in
 ('diagnostic_pdf_download_current','authorize_diagnostic_pdf_download','diagnostic_pdf_download_authority','read_diagnostic_pdf_download_context','complete_diagnostic_pdf_download','read_diagnostic_pdf_review') loop
  execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);
  if f.proname in('authorize_diagnostic_pdf_download','read_diagnostic_pdf_review') then execute format('grant execute on function %s to authenticated',f.signature);end if;
  if f.proname in('read_diagnostic_pdf_download_context','complete_diagnostic_pdf_download') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$

-- 3A2a: staff metadata review and private binding only. No schema14 export/recipient path.
-- Every embedded diagnostic root is locked before callers may lock other clinical sources.
create function public.diagnostic_pdf_release_binding(p_job uuid,p_pet uuid,p_mode text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare j public.diagnostic_pdf_jobs;v public.diagnostic_panel_versions;m public.diagnostic_pdf_manifests;
 a public.diagnostic_pdf_artifacts;i public.diagnostic_pdf_upload_intents;c public.diagnostic_pdf_captures;
 val public.diagnostic_pdf_validations;o storage.objects;row_source jsonb;embedded jsonb:='[]';root uuid;head uuid;
begin
 if p_mode is null or p_mode not in ('current','historical') then raise exception 'Explicit diagnostic version scope required' using errcode='23514';end if;
 perform 1 from public.pets where id=p_pet for share;if not found then raise exception 'Diagnostic patient unavailable' using errcode='42501';end if;
 select * into j from public.diagnostic_pdf_jobs where id=p_job and pet_id=p_pet;
 if not found then raise exception 'Diagnostic source unavailable' using errcode='42501';end if;
 select * into m from public.diagnostic_pdf_manifests where job_id=p_job;
 if not found then raise exception 'Verified diagnostic PDF required' using errcode='PT409';end if;
 if jsonb_typeof(m.source->'panels') is distinct from 'array' or jsonb_array_length(m.source->'panels') not between 1 and 200
  or not m.source->'panels' @> jsonb_build_array(j.snapshot->'diagnostic')
  or m.source#>'{job,snapshot}' is distinct from j.snapshot
 then raise exception 'Diagnostic manifest census differs' using errcode='23514';end if;
 -- Immutable manifest IDs can be discovered before acquiring mutable source locks.
 for root in select distinct (x->>'panel_id')::uuid from jsonb_array_elements(m.source->'panels') x order by 1 loop
  perform 1 from public.diagnostic_panels where id=root and pet_id=p_pet for share;
  if not found then raise exception 'Embedded diagnostic root unavailable' using errcode='23514';end if;
 end loop;
 select * into j from public.diagnostic_pdf_jobs where id=p_job and pet_id=p_pet for share;
 select * into strict v from public.diagnostic_panel_versions where id=p_job and panel_id=j.panel_id and pet_id=p_pet;
 select current_finalized_id into head from public.diagnostic_panels where id=j.panel_id;
 if p_mode='current' and head is distinct from p_job then raise exception 'Current diagnostic version changed; select historical explicitly' using errcode='PT409';end if;
 for row_source in select value from jsonb_array_elements(m.source->'panels') loop
  if not exists(select 1 from public.diagnostic_panel_versions ev where ev.id=(row_source->>'id')::uuid and ev.pet_id=p_pet and to_jsonb(ev)=row_source) then
   raise exception 'Embedded reviewed diagnostic version differs' using errcode='23514';end if;
  embedded:=embedded||jsonb_build_array(jsonb_build_object('id',row_source->'id','panel_id',row_source->'panel_id',
   'version',row_source->'number','label',row_source#>'{snapshot,panel_name}','reviewed_at',row_source->'reviewed_at','source_hash',row_source->'source_hash'));
 end loop;
 if (select count(distinct x->>'panel_id') from jsonb_array_elements(embedded) x)<>jsonb_array_length(embedded)
  or (m.source->>'total_panels')::integer<jsonb_array_length(embedded) or m.source->>'total_panels' is null
 then raise exception 'Diagnostic manifest census invalid' using errcode='23514';end if;
 select * into a from public.diagnostic_pdf_artifacts where job_id=p_job;
 select * into i from public.diagnostic_pdf_upload_intents where job_id=p_job;
 select * into c from public.diagnostic_pdf_captures where job_id=p_job;
 select * into val from public.diagnostic_pdf_validations where claim_id=a.claim_id and job_id=p_job;
 if a.job_id is null or i.job_id is null or c.job_id is null or val.job_id is null
  or row(j.source_hash,j.snapshot_hash,m.manifest_sha256,c.sha256,c.byte_length)
   is distinct from row(c.source_hash,c.snapshot_hash,i.manifest_sha256,i.sha256,i.byte_length)
  or row(val.manifest_sha256,val.sha256,val.byte_length) is distinct from row(m.manifest_sha256,c.sha256,c.byte_length)
  or v.source_hash is distinct from j.source_hash or octet_length(c.bytes)<>c.byte_length or encode(sha256(c.bytes),'hex')<>c.sha256
 then raise exception 'Admitted diagnostic artifact binding differs' using errcode='PT409';end if;
 select * into o from storage.objects where id=a.object_id for share;
 if not found or row(o.bucket_id,o.name,o.created_at,o.updated_at,o.version,o.metadata->>'mimetype',o.metadata->>'size')
  is distinct from row(i.bucket_id,i.object_path,a.object_created_at,a.object_updated_at,a.object_version,'application/pdf'::text,i.byte_length::text)
 then raise exception 'Registered diagnostic PDF object unavailable' using errcode='PT409';end if;
 return jsonb_build_object('binding_version',1,'job_id',j.id,'pet_id',j.pet_id,'panel_id',j.panel_id,'mode',p_mode,
  'version',v.number,'label',v.snapshot->>'panel_name','reviewed_at',v.reviewed_at,'source_hash',j.source_hash,'snapshot_hash',j.snapshot_hash,
  'manifest_sha256',m.manifest_sha256,'sha256',c.sha256,'byte_length',c.byte_length,
  'embedded_versions',embedded,'total_panels',(m.source->>'total_panels')::integer,
  'bucket',i.bucket_id,'object_path',i.object_path,'object_id',o.id,'object_created_at',o.created_at,'object_updated_at',o.updated_at,'object_version',o.version);
end $$

-- Future schema14 capture must compare actual private readback after recipient-current checks.
-- This helper grants no recipient authority and is not callable through the Data API.
create function public.verify_diagnostic_pdf_release_bytes(p_binding jsonb,p_bytes bytea) returns void
language plpgsql security definer set search_path=public as $$
declare current_binding jsonb;c public.diagnostic_pdf_captures;begin
 if p_binding is null or jsonb_typeof(p_binding)<>'object' or p_bytes is null or octet_length(p_bytes) not between 1 and 3145728 then
  raise exception 'Exact bounded diagnostic release bytes required' using errcode='23514';end if;
 current_binding:=public.diagnostic_pdf_release_binding((p_binding->>'job_id')::uuid,(p_binding->>'pet_id')::uuid,p_binding->>'mode');
 if current_binding is distinct from p_binding then raise exception 'Diagnostic release binding changed' using errcode='PT409';end if;
 select * into strict c from public.diagnostic_pdf_captures where job_id=(p_binding->>'job_id')::uuid;
 if p_bytes is distinct from c.bytes then raise exception 'Diagnostic release readback differs from admitted capture' using errcode='23514';end if;
end $$

create function public.read_diagnostic_pdf_release_scope(p_job uuid,p_pet uuid,p_mode text) returns jsonb
language plpgsql security definer set search_path=public as $$
declare actor uuid:=public.clinical_require_staff();binding jsonb;begin
 -- Current reader, never the historical processing owner or internal download authority.
 binding:=public.diagnostic_pdf_release_binding(p_job,p_pet,p_mode);
 perform 1 from public.profiles where id=actor for share;
 perform 1 from public.user_roles where user_id=actor order by id for share;
 perform public.clinical_require_staff();
 return (binding-array['bucket','object_path','object_id','object_created_at','object_updated_at','object_version'])
  ||jsonb_build_object('export_available',false,'scope_expansion_required',jsonb_array_length(binding->'embedded_versions')>1);
end $$

-- Freeze inherited discovery mappings; new families must never fall through to lesions.
do $$declare d text;needle text:='foreach k in array public.record_request_families() loop';begin
 select pg_get_functiondef('public.record_request_inventory_before_diagnostics(uuid)'::regprocedure) into d;
 if (length(d)-length(replace(d,needle,'')))/length(needle)<>2 then raise exception 'Expected both inherited inventory loops';end if;
 execute replace(d,needle,needle||' if k in (''diagnostic_pdf_ids'',''diagnostic_pdf_historical_ids'') then continue;end if;');
end $$

create function public.diagnostic_pdf_release_record(p_job uuid,p_pet uuid,p_mode text) returns jsonb language plpgsql security definer set search_path=public as $$
declare b jsonb;heads jsonb;begin
 b:=public.diagnostic_pdf_release_binding(p_job,p_pet,p_mode);
 -- Correction context is separate from immutable artifact identity. Every embedded root
 -- is already SHARE locked. A later correction requires fresh disclosure review in either mode.
 select jsonb_agg(jsonb_build_object('panel_id',p.id,'head_id',p.current_finalized_id,'version',p.version) order by p.id) into heads
 from public.diagnostic_panels p where p.id in(select (x->>'panel_id')::uuid from jsonb_array_elements(b->'embedded_versions') x);
 return jsonb_build_object('binding',b,'binding_hash',public.native_fulfillment_hash(b),'review_context',heads);
end $$

create function public.diagnostic_pdf_release_document(p_record jsonb) returns jsonb language plpgsql immutable set search_path=public as $$
declare b jsonb:=p_record->'binding';begin
 if b->>'bucket' is distinct from 'diagnostic-pdfs' or p_record->>'binding_hash' is distinct from public.native_fulfillment_hash(b)
  or b->>'mode' not in('current','historical') or (b->>'byte_length')::integer not between 1 and 3145728 then
  raise exception 'Exact diagnostic package binding required' using errcode='23514';end if;
 return jsonb_build_object('id',b->'job_id','version',b->'version','file_name','diagnostic-'||(b->>'job_id')||'.pdf',
  'file_path',b->'object_path','bucket','diagnostic-pdfs','mime_type','application/pdf','file_size',b->'byte_length','content_sha256',b->'sha256',
  'document_date',((b->>'reviewed_at')::timestamptz at time zone 'America/Denver')::date,'category','diagnostic_pdf',
  'diagnostic_pdf_ref',jsonb_build_object('job_id',b->'job_id','mode',b->'mode','binding_hash',p_record->'binding_hash'));
end $$

create function public.release_preview_v14_internal(p_pet_id uuid,p_client_id uuid,p_channel text,p_recipient text,p_selection jsonb) returns jsonb
language plpgsql security definer set search_path=public as $$
declare k text;ids jsonb;selection jsonb:='{}';older jsonb;old_count integer:=0;total integer:=0;aid uuid;root uuid;job uuid;r jsonb;s jsonb;item jsonb;pdfs jsonb:='[]';docs jsonb;mode text;
begin
 if auth.role() is distinct from 'service_role' then perform public.clinical_require_staff();end if;
 if p_selection is null or jsonb_typeof(p_selection) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_selection) f where f<>all(public.record_request_families())) then raise exception 'Known explicit release sources required' using errcode='23514';end if;
 foreach k in array array['diagnostic_pdf_ids','diagnostic_pdf_historical_ids'] loop
  ids:=coalesce(p_selection->k,'[]');
  if jsonb_typeof(ids) is distinct from 'array' or jsonb_array_length(ids)>24 or exists(select 1 from jsonb_array_elements(ids) x where jsonb_typeof(x)<>'string') or (select count(*)<>count(distinct x::uuid) from jsonb_array_elements_text(ids) x) then raise exception 'Select at most24 distinct diagnostic UUIDs per family' using errcode='23514';end if;
  select coalesce(jsonb_agg(x::uuid order by x::uuid),'[]') into ids from jsonb_array_elements_text(ids) x;
  selection:=selection||jsonb_build_object(k,ids);total:=total+jsonb_array_length(ids);
 end loop;
 if exists(select 1 from jsonb_array_elements_text(selection->'diagnostic_pdf_ids') a join jsonb_array_elements_text(selection->'diagnostic_pdf_historical_ids') b on a.value=b.value) then raise exception 'A diagnostic PDF cannot be selected in both modes' using errcode='23514';end if;
 older:=p_selection-array['diagnostic_pdf_ids','diagnostic_pdf_historical_ids'];
 if total=0 then return public.release_preview_v13_internal(p_pet_id,p_client_id,p_channel,p_recipient,older);end if;
 if total+jsonb_array_length(coalesce(older->'document_ids','[]'))+jsonb_array_length(coalesce(older->'api_attachment_ids','[]'))>24 then raise exception 'Distinct originals within24-file limit required' using errcode='23514';end if;
 -- Match inherited native and per-patient serialization before diagnostic/source locks.
 for aid in select x::uuid from jsonb_array_elements_text(coalesce(older->'native_prescription_ids','[]')) x union select d.authorization_id from public.native_dispenses d where d.id in(select x::uuid from jsonb_array_elements_text(coalesce(older->'native_dispense_ids','[]')) x) order by 1 loop
  perform pg_advisory_xact_lock(hashtextextended('native-prescription-authorization:'||aid::text,0));
 end loop;
 perform pg_advisory_xact_lock(hashtextextended(p_pet_id::text,4700));
 -- Imported source writers lock mapping before patient; acquire their common parents first.
 perform 1 from public.ezyvet_record_links where pet_id=p_pet_id order by id for share;
 perform 1 from public.pets where id=p_pet_id and client_id=p_client_id for share;if not found then raise exception 'Patient household differs' using errcode='42501';end if;
 -- Discover immutable manifests, then lock the union (not one report at a time).
 for root in select distinct (x->>'panel_id')::uuid from public.diagnostic_pdf_manifests m cross join lateral jsonb_array_elements(m.source->'panels') x where m.job_id in(select x::uuid from jsonb_array_elements_text(selection->'diagnostic_pdf_ids') x union select x::uuid from jsonb_array_elements_text(selection->'diagnostic_pdf_historical_ids') x) order by 1 loop
  perform 1 from public.diagnostic_panels where id=root and pet_id=p_pet_id for share;if not found then raise exception 'Embedded diagnostic root unavailable' using errcode='23514';end if;
 end loop;
 for k in select jsonb_object_keys(older) loop if jsonb_typeof(older->k) is distinct from 'array' then raise exception 'Source selections must be arrays' using errcode='23514';end if;old_count:=old_count+jsonb_array_length(older->k);end loop;
 if old_count=0 then
  r:=public.preview_record_release_v1(p_pet_id,p_client_id,p_channel,p_recipient,'{}');s:=r->'snapshot';
  foreach k in array array['dental_charts','qol_records','anesthesia_records','lesions','problems','weights','treatments','patient_summaries','lab_reports','external_records','imported_histories','problem_source_extractions','imported_vaccinations','imported_prescriptions','api_attachments','native_prescriptions','native_dispenses'] loop s:=s||jsonb_build_object(k,'[]'::jsonb);end loop;
  foreach k in array public.record_request_families() loop if k not in('diagnostic_pdf_ids','diagnostic_pdf_historical_ids') then selection:=selection||jsonb_build_object(k,'[]'::jsonb);end if;end loop;
 else r:=public.release_preview_v13_internal(p_pet_id,p_client_id,p_channel,p_recipient,older);s:=r->'snapshot';selection:=coalesce(s->'selection','{}')||selection;end if;
 docs:=s->'attachments';
 foreach k in array array['diagnostic_pdf_ids','diagnostic_pdf_historical_ids'] loop
  mode:=case k when 'diagnostic_pdf_ids' then 'current' else 'historical' end;
  for job in select x::uuid from jsonb_array_elements_text(selection->k) x order by 1 loop
   item:=public.diagnostic_pdf_release_record(job,p_pet_id,mode);pdfs:=pdfs||jsonb_build_array(item);docs:=docs||jsonb_build_array(public.diagnostic_pdf_release_document(item));
  end loop;
 end loop;
 if (select count(*)<>count(distinct x->>'id') from jsonb_array_elements(docs) x) then raise exception 'Distinct selected originals required' using errcode='23514';end if;
 s:=s||jsonb_build_object('schema_version',14,'selection',selection,'diagnostic_pdfs',pdfs,'attachments',docs);
 if octet_length(s::text)>1048576 then raise exception 'Release exceeds maximum reviewed snapshot size' using errcode='23514';end if;
 if auth.role() is distinct from 'service_role' then perform public.clinical_require_staff();end if;
 return jsonb_build_object('snapshot',s,'source_hash',public.native_fulfillment_hash(s));
exception when invalid_text_representation then raise exception 'Source IDs must be valid UUIDs' using errcode='23514';end $$

create or replace function public.record_request_inventory(p_pet_id uuid) returns jsonb language plpgsql volatile security definer set search_path=public as $$
declare r jsonb;v public.diagnostic_panel_versions;p public.diagnostic_panels;b jsonb;family text;mode text;count_rows integer:=0;nodes jsonb;excluded jsonb;
begin
 perform public.clinical_require_staff();
 if (select count(*) from public.diagnostic_panels where pet_id=p_pet_id)>10000 or (select count(*) from public.diagnostic_panel_versions where pet_id=p_pet_id)>10000 then raise exception 'Diagnostic census exceeds complete-capture capacity' using errcode='23514';end if;
 r:=public.record_request_inventory_before_diagnostics(p_pet_id);nodes:=r->'nodes';excluded:=r->'exclusions';
 -- Root union precedes artifact locks; inventory includes precise unavailable/current exclusions.
 perform 1 from public.diagnostic_panels where pet_id=p_pet_id order by id for share;
 for v in select * from public.diagnostic_panel_versions where pet_id=p_pet_id order by panel_id,number loop
  count_rows:=count_rows+1;if count_rows>10000 then raise exception 'Diagnostic census exceeds complete-capture capacity' using errcode='23514';end if;
  select * into strict p from public.diagnostic_panels where id=v.panel_id;
  mode:=case when p.current_finalized_id=v.id then 'current' else 'historical' end;
  family:=case mode when 'current' then 'diagnostic_pdf_ids' else 'diagnostic_pdf_historical_ids' end;
  begin
   b:=public.diagnostic_pdf_release_record(v.id,p_pet_id,mode);
   nodes:=nodes||jsonb_build_object(family||':'||v.id,jsonb_build_object('family',family,'id',v.id,'version',v.number,'label',v.snapshot->>'panel_name','recorded_at',v.reviewed_at,'diagnostic_category',v.snapshot->>'category','requires','[]'::jsonb,'diagnostic_pdf',b,'scope_expansion',jsonb_array_length(b#>'{binding,embedded_versions}')>1));
  exception when sqlstate 'PT409' or sqlstate '42501' then
   excluded:=excluded||jsonb_build_array(jsonb_build_object('family',family,'id',v.id,'label',v.snapshot->>'panel_name','reason',case mode when 'current' then 'Current reviewed PDF is unregistered, unavailable or replaced; historical PDFs are never substituted' else 'Historical PDF is unregistered, unavailable or replaced' end));
  end;
 end loop;
 for p in select * from public.diagnostic_panels where pet_id=p_pet_id and current_finalized_id is null order by id loop
  excluded:=excluded||jsonb_build_array(jsonb_build_object('family','diagnostic_pdf_ids','id',p.id,'label',p.draft->>'panel_name','reason','Diagnostic panel is not finalized; no current reviewed PDF exists'));
 end loop;
 if (select count(*) from jsonb_each(nodes))>10000 then raise exception 'Chart exceeds complete-capture capacity; no partial manifest was created' using errcode='23514';end if;
 perform public.clinical_require_staff();return r||jsonb_build_object('nodes',nodes,'exclusions',excluded);
end $$

